# Short TTL caches for hot auth/RBAC paths (OCI WAN: many round-trips per HTML page).
_AUTH_CACHE_LOCK = threading.Lock()
_AUTH_TTL_CACHE: Dict[str, Tuple[float, Any]] = {}
_AUTH_TTL_DEFAULT_SEC = 60.0


def _auth_ttl_get(key: str) -> Tuple[bool, Any]:
    now = time.time()
    with _AUTH_CACHE_LOCK:
        ent = _AUTH_TTL_CACHE.get(key)
        if not ent:
            return (False, None)
        exp, val = ent
        if now >= exp:
            del _AUTH_TTL_CACHE[key]
            return (False, None)
        return (True, val)


def _auth_ttl_set(key: str, value: Any, ttl_sec: Optional[float] = None) -> None:
    ttl = _AUTH_TTL_DEFAULT_SEC if ttl_sec is None else float(ttl_sec)
    with _AUTH_CACHE_LOCK:
        _AUTH_TTL_CACHE[key] = (time.time() + max(1.0, ttl), value)


def _req_cache_get(bucket: str, key: str) -> Tuple[bool, Any]:
    try:
        from nexa_http import g, has_request_context
        if not has_request_context() or g is None:
            return (False, None)
        store = g.get('nexa_req_cache')
        if not isinstance(store, dict):
            return (False, None)
        b = store.get(bucket)
        if not isinstance(b, dict) or key not in b:
            return (False, None)
        return (True, b[key])
    except Exception:
        return (False, None)


def _req_cache_set(bucket: str, key: str, value: Any) -> None:
    try:
        from nexa_http import g, has_request_context
        if not has_request_context() or g is None:
            return
        store = g.get('nexa_req_cache')
        if not isinstance(store, dict):
            store = {}
            g.nexa_req_cache = store
        b = store.get(bucket)
        if not isinstance(b, dict):
            b = {}
            store[bucket] = b
        b[key] = value
    except Exception:
        pass

def ensure_location_master_table(_db_key_ignored: Any=None) -> Tuple[bool, str, bool]:
    """
    Create LOCATIONMASTER (or whatever ``LOCATIONS_TABLE`` names) if it does not exist.
    DDL matches typical RGC/RF ``LocationmasterCols`` expectations (19 columns).

    Returns ``(ok, message, created_now)``: ``created_now`` is True only when DDL ran successfully.
    """
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    key = tbl.upper()
    try:
        if _table_exists(tbl):
            return (True, '', False)
    except Exception as e:
        return (False, str(e), False)
    ddl_body = "\n    (\n      LOCATIONCODE        NUMBER(10) NOT NULL CONSTRAINT {pk_name} PRIMARY KEY,\n      LOCATIONNAME        VARCHAR2(100 BYTE),\n      ADDRESS               VARCHAR2(200 BYTE),\n      TELEPHONE             VARCHAR2(30 BYTE),\n      FAX                   VARCHAR2(30 BYTE),\n      EMAILID               VARCHAR2(120 BYTE),\n      MANAGER               VARCHAR2(80 BYTE),\n      RESETNO               NUMBER(10),\n      BASELOCATIONFLAG      CHAR(1 BYTE),\n      MINUSBILLING          VARCHAR2(1 BYTE),\n      ITEMDESCRIPTION       VARCHAR2(400 BYTE),\n      RETURNDETAILS        VARCHAR2(500 BYTE),\n      BASEPRICE             NUMBER(18,4),\n      COUPONS               NUMBER(18,4),\n      COUPONAMOUNT          NUMBER(18,4),\n      LINECOLOR             VARCHAR2(40 BYTE),\n      PRODUCTION            CHAR(1 BYTE),\n      CASHLIMIT             NUMBER(18,4),\n      DBCODE                VARCHAR2(30 BYTE),\n      BATCH_TRACKING        VARCHAR2(1 BYTE)   DEFAULT 'N' NOT NULL,\n      BIN_TRACKING          VARCHAR2(1 BYTE)   DEFAULT 'N' NOT NULL,\n      WAREHOUSE_ENABLE      VARCHAR2(1 BYTE)   DEFAULT 'N' NOT NULL\n    )\n    ".strip()
    suf = ''.join((ch for ch in tbl if ch.isalnum()))[:20] or 'LOC'
    pk_name = f'PK_{suf}_LM'[:29]
    ddl_body_fmt = ddl_body.format(pk_name=pk_name)
    ddl_with_ts = 'CREATE TABLE {t} '.format(t=tbl) + ddl_body_fmt + ' TABLESPACE USERS'
    ddl_plain = 'CREATE TABLE {t} '.format(t=tbl) + ddl_body_fmt
    last_err = ''
    for ddl in (ddl_with_ts, ddl_plain):
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute(ddl)
                conn.commit()
            break
        except Exception as e:
            last_err = str(e)
    else:
        return (False, last_err or 'CREATE TABLE failed.', False)
    try:
        _TABLE_EXISTS_CACHE.pop(key, None)
        _TABLE_COLUMNS_CACHE.pop(key, None)
    except Exception:
        pass
    return (True, '', True)

