_ACTIVE_DB_CONTEXT = threading.local()

def set_active_db_key(_key: Optional[str]) -> None:
    """Set tenant DB key for background/non-request work in multi-DB mode."""
    try:
        key = (_key or '').strip() if isinstance(_key, str) else None
        _ACTIVE_DB_CONTEXT.tenant_id = key if key and key.lower() != 'none' else None
    except Exception:
        pass


def get_active_db_key() -> Optional[str]:
    """Current thread-local tenant DB key set by ``set_active_db_key`` (background workers)."""
    try:
        v = getattr(_ACTIVE_DB_CONTEXT, 'tenant_id', None)
        if isinstance(v, str):
            s = v.strip()
            return s if s and s.lower() != 'none' else None
        return None
    except Exception:
        return None

