def _get_auth_connection() -> cx_Oracle.Connection:
    """Get connection to auth (login) database. Used for login_users, roles, tenant_databases."""
    config = get_auth_db_config()
    if not config.get('user') or not config.get('dsn'):
        au = (os.getenv('AUTH_DB_USERNAME') or '').strip()
        ad = (os.getenv('AUTH_DB_DSN') or '').strip()
        missing = []
        if not au:
            missing.append('AUTH_DB_USERNAME')
        if not ad:
            missing.append('AUTH_DB_DSN')
        raise ValueError(f"Auth database not configured. Multi-DB requires AUTH_DB_USERNAME, AUTH_DB_PASSWORD, and AUTH_DB_DSN in .env (missing or empty: {', '.join(missing)}). Restart the app after saving. Or use /database-setup.")
    return cx_oracle_connect(user=config['user'], password=config['password'], dsn=config['dsn'])
_TENANT_CONFIG_CACHE_VER = 2
_tenant_config_cache: Dict[str, Any] = {}

def get_tenant_config(tenant_id: str) -> Dict[str, Any]:
    """Get connection config for a tenant from tenant_databases (auth DB). DSN built from ip, port, service_name."""
    _raw = (tenant_id or '').strip()
    if not _raw or _raw.lower() == 'none':
        raise ValueError('tenant_id is required.')
    tid = _raw
    if tid in _tenant_config_cache:
        ent = _tenant_config_cache[tid]
        if isinstance(ent, tuple) and len(ent) == 2 and ent[0] == _TENANT_CONFIG_CACHE_VER:
            return ent[1].copy()
        del _tenant_config_cache[tid]
    with _get_auth_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT ip, port, service_name, username, password FROM tenant_databases WHERE tenant_id = :tid AND NVL(active_flag, 'Y') = 'Y'", {'tid': tid})
            row = cur.fetchone()
            cols = [c[0].lower() for c in cur.description] if cur.description else []
    if not row:
        raise ValueError(f"Tenant '{tid}' not found or inactive.")
    r = dict(zip(cols, row)) if cols else {}
    ip = (r.get('ip') or '').strip()
    port = (r.get('port') or '').strip()
    svc = (r.get('service_name') or '').strip()
    dsn = f'{ip}:{port}/{svc}'
    default_cfg = get_db_config()
    user = (r.get('username') or '').strip() or default_cfg.get('user')
    tenant_pw = r.get('password')
    if tenant_pw is not None:
        tenant_pw = str(tenant_pw).strip()
    else:
        tenant_pw = ''
    if (r.get('username') or '').strip():
        password = tenant_pw if tenant_pw else (default_cfg.get('password') or '')
    else:
        password = default_cfg.get('password') or ''
    if not user:
        raise ValueError(f"Tenant '{tid}' has no username and default DB_USERNAME not set.")
    cfg = {'user': user, 'password': password or '', 'dsn': dsn}
    _tenant_config_cache[tid] = (_TENANT_CONFIG_CACHE_VER, cfg.copy())
    return cfg

def _get_tenant_connection(tenant_id: str) -> cx_Oracle.Connection:
    """Get connection to a tenant database using tenant_databases config."""
    config = get_tenant_config(tenant_id)
    return cx_oracle_connect(user=config['user'], password=config['password'], dsn=config['dsn'])

def _get_central_link_connection() -> cx_Oracle.Connection:
    """Connection to central DB where DB links (emdadco_link, rfss_link, rfil_link) are defined. Used for Stock Report Central when CENTRAL_REPORT_* is set."""
    cfg = get_central_report_config()
    if not cfg.get('user') or not cfg.get('dsn'):
        raise ValueError('Central report DB not configured. Set CENTRAL_REPORT_USER, CENTRAL_REPORT_PASSWORD, CENTRAL_REPORT_DSN (or AUTH_DB_*) and CENTRAL_REPORT_LINKS.')
    return cx_oracle_connect(user=cfg['user'], password=cfg.get('password') or '', dsn=cfg['dsn'])

def _resolve_db_connect_config() -> Dict[str, str]:
    """Resolve user/password/dsn for the active tenant without opening a connection."""
    current_tenant_id = None
    try:
        from nexa_http import g, session, has_request_context
        if g:
            current_tenant_id = g.get('current_tenant_id')
        if (current_tenant_id is None or (isinstance(current_tenant_id, str) and (not current_tenant_id.strip()))) and has_request_context():
            tid = session.get('tenant_id')
            if isinstance(tid, str):
                _s = tid.strip()
                current_tenant_id = _s if _s and _s.lower() != 'none' else None
            else:
                current_tenant_id = None
    except RuntimeError:
        current_tenant_id = None
    if current_tenant_id is None:
        try:
            current_tenant_id = getattr(_ACTIVE_DB_CONTEXT, 'tenant_id', None)
        except Exception:
            current_tenant_id = None
    if isinstance(current_tenant_id, str):
        _s = current_tenant_id.strip()
        current_tenant_id = _s if _s and _s.lower() != 'none' else None
    if is_multi_db_mode() and current_tenant_id:
        return get_tenant_config(current_tenant_id)
    if is_multi_db_mode() and (not current_tenant_id):
        cfg = get_auth_db_config()
        if not cfg.get('user') or not cfg.get('dsn'):
            au = (os.getenv('AUTH_DB_USERNAME') or '').strip()
            ad = (os.getenv('AUTH_DB_DSN') or '').strip()
            missing = []
            if not au:
                missing.append('AUTH_DB_USERNAME')
            if not ad:
                missing.append('AUTH_DB_DSN')
            raise ValueError(f"Auth database not configured. Multi-DB requires AUTH_DB_USERNAME, AUTH_DB_PASSWORD, and AUTH_DB_DSN in .env (missing or empty: {', '.join(missing)}). Restart the app after saving. Or use /database-setup.")
        return cfg
    config = get_db_config()
    if not config.get('user') or not config.get('dsn'):
        du = (os.getenv('DB_USERNAME') or '').strip()
        dd = (os.getenv('DB_DSN') or '').strip()
        missing = []
        if not du:
            missing.append('DB_USERNAME')
        if not dd:
            missing.append('DB_DSN')
        auth_u = (os.getenv('AUTH_DB_USERNAME') or '').strip()
        auth_d = (os.getenv('AUTH_DB_DSN') or '').strip()
        partial_auth = bool(auth_u or auth_d) and (not (auth_u and auth_d))
        hint = ''
        if partial_auth:
            hint = ' You have a partial AUTH_DB_* set: both AUTH_DB_USERNAME and AUTH_DB_DSN are required for multi-DB; otherwise the app uses single-DB and still needs DB_USERNAME and DB_DSN.'
        raise ValueError(f"Oracle default connection is not configured (single-DB mode). Set DB_USERNAME, DB_PASSWORD, and DB_DSN in .env next to app.py (missing or empty: {', '.join(missing)}). Restart the app after saving. Or open /database-setup to configure." + hint)
    return config


def _open_tenant_connection() -> cx_Oracle.Connection:
    cfg = _resolve_db_connect_config()
    return cx_oracle_connect(user=cfg['user'], password=cfg['password'], dsn=cfg['dsn'])


def _open_auth_connection() -> cx_Oracle.Connection:
    if is_multi_db_mode():
        return _get_auth_connection()
    return _open_tenant_connection()


class _ConnectionScope:
    """Context manager — closes only when the connection is not request-scoped."""

    __slots__ = ('_conn', '_close_on_exit')

    def __init__(self, conn: Any, *, close_on_exit: bool = True) -> None:
        self._conn = conn
        self._close_on_exit = close_on_exit

    def __enter__(self) -> Any:
        return self._conn

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        if self._close_on_exit:
            try:
                self._conn.close()
            except Exception:
                pass
        return False

    def __getattr__(self, name: str) -> Any:
        return getattr(self._conn, name)


def _get_connection() -> _ConnectionScope:
    """Get database connection. In multi-DB mode with session tenant_id, uses tenant DB; else single DB from config."""
    try:
        from nexa_http.oracle_request_scope import borrow_connection

        conn, scoped = borrow_connection('tenant', _open_tenant_connection)
        return _ConnectionScope(conn, close_on_exit=not scoped)
    except Exception:
        return _ConnectionScope(_open_tenant_connection(), close_on_exit=True)


def _get_connection_auth() -> _ConnectionScope:
    """Connection for login_users, roles, tenant_databases. Auth DB when multi-DB; else single DB."""
    try:
        from nexa_http.oracle_request_scope import borrow_connection

        conn, scoped = borrow_connection('auth', _open_auth_connection)
        return _ConnectionScope(conn, close_on_exit=not scoped)
    except Exception:
        return _ConnectionScope(_open_auth_connection(), close_on_exit=True)


def _fix_mojibake(text: Any) -> Any:
    """Attempt to fix wrong encoding of Arabic (ITEMNAMEARA). Handles UTF-8 decoded as Latin-1 or as Windows-1256."""
    if not isinstance(text, str) or not text.strip():
        return text
    arabic_rng = ('\u0600', 'ۿ')
    n = len(text)
    arabic_count = sum((1 for ch in text if arabic_rng[0] <= ch <= arabic_rng[1]))
    if arabic_count > 0 and (n <= 4 or arabic_count / float(n) >= 0.25):
        latin_mojibake_markers = ('Ã', 'Â', 'Ð', 'Ø', 'Ù', 'Å', 'ã', 'ä', 'ï', 'ý')
        if not any((m in text for m in latin_mojibake_markers)):
            return text
    if any((arabic_rng[0] <= ch <= arabic_rng[1] for ch in text)) or any((ord(ch) > 127 for ch in text)):
        try:
            fixed = text.encode('cp1256').decode('utf-8')
            if any(('\u0600' <= ch <= 'ۿ' for ch in fixed)) and '�' not in fixed:
                return fixed
        except (UnicodeEncodeError, UnicodeDecodeError):
            pass
    try:
        raw_bytes = text.encode('latin1')
    except UnicodeEncodeError:
        return text
    for encoding in ('utf-8', 'cp1256'):
        try:
            fixed = raw_bytes.decode(encoding)
            if any(('\u0600' <= ch <= 'ۿ' for ch in fixed)):
                return fixed
        except UnicodeDecodeError:
            continue
    if any((ch in text for ch in ('Ã', 'Â', 'Ð', 'Ø', 'Ù'))):
        try:
            fixed = text.encode('latin1').decode('utf-8')
            if any(('\u0600' <= ch <= 'ۿ' for ch in fixed)):
                return fixed
        except Exception:
            pass
    return text

def _display_item_name_prefer_arabic(itemname: Any, itemnameara: Any) -> str:
    """Prefer ITEMNAMEARA for UI when non-empty; else ITEMNAME (sales popups, barcode lookup)."""
    ara = _fix_mojibake(itemnameara)
    if isinstance(ara, str) and ara.strip():
        return ara.strip()
    return str(itemname or '').strip()

def _materialize_db_value(v: Any) -> Any:
    """Convert DB driver objects (e.g. CLOB/BLOB) to plain Python values."""
    if v is None:
        return None
    if hasattr(v, 'read'):
        try:
            data = v.read()
            if isinstance(data, bytes):
                try:
                    return data.decode('utf-8', errors='ignore')
                except Exception:
                    return data
            return data
        except Exception:
            return ''
    return v

def _oracle_bind_subset(sql: str, bind_params: Dict[str, Any]) -> Dict[str, Any]:
    """Keep only bind keys referenced as ``:name`` in *sql* (avoids ORA-01036 on thin oracledb)."""
    if not isinstance(bind_params, dict):
        return bind_params
    names = [m.group(1).lower() for m in re.finditer(':([A-Za-z_][A-Za-z0-9_]*)', sql or '')]
    if not names:
        return bind_params
    lower_map = {str(k).lower(): v for k, v in bind_params.items()}
    return {name: lower_map[name] for name in names if name in lower_map}

def _cursor_execute_named(cur: Any, sql: str, bind_params: Dict[str, Any]) -> None:
    """Execute with bind dict filtered to names used in *sql*."""
    try:
        cur.execute(sql, _oracle_bind_subset(sql, bind_params))
    except cx_Oracle.DatabaseError as e:
        if 'ORA-01036' in str(e) and isinstance(bind_params, dict):
            cur.execute(sql, _oracle_bind_subset(sql, bind_params))
        else:
            raise

def _fetch_rows(query: str, params: Dict[str, Any]) -> Tuple[List[str], List[Dict[str, Any]]]:
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                _cursor_execute_named(cur, query, params)
                columns = [col[0].lower() for col in cur.description]
                rows = [dict(zip(columns, [_materialize_db_value(v) for v in row])) for row in cur.fetchall()]
                return (columns, rows)
    except Exception as e:
        print(f'[ERROR _fetch_rows] Query failed: {e}')
        print(f'[ERROR _fetch_rows] Query preview: {query[:200]}...')
        raise

def _fetch_rows_with_key(_db_key_ignored: Any, query: str, params: Dict[str, Any]) -> Tuple[List[str], List[Dict[str, Any]]]:
    """Legacy: db_key ignored; single database only."""
    return _fetch_rows(query, params)

def _get_scalar(query: str, params: Dict[str, Any]) -> float:
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(query, params)
            row = cur.fetchone()
            return float(row[0]) if row and row[0] is not None else 0.0

def _get_count(query: str, params: Dict[str, Any]) -> int:
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(query, params)
            row = cur.fetchone()
            return int(row[0]) if row and row[0] is not None else 0

def is_unique_constraint_violation(exc: BaseException) -> bool:
    """
    True if Oracle rejected a statement for unique / primary key violation (ORA-00001).
    Use this in retry loops when two sessions choose the same next number.
    """
    if exc is None:
        return False
    s = str(exc).upper()
    if 'ORA-00001' in s:
        return True
    if 'UNIQUE CONSTRAINT' in s and 'VIOLATED' in s:
        return True
    a0 = exc.args[0] if getattr(exc, 'args', None) else None
    if a0 is not None and getattr(a0, 'code', None) == 1:
        return True
    return False

def _assert_safe_sql_ident(name: str) -> str:
    """Table or column: letters, digits, underscore; must not be empty."""
    s = (name or '').strip()
    if not s or not re.match('^[A-Za-z_][A-Za-z0-9_]*$', s):
        raise ValueError(f'Invalid SQL identifier: {name!r}')
    return s.upper()

def get_next_int_key(table: str, pk_column: str, where_sql: str='', where_params: Optional[Dict[str, Any]]=None) -> int:
    """
    Return the next integer key as NVL(MAX(pk_column), 0) + 1 (tenant connection).

    Use where_sql to scope the MAX (e.g. per location). where_sql must start with
    ``WHERE`` and use only :bind names (e.g. ``" WHERE LOCATIONCODE = :loc"``).
    where_params is only for that fragment.

    Notes:
    * Best for NUMBER / integer PKs. If several sessions run concurrently, two calls
      can return the same value until one commits — use :func:`insert_row_bump_int_pk`
      to retry on ORA-00001, or a DB sequence, or SELECT ... FOR UPDATE of a lock row.
    * For VARCHAR2 codes (e.g. 'PCS'), use application-specific logic, not this helper.
    """
    t = _assert_safe_sql_ident(table)
    c = _assert_safe_sql_ident(pk_column)
    wsql = (where_sql or '').strip()
    if wsql and (not wsql.upper().startswith('WHERE')):
        raise ValueError('where_sql must be empty or start with WHERE')
    wp = {str(k).lower(): v for k, v in (where_params or {}).items()}
    q = f'SELECT NVL(MAX({c}), 0) + 1 AS nxt FROM {t} {wsql}'
    try:
        _, rows = _fetch_rows(q, wp)
        if rows and rows[0].get('nxt') is not None:
            return int(rows[0]['nxt'])
    except Exception as e:
        print(f'[ERROR get_next_int_key] {e} query={q[:200]}')
    return 1

def _normalize_row_keys_upper(row: Dict[str, Any]) -> Dict[str, Any]:
    return {k.strip().upper(): v for k, v in row.items() if isinstance(k, str)}

def insert_row_bump_int_pk(table: str, pk_column: str, row: Dict[str, Any], *, where_sql_for_max: str='', where_params_for_max: Optional[Dict[str, Any]]=None, use_provided_pk_if_exists: bool=True, max_attempts: int=100) -> Tuple[bool, str, Optional[int]]:
    """
    Insert one row (tenant DB). The primary key must be a **numeric** column.

    * If ``use_provided_pk_if_exists`` is True and the row already contains a value
      for the PK, that value is tried first. On ORA-00001 (duplicate) or a collision
      after concurrent inserts, a fresh **next** value is taken from
      :func:`get_next_int_key` (same max scope) and the insert is retried.
    * If the PK in the row is ``None`` or missing, the first value is
      :func:`get_next_int_key`.

    This addresses duplicate keys and "overlap" when two users receive the same
    MAX+1 before either commits. ``max_attempts`` caps the retry loop (default 100).

    Returns (success, error_message, chosen_pk or None)

    **Example (scoped next number):**

    .. code-block:: python

        ok, err, pk = insert_row_bump_int_pk(
            "ITEMMASTER",
            "ITEMCODE",
            {
                "ITEMCODE": None,
                "ITEMNAME": "X",
                "LOCATIONCODE": 1,
            },
            where_sql_for_max=" WHERE LOCATIONCODE = :loc",
            where_params_for_max={"loc": 1},
        )
    """
    t = _assert_safe_sql_ident(table)
    pkc = _assert_safe_sql_ident(pk_column)
    work = _normalize_row_keys_upper(row)
    for col in work:
        _assert_safe_sql_ident(col)
    if pkc not in work:
        return (False, f'Row must include column {pkc}', None)
    wpmax = {str(k).lower(): v for k, v in (where_params_for_max or {}).items()}
    cols = list(work.keys())
    if not cols:
        return (False, 'Row is empty', None)

    def _coerce_int_pk(v: Any) -> int:
        if v is None:
            raise TypeError('none')
        if isinstance(v, bool):
            raise TypeError('bool')
        if isinstance(v, int):
            return v
        s = str(v).strip()
        if not s:
            raise TypeError('empty')
        return int(s)
    if not use_provided_pk_if_exists or work[pkc] is None:
        try:
            work[pkc] = get_next_int_key(t, pkc, where_sql_for_max, wpmax)
        except Exception as ex:
            return (False, f'get_next_int_key: {ex}', None)
    else:
        try:
            work[pkc] = _coerce_int_pk(work[pkc])
        except (TypeError, ValueError) as ex:
            return (False, f'PK {pkc} must be integer: {ex}', None)
    col_list = ', '.join(cols)
    val_list = ', '.join([f':{c.lower()}' for c in cols])
    insert_sql = f'INSERT INTO {t} ({col_list}) VALUES ({val_list})'
    last_err: Optional[str] = None
    for attempt in range(max_attempts):
        params = {c.lower(): work[c] for c in cols}
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute(insert_sql, params)
                conn.commit()
            try:
                final_pk = _coerce_int_pk(work[pkc])
            except (TypeError, ValueError):
                final_pk = None
            return (True, '', final_pk)
        except Exception as e:
            last_err = str(e)
            if not is_unique_constraint_violation(e):
                return (False, last_err, None)
            try:
                work[pkc] = get_next_int_key(t, pkc, where_sql_for_max, wpmax)
            except Exception as ex2:
                return (False, f'After duplicate, get_next_int_key failed: {ex2}', None)
    return (False, last_err or f'Exhausted {max_attempts} attempts (unique collisions)', None)

def _safe_rows(query: str, params: Dict[str, Any], db_key: Optional[str]=None) -> List[Dict[str, Any]]:
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except cx_Oracle.DatabaseError:
        return []

def _safe_rows_auth(query: str, params: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Run query against auth DB (login_users, roles, tenant_databases)."""
    try:
        with _get_connection_auth() as conn:
            with conn.cursor() as cur:
                cur.execute(query, params)
                columns = [col[0].lower() for col in cur.description] if cur.description else []
                rows = [dict(zip(columns, [_materialize_db_value(v) for v in row])) for row in cur.fetchall()]
                return rows
    except (cx_Oracle.DatabaseError, AttributeError, TypeError):
        return []

def ensure_smart_list_ai_history_table() -> None:
    """Create Smart List AI chat history table in tenant DB when missing."""
    global _SMARTLIST_AI_HISTORY_ENSURED
    if _SMARTLIST_AI_HISTORY_ENSURED:
        return
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(1) FROM user_tables WHERE table_name = 'SMARTLIST_AI_HISTORY'")
            exists = int((cur.fetchone() or [0])[0] or 0) > 0
            if not exists:
                cur.execute('\n                    CREATE TABLE SMARTLIST_AI_HISTORY (\n                        MSG_ID      VARCHAR2(40 BYTE) PRIMARY KEY,\n                        CHAT_ID     VARCHAR2(40 BYTE) NOT NULL,\n                        CHAT_TITLE  VARCHAR2(200 BYTE),\n                        USER_NAME   VARCHAR2(100 BYTE) NOT NULL,\n                        TENANT_ID   VARCHAR2(50 BYTE),\n                        ROLE        VARCHAR2(20 BYTE) NOT NULL,\n                        CONTENT     CLOB,\n                        CREATED_AT  TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL\n                    )\n                    ')
            else:
                cur.execute("SELECT COUNT(1) FROM user_tab_columns WHERE table_name = 'SMARTLIST_AI_HISTORY' AND column_name = 'CHAT_TITLE'")
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute('ALTER TABLE SMARTLIST_AI_HISTORY ADD CHAT_TITLE VARCHAR2(200 BYTE)')
            cur.execute("SELECT COUNT(1) FROM user_indexes WHERE index_name = 'IX_SLAI_CHAT'")
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                cur.execute('CREATE INDEX IX_SLAI_CHAT ON SMARTLIST_AI_HISTORY (CHAT_ID, CREATED_AT)')
            cur.execute("SELECT COUNT(1) FROM user_indexes WHERE index_name = 'IX_SLAI_USER_TENANT'")
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                cur.execute('CREATE INDEX IX_SLAI_USER_TENANT ON SMARTLIST_AI_HISTORY (USER_NAME, TENANT_ID, CREATED_AT)')
    _SMARTLIST_AI_HISTORY_ENSURED = True

def save_smart_list_ai_message(msg_id: str, chat_id: str, user_name: str, tenant_id: Optional[str], role: str, content: str) -> None:
    """Persist one Smart List AI chat message for a user and tenant."""
    if not (msg_id and chat_id and user_name and role):
        return
    text = str(content or '').strip()
    if not text:
        return
    role_up = str(role or '').strip().lower()
    if role_up not in {'user', 'assistant'}:
        return
    ensure_smart_list_ai_history_table()
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute('\n                INSERT INTO SMARTLIST_AI_HISTORY\n                (MSG_ID, CHAT_ID, USER_NAME, TENANT_ID, ROLE, CONTENT, CREATED_AT)\n                VALUES\n                (:msg_id, :chat_id, :user_name, :tenant_id, :role, :content, SYSTIMESTAMP)\n                ', {'msg_id': str(msg_id)[:40], 'chat_id': str(chat_id)[:40], 'user_name': str(user_name)[:100], 'tenant_id': str(tenant_id)[:50] if tenant_id else None, 'role': role_up, 'content': text})

def get_smart_list_ai_chat_sessions(user_name: str, tenant_id: Optional[str], limit: int=20) -> List[Dict[str, Any]]:
    """Get recent chat sessions for one user in current tenant DB."""
    ensure_smart_list_ai_history_table()
    lim = max(1, min(int(limit or 20), 100))
    return _safe_rows("\n        SELECT * FROM (\n            SELECT\n                CHAT_ID AS chat_id,\n                MAX(CHAT_TITLE) KEEP (DENSE_RANK LAST ORDER BY CREATED_AT) AS chat_title,\n                MAX(CREATED_AT) AS last_message_at,\n                MIN(CASE WHEN ROLE = 'user' THEN DBMS_LOB.SUBSTR(CONTENT, 160, 1) END)\n                    KEEP (DENSE_RANK FIRST ORDER BY CREATED_AT) AS first_prompt,\n                COUNT(1) AS message_count\n            FROM SMARTLIST_AI_HISTORY\n            WHERE USER_NAME = :u\n              AND NVL(TENANT_ID, '~') = NVL(:t, '~')\n            GROUP BY CHAT_ID\n            ORDER BY MAX(CREATED_AT) DESC\n        )\n        WHERE ROWNUM <= :lim\n        ", {'u': str(user_name)[:100], 't': str(tenant_id)[:50] if tenant_id else None, 'lim': lim})

def get_smart_list_ai_chat_messages(user_name: str, tenant_id: Optional[str], chat_id: str, limit: int=300) -> List[Dict[str, Any]]:
    """Get ordered messages for one Smart List AI chat session."""
    ensure_smart_list_ai_history_table()
    lim = max(1, min(int(limit or 300), 1000))
    return _safe_rows("\n        SELECT role, content, created_at\n        FROM (\n            SELECT\n                ROLE AS role,\n                DBMS_LOB.SUBSTR(CONTENT, 4000, 1) AS content,\n                CREATED_AT AS created_at\n            FROM SMARTLIST_AI_HISTORY\n            WHERE USER_NAME = :u\n              AND NVL(TENANT_ID, '~') = NVL(:t, '~')\n              AND CHAT_ID = :chat_id\n            ORDER BY CREATED_AT\n        )\n        WHERE ROWNUM <= :lim\n        ", {'u': str(user_name)[:100], 't': str(tenant_id)[:50] if tenant_id else None, 'chat_id': str(chat_id)[:40], 'lim': lim})

def delete_smart_list_ai_chat(user_name: str, tenant_id: Optional[str], chat_id: str) -> int:
    """Delete one Smart List AI chat session for a user. Returns deleted row count."""
    ensure_smart_list_ai_history_table()
    cid = str(chat_id or '').strip()[:40]
    if not cid:
        return 0
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("\n                DELETE FROM SMARTLIST_AI_HISTORY\n                WHERE USER_NAME = :u\n                  AND NVL(TENANT_ID, '~') = NVL(:t, '~')\n                  AND CHAT_ID = :chat_id\n                ", {'u': str(user_name or '')[:100], 't': str(tenant_id)[:50] if tenant_id else None, 'chat_id': cid})
            return int(cur.rowcount or 0)

def rename_smart_list_ai_chat(user_name: str, tenant_id: Optional[str], chat_id: str, title: str) -> int:
    """Rename one Smart List AI chat session. Returns updated row count."""
    ensure_smart_list_ai_history_table()
    cid = str(chat_id or '').strip()[:40]
    ttl = str(title or '').strip()[:200]
    if not cid:
        return 0
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("\n                UPDATE SMARTLIST_AI_HISTORY\n                SET CHAT_TITLE = :title\n                WHERE USER_NAME = :u\n                  AND NVL(TENANT_ID, '~') = NVL(:t, '~')\n                  AND CHAT_ID = :chat_id\n                ", {'title': ttl if ttl else None, 'u': str(user_name or '')[:100], 't': str(tenant_id)[:50] if tenant_id else None, 'chat_id': cid})
            return int(cur.rowcount or 0)
_FK_CONSTRAINT_NAME_DD = re.compile('^[A-Z0-9_$#]+$')

def _drop_companyprofile_fk_referencing_pdccheck(cur: Any) -> None:
    """Strip bogus heuristic FK COMPANYPROFILE -> PDCCHECK (same-named ID); avoids ORA-02291 on save."""
    cur.execute("SELECT COUNT(1) FROM user_tables WHERE table_name = 'COMPANYPROFILE'")
    if int((cur.fetchone() or [0])[0] or 0) == 0:
        return
    cur.execute("\n        SELECT c.constraint_name\n          FROM user_constraints c\n          JOIN user_constraints r ON r.constraint_name = c.r_constraint_name\n                                   AND r.constraint_type IN ('P', 'U')\n         WHERE c.table_name = 'COMPANYPROFILE'\n           AND c.constraint_type = 'R'\n           AND r.table_name = 'PDCCHECK'\n        ")
    for row in cur.fetchall() or []:
        cn = str((row or [None])[0] or '').strip().upper()
        if not cn or not _FK_CONSTRAINT_NAME_DD.match(cn):
            continue
        cur.execute('ALTER TABLE COMPANYPROFILE DROP CONSTRAINT %s' % cn)

def _drop_category_fk_referencing_pdccheck(cur: Any) -> None:
    """Strip bogus FK CATEGORY.ID -> PDCCHECK.ID.RFIM CATEGORY.ID links hierarchy codes, not PDC cheque PKs."""
    cur.execute("SELECT COUNT(1) FROM user_tables WHERE table_name = 'CATEGORY'")
    if int((cur.fetchone() or [0])[0] or 0) == 0:
        return
    cur.execute("\n        SELECT c.constraint_name\n          FROM user_constraints c\n          JOIN user_constraints r ON r.constraint_name = c.r_constraint_name\n                                   AND r.constraint_type IN ('P', 'U')\n         WHERE c.table_name = 'CATEGORY'\n           AND c.constraint_type = 'R'\n           AND r.table_name = 'PDCCHECK'\n        ")
    for row in cur.fetchall() or []:
        cn = str((row or [None])[0] or '').strip().upper()
        if not cn or not _FK_CONSTRAINT_NAME_DD.match(cn):
            continue
        cur.execute('ALTER TABLE CATEGORY DROP CONSTRAINT %s' % cn)

def _maybe_strip_category_fk_to_pdccheck_before_write() -> None:
    """Drop misplaced CATEGORY.ID -> PDCCHECK FK if present (ORA-02291 on category saves)."""
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                _drop_category_fk_referencing_pdccheck(cur)
            conn.commit()
    except Exception as e:
        print(f'[WARN strip CATEGORY FK to PDCCHECK] {e}')

def ensure_company_profile_table() -> None:
    """Create COMPANYPROFILE (single row ID=1) in current tenant DB for org details and logo."""
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(1) FROM user_tables WHERE table_name = 'COMPANYPROFILE'")
            exists = int((cur.fetchone() or [0])[0] or 0) > 0
            if not exists:
                cur.execute('\n                    CREATE TABLE COMPANYPROFILE (\n                        ID             NUMBER(10) PRIMARY KEY,\n                        COMPANY_NAME   VARCHAR2(200 BYTE),\n                        LEGAL_NAME     VARCHAR2(200 BYTE),\n                        ADDRESS1       VARCHAR2(300 BYTE),\n                        ADDRESS2       VARCHAR2(300 BYTE),\n                        CITY           VARCHAR2(120 BYTE),\n                        STATE_REGION   VARCHAR2(120 BYTE),\n                        COUNTRY        VARCHAR2(120 BYTE),\n                        POSTAL_CODE    VARCHAR2(40 BYTE),\n                        PHONE          VARCHAR2(60 BYTE),\n                        EMAIL          VARCHAR2(150 BYTE),\n                        WEBSITE        VARCHAR2(250 BYTE),\n                        TAX_ID         VARCHAR2(80 BYTE),\n                        LOGO_MODE      VARCHAR2(20 BYTE),\n                        LOGO_PATH      VARCHAR2(500 BYTE),\n                        LOGO_URL       VARCHAR2(500 BYTE),\n                        UPDATED_AT     DATE\n                    )\n                    ')
                cur.execute('INSERT INTO COMPANYPROFILE (ID) VALUES (1)')
            _drop_companyprofile_fk_referencing_pdccheck(cur)
        conn.commit()
    _TABLE_EXISTS_CACHE.pop('COMPANYPROFILE', None)

