def _fetch_rows_itemnameara_only(_db_key_ignored: Any, query: str, params: Dict[str, Any], nls_lang: str='AMERICAN_AMERICA.UTF8') -> List[Dict[str, Any]]:
    """Run query with NLS_LANG set only for this connection (for ITEMNAMEARA). Avoids ORA-12705 elsewhere."""
    config = get_db_config()
    if not config.get('user') or not config.get('dsn'):
        return _safe_rows(query, params)
    old_nls = os.environ.get('NLS_LANG')
    try:
        os.environ['NLS_LANG'] = nls_lang
        conn = cx_oracle_connect(user=config['user'], password=config['password'], dsn=config['dsn'])
        try:
            with conn.cursor() as cur:
                cur.execute(query, params)
                columns = [col[0].lower() for col in cur.description]
                rows = [dict(zip(columns, row)) for row in cur.fetchall()]
                return rows
        finally:
            conn.close()
    except cx_Oracle.DatabaseError as e:
        if 'ORA-12705' in str(e) or '12705' in str(e):
            pass
        else:
            raise
    finally:
        if old_nls is None:
            os.environ.pop('NLS_LANG', None)
        else:
            os.environ['NLS_LANG'] = old_nls
    return _safe_rows(query, params)


def _execute_itemnameara_dml(query: str, params: Dict[str, Any], nls_lang: str = 'AMERICAN_AMERICA.UTF8') -> int:
    """Execute DML with Arabic-safe NLS (ITEMNAMEARA updates). Returns rowcount."""
    config = get_db_config()
    if not config.get('user') or not config.get('dsn'):
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(query, params)
                n = int(cur.rowcount or 0)
            conn.commit()
            return n
    old_nls = os.environ.get('NLS_LANG')
    try:
        os.environ['NLS_LANG'] = nls_lang
        conn = cx_oracle_connect(user=config['user'], password=config['password'], dsn=config['dsn'])
        try:
            with conn.cursor() as cur:
                cur.execute(query, params)
                n = int(cur.rowcount or 0)
            conn.commit()
            return n
        finally:
            conn.close()
    except Exception:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(query, params)
                n = int(cur.rowcount or 0)
            conn.commit()
            return n
    finally:
        if old_nls is None:
            os.environ.pop('NLS_LANG', None)
        else:
            os.environ['NLS_LANG'] = old_nls


def _itemmaster_missing_arabic_where_sql(imx: str, lc_col: str) -> str:
    """Rows with a non-empty ITEMNAME and empty/null ITEMNAMEARA.

    Oracle treats '' as NULL, so never use ``NVL(TRIM(col), '') <> ''`` for non-empty checks.
    """
    icols = [c.upper() for c in (_get_table_columns(imx) or [])]
    if 'ITEMNAMEARA' not in icols:
        return '1=0'
    if 'ITEMNAME' not in icols:
        return '1=0'
    return (
        'LENGTH(TRIM(im.ITEMNAME)) > 0 '
        'AND (im.ITEMNAMEARA IS NULL OR LENGTH(TRIM(im.ITEMNAMEARA)) = 0 '
        'OR LENGTH(TRIM(im.ITEMNAMEARA)) IS NULL)'
    )


def count_itemmaster_missing_itemnameara(location_code: int) -> int:
    """Count ITEMMASTER rows with ITEMNAME but empty/null ITEMNAMEARA for a branch."""
    if not _table_exists('ITEMMASTER'):
        return 0
    imx = _detect_table('ITEMMASTER') or 'ITEMMASTER'
    lc_col = _detect_column(imx, ['LOCATIONCODE', 'locationcode']) or 'LOCATIONCODE'
    where_extra = _itemmaster_missing_arabic_where_sql(imx, lc_col)
    q = f'SELECT COUNT(*) AS cnt FROM {imx} im WHERE im.{lc_col} = :loc AND {where_extra}'
    rows = _safe_rows(q, {'loc': int(location_code)})
    if not rows:
        return 0
    try:
        return int(rows[0].get('cnt') or 0)
    except (TypeError, ValueError):
        return 0


def fetch_itemmaster_missing_itemnameara_batch(
    location_code: int, offset: int, limit: int,
) -> List[Dict[str, Any]]:
    """Paged ITEMCODE + ITEMNAME rows needing ITEMNAMEARA for a branch."""
    if not _table_exists('ITEMMASTER') or limit <= 0:
        return []
    imx = _detect_table('ITEMMASTER') or 'ITEMMASTER'
    lc_col = _detect_column(imx, ['LOCATIONCODE', 'locationcode']) or 'LOCATIONCODE'
    ic_col = _detect_column(imx, ['ITEMCODE', 'itemcode']) or 'ITEMCODE'
    where_extra = _itemmaster_missing_arabic_where_sql(imx, lc_col)
    off = max(0, int(offset))
    lim = max(1, min(int(limit), 500))
    hi = off + lim
    q = f"""
        SELECT itemcode, itemname FROM (
            SELECT TO_CHAR(im.{ic_col}) AS itemcode,
                   im.ITEMNAME AS itemname,
                   ROW_NUMBER() OVER (ORDER BY im.{ic_col}) AS rn
            FROM {imx} im
            WHERE im.{lc_col} = :loc AND {where_extra}
        ) t
        WHERE t.rn > :off AND t.rn <= :hi
    """
    rows = _safe_rows(q, {'loc': int(location_code), 'off': off, 'hi': hi})
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        try:
            ic = int(str(r.get('itemcode') or '').strip())
        except (TypeError, ValueError):
            continue
        name = str(r.get('itemname') or '').strip()
        if not name:
            continue
        out.append({'itemcode': ic, 'itemname': name})
    return out


