def returnhdr_goodsreturnno_match_sql(col_sql: str, *, bind_prefix: str = 'grn') -> str:
    """SQL predicate matching GOODSRETURNNO without implicit VARCHAR→NUMBER conversion."""
    p_str = f'{bind_prefix}_str'
    p_num = f'{bind_prefix}_num'
    num_suffix = f"NVL(TO_NUMBER(REGEXP_SUBSTR(TO_CHAR({col_sql}), '[0-9]+$')), 0)"
    return (
        f"(TO_CHAR({col_sql}) = :{p_str} "
        f"OR (:{p_num} > 0 AND {num_suffix} = :{p_num}))"
    )


def returnhdr_goodsreturnno_match_params(val: Any, *, bind_prefix: str = 'grn') -> Dict[str, Any]:
    """Bind params paired with returnhdr_goodsreturnno_match_sql()."""
    s = normalize_goodsreturnno(val)
    n = billno_numeric_part(val)
    p_str = f'{bind_prefix}_str'
    p_num = f'{bind_prefix}_num'
    if not s and n > 0:
        s = str(n)
    return {p_str: s, p_num: int(n) if n > 0 else -1}


def returnhdr_goodsreturnno_is_valid_match(val: Any) -> bool:
    s = normalize_goodsreturnno(val)
    n = billno_numeric_part(val)
    if s and not s.lstrip('-').isdigit():
        return True
    return n > 0


