def _goodsreturnno_table_needs_varchar_migration(tbl: Optional[str]) -> bool:
    if not tbl:
        return False
    try:
        types = _get_table_column_types_with_key(tbl)
        col = _detect_column(tbl, ['GOODSRETURNNO', 'goodsreturnno'])
        if not col:
            return False
        dt = str(types.get(str(col).upper()) or '').upper()
        return dt not in ('VARCHAR2', 'VARCHAR', 'CHAR', 'NVARCHAR2', 'NCHAR')
    except Exception:
        return False


def ensure_goodsreturnno_varchar_columns() -> bool:
    """Migrate GOODSRETURNNO to VARCHAR2(30) when GOODSRETURNNO_AS_VARCHAR=1 (or BILLNO_AS_VARCHAR=1)."""
    global _GOODSRETURNNO_VARCHAR_ENSURED
    if not _goodsreturnno_varchar_requested():
        return goodsreturnno_uses_varchar_storage()
    temp_hdr = _detect_table(['TEMPRETURNHDR', 'tempreturnhdr'])
    ret_hdr = _detect_table(['RETURNHDR', 'returnhdr'])
    temp_dtl = _detect_table(['TEMPRETURNDTL', 'tempreturndtl'])
    ret_dtl = _detect_table(['RETURNDTL', 'returndtl'])
    needs_any = any(
        _goodsreturnno_table_needs_varchar_migration(t)
        for t in (temp_hdr, ret_hdr, temp_dtl, ret_dtl)
    )
    if _GOODSRETURNNO_VARCHAR_ENSURED and not needs_any:
        return goodsreturnno_uses_varchar_storage()
    _GOODSRETURNNO_VARCHAR_ENSURED = True
    if not temp_hdr and not ret_hdr:
        print('[WARN ensure_goodsreturnno_varchar_columns] TEMPRETURNHDR/RETURNHDR not found; skipped.')
        return False
    ok_any = goodsreturnno_uses_varchar_storage() or returnhdr_goodsreturnno_uses_varchar_storage()
    core_specs: List[Tuple[Any, ...]] = []
    if temp_hdr:
        core_specs.append((temp_hdr, 'GOODSRETURNNO', 'PK_TEMPRETURNHDR', ['LOCATIONCODE', 'GOODSRETURNNO'], []))
    if temp_dtl:
        core_specs.append((temp_dtl, 'GOODSRETURNNO', 'PK_TEMPRETURNDTL', ['LOCATIONCODE', 'GOODSRETURNNO', 'ITEMCODE'], []))
    if ret_hdr:
        core_specs.append((ret_hdr, 'GOODSRETURNNO', 'PK_RETURNHDR', ['LOCATIONCODE', 'RESETNO', 'GOODSRETURNNO'], []))
    if ret_dtl:
        d_item = _detect_column(ret_dtl, ['ITEMCODE', 'itemcode']) or 'ITEMCODE'
        d_uom = _detect_column(ret_dtl, ['UOM', 'uom']) or 'UOM'
        core_specs.append((ret_dtl, 'GOODSRETURNNO', 'PK_RETURNDTL', ['LOCATIONCODE', 'RESETNO', 'GOODSRETURNNO', d_item, d_uom], []))
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                for tbl, col, pk, pk_cols, extras in core_specs:
                    if not _table_exists(tbl):
                        continue
                    try:
                        if _oracle_migrate_docno_column_to_varchar(
                            cur, tbl, col, pk_name=pk, pk_columns=pk_cols, extra_drop_constraints=extras,
                            varchar_len=_GOODSRETURNNO_VARCHAR_LEN,
                        ):
                            ok_any = True
                    except Exception as ex:
                        print(f'[WARN ensure_goodsreturnno_varchar_columns] {tbl}.{col}: {ex}')
            conn.commit()
    except Exception as ex:
        print(f'[WARN ensure_goodsreturnno_varchar_columns] {ex}')
    if temp_hdr:
        _TABLE_COLUMNS_CACHE.pop(str(temp_hdr).upper(), None)
    if ret_hdr:
        _TABLE_COLUMNS_CACHE.pop(str(ret_hdr).upper(), None)
    ensure_purchase_approval_docno_varchar()
    return goodsreturnno_uses_varchar_storage()


def _max_existing_goodsreturnno_cur(cur: Any, table_aliases: List[str], location_code: Optional[int], reset_no: int = 1) -> int:
    tbl = _detect_table(table_aliases)
    if not tbl:
        return 0
    no_col = _detect_column(tbl, ['GOODSRETURNNO', 'goodsreturnno'])
    loc_col = _detect_column(tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    reset_col = _detect_column(tbl, ['RESETNO', 'RESET_NO', 'resetno'])
    if not no_col:
        return 0
    where = ['1=1']
    params: Dict[str, Any] = {}
    if loc_col and location_code is not None:
        where.append(f'{loc_col} = :loc')
        params['loc'] = int(location_code)
    if reset_col:
        where.append(f'{reset_col} = :rn')
        params['rn'] = int(reset_no or 1)
    try:
        cur.execute(f'SELECT {no_col} FROM {tbl} WHERE {" AND ".join(where)}', params)
        mx = 0
        for row in cur.fetchall() or []:
            mx = max(mx, billno_numeric_part(row[0]))
        return mx
    except Exception:
        return 0


