def get_next_return_order_no_cur(
    cur: Any,
    location_code: int,
    *,
    reset_no: int = 1,
    user: str = 'system',
) -> Any:
    ensure_goodsreturnno_varchar_columns()
    from addons.document_numbering.document_numbering_db import allocate_document_no_cur
    floor_no = _max_existing_goodsreturnno_cur(cur, ['TEMPRETURNHDR', 'tempreturnhdr'], location_code, reset_no=int(reset_no or 1))
    next_no, formatted, err = allocate_document_no_cur(
        cur,
        DOC_TYPE_RETURN_ORDER,
        location_code=location_code,
        reset_no=int(reset_no or 1),
        user=user,
        floor_no=floor_no if floor_no else None,
    )
    if not next_no:
        raise RuntimeError(err or 'Could not allocate return order number from document series.')
    return _goodsreturnno_storage_from_series(int(next_no), str(formatted or ''))


