def _purchase_approval_doc_no(doc_type: str, doc_no: Any) -> Any:
    """Bind value for PURCHASE_APPROVAL_* .DOC_NO — matches actual column type."""
    dt = str(doc_type or '').strip().upper()
    if dt == 'LPO':
        return _lpo_approval_doc_no(doc_no)
    if dt == 'GRN':
        return _grn_approval_doc_no(doc_no)
    if dt == 'PRR':
        ensure_goodsreturnno_varchar_columns()
        col_type = _purchase_approval_docno_column_type(refresh=True)
        if col_type == 'VARCHAR2' or (col_type == 'MISSING' and goodsreturnno_uses_varchar_storage()):
            return normalize_goodsreturnno(doc_no)
        n = billno_numeric_part(doc_no)
        if n > 0:
            return int(n)
        try:
            return int(doc_no or 0)
        except (TypeError, ValueError):
            return 0
    ensure_purchase_approval_docno_varchar()
    col_type = _purchase_approval_docno_column_type(refresh=True)
    if col_type == 'VARCHAR2' or (col_type == 'MISSING' and billno_uses_varchar_storage()):
        s = str(doc_no or '').strip()
        if s:
            return s
        n = billno_numeric_part(doc_no)
        return str(int(n)) if n > 0 else '0'
    n = billno_numeric_part(doc_no)
    if n > 0:
        return int(n)
    try:
        return int(doc_no or 0)
    except (TypeError, ValueError):
        return 0


def _peek_billno_from_series(
    location_code: Optional[int],
    reset_no: int = 1,
    *,
    doc_type: Optional[str] = None,
) -> Optional[Any]:
    from addons.document_numbering.document_numbering_db import (
        BILLNO_DOC_TYPE,
        _compute_next_series_no,
        format_document_no,
        get_document_series_by_type,
    )
    dt = str(doc_type or BILLNO_DOC_TYPE).strip().upper() or BILLNO_DOC_TYPE
    series = get_document_series_by_type(dt, location_code=location_code, reset_no=reset_no)
    if not series:
        return None
    floor_no: Optional[int] = 0 if billno_uses_varchar_storage() else None
    if not billno_uses_varchar_storage():
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    floor_no = _max_existing_billno_cur(cur, location_code)
        except Exception:
            floor_no = 0
    n = _compute_next_series_no(
        series.get('starting_no', 1),
        series.get('last_no_used', 0),
        series.get('increment_by', 1),
        floor_no=floor_no,
    )
    if n is None:
        return None
    formatted = format_document_no(series, n)
    return _billno_storage_from_series(int(n), formatted)


def _table_exists(table: str, db_key: Optional[str]=None) -> bool:
    t = (table or '').strip().upper()
    if not t:
        return False
    cache_key = _schema_cache_key(t)
    if cache_key in _TABLE_EXISTS_CACHE:
        return _TABLE_EXISTS_CACHE[cache_key]
    if t in _TABLE_EXISTS_CACHE:
        return _TABLE_EXISTS_CACHE[t]
    query = '\n        SELECT COUNT(*) AS cnt\n        FROM user_tables\n        WHERE table_name = :table_name\n    '
    try:
        result = _get_count(query, {'table_name': t}) > 0
    except Exception:
        result = False
    _TABLE_EXISTS_CACHE[cache_key] = result
    return result

def _view_exists(view_name: str, db_key: Optional[str]=None) -> bool:
    """True if ``USER_VIEWS`` contains this name (Oracle)."""
    k = (view_name or '').strip().upper()
    if not k:
        return False
    cache_key = _schema_cache_key(k)
    if cache_key in _VIEW_EXISTS_CACHE:
        return _VIEW_EXISTS_CACHE[cache_key]
    if k in _VIEW_EXISTS_CACHE:
        return _VIEW_EXISTS_CACHE[k]
    rows = _safe_rows('\n        SELECT COUNT(*) AS cnt\n        FROM user_views\n        WHERE view_name = :v\n    ', {'v': k}, db_key=db_key)
    try:
        n = int(rows[0].get('cnt') or 0) if rows else 0
    except (TypeError, ValueError, IndexError):
        n = 0
    ok = n > 0
    _VIEW_EXISTS_CACHE[cache_key] = ok
    return ok

def _table_exists_in_owner(table: str, owner: str, _db_key_ignored: Any=None) -> bool:
    query = '\n        SELECT COUNT(*) AS cnt\n        FROM all_tables\n        WHERE table_name = :table_name\n          AND owner = :owner\n    '
    try:
        _, rows = _fetch_rows(query, {'table_name': table.upper(), 'owner': owner.upper()})
        return bool(rows and rows[0] and rows[0].get('cnt'))
    except Exception as e:
        print(f'[ERROR save_item_in_tenant] tenant_id={tenant_id}, item_code={item_code}, location_code={location_code}: {e}')
        import traceback
        traceback.print_exc()
        return False

def _detect_column(table: str, candidates: List[str]) -> Optional[str]:
    """Detect which column exists in the table from a list of candidates"""
    cols = _get_table_columns(table)
    for candidate in candidates:
        if candidate.upper() in cols:
            return candidate
    return None

def _detect_table(candidates: List[str]) -> Optional[str]:
    """Return the first table name from candidates that exists."""
    for table_name in candidates:
        try:
            if _table_exists(table_name):
                return table_name
        except Exception:
            continue
    return None

def _detect_column_with_key(table: str, candidates: List[str], db_key: str) -> Optional[str]:
    """Detect which column exists in the table from a list of candidates using a specific dbkey"""
    try:
        cols = _get_table_columns_with_key(table, db_key)
        for candidate in candidates:
            if candidate.upper() in cols:
                return candidate
    except Exception as e:
        print(f'[DEBUG _detect_column_with_key] Error detecting column in {table} for {db_key}: {e}')
    return None

def get_item_stores_stock(itemcode: Any, location_code: Optional[Any]=None) -> List[Dict[str, Any]]:
    """Return rows from itemstore: itemcode, REPLACE(store,' ') itemlocation, stock. Query: SELECT itemcode, REPLACE(store,' ') itemlocation, stock FROM itemstore WHERE itemcode = :itemcode"""
    tbl = _detect_table(['ITEMSTORE', 'itemstore', 'ITEM_STORE'])
    if not tbl:
        return []
    code_col = _detect_column(tbl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    store_col = _detect_column(tbl, ['STORE', 'store', 'STORECODE', 'storecode'])
    stock_col = _detect_column(tbl, ['STOCK', 'stock', 'QTY', 'qty', 'QUANTITY', 'quantity'])
    if not code_col or not store_col:
        return []
    itemlocation_expr = f"REPLACE({tbl}.{store_col}, ' ', '') AS itemlocation"
    sel = [f'{tbl}.{code_col} AS itemcode', itemlocation_expr]
    if stock_col:
        sel.append(f'{tbl}.{stock_col} AS stock')
    else:
        sel.append('0 AS stock')
    q = f"SELECT {', '.join(sel)} FROM {tbl} WHERE {tbl}.{code_col} = :itemcode"
    params: Dict[str, Any] = {'itemcode': str(itemcode).strip() if itemcode is not None else ''}
    try:
        _, rows = _fetch_rows(q, params)
        return rows or []
    except Exception:
        return []

def get_purchase_locations() -> List[Dict[str, Any]]:
    """Return warehouse codes usable for purchase receive (active WAREHOUSE/STORE types)."""
    tbl = resolve_warehouse_master_table()
    if tbl:
        q = f"""
            SELECT WAREHOUSE_CODE AS dbcode FROM {tbl}
            WHERE NVL(IS_ACTIVE, 'Y') = 'Y'
              AND WAREHOUSE_TYPE IN ('WAREHOUSE', 'STORE')
        """
        try:
            _, rows = _fetch_rows(q, {})
            return rows or []
        except Exception:
            return []
    legacy = resolve_legacy_store_table()
    if not legacy:
        return []
    dbcode_col = _detect_column(legacy, ['DBCODE', 'dbcode', 'CODE', 'code'])
    purchase_col = _detect_column(legacy, ['PURCHASE', 'purchase'])
    if not dbcode_col:
        return []
    where = f" WHERE UPPER(TRIM({legacy}.{purchase_col})) = 'Y'" if purchase_col else ''
    q = f'SELECT {legacy}.{dbcode_col} AS dbcode FROM {legacy}{where}'
    try:
        _, rows = _fetch_rows(q, {})
        return rows or []
    except Exception:
        return []

def ensure_system_config_table(db_key: str='HO') -> None:
    """Create SYSTEMCONFIG table in HO if missing."""
    if _table_exists('SYSTEMCONFIG', db_key=db_key):
        columns = _get_table_columns_with_key('SYSTEMCONFIG', db_key)
        if 'COUNTERCODE' not in columns:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute('ALTER TABLE SYSTEMCONFIG ADD COUNTERCODE VARCHAR2(50)')
                    if 'STORECODE' in columns:
                        cur.execute('UPDATE SYSTEMCONFIG SET COUNTERCODE = STORECODE WHERE COUNTERCODE IS NULL')
                conn.commit()
        if 'STORECODE' in columns:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute('ALTER TABLE SYSTEMCONFIG DROP COLUMN STORECODE')
                conn.commit()
        if 'BIOSSERIAL' not in columns:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute('ALTER TABLE SYSTEMCONFIG ADD BIOSSERIAL VARCHAR2(200)')
                conn.commit()
        if 'LOCATION' not in columns:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute('ALTER TABLE SYSTEMCONFIG ADD LOCATION VARCHAR2(50)')
                conn.commit()
        return
    create_sql = '\n        CREATE TABLE SYSTEMCONFIG (\n            COUNTERCODE VARCHAR2(50),\n            SYSTEMNAME VARCHAR2(200),\n            COUNTERNAME VARCHAR2(100),\n            LOCATIONCODE VARCHAR2(50),\n            LOCATION VARCHAR2(50),\n            BIOSSERIAL VARCHAR2(200),\n            UPDATEDAT DATE\n        )\n    '
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(create_sql)
        conn.commit()

def ensure_pos_counter_table(_db_key_ignored: Any=None) -> None:
    """Create tenant ``COUNTER`` for POS setup if missing; add any missing columns (TABLESPACE USERS)."""
    cols_needed: Tuple[Tuple[str, str], ...] = (
        ('LOCATIONCODE', 'NUMBER(2)'),
        ('COUNTERCODE', 'NUMBER(3)'),
        ('COUNTERNAME', 'VARCHAR2(40 BYTE)'),
        ('ONLINESALE', 'CHAR(1 BYTE)'),
        ('CREATEDBY', 'VARCHAR2(50 BYTE)'),
        ('CREATEDDATE', 'DATE'),
        ('SYSTEMIP', 'VARCHAR2(20 BYTE)'),
        ('SYSTEMNAME', 'VARCHAR2(25 BYTE)'),
        ('APPROVED', "CHAR(1 BYTE) DEFAULT 'N'"),
        ('STORE', 'VARCHAR2(20 BYTE)'),
        ('WAREHOUSE_ID', 'NUMBER(10)'),
    )
    needed_names = frozenset(c[0] for c in cols_needed)
    if _table_exists('COUNTER'):
        cur_cols = frozenset(_get_table_columns_with_key('COUNTER') or [])
        if needed_names.issubset(cur_cols):
            return
    create_sql = '\n        CREATE TABLE COUNTER (\n            LOCATIONCODE   NUMBER(2),\n            COUNTERCODE    NUMBER(3),\n            COUNTERNAME    VARCHAR2(40 BYTE),\n            ONLINESALE     CHAR(1 BYTE),\n            CREATEDBY      VARCHAR2(50 BYTE),\n            CREATEDDATE    DATE,\n            SYSTEMIP       VARCHAR2(20 BYTE),\n            SYSTEMNAME     VARCHAR2(25 BYTE),\n            APPROVED       CHAR(1 BYTE) DEFAULT \'N\',\n            STORE          VARCHAR2(20 BYTE)\n        ) TABLESPACE USERS\n    '
    key = 'COUNTER'
    changed = False
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) FROM user_tables WHERE table_name = 'COUNTER'")
            exists = int((cur.fetchone() or [0])[0] or 0) > 0
            if not exists:
                try:
                    cur.execute(create_sql)
                    changed = True
                except cx_Oracle.DatabaseError as e:
                    msg = str(e)
                    if 'ORA-00955' not in msg:
                        raise
                    changed = True
            cur.execute("SELECT column_name FROM user_tab_columns WHERE table_name = 'COUNTER'")
            have = {row[0].upper() for row in cur.fetchall()}
            for col_name, col_type in cols_needed:
                if col_name not in have:
                    cur.execute(f'ALTER TABLE COUNTER ADD ({col_name} {col_type})')
                    changed = True
                    have.add(col_name)
        conn.commit()
    if changed:
        _TABLE_EXISTS_CACHE.pop(key, None)
        _TABLE_COLUMNS_CACHE.pop(key, None)

def get_system_config(db_key: str='HO') -> Dict[str, Any]:
    """Fetch counter configuration from HO."""
    ensure_pos_counter_table()
    if not _table_exists('COUNTER', db_key=db_key):
        return {}
    columns = _get_table_columns_with_key('COUNTER', db_key)
    counter_col = _detect_column_with_key('COUNTER', ['COUNTERCODE', 'countercode', 'CODE', 'code', 'COUNTER_CODE', 'counter_code'], db_key)
    counter_name_col = _detect_column_with_key('COUNTER', ['COUNTERNAME', 'countername', 'NAME', 'name', 'COUNTER_NAME', 'counter_name'], db_key)
    systemname_col = _detect_column_with_key('COUNTER', ['SYSTEMNAME', 'systemname', 'SYSTEM_NAME', 'system_name'], db_key)
    locationcode_col = _detect_column_with_key('COUNTER', ['LOCATIONCODE', 'locationcode', 'LOCATION_CODE', 'location_code'], db_key)
    select_parts = ['ROWID']
    if counter_col:
        select_parts.append(f'{counter_col} AS countercode')
    if counter_name_col:
        select_parts.append(f'{counter_name_col} AS countername')
    if systemname_col:
        select_parts.append(f'{systemname_col} AS systemname')
    if locationcode_col:
        select_parts.append(f'{locationcode_col} AS locationcode')
    select_cols = ', '.join(select_parts) if len(select_parts) > 1 else 'ROWID, *'
    order_by = f'{counter_col} DESC' if counter_col else 'ROWID DESC'
    query = f'\n        SELECT {select_cols}\n        FROM COUNTER\n        ORDER BY {order_by}\n    '
    rows = _safe_rows(query, {}, db_key=db_key)
    return rows[0] if rows else {}

