def get_system_config_rows(db_key: str='HO') -> Tuple[List[str], List[Dict[str, Any]]]:
    """Fetch all rows and columns from COUNTER for listing."""
    ensure_pos_counter_table()
    owner = get_db_config().get('user', '').upper()
    if _table_exists('COUNTER', db_key=db_key):
        columns = _get_table_columns_with_key('COUNTER', db_key)
        if not columns:
            return ([], [])
        select_cols = ', '.join(columns)
        query = f'\n            SELECT ROWID,\n                   {select_cols}\n            FROM COUNTER\n        '
        try:
            cur_cols, rows = _fetch_rows_with_key(db_key, query, {})
        except Exception:
            return ([], [])
        display_cols = [col for col in cur_cols if col != 'rowid']
        return (display_cols, rows)
    if not owner or not _table_exists_in_owner('COUNTER', owner, db_key):
        return ([], [])
    owner_columns = _get_table_columns_with_owner('COUNTER', owner, db_key)
    if not owner_columns:
        return ([], [])
    select_cols = ', '.join((f't.{col}' for col in owner_columns))
    query = f'\n        SELECT t.ROWID,\n               {select_cols}\n        FROM "{owner}"."COUNTER" t\n    '
    try:
        cur_cols, rows = _fetch_rows_with_key(db_key, query, {})
    except Exception:
        return ([], [])
    display_cols = [col for col in cur_cols if col != 'rowid']
    return (display_cols, rows)

