def biosserial_exists(biosserial: str, db_key: str='HO', exclude_rowid: Optional[str]=None) -> bool:
    if not biosserial or not _table_exists('SYSTEMCONFIG', db_key=db_key):
        return False
    columns = _get_table_columns_with_key('SYSTEMCONFIG', db_key)
    if 'BIOSSERIAL' not in columns:
        return False
    query = 'SELECT ROWID FROM SYSTEMCONFIG WHERE BIOSSERIAL = :biosserial'
    params = {'biosserial': biosserial}
    if exclude_rowid:
        query += ' AND ROWID != :exclude_rowid'
        params['exclude_rowid'] = exclude_rowid
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(query, params)
            return cur.fetchone() is not None

def save_system_config(data: Dict[str, Any], db_key: str='HO') -> None:
    """Save counter configuration in HO. Only allows updating approved, countername, and dblocation."""
    ensure_pos_counter_table()
    if not _table_exists('COUNTER', db_key=db_key):
        raise ValueError('COUNTER table does not exist.')
    columns = _get_table_columns_with_key('COUNTER', db_key)
    column_types = _get_table_column_types_with_key('COUNTER', db_key)
    counter_name_col = _detect_column_with_key('COUNTER', ['COUNTERNAME', 'countername', 'NAME', 'name', 'COUNTER_NAME', 'counter_name'], db_key)
    dblocation_col = _detect_column_with_key('COUNTER', ['DBLOCATION', 'dblocation', 'DB_LOCATION', 'db_location', 'LOCATIONCODE', 'locationcode'], db_key)
    approved_col = _detect_column_with_key('COUNTER', ['APPROVED', 'approved', 'APPROVE', 'approve'], db_key)
    row_id = data.get('rowid')
    if not row_id:
        raise ValueError('Row ID is required for update.')
    has_counter_name = counter_name_col and counter_name_col in columns
    has_dblocation = dblocation_col and dblocation_col in columns
    has_approved = approved_col and approved_col in columns

    def _coerce_value(column_name: str, value: Any) -> Any:
        if value is None:
            return None
        data_type = column_types.get(column_name)
        if data_type == 'NUMBER':
            if isinstance(value, (int, float)):
                return value
            if isinstance(value, str):
                stripped = value.strip()
                if not stripped:
                    return None
                if stripped.isdigit():
                    return int(stripped)
            return None
        return value
    with _get_connection() as conn:
        with conn.cursor() as cur:
            set_clauses = []
            params = {'row_id': row_id}
            if has_counter_name:
                set_clauses.append(f'{counter_name_col} = :countername')
                params['countername'] = _coerce_value(counter_name_col, data.get('countername'))
            if has_dblocation:
                set_clauses.append(f'{dblocation_col} = :dblocation')
                params['dblocation'] = _coerce_value(dblocation_col, data.get('dblocation'))
            if has_approved:
                set_clauses.append(f'{approved_col} = :approved')
                params['approved'] = _coerce_value(approved_col, data.get('approved'))
            if set_clauses:
                set_sql = ',\n                        '.join(set_clauses)
                cur.execute(f'\n                    UPDATE COUNTER\n                    SET {set_sql}\n                    WHERE ROWID = :row_id\n                    ', params)
        conn.commit()

def get_next_countercode(db_key: str='HO') -> str:
    """Get next counter code from COUNTER (HO)."""
    ensure_pos_counter_table()
    if not _table_exists('COUNTER', db_key=db_key):
        return '1'
    counter_col = _detect_column_with_key('COUNTER', ['COUNTERCODE', 'countercode', 'CODE', 'code', 'COUNTER_CODE', 'counter_code'], db_key)
    if not counter_col:
        return '1'
    query = f"\n        SELECT NVL(MAX(TO_NUMBER({counter_col})), 0) + 1 AS next_code\n        FROM COUNTER\n        WHERE {counter_col} IS NOT NULL\n          AND REGEXP_LIKE({counter_col}, '^[0-9]+$')\n    "
    try:
        result = _get_scalar(query, {})
        return str(int(result))
    except Exception:
        return '1'

def _norm_counter_hostname(val: Any) -> str:
    """Normalize PC name / ``COUNTER.SYSTEMNAME`` for comparison (matches POS Counter Operations JS ``normHostname``)."""
    return re.sub(r'\s+', '', str(val or '').strip().upper())


def pos_counter_systemname_normalized_in_use(normalized: str, exclude_countercode: Optional[int]=None) -> bool:
    """Return True if another ``COUNTER`` row already has this normalized ``SYSTEMNAME`` (tenant connection)."""
    if not normalized:
        return False
    try:
        rows = get_system_config_list('HO')
    except Exception:
        return False
    for r in rows or []:
        if not isinstance(r, dict):
            continue
        sn = _norm_counter_hostname(r.get('systemname'))
        if not sn or sn != normalized:
            continue
        cc = r.get('countercode')
        try:
            cci = int(cc)
        except (TypeError, ValueError):
            continue
        if exclude_countercode is not None and cci == int(exclude_countercode):
            continue
        return True
    return False


def list_warehouses_for_location(location_code: int, *, active_only: bool=True) -> List[Dict[str, Any]]:
    """Active ``WAREHOUSE_MASTER`` rows for one branch ``LOCATIONCODE`` (POS counter setup)."""
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return []
    out: List[Dict[str, Any]] = []
    for row in list_warehouse_master_rows(active_only=active_only) or []:
        rl = {str(k).lower(): v for k, v in (row.items() if hasattr(row, 'items') else [])}
        try:
            if int(rl.get('locationcode') or 0) != lc:
                continue
        except (TypeError, ValueError):
            continue
        try:
            wid = int(float(rl.get('warehouse_id') or 0))
        except (TypeError, ValueError):
            continue
        if wid <= 0:
            continue
        code = str(rl.get('warehouse_code') or '').strip().upper()
        name = str(rl.get('warehouse_name') or code).strip()
        out.append({'warehouse_id': wid, 'warehouse_code': code, 'warehouse_name': name})
    out.sort(key=lambda x: (x.get('warehouse_code') or '', x.get('warehouse_id') or 0))
    return out


def get_counter_row_by_code(countercode: Any, location_code: Optional[int]=None, db_key: str='HO') -> Dict[str, Any]:
    """One ``COUNTER`` row (lowercase keys) by code, optionally scoped to branch."""
    ensure_pos_counter_table()
    if countercode is None:
        return {}
    if not _table_exists('COUNTER', db_key=db_key):
        return {}
    cols = _get_table_columns_with_key('COUNTER', db_key) or []
    if not cols:
        return {}
    cc_col = _detect_column_with_key('COUNTER', ['COUNTERCODE', 'countercode'], db_key) or 'COUNTERCODE'
    lc_col = _detect_column_with_key('COUNTER', ['LOCATIONCODE', 'locationcode'], db_key)
    select_cols = ', '.join(cols)
    params: Dict[str, Any] = {'cc': countercode}
    where = [f'{cc_col} = :cc']
    if location_code is not None and lc_col:
        where.append(f'{lc_col} = :loc')
        params['loc'] = int(location_code)
    q = f'SELECT {select_cols} FROM COUNTER WHERE {" AND ".join(where)} AND ROWNUM = 1'
    rows = _safe_rows(q, params, db_key=db_key) or []
    if not rows and location_code is not None and lc_col:
        rows = _safe_rows(f'SELECT {select_cols} FROM COUNTER WHERE {cc_col} = :cc AND ROWNUM = 1', {'cc': countercode}, db_key=db_key) or []
    if not rows:
        return {}
    out = {str(k).lower(): v for k, v in rows[0].items()}
    wh_raw = out.get('warehouse_id')
    if wh_raw is not None and str(wh_raw).strip() != '':
        try:
            out['warehouse_id'] = int(float(wh_raw))
        except (TypeError, ValueError):
            out['warehouse_id'] = None
    else:
        out['warehouse_id'] = None
    return out


def resolve_pos_counter_warehouse(countercode: Any, location_code: int) -> Dict[str, Any]:
    """POS stock scope for a register: warehouse id/code and line ``store`` key."""
    row = get_counter_row_by_code(countercode, location_code)
    wh_id = row.get('warehouse_id')
    wh_code = str(row.get('store') or '').strip().upper()
    wh_name = ''
    if wh_id:
        try:
            wid_norm, code_from_id = _pos_counter_warehouse_store_from_id(int(wh_id), int(location_code))
            if code_from_id:
                wh_code = code_from_id
                wh_id = wid_norm
        except (TypeError, ValueError):
            pass
        wh = get_warehouse_master_by_id(int(wh_id))
        if wh:
            wh_code = str(wh.get('warehouse_code') or wh_code).strip().upper()
            wh_name = str(wh.get('warehouse_name') or wh_code).strip()
    elif wh_code:
        wh = get_warehouse_master_by_code(wh_code)
        if wh:
            try:
                wh_id = int(float(wh.get('warehouse_id') or wh.get('WAREHOUSE_ID') or 0)) or None
            except (TypeError, ValueError):
                wh_id = None
            wh_name = str(wh.get('warehouse_name') or wh_code).strip()
    if not wh_code:
        wh_code = 'STORE1'
    bin_loc_key = str(wh_id) if wh_id else wh_code
    return {
        'warehouse_id': wh_id,
        'warehouse_code': wh_code,
        'warehouse_name': wh_name,
        'store': wh_code,
        'bin_loc_key': bin_loc_key,
    }


def get_item_warehouse_stock_qty(location_code: int, warehouse_id: int, item_code: int) -> Optional[float]:
    """On-hand qty for one item in ``WAREHOUSE_STOCK``; ``None`` when table/row unavailable."""
    if not ensure_warehouse_stock_table() or not _table_exists(WAREHOUSE_STOCK_TABLE):
        return None
    try:
        lc = int(location_code)
        wid = int(warehouse_id)
        ic = int(item_code)
    except (TypeError, ValueError):
        return None
    rows = get_warehouse_stock_for_branch(lc, warehouse_id=wid, item_code=ic, include_zero=True, limit=1)
    if not rows:
        return 0.0
    try:
        return float(rows[0].get('qty') or rows[0].get('QTY') or 0)
    except (TypeError, ValueError):
        return 0.0


def _pos_counter_warehouse_store_from_id(warehouse_id: Optional[int], location_code: int) -> Tuple[Optional[int], Optional[str]]:
    """Validate warehouse belongs to branch; return (id, WAREHOUSE_CODE) for ``COUNTER.STORE``."""
    if warehouse_id is None:
        return (None, None)
    try:
        wid = int(warehouse_id)
        lc = int(location_code)
    except (TypeError, ValueError):
        return (None, None)
    if wid <= 0:
        return (None, None)
    wh = get_warehouse_master_by_id(wid)
    if not wh:
        return (None, None)
    try:
        wh_lc = int(float(wh.get('locationcode') or wh.get('LOCATIONCODE') or 0))
    except (TypeError, ValueError):
        wh_lc = 0
    if wh_lc != lc:
        return (None, None)
    code = str(wh.get('warehouse_code') or wh.get('WAREHOUSE_CODE') or '').strip().upper()[:20]
    return (wid, code or None)


def insert_pos_counter_row(*, locationcode: Any, countername: str, onlinesale: str, systemname: str, systemip: str, store: Optional[str], createdby: str, approved: str='N', warehouse_id: Optional[int]=None) -> Tuple[bool, str, Optional[int]]:
    """Insert one row into tenant ``COUNTER`` (POS setup). Uses MAX+1 style next ``COUNTERCODE``; retries on unique-key races.

    Returns ``(ok, error_message, countercode_or_none)``.
    """
    ensure_pos_counter_table()
    cols_upper = {c.upper() for c in (_get_table_columns_with_key('COUNTER') or [])}
    need = {'LOCATIONCODE', 'COUNTERCODE', 'COUNTERNAME'}
    if not need.issubset(cols_upper):
        return (False, 'COUNTER table is missing required columns (LOCATIONCODE, COUNTERCODE, COUNTERNAME).', None)
    try:
        loc = int(locationcode)
    except (TypeError, ValueError):
        return (False, 'Location code must be a number.', None)
    if loc < 0 or loc > 99:
        return (False, 'Location code must be between 0 and 99.', None)
    name = (countername or '').strip()
    if not name:
        return (False, 'Counter name is required.', None)
    name = name[:40]
    osale = (onlinesale or 'N').strip().upper()[:1]
    if osale not in ('Y', 'N'):
        osale = 'N'
    appr = (approved or 'N').strip().upper()[:1]
    if appr not in ('Y', 'N'):
        appr = 'N'
    sysname = (systemname or '').strip()[:25]
    if not sysname:
        return (False, 'System name (PC name) is required.', None)
    sysip = (systemip or '').strip()[:20]
    wid, wh_code = _pos_counter_warehouse_store_from_id(warehouse_id, loc)
    if is_location_warehouse_enabled(loc) and list_warehouses_for_location(loc):
        if not wid:
            return (False, 'Select a warehouse for this counter (branch warehouse mode is on).', None)
    st = (wh_code or (store or '').strip())[:20] or None
    cb = (createdby or '').strip()[:50]
    if not cb:
        cb = 'SYSTEM'
    sn_norm = _norm_counter_hostname(sysname)
    if pos_counter_systemname_normalized_in_use(sn_norm):
        return (False, 'System name (PC name) is already used by another counter. Each PC name must be unique.', None)
    candidates = [('LOCATIONCODE', loc), ('COUNTERCODE', None), ('COUNTERNAME', name), ('ONLINESALE', osale), ('CREATEDBY', cb), ('CREATEDDATE', datetime.now()), ('SYSTEMIP', sysip or None), ('SYSTEMNAME', sysname or None), ('APPROVED', appr), ('STORE', st), ('WAREHOUSE_ID', wid)]
    insert_cols: List[str] = []
    insert_vals: Dict[str, Any] = {}
    for col, val in candidates:
        cu = col.upper()
        if cu not in cols_upper:
            continue
        if cu == 'COUNTERCODE':
            insert_cols.append(cu)
            insert_vals[cu.lower()] = None
        else:
            insert_cols.append(cu)
            insert_vals[cu.lower()] = val
    if 'COUNTERCODE' not in insert_cols:
        return (False, 'COUNTERCODE column not found.', None)
    ph = ', '.join([f':{c.lower()}' for c in insert_cols])
    sql = f"INSERT INTO COUNTER ({', '.join(insert_cols)}) VALUES ({ph})"
    last_err = ''
    for _attempt in range(15):
        try:
            cc = int(get_next_countercode())
            insert_vals['countercode'] = cc
            if 'createddate' in insert_vals:
                insert_vals['createddate'] = datetime.now()
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute(sql, insert_vals)
                conn.commit()
            return (True, '', cc)
        except cx_Oracle.DatabaseError as e:
            last_err = str(e)
            if is_unique_constraint_violation(e):
                continue
            return (False, last_err, None)
        except Exception as e:
            return (False, str(e), None)
    return (False, last_err or 'Could not allocate a unique counter code.', None)

def fetch_counter_row_by_rowid(row_id: str, db_key: str='HO') -> Dict[str, Any]:
    """Return one ``COUNTER`` row as a dict (lowercase keys) with string ``rowid`` for URLs/forms."""
    ensure_pos_counter_table()
    rid = (row_id or '').strip()
    if not rid or not _table_exists('COUNTER', db_key=db_key):
        return {}
    columns = _get_table_columns_with_key('COUNTER', db_key)
    if not columns:
        return {}
    select_cols = ', '.join(columns)
    query = f'\n        SELECT ROWID,\n               {select_cols}\n        FROM COUNTER\n        WHERE ROWID = :rid\n    '
    rows = _safe_rows(query, {'rid': rid}, db_key=db_key)
    if not rows:
        return {}
    out = dict(rows[0])
    rv = out.get('rowid')
    if rv is not None:
        out['rowid'] = str(rv).strip()
    return out

def update_pos_counter_row(
    *,
    row_id: str,
    countername: str,
    onlinesale: str,
    systemname: str,
    systemip: str,
    store: Optional[str],
    warehouse_id: Optional[int]=None,
    db_key: str='HO',
) -> Tuple[bool, str]:
    """Update editable columns on ``COUNTER`` by ROWID (does not change ``COUNTERCODE`` / ``LOCATIONCODE``)."""
    ensure_pos_counter_table()
    rid = (row_id or '').strip()
    if not rid:
        return (False, 'Missing row reference.')
    existing = fetch_counter_row_by_rowid(rid, db_key=db_key)
    if not existing:
        return (False, 'Counter row not found.')
    try:
        ex_cc = int(existing.get('countercode'))
    except (TypeError, ValueError):
        return (False, 'Invalid existing counter code.')
    name = (countername or '').strip()
    if not name:
        return (False, 'Counter name is required.')
    name = name[:40]
    osale = (onlinesale or 'N').strip().upper()[:1]
    if osale not in ('Y', 'N'):
        osale = 'N'
    sysname = (systemname or '').strip()[:25]
    if not sysname:
        return (False, 'System name (PC name) is required.')
    sysip = (systemip or '').strip()[:20]
    try:
        loc = int(existing.get('locationcode'))
    except (TypeError, ValueError):
        loc = 0
    wid, wh_code = _pos_counter_warehouse_store_from_id(warehouse_id, loc)
    if is_location_warehouse_enabled(loc) and list_warehouses_for_location(loc):
        if not wid:
            return (False, 'Select a warehouse for this counter (branch warehouse mode is on).')
    st = (wh_code or (store or '').strip())[:20] or None
    sn_norm = _norm_counter_hostname(sysname)
    if pos_counter_systemname_normalized_in_use(sn_norm, exclude_countercode=ex_cc):
        return (False, 'System name (PC name) is already used by another counter. Each PC name must be unique.')
    cols_upper = {c.upper() for c in (_get_table_columns_with_key('COUNTER') or [])}
    set_fragments: List[str] = []
    bind: Dict[str, Any] = {'rid': rid}
    if 'COUNTERNAME' in cols_upper:
        set_fragments.append('COUNTERNAME = :countername')
        bind['countername'] = name
    if 'ONLINESALE' in cols_upper:
        set_fragments.append('ONLINESALE = :onlinesale')
        bind['onlinesale'] = osale
    if 'SYSTEMNAME' in cols_upper:
        set_fragments.append('SYSTEMNAME = :systemname')
        bind['systemname'] = sysname or None
    if 'SYSTEMIP' in cols_upper:
        set_fragments.append('SYSTEMIP = :systemip')
        bind['systemip'] = sysip or None
    if 'STORE' in cols_upper:
        set_fragments.append('STORE = :store')
        bind['store'] = st
    if 'WAREHOUSE_ID' in cols_upper:
        set_fragments.append('WAREHOUSE_ID = :warehouse_id')
        bind['warehouse_id'] = wid
    if not set_fragments:
        return (False, 'No updatable columns on COUNTER table.')
    sql = f"UPDATE COUNTER SET {', '.join(set_fragments)} WHERE ROWID = :rid"
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(sql, bind)
            conn.commit()
        return (True, '')
    except Exception as e:
        print(f'[ERROR update_pos_counter_row] {e}')
        return (False, str(e))

def delete_pos_counter_row(*, row_id: str, db_key: str='HO') -> Tuple[bool, str]:
    """Delete one ``COUNTER`` row by ROWID if no open shift exists for that location/counter."""
    ensure_pos_counter_table()
    rid = (row_id or '').strip()
    if not rid:
        return (False, 'Missing row reference.')
    existing = fetch_counter_row_by_rowid(rid, db_key=db_key)
    if not existing:
        return (False, 'Counter row not found.')
    try:
        cc = int(existing.get('countercode'))
    except (TypeError, ValueError):
        return (False, 'Invalid counter code on row.')
    lc_raw = existing.get('locationcode')
    lc: Optional[int] = None
    if lc_raw is not None:
        try:
            lc = int(lc_raw)
        except (TypeError, ValueError):
            lc = None
    if lc is not None:
        op = find_open_counter_operation(lc, cc, db_key=None)
        if op:
            return (False, 'Cannot delete: this counter has an open shift. Close it in Counter Operations first.')
    sql = 'DELETE FROM COUNTER WHERE ROWID = :rid'
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(sql, {'rid': rid})
                if cur.rowcount == 0:
                    return (False, 'Counter row was not deleted (not found).')
            conn.commit()
        return (True, '')
    except Exception as e:
        print(f'[ERROR delete_pos_counter_row] {e}')
        return (False, str(e))

def get_counter_name_by_code(countercode: Any, db_key: str='HO', location_code: Optional[int]=None) -> str:
    """Return ``COUNTERNAME`` from ``COUNTER`` for ``countercode``.

    When ``location_code`` is set and ``LOCATIONCODE`` exists on ``COUNTER``, rows are filtered
    by branch first (matches POS Counter Operations). If no row matches, falls back to
    counter-code-only lookup for legacy schemas.
    ``db_key`` is retained for API compatibility; the active connection from ``_get_connection()`` is used.
    """
    ensure_pos_counter_table()
    if countercode is None:
        return ''
    if not _table_exists('COUNTER', db_key=db_key):
        return ''
    counter_col = _detect_column_with_key('COUNTER', ['COUNTERCODE', 'countercode', 'CODE', 'code', 'COUNTER_CODE', 'counter_code'], db_key)
    counter_name_col = _detect_column_with_key('COUNTER', ['COUNTERNAME', 'countername', 'NAME', 'name', 'COUNTER_NAME', 'counter_name'], db_key)
    if not counter_col or not counter_name_col:
        return ''
    locationcode_col = _detect_column_with_key('COUNTER', ['LOCATIONCODE', 'locationcode', 'LOCATION_CODE', 'location_code'], db_key)

    def _run_pick(rows: List[Dict[str, Any]]) -> str:
        if not rows or not rows[0]:
            return ''
        name = rows[0].get('countername') or (list(rows[0].values())[0] if rows[0] else None)
        return str(name).strip() if name else ''

    try:
        if location_code is not None and locationcode_col:
            query_lc = f'\n            SELECT {counter_name_col} AS countername\n            FROM COUNTER\n            WHERE {counter_col} = :countercode AND {locationcode_col} = :location_code\n        '
            _, rows_lc = _fetch_rows_with_key(db_key, query_lc, {'countercode': countercode, 'location_code': int(location_code)})
            picked = _run_pick(rows_lc)
            if picked:
                return picked
        query = f'\n        SELECT {counter_name_col} AS countername\n        FROM COUNTER\n        WHERE {counter_col} = :countercode\n    '
        _, rows = _fetch_rows_with_key(db_key, query, {'countercode': countercode})
        return _run_pick(rows)
    except Exception as e:
        print(f'[ERROR get_counter_name_by_code] {e}')
    return ''

_COUNTER_OPERATIONS_PK_CACHE: Dict[str, Tuple[str, ...]] = {}


def _counter_operations_pk_columns(db_key: Optional[str] = None) -> Tuple[str, ...]:
    """Primary-key columns for tenant ``COUNTEROPERATIONS`` (legacy RFIM: location+counter only)."""
    cache_key = (db_key or '__default__').strip() or '__default__'
    cached = _COUNTER_OPERATIONS_PK_CACHE.get(cache_key)
    if cached is not None:
        return cached
    cols: Tuple[str, ...] = ()
    try:
        rows = _safe_rows(
            """
            SELECT cc.column_name
            FROM user_constraints c
            JOIN user_cons_columns cc ON c.constraint_name = cc.constraint_name
            WHERE c.table_name = 'COUNTEROPERATIONS' AND c.constraint_type = 'P'
            ORDER BY cc.position
            """,
            {},
            db_key=db_key,
        ) or []
        if rows:
            cols = tuple(str(r.get('column_name') or '').strip().upper() for r in rows if r.get('column_name'))
    except Exception as e:
        print(f'[WARN _counter_operations_pk_columns] {e}')
    if not cols:
        cols = ('LOCATIONCODE', 'COUNTERCODE', 'POSDATE', 'SHIFTCODE')
    _COUNTER_OPERATIONS_PK_CACHE[cache_key] = cols
    return cols


def _counter_operations_legacy_pk(db_key: Optional[str] = None) -> bool:
    """True when PK is legacy ``(LOCATIONCODE, COUNTERCODE)`` — one row per counter."""
    pk = _counter_operations_pk_columns(db_key=db_key)
    return pk == ('LOCATIONCODE', 'COUNTERCODE')


def _counter_operations_table_columns(db_key: Optional[str] = None) -> frozenset:
    ensure_counter_operations_table()
    cols = _get_table_columns_with_key('COUNTEROPERATIONS', db_key) or []
    return frozenset(str(c).upper() for c in cols)


def _counter_operations_pos_date_select_sql(*, alias: str = '', db_key: Optional[str] = None) -> str:
    """SQL expression for shift POS date (``POSDATE`` and/or legacy ``DATEOFOPEN``)."""
    cols = _counter_operations_table_columns(db_key)
    pre = f'{alias}.' if alias else ''
    if 'POSDATE' in cols and 'DATEOFOPEN' in cols:
        return f'NVL({pre}POSDATE, {pre}DATEOFOPEN)'
    if 'POSDATE' in cols:
        return f'{pre}POSDATE'
    if 'DATEOFOPEN' in cols:
        return f'{pre}DATEOFOPEN'
    return f'{pre}POSDATE'


def _counter_operations_pos_date_set_sql(cols: frozenset) -> List[str]:
    """UPDATE SET fragments so legacy ``DATEOFOPEN`` stays in sync with ``POSDATE``."""
    parts: List[str] = []
    if 'POSDATE' in cols:
        parts.append('POSDATE = TRUNC(:pd)')
    if 'DATEOFOPEN' in cols:
        parts.append('DATEOFOPEN = TRUNC(:pd)')
    return parts


def _counter_operations_open_insert_sql(cols: frozenset) -> str:
    """Build INSERT for open shift, including legacy NOT NULL columns when present."""
    insert_cols = ['LOCATIONCODE', 'COUNTERCODE', 'SHIFTCODE', 'SLNO', 'OPENFLAG', 'OPENEDBY']
    insert_vals = [':lc', ':cc', ':sc', ':slno', "'O'", ':ob']
    if 'POSDATE' in cols:
        insert_cols.append('POSDATE')
        insert_vals.append('TRUNC(:pd)')
    if 'DATEOFOPEN' in cols:
        insert_cols.append('DATEOFOPEN')
        insert_vals.append('TRUNC(:pd)')
    if 'OPENEDDATE' in cols:
        insert_cols.append('OPENEDDATE')
        insert_vals.append('TRUNC(:ots)')
    if 'OPENEDTIME' in cols:
        insert_cols.append('OPENEDTIME')
        insert_vals.append(':ots')
    for close_col in ('CLOSEDBY', 'CLOSEDDATE', 'CLOSEDTIME'):
        if close_col in cols:
            insert_cols.append(close_col)
            insert_vals.append('NULL')
    if 'CASHIERCODE' in cols:
        insert_cols.append('CASHIERCODE')
        insert_vals.append(':cashier_code')
    if 'POSFLAG' in cols:
        insert_cols.append('POSFLAG')
        insert_vals.append("'Y'")
    return (
        f"INSERT INTO COUNTEROPERATIONS ({', '.join(insert_cols)}) "
        f"VALUES ({', '.join(insert_vals)})"
    )


def _counter_operations_legacy_open_update_fragments(cols: frozenset) -> List[str]:
    """UPDATE SET fragments for legacy RFIM columns on open shift."""
    parts: List[str] = []
    if 'CASHIERCODE' in cols:
        parts.append('CASHIERCODE = :cashier_code')
    if 'POSFLAG' in cols:
        parts.append("POSFLAG = 'Y'")
    return parts


def _resolve_counter_operations_cashier_code(opened_by: str, cashier_code: Optional[int] = None) -> int:
    """Legacy ``CASHIERCODE`` (employee number); defaults to 0 when unknown."""
    if cashier_code is not None:
        try:
            return max(0, int(cashier_code))
        except (TypeError, ValueError):
            pass
    user = (opened_by or '').strip()
    if user:
        try:
            ec = get_user_employeecode(user)
            if ec:
                return max(0, int(str(ec).strip()))
        except (TypeError, ValueError):
            pass
    return 0


def _migrate_counter_operations_pk_if_legacy(db_key: Optional[str] = None) -> bool:
    """Upgrade legacy PK (location+counter) to (location+counter+posdate+shift) so history rows are kept."""
    if not _table_exists('COUNTEROPERATIONS', db_key=db_key):
        return False
    if not _counter_operations_legacy_pk(db_key=db_key):
        return False
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE COUNTEROPERATIONS
                    SET SHIFTCODE = NVL(SHIFTCODE, 1)
                    WHERE SHIFTCODE IS NULL
                    """
                )
                cur.execute(
                    """
                    SELECT 1 FROM (
                        SELECT LOCATIONCODE, COUNTERCODE, TRUNC(POSDATE) AS pd, SHIFTCODE, COUNT(*) AS cnt
                        FROM COUNTEROPERATIONS
                        GROUP BY LOCATIONCODE, COUNTERCODE, TRUNC(POSDATE), SHIFTCODE
                        HAVING COUNT(*) > 1
                    ) WHERE ROWNUM = 1
                    """
                )
                if cur.fetchone():
                    print('[WARN _migrate_counter_operations_pk_if_legacy] duplicate keys; keeping legacy PK')
                    return False
                cur.execute(
                    """
                    SELECT constraint_name FROM user_constraints
                    WHERE table_name = 'COUNTEROPERATIONS' AND constraint_type = 'P'
                    """
                )
                pk_row = cur.fetchone()
                if not pk_row or not pk_row[0]:
                    return False
                pk_name = str(pk_row[0]).strip()
                cur.execute(f'ALTER TABLE COUNTEROPERATIONS DROP CONSTRAINT "{pk_name}"')
                cur.execute(
                    """
                    ALTER TABLE COUNTEROPERATIONS ADD CONSTRAINT PK_COUNTEROPERATIONS
                    PRIMARY KEY (LOCATIONCODE, COUNTERCODE, POSDATE, SHIFTCODE)
                    """
                )
            conn.commit()
        _COUNTER_OPERATIONS_PK_CACHE.clear()
        _TABLE_COLUMNS_CACHE.pop('COUNTEROPERATIONS', None)
        print('[INFO _migrate_counter_operations_pk_if_legacy] upgraded COUNTEROPERATIONS primary key')
        return True
    except Exception as e:
        print(f'[WARN _migrate_counter_operations_pk_if_legacy] {e}')
        return False


def ensure_counter_operations_hist_table(_db_key_ignored: Any = None) -> None:
    """Archive table for legacy-PK overwrites (preserves closed shift rows before open replaces them)."""
    key = 'COUNTEROPERATIONS_HIST'
    if _table_exists(key):
        return
    create_sql = """
        CREATE TABLE COUNTEROPERATIONS_HIST (
            ARCHIVE_ID     NUMBER(12) NOT NULL,
            LOCATIONCODE   NUMBER(2) NOT NULL,
            COUNTERCODE    NUMBER(3) NOT NULL,
            POSDATE        DATE NOT NULL,
            SHIFTCODE      NUMBER(2) NOT NULL,
            SLNO           NUMBER(8),
            OPENFLAG       CHAR(1) DEFAULT 'C' NOT NULL,
            OPENEDBY       VARCHAR2(20 BYTE),
            OPENEDDATE     DATE,
            OPENEDTIME     TIMESTAMP(6),
            CLOSEDBY       VARCHAR2(20 BYTE),
            CLOSEDDATE     DATE,
            CLOSEDTIME     TIMESTAMP(6),
            ARCHIVED_AT    TIMESTAMP(6) NOT NULL,
            CONSTRAINT PK_COUNTEROPERATIONS_HIST PRIMARY KEY (ARCHIVE_ID)
        ) TABLESPACE USERS
    """
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT COUNT(*) FROM user_tables WHERE table_name = 'COUNTEROPERATIONS_HIST'")
                exists = int((cur.fetchone() or [0])[0] or 0) > 0
                if not exists:
                    try:
                        cur.execute(create_sql)
                    except cx_Oracle.DatabaseError as e:
                        if 'ORA-00955' not in str(e):
                            raise
            conn.commit()
        _TABLE_EXISTS_CACHE.pop(key, None)
    except Exception as e:
        print(f'[WARN ensure_counter_operations_hist_table] {e}')


def _archive_counter_operation_row_cur(cur, location_code: int, counter_code: int) -> None:
    """Copy the live counter row to COUNTEROPERATIONS_HIST before legacy overwrite."""
    ensure_counter_operations_hist_table()
    if not _table_exists('COUNTEROPERATIONS_HIST'):
        return
    cur.execute('SELECT NVL(MAX(ARCHIVE_ID), 0) + 1 FROM COUNTEROPERATIONS_HIST')
    next_id = int((cur.fetchone() or [1])[0] or 1)
    now_ts = datetime.now()
    cur.execute(
        """
        INSERT INTO COUNTEROPERATIONS_HIST (
            ARCHIVE_ID, LOCATIONCODE, COUNTERCODE, POSDATE, SHIFTCODE, SLNO,
            OPENFLAG, OPENEDBY, OPENEDDATE, OPENEDTIME, CLOSEDBY, CLOSEDDATE, CLOSEDTIME, ARCHIVED_AT
        )
        SELECT :aid, LOCATIONCODE, COUNTERCODE, POSDATE, SHIFTCODE, SLNO,
               OPENFLAG, OPENEDBY, OPENEDDATE, OPENEDTIME, CLOSEDBY, CLOSEDDATE, CLOSEDTIME, :ats
        FROM COUNTEROPERATIONS
        WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc
        """,
        {'aid': next_id, 'ats': now_ts, 'lc': int(location_code), 'cc': int(counter_code)},
    )


def ensure_counter_operations_table(_db_key_ignored: Any=None) -> None:
    """Create tenant ``COUNTEROPERATIONS`` for POS shift open/close (TABLESPACE USERS); add missing columns."""
    key = 'COUNTEROPERATIONS'
    cols_needed: Tuple[Tuple[str, str], ...] = (
        ('LOCATIONCODE', 'NUMBER(2)'),
        ('COUNTERCODE', 'NUMBER(3)'),
        ('POSDATE', 'DATE'),
        ('SHIFTCODE', 'NUMBER(2)'),
        ('SLNO', 'NUMBER(8)'),
        ('OPENFLAG', "CHAR(1) DEFAULT 'C'"),
        ('OPENEDBY', 'VARCHAR2(20 BYTE)'),
        ('OPENEDDATE', 'DATE'),
        ('OPENEDTIME', 'TIMESTAMP(6)'),
        ('CLOSEDBY', 'VARCHAR2(20 BYTE)'),
        ('CLOSEDDATE', 'DATE'),
        ('CLOSEDTIME', 'TIMESTAMP(6)'),
    )
    needed_names = frozenset(c[0] for c in cols_needed)
    if _table_exists(key):
        cur_cols = frozenset(_get_table_columns_with_key(key) or [])
        if needed_names.issubset(cur_cols):
            _migrate_counter_operations_pk_if_legacy()
            ensure_counter_operations_hist_table()
            return
    create_sql = "\n        CREATE TABLE COUNTEROPERATIONS (\n            LOCATIONCODE  NUMBER(2) NOT NULL,\n            COUNTERCODE   NUMBER(3) NOT NULL,\n            POSDATE       DATE NOT NULL,\n            SHIFTCODE     NUMBER(2) NOT NULL,\n            SLNO          NUMBER(8),\n            OPENFLAG      CHAR(1) DEFAULT 'C' NOT NULL,\n            OPENEDBY      VARCHAR2(20 BYTE),\n            OPENEDDATE    DATE,\n            OPENEDTIME    TIMESTAMP(6),\n            CLOSEDBY      VARCHAR2(20 BYTE),\n            CLOSEDDATE    DATE,\n            CLOSEDTIME    TIMESTAMP(6),\n            CONSTRAINT PK_COUNTEROPERATIONS PRIMARY KEY (LOCATIONCODE, COUNTERCODE, POSDATE, SHIFTCODE)\n        ) TABLESPACE USERS\n    "
    changed = False
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) FROM user_tables WHERE table_name = 'COUNTEROPERATIONS'")
            exists = int((cur.fetchone() or [0])[0] or 0) > 0
            if not exists:
                try:
                    cur.execute(create_sql)
                    changed = True
                except cx_Oracle.DatabaseError as e:
                    msg = str(e)
                    if 'ORA-00955' not in msg:
                        raise
                    changed = True
            cur.execute("SELECT column_name FROM user_tab_columns WHERE table_name = 'COUNTEROPERATIONS'")
            have = {row[0].upper() for row in cur.fetchall()}
            for col_name, col_type in cols_needed:
                if col_name not in have:
                    cur.execute(f'ALTER TABLE COUNTEROPERATIONS ADD ({col_name} {col_type})')
                    changed = True
                    have.add(col_name)
            if 'POSDATE' in have and 'DATEOFOPEN' in have:
                try:
                    cur.execute(
                        'UPDATE COUNTEROPERATIONS SET DATEOFOPEN = TRUNC(POSDATE) '
                        'WHERE DATEOFOPEN IS NULL AND POSDATE IS NOT NULL'
                    )
                    cur.execute(
                        'UPDATE COUNTEROPERATIONS SET POSDATE = TRUNC(DATEOFOPEN) '
                        'WHERE POSDATE IS NULL AND DATEOFOPEN IS NOT NULL'
                    )
                except Exception as _e_sync:
                    print(f'[WARN ensure_counter_operations_table POSDATE/DATEOFOPEN sync] {_e_sync}')
            try:
                cur.execute("\n                    MERGE INTO COUNTEROPERATIONS t\n                    USING (\n                        SELECT ROWID AS rid,\n                               ROW_NUMBER() OVER (PARTITION BY LOCATIONCODE ORDER BY ROWID) AS rn\n                        FROM COUNTEROPERATIONS\n                        WHERE SLNO IS NULL\n                    ) s ON (t.ROWID = s.rid)\n                    WHEN MATCHED THEN UPDATE SET t.SLNO = s.rn\n                    ")
            except Exception as _e_merge:
                print(f'[WARN ensure_counter_operations_table SLNO backfill] {_e_merge}')
        conn.commit()
    if changed:
        _TABLE_EXISTS_CACHE.pop(key, None)
        _TABLE_COLUMNS_CACHE.pop(key, None)
        _COUNTER_OPERATIONS_PK_CACHE.clear()
    if _table_exists(key):
        _migrate_counter_operations_pk_if_legacy()
        ensure_counter_operations_hist_table()

def list_pos_counters_for_location(location_code: int, db_key: Optional[str]=None) -> List[Dict[str, Any]]:
    """Counters registered in ``COUNTER`` for the given location (for POS Counter Operations UI)."""
    ensure_pos_counter_table()
    rows = get_system_config_list(db_key or 'HO')
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        rl = {str(k).lower(): v for k, v in (r.items() if hasattr(r, 'items') else [])}
        lc = rl.get('locationcode')
        if 'locationcode' in rl:
            try:
                if lc is not None and int(lc) != int(location_code):
                    continue
            except (TypeError, ValueError):
                continue
        cc = rl.get('countercode')
        nm = rl.get('countername') or ''
        sn = rl.get('systemname')
        out.append({'countercode': cc, 'countername': str(nm).strip(), 'locationcode': location_code, 'systemname': str(sn).strip() if sn is not None else ''})
    def _sort_key(x: Dict[str, Any]) -> Tuple[Any, ...]:
        c = x.get('countercode')
        try:
            return (0, int(c))
        except (TypeError, ValueError):
            return (1, str(c))

    out.sort(key=_sort_key)
    return out

def find_counter_by_systemname(hostname: str, location_codes: List[int]) -> Optional[Dict[str, Any]]:
    """Return first ``COUNTER`` row for any candidate branch whose ``SYSTEMNAME`` matches ``hostname``.

    Uses ``list_pos_counters_for_location`` per ``location_codes`` entry (tenant connection).
    """
    h = _norm_counter_hostname(hostname)
    if not h:
        return None
    visited: Set[int] = set()
    for lc in location_codes:
        try:
            key = int(lc)
        except (TypeError, ValueError):
            continue
        if key in visited:
            continue
        visited.add(key)
        try:
            rows = list_pos_counters_for_location(key, db_key=None)
        except Exception:
            continue
        for row in rows or []:
            sn = _norm_counter_hostname(row.get('systemname'))
            if not sn or sn != h:
                continue
            cc = row.get('countercode')
            try:
                cci = int(cc)
            except (TypeError, ValueError):
                continue
            return {'countercode': cci, 'countername': str(row.get('countername') or '').strip(), 'locationcode': key}
    return None

def list_counter_operations_recent(location_code: int, limit: int = 500, db_key: Optional[str]=None) -> List[Dict[str, Any]]:
    """Recent ``COUNTEROPERATIONS`` rows for a location (newest activity first), including archived history."""
    ensure_counter_operations_table()
    if not _table_exists('COUNTEROPERATIONS', db_key=db_key):
        return []
    lim = max(1, min(int(limit), 2000))
    cols = """
            SLNO, LOCATIONCODE, COUNTERCODE, POSDATE, SHIFTCODE, OPENFLAG,
            OPENEDBY, OPENEDDATE, OPENEDTIME, CLOSEDBY, CLOSEDDATE, CLOSEDTIME
    """
    order_by = """
            ORDER BY NVL(CLOSEDTIME, OPENEDTIME) DESC NULLS LAST,
                     POSDATE DESC, SHIFTCODE DESC, SLNO DESC
    """
    params: Dict[str, Any] = {'lc': int(location_code), 'lim': lim}
    if _table_exists('COUNTEROPERATIONS_HIST', db_key=db_key):
        q = f"""
        SELECT * FROM (
            SELECT {cols} FROM (
                SELECT {cols} FROM COUNTEROPERATIONS WHERE LOCATIONCODE = :lc
                UNION ALL
                SELECT {cols} FROM COUNTEROPERATIONS_HIST WHERE LOCATIONCODE = :lc
            ) combined
            {order_by}
        ) WHERE ROWNUM <= :lim
        """
    else:
        q = f"""
        SELECT * FROM (
            SELECT {cols}
            FROM COUNTEROPERATIONS
            WHERE LOCATIONCODE = :lc
            {order_by}
        ) WHERE ROWNUM <= :lim
        """
    return _safe_rows(q, params, db_key=db_key) or []

def get_latest_closed_pos_date_for_counter(
    location_code: int,
    counter_code: int,
    *,
    db_key: Optional[str] = None,
) -> Optional[date]:
    """Latest POSDATE among closed shifts (OPENFLAG C) for this location+counter."""
    ensure_counter_operations_table()
    if not _table_exists('COUNTEROPERATIONS', db_key=db_key):
        return None
    try:
        lc = int(location_code)
        cc = int(counter_code)
    except (TypeError, ValueError):
        return None
    pd_sel = _counter_operations_pos_date_select_sql(db_key=db_key)
    if _table_exists('COUNTEROPERATIONS_HIST', db_key=db_key):
        q = f"""
            SELECT MAX(TRUNC(pd)) AS max_pd FROM (
                SELECT {pd_sel} AS pd FROM COUNTEROPERATIONS
                WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc AND TRIM(OPENFLAG) = 'C'
                UNION ALL
                SELECT POSDATE AS pd FROM COUNTEROPERATIONS_HIST
                WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc AND TRIM(OPENFLAG) = 'C'
            )
        """
    else:
        q = f"""
            SELECT MAX(TRUNC({pd_sel})) AS max_pd
            FROM COUNTEROPERATIONS
            WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc
              AND TRIM(OPENFLAG) = 'C'
        """
    rows = _safe_rows(q, {'lc': lc, 'cc': cc}, db_key=db_key) or []
    if not rows:
        return None
    r0 = rows[0]
    raw = r0.get('max_pd') if hasattr(r0, 'get') else (r0[0] if r0 else None)
    if raw is None:
        return None
    if hasattr(raw, 'date') and callable(raw.date):
        try:
            return raw.date()
        except Exception:
            pass
    try:
        if hasattr(raw, 'strftime'):
            return datetime.strptime(str(raw)[:10], '%Y-%m-%d').date()
    except (TypeError, ValueError):
        pass
    s = str(raw).strip()
    if len(s) >= 10:
        try:
            return datetime.strptime(s[:10], '%Y-%m-%d').date()
        except ValueError:
            pass
    return None


