def resolve_pos_settlement_default_date(
    location_code: int,
    *,
    db_key: Optional[str] = None,
) -> date:
    """Default From/To for POS settlement: latest closed POS day, else latest bill date, else today."""
    closed = get_latest_closed_pos_date_for_location(location_code, db_key=db_key)
    if closed is not None:
        return closed
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return date.today()
    extra = ''
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    if 'DELFLAG' in cols_u:
        extra += " AND NVL(DELFLAG, 'N') <> 'Y'"
    if 'BILLSTATUS' in cols_u:
        extra += " AND NVL(BILLSTATUS, ' ') <> 'V'"
    rows = _safe_rows(
        f"""
        SELECT MAX(TRUNC(BILLDATE)) AS max_bd
        FROM BILLHDR
        WHERE LOCATIONCODE = :lc{extra}
        """,
        {'lc': lc},
        db_key=db_key,
    ) or []
    if rows:
        r0 = rows[0]
        raw = r0.get('max_bd') if hasattr(r0, 'get') else (r0[0] if r0 else None)
        if raw is not None:
            if hasattr(raw, 'date') and callable(raw.date):
                try:
                    return raw.date()
                except Exception:
                    pass
            try:
                if hasattr(raw, 'strftime'):
                    return datetime.strptime(str(raw)[:10], '%Y-%m-%d').date()
            except (TypeError, ValueError):
                pass
            s = str(raw).strip()
            if len(s) >= 10:
                try:
                    return datetime.strptime(s[:10], '%Y-%m-%d').date()
                except ValueError:
                    pass
    return date.today()


def _pos_date_display(value: Any) -> str:
    raw = value.isoformat() if hasattr(value, 'isoformat') and callable(value.isoformat) else str(value or '')
    try:
        return datetime.strptime(str(raw)[:10], '%Y-%m-%d').strftime('%d/%b/%Y')
    except ValueError:
        return str(raw)[:10]


def _counter_codes_for_pos_closed_check(
    location_code: int,
    from_date: date,
    to_date: date,
    *,
    db_key: Optional[str] = None,
) -> List[int]:
    """Counter codes to validate when no single counter is selected."""
    codes: Set[int] = set()
    for row in list_pos_counters_for_location(location_code, db_key) or []:
        try:
            cc = int(row.get('countercode'))
        except (TypeError, ValueError):
            continue
        if cc > 0:
            codes.add(cc)
    params = {'lc': int(location_code), 'fd': from_date, 'td': to_date}
    if _table_exists('COUNTEROPERATIONS', db_key=db_key):
        for row in _safe_rows(
            """
            SELECT DISTINCT COUNTERCODE AS cc FROM COUNTEROPERATIONS
            WHERE LOCATIONCODE = :lc
              AND TRUNC(POSDATE) >= TRUNC(:fd) AND TRUNC(POSDATE) <= TRUNC(:td)
            """,
            params,
            db_key=db_key,
        ) or []:
            try:
                cc = int(row.get('cc'))
            except (TypeError, ValueError):
                continue
            if cc > 0:
                codes.add(cc)
    hdr_cols = {str(c or '').upper() for c in (_get_table_columns('BILLHDR') or [])}
    if _table_exists('BILLHDR', db_key=db_key) and 'COUNTERCODE' in hdr_cols and 'BILLDATE' in hdr_cols:
        bill_where = [
            'LOCATIONCODE = :lc',
            'TRUNC(BILLDATE) >= TRUNC(:fd)',
            'TRUNC(BILLDATE) <= TRUNC(:td)',
        ]
        if 'DELFLAG' in hdr_cols:
            bill_where.append("NVL(DELFLAG, 'N') NOT IN ('Y', 'y')")
        if 'BILLSTATUS' in hdr_cols:
            bill_where.append("NVL(BILLSTATUS, ' ') <> 'V'")
        for row in _safe_rows(
            f"SELECT DISTINCT COUNTERCODE AS cc FROM BILLHDR WHERE {' AND '.join(bill_where)}",
            params,
            db_key=db_key,
        ) or []:
            try:
                cc = int(row.get('cc'))
            except (TypeError, ValueError):
                continue
            if cc > 0:
                codes.add(cc)
    return sorted(codes)


def _validate_one_counter_pos_dates_closed(
    location_code: int,
    counter_code: int,
    from_date: date,
    to_date: date,
    *,
    shift_code: Optional[int] = None,
    db_key: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Return unclosed POS date rows for one counter."""
    lc = int(location_code)
    cc = int(counter_code)
    sc = shift_code
    hdr_cols = {str(c or '').upper() for c in (_get_table_columns('BILLHDR') or [])}
    unclosed: List[Dict[str, Any]] = []
    d = from_date
    while d <= to_date:
        params: Dict[str, Any] = {'lc': lc, 'cc': cc, 'pd': d}
        shift_sql = ''
        if sc is not None:
            shift_sql = ' AND SHIFTCODE = :sc'
            params['sc'] = sc
        open_rows = _safe_rows(
            f"""
            SELECT SHIFTCODE FROM COUNTEROPERATIONS
            WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc AND TRUNC(POSDATE) = TRUNC(:pd)
              AND TRIM(OPENFLAG) IN ('O', 'Y'){shift_sql}
            """,
            params,
            db_key=db_key,
        ) or []
        if open_rows:
            unclosed.append({'counter_code': cc, 'pos_date': d.isoformat(), 'reason': 'open'})
            d += timedelta(days=1)
            continue
        closed_rows = _safe_rows(
            f"""
            SELECT 1 AS ok FROM COUNTEROPERATIONS
            WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc AND TRUNC(POSDATE) = TRUNC(:pd)
              AND TRIM(OPENFLAG) = 'C'{shift_sql}
            """,
            params,
            db_key=db_key,
        ) or []
        if not closed_rows and 'BILLNO' in hdr_cols and 'COUNTERCODE' in hdr_cols:
            bill_where = [
                'LOCATIONCODE = :lc',
                'COUNTERCODE = :cc',
                'TRUNC(BILLDATE) = TRUNC(:pd)',
            ]
            if 'DELFLAG' in hdr_cols:
                bill_where.append("NVL(DELFLAG, 'N') NOT IN ('Y', 'y')")
            if 'BILLSTATUS' in hdr_cols:
                bill_where.append("NVL(BILLSTATUS, ' ') <> 'V'")
            if sc is not None and 'SHIFTCODE' in hdr_cols:
                bill_where.append('SHIFTCODE = :sc')
            bill_rows = _safe_rows(
                f"SELECT 1 AS ok FROM BILLHDR WHERE {' AND '.join(bill_where)} AND ROWNUM = 1",
                params,
                db_key=db_key,
            ) or []
            if bill_rows:
                unclosed.append({'counter_code': cc, 'pos_date': d.isoformat(), 'reason': 'not_closed'})
        d += timedelta(days=1)
    return unclosed


def validate_pos_counter_dates_closed_for_sales_load(
    location_code: int,
    counter_code: Optional[int],
    from_date: Any,
    to_date: Any,
    *,
    shift_code: Optional[int] = None,
    db_key: Optional[str] = None,
) -> Dict[str, Any]:
    """Ensure POS date(s) are shift-closed in Counter Operations before loading POS sales."""
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return {'ok': False, 'error': 'Invalid location.'}
    cc_filter: Optional[int] = None
    if counter_code is not None and str(counter_code).strip() != '':
        try:
            cc_val = int(counter_code)
            if cc_val > 0:
                cc_filter = cc_val
        except (TypeError, ValueError):
            cc_filter = None
    fd = from_date.date() if hasattr(from_date, 'date') and callable(from_date.date) else from_date
    td = to_date.date() if hasattr(to_date, 'date') and callable(to_date.date) else to_date
    if fd is None and td is None:
        fd = td = date.today()
    elif fd is None:
        fd = td
    elif td is None:
        td = fd
    if fd > td:
        fd, td = td, fd
    sc: Optional[int] = None
    if shift_code is not None and str(shift_code).strip() != '':
        try:
            sc_val = int(shift_code)
            if sc_val > 0:
                sc = sc_val
        except (TypeError, ValueError):
            sc = None
    ensure_counter_operations_table()
    if not _table_exists('COUNTEROPERATIONS', db_key=db_key):
        return {'ok': True, 'valid': True, 'counter_code': cc_filter, 'unclosed_dates': [], 'unclosed_items': []}
    counter_codes = [cc_filter] if cc_filter is not None else _counter_codes_for_pos_closed_check(lc, fd, td, db_key=db_key)
    if not counter_codes:
        return {'ok': True, 'valid': True, 'counter_code': cc_filter, 'unclosed_dates': [], 'unclosed_items': []}
    unclosed_items: List[Dict[str, Any]] = []
    for cc in counter_codes:
        unclosed_items.extend(
            _validate_one_counter_pos_dates_closed(lc, cc, fd, td, shift_code=sc, db_key=db_key)
        )
    if unclosed_items:
        lines: List[str] = []
        for item in unclosed_items[:25]:
            pd_disp = _pos_date_display(item.get('pos_date'))
            lines.append(f'POS date {pd_disp} is not closed for Counter {item.get("counter_code")}.')
        if len(unclosed_items) > 25:
            lines.append(f'... and {len(unclosed_items) - 25} more.')
        msg = '\n'.join(lines)
        return {
            'ok': True,
            'valid': False,
            'counter_code': cc_filter,
            'unclosed_dates': unclosed_items,
            'unclosed_items': unclosed_items,
            'message': msg,
        }
    return {'ok': True, 'valid': True, 'counter_code': cc_filter, 'unclosed_dates': [], 'unclosed_items': []}


def find_open_counter_operation(location_code: int, counter_code: int, db_key: Optional[str]=None) -> Optional[Dict[str, Any]]:
    """Return the open row (OPENFLAG O = open; legacy Y still treated as open) for location+counter if any."""
    ensure_counter_operations_table()
    if not _table_exists('COUNTEROPERATIONS', db_key=db_key):
        return None
    pd_sel = _counter_operations_pos_date_select_sql(db_key=db_key)
    rows = _safe_rows(
        f"""
        SELECT SLNO, LOCATIONCODE, COUNTERCODE, {pd_sel} AS POSDATE, SHIFTCODE, OPENFLAG,
               OPENEDBY, OPENEDDATE, OPENEDTIME, CLOSEDBY, CLOSEDDATE, CLOSEDTIME
        FROM COUNTEROPERATIONS
        WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc
          AND TRIM(OPENFLAG) IN ('O', 'Y')
        ORDER BY NVL(OPENEDTIME, CAST(OPENEDDATE AS TIMESTAMP)) DESC NULLS LAST
        """,
        {'lc': int(location_code), 'cc': int(counter_code)},
        db_key=db_key,
    )
    return rows[0] if rows else None

def open_pos_counter_operation(*, location_code: int, counter_code: int, pos_date: date, shift_code: int, opened_by: str, cashier_code: Optional[int] = None, db_key: Optional[str]=None) -> Tuple[bool, str]:
    """Open shift: one OPENFLAG=O per counter per location; PK is (location, counter, POSDATE, SHIFTCODE). Legacy Y counts as open."""
    ensure_counter_operations_table()
    ensure_pos_counter_table()
    _migrate_counter_operations_pk_if_legacy(db_key=db_key)
    if not _table_exists('COUNTEROPERATIONS', db_key=db_key):
        return (False, 'COUNTEROPERATIONS table not available.')
    ob = (opened_by or '').strip()[:20] or 'SYSTEM'
    try:
        lc = int(location_code)
        cc = int(counter_code)
        sc = int(shift_code)
    except (TypeError, ValueError):
        return (False, 'Invalid location, counter, or shift code.')
    if sc < 0 or sc > 99:
        return (False, 'Shift code must be between 0 and 99.')
    if not isinstance(pos_date, date):
        return (False, 'POS date is required.')
    dup_open = _safe_rows("\n        SELECT 1 FROM COUNTEROPERATIONS\n        WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc\n          AND TRIM(OPENFLAG) IN ('O', 'Y')\n        ", {'lc': lc, 'cc': cc}, db_key=db_key)
    if dup_open:
        return (False, 'This counter already has an open shift. Close it first.')
    legacy_pk = _counter_operations_legacy_pk(db_key=db_key)
    pd_sel = _counter_operations_pos_date_select_sql(db_key=db_key)
    if legacy_pk:
        existing = _safe_rows(
            f"""
            SELECT OPENFLAG, SLNO, {pd_sel} AS POSDATE, SHIFTCODE
            FROM COUNTEROPERATIONS
            WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc
            """,
            {'lc': lc, 'cc': cc},
            db_key=db_key,
        )
    else:
        existing = _safe_rows(
            f"""
            SELECT OPENFLAG, SLNO FROM COUNTEROPERATIONS
            WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc
              AND TRUNC({pd_sel}) = TRUNC(:pd) AND SHIFTCODE = :sc
            """,
            {'lc': lc, 'cc': cc, 'pd': pos_date, 'sc': sc},
            db_key=db_key,
        )
    reopen_closed_slot = False
    if existing:
        r0l = {str(k).lower(): v for k, v in (existing[0].items() if hasattr(existing[0], 'items') else [])}
        fl0 = str(r0l.get('openflag') or 'C').strip().upper()
        if fl0.startswith('O') or fl0.startswith('Y'):
            return (False, 'This POS date and shift are already open.')
        if legacy_pk:
            if fl0.startswith('C'):
                ex_pd_raw = r0l.get('posdate')
                ex_pd: Optional[date] = None
                if ex_pd_raw is not None:
                    if hasattr(ex_pd_raw, 'date') and callable(ex_pd_raw.date):
                        try:
                            ex_pd = ex_pd_raw.date()
                        except Exception:
                            ex_pd = None
                    elif isinstance(ex_pd_raw, date):
                        ex_pd = ex_pd_raw
                try:
                    ex_sc = int(r0l.get('shiftcode') if r0l.get('shiftcode') is not None else sc)
                except (TypeError, ValueError):
                    ex_sc = sc
                if ex_pd == pos_date and ex_sc == sc:
                    reopen_closed_slot = True
        elif fl0.startswith('C'):
            reopen_closed_slot = True
    if not reopen_closed_slot:
        last_closed = get_latest_closed_pos_date_for_counter(lc, cc, db_key=db_key)
        if last_closed is not None and pos_date <= last_closed:
            try:
                closed_disp = last_closed.strftime('%d/%b/%Y')
            except Exception:
                closed_disp = str(last_closed)[:10]
            try:
                pos_disp = pos_date.strftime('%d/%b/%Y')
            except Exception:
                pos_disp = str(pos_date)[:10]
            return (
                False,
                f'Cannot open shift on {pos_disp}: counter {cc} already has a closed shift on or after that date '
                f'(last closed POS date {closed_disp}). Choose a later POS date.',
            )
    now_ts = datetime.now()
    co_cols = _counter_operations_table_columns(db_key)
    cashier_code_int = _resolve_counter_operations_cashier_code(ob, cashier_code)
    bind_params = {
        'lc': lc, 'cc': cc, 'pd': pos_date, 'sc': sc, 'ob': ob, 'ots': now_ts,
        'cashier_code': cashier_code_int,
    }
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if not existing:
                    cur.execute('SELECT NVL(MAX(SLNO), 0) + 1 FROM COUNTEROPERATIONS WHERE LOCATIONCODE = :lc', {'lc': lc})
                    rmax = cur.fetchone()
                    next_slno = int(rmax[0]) if rmax and rmax[0] is not None else 1
                    bind_params['slno'] = next_slno
                    cur.execute(
                        _counter_operations_open_insert_sql(co_cols),
                        bind_params,
                    )
                else:
                    r0 = existing[0]
                    r0l = {str(k).lower(): v for k, v in (r0.items() if hasattr(r0, 'items') else [])}
                    raw_sl = r0l.get('slno')
                    row_slno: Optional[int] = None
                    if raw_sl is not None:
                        try:
                            row_slno = int(raw_sl)
                        except (TypeError, ValueError):
                            row_slno = None
                    if row_slno is None:
                        cur.execute('SELECT NVL(MAX(SLNO), 0) + 1 FROM COUNTEROPERATIONS WHERE LOCATIONCODE = :lc', {'lc': lc})
                        rmx = cur.fetchone()
                        row_slno = int(rmx[0]) if rmx and rmx[0] is not None else 1
                    if legacy_pk:
                        if not reopen_closed_slot:
                            fl_existing = str(r0l.get('openflag') or 'C').strip().upper()
                            if fl_existing.startswith('C'):
                                _archive_counter_operation_row_cur(cur, lc, cc)
                        pd_sets = ', '.join(_counter_operations_pos_date_set_sql(co_cols))
                        opened_sets: List[str] = []
                        if 'OPENEDDATE' in co_cols:
                            opened_sets.append('OPENEDDATE = TRUNC(:ots)')
                        if 'OPENEDTIME' in co_cols:
                            opened_sets.append('OPENEDTIME = :ots')
                        close_nulls: List[str] = []
                        if 'CLOSEDBY' in co_cols:
                            close_nulls.append('CLOSEDBY = NULL')
                        if 'CLOSEDDATE' in co_cols:
                            close_nulls.append('CLOSEDDATE = NULL')
                        if 'CLOSEDTIME' in co_cols:
                            close_nulls.append('CLOSEDTIME = NULL')
                        set_sql = ', '.join(
                            ['SHIFTCODE = :sc', "OPENFLAG = 'O'", 'SLNO = :slno', 'OPENEDBY = :ob']
                            + ([pd_sets] if pd_sets else [])
                            + opened_sets
                            + close_nulls
                            + _counter_operations_legacy_open_update_fragments(co_cols)
                        )
                        cur.execute(
                            f"""
                            UPDATE COUNTEROPERATIONS SET
                                {set_sql}
                            WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc
                            """,
                            {**bind_params, 'slno': row_slno},
                        )
                    else:
                        pd_sets = ', '.join(_counter_operations_pos_date_set_sql(co_cols))
                        opened_sets = []
                        if 'OPENEDDATE' in co_cols:
                            opened_sets.append('OPENEDDATE = TRUNC(:ots)')
                        if 'OPENEDTIME' in co_cols:
                            opened_sets.append('OPENEDTIME = :ots')
                        close_nulls = []
                        if 'CLOSEDBY' in co_cols:
                            close_nulls.append('CLOSEDBY = NULL')
                        if 'CLOSEDDATE' in co_cols:
                            close_nulls.append('CLOSEDDATE = NULL')
                        if 'CLOSEDTIME' in co_cols:
                            close_nulls.append('CLOSEDTIME = NULL')
                        set_sql = ', '.join(
                            ["OPENFLAG = 'O'", 'SLNO = :slno', 'OPENEDBY = :ob']
                            + ([pd_sets] if pd_sets else [])
                            + opened_sets
                            + close_nulls
                            + _counter_operations_legacy_open_update_fragments(co_cols)
                        )
                        cur.execute(
                            f"""
                            UPDATE COUNTEROPERATIONS SET
                                {set_sql}
                            WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc
                              AND TRUNC({_counter_operations_pos_date_select_sql(db_key=db_key)}) = TRUNC(:pd)
                              AND SHIFTCODE = :sc
                            """,
                            {**bind_params, 'slno': row_slno},
                        )
            conn.commit()
        _TABLE_COLUMNS_CACHE.pop('COUNTEROPERATIONS', None)
        return (True, '')
    except Exception as e:
        print(f'[ERROR open_pos_counter_operation] {e}')
        return (False, str(e))

def close_pos_counter_operation(*, location_code: int, counter_code: int, closed_by: str, db_key: Optional[str]=None) -> Tuple[bool, str]:
    """Close the latest open shift row for location+counter."""
    ensure_counter_operations_table()
    if not _table_exists('COUNTEROPERATIONS', db_key=db_key):
        return (False, 'COUNTEROPERATIONS table not available.')
    cb = (closed_by or '').strip()[:20] or 'SYSTEM'
    try:
        lc = int(location_code)
        cc = int(counter_code)
    except (TypeError, ValueError):
        return (False, 'Invalid location or counter code.')
    now_ts = datetime.now()
    pd_sel = _counter_operations_pos_date_select_sql(db_key=db_key)
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT ROWID, {pd_sel} AS POSDATE
                    FROM COUNTEROPERATIONS
                    WHERE LOCATIONCODE = :lc AND COUNTERCODE = :cc
                      AND TRIM(OPENFLAG) IN ('O', 'Y')
                    ORDER BY NVL(OPENEDTIME, CAST(OPENEDDATE AS TIMESTAMP)) DESC NULLS LAST
                    """,
                    {'lc': lc, 'cc': cc},
                )
                row = cur.fetchone()
                if not row:
                    return (False, 'No open shift for this counter.')
                rid = row[0]
                pos_date_val = row[1] if len(row) > 1 else None
                held_n = count_pos_held_bills_for_counter(lc, cc, pos_date_val or date.today(), db_key=db_key)
                if held_n > 0:
                    return (
                        False,
                        f'Cannot close shift: {held_n} held bill(s) for this counter on POS date. '
                        'Resume or void them in POS Billing before closing.',
                    )
                cur.execute("\n                    UPDATE COUNTEROPERATIONS SET\n                        OPENFLAG = 'C',\n                        CLOSEDBY = :cb,\n                        CLOSEDDATE = TRUNC(:cts),\n                        CLOSEDTIME = :cts\n                    WHERE ROWID = :rid\n                    ", {'cb': cb, 'cts': now_ts, 'rid': rid})
            conn.commit()
        return (True, '')
    except Exception as e:
        print(f'[ERROR close_pos_counter_operation] {e}')
        return (False, str(e))


def _pos_billhdr_summary_where(
    cols_u: set,
    *,
    location_code: int,
    counter_code: Optional[int] = None,
    pos_date: Any = None,
    from_date: Any = None,
    to_date: Any = None,
    shift_code: Optional[int] = None,
    alias: str = '',
    pos_posted_only: bool = False,
) -> Tuple[List[str], Dict[str, Any]]:
    """Shared BILLHDR filters for POS shift close / sales list summaries."""
    pre = f'{alias}.' if alias else ''
    where: List[str] = [f'{pre}LOCATIONCODE = :loc']
    params: Dict[str, Any] = {'loc': int(location_code)}
    if counter_code is not None and int(counter_code) > 0 and 'COUNTERCODE' in cols_u:
        where.append(f'{pre}COUNTERCODE = :cc')
        params['cc'] = int(counter_code)
    if pos_date is not None:
        where.append(f'TRUNC({pre}BILLDATE) = TRUNC(:pd)')
        params['pd'] = pos_date
    else:
        if from_date is not None:
            where.append(f'TRUNC({pre}BILLDATE) >= TRUNC(:from_d)')
            params['from_d'] = from_date
        if to_date is not None:
            where.append(f'TRUNC({pre}BILLDATE) <= TRUNC(:to_d)')
            params['to_d'] = to_date
    if shift_code is not None and 'SHIFTCODE' in cols_u:
        try:
            sc = int(shift_code)
            if sc > 0:
                where.append(f'{pre}SHIFTCODE = :sc')
                params['sc'] = sc
        except (TypeError, ValueError):
            pass
    if 'DELFLAG' in cols_u:
        where.append(f"NVL({pre}DELFLAG, 'N') NOT IN ('Y', 'y')")
    if 'BILLSTATUS' in cols_u:
        where.append(f"NVL({pre}BILLSTATUS, ' ') <> 'V'")
    if pos_posted_only:
        _append_pos_posted_scope_filters(where, cols_u, hdr_alias=alias or '')
    return where, params


def _pos_billhdr_billtype_char_expr(cols_u: set, alias: str = '') -> str:
    """Oracle expression → ``C`` (cash) or ``R`` (credit).

    Handles single-letter ``C``/``R`` and full words ``CASH``/``CREDIT``
    (first-letter of CREDIT must not be treated as cash).
    """
    pre = f'{alias}.' if alias else ''
    if 'BILLTYPE' not in cols_u:
        return "''"
    raw = f"UPPER(TRIM(TO_CHAR({pre}BILLTYPE)))"
    return (
        f"CASE "
        f"WHEN {raw} IN ('R', 'CREDIT', 'CR', '2') OR {raw} LIKE 'CREDIT%' THEN 'R' "
        f"WHEN {raw} IN ('C', 'CASH', '1') OR {raw} LIKE 'CASH%' THEN 'C' "
        f"WHEN SUBSTR({raw}, 1, 1) IN ('C', 'R') THEN SUBSTR({raw}, 1, 1) "
        f"ELSE '' END"
    )


def _normalize_billtype_cash_credit(raw: Any) -> str:
    """Normalize BILLHDR.BILLTYPE to ``C`` (cash) or ``R`` (credit) or ``''``."""
    s = str(raw or '').strip().upper()
    if not s:
        return ''
    if s in ('R', 'CREDIT', 'CR', '2') or s.startswith('CREDIT'):
        return 'R'
    if s in ('C', 'CASH', '1') or s.startswith('CASH'):
        return 'C'
    ch = s[:1]
    return ch if ch in ('C', 'R') else ''


def _pos_billhdr_customer_code_expr(cols_u: set, alias: str = '') -> str:
    pre = f'{alias}.' if alias else ''
    if 'CUSTOMERCODE' in cols_u:
        return f'NVL({pre}CUSTOMERCODE, 0)'
    return '0'


def _query_pos_billhdr_sales_metrics_sql(
    cols_u: set,
    where: List[str],
    params: Dict[str, Any],
    *,
    db_key: Optional[str] = None,
) -> Tuple[float, float, float]:
    """``SUM(NETBILLAMOUNT)`` for cash (``BILLTYPE='C'``) and credit (``BILLTYPE='R'``) bills.

    Cash customer sale includes cash bills with a customer selected — do **not** treat
    ``CUSTOMERCODE > 0`` as credit when bill type is cash.
    """
    if 'NETBILLAMOUNT' not in cols_u:
        return 0.0, 0.0, 0.0
    bt = _pos_billhdr_billtype_char_expr(cols_u)
    disc_sql = 'NVL(DISCOUNTAMOUNT, 0)' if 'DISCOUNTAMOUNT' in cols_u else '0'
    q = f"""
        SELECT
            NVL(SUM(CASE WHEN {bt} = 'C'
                THEN NVL(NETBILLAMOUNT, 0) ELSE 0 END), 0) AS direct_customer,
            NVL(SUM(CASE WHEN {bt} = 'R'
                AND NVL(NETBILLAMOUNT, 0) > 0.0005
                THEN NVL(NETBILLAMOUNT, 0) ELSE 0 END), 0) AS credit_sales,
            NVL(SUM({disc_sql}), 0) AS total_discount
        FROM BILLHDR
        WHERE {' AND '.join(where)}
    """
    try:
        rows = _safe_rows(q, params, db_key=db_key) or []
        if rows:
            rk = {str(k).lower(): v for k, v in rows[0].items()}
            direct = round(float(rk.get('direct_customer') or 0), 2)
            credit = round(float(rk.get('credit_sales') or 0), 2)
            disc = round(float(rk.get('total_discount') or 0), 2)
            return direct, credit, disc
    except Exception as e:
        print(f'[ERROR _query_pos_billhdr_sales_metrics_sql] {e}')
    return 0.0, 0.0, 0.0


def _metrics_from_pos_billhdr_rows(bill_rows: List[Dict[str, Any]]) -> Tuple[List[int], float, float, float, float]:
    """Return bill_nos, direct_customer (cash), credit_sales, total_sales, total_discount.

    Cash customer sale = ``BILLTYPE = 'C'`` (with or without customer).
    Credit customer sale = ``BILLTYPE = 'R'`` (positive net only).
    """
    bill_nos: List[int] = []
    direct_customer = 0.0
    credit_sales = 0.0
    total_sales = 0.0
    total_discount = 0.0
    for r in bill_rows or []:
        rk = {str(k).lower(): v for k, v in r.items()}
        try:
            bn = int(rk.get('billno') or 0)
        except (TypeError, ValueError):
            bn = 0
        if bn > 0:
            bill_nos.append(bn)
        bt = _normalize_billtype_cash_credit(rk.get('billtype'))
        try:
            net = float(rk.get('netbillamount') or 0)
        except (TypeError, ValueError):
            net = 0.0
        try:
            disc = float(rk.get('discountamount') or 0)
        except (TypeError, ValueError):
            disc = 0.0
        total_discount += disc
        if bt == 'C':
            direct_customer += net
        elif bt == 'R' and net > 0.0005:
            credit_sales += net
    total_sales = round(direct_customer + credit_sales, 2)
    return bill_nos, direct_customer, credit_sales, total_sales, total_discount


def _pos_billnos_with_paymode_rows(location_code: int, bill_nos: List[Any]) -> set:
    """Bill numbers that have at least one ``POS_BILL_PAYMODE`` row."""
    if not bill_nos or not ensure_pos_bill_paymode_table():
        return set()
    tbl = POS_BILL_PAYMODE_TABLE
    clean = _clean_settlement_billnos(bill_nos)
    if not clean:
        return set()
    ph = ','.join([f':b{i}' for i in range(len(clean))])
    params: Dict[str, Any] = {'loc': int(location_code)}
    for i, bn in enumerate(clean):
        params[f'b{i}'] = bn
    q = f'SELECT BILLNO AS bno, COUNT(*) AS cnt FROM {tbl} WHERE LOCATIONCODE = :loc AND BILLNO IN ({ph}) GROUP BY BILLNO'
    rows = _safe_rows(q, params) or []
    out: set = set()
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        try:
            cnt = int(float(rk.get('cnt') or 0))
        except (TypeError, ValueError):
            cnt = 0
        if cnt <= 0:
            continue
        bn = coerce_billno(rk.get('bno'))
        if billno_is_valid(bn):
            out.add(str(bn))
    return out


def _merge_pos_shift_tender_totals(
    location_code: int,
    bill_rows: List[Dict[str, Any]],
    bill_nos: List[int],
) -> Dict[str, float]:
    """Merge ``POS_BILL_PAYMODE`` totals with BILLHDR bucket fallback for bills missing paymode rows."""
    totals_agg = _aggregate_pos_settlement_totals_from_billhdr_rows(bill_rows)
    pm_totals = fetch_pos_paymode_totals_for_bills(location_code, bill_nos) if bill_nos else {}
    if not pm_totals:
        return paymode_amounts_from_billhdr_settlement_totals(totals_agg)
    with_pm = _pos_billnos_with_paymode_rows(location_code, bill_nos)
    clean_keys = {str(b) for b in _clean_settlement_billnos(bill_nos)}
    if not with_pm or len(with_pm) >= len(clean_keys):
        return dict(pm_totals)
    rows_without: List[Dict[str, Any]] = []
    for r in bill_rows or []:
        rk = {str(k).lower(): v for k, v in r.items()}
        bn = coerce_billno(rk.get('billno'))
        if not billno_is_valid(bn):
            continue
        if str(bn) not in with_pm:
            rows_without.append(r)
    hdr_buckets = paymode_amounts_from_billhdr_settlement_totals(
        _aggregate_pos_settlement_totals_from_billhdr_rows(rows_without)
    )
    merged: Dict[str, float] = dict(hdr_buckets)
    for k, v in pm_totals.items():
        ku = str(k or '').strip().upper()
        if not ku:
            continue
        try:
            fv = float(v or 0)
        except (TypeError, ValueError):
            fv = 0.0
        merged[ku] = round(float(merged.get(ku, 0)) + fv, 4)
    return merged


def _pos_shift_tender_label_map() -> Dict[str, str]:
    labels: Dict[str, str] = {}
    if ensure_pos_tender_type_table():
        for tr in list_pos_tender_types(active_only=False):
            tc = str(tr.get('tender_code') or '').strip().upper()
            if tc:
                labels[tc] = str(tr.get('tender_name') or tc).strip()
    return labels


def _build_pos_tender_breakdown_for_bills(
    location_code: int,
    bill_rows: List[Dict[str, Any]],
    bill_nos: List[int],
) -> Dict[str, Any]:
    """Cash + non-credit tender lines (credit sales shown separately in summary)."""
    totals_agg = _aggregate_pos_settlement_totals_from_billhdr_rows(bill_rows)
    merged_pm = _merge_pos_shift_tender_totals(location_code, bill_rows, bill_nos)
    code_to_label = _pos_shift_tender_label_map()
    tender_rows: List[Dict[str, Any]] = []
    for code, amt in merged_pm.items():
        cu = str(code or '').strip().upper()
        if not cu or _is_pos_shift_credit_tender(cu):
            continue
        try:
            fv = float(amt or 0)
        except (TypeError, ValueError):
            fv = 0.0
        if abs(fv) <= 0.0005:
            continue
        tender_rows.append(
            {
                'code': cu,
                'label': code_to_label.get(cu) or cu.replace('_', ' ').title(),
                'amount': round(fv, 2),
                'is_cash': cu == 'CASH',
            }
        )
    tender_rows.sort(key=lambda r: _paymode_sort_key(str(r.get('code') or ''), list_pos_tender_types(active_only=True) if ensure_pos_tender_type_table() else []))
    non_cash = [r for r in tender_rows if not r.get('is_cash')]
    cash_rows = [r for r in tender_rows if r.get('is_cash')]
    tender_breakdown: List[Dict[str, Any]] = non_cash + cash_rows
    cash_in_box = round(float(merged_pm.get('CASH') or totals_agg.get('cash') or 0), 2)
    collection_total = round(
        sum(float(r.get('amount') or 0) for r in tender_breakdown),
        2,
    )
    return {
        'cash_in_box': cash_in_box,
        'card_total': round(float(merged_pm.get('CARD') or totals_agg.get('card') or 0), 2),
        'wallet_total': round(
            float(merged_pm.get('WALLET') or totals_agg.get('wallet') or 0)
            + float(merged_pm.get('LOYALTY') or 0)
            + float(merged_pm.get('POINTS') or 0),
            2,
        ),
        'collection_total': collection_total,
        'tender_breakdown': tender_breakdown,
        'totals_agg': totals_agg,
        'paymode_totals': merged_pm,
    }


def _sum_pos_sales_returns_from_billdtl(
    location_code: int,
    *,
    pos_date: Any = None,
    from_date: Any = None,
    to_date: Any = None,
    counter_code: Optional[int] = None,
    shift_code: Optional[int] = None,
    db_key: Optional[str] = None,
) -> float:
    """Sum absolute value of negative BILLDTL line nets for scoped BILLHDR rows."""
    hdr_cols = {str(c or '').upper() for c in (_get_table_columns('BILLHDR') or [])}
    dtl_cols = {str(c or '').upper() for c in (_get_table_columns('BILLDTL') or [])}
    if not _table_exists('BILLHDR', db_key=db_key) or not _table_exists('BILLDTL', db_key=db_key):
        return 0.0
    if 'BILLNO' not in hdr_cols or 'BILLNO' not in dtl_cols:
        return 0.0
    if 'QUANTITY' not in dtl_cols or 'RATE' not in dtl_cols:
        return 0.0
    disc_col = 'ITDISC' if 'ITDISC' in dtl_cols else ('DISCOUNT' if 'DISCOUNT' in dtl_cols else None)
    if disc_col:
        line_net = f'(NVL(d.QUANTITY, 0) * NVL(d.RATE, 0) - NVL(d.{disc_col}, 0))'
    else:
        line_net = '(NVL(d.QUANTITY, 0) * NVL(d.RATE, 0))'
    hdr_where, params = _pos_billhdr_summary_where(
        hdr_cols,
        location_code=location_code,
        counter_code=counter_code,
        pos_date=pos_date,
        from_date=from_date,
        to_date=to_date,
        shift_code=shift_code,
        alias='h',
    )
    dtl_where: List[str] = []
    if 'LOCATIONCODE' in dtl_cols:
        dtl_where.append('d.LOCATIONCODE = h.LOCATIONCODE')
    dtl_where.append('d.BILLNO = h.BILLNO')
    if 'ITEMFLAG' in dtl_cols:
        dtl_where.append('NVL(d.ITEMFLAG, 1) = 1')
    join_on = ' AND '.join(dtl_where)
    q = f"""
        SELECT NVL(SUM(
            CASE WHEN {line_net} < -0.0005 THEN ABS({line_net}) ELSE 0 END
        ), 0) AS ret_total
        FROM BILLDTL d
        INNER JOIN BILLHDR h ON {join_on}
        WHERE {' AND '.join(hdr_where)}
    """
    try:
        rows = _safe_rows(q, params, db_key=db_key) or []
        if rows:
            rk = {str(k).lower(): v for k, v in rows[0].items()}
            return round(abs(float(rk.get('ret_total') or 0)), 2)
    except Exception as e:
        print(f'[ERROR _sum_pos_sales_returns_from_billdtl] {e}')
    return 0.0


def _sum_pos_canceled_bill_amount_for_scope(
    location_code: int,
    *,
    pos_date: Any = None,
    from_date: Any = None,
    to_date: Any = None,
    counter_code: Optional[int] = None,
    db_key: Optional[str] = None,
) -> float:
    """Sum canceled/void bill amounts (TBLCANCELEDHDR) for location + optional scope."""
    if not _table_exists('TBLCANCELEDHDR', db_key=db_key):
        return 0.0
    cols_u = {str(c or '').upper() for c in (_get_table_columns('TBLCANCELEDHDR') or [])}
    if 'BILLNO' not in cols_u or 'BILLDATE' not in cols_u:
        return 0.0
    amt_col = 'NETBILLAMOUNT' if 'NETBILLAMOUNT' in cols_u else ('BILLAMOUNT' if 'BILLAMOUNT' in cols_u else None)
    if not amt_col:
        return 0.0
    where = ['LOCATIONCODE = :loc']
    params: Dict[str, Any] = {'loc': int(location_code)}
    if counter_code is not None and int(counter_code) > 0 and 'COUNTERCODE' in cols_u:
        where.append('COUNTERCODE = :cc')
        params['cc'] = int(counter_code)
    if pos_date is not None:
        where.append('TRUNC(BILLDATE) = TRUNC(:pd)')
        params['pd'] = pos_date
    else:
        if from_date is not None:
            where.append('TRUNC(BILLDATE) >= TRUNC(:from_d)')
            params['from_d'] = from_date
        if to_date is not None:
            where.append('TRUNC(BILLDATE) <= TRUNC(:to_d)')
            params['to_d'] = to_date
    q = f"""
        SELECT NVL(SUM(ABS(NVL({amt_col}, 0))), 0) AS cancel_total
        FROM TBLCANCELEDHDR
        WHERE {' AND '.join(where)}
    """
    try:
        rows = _safe_rows(q, params, db_key=db_key) or []
        if rows:
            rk = {str(k).lower(): v for k, v in rows[0].items()}
            return round(abs(float(rk.get('cancel_total') or 0)), 2)
    except Exception as e:
        print(f'[ERROR _sum_pos_canceled_bill_amount_for_scope] {e}')
    return 0.0


def _sum_pos_shift_sales_returns_from_billdtl(
    location_code: int,
    counter_code: int,
    pos_date: Any,
    *,
    db_key: Optional[str] = None,
) -> float:
    """Sum absolute value of negative BILLDTL line nets for counter + POS business date."""
    return _sum_pos_sales_returns_from_billdtl(
        location_code,
        pos_date=pos_date,
        counter_code=counter_code,
        db_key=db_key,
    )


