def _is_pos_shift_credit_tender(code: str) -> bool:
    """Credit/on-account tender — shown in report summary, not in tender footer."""
    cu = str(code or '').strip().upper()
    return cu in ('CREDIT', 'ON_ACCOUNT', 'ONACCOUNT', 'CREDIT_ON_ACCOUNT', 'ACCOUNT')


def build_pos_shift_preclose_report(
    location_code: int,
    counter_code: int,
    pos_date: Any,
    *,
    db_key: Optional[str] = None,
    cashier: str = '',
    is_final: bool = False,
) -> Dict[str, Any]:
    """Aggregate posted POS bills for counter + POS business date (shift pre-close / close print)."""
    try:
        lc = int(location_code)
        cc = int(counter_code)
    except (TypeError, ValueError):
        return {'ok': False, 'error': 'Invalid location or counter.'}
    pd = pos_date.date() if hasattr(pos_date, 'date') and callable(pos_date.date) else pos_date
    loc_info = get_location_info_by_dbkey(db_key) or {}
    counter_name = (get_counter_name_by_code(cc, db_key=db_key or 'HO', location_code=lc) or '').strip()
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    if 'BILLNO' not in cols_u or 'LOCATIONCODE' not in cols_u:
        return {'ok': False, 'error': 'BILLHDR not available.'}
    where, params = _pos_billhdr_summary_where(
        cols_u,
        location_code=lc,
        counter_code=cc,
        pos_date=pd,
        pos_posted_only=False,
    )
    q = f"SELECT * FROM BILLHDR WHERE {' AND '.join(where)} ORDER BY BILLNO"
    bill_rows = _safe_rows(q, params, db_key=db_key) or []
    bill_nos: List[int] = []
    for r in bill_rows or []:
        rk = {str(k).lower(): v for k, v in r.items()}
        try:
            bn = int(rk.get('billno') or 0)
        except (TypeError, ValueError):
            bn = 0
        if bn > 0:
            bill_nos.append(bn)
    direct_customer, credit_sales, total_discount = _query_pos_billhdr_sales_metrics_sql(
        cols_u, where, params, db_key=db_key,
    )
    total_sales = round(direct_customer + credit_sales, 2)
    sales_returns = _sum_pos_sales_returns_from_billdtl(lc, pos_date=pd, counter_code=cc, db_key=db_key)
    total_cancel = _sum_pos_canceled_bill_amount_for_scope(lc, pos_date=pd, counter_code=cc, db_key=db_key)
    tender_info = _build_pos_tender_breakdown_for_bills(lc, bill_rows, bill_nos)
    cash_in_box = tender_info['cash_in_box']
    tender_breakdown = tender_info['tender_breakdown']
    totals_agg = tender_info['totals_agg']
    credit_on_account = round(float(totals_agg.get('credit') or 0), 2)
    now_ts = datetime.now()
    return {
        'ok': True,
        'is_final': bool(is_final),
        'location_code': lc,
        'counter_code': cc,
        'counter_name': counter_name,
        'pos_date': pd.isoformat() if hasattr(pd, 'isoformat') else str(pd)[:10],
        'pos_date_display': pd.strftime('%d/%b/%Y') if hasattr(pd, 'strftime') else str(pd)[:10],
        'check_time_display': now_ts.strftime('%d/%b/%Y %I:%M:%S %p').replace(' 0', ' '),
        'cashier': (cashier or '').strip(),
        'location_name': str(loc_info.get('locationname') or '').strip(),
        'location_phones': str(loc_info.get('telephone') or loc_info.get('phone') or '').strip(),
        'bill_count': len(bill_nos),
        'direct_customer': round(direct_customer, 2),
        'credit_sales': round(credit_sales, 2),
        'total_sales': round(total_sales, 2),
        'sales_returns': round(sales_returns, 2),
        'total_discount': round(total_discount, 2),
        'total_cancel': round(total_cancel, 2),
        'discount_lines': round(total_discount, 2),
        'credit_on_account': credit_on_account,
        'cash_in_box': cash_in_box,
        'collection_total': round(float(tender_info.get('collection_total') or 0), 2),
        'tender_breakdown': tender_breakdown,
        'payment_lines': compute_pos_settlement_payment_mode_summary(lc, bill_nos).get('lines') if bill_nos else [],
    }


def build_pos_price_edited_report(
    location_code: int,
    *,
    from_date: Any = None,
    to_date: Any = None,
    counter_code: Optional[int] = None,
    shift_code: Optional[int] = None,
    db_key: Optional[str] = None,
) -> Dict[str, Any]:
    """Lines where sold unit price (RATE) differs from catalog price (OLDPRICE) on posted POS bills."""
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return {'ok': False, 'error': 'Invalid location.', 'rows': []}
    fd = from_date.date() if hasattr(from_date, 'date') and callable(from_date.date) else from_date
    td = to_date.date() if hasattr(to_date, 'date') and callable(to_date.date) else to_date
    if fd is None and td is None:
        fd = td = date.today()
    elif fd is None:
        fd = td
    elif td is None:
        td = fd
    cc: Optional[int] = None
    if counter_code is not None:
        try:
            cc_val = int(counter_code)
            if cc_val > 0:
                cc = cc_val
        except (TypeError, ValueError):
            cc = None
    sc: Optional[int] = None
    if shift_code is not None and str(shift_code).strip() != '':
        try:
            sc_val = int(shift_code)
            if sc_val > 0:
                sc = sc_val
        except (TypeError, ValueError):
            sc = None
    pairs: List[Tuple[str, str]] = []
    for dtl_t, hdr_t in (('BILLDTL', 'BILLHDR'), ('BILLDTLHISTORY', 'BILLHDRHISTORY')):
        if not _table_exists(hdr_t) or not _table_exists(dtl_t):
            continue
        dtl_cols_u = {str(c or '').upper() for c in (_get_table_columns(dtl_t) or [])}
        hdr_cols_u = {str(c or '').upper() for c in (_get_table_columns(hdr_t) or [])}
        if 'OLDPRICE' not in dtl_cols_u or 'RATE' not in dtl_cols_u or 'BILLNO' not in dtl_cols_u:
            continue
        if 'LOCATIONCODE' not in hdr_cols_u or 'BILLDATE' not in hdr_cols_u:
            continue
        pairs.append((dtl_t, hdr_t))
    if not pairs:
        return {'ok': False, 'error': 'Bill detail tables with OLDPRICE are not available.', 'rows': []}
    all_rows: List[Dict[str, Any]] = []
    for dtl_t, hdr_t in pairs:
        hdr_cols_u = {str(c or '').upper() for c in (_get_table_columns(hdr_t) or [])}
        shift_sql = ''
        params: Dict[str, Any] = {'loc': lc, 'fd': fd, 'td': td}
        if cc is not None and 'COUNTERCODE' in hdr_cols_u:
            shift_sql += ' AND NVL(h.COUNTERCODE, 0) = :cc'
            params['cc'] = cc
        if sc is not None and 'SHIFTCODE' in hdr_cols_u:
            shift_sql += ' AND NVL(h.SHIFTCODE, 0) = :sc'
            params['sc'] = sc
        elif sc is not None and 'SESSIONCODE' in hdr_cols_u:
            shift_sql += ' AND NVL(h.SESSIONCODE, 0) = :sc'
            params['sc'] = sc
        created_expr = 'NVL(h.CREATEDBY, \'\')' if 'CREATEDBY' in hdr_cols_u else "''"
        q = f"""
            SELECT
                h.BILLNO AS billno,
                TO_CHAR(h.BILLDATE, 'YYYY-MM-DD') AS billdate,
                NVL(h.COUNTERCODE, 0) AS countercode,
                {created_expr} AS createdby,
                d.SLNO AS slno,
                d.ITEMCODE AS itemcode,
                NVL(d.UNITOFMEASUREMENT, '') AS uom,
                NVL(d.QUANTITY, 0) AS quantity,
                NVL(d.OLDPRICE, 0) AS original_rate,
                NVL(d.RATE, 0) AS edited_rate,
                (NVL(d.RATE, 0) - NVL(d.OLDPRICE, 0)) AS rate_diff,
                (NVL(d.QUANTITY, 0) * (NVL(d.RATE, 0) - NVL(d.OLDPRICE, 0))) AS line_impact
            FROM {dtl_t} d
            JOIN {hdr_t} h ON d.BILLNO = h.BILLNO
            WHERE h.LOCATIONCODE = :loc
              AND TRUNC(h.BILLDATE) >= TRUNC(:fd)
              AND TRUNC(h.BILLDATE) <= TRUNC(:td)
              AND NVL(d.OLDPRICE, 0) > 0
              AND ABS(NVL(d.RATE, 0) - NVL(d.OLDPRICE, 0)) > 0.009
              {shift_sql}
            ORDER BY h.BILLDATE DESC, h.BILLNO DESC, d.SLNO
        """
        try:
            chunk = _safe_rows(q, params, db_key=db_key) or []
            for r in chunk:
                r['_source'] = dtl_t
            all_rows.extend(chunk)
        except Exception as exc:
            print(f'[build_pos_price_edited_report] {dtl_t}: {exc}')
    # POS save copies the same bill into BILLDTL and BILLDTLHISTORY — keep one row per line.
    if all_rows:
        seen_lines: Set[Tuple[str, int]] = set()
        deduped: List[Dict[str, Any]] = []
        for r in all_rows:
            bill_key = str(r.get('billno') or '').strip()
            try:
                sl_key = int(r.get('slno') or 0)
            except (TypeError, ValueError):
                sl_key = 0
            line_key = (bill_key, sl_key)
            if line_key in seen_lines:
                continue
            seen_lines.add(line_key)
            deduped.append(r)
        all_rows = deduped
    if not all_rows:
        return {'ok': True, 'location_code': lc, 'from_date': fd.isoformat() if hasattr(fd, 'isoformat') else str(fd)[:10], 'to_date': td.isoformat() if hasattr(td, 'isoformat') else str(td)[:10], 'counter_code': cc, 'shift_code': sc, 'rows': [], 'line_count': 0}
    item_codes = list({r.get('itemcode') for r in all_rows if r.get('itemcode') is not None})
    names: Dict[Any, str] = {}
    if item_codes and _table_exists('ITEMMASTER'):
        placeholders = ', '.join([f':ic{i}' for i in range(len(item_codes))])
        params_im = {'loc': lc, **{f'ic{i}': item_codes[i] for i in range(len(item_codes))}}
        try:
            for nr in _safe_rows(f'SELECT ITEMCODE, ITEMNAME FROM ITEMMASTER WHERE LOCATIONCODE = :loc AND ITEMCODE IN ({placeholders})', params_im, db_key=db_key) or []:
                code = nr.get('itemcode') or nr.get('ITEMCODE')
                nm = str(nr.get('itemname') or nr.get('ITEMNAME') or '').strip()
                if code is not None:
                    names[code] = nm or str(code)
        except Exception:
            pass
    out: List[Dict[str, Any]] = []
    for r in all_rows:
        ic = r.get('itemcode')
        out.append({'billno': r.get('billno'), 'billdate': r.get('billdate'), 'countercode': r.get('countercode'), 'createdby': (r.get('createdby') or '').strip(), 'slno': r.get('slno'), 'itemcode': ic, 'itemname': names.get(ic, str(ic) if ic is not None else ''), 'uom': (r.get('uom') or '').strip(), 'quantity': round(float(r.get('quantity') or 0), 3), 'original_rate': round(float(r.get('original_rate') or 0), 2), 'edited_rate': round(float(r.get('edited_rate') or 0), 2), 'rate_diff': round(float(r.get('rate_diff') or 0), 2), 'line_impact': round(float(r.get('line_impact') or 0), 2)})
    return {'ok': True, 'location_code': lc, 'from_date': fd.isoformat() if hasattr(fd, 'isoformat') else str(fd)[:10], 'to_date': td.isoformat() if hasattr(td, 'isoformat') else str(td)[:10], 'counter_code': cc, 'shift_code': sc, 'rows': out, 'line_count': len(out)}


def build_pos_sales_list_summary(
    location_code: int,
    *,
    from_date: Any = None,
    to_date: Any = None,
    counter_code: Optional[int] = None,
    shift_code: Optional[int] = None,
    db_key: Optional[str] = None,
) -> Dict[str, Any]:
    """POS Sales List / X Report style totals for a date range and optional counter/shift."""
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return {'ok': False, 'error': 'Invalid location.'}
    fd = from_date.date() if hasattr(from_date, 'date') and callable(from_date.date) else from_date
    td = to_date.date() if hasattr(to_date, 'date') and callable(to_date.date) else to_date
    if fd is None and td is None:
        fd = td = date.today()
    elif fd is None:
        fd = td
    elif td is None:
        td = fd
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    if 'BILLNO' not in cols_u or 'LOCATIONCODE' not in cols_u:
        return {'ok': False, 'error': 'BILLHDR not available.'}
    cc: Optional[int] = None
    if counter_code is not None:
        try:
            cc_val = int(counter_code)
            if cc_val > 0:
                cc = cc_val
        except (TypeError, ValueError):
            cc = None
    sc: Optional[int] = None
    if shift_code is not None and str(shift_code).strip() != '':
        try:
            sc_val = int(shift_code)
            if sc_val > 0:
                sc = sc_val
        except (TypeError, ValueError):
            sc = None
    where, params = _pos_billhdr_summary_where(
        cols_u,
        location_code=lc,
        counter_code=cc,
        from_date=fd,
        to_date=td,
        shift_code=sc,
    )
    q = f"SELECT * FROM BILLHDR WHERE {' AND '.join(where)} ORDER BY BILLNO"
    bill_rows = _safe_rows(q, params, db_key=db_key) or []
    bill_nos, direct_customer, credit_sales, total_sales, total_discount = _metrics_from_pos_billhdr_rows(bill_rows)
    sales_returns = _sum_pos_sales_returns_from_billdtl(
        lc,
        from_date=fd,
        to_date=td,
        counter_code=cc,
        shift_code=sc,
        db_key=db_key,
    )
    total_cancel = _sum_pos_canceled_bill_amount_for_scope(
        lc,
        from_date=fd,
        to_date=td,
        counter_code=cc,
        db_key=db_key,
    )
    tender_info = _build_pos_tender_breakdown_for_bills(lc, bill_rows, bill_nos)
    return {
        'ok': True,
        'location_code': lc,
        'from_date': fd.isoformat() if hasattr(fd, 'isoformat') else str(fd)[:10],
        'to_date': td.isoformat() if hasattr(td, 'isoformat') else str(td)[:10],
        'counter_code': cc,
        'shift_code': sc,
        'bill_count': len(bill_nos),
        'direct_customer': round(direct_customer, 2),
        'credit_sales': round(credit_sales, 2),
        'total_sales': round(total_sales, 2),
        'total_discount': round(total_discount, 2),
        'sales_returns': round(sales_returns, 2),
        'total_cancel': round(total_cancel, 2),
        'cash_in_box': tender_info['cash_in_box'],
        'card_total': tender_info['card_total'],
        'wallet_total': tender_info['wallet_total'],
        'tender_breakdown': tender_info['tender_breakdown'],
    }


def get_locations_list(_db_key_ignored: Any=None) -> List[Dict[str, Any]]:
    """Get location list from LOCATIONMASTER (single database)."""
    query = f'\n        SELECT LOCATIONCODE AS code, LOCATIONNAME AS name\n        FROM {LOCATIONS_TABLE}\n        ORDER BY LOCATIONNAME\n    '
    return _safe_rows(query, {})

def get_base_locations_list(_db_key_ignored: Any=None) -> List[Dict[str, Any]]:
    """Branches from ``LOCATIONMASTER`` where ``BASELOCATIONFLAG`` is ``Y`` (tenant DB). Ordered by ``LOCATIONCODE``."""
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    try:
        if not _table_exists(tbl):
            return []
    except Exception:
        return []
    try:
        cols = {str(c or '').upper() for c in (_get_table_columns(tbl) or [])}
    except Exception:
        return []
    if 'LOCATIONCODE' not in cols:
        return []
    flag_col = None
    for candidate in ('BASELOCATIONFLAG', 'BASE_LOCATION_FLAG'):
        if candidate in cols:
            flag_col = candidate
            break
    if not flag_col:
        return []
    q = f"\n        SELECT LOCATIONCODE AS code, LOCATIONNAME AS name\n        FROM {tbl}\n        WHERE NVL(TRIM({flag_col}), 'N') = 'Y'\n        ORDER BY LOCATIONCODE\n    "
    rows = _safe_rows(q, {}) or []
    out: List[Dict[str, Any]] = []
    for r in rows:
        rl = {str(k).lower(): v for k, v in (r.items() if hasattr(r, 'items') else [])}
        code = rl.get('code')
        name = rl.get('name')
        out.append({'code': code, 'name': str(name).strip() if name is not None else ''})
    return out

def list_location_master_rows(_db_key_ignored: Any=None) -> List[Dict[str, Any]]:
    """
    Full rows from ``LOCATIONMASTER`` (tenant DB), all columns detected at runtime.
    Ordered by LOCATIONCODE when present.
    """
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    try:
        if not _table_exists(tbl):
            return []
    except Exception:
        return []
    try:
        cols = _get_table_columns(tbl)
    except Exception:
        return []
    if not cols:
        return []
    col_sql = ', '.join(cols)
    order_col = 'LOCATIONCODE' if 'LOCATIONCODE' in cols else cols[0]
    q = f'SELECT {col_sql} FROM {tbl} ORDER BY {order_col}'
    rows = _safe_rows(q, {})
    return rows or []

def get_location_master_row(locationcode: Any, _db_key_ignored: Any=None) -> Optional[Dict[str, Any]]:
    """Single LOCATIONMASTER row by LOCATIONCODE."""
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    if not _table_exists(tbl) or 'LOCATIONCODE' not in _get_table_columns(tbl):
        return None
    cols = _get_table_columns(tbl)
    col_sql = ', '.join(cols)
    q = f'SELECT {col_sql} FROM {tbl} WHERE LOCATIONCODE = :lc'
    rows = _safe_rows(q, {'lc': locationcode})
    if not rows:
        return None
    return rows[0]

def get_location_master_name_by_code(location_code: Any, db_key: Optional[str]=None) -> str:
    """LOCATIONNAME from LOCATIONMASTER for the given LOCATIONCODE."""
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return ''
    row = get_location_master_row(lc, db_key)
    if not row:
        return ''
    return str(row.get('locationname') or row.get('LOCATIONNAME') or '').strip()


def enrich_location_details_with_branch_logo(
    location_details: Optional[Dict[str, Any]],
    location_code: Optional[Any] = None,
) -> Dict[str, Any]:
    """Attach branch logo_path / logo_url from LOCATIONMASTER for receipt print."""
    out = dict(location_details or {})
    lc = location_code if location_code is not None else out.get('locationcode')
    logo_rel = ''
    try:
        lc_i = int(lc) if lc is not None and str(lc).strip() != '' else None
    except (TypeError, ValueError):
        lc_i = None
    if lc_i is not None:
        row = get_location_master_row(lc_i)
        if row:
            logo_rel = str(row.get('logo_path') or row.get('LOGO_PATH') or '').strip()
    if logo_rel:
        out['logo_path'] = logo_rel
        out['logo_url'] = '/static/' + logo_rel.lstrip('/')
    return out

def _location_master_editable_columns() -> List[str]:
    """Columns we allow updating (PK LOCATIONCODE excluded). Uses live table minus primary key."""
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    try:
        if not _table_exists(tbl):
            return []
    except Exception:
        return []
    try:
        cols = set(_get_table_columns(tbl))
    except Exception:
        return []
    exclude = {'LOCATIONCODE'}
    return [c for c in sorted(cols) if c not in exclude]

def ensure_itemmaster_store_column_default_store1(_db_key_ignored: Any=None) -> None:
    """Legacy no-op — use :func:`ensure_itemmaster_default_warehouse_id_column` instead of STORE."""
    ensure_itemmaster_default_warehouse_id_column(_db_key_ignored)


def ensure_itemmaster_default_warehouse_id_column(_db_key_ignored: Any=None) -> None:
    """Ensure ITEMMASTER has ``DEFAULT_WAREHOUSE_ID`` (FK to ``WAREHOUSE_MASTER``); migrate/drop legacy ``STORE``."""
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return
    wm_tbl = resolve_warehouse_master_table(_db_key_ignored)
    try:
        cols = {c.upper() for c in _get_table_columns(im) or []}
    except Exception:
        return
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if 'DEFAULT_WAREHOUSE_ID' not in cols:
                    try:
                        cur.execute(f'ALTER TABLE {im} ADD (DEFAULT_WAREHOUSE_ID NUMBER)')
                        _invalidate_itemmaster_detail_select_cache()
                    except Exception as e:
                        print(f'[ensure_itemmaster_default_warehouse_id_column] add column: {e}')
                        return
                if wm_tbl and 'STORE' in cols:
                    cur.execute(f"""
                        UPDATE {im} im SET DEFAULT_WAREHOUSE_ID = (
                            SELECT wm.WAREHOUSE_ID FROM {wm_tbl} wm
                            WHERE UPPER(TRIM(wm.WAREHOUSE_CODE)) = UPPER(TRIM(im.STORE))
                              AND ROWNUM = 1
                        )
                        WHERE im.DEFAULT_WAREHOUSE_ID IS NULL AND im.STORE IS NOT NULL
                    """)
                if wm_tbl and 'LOCATIONCODE' in cols:
                    cur.execute(f"""
                        UPDATE {im} im SET DEFAULT_WAREHOUSE_ID = (
                            SELECT MIN(wm.WAREHOUSE_ID) FROM {wm_tbl} wm
                            WHERE wm.LOCATIONCODE = im.LOCATIONCODE AND NVL(wm.IS_ACTIVE, 'Y') = 'Y'
                        )
                        WHERE im.DEFAULT_WAREHOUSE_ID IS NULL
                          AND EXISTS (
                            SELECT 1 FROM {wm_tbl} wm2
                            WHERE wm2.LOCATIONCODE = im.LOCATIONCODE AND NVL(wm2.IS_ACTIVE, 'Y') = 'Y'
                          )
                    """)
                if 'STORE' in cols:
                    try:
                        cur.execute(f'ALTER TABLE {im} SET UNUSED COLUMN STORE')
                        cur.execute(f'ALTER TABLE {im} DROP UNUSED COLUMNS')
                    except Exception as e:
                        try:
                            cur.execute(f'ALTER TABLE {im} DROP COLUMN STORE')
                        except Exception as e2:
                            print(f'[ensure_itemmaster_default_warehouse_id_column] drop STORE: {e}; {e2}')
            conn.commit()
        k = im.upper()
        _TABLE_COLUMNS_CACHE.pop(k, None)
    except Exception as e:
        print(f'[ensure_itemmaster_default_warehouse_id_column] {e}')

def _ensure_table_column(tbl: str, column: str, ddl: str) -> None:
    """Add one column when missing; refresh column cache on success."""
    if not tbl or not column:
        return
    try:
        cols = {c.upper() for c in _get_table_columns(tbl) or []}
    except Exception:
        return
    if column.upper() in cols:
        return
    if not cols and _table_has_column_direct(tbl, column):
        try:
            _TABLE_COLUMNS_CACHE[tbl.upper()] = _query_user_tab_columns(tbl.upper())
        except Exception:
            _TABLE_COLUMNS_CACHE.pop(tbl.upper(), None)
        return
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(ddl)
            conn.commit()
        cols_fresh = _query_user_tab_columns(tbl.upper())
        if cols_fresh:
            _TABLE_COLUMNS_CACHE[tbl.upper()] = cols_fresh
        else:
            _TABLE_COLUMNS_CACHE.pop(tbl.upper(), None)
    except Exception as e:
        err = str(e)
        if 'ORA-01430' in err or '01430' in err:
            cols_fresh = _query_user_tab_columns(tbl.upper())
            if cols_fresh:
                _TABLE_COLUMNS_CACHE[tbl.upper()] = cols_fresh
            else:
                _TABLE_COLUMNS_CACHE.pop(tbl.upper(), None)
            return
        print(f'[_ensure_table_column] {tbl}.{column}: {e}')

def _drop_table_column(tbl: str, column: str) -> None:
    """Drop a column when present (SET UNUSED then DROP for Oracle)."""
    if not tbl or not column:
        return
    try:
        cols = {c.upper() for c in _get_table_columns(tbl) or []}
    except Exception:
        return
    if column.upper() not in cols:
        return
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                try:
                    cur.execute(f'ALTER TABLE {tbl} DROP COLUMN {column}')
                except Exception as e1:
                    try:
                        cur.execute(f'ALTER TABLE {tbl} SET UNUSED COLUMN {column}')
                        cur.execute(f'ALTER TABLE {tbl} DROP UNUSED COLUMNS')
                    except Exception as e2:
                        print(f'[_drop_table_column] {tbl}.{column}: {e1}; {e2}')
                        return
            conn.commit()
        _TABLE_COLUMNS_CACHE.pop(tbl.upper(), None)
    except Exception as e:
        print(f'[_drop_table_column] {tbl}.{column}: {e}')

