def ensure_lpodtl_po_form_columns(_db_key_ignored: Any=None) -> None:
    """``LPODTL``: FOC, ``WAREHOUSE_ID``; ensure line barcode column (MANUFACTURERID or BARCODE)."""
    dtl = _detect_table(['LPODTL', 'lpodtl'])
    if not dtl:
        return
    for col, typ in _LPODTL_PO_FORM_COLUMNS:
        _ensure_table_column(dtl, col, f'ALTER TABLE {dtl} ADD ({col} {typ})')
