def update_location_master_row(locationcode: Any, updates: Dict[str, Any], _db_key_ignored: Any=None) -> Tuple[bool, str]:
    """
    Update one LOCATIONMASTER row. ``updates`` keys: uppercase or lowercase column names.
    Only columns present in the table and not LOCATIONCODE are applied.
    """
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    if not _table_exists(tbl) or 'LOCATIONCODE' not in _get_table_columns(tbl):
        return (False, 'LOCATIONMASTER table or LOCATIONCODE column not found.')
    allow = {x.upper(): x.upper() for x in _location_master_editable_columns()}
    if not allow:
        return (False, 'No editable columns.')
    pairs: List[str] = []
    params: Dict[str, Any] = {'pk_lc': locationcode}
    for raw_k, raw_v in (updates or {}).items():
        k = str(raw_k or '').strip().upper()
        if k not in allow:
            continue
        vn = 'v_' + k.lower()
        v = raw_v
        if v is not None:
            if isinstance(v, str):
                v_st = v.strip()
                params[vn] = v_st if v_st != '' else None
            else:
                params[vn] = v
        else:
            params[vn] = None
        pairs.append(f'{k} = :{vn}')
    if not pairs:
        return (False, 'Nothing to update.')
    set_sql = ', '.join(pairs)
    sql = f'UPDATE {tbl} SET {set_sql} WHERE LOCATIONCODE = :pk_lc'
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(sql, params)
            conn.commit()
        wh_flag = str((updates or {}).get('WAREHOUSE_ENABLE') if isinstance(updates, dict) else '').strip().upper()
        if not wh_flag:
            wh_flag = str((updates or {}).get('warehouse_enable') if isinstance(updates, dict) else '').strip().upper()
        if wh_flag == 'Y':
            ensure_itemmaster_default_warehouse_id_column()
        return (True, '')
    except Exception as e:
        return (False, str(e))

def suggest_next_location_code(_db_key_ignored: Any=None) -> Optional[Any]:
    """Next LOCATIONCODE suggestion: MAX(LOCATIONCODE)+1, or ``None`` if unavailable."""
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    try:
        if not _table_exists(tbl) or 'LOCATIONCODE' not in _get_table_columns(tbl):
            return None
    except Exception:
        return None
    q = f'SELECT NVL(MAX(LOCATIONCODE), 0) + 1 AS n FROM {tbl}'
    rows = _safe_rows(q, {})
    if not rows:
        return 1
    n = rows[0].get('n')
    if n is None:
        return 1
    try:
        if float(n) == int(float(n)):
            return int(float(n))
        return float(n)
    except (TypeError, ValueError):
        return n

def insert_location_master_row(values: Dict[str, Any], _db_key_ignored: Any=None) -> Tuple[bool, str]:
    """
    Insert one LOCATIONMASTER row. ``values`` keys: uppercase or lowercase column names.
    ``LOCATIONCODE`` is required; other columns optional (NULL when blank).
    """
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    if not _table_exists(tbl) or 'LOCATIONCODE' not in _get_table_columns(tbl):
        return (False, 'LOCATIONMASTER table or LOCATIONCODE column not found.')
    try:
        cols_upper = set(_get_table_columns(tbl))
    except Exception:
        return (False, 'Could not read table columns.')
    row: Dict[str, Any] = {}
    for raw_k, raw_v in (values or {}).items():
        k = str(raw_k or '').strip().upper()
        if k not in cols_upper:
            continue
        if raw_v is not None:
            if isinstance(raw_v, str):
                vs = raw_v.strip()
                row[k] = vs if vs != '' else None
            else:
                row[k] = raw_v
        else:
            row[k] = None
    if 'LOCATIONCODE' not in row or row['LOCATIONCODE'] is None:
        return (False, 'LOCATIONCODE is required.')
    lc_val = row['LOCATIONCODE']
    if isinstance(lc_val, str) and str(lc_val).strip() == '':
        return (False, 'LOCATIONCODE is required.')
    if isinstance(lc_val, str):
        try:
            row['LOCATIONCODE'] = int(lc_val.strip()) if '.' not in lc_val.strip() else float(lc_val.strip())
        except (ValueError, TypeError):
            pass
    col_list = sorted(row.keys(), key=lambda x: (0 if x == 'LOCATIONCODE' else 1, x))
    placeholders: List[str] = []
    params: Dict[str, Any] = {}
    for k in col_list:
        vn = 'v_' + k.lower()
        placeholders.append(':' + vn)
        params[vn] = row[k]
    cols_sql = ', '.join(col_list)
    ph_sql = ', '.join(placeholders)
    sql = f'INSERT INTO {tbl} ({cols_sql}) VALUES ({ph_sql})'
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(sql, params)
            conn.commit()
        wh_flag = str((row or {}).get('WAREHOUSE_ENABLE') or '').strip().upper()
        if wh_flag == 'Y':
            ensure_itemmaster_default_warehouse_id_column()
        return (True, '')
    except Exception as e:
        return (False, str(e))
SUPPLIER_TABLE = 'SUPPLIER'

def _supplier_table_exists() -> bool:
    return _table_exists(SUPPLIER_TABLE)

def ensure_supplier_table() -> None:
    """Create SUPPLIER table with standard vendor master structure if missing."""
    with _get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) FROM user_tables WHERE table_name = 'SUPPLIER'")
            table_exists = int(cur.fetchone()[0] or 0) > 0
            ddl_with_tablespace = "\n                CREATE TABLE SUPPLIER\n                (\n                  LOCATIONCODE      NUMBER(2),\n                  SUPPLIERCODE      NUMBER(5),\n                  SUPPLIERNAME      VARCHAR2(40 BYTE) NOT NULL,\n                  SUPPLIERTYPE      VARCHAR2(25 BYTE),\n                  ADDRESS           VARCHAR2(200 BYTE),\n                  TELEPHONE         VARCHAR2(15 BYTE),\n                  FAX               VARCHAR2(15 BYTE),\n                  MOBILE            VARCHAR2(15 BYTE),\n                  EMAILID           VARCHAR2(150 BYTE),\n                  CONTACTPERSON     VARCHAR2(40 BYTE),\n                  SUPPLIERID        CHAR(3 BYTE),\n                  ACCOUNTCODE       NUMBER(10),\n                  PAYABLEACCOUNT    NUMBER(10),\n                  FLAG              CHAR(1 BYTE),\n                  SUPPLIERLOCATION  VARCHAR2(30 BYTE),\n                  SUPREF            VARCHAR2(50 BYTE),\n                  SUPPLIERCR        VARCHAR2(250 BYTE),\n                  PURCHASEACCOUNT   NUMBER(10),\n                  VATINPUTACCOUNT   NUMBER(10),\n                  ADVANCEACCOUNT    NUMBER(10),\n                  CREATIONFLAG      CHAR(1 BYTE) DEFAULT 'B' NOT NULL\n                )\n                TABLESPACE USERS\n            "
            ddl_without_tablespace = "\n                CREATE TABLE SUPPLIER\n                (\n                  LOCATIONCODE      NUMBER(2),\n                  SUPPLIERCODE      NUMBER(5),\n                  SUPPLIERNAME      VARCHAR2(40 BYTE) NOT NULL,\n                  SUPPLIERTYPE      VARCHAR2(25 BYTE),\n                  ADDRESS           VARCHAR2(200 BYTE),\n                  TELEPHONE         VARCHAR2(15 BYTE),\n                  FAX               VARCHAR2(15 BYTE),\n                  MOBILE            VARCHAR2(15 BYTE),\n                  EMAILID           VARCHAR2(150 BYTE),\n                  CONTACTPERSON     VARCHAR2(40 BYTE),\n                  SUPPLIERID        CHAR(3 BYTE),\n                  ACCOUNTCODE       NUMBER(10),\n                  PAYABLEACCOUNT    NUMBER(10),\n                  FLAG              CHAR(1 BYTE),\n                  SUPPLIERLOCATION  VARCHAR2(30 BYTE),\n                  SUPREF            VARCHAR2(50 BYTE),\n                  SUPPLIERCR        VARCHAR2(250 BYTE),\n                  PURCHASEACCOUNT   NUMBER(10),\n                  VATINPUTACCOUNT   NUMBER(10),\n                  ADVANCEACCOUNT    NUMBER(10),\n                  CREATIONFLAG      CHAR(1 BYTE) DEFAULT 'B' NOT NULL\n                )\n            "
            if not table_exists:
                try:
                    cur.execute(ddl_with_tablespace)
                except Exception as exc:
                    msg = str(exc).upper()
                    if 'TABLESPACE' in msg or 'ORA-00959' in msg or 'ORA-01536' in msg:
                        cur.execute(ddl_without_tablespace)
                    else:
                        raise
            cols = _get_table_columns(SUPPLIER_TABLE)
            cols_changed = False
            if 'PAYABLEACCOUNT' not in cols:
                cur.execute('ALTER TABLE SUPPLIER ADD PAYABLEACCOUNT NUMBER(10)')
                cur.execute('UPDATE SUPPLIER SET PAYABLEACCOUNT = ACCOUNTCODE WHERE PAYABLEACCOUNT IS NULL')
                cols_changed = True
            if 'PURCHASEACCOUNT' not in cols:
                cur.execute('ALTER TABLE SUPPLIER ADD PURCHASEACCOUNT NUMBER(10)')
                cols_changed = True
            if 'VATINPUTACCOUNT' not in cols:
                cur.execute('ALTER TABLE SUPPLIER ADD VATINPUTACCOUNT NUMBER(10)')
                cols_changed = True
            if 'ADVANCEACCOUNT' not in cols:
                cur.execute('ALTER TABLE SUPPLIER ADD ADVANCEACCOUNT NUMBER(10)')
                cols_changed = True
            if cols_changed:
                _TABLE_COLUMNS_CACHE.pop(SUPPLIER_TABLE.upper(), None)
        conn.commit()

def get_supplier_list(location_code: Optional[int]=None, search: Optional[str]=None, limit: int=100, row_cap: int=1000) -> List[Dict[str, Any]]:
    """Get supplier list from SUPPLIER; optional location and search."""
    if not _supplier_table_exists():
        return []
    loc_col = _detect_column(SUPPLIER_TABLE, ['LOCATIONCODE', 'locationcode'])
    code_col = _detect_column(SUPPLIER_TABLE, ['SUPPLIERCODE', 'suppliercode'])
    name_col = _detect_column(SUPPLIER_TABLE, ['SUPPLIERNAME', 'suppliername'])
    type_col = _detect_column(SUPPLIER_TABLE, ['SUPPLIERTYPE', 'suppliertype'])
    contact_col = _detect_column(SUPPLIER_TABLE, ['CONTACTPERSON', 'contactperson'])
    payable_col = _detect_column(SUPPLIER_TABLE, ['PAYABLEACCOUNT', 'payableaccount'])
    purchase_col = _detect_column(SUPPLIER_TABLE, ['PURCHASEACCOUNT', 'purchaseaccount'])
    vatinput_col = _detect_column(SUPPLIER_TABLE, ['VATINPUTACCOUNT', 'vatinputaccount'])
    advance_col = _detect_column(SUPPLIER_TABLE, ['ADVANCEACCOUNT', 'advanceaccount'])
    if not code_col or not name_col:
        return []
    select_parts = [f'{loc_col} AS locationcode', f'{code_col} AS suppliercode', f'{name_col} AS suppliername', f'{type_col} AS suppliertype' if type_col else 'NULL AS suppliertype', f'{contact_col} AS contactperson' if contact_col else 'NULL AS contactperson', f'{payable_col} AS payableaccount' if payable_col else 'NULL AS payableaccount', f'{purchase_col} AS purchaseaccount' if purchase_col else 'NULL AS purchaseaccount', f'{vatinput_col} AS vatinputaccount' if vatinput_col else 'NULL AS vatinputaccount', f'{advance_col} AS advanceaccount' if advance_col else 'NULL AS advanceaccount']
    where_parts = []
    params: Dict[str, Any] = {}
    if location_code is not None and loc_col:
        where_parts.append(f'{loc_col} = :location_code')
        params['location_code'] = location_code
    if search and search.strip():
        search_term = f'%{search.strip()}%'
        params['search_name'] = search_term
        params['search_code'] = search_term
        where_parts.append(f'(UPPER({name_col}) LIKE UPPER(:search_name) OR TO_CHAR({code_col}) LIKE :search_code)')
    where_sql = ' WHERE ' + ' AND '.join(where_parts) if where_parts else ''
    _cap = max(1, int(row_cap) if int(row_cap) > 0 else 1000)
    limit_val = max(1, min(int(limit), _cap))
    params['row_limit'] = limit_val
    order_col = loc_col or code_col
    inner = f"\n        SELECT {', '.join(select_parts)}\n        FROM {SUPPLIER_TABLE}\n        {where_sql}\n        ORDER BY {order_col} DESC, {code_col} DESC\n    "
    query = f'SELECT * FROM ({inner}) WHERE ROWNUM <= :row_limit'
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except Exception as e:
        print(f'[ERROR get_supplier_list] {e}')
        return []

def get_customers_for_journal_party_select(limit: int=20000) -> List[Dict[str, Any]]:
    """Customers with receivable GL for journal line picker (CUSTOMER party + receivable A/c)."""
    default_recv = str(DEFAULT_PARTY_ACCOUNTS.get('customer_receivable') or '1200').strip()
    table_candidates = ['CUSTOMER', 'CUSTOMERS', 'customer', 'customers']
    limit_val = max(1, min(int(limit), 20000))
    for table_name in table_candidates:
        if not _table_exists(table_name):
            continue
        code_col = _detect_column(table_name, ['CUSTOMERCODE', 'CUST_CODE', 'CUSTOMER_CODE', 'CODE', 'code'])
        name_col = _detect_column(table_name, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME', 'name'])
        recv_col = _detect_column(table_name, ['RECEIVABLEACCOUNT', 'receivableaccount', 'RECEIVABLE_AC', 'receivable_acct'])
        if not code_col or not name_col:
            continue
        name_sql = f'c.{name_col}'
        if recv_col:
            recv_expr = f'TRIM(TO_CHAR(c.{recv_col}))'
        else:
            recv_expr = 'NULL'
        query = f'\n            SELECT\n                c.{code_col} AS customercode,\n                {name_sql} AS customername,\n                {recv_expr} AS receivableaccount\n            FROM {table_name} c\n            WHERE c.{code_col} IS NOT NULL\n            ORDER BY c.{code_col}\n        '
        q2 = f'SELECT * FROM ({query}) WHERE ROWNUM <= :row_limit'
        try:
            _, rows = _fetch_rows(q2, {'row_limit': limit_val})
            out: List[Dict[str, Any]] = []
            for r in rows or []:
                code = r.get('customercode')
                if code is None:
                    continue
                sc = str(code).strip()
                if not sc:
                    continue
                ra = str(r.get('receivableaccount') or default_recv).strip() or default_recv
                out.append({'customercode': sc, 'customername': str(r.get('customername') or '').strip(), 'receivableaccount': ra[:COA_CODE_MAX_LEN]})
            if out:
                return out
        except Exception as e:
            print(f'[ERROR get_customers_for_journal_party_select] {e}')
            continue
    return []

def get_next_supplier_code(location_code: Optional[int]=None) -> int:
    """Next supplier code = MAX(SUPPLIERCODE) + 1. If location given, max per location; else global max."""
    if not _supplier_table_exists():
        return 1
    loc_col = _detect_column(SUPPLIER_TABLE, ['LOCATIONCODE', 'locationcode'])
    code_col = _detect_column(SUPPLIER_TABLE, ['SUPPLIERCODE', 'suppliercode'])
    if not code_col:
        return 1
    if location_code is not None and loc_col:
        query = f'\n            SELECT NVL(MAX({code_col}), 0) + 1 AS nextcode\n            FROM {SUPPLIER_TABLE}\n            WHERE {loc_col} = :location_code\n        '
        params: Dict[str, Any] = {'location_code': location_code}
    else:
        query = f'SELECT NVL(MAX({code_col}), 0) + 1 AS nextcode FROM {SUPPLIER_TABLE}'
        params = {}
    try:
        _, rows = _fetch_rows(query, params)
        if rows and rows[0].get('nextcode') is not None:
            return int(rows[0]['nextcode'])
    except Exception as e:
        print(f'[ERROR get_next_supplier_code] {e}')
    return 1

def get_supplier_by_code(location_code: int, supplier_code: int) -> Optional[Dict[str, Any]]:
    """Get one supplier by location and supplier code."""
    if not _supplier_table_exists():
        return None
    loc_col = _detect_column(SUPPLIER_TABLE, ['LOCATIONCODE', 'locationcode'])
    code_col = _detect_column(SUPPLIER_TABLE, ['SUPPLIERCODE', 'suppliercode'])
    if not loc_col or not code_col:
        return None
    cols = _get_table_columns(SUPPLIER_TABLE)
    select_parts = []
    for c in [
        'LOCATIONCODE',
        'SUPPLIERCODE',
        'SUPPLIERNAME',
        'SUPPLIERTYPE',
        'SUPPLIER_BILLING_TYPE',
        'ADDRESS',
        'TELEPHONE',
        'FAX',
        'MOBILE',
        'EMAILID',
        'CONTACTPERSON',
        'SUPPLIERID',
        'ACCOUNTCODE',
        'PAYABLEACCOUNT',
        'PURCHASEACCOUNT',
        'VATINPUTACCOUNT',
        'ADVANCEACCOUNT',
        'FLAG',
        'SUPPLIERLOCATION',
        'SUPREF',
        'SUPPLIERCR',
        'CREATIONFLAG',
    ]:
        if c in cols:
            select_parts.append(f'{c} AS {c.lower()}')
    if not select_parts:
        select_parts = [f'{loc_col} AS locationcode', f'{code_col} AS suppliercode', f"{_detect_column(SUPPLIER_TABLE, ['SUPPLIERNAME', 'suppliername'])} AS suppliername"]
    query = f"\n        SELECT {', '.join(select_parts)}\n        FROM {SUPPLIER_TABLE}\n        WHERE {loc_col} = :location_code AND {code_col} = :supplier_code\n    "
    try:
        _, rows = _fetch_rows(query, {'location_code': location_code, 'supplier_code': supplier_code})
        return rows[0] if rows else None
    except Exception as e:
        print(f'[ERROR get_supplier_by_code] {e}')
        return None

