def update_tenant(tenant_id: str, ip: str, port: str, service_name: str, display_name: Optional[str]=None, network_link: Optional[str]=None, username: Optional[str]=None, password: Optional[str]=None, logo_path: Optional[str]=None, locationcode: Optional[int]=None, active_flag: str='Y') -> None:
    """Update tenant_databases row. Password None keeps current; logo_path None keeps current."""
    tid = (tenant_id or '').strip()
    if not tid:
        raise ValueError('Tenant ID is required.')
    if not (ip or '').strip():
        raise ValueError('IP is required.')
    if not (port or '').strip():
        raise ValueError('Port is required.')
    if not (service_name or '').strip():
        raise ValueError('Service name is required.')
    if active_flag not in ('Y', 'N'):
        active_flag = 'Y'
    if not tenant_exists(tid):
        raise ValueError('Tenant does not exist.')
    ensure_tenant_databases_table()
    try:
        with _get_connection_auth() as conn:
            with conn.cursor() as cur:
                if password is not None:
                    cur.execute('UPDATE tenant_databases SET\n                        ip = :ip, port = :port, service_name = :svc, username = :u, password = :p,\n                        display_name = :dname, network_link = :nlink, logo_path = NVL(:logo, logo_path), active_flag = :act, locationcode = :loc\n                       WHERE tenant_id = :tid', {'tid': tid, 'ip': (ip or '').strip(), 'port': (port or '').strip(), 'svc': (service_name or '').strip(), 'u': (username or '').strip() or None, 'p': (password or '').strip() or None, 'dname': (display_name or '').strip() or None, 'nlink': (network_link or '').strip() or None, 'logo': (logo_path or '').strip() or None, 'act': active_flag, 'loc': locationcode})
                else:
                    cur.execute('UPDATE tenant_databases SET\n                        ip = :ip, port = :port, service_name = :svc, username = :u,\n                        display_name = :dname, network_link = :nlink, logo_path = NVL(:logo, logo_path), active_flag = :act, locationcode = :loc\n                       WHERE tenant_id = :tid', {'tid': tid, 'ip': (ip or '').strip(), 'port': (port or '').strip(), 'svc': (service_name or '').strip(), 'u': (username or '').strip() or None, 'dname': (display_name or '').strip() or None, 'nlink': (network_link or '').strip() or None, 'logo': (logo_path or '').strip() or None, 'act': active_flag, 'loc': locationcode})
            conn.commit()
    except cx_Oracle.DatabaseError as exc:
        _raise_friendly_tenant_save_error(exc)
    _tenant_config_cache.pop(tid, None)
    global _TENANT_LIST_CACHE
    _TENANT_LIST_CACHE = None

def get_tenant_list() -> List[Dict[str, Any]]:
    """Return list of tenants for dropdown (tenant_id, display_name, locationcode when available). Uses tenant_databases table."""
    global _TENANT_LIST_CACHE
    import time as _time
    now = _time.time()
    if _TENANT_LIST_CACHE is not None:
        cached_at, cached_rows = _TENANT_LIST_CACHE
        if (now - cached_at) < _TENANT_LIST_CACHE_TTL_SEC:
            return cached_rows
    ensure_tenant_databases_table()
    try:
        rows = _safe_rows_auth("\n            SELECT tenant_id,\n                   NVL(display_name, tenant_id) AS display_name,\n                   locationcode\n            FROM tenant_databases\n            WHERE NVL(active_flag, 'Y') = 'Y'\n            ORDER BY tenant_id\n            ", {})
        _TENANT_LIST_CACHE = (now, rows)
        return rows
    except Exception:
        try:
            rows = _safe_rows_auth("SELECT tenant_id, NVL(display_name, tenant_id) AS display_name FROM tenant_databases WHERE NVL(active_flag, 'Y') = 'Y' ORDER BY tenant_id", {})
            for r in rows:
                if 'locationcode' not in r:
                    r['locationcode'] = None
            _TENANT_LIST_CACHE = (now, rows)
            return rows
        except Exception:
            try:
                rows = _safe_rows_auth("SELECT tenant_id FROM tenant_databases WHERE NVL(active_flag, 'Y') = 'Y' ORDER BY tenant_id", {})
                out = [{'tenant_id': r['tenant_id'], 'display_name': r['tenant_id'], 'locationcode': None} for r in rows]
                _TENANT_LIST_CACHE = (now, out)
                return out
            except Exception:
                return []

