def get_tenant_locationcode_from_auth(tenant_id: str) -> Optional[int]:
    """Return LOCATIONCODE for ``tenant_id`` from auth ``tenant_databases`` (> 0), or None."""
    tid = (tenant_id or '').strip()
    if not tid:
        return None
    ensure_tenant_databases_table()
    try:
        rows = _safe_rows_auth('SELECT locationcode FROM tenant_databases WHERE tenant_id = :tid', {'tid': tid})
        if not rows:
            return None
        raw = rows[0].get('locationcode')
        if raw is None:
            return None
        try:
            n = int(raw)
        except (TypeError, ValueError):
            try:
                n = int(float(str(raw).strip()))
            except (TypeError, ValueError):
                return None
        return n if n > 0 else None
    except Exception:
        return None

def ensure_default_admin() -> None:
    if not user_exists('admin'):
        create_user('admin', 'admin123', 'ADMIN', 'N')

def ensure_initial_app_admin(login_username: Optional[str]=None, login_password: Optional[str]=None) -> None:
    """
    Create the first ``login_users`` row after schema bootstrap.

    If ``login_username`` is omitted or blank, behaves like :func:`ensure_default_admin`
    (``admin`` / ``admin123`` when no ``admin`` user exists).

    If username and password are given, creates that user with employee code ``ADMIN`` when the
    user does not yet exist (no-op when the username already exists).
    """
    u = (login_username or '').strip()
    if u:
        p = login_password if login_password is not None else ''
        if not (p or '').strip():
            raise ValueError('Initial application login password is required when a username is set.')
        if user_exists(u):
            return
        create_user(u, p, 'ADMIN', 'N')
        return
    ensure_default_admin()

def user_exists(username: str) -> bool:
    query = 'SELECT 1 FROM login_users WHERE username = :username'
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute(query, {'username': username})
            return cur.fetchone() is not None

def create_user(username: str, password: str, employeecode: str, needcounter: str='N', tenant_id: Optional[str]=None, multilocations_view: str='N', transit_only: str='N', customer_creation: str='N', allowed_tenant_ids: Optional[str]=None, *, default_wh_sales: Optional[int]=None, default_wh_sales_return: Optional[int]=None, default_wh_purchase: Optional[int]=None, default_wh_purchase_return: Optional[int]=None) -> None:
    if not username or not password:
        raise ValueError('Username and password are required.')
    if not employeecode:
        raise ValueError('Employee Code is required.')
    if employeecode.upper() != 'ADMIN' and (not employeecode.isdigit()):
        raise ValueError('Employee Code must be numeric.')
    if needcounter not in ['Y', 'N']:
        raise ValueError("Need Counter must be 'Y' or 'N'.")
    if multilocations_view not in ['Y', 'N']:
        multilocations_view = 'N'
    if transit_only not in ['Y', 'N']:
        transit_only = 'N'
    if customer_creation not in ['Y', 'N']:
        customer_creation = 'N'
    if user_exists(username):
        raise ValueError('User already exists.')
    if employee_code_exists(employeecode):
        raise ValueError('Employee Code already exists.')
    ensure_login_table()
    password_hash = generate_password_hash(password)
    tenant_val = (tenant_id or '').strip() or None
    mlv = (multilocations_view or 'N').strip().upper() or 'N'
    atai: Optional[str] = None
    if mlv == 'Y' and (allowed_tenant_ids or '').strip():
        atai = (allowed_tenant_ids or '').strip()[:2000] or None
    tov = (transit_only or 'N').strip().upper() or 'N'
    ccr = (customer_creation or 'N').strip().upper() or 'N'
    from db.user_warehouse_prefs import warehouse_prefs_insert_columns, warehouse_prefs_insert_params
    wh_cols_sql, wh_vals_sql = warehouse_prefs_insert_columns()
    wh_params = warehouse_prefs_insert_params({
        'sales': default_wh_sales,
        'sales_return': default_wh_sales_return,
        'purchase': default_wh_purchase,
        'purchase_return': default_wh_purchase_return,
    })
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute(
                f"INSERT INTO login_users (username, password_hash, employeecode, active_flag, needcounter, tenant_id, multilocations_view, transit_only, customer_creation, allowed_tenant_ids, {wh_cols_sql}) "
                f"VALUES (:u, :p, :e, 'Y', :nc, :tid, :mlv, :tov, :ccr, :atai, {wh_vals_sql})",
                {'u': username, 'p': password_hash, 'e': employeecode, 'nc': needcounter, 'tid': tenant_val, 'mlv': mlv, 'tov': tov, 'ccr': ccr, 'atai': atai, **wh_params},
            )
        conn.commit()

def employee_code_exists(employeecode: str) -> bool:
    query = 'SELECT 1 FROM login_users WHERE employeecode = :employeecode'
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute(query, {'employeecode': employeecode})
            return cur.fetchone() is not None

def get_user_tenant_id(username: str) -> Optional[str]:
    """Get tenant_id from login_users or pdt_users (auth DB)."""
    if not (username or '').strip():
        return None
    uname = (username or '').strip()
    try:
        rows = _safe_rows_auth(
            'SELECT tenant_id FROM login_users WHERE UPPER(TRIM(username)) = UPPER(TRIM(:username))',
            {'username': uname},
        )
    except Exception:
        rows = []
    if rows:
        tid = rows[0].get('tenant_id')
        if tid is not None:
            s = (tid.strip() if isinstance(tid, str) else str(tid).strip()) or None
            if s:
                return s
    try:
        from db.pdt_auth import get_pdt_user_tenant_id
        return get_pdt_user_tenant_id(uname)
    except Exception:
        return None

def get_user_dbkey(username: str) -> Optional[str]:
    """Multi-DB: returns tenant_id from login_users. Single DB: returns None."""
    if is_multi_db_mode():
        return get_user_tenant_id(username)
    return None

def ensure_roles_tables() -> None:
    """Ensure ROLES and ROLE_PERMISSIONS tables exist"""
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute("\n                SELECT COUNT(*) FROM user_tables WHERE table_name = 'ROLES'\n            ")
            if cur.fetchone()[0] == 0:
                cur.execute('\n                    CREATE TABLE roles (\n                        role_id VARCHAR2(50) PRIMARY KEY,\n                        role_name VARCHAR2(100) NOT NULL,\n                        description VARCHAR2(500),\n                        created_at DATE DEFAULT SYSDATE,\n                        updated_at DATE DEFAULT SYSDATE\n                    )\n                ')
                conn.commit()
            cur.execute("\n                SELECT COUNT(*) FROM user_tables WHERE table_name = 'ROLE_PERMISSIONS'\n            ")
            if cur.fetchone()[0] == 0:
                cur.execute("\n                    CREATE TABLE role_permissions (\n                        role_id VARCHAR2(50),\n                        menu_path VARCHAR2(200),\n                        permission VARCHAR2(50) DEFAULT 'Y',\n                        PRIMARY KEY (role_id, menu_path),\n                        FOREIGN KEY (role_id) REFERENCES roles(role_id) ON DELETE CASCADE\n                    )\n                ")
                conn.commit()
            cur.execute("\n                SELECT COUNT(*) FROM user_tables WHERE table_name = 'ROLE_QUICK_ACCESS'\n            ")
            if cur.fetchone()[0] == 0:
                cur.execute("\n                    CREATE TABLE role_quick_access (\n                        role_id VARCHAR2(50),\n                        menu_path VARCHAR2(200),\n                        sort_order NUMBER DEFAULT 0,\n                        PRIMARY KEY (role_id, menu_path),\n                        FOREIGN KEY (role_id) REFERENCES roles(role_id) ON DELETE CASCADE\n                    )\n                ")
                conn.commit()
            cur.execute("\n                SELECT column_name\n                FROM user_tab_columns\n                WHERE table_name = 'LOGIN_USERS'\n            ")
            cols = {row[0].upper() for row in cur.fetchall()}
            if 'ROLE_ID' not in cols:
                cur.execute('ALTER TABLE login_users ADD role_id VARCHAR2(50)')
                conn.commit()

def get_user_employeecode(username: str) -> Optional[str]:
    """Get employeecode from login_users or pdt_users (auth DB)."""
    query = 'SELECT employeecode FROM login_users WHERE username = :username'
    rows = _safe_rows_auth(query, {'username': username})
    if rows and rows[0].get('employeecode'):
        return rows[0]['employeecode'].strip() if rows[0]['employeecode'] else None
    try:
        from db.pdt_auth import get_pdt_user_employeecode
        return get_pdt_user_employeecode(username)
    except Exception:
        return None

def get_username_by_employeecode(employeecode: str) -> Optional[str]:
    """Resolve a username from an employee code (ERP or PDT user)."""
    if not (employeecode or '').strip():
        return None
    ec = employeecode.strip()
    rows = _safe_rows_auth(
        "SELECT username FROM login_users\n"
        "           WHERE UPPER(TRIM(employeecode)) = UPPER(TRIM(:ec))\n"
        "             AND NVL(active_flag, 'Y') = 'Y'",
        {'ec': ec},
    )
    if rows:
        return rows[0].get('username')
    try:
        from db.pdt_auth import get_pdt_username_by_employeecode
        return get_pdt_username_by_employeecode(ec)
    except Exception:
        return None

def get_user_needcounter(username: str) -> Optional[str]:
    """Get needcounter from login_users table for a user"""
    query = 'SELECT needcounter FROM login_users WHERE username = :username'
    rows = _safe_rows_auth(query, {'username': username})
    if not rows:
        return None
    needcounter = rows[0].get('needcounter')
    if needcounter:
        return needcounter.strip().upper()
    return 'N'

def get_user_by_username(username: str) -> Optional[Dict[str, Any]]:
    """Get a user's details; ``location`` is derived from Tenants maintenance (tenant_databases.locationcode)."""
    uname = (username or '').strip()
    if not uname:
        return None
    cache_key = uname.upper()
    hit, cached = _req_cache_get('user_by_username', cache_key)
    if hit:
        return cached
    ok, ttl_val = _auth_ttl_get(f'user:{cache_key}')
    if ok:
        _req_cache_set('user_by_username', cache_key, ttl_val)
        return ttl_val
    ensure_login_table()
    ensure_tenant_databases_table()
    from db.user_warehouse_prefs import warehouse_prefs_sql_columns
    wh_sel = warehouse_prefs_sql_columns()
    query = f"\n        SELECT u.username,\n               TRIM(TO_CHAR(td.locationcode)) AS location,\n               u.employeecode,\n               u.role_id,\n               u.active_flag,\n               NVL(u.needcounter, 'N') AS needcounter,\n               u.tenant_id,\n               NVL(u.multilocations_view, 'N') AS multilocations_view,\n               NVL(u.transit_only, 'N') AS transit_only,\n               NVL(u.customer_creation, 'N') AS customer_creation,\n               u.allowed_tenant_ids,\n               {wh_sel}\n        FROM login_users u\n        LEFT JOIN tenant_databases td\n          ON UPPER(TRIM(u.tenant_id)) = UPPER(TRIM(td.tenant_id))\n        WHERE UPPER(TRIM(u.username)) = UPPER(TRIM(:username))\n    "
    rows = _safe_rows_auth(query, {'username': uname})
    row = rows[0] if rows else None
    _auth_ttl_set(f'user:{cache_key}', row)
    _req_cache_set('user_by_username', cache_key, row)
    return row

def get_user_multilocations_view(username: str) -> str:
    """Return 'Y' or 'N' if user is allowed to switch tenant from dashboard. Default 'N'."""
    if not (username or '').strip():
        return 'N'
    try:
        row = get_user_by_username(username.strip())
        if not row:
            return 'N'
        mlv = (row.get('multilocations_view') or 'N').strip().upper()
        return 'Y' if mlv == 'Y' else 'N'
    except Exception:
        return 'N'

def get_user_allowed_tenant_ids(username: str) -> List[str]:
    """
    When non-empty: user may switch only to these tenant_id values (case-insensitive match to master).
    Empty list means no restriction (all tenants configured in Tenants maintenance).
    """
    if not (username or '').strip():
        return []
    try:
        row = get_user_by_username(username.strip())
        if not row:
            return []
        raw = row.get('allowed_tenant_ids')
        if raw is None or (isinstance(raw, str) and (not raw.strip())):
            return []
        parts = [p.strip() for p in str(raw).split(',') if p.strip()]
        out: List[str] = []
        seen = set()
        for p in parts:
            lk = p.lower()
            if lk not in seen:
                seen.add(lk)
                out.append(p)
        return out
    except Exception:
        return []

def get_user_role_id(username: str) -> Optional[str]:
    """Get role_id from login_users or pdt_users (auth DB). Case-insensitive username."""
    if not (username or '').strip():
        return None
    uname = (username or '').strip()
    cache_key = uname.upper()
    hit, cached = _req_cache_get('user_role_id', cache_key)
    if hit:
        return cached
    ok, ttl_val = _auth_ttl_get(f'role_id:{cache_key}')
    if ok:
        _req_cache_set('user_role_id', cache_key, ttl_val)
        return ttl_val
    query = '\n        SELECT role_id FROM login_users\n        WHERE UPPER(TRIM(username)) = UPPER(TRIM(:username))\n    '
    rows = _safe_rows_auth(query, {'username': uname})
    result: Optional[str] = None
    if rows and rows[0].get('role_id'):
        role_id_val = rows[0]['role_id']
        raw = role_id_val.strip() if role_id_val else None
        if raw:
            result = resolve_role_id_canonical(raw)
    else:
        try:
            from db.pdt_auth import get_pdt_user_role_id
            result = get_pdt_user_role_id(uname)
        except Exception:
            result = None
    _auth_ttl_set(f'role_id:{cache_key}', result)
    _req_cache_set('user_role_id', cache_key, result)
    return result

def get_all_roles() -> List[Dict[str, Any]]:
    """Get all roles from ROLES table"""
    query = 'SELECT role_id, role_name, description FROM roles ORDER BY role_name'
    rows = _safe_rows_auth(query, {})
    return rows

def resolve_role_id_canonical(role_id: Optional[str]) -> Optional[str]:
    """Return roles.role_id as stored in DB (trim/case-insensitive match), or None."""
    rid = (role_id or '').strip()
    if not rid:
        return None
    cache_key = rid.upper()
    hit, cached = _req_cache_get('role_canon', cache_key)
    if hit:
        return cached
    ok, ttl_val = _auth_ttl_get(f'role_canon:{cache_key}')
    if ok:
        _req_cache_set('role_canon', cache_key, ttl_val)
        return ttl_val
    rows = _safe_rows_auth('\n        SELECT role_id FROM roles\n        WHERE UPPER(TRIM(role_id)) = UPPER(TRIM(:role_id))\n    ', {'role_id': rid})
    if not rows:
        _auth_ttl_set(f'role_canon:{cache_key}', None)
        _req_cache_set('role_canon', cache_key, None)
        return None
    val = rows[0].get('role_id')
    result = val.strip() if val else None
    _auth_ttl_set(f'role_canon:{cache_key}', result)
    _req_cache_set('role_canon', cache_key, result)
    return result

def get_role_permissions(role_id: str) -> List[str]:
    """Get all menu paths (permissions) for a role (from auth DB)."""
    rid = (role_id or '').strip()
    if not rid:
        return []
    cache_key = rid.upper()
    hit, cached = _req_cache_get('role_perms', cache_key)
    if hit:
        return list(cached) if cached is not None else []
    ok, ttl_val = _auth_ttl_get(f'role_perms:{cache_key}')
    if ok:
        _req_cache_set('role_perms', cache_key, ttl_val)
        return list(ttl_val) if ttl_val is not None else []
    canon = resolve_role_id_canonical(rid)
    if not canon:
        _auth_ttl_set(f'role_perms:{cache_key}', [])
        _req_cache_set('role_perms', cache_key, [])
        return []
    query = "SELECT menu_path FROM role_permissions WHERE role_id = :role_id AND permission = 'Y'"
    rows = _safe_rows_auth(query, {'role_id': canon})
    paths = [row['menu_path'] for row in rows if row.get('menu_path')]
    try:
        from permissions import expand_role_permission_paths
        paths = expand_role_permission_paths(paths)
    except Exception:
        pass
    _auth_ttl_set(f'role_perms:{cache_key}', paths)
    _req_cache_set('role_perms', cache_key, paths)
    return list(paths)

def get_role_quick_access(role_id: str) -> List[str]:
    """Get quick-access menu paths for a role, ordered by sort_order (auth DB)."""
    rid = (role_id or '').strip()
    if not rid:
        return []
    cache_key = rid.upper()
    hit, cached = _req_cache_get('role_qa', cache_key)
    if hit:
        return list(cached) if cached is not None else []
    ok, ttl_val = _auth_ttl_get(f'role_qa:{cache_key}')
    if ok:
        _req_cache_set('role_qa', cache_key, ttl_val)
        return list(ttl_val) if ttl_val is not None else []
    canon = resolve_role_id_canonical(rid)
    if not canon:
        _auth_ttl_set(f'role_qa:{cache_key}', [])
        _req_cache_set('role_qa', cache_key, [])
        return []
    query = "\n        SELECT menu_path\n        FROM role_quick_access\n        WHERE role_id = :role_id\n        ORDER BY sort_order, menu_path\n    "
    rows = _safe_rows_auth(query, {'role_id': canon})
    paths = [row['menu_path'] for row in rows if row.get('menu_path')]
    _auth_ttl_set(f'role_qa:{cache_key}', paths)
    _req_cache_set('role_qa', cache_key, paths)
    return list(paths)

def _replace_role_quick_access(cur, role_id: str, quick_access_paths: Optional[List[str]]) -> None:
    if quick_access_paths is None:
        return
    cur.execute('DELETE FROM role_quick_access WHERE role_id = :role_id', {'role_id': role_id})
    for idx, menu_path in enumerate(quick_access_paths):
        path = (menu_path or '').strip()
        if not path:
            continue
        cur.execute('\n            INSERT INTO role_quick_access (role_id, menu_path, sort_order)\n            VALUES (:role_id, :menu_path, :sort_order)\n        ', {'role_id': role_id, 'menu_path': path, 'sort_order': idx})

def get_next_role_id(prefix: str='ROLE', width: int=3) -> str:
    """Generate next role_id using existing roles (auth DB)."""
    rows = _safe_rows_auth('SELECT role_id FROM roles', {})
    max_value = 0
    pattern = re.compile('(\\d+)$')
    for row in rows:
        role_id = str(row.get('role_id') or '').strip()
        if not role_id:
            continue
        if role_id.isdigit():
            max_value = max(max_value, int(role_id))
            continue
        match = pattern.search(role_id)
        if match:
            max_value = max(max_value, int(match.group(1)))
    next_value = max_value + 1
    return f'{prefix}{next_value:0{width}d}'

def create_role(role_id: str, role_name: str, description: str='', menu_permissions: List[str]=None, quick_access_paths: List[str]=None) -> None:
    """Create a new role with permissions (auth DB)."""
    if not role_id or not role_name:
        raise ValueError('Role ID and Role Name are required.')
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute('SELECT 1 FROM roles WHERE role_id = :role_id', {'role_id': role_id})
            if cur.fetchone():
                raise ValueError('Role ID already exists.')
            cur.execute('INSERT INTO roles (role_id, role_name, description) VALUES (:role_id, :role_name, :role_desc)', {'role_id': role_id, 'role_name': role_name, 'role_desc': description or ''})
            if menu_permissions:
                for menu_path in menu_permissions:
                    cur.execute("INSERT INTO role_permissions (role_id, menu_path, permission) VALUES (:role_id, :menu_path, 'Y')", {'role_id': role_id, 'menu_path': menu_path})
            _replace_role_quick_access(cur, role_id, quick_access_paths)
            conn.commit()

def update_role(role_id: str, role_name: str=None, description: str=None, menu_permissions: List[str]=None, quick_access_paths: List[str]=None) -> None:
    """Update an existing role (auth DB)."""
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            updates = []
            params = {'role_id': role_id}
            if role_name is not None:
                updates.append('role_name = :role_name')
                params['role_name'] = role_name
            if description is not None:
                updates.append('description = :description')
                params['description'] = description
            if updates:
                updates.append('updated_at = SYSDATE')
                cur.execute(f"UPDATE roles SET {', '.join(updates)} WHERE role_id = :role_id", params)
            if menu_permissions is not None:
                cur.execute('DELETE FROM role_permissions WHERE role_id = :role_id', {'role_id': role_id})
                for menu_path in menu_permissions:
                    cur.execute("INSERT INTO role_permissions (role_id, menu_path, permission) VALUES (:id, :path, 'Y')", {'id': role_id, 'path': menu_path})
            _replace_role_quick_access(cur, role_id, quick_access_paths)
            conn.commit()

def delete_role(role_id: str) -> None:
    """Delete a role (cascade will delete permissions) (auth DB)."""
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute('DELETE FROM roles WHERE role_id = :role_id', {'role_id': role_id})
            conn.commit()

def role_exists(role_id: str) -> bool:
    """Check if a role exists (auth DB)."""
    return resolve_role_id_canonical(role_id) is not None

def get_role_by_id(role_id: str) -> Optional[Dict[str, Any]]:
    """Get role details by role_id (auth DB). Case-insensitive on role_id."""
    canon = resolve_role_id_canonical(role_id)
    if not canon:
        return None
    query = 'SELECT role_id, role_name, description FROM roles WHERE role_id = :role_id'
    rows = _safe_rows_auth(query, {'role_id': canon})
    return rows[0] if rows else None

def ensure_ho_roles() -> None:
    """Ensure default HO and Master Request seed roles exist on the auth DB (no-op if present)."""
    try:
        from permissions import get_ho_seed_roles
    except ImportError:
        return
    ensure_roles_tables()
    for spec in get_ho_seed_roles():
        rid = str(spec.get('role_id') or '').strip()
        if not rid:
            continue
        if role_exists(rid):
            continue
        rname = str(spec.get('role_name') or '').strip() or rid
        rdesc = str(spec.get('description') or '').strip()
        menus = spec.get('menu_permissions')
        menus_list: List[str] = []
        if isinstance(menus, list):
            menus_list = [str(m).strip() for m in menus if str(m).strip()]
        create_role(rid, rname, rdesc, menus_list)
