def get_salesman_outstanding_details(salesman_code: Optional[str], bucket: str) -> List[Dict[str, Any]]:
    """Fetch invoice-level outstanding for a salesman and aging bucket. Details only from tblsettlement; customer name from customer table only. No BILLHDR. Filter balance > 0, flag = 'B'. All customers (no invoice-code filter)."""
    salesman_join_clause, salesman_name_column = _resolve_salesman_join()
    salesman_code_col = os.getenv('DASH_SALESMAN_CODE_COLUMN', 'salesmancode')
    invoice_date_column = _resolve_invoice_date_column()
    date_col = invoice_date_column if '.' in invoice_date_column else f's.{invoice_date_column}'
    salesman_name_sql = salesman_name_column or 'NULL'
    balance_col = _detect_column('tblsettlement', ['BALANCE', 'OUTSTANDING', 'NETBALANCE']) or 'balance'
    balance_sql = f'NVL(s.{balance_col}, 0)'
    settle_billno = _detect_column('tblsettlement', ['BILLNO', 'BILL_NO', 'billno']) or 'billno'
    settle_billdate = _detect_column('tblsettlement', ['BILLDATE', 'BILL_DATE', 'billdate']) or 'billdate'
    settle_cust = _detect_column('tblsettlement', ['CUSTOMERCODE', 'CUSTOMER_CODE', 'customercode']) or 'customercode'
    settle_billamount = _detect_column('tblsettlement', ['BILLAMOUNT', 'BILL_AMOUNT', 'billamount']) or 'billamount'
    settle_paidamount = _detect_column('tblsettlement', ['PAIDAMOUNT', 'PAID_AMOUNT', 'paidamount']) or 'paidamount'
    settle_flag = _detect_column('tblsettlement', ['FLAG', 'FLAG_CODE', 'flag']) or 'flag'
    settle_emp = _detect_column('tblsettlement', ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
    settle_expecteddate = _detect_column('tblsettlement', ['EXPECTEDDATE', 'EXPECTED_DATE', 'expecteddate', 'expected_date', 'EXPECTED', 'expected'])
    settle_remarks = _detect_column('tblsettlement', ['REMARKS', 'REMARK', 'remarks', 'remark'])
    employee_join = ''
    employeecode_sql = 'NULL AS employeecode'
    employeename_sql = 'NULL AS employeename'
    if settle_emp:
        for et in ['EMPLOYEE1', 'employee1', 'EMPLOYEE', 'employee']:
            if not _table_exists(et):
                continue
            ec = _detect_column(et, ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
            if ec:
                en = _detect_column(et, ['EMPLOYEENAME', 'EMPLOYEE_NAME', 'employeename'])
                employee_join = f' LEFT JOIN {et} emp ON s.{settle_emp} = emp.{ec}'
                employeecode_sql = f's.{settle_emp} AS employeecode'
                employeename_sql = f'emp.{en}' if en else 'NULL'
                employeename_sql = f'{employeename_sql} AS employeename'
                break
    expecteddate_sql = f's.{settle_expecteddate} AS expecteddate' if settle_expecteddate else 'NULL AS expecteddate'
    remarks_sql = f's.{settle_remarks} AS remarks' if settle_remarks else 'NULL AS remarks'
    cust_join = ''
    customer_name_column = None
    for ct in ['customers', 'CUSTOMERS', 'CUSTOMER', 'customer']:
        if not _table_exists(ct):
            continue
        cc = _detect_column(ct, ['CUST_CODE', 'CUSTOMERCODE', 'CUSTOMER_CODE', 'CODE'])
        if cc:
            cust_join = f'LEFT JOIN {ct} c ON s.{settle_cust} = c.{cc}'
            customer_name_column = _detect_column(ct, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME'])
            break
    customer_name_sql = f'c.{customer_name_column}' if customer_name_column else 'NULL'
    aging_clause = ''
    if bucket == 'all' or not bucket:
        aging_clause = ''
    elif bucket == '30':
        aging_clause = f'AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 30'
    elif bucket == '60':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 30 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 60'
    elif bucket == '90':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 60 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 90'
    elif bucket == '120':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 90 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 120'
    elif bucket == '120p':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 120'
    params: Dict[str, Any] = {}
    if salesman_code:
        params['salesman_code'] = salesman_code
    settlement_salesman_col = _detect_column('tblsettlement', ['SALESMANCODE', 'SALESMAN_CODE', 'salesmancode', 'salesman'])
    if settlement_salesman_col:
        join_clause = f'{cust_join} LEFT JOIN salesman sm ON sm.{salesman_code_col} = s.{settlement_salesman_col}{employee_join}'
        salesmancode_sql = f's.{settlement_salesman_col}'
        salesmanname_sql_select = salesman_name_sql
        salesman_notnull = f's.{settlement_salesman_col} IS NOT NULL' if salesman_code else '1=1'
        salesman_filter = f'AND s.{settlement_salesman_col} = :salesman_code' if salesman_code else ''
    else:
        join_clause = f'{cust_join}{employee_join}'.strip()
        salesmancode_sql = 'NULL'
        salesmanname_sql_select = 'NULL'
        salesman_notnull = '1=1'
        salesman_filter = ''
    query = f"\n        SELECT\n            ROW_NUMBER() OVER (ORDER BY {date_col} DESC, s.{settle_billno} DESC) AS slno,\n            s.{settle_billno} AS billno,\n            s.{settle_billdate} AS billdate,\n            s.{settle_cust} AS customercode,\n            {customer_name_sql} AS customername,\n            {salesmancode_sql} AS salesmancode,\n            {salesmanname_sql_select} AS salesmanname,\n            {employeecode_sql},\n            {employeename_sql},\n            {expecteddate_sql},\n            {remarks_sql},\n            NVL(s.{settle_billamount}, 0) AS billamount,\n            NVL(s.{settle_paidamount}, 0) AS paidamount,\n            {balance_sql} AS outstanding\n        FROM tblsettlement s\n        {join_clause}\n        WHERE {balance_sql} <> 0\n          AND s.{settle_flag} = 'B'\n          AND {salesman_notnull}\n          {aging_clause}\n          {salesman_filter}\n        ORDER BY {date_col} DESC, s.{settle_billno} DESC\n    "
    if os.getenv('DEBUG_SALESMAN_OUTSTANDING'):
        print('[DEBUG Salesman Outstanding Details] salesman_code=%r bucket=%r' % (salesman_code, bucket))
        print('[DEBUG Salesman Outstanding Details] settlement_salesman_col=%r' % (settlement_salesman_col,))
        print('[DEBUG Salesman Outstanding Details] settle_billno=%r settle_flag=%r balance_col=%r' % (settle_billno, settle_flag, balance_col))
        print('[DEBUG Salesman Outstanding Details] Query:\n%s' % query)
        print('[DEBUG Salesman Outstanding Details] Params: %s' % params)
    try:
        _, rows = _fetch_rows(query, params)
        if os.getenv('DEBUG_SALESMAN_OUTSTANDING'):
            print('[DEBUG Salesman Outstanding Details] Row count: %d' % len(rows or []))
        return rows
    except Exception as e:
        if os.getenv('DEBUG_SALESMAN_OUTSTANDING'):
            import traceback
            print('[DEBUG Salesman Outstanding Details] Error: %s' % e)
            traceback.print_exc()
        return []

def get_customer_outstanding_details(customer_code: Optional[str], bucket: str) -> List[Dict[str, Any]]:
    """Fetch invoice-level outstanding for a customer and aging bucket. Details only from tblsettlement; customer name from customer table only. Filter balance > 0, flag = 'B'. All customers (no invoice-code filter). Includes salesman from tblsettlement."""
    invoice_date_column = _resolve_invoice_date_column()
    date_col = invoice_date_column if '.' in invoice_date_column else f's.{invoice_date_column}'
    salesman_code_col = os.getenv('DASH_SALESMAN_CODE_COLUMN', 'salesmancode')
    balance_col = _detect_column('tblsettlement', ['BALANCE', 'OUTSTANDING', 'NETBALANCE']) or 'balance'
    balance_sql = f'NVL(s.{balance_col}, 0)'
    settle_billno = _detect_column('tblsettlement', ['BILLNO', 'BILL_NO', 'billno']) or 'billno'
    settle_billdate = _detect_column('tblsettlement', ['BILLDATE', 'BILL_DATE', 'billdate']) or 'billdate'
    settle_cust = _detect_column('tblsettlement', ['CUSTOMERCODE', 'CUSTOMER_CODE', 'customercode']) or 'customercode'
    settle_billamount = _detect_column('tblsettlement', ['BILLAMOUNT', 'BILL_AMOUNT', 'billamount']) or 'billamount'
    settle_paidamount = _detect_column('tblsettlement', ['PAIDAMOUNT', 'PAID_AMOUNT', 'paidamount']) or 'paidamount'
    settle_flag = _detect_column('tblsettlement', ['FLAG', 'FLAG_CODE', 'flag']) or 'flag'
    settle_emp = _detect_column('tblsettlement', ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
    settle_expecteddate = _detect_column('tblsettlement', ['EXPECTEDDATE', 'EXPECTED_DATE', 'expecteddate', 'expected_date', 'EXPECTED', 'expected'])
    settle_remarks = _detect_column('tblsettlement', ['REMARKS', 'REMARK', 'remarks', 'remark'])
    expecteddate_sql = f's.{settle_expecteddate} AS expecteddate' if settle_expecteddate else 'NULL AS expecteddate'
    remarks_sql = f's.{settle_remarks} AS remarks' if settle_remarks else 'NULL AS remarks'
    employee_table = None
    emp_code_col = None
    emp_name_col = None
    employee_join = ''
    employeename_sql = 'NULL AS employeename'
    for et in ['EMPLOYEE1', 'employee1']:
        if _table_exists(et):
            employee_table = et
            break
    if employee_table and settle_emp:
        emp_code_col = _detect_column(employee_table, ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
        emp_name_col = _detect_column(employee_table, ['EMPLOYEENAME', 'EMPLOYEE_NAME', 'employeename'])
        if emp_code_col and emp_name_col:
            employee_join = f' LEFT JOIN {employee_table} emp ON emp.{emp_code_col} = s.{settle_emp}'
            employeename_sql = f'emp.{emp_name_col} AS employeename'
    cust_join = ''
    customer_name_column = None
    for ct in ['customers', 'CUSTOMERS', 'CUSTOMER', 'customer']:
        if not _table_exists(ct):
            continue
        cc = _detect_column(ct, ['CUST_CODE', 'CUSTOMERCODE', 'CUSTOMER_CODE', 'CODE'])
        if cc:
            cust_join = f'LEFT JOIN {ct} c ON s.{settle_cust} = c.{cc}'
            customer_name_column = _detect_column(ct, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME'])
            break
    customer_name_sql = f'c.{customer_name_column}' if customer_name_column else 'NULL'
    settlement_salesman_col = _detect_column('tblsettlement', ['SALESMANCODE', 'SALESMAN_CODE', 'salesmancode', 'salesman'])
    salesman_name_col = os.getenv('DASH_SALESMAN_NAME_COLUMN')
    if not salesman_name_col:
        salesman_name_col = _detect_column('SALESMAN', ['SALESMANNAME', 'SALESMAN_NAME', 'NAME'])
    if settlement_salesman_col:
        salesman_join = f'LEFT JOIN salesman sm ON sm.{salesman_code_col} = s.{settlement_salesman_col}'
        salesmancode_sql = f's.{settlement_salesman_col}'
        salesmanname_sql = f'sm.{salesman_name_col}' if salesman_name_col else 'NULL'
        if cust_join:
            join_clause = f'{cust_join} {salesman_join}{employee_join}'
        else:
            join_clause = f'{salesman_join}{employee_join}'
    else:
        join_clause = f'{cust_join}{employee_join}' if cust_join else employee_join.strip()
        salesmancode_sql = 'NULL'
        salesmanname_sql = 'NULL'
    aging_clause = ''
    if bucket == 'all' or not bucket:
        aging_clause = ''
    elif bucket == '30':
        aging_clause = f'AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 30'
    elif bucket == '60':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 30 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 60'
    elif bucket == '90':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 60 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 90'
    elif bucket == '120':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 90 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 120'
    elif bucket == '120p':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 120'
    elif bucket == 'm0':
        aging_clause = f"AND TRUNC({date_col}, 'MM') = TRUNC(SYSDATE, 'MM')"
    elif bucket == 'm1':
        aging_clause = f"AND TRUNC({date_col}, 'MM') = TRUNC(ADD_MONTHS(SYSDATE, -1), 'MM')"
    elif bucket == 'm2':
        aging_clause = f"AND TRUNC({date_col}, 'MM') = TRUNC(ADD_MONTHS(SYSDATE, -2), 'MM')"
    elif bucket == 'older_months':
        aging_clause = f"AND TRUNC({date_col}, 'MM') < TRUNC(ADD_MONTHS(SYSDATE, -2), 'MM')"
    params: Dict[str, Any] = {}
    if customer_code:
        params['customer_code'] = customer_code
        customer_filter = f'AND s.{settle_cust} = :customer_code'
    else:
        customer_filter = ''
    query = f"\n        SELECT\n            ROW_NUMBER() OVER (ORDER BY {date_col} DESC, s.{settle_billno} DESC) AS slno,\n            s.{settle_billno} AS billno,\n            s.{settle_billdate} AS billdate,\n            s.{settle_cust} AS customercode,\n            {customer_name_sql} AS customername,\n            {salesmancode_sql} AS salesmancode,\n            {salesmanname_sql} AS salesmanname,\n            {(f's.{settle_emp} AS employeecode' if settle_emp else 'NULL AS employeecode')},\n            {employeename_sql},\n            {expecteddate_sql},\n            {remarks_sql},\n            NVL(s.{settle_billamount}, 0) AS billamount,\n            NVL(s.{settle_paidamount}, 0) AS paidamount,\n            {balance_sql} AS outstanding\n        FROM tblsettlement s\n        {join_clause}\n        WHERE {balance_sql} > 0\n          AND s.{settle_flag} = 'B'\n          {aging_clause}\n          {customer_filter}\n        ORDER BY {date_col} DESC, s.{settle_billno} DESC\n    "
    if os.getenv('DEBUG_CUSTOMER_OUTSTANDING'):
        print('[DEBUG Customer Outstanding Details] customer_code=%r bucket=%r' % (customer_code, bucket))
        print('[DEBUG Customer Outstanding Details] Query:\n%s' % query)
        print('[DEBUG Customer Outstanding Details] Params: %s' % params)
    try:
        _, rows = _fetch_rows(query, params)
        if os.getenv('DEBUG_CUSTOMER_OUTSTANDING'):
            print('[DEBUG Customer Outstanding Details] Row count: %d' % len(rows or []))
        return rows
    except Exception as e:
        if os.getenv('DEBUG_CUSTOMER_OUTSTANDING'):
            print('[DEBUG Customer Outstanding Details] Error: %s' % e)
        return []

def _voucher_date_as_date(voucher_date: Any) -> Optional[date]:
    iso = _to_iso_date(voucher_date)
    if not iso:
        return None
    try:
        return datetime.strptime(str(iso)[:10], '%Y-%m-%d').date()
    except Exception:
        return None


def _customer_master_index_for_branch(
    branchflag: Optional[str] = None,
    transferbranch: Optional[str] = None,
) -> Dict[str, Dict[str, Any]]:
    """Customer code -> master row (name, receivable account) with optional branch filters."""
    cinfo = _resolve_customer_branch_cols()
    ct = cinfo['table']
    cc = cinfo['code_col']
    if not ct or not cc:
        return {}
    name_col = cinfo['name_col']
    recv_col = _detect_column(ct, ['RECEIVABLEACCOUNT', 'receivableaccount', 'RECEIVABLE_AC', 'receivable_acct'])
    bf_col = cinfo['branchflag_col']
    tb_col = cinfo['transferbranch_col']
    cols = [f'{cc} AS customercode']
    if name_col:
        cols.append(f'{name_col} AS customername')
    else:
        cols.append('NULL AS customername')
    if recv_col:
        cols.append(f'{recv_col} AS receivableaccount')
    else:
        cols.append('NULL AS receivableaccount')
    where = ['1=1']
    params: Dict[str, Any] = {}
    if branchflag and bf_col:
        where.append(f'{bf_col} = :p_branchflag')
        params['p_branchflag'] = branchflag
    if transferbranch and tb_col:
        where.append(f'{tb_col} = :p_transferbranch')
        params['p_transferbranch'] = transferbranch
    q = f"SELECT {', '.join(cols)} FROM {ct} WHERE {' AND '.join(where)}"
    try:
        rows = _safe_rows(q, params)
    except Exception:
        return {}
    out: Dict[str, Dict[str, Any]] = {}
    default_recv = str(DEFAULT_PARTY_ACCOUNTS.get('customer_receivable') or '1200').strip()
    for r in rows or []:
        key = _norm_supplier_key(r.get('customercode'))
        if not key:
            continue
        raw_recv = r.get('receivableaccount')
        recv = _norm_gl_account_code(raw_recv) if raw_recv not in (None, '') else _norm_gl_account_code(default_recv)
        out[key] = {
            'customercode': r.get('customercode'),
            'customername': r.get('customername'),
            'receivableaccount': recv or default_recv,
        }
    return out


def _fetch_all_customer_gl_voucher_aggregate_rows() -> List[Dict[str, Any]]:
    """All customer party-tagged GL voucher lines (excludes AR receipt settlement vouchers)."""
    ensure_gl_tables()
    return _safe_rows(
        f"""
        SELECT
            TRIM(TO_CHAR(d.PARTY_CODE)) AS party_code,
            d.VOUCHER_NO AS voucher_no,
            h.VOUCHER_DATE AS voucher_date,
            h.REFERENCE_NO AS reference_no,
            h.NARRATION AS narration,
            h.SOURCE AS source,
            d.ACCOUNT_CODE AS account_code,
            SUM(d.DEBIT) AS debit,
            SUM(d.CREDIT) AS credit
        FROM {GL_DTL_TABLE} d
        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO
        WHERE UPPER(NVL(d.PARTY_TYPE, '')) = 'CUSTOMER'
          AND d.PARTY_CODE IS NOT NULL
          AND UPPER(NVL(h.SOURCE, '')) NOT IN ('AR_RECEIPT')
        GROUP BY TRIM(TO_CHAR(d.PARTY_CODE)), d.VOUCHER_NO, h.VOUCHER_DATE,
                 h.REFERENCE_NO, h.NARRATION, h.SOURCE, d.ACCOUNT_CODE
        """,
        {},
    ) or []


def _ar_allocated_by_voucher() -> Dict[str, float]:
    ensure_ar_payment_tables()
    if not _table_exists(AR_ALLOC_TABLE):
        return {}
    rows = _safe_rows(
        f"""
        SELECT INVOICE_VOUCHER_NO AS invoice_voucher_no,
               SUM(ALLOCATED_AMOUNT) AS allocated_amount
        FROM {AR_ALLOC_TABLE}
        GROUP BY INVOICE_VOUCHER_NO
        """,
        {},
    )
    return {
        _norm_voucher_key(r.get('invoice_voucher_no')): round(float(r.get('allocated_amount') or 0), 2)
        for r in rows or []
    }


def _ar_payment_allocated_by_voucher() -> Dict[str, float]:
    """Amounts allocated from payment vouchers (e.g. receipts, online settlement JVs)."""
    ensure_ar_payment_tables()
    if not _table_exists(AR_ALLOC_TABLE):
        return {}
    rows = _safe_rows(
        f"""
        SELECT PAYMENT_VOUCHER_NO AS payment_voucher_no,
               SUM(ALLOCATED_AMOUNT) AS allocated_amount
        FROM {AR_ALLOC_TABLE}
        GROUP BY PAYMENT_VOUCHER_NO
        """,
        {},
    )
    return {
        _norm_voucher_key(r.get('payment_voucher_no')): round(float(r.get('allocated_amount') or 0), 2)
        for r in rows or []
    }


def _ar_open_amount_from_allocations(
    invoice_amount: float,
    vkey: str,
    allocated_map: Dict[str, float],
    payment_allocated_map: Dict[str, float],
) -> Tuple[float, float]:
    """Return (open_amount, display_paid_amount) for one AR voucher."""
    allocated = round(float(allocated_map.get(vkey, 0.0) or 0), 2)
    payment_applied = round(float(payment_allocated_map.get(vkey, 0.0) or 0), 2)
    if invoice_amount > 0:
        open_amount = round(invoice_amount - allocated, 2)
        display_paid = allocated
    else:
        open_amount = round(invoice_amount + allocated + payment_applied, 2)
        display_paid = round(allocated + payment_applied, 2)
    return open_amount, display_paid


def _credit_outstanding_aging_bucket(voucher_date: Any) -> str:
    d = _voucher_date_as_date(voucher_date)
    if not d:
        return '120p'
    days = (date.today() - d).days
    if days <= 30:
        return '30'
    if days <= 60:
        return '60'
    if days <= 90:
        return '90'
    if days <= 120:
        return '120'
    return '120p'


def _credit_outstanding_month_bucket(voucher_date: Any) -> str:
    d = _voucher_date_as_date(voucher_date)
    if not d:
        return 'older_months'
    today = date.today()
    diff = (today.year - d.year) * 12 + (today.month - d.month)
    if diff <= 0:
        return 'm0'
    if diff == 1:
        return 'm1'
    if diff == 2:
        return 'm2'
    return 'older_months'


def _customer_open_documents_gl(
    customer_code: Optional[str] = None,
    branchflag: Optional[str] = None,
    transferbranch: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Open customer receivable documents from GL_VOUCHER_* and AR_CUSTOMER_PAYMENT_ALLOC."""
    cust_index = _customer_master_index_for_branch(branchflag, transferbranch)
    if not cust_index:
        return []
    target = _norm_supplier_key(customer_code) if customer_code else ''
    coa_types = _coa_type_map_for_payment()
    allocated_map = _ar_allocated_by_voucher()
    payment_allocated_map = _ar_payment_allocated_by_voucher()
    by_party: Dict[str, List[Dict[str, Any]]] = {}
    for row in _fetch_all_customer_gl_voucher_aggregate_rows():
        pcode = _norm_supplier_key(row.get('party_code'))
        if not pcode or pcode not in cust_index:
            continue
        if target and pcode != target:
            continue
        by_party.setdefault(pcode, []).append(row)
    docs: List[Dict[str, Any]] = []
    for pcode, party_rows in by_party.items():
        meta = cust_index[pcode]
        recv_acc = meta.get('receivableaccount') or str(DEFAULT_PARTY_ACCOUNTS.get('customer_receivable') or '1200')
        voucher_map = _voucher_open_amount_from_party_rows(
            party_rows,
            balance_mode='receivable',
            primary_account=str(recv_acc),
            coa_types=coa_types,
        )
        for vno, rec in voucher_map.items():
            invoice_amount = round(float(rec.get('invoice_amount') or 0), 2)
            if abs(invoice_amount) < 0.005:
                continue
            vkey = _norm_voucher_key(vno)
            open_amount, display_paid = _ar_open_amount_from_allocations(
                invoice_amount, vkey, allocated_map, payment_allocated_map,
            )
            if abs(open_amount) < 0.005:
                continue
            billno = str(rec.get('reference_no') or '').strip() or str(vno)
            bill_dt = _voucher_date_as_date(rec.get('voucher_date'))
            docs.append({
                'billno': billno,
                'billdate': bill_dt if bill_dt is not None else rec.get('voucher_date'),
                'customercode': meta.get('customercode'),
                'customername': meta.get('customername'),
                'salesmancode': None,
                'salesmanname': None,
                'employeecode': None,
                'employeename': None,
                'expecteddate': None,
                'remarks': rec.get('narration'),
                'billamount': invoice_amount,
                'paidamount': display_paid,
                'outstanding': open_amount,
                'voucher_no': vno,
                'source': rec.get('source'),
                'reference_no': rec.get('reference_no'),
            })
    docs.sort(key=lambda x: (str(x.get('billdate') or ''), str(x.get('billno') or '')), reverse=True)
    return docs


def _customer_outstanding_summary_from_gl_docs(
    docs: List[Dict[str, Any]],
    summary_mode: str,
) -> List[Dict[str, Any]]:
    """Aggregate open GL documents per customer (summary_mode: 'aging' or 'month')."""
    agg: Dict[str, Dict[str, Any]] = {}
    aging_fields = {'30': 'd30', '60': 'd60', '90': 'd90', '120': 'd120', '120p': 'd120p'}
    month_fields = {'m0': 'dm0', 'm1': 'dm1', 'm2': 'dm2', 'older_months': 'dolder'}
    for d in docs or []:
        key = _norm_supplier_key(d.get('customercode'))
        if not key:
            continue
        amt = round(float(d.get('outstanding') or 0), 2)
        if abs(amt) < 0.005:
            continue
        if key not in agg:
            row: Dict[str, Any] = {
                'customercode': d.get('customercode'),
                'customername': d.get('customername'),
            }
            if summary_mode == 'aging':
                row.update({v: 0.0 for v in aging_fields.values()})
            else:
                row.update({v: 0.0 for v in month_fields.values()})
            agg[key] = row
        if summary_mode == 'aging':
            bucket = _credit_outstanding_aging_bucket(d.get('billdate'))
            field = aging_fields.get(bucket)
        else:
            bucket = _credit_outstanding_month_bucket(d.get('billdate'))
            field = month_fields.get(bucket)
        if field:
            agg[key][field] = round(float(agg[key].get(field) or 0) + amt, 2)
    rows = list(agg.values())
    rows.sort(key=lambda r: str(r.get('customercode') or ''))
    return rows


def get_customer_outstanding_details_credit(customer_code: Optional[str], bucket: str, branchflag: Optional[str]=None, transferbranch: Optional[str]=None) -> List[Dict[str, Any]]:
    """Invoice-level customer outstanding from GL vouchers (accounts), not tblcreditsettlement."""
    docs = _customer_open_documents_gl(customer_code=customer_code, branchflag=branchflag, transferbranch=transferbranch)
    if not bucket or bucket == 'all':
        filtered = docs
    elif bucket in ('m0', 'm1', 'm2', 'older_months'):
        filtered = [d for d in docs if _credit_outstanding_month_bucket(d.get('billdate')) == bucket]
    else:
        filtered = [d for d in docs if _credit_outstanding_aging_bucket(d.get('billdate')) == bucket]
    out: List[Dict[str, Any]] = []
    for i, d in enumerate(filtered, start=1):
        row = dict(d)
        row['slno'] = i
        out.append(row)
    return out


def _get_outstanding_aging_three_month_from(settle_table_name: str, branchflag: Optional[str]=None, transferbranch: Optional[str]=None) -> List[Dict[str, Any]]:
    """Like _get_outstanding_aging_from but buckets by bill-date calendar month: current + 2 prior + older."""
    settle_table = _detect_table([settle_table_name.upper(), settle_table_name.lower()])
    if not settle_table:
        return []
    date_raw = _detect_column(settle_table, ['BILLDATE', 'BILL_DATE', 'billdate', 'PAIDDATE', 'PAID_DATE', 'paiddate']) or 'billdate'
    date_col = f's.{date_raw}'
    balance_col = _detect_column(settle_table, ['BALANCE', 'OUTSTANDING', 'NETBALANCE'])
    if balance_col:
        balance_sql = f'NVL(s.{balance_col}, 0)'
    else:
        bill_col = _detect_column(settle_table, ['BILLAMOUNT', 'BILL_AMOUNT', 'billamount'])
        paid_col = _detect_column(settle_table, ['PAIDAMOUNT', 'PAID_AMOUNT', 'paidamount'])
        balance_sql = f'(NVL(s.{bill_col}, 0) - NVL(s.{paid_col}, 0))' if bill_col and paid_col else '0'
    settle_cust = _detect_column(settle_table, ['CUSTOMERCODE', 'CUSTOMER_CODE', 'customercode']) or 'customercode'
    settle_flag = _detect_column(settle_table, ['FLAG', 'FLAG_CODE', 'flag']) or 'flag'
    cinfo = _resolve_customer_branch_cols()
    customer_table = cinfo['table']
    customer_code_col = cinfo['code_col']
    customer_name_col = cinfo['name_col']
    branchflag_col = cinfo['branchflag_col']
    transferbranch_col = cinfo['transferbranch_col']
    if not customer_table or not customer_code_col:
        return []
    join_clause = f'LEFT JOIN {customer_table} c ON s.{settle_cust} = c.{customer_code_col}'
    customer_name_sql = f'c.{customer_name_col}' if customer_name_col else 'NULL'
    params: Dict[str, Any] = {}
    branch_filters = ''
    if branchflag and branchflag_col:
        params['p_branchflag'] = branchflag
        branch_filters += f' AND c.{branchflag_col} = :p_branchflag'
    if transferbranch and transferbranch_col:
        params['p_transferbranch'] = transferbranch
        branch_filters += f' AND c.{transferbranch_col} = :p_transferbranch'
    trunc_m = f"TRUNC({date_col}, 'MM')"
    query = f"\n        SELECT\n            NVL(c.{customer_code_col}, s.{settle_cust}) AS customercode,\n            {customer_name_sql} AS customername,\n            SUM(CASE WHEN {trunc_m} = TRUNC(SYSDATE, 'MM') THEN {balance_sql} ELSE 0 END) AS dm0,\n            SUM(CASE WHEN {trunc_m} = TRUNC(ADD_MONTHS(SYSDATE, -1), 'MM') THEN {balance_sql} ELSE 0 END) AS dm1,\n            SUM(CASE WHEN {trunc_m} = TRUNC(ADD_MONTHS(SYSDATE, -2), 'MM') THEN {balance_sql} ELSE 0 END) AS dm2,\n            SUM(CASE WHEN {trunc_m} < TRUNC(ADD_MONTHS(SYSDATE, -2), 'MM') THEN {balance_sql} ELSE 0 END) AS dolder\n        FROM {settle_table} s\n        {join_clause}\n        WHERE {balance_sql} <> 0\n          AND s.{settle_flag} = 'B'\n          {branch_filters}\n        GROUP BY NVL(c.{customer_code_col}, s.{settle_cust}), {customer_name_sql}\n        ORDER BY customercode\n    "
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except Exception:
        return []

def _resolve_customer_branch_cols() -> Dict[str, Any]:
    """Detect CUSTOMER table and its BRANCHFLAG / TRANSFERBRANCH columns. Returns dict with keys:
    table, code_col, name_col, branchflag_col, transferbranch_col (any may be None)."""
    result: Dict[str, Any] = {'table': None, 'code_col': None, 'name_col': None, 'branchflag_col': None, 'transferbranch_col': None}
    for ct in ['CUSTOMER', 'customers', 'CUSTOMERS', 'customer']:
        if not _table_exists(ct):
            continue
        cc = _detect_column(ct, ['CUST_CODE', 'CUSTOMERCODE', 'CUSTOMER_CODE', 'CODE'])
        if not cc:
            continue
        result['table'] = ct
        result['code_col'] = cc
        result['name_col'] = _detect_column(ct, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME'])
        result['branchflag_col'] = _detect_column(ct, ['BRANCHFLAG', 'BRANCH_FLAG', 'branchflag'])
        result['transferbranch_col'] = _detect_column(ct, ['TRANSFERBRANCH', 'TRANSFER_BRANCH', 'transferbranch'])
        break
    return result

def get_customer_branch_filter_options() -> Dict[str, List[str]]:
    """Return distinct values of BRANCHFLAG and TRANSFERBRANCH from CUSTOMER table."""
    info = _resolve_customer_branch_cols()
    ct = info['table']
    result: Dict[str, List[str]] = {'branchflag': [], 'transferbranch': []}
    if not ct:
        return result
    for key, col in [('branchflag', info['branchflag_col']), ('transferbranch', info['transferbranch_col'])]:
        if not col:
            continue
        try:
            _, rows = _fetch_rows(f'SELECT DISTINCT {col} AS v FROM {ct} WHERE {col} IS NOT NULL ORDER BY {col}', {})
            result[key] = [str(r['v']) for r in rows if r.get('v') is not None]
        except Exception:
            pass
    return result

def _get_outstanding_aging_from(settle_table_name: str, branchflag: Optional[str]=None, transferbranch: Optional[str]=None) -> List[Dict[str, Any]]:
    """Generic customer aging summary (0-30/31-60/61-90/91-120/120+) from any settlement table.
    Optional branchflag / transferbranch filter applied via JOIN to CUSTOMER table."""
    settle_table = _detect_table([settle_table_name.upper(), settle_table_name.lower()])
    if not settle_table:
        return []
    date_raw = _detect_column(settle_table, ['BILLDATE', 'BILL_DATE', 'billdate', 'PAIDDATE', 'PAID_DATE', 'paiddate']) or 'billdate'
    date_col = f's.{date_raw}'
    balance_col = _detect_column(settle_table, ['BALANCE', 'OUTSTANDING', 'NETBALANCE'])
    if balance_col:
        balance_sql = f'NVL(s.{balance_col}, 0)'
    else:
        bill_col = _detect_column(settle_table, ['BILLAMOUNT', 'BILL_AMOUNT', 'billamount'])
        paid_col = _detect_column(settle_table, ['PAIDAMOUNT', 'PAID_AMOUNT', 'paidamount'])
        balance_sql = f'(NVL(s.{bill_col}, 0) - NVL(s.{paid_col}, 0))' if bill_col and paid_col else '0'
    settle_cust = _detect_column(settle_table, ['CUSTOMERCODE', 'CUSTOMER_CODE', 'customercode']) or 'customercode'
    settle_flag = _detect_column(settle_table, ['FLAG', 'FLAG_CODE', 'flag']) or 'flag'
    cinfo = _resolve_customer_branch_cols()
    customer_table = cinfo['table']
    customer_code_col = cinfo['code_col']
    customer_name_col = cinfo['name_col']
    branchflag_col = cinfo['branchflag_col']
    transferbranch_col = cinfo['transferbranch_col']
    if not customer_table or not customer_code_col:
        return []
    join_clause = f'LEFT JOIN {customer_table} c ON s.{settle_cust} = c.{customer_code_col}'
    customer_name_sql = f'c.{customer_name_col}' if customer_name_col else 'NULL'
    params: Dict[str, Any] = {}
    branch_filters = ''
    if branchflag and branchflag_col:
        params['p_branchflag'] = branchflag
        branch_filters += f' AND c.{branchflag_col} = :p_branchflag'
    if transferbranch and transferbranch_col:
        params['p_transferbranch'] = transferbranch
        branch_filters += f' AND c.{transferbranch_col} = :p_transferbranch'
    query = f"\n        SELECT\n            NVL(c.{customer_code_col}, s.{settle_cust}) AS customercode,\n            {customer_name_sql} AS customername,\n            SUM(CASE WHEN TRUNC({date_col}) >= TRUNC(SYSDATE) - 30 THEN {balance_sql} ELSE 0 END) AS d30,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 30\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 60 THEN {balance_sql} ELSE 0 END) AS d60,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 60\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 90 THEN {balance_sql} ELSE 0 END) AS d90,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 90\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 120 THEN {balance_sql} ELSE 0 END) AS d120,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 120 THEN {balance_sql} ELSE 0 END) AS d120p\n        FROM {settle_table} s\n        {join_clause}\n        WHERE {balance_sql} <> 0\n          AND s.{settle_flag} = 'B'\n          {branch_filters}\n        GROUP BY NVL(c.{customer_code_col}, s.{settle_cust}), {customer_name_sql}\n        ORDER BY customercode\n    "
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except Exception:
        return []

def _get_outstanding_details_from(settle_table_name: str, customer_code: Optional[str], bucket: str, branchflag: Optional[str]=None, transferbranch: Optional[str]=None) -> List[Dict[str, Any]]:
    """Generic invoice-level outstanding details from any settlement table."""
    settle_table = _detect_table([settle_table_name.upper(), settle_table_name.lower()])
    if not settle_table:
        return []
    date_raw = _detect_column(settle_table, ['BILLDATE', 'BILL_DATE', 'billdate', 'PAIDDATE', 'PAID_DATE', 'paiddate']) or 'billdate'
    date_col = f's.{date_raw}'
    balance_col = _detect_column(settle_table, ['BALANCE', 'OUTSTANDING', 'NETBALANCE'])
    if balance_col:
        balance_sql = f'NVL(s.{balance_col}, 0)'
    else:
        bill_col2 = _detect_column(settle_table, ['BILLAMOUNT', 'BILL_AMOUNT', 'billamount'])
        paid_col2 = _detect_column(settle_table, ['PAIDAMOUNT', 'PAID_AMOUNT', 'paidamount'])
        balance_sql = f'(NVL(s.{bill_col2}, 0) - NVL(s.{paid_col2}, 0))' if bill_col2 and paid_col2 else '0'
    settle_billno = _detect_column(settle_table, ['BILLNO', 'BILL_NO', 'billno', 'PENDINGNO', 'PENDING_NO', 'pendingno']) or 'billno'
    settle_billdate = _detect_column(settle_table, ['BILLDATE', 'BILL_DATE', 'billdate', 'PAIDDATE', 'PAID_DATE', 'paiddate']) or 'billdate'
    settle_cust = _detect_column(settle_table, ['CUSTOMERCODE', 'CUSTOMER_CODE', 'customercode']) or 'customercode'
    settle_billamount = _detect_column(settle_table, ['BILLAMOUNT', 'BILL_AMOUNT', 'billamount']) or 'billamount'
    settle_paidamount = _detect_column(settle_table, ['PAIDAMOUNT', 'PAID_AMOUNT', 'paidamount']) or 'paidamount'
    settle_flag = _detect_column(settle_table, ['FLAG', 'FLAG_CODE', 'flag']) or 'flag'
    cinfo = _resolve_customer_branch_cols()
    ct = cinfo['table']
    cc = cinfo['code_col']
    customer_name_column = cinfo['name_col']
    branchflag_col = cinfo['branchflag_col']
    transferbranch_col = cinfo['transferbranch_col']
    cust_join = f'LEFT JOIN {ct} c ON s.{settle_cust} = c.{cc}' if ct and cc else ''
    customer_name_sql = f'c.{customer_name_column}' if customer_name_column else 'NULL'
    salesman_code_col = os.getenv('DASH_SALESMAN_CODE_COLUMN', 'salesmancode')
    settlement_salesman_col = _detect_column(settle_table, ['SALESMANCODE', 'SALESMAN_CODE', 'salesmancode', 'salesman'])
    salesman_name_col = os.getenv('DASH_SALESMAN_NAME_COLUMN') or _detect_column('SALESMAN', ['SALESMANNAME', 'SALESMAN_NAME', 'NAME'])
    if settlement_salesman_col:
        salesman_join = f'LEFT JOIN salesman sm ON sm.{salesman_code_col} = s.{settlement_salesman_col}'
        salesmancode_sql = f's.{settlement_salesman_col}'
        salesmanname_sql = f'sm.{salesman_name_col}' if salesman_name_col else 'NULL'
        join_clause = f'{cust_join} {salesman_join}' if cust_join else salesman_join
    else:
        join_clause = cust_join
        salesmancode_sql = 'NULL'
        salesmanname_sql = 'NULL'
    aging_map = {'30': f'AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 30', '60': f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 30  AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 60', '90': f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 60  AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 90', '120': f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 90  AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 120', '120p': f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 120'}
    aging_clause = aging_map.get(bucket, '')
    params: Dict[str, Any] = {}
    if customer_code:
        params['customer_code'] = customer_code
        customer_filter = f'AND s.{settle_cust} = :customer_code'
    else:
        customer_filter = ''
    branch_filters = ''
    if branchflag and branchflag_col:
        params['p_branchflag'] = branchflag
        branch_filters += f' AND c.{branchflag_col} = :p_branchflag'
    if transferbranch and transferbranch_col:
        params['p_transferbranch'] = transferbranch
        branch_filters += f' AND c.{transferbranch_col} = :p_transferbranch'
    query = f"\n        SELECT\n            ROW_NUMBER() OVER (ORDER BY {date_col} DESC, s.{settle_billno} DESC) AS slno,\n            s.{settle_billno} AS billno,\n            s.{settle_billdate} AS billdate,\n            s.{settle_cust} AS customercode,\n            {customer_name_sql} AS customername,\n            {salesmancode_sql} AS salesmancode,\n            {salesmanname_sql} AS salesmanname,\n            NVL(s.{settle_billamount}, 0) AS billamount,\n            NVL(s.{settle_paidamount}, 0) AS paidamount,\n            {balance_sql} AS outstanding\n        FROM {settle_table} s\n        {join_clause}\n        WHERE {balance_sql} <> 0\n          AND s.{settle_flag} = 'B'\n          {aging_clause}\n          {customer_filter}\n          {branch_filters}\n        ORDER BY {date_col} DESC, s.{settle_billno} DESC\n    "
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except Exception:
        return []

def get_customer_outstanding_aging_cash(branchflag: Optional[str]=None, transferbranch: Optional[str]=None) -> List[Dict[str, Any]]:
    """Customer outstanding aging summary from tblcrsettlement (Cash)."""
    return _get_outstanding_aging_from('tblcrsettlement', branchflag=branchflag, transferbranch=transferbranch)

def get_customer_outstanding_aging_credit(branchflag: Optional[str]=None, transferbranch: Optional[str]=None) -> List[Dict[str, Any]]:
    """Customer outstanding aging from GL vouchers / AR allocation (accounts)."""
    docs = _customer_open_documents_gl(branchflag=branchflag, transferbranch=transferbranch)
    return _customer_outstanding_summary_from_gl_docs(docs, 'aging')

def get_customer_outstanding_aging_credit_three_month(branchflag: Optional[str]=None, transferbranch: Optional[str]=None) -> List[Dict[str, Any]]:
    """Credit outstanding by voucher-date calendar month from GL (accounts)."""
    docs = _customer_open_documents_gl(branchflag=branchflag, transferbranch=transferbranch)
    return _customer_outstanding_summary_from_gl_docs(docs, 'month')

def get_customer_outstanding_details_cash(customer_code: Optional[str], bucket: str, branchflag: Optional[str]=None, transferbranch: Optional[str]=None) -> List[Dict[str, Any]]:
    """Invoice-level outstanding details from tblcrsettlement (Cash)."""
    return _get_outstanding_details_from('tblcrsettlement', customer_code, bucket, branchflag=branchflag, transferbranch=transferbranch)

def get_employee_outstanding_aging() -> List[Dict[str, Any]]:
    """Get employee outstanding split by aging buckets (30/60/90/120/120+). All employees from tblsettlement using employeecode."""
    invoice_date_column = _resolve_invoice_date_column()
    date_col = invoice_date_column if '.' in invoice_date_column else f's.{invoice_date_column}'
    balance_col = _detect_column('tblsettlement', ['BALANCE', 'OUTSTANDING', 'NETBALANCE']) or 'balance'
    balance_sql = f'NVL(s.{balance_col}, 0)'
    employee_table = None
    employee_code_col = None
    employee_name_col = None
    for et in ['EMPLOYEE1', 'employee1', 'EMPLOYEE', 'employee']:
        if not _table_exists(et):
            continue
        code_col = _detect_column(et, ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
        if code_col:
            employee_table = et
            employee_code_col = code_col
            employee_name_col = _detect_column(et, ['EMPLOYEENAME', 'EMPLOYEE_NAME', 'employeename'])
            break
    if not employee_table or not employee_code_col:
        return []
    settle_emp = _detect_column('tblsettlement', ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
    if not settle_emp:
        return []
    employee_name_sql = f'e.{employee_name_col}' if employee_name_col else 'NULL'
    join_clause = f'LEFT JOIN {employee_table} e ON s.{settle_emp} = e.{employee_code_col}'
    query = f"\n        SELECT\n            NVL(e.{employee_code_col}, s.{settle_emp}) AS employeecode,\n            {employee_name_sql} AS employeename,\n            SUM(CASE WHEN TRUNC({date_col}) >= TRUNC(SYSDATE) - 30 THEN {balance_sql} ELSE 0 END) AS d30,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 30\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 60 THEN {balance_sql} ELSE 0 END) AS d60,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 60\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 90 THEN {balance_sql} ELSE 0 END) AS d90,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 90\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 120 THEN {balance_sql} ELSE 0 END) AS d120,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 120 THEN {balance_sql} ELSE 0 END) AS d120p\n        FROM tblsettlement s\n        {join_clause}\n        WHERE {balance_sql} <> 0\n          AND s.flag = 'B'\n          AND s.{settle_emp} IS NOT NULL\n        GROUP BY NVL(e.{employee_code_col}, s.{settle_emp}), {employee_name_sql}\n        ORDER BY employeecode\n    "
    try:
        _, rows = _fetch_rows(query, {})
        return rows
    except Exception as e:
        print(f'[ERROR get_employee_outstanding_aging] {e}')
        import traceback
        traceback.print_exc()
        return []

def get_employee_outstanding_details(employeecode: Optional[str], bucket: str, salesmancode: Optional[str]=None, customercode: Optional[str]=None, date_from: Optional[str]=None, date_to: Optional[str]=None, expecteddate_from: Optional[str]=None, expecteddate_to: Optional[str]=None) -> List[Dict[str, Any]]:
    """Fetch invoice-level outstanding for an employee and aging bucket. Details only from tblsettlement; employee name from employee1 table. Filter balance > 0, flag = 'B'. Optional filters: salesmancode, customercode, date_from/date_to (bill date), expecteddate_from/expecteddate_to (expected date)."""
    invoice_date_column = _resolve_invoice_date_column()
    date_col = invoice_date_column if '.' in invoice_date_column else f's.{invoice_date_column}'
    balance_col = _detect_column('tblsettlement', ['BALANCE', 'OUTSTANDING', 'NETBALANCE']) or 'balance'
    balance_sql = f'NVL(s.{balance_col}, 0)'
    settle_billno = _detect_column('tblsettlement', ['BILLNO', 'BILL_NO', 'billno']) or 'billno'
    settle_billdate = _detect_column('tblsettlement', ['BILLDATE', 'BILL_DATE', 'billdate']) or 'billdate'
    settle_cust = _detect_column('tblsettlement', ['CUSTOMERCODE', 'CUSTOMER_CODE', 'customercode']) or 'customercode'
    settle_emp = _detect_column('tblsettlement', ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
    settle_billamount = _detect_column('tblsettlement', ['BILLAMOUNT', 'BILL_AMOUNT', 'billamount']) or 'billamount'
    settle_paidamount = _detect_column('tblsettlement', ['PAIDAMOUNT', 'PAID_AMOUNT', 'paidamount']) or 'paidamount'
    settle_flag = _detect_column('tblsettlement', ['FLAG', 'FLAG_CODE', 'flag']) or 'flag'
    settle_expecteddate = _detect_column('tblsettlement', ['EXPECTEDDATE', 'EXPECTED_DATE', 'expecteddate', 'expected_date', 'EXPECTED', 'expected'])
    settle_remarks = _detect_column('tblsettlement', ['REMARKS', 'REMARK', 'remarks', 'remark'])
    if not settle_emp:
        return []
    expecteddate_sql = f's.{settle_expecteddate} AS expecteddate' if settle_expecteddate else 'NULL AS expecteddate'
    remarks_sql = f's.{settle_remarks} AS remarks' if settle_remarks else 'NULL AS remarks'
    emp_join = ''
    employee_name_column = None
    for et in ['EMPLOYEE1', 'employee1', 'EMPLOYEE', 'employee']:
        if not _table_exists(et):
            continue
        ec = _detect_column(et, ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
        if ec:
            emp_join = f'LEFT JOIN {et} e ON s.{settle_emp} = e.{ec}'
            employee_name_column = _detect_column(et, ['EMPLOYEENAME', 'EMPLOYEE_NAME', 'employeename'])
            break
    employee_name_sql = f'e.{employee_name_column}' if employee_name_column else 'NULL'
    cust_join = ''
    customer_name_column = None
    for ct in ['customers', 'CUSTOMERS', 'CUSTOMER', 'customer']:
        if not _table_exists(ct):
            continue
        cc = _detect_column(ct, ['CUST_CODE', 'CUSTOMERCODE', 'CUSTOMER_CODE', 'CODE'])
        if cc:
            cust_join = f'LEFT JOIN {ct} c ON s.{settle_cust} = c.{cc}'
            customer_name_column = _detect_column(ct, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME'])
            break
    customer_name_sql = f'c.{customer_name_column}' if customer_name_column else 'NULL'
    salesman_code_col = os.getenv('DASH_SALESMAN_CODE_COLUMN', 'salesmancode')
    settlement_salesman_col = _detect_column('tblsettlement', ['SALESMANCODE', 'SALESMAN_CODE', 'salesmancode', 'salesman'])
    salesman_name_col = os.getenv('DASH_SALESMAN_NAME_COLUMN') or _detect_column('SALESMAN', ['SALESMANNAME', 'SALESMAN_NAME', 'NAME'])
    salesman_join = ''
    salesmancode_sql = 'NULL AS salesmancode'
    salesmanname_sql = 'NULL AS salesmanname'
    if settlement_salesman_col:
        for st in ['SALESMAN', 'salesman', 'SALESMANMASTER', 'SALESMEN']:
            if not _table_exists(st):
                continue
            sc = _detect_column(st, ['SALESMANCODE', 'SALESMAN_CODE', 'salesmancode', 'CODE'])
            if sc:
                salesman_join = f'LEFT JOIN {st} sm ON sm.{sc} = s.{settlement_salesman_col}'
                salesmancode_sql = f's.{settlement_salesman_col} AS salesmancode'
                salesmanname_sql = f'sm.{salesman_name_col}' if salesman_name_col else 'NULL'
                salesmanname_sql = f'{salesmanname_sql} AS salesmanname'
                break
        else:
            salesmancode_sql = f's.{settlement_salesman_col} AS salesmancode'
    aging_clause = ''
    if bucket == 'all' or not bucket:
        aging_clause = ''
    elif bucket == '30':
        aging_clause = f'AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 30'
    elif bucket == '60':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 30 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 60'
    elif bucket == '90':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 60 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 90'
    elif bucket == '120':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 90 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 120'
    elif bucket == '120p':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 120'
    params: Dict[str, Any] = {}
    if employeecode:
        params['employeecode'] = employeecode
        employee_filter = f'AND s.{settle_emp} = :employeecode'
    else:
        employee_filter = ''
    salesman_filter = ''
    if salesmancode and str(salesmancode).strip() and settlement_salesman_col:
        params['salesmancode'] = str(salesmancode).strip()
        salesman_filter = 'AND s.{0} = :salesmancode'.format(settlement_salesman_col)
    customer_filter_emp = ''
    if customercode and str(customercode).strip():
        params['customercode'] = str(customercode).strip()
        customer_filter_emp = 'AND s.{0} = :customercode'.format(settle_cust)
    date_range_clause = ''
    if date_from and str(date_from).strip():
        params['date_from'] = str(date_from).strip()[:10]
        date_range_clause += " AND TRUNC(s.{0}) >= TO_DATE(:date_from, 'YYYY-MM-DD')".format(settle_billdate)
    if date_to and str(date_to).strip():
        params['date_to'] = str(date_to).strip()[:10]
        date_range_clause += " AND TRUNC(s.{0}) <= TO_DATE(:date_to, 'YYYY-MM-DD')".format(settle_billdate)
    expecteddate_range_clause = ''
    if settle_expecteddate:
        if expecteddate_from and str(expecteddate_from).strip():
            params['expecteddate_from'] = str(expecteddate_from).strip()[:10]
            expecteddate_range_clause += " AND TRUNC(s.{0}) >= TO_DATE(:expecteddate_from, 'YYYY-MM-DD')".format(settle_expecteddate)
        if expecteddate_to and str(expecteddate_to).strip():
            params['expecteddate_to'] = str(expecteddate_to).strip()[:10]
            expecteddate_range_clause += " AND TRUNC(s.{0}) <= TO_DATE(:expecteddate_to, 'YYYY-MM-DD')".format(settle_expecteddate)
    parts = [p for p in [emp_join, cust_join, salesman_join] if p]
    join_clause = ' '.join(parts)
    query = f"\n        SELECT\n            ROW_NUMBER() OVER (ORDER BY {date_col} DESC, s.{settle_billno} DESC) AS slno,\n            s.{settle_billno} AS billno,\n            s.{settle_billdate} AS billdate,\n            s.{settle_cust} AS customercode,\n            {customer_name_sql} AS customername,\n            {salesmancode_sql},\n            {salesmanname_sql},\n            s.{settle_emp} AS employeecode,\n            {employee_name_sql} AS employeename,\n            {expecteddate_sql},\n            {remarks_sql},\n            NVL(s.{settle_billamount}, 0) AS billamount,\n            NVL(s.{settle_paidamount}, 0) AS paidamount,\n            {balance_sql} AS outstanding\n        FROM tblsettlement s\n        {join_clause}\n        WHERE {balance_sql} > 0\n          AND s.{settle_flag} = 'B'\n          AND s.{settle_emp} IS NOT NULL\n          {aging_clause}\n          {employee_filter}\n          {salesman_filter}\n          {customer_filter_emp}\n          {date_range_clause}\n          {expecteddate_range_clause}\n        ORDER BY {date_col} DESC, s.{settle_billno} DESC\n    "
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except Exception as e:
        print(f'[ERROR get_employee_outstanding_details] {e}')
        import traceback
        traceback.print_exc()
        return []

def ensure_tblpaymentfollowup_exists() -> bool:
    """Create TBLPAYMENTFOLLOWUP and sequence if not exist. One row per follow-up (SLNO PK); same BILLNO can have multiple rows."""
    for name in ['TBLPAYMENTFOLLOWUP', 'tblpaymentfollowup']:
        if _table_exists(name):
            return True
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                try:
                    cur.execute('CREATE SEQUENCE TBLPAYMENTFOLLOWUP_SEQ START WITH 1 INCREMENT BY 1 NOCACHE')
                except Exception:
                    pass
                cur.execute('\n                    CREATE TABLE TBLPAYMENTFOLLOWUP (\n                        SLNO NUMBER PRIMARY KEY,\n                        BILLNO VARCHAR2(50) NOT NULL,\n                        EXPECTEDDATE DATE,\n                        REMARKS VARCHAR2(500),\n                        CREATEDAT DATE DEFAULT SYSDATE,\n                        CREATEDBY VARCHAR2(100)\n                    )\n                ')
            conn.commit()
        return True
    except Exception as e:
        print(f'[ERROR ensure_tblpaymentfollowup_exists] {e}')
        return False

def save_payment_followup(billno: str, expecteddate: Optional[str]=None, remarks: Optional[str]=None, updated_by: Optional[str]=None) -> tuple:
    """Insert one new row into TBLPAYMENTFOLLOWUP (SLNO from sequence) and update TBLSETTLEMENT for the given billno. One bill can have multiple follow-up rows. Returns (success: bool, message: str, slno: Optional[int])."""
    billno = (billno or '').strip()
    if not billno:
        return (False, 'Bill number is required', None)
    settlement_table = _detect_table(['TBLSETTLEMENT', 'tblsettlement'])
    if not settlement_table:
        return (False, 'TBLSETTLEMENT table not found', None)
    if not ensure_tblpaymentfollowup_exists():
        return (False, 'Could not create TBLPAYMENTFOLLOWUP', None)
    followup_table = 'TBLPAYMENTFOLLOWUP' if _table_exists('TBLPAYMENTFOLLOWUP') else 'tblpaymentfollowup'
    has_slno = 'SLNO' in (c.upper() for c in (_get_table_columns(followup_table) if followup_table else []))
    slno = None
    if has_slno:
        seq_name = 'TBLPAYMENTFOLLOWUP_SEQ'
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute('SELECT {0}.NEXTVAL FROM DUAL'.format(seq_name))
                    slno = cur.fetchone()[0]
        except Exception:
            pass
    settle_billno = _detect_column(settlement_table, ['BILLNO', 'BILL_NO', 'billno'])
    settle_flag = _detect_column(settlement_table, ['FLAG', 'flag'])
    settle_exp = _detect_column(settlement_table, ['EXPECTEDDATE', 'EXPECTED_DATE', 'expecteddate', 'expected_date', 'EXPECTED', 'expected'])
    settle_remark = _detect_column(settlement_table, ['REMARKS', 'REMARK', 'remarks', 'remark'])
    if not settle_billno or not settle_flag:
        return (False, 'Required columns not found in TBLSETTLEMENT', None)
    expecteddate_oracle = None
    if expecteddate and str(expecteddate).strip():
        s = str(expecteddate).strip()[:10]
        if len(s) >= 10 and '-' in s:
            try:
                from datetime import datetime as _dt
                d = _dt.strptime(s, '%Y-%m-%d')
                expecteddate_oracle = d.strftime('%d/%b/%Y').upper()
            except ValueError:
                pass
    remarks_val = (remarks or '').strip()[:500] or None
    created_by_val = (updated_by or '').strip() or None
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if has_slno:
                    if slno is not None:
                        cur.execute(f'\n                            INSERT INTO {followup_table} (SLNO, BILLNO, EXPECTEDDATE, REMARKS, CREATEDAT, CREATEDBY)\n                            VALUES (:slno, :billno, :exp, :rem, SYSDATE, :cby)\n                            ', {'slno': slno, 'billno': billno, 'exp': expecteddate_oracle, 'rem': remarks_val, 'cby': created_by_val})
                    else:
                        cur.execute(f'\n                            INSERT INTO {followup_table} (SLNO, BILLNO, EXPECTEDDATE, REMARKS, CREATEDAT, CREATEDBY)\n                            SELECT NVL(MAX(SLNO),0)+1, :billno, :exp, :rem, SYSDATE, :cby FROM {followup_table}\n                            ', {'billno': billno, 'exp': expecteddate_oracle, 'rem': remarks_val, 'cby': created_by_val})
                        slno = None
                else:
                    cur.execute(f'\n                        MERGE INTO {followup_table} t\n                        USING (SELECT :billno AS billno FROM DUAL) s\n                        ON (t.BILLNO = s.billno)\n                        WHEN MATCHED THEN\n                          UPDATE SET t.EXPECTEDDATE = :exp, t.REMARKS = :rem\n                        WHEN NOT MATCHED THEN\n                          INSERT (BILLNO, EXPECTEDDATE, REMARKS, CREATEDAT, CREATEDBY)\n                          VALUES (:billno, :exp, :rem, SYSDATE, :cby)\n                        ', {'billno': billno, 'exp': expecteddate_oracle, 'rem': remarks_val, 'cby': created_by_val})
                if settle_exp or settle_remark:
                    set_parts = []
                    params_f: Dict[str, Any] = {'billno': billno}
                    if settle_exp and expecteddate_oracle:
                        set_parts.append(f"{settle_exp} = TO_DATE(:exp, 'DD/MON/YYYY')")
                        params_f['exp'] = expecteddate_oracle
                    elif settle_exp:
                        set_parts.append(f'{settle_exp} = NULL')
                    if settle_remark:
                        set_parts.append(f'{settle_remark} = :rem')
                        params_f['rem'] = remarks_val
                    if set_parts:
                        cur.execute(f"UPDATE {settlement_table} SET {', '.join(set_parts)} WHERE {settle_billno} = :billno AND (NVL({settle_flag}, 'B') = 'B')", params_f)
            conn.commit()
        msg = 'Payment follow-up saved.'
        if slno is not None:
            msg = 'Payment follow-up #{} saved.'.format(slno)
        return (True, msg, slno)
    except Exception as e:
        print(f'[ERROR save_payment_followup] {e}')
        import traceback
        traceback.print_exc()
        return (False, str(e), None)

def insert_payment_followup_only(billno: str, expecteddate: Optional[str]=None, remarks: Optional[str]=None, created_by: Optional[str]=None) -> tuple:
    """Insert one row into TBLPAYMENTFOLLOWUP only (no TBLSETTLEMENT update). Use when tblsettlement was already updated elsewhere (e.g. Update C/O Employee). Returns (success: bool, message: str)."""
    billno = (billno or '').strip()
    if not billno:
        return (False, 'Bill number is required')
    if not ensure_tblpaymentfollowup_exists():
        return (False, 'Could not create TBLPAYMENTFOLLOWUP')
    followup_table = 'TBLPAYMENTFOLLOWUP' if _table_exists('TBLPAYMENTFOLLOWUP') else 'tblpaymentfollowup'
    cols = _get_table_columns(followup_table) if followup_table else []
    has_slno = 'SLNO' in [c.upper() for c in cols]
    expecteddate_oracle = None
    if expecteddate and str(expecteddate).strip():
        s = str(expecteddate).strip()[:10]
        if len(s) >= 10 and '-' in s:
            try:
                from datetime import datetime as _dt
                d = _dt.strptime(s, '%Y-%m-%d')
                expecteddate_oracle = d.strftime('%d/%b/%Y').upper()
            except ValueError:
                pass
    remarks_val = (remarks or '').strip()[:500] or None
    created_by_val = (created_by or '').strip() or None
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if has_slno:
                    try:
                        cur.execute('SELECT TBLPAYMENTFOLLOWUP_SEQ.NEXTVAL FROM DUAL')
                        slno = cur.fetchone()[0]
                    except Exception:
                        slno = None
                    if slno is not None:
                        cur.execute(f'\n                            INSERT INTO {followup_table} (SLNO, BILLNO, EXPECTEDDATE, REMARKS, CREATEDAT, CREATEDBY)\n                            VALUES (:slno, :billno, :exp, :rem, SYSDATE, :cby)\n                            ', {'slno': slno, 'billno': billno, 'exp': expecteddate_oracle, 'rem': remarks_val, 'cby': created_by_val})
                    else:
                        cur.execute(f'\n                            INSERT INTO {followup_table} (SLNO, BILLNO, EXPECTEDDATE, REMARKS, CREATEDAT, CREATEDBY)\n                            SELECT NVL(MAX(SLNO),0)+1, :billno, :exp, :rem, SYSDATE, :cby FROM {followup_table}\n                            ', {'billno': billno, 'exp': expecteddate_oracle, 'rem': remarks_val, 'cby': created_by_val})
                else:
                    cur.execute(f'\n                        MERGE INTO {followup_table} t\n                        USING (SELECT :billno AS billno FROM DUAL) s\n                        ON (t.BILLNO = s.billno)\n                        WHEN MATCHED THEN\n                          UPDATE SET t.EXPECTEDDATE = :exp, t.REMARKS = :rem\n                        WHEN NOT MATCHED THEN\n                          INSERT (BILLNO, EXPECTEDDATE, REMARKS, CREATEDAT, CREATEDBY)\n                          VALUES (:billno, :exp, :rem, SYSDATE, :cby)\n                        ', {'billno': billno, 'exp': expecteddate_oracle, 'rem': remarks_val, 'cby': created_by_val})
            conn.commit()
        return (True, 'OK')
    except Exception as e:
        print(f'[ERROR insert_payment_followup_only] {e}')
        import traceback
        traceback.print_exc()
        return (False, str(e))

def get_employee_outstanding_count(employeecode: Optional[str]) -> int:
    """Return count of outstanding invoice rows in tblsettlement for the given employeecode (balance > 0, flag = 'B'). Uses active connection."""
    employeecode = (employeecode or '').strip()
    if not employeecode:
        return 0
    settle_table = _detect_table(['TBLSETTLEMENT', 'tblsettlement'])
    if not settle_table:
        return 0
    settle_emp = _detect_column(settle_table, ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
    settle_flag = _detect_column(settle_table, ['FLAG', 'flag'])
    balance_col = _detect_column(settle_table, ['BALANCE', 'OUTSTANDING', 'NETBALANCE']) or 'balance'
    if not settle_emp or not settle_flag:
        return 0
    balance_sql = f'NVL({balance_col}, 0)'
    query = f"\n        SELECT COUNT(*) FROM {settle_table}\n        WHERE {balance_sql} > 0\n          AND (NVL({settle_flag}, 'B') = 'B')\n          AND TRIM(TO_CHAR({settle_emp})) = TRIM(:employeecode)\n    "
    try:
        return _get_count(query, {'employeecode': employeecode})
    except Exception as e:
        print(f'[ERROR get_employee_outstanding_count] {e}')
        return 0

def get_payment_followups(billno: str) -> List[Dict[str, Any]]:
    """Return list of payment follow-up rows for the given billno from TBLPAYMENTFOLLOWUP (SLNO, BILLNO, EXPECTEDDATE, REMARKS, CREATEDAT, CREATEDBY). Newest first."""
    billno = (billno or '').strip()
    if not billno:
        return []
    for name in ['TBLPAYMENTFOLLOWUP', 'tblpaymentfollowup']:
        if not _table_exists(name):
            continue
        cols = _get_table_columns(name)
        if 'BILLNO' not in [c.upper() for c in cols]:
            continue
        has_slno = 'SLNO' in [c.upper() for c in cols]
        slno_sql = 'SLNO AS slno,' if has_slno else 'NULL AS slno,'
        order_by = 'ORDER BY SLNO DESC' if has_slno else 'ORDER BY CREATEDAT DESC NULLS LAST'
        try:
            createdby_sql = 'CREATEDBY AS createdby'
            if 'UPDATEDBY' in [c.upper() for c in cols]:
                createdby_sql = 'NVL(CREATEDBY, UPDATEDBY) AS createdby'
            query = f'\n                SELECT {slno_sql} BILLNO AS billno,\n                    EXPECTEDDATE AS expecteddate,\n                    REMARKS AS remarks,\n                    CREATEDAT AS createdat,\n                    {createdby_sql}\n                FROM {name}\n                WHERE BILLNO = :billno\n                {order_by}\n            '
            _, rows = _fetch_rows(query, {'billno': billno})
            return rows or []
        except Exception as e:
            print(f'[ERROR get_payment_followups] {e}')
            return []
    return []

def get_route_outstanding_aging() -> List[Dict[str, Any]]:
    """Get route outstanding split by aging buckets (30/60/90/120/120+). Grouped by route from customers table."""
    invoice_date_column = _resolve_invoice_date_column()
    date_col = invoice_date_column if '.' in invoice_date_column else f's.{invoice_date_column}'
    balance_col = _detect_column('tblsettlement', ['BALANCE', 'OUTSTANDING', 'NETBALANCE']) or 'balance'
    balance_sql = f'NVL(s.{balance_col}, 0)'
    customer_table = 'customer'
    if not _table_exists(customer_table):
        print(f'[DEBUG get_route_outstanding_aging] customer table not found')
        return []
    customer_code_col = _detect_column(customer_table, ['CUSTOMERCODE', 'customercode', 'CUSTOMER_CODE', 'customer_code', 'CUST_CODE', 'cust_code', 'CODE', 'code'])
    if not customer_code_col:
        print(f'[DEBUG get_route_outstanding_aging] Customer code column not found in customer table')
        return []
    customer_route_col = _detect_column(customer_table, ['routeno', 'ROUTENO', 'ROUTE_NO', 'route_no', 'route', 'ROUTE', 'ROUTE_CODE', 'route_code', 'ROUTECODE', 'routecode'])
    if not customer_route_col:
        print(f'[DEBUG get_route_outstanding_aging] Route column not found in customer table. Cannot proceed.')
        return []
    route_table = None
    route_code_col = None
    route_name_col = None
    for rt in ['tblroutes', 'TBLROUTES', 'tblroute', 'TBLROUTE', 'ROUTES', 'routes', 'ROUTE', 'route']:
        if not _table_exists(rt):
            continue
        route_code_col = _detect_column(rt, ['routeno', 'ROUTENO', 'ROUTE_NO', 'route_no', 'ROUTE_CODE', 'route_code', 'ROUTECODE', 'routecode', 'ROUTE', 'route'])
        if route_code_col:
            route_table = rt
            route_name_col = _detect_column(rt, ['routename', 'ROUTENAME', 'ROUTE_NAME', 'route_name', 'ROUTENAM', 'routenam', 'NAME', 'name'])
            break
    if not route_table or not route_code_col:
        print(f'[DEBUG get_route_outstanding_aging] tblroutes table not found or route code column missing')
        return []
    if not route_name_col:
        print(f'[DEBUG get_route_outstanding_aging] Route name column not found in {route_table}')
    settle_cust = _detect_column('tblsettlement', ['CUSTOMERCODE', 'customercode', 'CUSTOMER_CODE', 'customer_code']) or 'customercode'
    customer_join = f'LEFT JOIN {customer_table} c ON s.{settle_cust} = c.{customer_code_col}'
    route_join = f'LEFT JOIN {route_table} r ON c.{customer_route_col} = r.{route_code_col}'
    route_code_sql = f'NVL(r.{route_code_col}, c.{customer_route_col})'
    route_name_sql = f'r.{route_name_col}' if route_name_col else 'NULL'
    query = f"\n        SELECT\n            {route_code_sql} AS routecode,\n            {route_name_sql} AS routename,\n            SUM(CASE WHEN TRUNC({date_col}) >= TRUNC(SYSDATE) - 30 THEN {balance_sql} ELSE 0 END) AS d30,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 30\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 60 THEN {balance_sql} ELSE 0 END) AS d60,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 60\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 90 THEN {balance_sql} ELSE 0 END) AS d90,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 90\n                     AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 120 THEN {balance_sql} ELSE 0 END) AS d120,\n            SUM(CASE WHEN TRUNC({date_col}) < TRUNC(SYSDATE) - 120 THEN {balance_sql} ELSE 0 END) AS d120p\n        FROM tblsettlement s\n        {customer_join}\n        {route_join}\n        WHERE {balance_sql} <> 0\n          AND s.flag = 'B'\n          AND (r.{route_code_col} IS NOT NULL OR c.{customer_route_col} IS NOT NULL)\n        GROUP BY {route_code_sql}, {route_name_sql}\n        ORDER BY routecode\n    "
    try:
        print(f'[DEBUG get_route_outstanding_aging] Main query: {query}')
        print(f'[DEBUG get_route_outstanding_aging] Customer table: {customer_table}, Route table: {route_table}')
        print(f'[DEBUG get_route_outstanding_aging] Customer code col: {customer_code_col}')
        print(f'[DEBUG get_route_outstanding_aging] Customer route col: {customer_route_col}')
        print(f'[DEBUG get_route_outstanding_aging] Route code col: {route_code_col}, Route name col: {route_name_col}')
        _, rows = _fetch_rows(query, {})
        print(f'[DEBUG get_route_outstanding_aging] Found {len(rows)} rows')
        if rows:
            print(f"[DEBUG get_route_outstanding_aging] First row sample: routecode={rows[0].get('routecode')}, routename={rows[0].get('routename')}")
        return rows
    except Exception as e:
        print(f'[ERROR get_route_outstanding_aging] {e}')
        import traceback
        traceback.print_exc()
        return []

def get_route_outstanding_details(routecode: Optional[str], bucket: str) -> List[Dict[str, Any]]:
    """Fetch invoice-level outstanding for a route and aging bucket. Details from tblsettlement; route name from route table."""
    invoice_date_column = _resolve_invoice_date_column()
    date_col = invoice_date_column if '.' in invoice_date_column else f's.{invoice_date_column}'
    balance_col = _detect_column('tblsettlement', ['BALANCE', 'OUTSTANDING', 'NETBALANCE']) or 'balance'
    balance_sql = f'NVL(s.{balance_col}, 0)'
    settle_billno = _detect_column('tblsettlement', ['BILLNO', 'BILL_NO', 'billno']) or 'billno'
    settle_billdate = _detect_column('tblsettlement', ['BILLDATE', 'BILL_DATE', 'billdate']) or 'billdate'
    settle_cust = _detect_column('tblsettlement', ['CUSTOMERCODE', 'CUSTOMER_CODE', 'customercode']) or 'customercode'
    settle_billamount = _detect_column('tblsettlement', ['BILLAMOUNT', 'BILL_AMOUNT', 'billamount']) or 'billamount'
    settle_paidamount = _detect_column('tblsettlement', ['PAIDAMOUNT', 'PAID_AMOUNT', 'paidamount']) or 'paidamount'
    settle_flag = _detect_column('tblsettlement', ['FLAG', 'FLAG_CODE', 'flag']) or 'flag'
    settle_salesman = _detect_column('tblsettlement', ['SALESMANCODE', 'SALESMAN_CODE', 'salesmancode', 'salesman'])
    settle_employee = _detect_column('tblsettlement', ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
    settle_expecteddate = _detect_column('tblsettlement', ['EXPECTEDDATE', 'EXPECTED_DATE', 'expecteddate', 'expected_date', 'EXPECTED', 'expected'])
    settle_remarks = _detect_column('tblsettlement', ['REMARKS', 'REMARK', 'remarks', 'remark'])
    expecteddate_sql = f's.{settle_expecteddate} AS expecteddate' if settle_expecteddate else 'NULL AS expecteddate'
    remarks_sql = f's.{settle_remarks} AS remarks' if settle_remarks else 'NULL AS remarks'
    customer_table = 'customer'
    if not _table_exists(customer_table):
        print(f'[DEBUG get_route_outstanding_details] customer table not found')
        return []
    customer_code_col = _detect_column(customer_table, ['CUSTOMERCODE', 'customercode', 'CUSTOMER_CODE', 'customer_code', 'CUST_CODE', 'cust_code', 'CODE', 'code'])
    if not customer_code_col:
        print(f'[DEBUG get_route_outstanding_details] Customer code column not found in customer table')
        return []
    customer_name_col = _detect_column(customer_table, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME'])
    customer_route_col = _detect_column(customer_table, ['routeno', 'ROUTENO', 'ROUTE_NO', 'route_no', 'route', 'ROUTE', 'ROUTE_CODE', 'route_code', 'ROUTECODE', 'routecode'])
    if not customer_route_col:
        print(f'[DEBUG get_route_outstanding_details] Route column (routeno) not found in customer table. Cannot proceed.')
        return []
    route_table = None
    route_code_col = None
    route_name_col = None
    for rt in ['tblroutes', 'TBLROUTES', 'tblroute', 'TBLROUTE', 'ROUTES', 'routes', 'ROUTE', 'route']:
        if not _table_exists(rt):
            continue
        route_code_col = _detect_column(rt, ['routeno', 'ROUTENO', 'ROUTE_NO', 'route_no', 'ROUTE_CODE', 'route_code', 'ROUTECODE', 'routecode', 'ROUTE', 'route'])
        if route_code_col:
            route_table = rt
            route_name_col = _detect_column(rt, ['routename', 'ROUTENAME', 'ROUTE_NAME', 'route_name', 'ROUTENAM', 'routenam', 'NAME', 'name'])
            break
    if not route_table or not route_code_col:
        print(f'[DEBUG get_route_outstanding_details] tblroutes table not found or route code column missing')
        return []
    if not route_name_col:
        print(f'[DEBUG get_route_outstanding_details] Route name column not found in {route_table}')
    settle_cust = _detect_column('tblsettlement', ['CUSTOMERCODE', 'customercode', 'CUSTOMER_CODE', 'customer_code']) or 'customercode'
    customer_join = f'LEFT JOIN {customer_table} c ON s.{settle_cust} = c.{customer_code_col}'
    route_join = f'LEFT JOIN {route_table} r ON c.{customer_route_col} = r.{route_code_col}'
    customer_name_sql = f'c.{customer_name_col}' if customer_name_col else 'NULL'
    salesman_join = ''
    salesmancode_sql = 'NULL'
    salesmanname_sql = 'NULL'
    if settle_salesman:
        salesman_code_col = os.getenv('DASH_SALESMAN_CODE_COLUMN', 'salesmancode')
        salesman_name_col = os.getenv('DASH_SALESMAN_NAME_COLUMN')
        if not salesman_name_col:
            salesman_name_col = _detect_column('SALESMAN', ['SALESMANNAME', 'SALESMAN_NAME', 'NAME'])
        if salesman_name_col:
            salesman_join = f'LEFT JOIN salesman sm ON sm.{salesman_code_col} = s.{settle_salesman}'
            salesmancode_sql = f's.{settle_salesman}'
            salesmanname_sql = f'sm.{salesman_name_col}'
    employee_join = ''
    employeecode_sql = 'NULL'
    employeename_sql = 'NULL'
    if settle_employee:
        for et in ['EMPLOYEE1', 'employee1', 'EMPLOYEE', 'employee']:
            if not _table_exists(et):
                continue
            emp_code_col = _detect_column(et, ['EMPLOYEECODE', 'EMPLOYEE_CODE', 'employeecode'])
            if emp_code_col:
                emp_name_col = _detect_column(et, ['EMPLOYEENAME', 'EMPLOYEE_NAME', 'employeename'])
                employee_join = f'LEFT JOIN {et} e ON s.{settle_employee} = e.{emp_code_col}'
                employeecode_sql = f's.{settle_employee}'
                employeename_sql = f'e.{emp_name_col}' if emp_name_col else 'NULL'
                break
    route_code_sql = f'r.{route_code_col}'
    route_name_sql = f"NVL(r.{route_name_col}, '')" if route_name_col else "''"
    aging_clause = ''
    if bucket == 'all' or not bucket:
        aging_clause = ''
    elif bucket == '30':
        aging_clause = f'AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 30'
    elif bucket == '60':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 30 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 60'
    elif bucket == '90':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 60 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 90'
    elif bucket == '120':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 90 AND TRUNC({date_col}) >= TRUNC(SYSDATE) - 120'
    elif bucket == '120p':
        aging_clause = f'AND TRUNC({date_col}) < TRUNC(SYSDATE) - 120'
    params: Dict[str, Any] = {}
    if routecode:
        params['routecode'] = routecode
        route_filter = f'AND r.{route_code_col} = :routecode'
    else:
        route_filter = ''
    query = f"\n        SELECT\n            ROW_NUMBER() OVER (ORDER BY {date_col} DESC, s.{settle_billno} DESC) AS slno,\n            s.{settle_billno} AS billno,\n            s.{settle_billdate} AS billdate,\n            s.{settle_cust} AS customercode,\n            {customer_name_sql} AS customername,\n            {route_code_sql} AS routecode,\n            {route_name_sql} AS routename,\n            {salesmancode_sql} AS salesmancode,\n            {salesmanname_sql} AS salesmanname,\n            {employeecode_sql} AS employeecode,\n            {employeename_sql} AS employeename,\n            {expecteddate_sql},\n            {remarks_sql},\n            NVL(s.{settle_billamount}, 0) AS billamount,\n            NVL(s.{settle_paidamount}, 0) AS paidamount,\n            {balance_sql} AS outstanding\n        FROM tblsettlement s\n        {customer_join}\n        {route_join}\n        {salesman_join}\n        {employee_join}\n        WHERE {balance_sql} > 0\n          AND s.{settle_flag} = 'B'\n          AND c.{customer_route_col} IS NOT NULL\n          AND r.{route_code_col} IS NOT NULL\n          {aging_clause}\n          {route_filter}\n        ORDER BY {date_col} DESC, s.{settle_billno} DESC\n    "
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except Exception as e:
        print(f'[ERROR get_route_outstanding_details] {e}')
        import traceback
        traceback.print_exc()
        return []

def get_customers_list() -> List[Dict[str, Any]]:
    customer_name_column = os.getenv('DASH_CUSTOMER_NAME_COLUMN')
    if not customer_name_column:
        detected = _detect_column('CUSTOMERS', ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME'])
        customer_name_column = detected
    name_sql = customer_name_column if customer_name_column else 'NULL'
    query = f"\n        SELECT DISTINCT\n            c.cust_code AS code,\n            {name_sql} AS name,\n            (SELECT SUM(NVL(balance, 0)) FROM tblsettlement WHERE customercode = c.cust_code AND balance <> 0 AND flag = 'B') AS outstanding\n        FROM customers c\n        WHERE EXISTS (SELECT 1 FROM tblsettlement WHERE customercode = c.cust_code AND balance <> 0 AND flag = 'B')\n        ORDER BY c.cust_code\n    "
    try:
        _, rows = _fetch_rows(query, {})
    except cx_Oracle.DatabaseError:
        return []
    return rows

def _customer_picker_search_where(
    code_col: str,
    name_col: Optional[str],
    phone_col: Optional[str],
    search: str,
    params: Dict[str, Any],
    *,
    prefix_only: bool = False,
) -> str:
    """Build capped customer-picker search filter (prefix or contains)."""
    ps = (search or '').strip()
    if not ps:
        return ''
    params['pick_sw_name'] = f'{ps.upper()}%' if prefix_only else f'%{ps.upper()}%'
    params['pick_sw_code'] = f'{ps}%' if prefix_only else f'%{ps}%'
    parts = [f'TO_CHAR(c.{code_col}) LIKE :pick_sw_code']
    if name_col:
        parts.append(f'UPPER(c.{name_col}) LIKE :pick_sw_name')
    if phone_col:
        parts.append(f'TO_CHAR(c.{phone_col}) LIKE :pick_sw_code')
    return ' AND (' + ' OR '.join(parts) + ')'


def get_customers_master_list(
    *,
    for_picker: bool=False,
    picker_search: str='',
    picker_limit: int=300,
    picker_billing_type: str='',
) -> List[Dict[str, Any]]:
    """Get customers list for sales screens.

    Default (for_picker=False): full list — legacy behaviour for callers that still need it.

    for_picker=True: capped rows for modal pickers (search optional; avoids loading every row).
    picker_billing_type: optional ``CASH`` / ``CREDIT`` filter for the sales customer picker.
    """
    table_candidates = ['CUSTOMER', 'CUSTOMERS']
    for table_name in table_candidates:
        try:
            code_col = _detect_column(table_name, ['CUSTOMERCODE', 'CUST_CODE', 'CUSTOMER_CODE', 'CODE'])
            name_col = _detect_column(table_name, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME'])
            address_col = _detect_column(table_name, ['ADDRESS', 'ADDR', 'CUSTOMERADDRESS', 'CUST_ADDRESS'])
            phone_col = _detect_column(table_name, ['MOBILENO', 'MOBILE', 'PHONE', 'TEL'])
            billing_col = _customer_billing_type_column(table_name)
            invoice_col = _detect_column(table_name, ['INVOICECODE', 'INVOICE_CODE', 'INVOICETYPE', 'TYPECODE'])
            category_col = _detect_column(table_name, ['CUSTOMERCATEGORY', 'CATEGORY', 'CATEGORYCODE', 'CUSTCATEGORY'])
            credit_limit_col = _detect_column(table_name, ['CREDITLIMIT', 'creditlimit', 'CREDIT_LIMIT', 'CREDITLIMITAMOUNT', 'CREDITAMOUNT', 'CREDIT_AMT'])
            recv_col = _detect_column(table_name, ['RECEIVABLEACCOUNT', 'receivableaccount', 'RECEIVABLE_AC', 'receivable_acct'])
            points_col = _detect_column(table_name, ['TOTALPOINTS', 'POINTS', 'LOYALTYPOINTS', 'LOYALTY_POINTS', 'TOTAL_POINTS'])
            current_credit_col = _detect_column(table_name, ['CURRENTCREDIT', 'CURRENT_CREDIT', 'CURRCREDIT', 'CURRENTCREDITAMOUNT', 'CURRENT_CREDIT_AMOUNT', 'CREDITBALANCE', 'CREDITBAL'])
            category_table = 'TBLCUSTOMERCATEGORY'
            category_code_col = _detect_column(category_table, ['CATEGORYCODE', 'CODE', 'CUSTOMERCATEGORY', 'CATCODE'])
            category_name_col = _detect_column(category_table, ['CATEGORYNAME', 'NAME', 'CUSTOMERCATEGORYNAME', 'CATNAME'])
            if not code_col:
                continue
            name_sql = name_col if name_col else 'NULL'
            address_sql = address_col if address_col else 'NULL'
            phone_sql = phone_col if phone_col else 'NULL'
            if billing_col:
                invoice_sql = f"NVL(NULLIF(TRIM(UPPER(c.{billing_col})), ''), 'CASH')"
            elif invoice_col:
                invoice_sql = (
                    f"CASE WHEN c.{invoice_col} = 2 THEN 'CREDIT' "
                    f"WHEN c.{invoice_col} = 1 THEN 'CASH' ELSE 'CASH' END"
                )
            else:
                invoice_sql = "'CASH'"
            category_sql = f'c.{category_col}' if category_col else 'NULL'
            credit_limit_sql = f'c.{credit_limit_col}' if credit_limit_col else '0'
            recv_sql = f'c.{recv_col}' if recv_col else 'NULL'
            points_sql = f'c.{points_col}' if points_col else '0'
            current_credit_sql = f'NVL(c.{current_credit_col}, 0)' if current_credit_col else '0'
            category_name_sql = 'NULL'
            join_sql = ''
            if not for_picker and category_col and category_code_col and category_name_col:
                category_name_sql = f'cat.{category_name_col}'
                join_sql = f'LEFT JOIN {category_table} cat ON c.{category_col} = cat.{category_code_col}'
            # Outstanding: GL receivable only; 0 when GL is not configured.
            outstanding_sql = '0'
            settle_join_sql = ''
            where_extra = ''
            params: Dict[str, Any] = {}
            lim = 300
            ps_raw = ''
            billing_where = ''
            if for_picker:
                try:
                    lim = max(1, min(int(picker_limit or 300), 500))
                except (TypeError, ValueError):
                    lim = 300
                ps_raw = (picker_search or '').strip()
                params['pick_lim'] = lim
                want_bt = normalize_customer_billing_type(picker_billing_type) if str(picker_billing_type or '').strip() else ''
                # Only filter when caller explicitly asks for CASH/CREDIT.
                if str(picker_billing_type or '').strip() and want_bt in ('CASH', 'CREDIT'):
                    if billing_col:
                        if want_bt == 'CREDIT':
                            billing_where = (
                                f" AND UPPER(TRIM(TO_CHAR(c.{billing_col}))) IN ('CREDIT','CR','R','2')"
                            )
                        else:
                            billing_where = (
                                f" AND ("
                                f"c.{billing_col} IS NULL OR "
                                f"TRIM(TO_CHAR(c.{billing_col})) IS NULL OR "
                                f"UPPER(TRIM(TO_CHAR(c.{billing_col}))) IN ('CASH','C','1','')"
                                f")"
                            )
                    elif invoice_col:
                        if want_bt == 'CREDIT':
                            billing_where = f' AND NVL(c.{invoice_col}, 0) = 2'
                        else:
                            billing_where = f' AND NVL(c.{invoice_col}, 0) <> 2'
            tail_sql = f'WHERE 1=1 {where_extra}\n                ORDER BY c.{code_col}' if for_picker else f'ORDER BY c.{code_col}'
            inner_sql = f'\n                SELECT\n                    c.{code_col} AS CODE,\n                    {name_sql} AS NAME,\n                    {address_sql} AS ADDRESS,\n                    {phone_sql} AS PHONE,\n                    {invoice_sql} AS CUSTOMER_BILLING_TYPE,\n                    {category_sql} AS CATEGORYCODE,\n                    {category_name_sql} AS CATEGORYNAME,\n                    {credit_limit_sql} AS CREDITLIMIT,\n                    {recv_sql} AS RECEIVABLEACCOUNT,\n                    {points_sql} AS TOTALPOINTS,\n                    {current_credit_sql} AS CURRENTCREDIT,\n                    {outstanding_sql} AS OUTSTANDINGCASH\n                FROM {table_name} c\n                {join_sql}\n                {settle_join_sql}\n                {tail_sql}\n            '

            def _run_picker_query(search_where: str, run_params: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
                qp = run_params if run_params is not None else params
                q_inner = inner_sql.replace(
                    f'WHERE 1=1 {where_extra}',
                    f'WHERE 1=1{search_where}',
                )
                query = f'\n                    SELECT CODE, NAME, ADDRESS, PHONE, CUSTOMER_BILLING_TYPE, CATEGORYCODE, CATEGORYNAME,\n                           CREDITLIMIT, RECEIVABLEACCOUNT, TOTALPOINTS, CURRENTCREDIT, OUTSTANDINGCASH\n                    FROM (\n                        SELECT inn.*, ROWNUM AS pick_rn FROM (\n                            {q_inner}\n                        ) inn WHERE ROWNUM <= :pick_lim\n                    )\n                    WHERE pick_rn >= 1\n                '
                _, run_rows = _fetch_rows(query, qp)
                return run_rows or []

            if for_picker:
                rows: List[Dict[str, Any]] = []
                if ps_raw:
                    prefix_where = _customer_picker_search_where(
                        code_col, name_col, phone_col, ps_raw, params, prefix_only=True,
                    ) + billing_where
                    rows = _run_picker_query(prefix_where)
                    if not rows:
                        contains_params: Dict[str, Any] = {'pick_lim': lim}
                        contains_where = _customer_picker_search_where(
                            code_col, name_col, phone_col, ps_raw, contains_params, prefix_only=False,
                        ) + billing_where
                        rows = _run_picker_query(contains_where, contains_params)
                else:
                    rows = _run_picker_query(billing_where)
            else:
                query = inner_sql
                _, rows = _fetch_rows(query, params if params else {})
            if for_picker:
                for r in rows or []:
                    bt = normalize_customer_billing_type(
                        r.get('CUSTOMER_BILLING_TYPE') or r.get('customer_billing_type')
                    )
                    r['CUSTOMER_BILLING_TYPE'] = bt
                    r['customer_billing_type'] = bt
                    cur = round(float(r.get('CURRENTCREDIT') or r.get('currentcredit') or 0), 2)
                    r['CURRENTCREDIT'] = cur
                    r['currentcredit'] = cur
                    r['OUTSTANDINGCASH'] = cur if bt == 'CREDIT' else 0.0
                    r['outstandingcash'] = r['OUTSTANDINGCASH']
                return rows
            gl_ctx = _customer_gl_receivable_context()
            doc_totals = _customer_open_documents_outstanding_totals() if gl_ctx else {}
            for r in rows or []:
                bt = normalize_customer_billing_type(
                    r.get('CUSTOMER_BILLING_TYPE') or r.get('customer_billing_type')
                )
                r['CUSTOMER_BILLING_TYPE'] = bt
                r['customer_billing_type'] = bt
                if gl_ctx:
                    code = r.get('CODE') or r.get('code')
                    recv_ac = r.get('RECEIVABLEACCOUNT') or r.get('receivableaccount')
                    bal = _customer_list_gl_outstanding(code, recv_ac, ctx=gl_ctx, doc_totals=doc_totals)
                    r['OUTSTANDINGCASH'] = bal
                    r['outstandingcash'] = bal
                    r['CURRENTCREDIT'] = bal
                    r['currentcredit'] = bal
                else:
                    r['OUTSTANDINGCASH'] = 0
                    r['outstandingcash'] = 0
                    r['CURRENTCREDIT'] = 0
                    r['currentcredit'] = 0
            return rows
        except Exception:
            continue
    return []

def get_customer_loyalty_for_picker(location_code: int, *, picker_search: str='', picker_limit: int=300) -> List[Dict[str, Any]]:
    """CUSTOMERLOYALTY rows for POS loyalty customer picker (same general shape as ``get_customers_master_list`` picker rows)."""
    ensure_customerloyalty_table()
    if not _table_exists('CUSTOMERLOYALTY'):
        return []
    try:
        lim = max(1, min(int(picker_limit or 300), 500))
    except (TypeError, ValueError):
        lim = 300
    params: Dict[str, Any] = {'loc': int(location_code), 'pick_lim': lim}
    where_extra = ''
    ps = (picker_search or '').strip()
    if ps:
        params['pick_sw'] = f'%{ps}%'
        where_extra = "\n                AND (\n                    UPPER(NVL(c.CUSTOMERNAME, '')) LIKE UPPER(:pick_sw)\n                    OR TO_CHAR(c.CUSTOMERCODE) LIKE :pick_sw\n                    OR UPPER(NVL(c.MOB, '')) LIKE UPPER(:pick_sw)\n                    OR UPPER(NVL(c.PHONE1, '')) LIKE UPPER(:pick_sw)\n                    OR UPPER(NVL(c.PHONE2, '')) LIKE UPPER(:pick_sw)\n                    OR UPPER(NVL(c.EMAILID, '')) LIKE UPPER(:pick_sw)\n                )\n            "
    cols_loy = {str(c).upper() for c in (_get_table_columns('CUSTOMERLOYALTY') or [])}
    cardno_sel = 'NVL(c.CARDNO, 0) AS cardno' if 'CARDNO' in cols_loy else '0 AS cardno'
    inner_sql = f"\n            SELECT\n                c.CUSTOMERCODE AS code,\n                c.CUSTOMERNAME AS name,\n                TRIM(NVL(c.MOB, NVL(c.PHONE1, c.PHONE2))) AS phone,\n                0 AS creditlimit,\n                0 AS outstandingcash,\n                NVL(c.TOTALPOINTS, 0) AS totalpoints,\n                {cardno_sel}\n            FROM CUSTOMERLOYALTY c\n            WHERE c.LOCATIONCODE = :loc\n            {where_extra}\n            ORDER BY c.CUSTOMERCODE\n        "
    query = f"\n            SELECT code, name, phone, creditlimit, outstandingcash, totalpoints, cardno\n            FROM (\n                SELECT inn.*, ROWNUM AS pick_rn FROM (\n                    {inner_sql}\n                ) inn WHERE ROWNUM <= :pick_lim\n            )\n            WHERE pick_rn >= 1\n        "
    return _safe_rows(query, params)

def peek_next_customer_loyalty_code(location_code: int) -> Optional[int]:
    """Suggested next ``CUSTOMERCODE`` for ``CUSTOMERLOYALTY`` at this location (``MAX + 1``)."""
    ensure_customerloyalty_table()
    if not _table_exists('CUSTOMERLOYALTY'):
        return None
    try:
        rows = _safe_rows(
            'SELECT NVL(MAX(CUSTOMERCODE), 0) + 1 AS n FROM CUSTOMERLOYALTY WHERE LOCATIONCODE = :loc',
            {'loc': int(location_code)},
        )
        if rows and rows[0].get('n') is not None:
            return int(rows[0]['n'])
    except Exception:
        pass
    return None

def insert_customer_loyalty_row(location_code: int, payload: Dict[str, Any]) -> Tuple[bool, Optional[str]]:
    """Insert one ``CUSTOMERLOYALTY`` row (tenant DB). ``payload`` uses lowercase keys from JSON."""
    tbl = CUSTOMERLOYALTY_TABLE
    if not ensure_customerloyalty_table():
        return (False, 'CUSTOMERLOYALTY table could not be created.')
    if not _table_exists(tbl):
        return (False, 'CUSTOMERLOYALTY table not found.')
    cols_upper = {str(c).upper() for c in (_get_table_columns(tbl) or [])}
    try:
        loc = int(location_code)
    except (TypeError, ValueError):
        return (False, 'Invalid location.')
    try:
        cc = int(payload.get('customercode') or payload.get('customer_code') or 0)
    except (TypeError, ValueError):
        cc = 0
    name_raw = str(payload.get('customername') or payload.get('name') or '').strip()
    if not name_raw:
        return (False, 'Customer name is required.')

    def _s(key: str, max_len: int, default: str='') -> str:
        v = payload.get(key)
        if v is None:
            return default
        return str(v).strip()[:max_len]

    def _int(key: str, default: int=0) -> int:
        try:
            return int(payload.get(key) if payload.get(key) is not None and str(payload.get(key)).strip() != '' else default)
        except (TypeError, ValueError):
            return default

    def _float(key: str, default: float=0.0) -> float:
        try:
            return float(payload.get(key) if payload.get(key) is not None and str(payload.get(key)).strip() != '' else default)
        except (TypeError, ValueError):
            return default

    def _parse_date(key: str) -> Optional[Any]:
        raw = (payload.get(key) or '').strip() if isinstance(payload.get(key), str) else ''
        if not raw:
            return None
        try:
            from datetime import datetime as _dt

            return _dt.strptime(raw[:10], '%Y-%m-%d').date()
        except Exception:
            return None

    mob_val = _s('mob', 15) or _s('mobile', 15)
    issued = _parse_date('issuedate')
    expiry = _parse_date('expirydate')
    alloc_err = 'Could not allocate a unique loyalty customer code.'
    for _attempt in range(50):
        if cc <= 0:
            cand = peek_next_customer_loyalty_code(loc)
            if cand is None:
                return (False, alloc_err if _attempt else 'Customer code could not be determined.')
            cc = int(cand)
        dup_exist = _safe_rows(
            f'SELECT 1 AS x FROM {tbl} WHERE LOCATIONCODE = :loc AND CUSTOMERCODE = :cc',
            {'loc': loc, 'cc': cc},
        )
        if dup_exist:
            cand = peek_next_customer_loyalty_code(loc)
            if cand is None:
                return (False, alloc_err)
            cc = int(cand)
            continue

        payload['customercode'] = cc

        insert_data: Dict[str, Any] = {}
        if 'LOCATIONCODE' in cols_upper:
            insert_data['LOCATIONCODE'] = loc
        if 'CUSTOMERCODE' in cols_upper:
            insert_data['CUSTOMERCODE'] = cc
        if 'CUSTOMERNAME' in cols_upper:
            insert_data['CUSTOMERNAME'] = name_raw.upper()[:40] if len(name_raw) > 40 else name_raw.upper()
        if 'ADDRESS1' in cols_upper:
            insert_data['ADDRESS1'] = _s('address1', 40)
        if 'ADDRESS2' in cols_upper:
            insert_data['ADDRESS2'] = _s('address2', 40)
        if 'ADDRESS3' in cols_upper:
            insert_data['ADDRESS3'] = _s('address3', 40)
        if 'NATIONALITY' in cols_upper:
            insert_data['NATIONALITY'] = _s('nationality', 40)
        if 'MOB' in cols_upper:
            insert_data['MOB'] = mob_val
        if 'PHONE1' in cols_upper:
            insert_data['PHONE1'] = mob_val or _s('phone1', 15)
        if 'PHONE2' in cols_upper:
            insert_data['PHONE2'] = _s('phone2', 15)
        if 'EMAILID' in cols_upper:
            insert_data['EMAILID'] = _s('emailid', 30) or _s('email', 30)
        if 'CARDNO' in cols_upper:
            insert_data['CARDNO'] = max(0, _int('cardno', 0))
        if 'ISSUEDATE' in cols_upper and issued is not None:
            insert_data['ISSUEDATE'] = issued
        if 'EXPIRYDATE' in cols_upper and expiry is not None:
            insert_data['EXPIRYDATE'] = expiry
        if 'OUTLETCODE' in cols_upper:
            insert_data['OUTLETCODE'] = _int('outletcode', 0)
        if 'TOTALPOINTS' in cols_upper:
            insert_data['TOTALPOINTS'] = round(_float('totalpoints', _float('points', 0.0)), 2)
        if 'QIDNO' in cols_upper:
            insert_data['QIDNO'] = max(0, _int('qidno', 0))

        contact_phone = (mob_val or _s('phone1', 15)).strip()
        if contact_phone:
            if 'MOB' in cols_upper:
                dup_mob = _safe_rows(
                    f"SELECT 1 AS x FROM {tbl} WHERE LOCATIONCODE = :loc AND TRIM(NVL(MOB, '')) = :p",
                    {'loc': loc, 'p': contact_phone},
                )
                if dup_mob:
                    return (False, 'A loyalty customer with this mobile number already exists for this location.')
            if 'PHONE1' in cols_upper:
                dup_p1 = _safe_rows(
                    f"SELECT 1 AS x FROM {tbl} WHERE LOCATIONCODE = :loc AND TRIM(NVL(PHONE1, '')) = :p",
                    {'loc': loc, 'p': contact_phone},
                )
                if dup_p1:
                    return (False, 'A loyalty customer with this mobile number already exists for this location.')
        if 'CARDNO' in cols_upper:
            card_v = insert_data.get('CARDNO')
            try:
                card_n = int(card_v) if card_v is not None else 0
            except (TypeError, ValueError):
                card_n = 0
            if card_n > 0:
                dup_card = _safe_rows(
                    f'SELECT 1 AS x FROM {tbl} WHERE LOCATIONCODE = :loc AND CARDNO = :c',
                    {'loc': loc, 'c': card_n},
                )
                if dup_card:
                    return (False, 'A loyalty customer with this card number already exists for this location.')
        if 'QIDNO' in cols_upper:
            qid_v = insert_data.get('QIDNO')
            try:
                qid_n = int(qid_v) if qid_v is not None else 0
            except (TypeError, ValueError):
                qid_n = 0
            if qid_n > 0:
                dup_qid = _safe_rows(
                    f'SELECT 1 AS x FROM {tbl} WHERE LOCATIONCODE = :loc AND QIDNO = :q',
                    {'loc': loc, 'q': qid_n},
                )
                if dup_qid:
                    return (False, 'A loyalty customer with this QID no. already exists for this location.')

        ins_cols = [c for c in insert_data.keys() if c.upper() in cols_upper]
        if 'LOCATIONCODE' not in insert_data or 'CUSTOMERCODE' not in insert_data or 'CUSTOMERNAME' not in insert_data:
            return (False, 'CUSTOMERLOYALTY schema mismatch; LOCATIONCODE, CUSTOMERCODE, and CUSTOMERNAME columns are required.')
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    placeholders = ','.join([f':{c.lower()}' for c in ins_cols])
                    sql = f"INSERT INTO {tbl} ({', '.join(ins_cols)}) VALUES ({placeholders})"
                    cur.execute(sql, {c.lower(): insert_data[c] for c in ins_cols})
                conn.commit()
            payload['customercode'] = cc
            return (True, None)
        except Exception as e:
            err_up = str(e).upper()
            if 'ORA-00001' in err_up or 'UNIQUE' in err_up:
                cand = peek_next_customer_loyalty_code(loc)
                if cand is None:
                    cc = cc + 1
                else:
                    cc = int(cand)
                continue
            print(f'[ERROR insert_customer_loyalty_row] {e}')
            return (False, str(e))

    return (False, alloc_err)

def get_customer_category(customer_code: str) -> Optional[str]:
    """Get customer category code for filter queries (CUSTOMER master only — not CUSTOMERS view)."""
    customer_code = (customer_code or '').strip()
    if not customer_code:
        return None
    tbl = _detect_table(['CUSTOMER', 'customer'])
    if not tbl:
        return None
    code_col = _detect_column(tbl, ['CUSTOMERCODE', 'CUSTOMER_CODE', 'CUSTCODE', 'CUST_CODE', 'CODE', 'code'])
    category_col = _detect_column(
        tbl,
        ['CUSTOMERCATEGORY', 'CUSTOMERCATEGORYCODE', 'CATEGORY', 'CATEGORYCODE', 'CUSTCATEGORY'],
    )
    if not code_col or not category_col:
        return None
    query = f"""
        SELECT {category_col} AS category
        FROM {tbl}
        WHERE TRIM(TO_CHAR({code_col})) = :customer_code
    """
    rows = _safe_rows(query, {'customer_code': customer_code})
    if rows and rows[0].get('category') is not None:
        cat = str(rows[0]['category']).strip()
        return cat or None
    return None

def _enrich_item_popup_rows_display_names(rows: List[Dict[str, Any]], location_code: int) -> None:
    """Set ``display_item_name`` on each row (Arabic when ITEMNAMEARA is set); Arabic-safe batch read."""
    if not rows:
        return
    im_cols = {str(c).upper() for c in _get_table_columns('ITEMMASTER') or []}
    if 'ITEMNAMEARA' not in im_cols:
        for row in rows:
            row['display_item_name'] = str(row.get('itemname') or '').strip()
        return
    codes: List[str] = []
    seen: Set[str] = set()
    for row in rows:
        raw = row.get('itemcode')
        if raw is None:
            continue
        cs = str(raw).strip()
        if cs and cs not in seen:
            seen.add(cs)
            codes.append(cs)
    if not codes:
        for row in rows:
            row['display_item_name'] = str(row.get('itemname') or '').strip()
        return
    imx = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER']) or 'ITEMMASTER'
    ic_col = _detect_column(imx, ['ITEMCODE', 'ITEM_CODE', 'itemcode']) or 'ITEMCODE'
    lc_col = _detect_column(imx, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode']) or 'LOCATIONCODE'
    by_code: Dict[str, str] = {}
    nls_lang = (os.environ.get('NLS_LANG') or 'AMERICAN_AMERICA.UTF8').strip() or 'AMERICAN_AMERICA.UTF8'
    chunk_size = 900
    for start in range(0, len(codes), chunk_size):
        chunk = codes[start:start + chunk_size]
        bind_parts = []
        chunk_params: Dict[str, Any] = {'loc': int(location_code)}
        for i, c in enumerate(chunk):
            k = f'c{i}'
            bind_parts.append(f':{k}')
            chunk_params[k] = c
        in_list = ', '.join(bind_parts)
        base_query = f'\n        SELECT TO_CHAR(im.{ic_col}) AS itemcode, im.ITEMNAME AS itemname, im.ITEMNAMEARA AS itemnameara\n        FROM {imx} im\n        WHERE im.{lc_col} = :loc AND TO_CHAR(im.{ic_col}) IN ({in_list})\n    '
        try:
            im_rows = _fetch_rows_itemnameara_only(None, base_query, chunk_params, nls_lang=nls_lang)
        except Exception:
            im_rows = _safe_rows(base_query, chunk_params)
        for r in im_rows or []:
            code = str(r.get('itemcode') or '').strip()
            if not code:
                continue
            en = str(r.get('itemname') or '').strip()
            ara_raw = _fix_mojibake(r.get('itemnameara'))
            ara = str(ara_raw).strip() if ara_raw is not None else ''
            by_code[code] = ara or en
    for row in rows:
        ic = str(row.get('itemcode') or '').strip()
        row['display_item_name'] = by_code.get(ic) or str(row.get('itemname') or '').strip()

def _resolve_customer_category_filter() -> Optional[Tuple[str, str, str]]:
    """Resolve customer table and columns for category filtering"""
    table_candidates = ['CUSTOMER', 'CUSTOMERS']
    for table_name in table_candidates:
        try:
            code_col = _detect_column(table_name, ['CUSTOMERCODE', 'CUST_CODE', 'CUSTOMER_CODE', 'CODE'])
            category_col = _detect_column(table_name, ['CUSTOMERCATEGORY', 'CATEGORY', 'CATEGORYCODE', 'CUSTCATEGORY'])
            if code_col and category_col:
                return (table_name, code_col, category_col)
        except Exception:
            continue
    return None

_WH_STOCK_BRANCH_HAS_ROWS: Dict[int, bool] = {}

_ITEM_POPUP_SIMPLE_FILTERS = frozenset({
    'all', 'own_products', 'slow_moving', 'veg', 'special_promotion', 'disposable_packing',
})


def _item_popup_branch_stock_sql(
    location_code: Optional[int] = None,
    location_bind: str = ':location_code',
    item_alias: str = 'im',
) -> Tuple[str, str, str, str]:
    """Branch stock for sales item popup: WAREHOUSE_STOCK + CURRENTSTOCK (best of), legacy store cols.

    Returns ``(stock_expr, positive_where_clause, group_by_store_cols, join_clause)``.
    When the branch has no ``WAREHOUSE_STOCK`` rows yet, use ``CURRENTSTOCK`` only (migration period).
    """
    im_tbl = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER']) or 'itemmaster'
    im_cols = {str(c or '').upper() for c in (_get_table_columns(im_tbl) or [])}
    stock_parts: List[str] = []
    group_parts: List[str] = []
    join_clause = ''
    wh_branch_has_rows = False
    if location_code is not None and ensure_warehouse_stock_table() and _table_exists(WAREHOUSE_STOCK_TABLE):
        try:
            lc = int(location_code)
            if lc in _WH_STOCK_BRANCH_HAS_ROWS:
                wh_branch_has_rows = _WH_STOCK_BRANCH_HAS_ROWS[lc]
            else:
                probe = _safe_rows(
                    f'SELECT 1 FROM {WAREHOUSE_STOCK_TABLE} WHERE LOCATIONCODE = :loc AND ROWNUM = 1',
                    {'loc': lc},
                )
                wh_branch_has_rows = bool(probe)
                _WH_STOCK_BRANCH_HAS_ROWS[lc] = wh_branch_has_rows
        except Exception:
            wh_branch_has_rows = False
    if wh_branch_has_rows:
        join_clause = (
            f" LEFT JOIN (SELECT ws.ITEMCODE, NVL(SUM(ws.QTY), 0) AS wh_qty "
            f"FROM {WAREHOUSE_STOCK_TABLE} ws WHERE ws.LOCATIONCODE = {location_bind} "
            f"GROUP BY ws.ITEMCODE) ws_agg ON ws_agg.ITEMCODE = {item_alias}.itemcode "
        )
        stock_parts.append('NVL(ws_agg.wh_qty, 0)')
    for i in range(1, 7):
        col = f'STORE{i}'
        if col in im_cols:
            stock_parts.append(f'NVL({item_alias}.store{i}, 0)')
            group_parts.append(f'{item_alias}.store{i}')
    if 'CURRENTSTOCK' in im_cols:
        stock_parts.append(f'NVL({item_alias}.currentstock, 0)')
        if not group_parts:
            group_parts.append(f'{item_alias}.currentstock')
    if not stock_parts:
        return '0', '', '', ''
    if len(stock_parts) == 1:
        stock_expr = stock_parts[0]
    else:
        stock_expr = f"GREATEST({', '.join(stock_parts)})"
    group_by = ', '.join(group_parts)
    return stock_expr, f' AND {stock_expr} > 0', group_by, join_clause


def _item_popup_stock_sql(
    location_code: Optional[int] = None,
    warehouse_id: Optional[int] = None,
    location_bind: str = ':location_code',
    item_alias: str = 'im',
) -> Tuple[str, str, str, str]:
    """Stock expression/join for item popup — per-warehouse when ``warehouse_id`` set, else branch aggregate."""
    wh_id: Optional[int] = None
    if warehouse_id is not None:
        try:
            wh_id = int(warehouse_id)
            if wh_id <= 0:
                wh_id = None
        except (TypeError, ValueError):
            wh_id = None
    if wh_id is not None and ensure_warehouse_stock_table() and _table_exists(WAREHOUSE_STOCK_TABLE):
        join_clause = (
            f' INNER JOIN {WAREHOUSE_STOCK_TABLE} ws_popup '
            f'ON ws_popup.ITEMCODE = {item_alias}.itemcode '
            f'AND ws_popup.WAREHOUSE_ID = :warehouse_id '
            f'AND ws_popup.LOCATIONCODE = {location_bind} '
        )
        stock_expr = 'NVL(ws_popup.QTY, 0)'
        return stock_expr, f' AND {stock_expr} > 0', '', join_clause
    if wh_id is not None:
        im_cols = {str(c or '').upper() for c in (_get_table_columns('ITEMMASTER') or [])}
        if 'DEFAULT_WAREHOUSE_ID' in im_cols:
            stock_expr = 'NVL(im.currentstock, 0)' if 'CURRENTSTOCK' in im_cols else '0'
            return stock_expr, f' AND {stock_expr} > 0', '', ''
    return _item_popup_branch_stock_sql(location_code, location_bind, item_alias)


def _item_popup_warehouse_where(warehouse_id: Optional[int]) -> Optional[str]:
    """When ``WAREHOUSE_STOCK`` is unavailable, restrict items to ``DEFAULT_WAREHOUSE_ID``."""
    wh_id: Optional[int] = None
    if warehouse_id is not None:
        try:
            wh_id = int(warehouse_id)
            if wh_id <= 0:
                wh_id = None
        except (TypeError, ValueError):
            wh_id = None
    if wh_id is None:
        return None
    if ensure_warehouse_stock_table() and _table_exists(WAREHOUSE_STOCK_TABLE):
        return None
    im_cols = {str(c or '').upper() for c in (_get_table_columns('ITEMMASTER') or [])}
    if 'DEFAULT_WAREHOUSE_ID' in im_cols:
        return 'im.DEFAULT_WAREHOUSE_ID = :warehouse_id'
    return None


def _item_popup_limited_query(inner_sql: str, limit: int, order_by: str = 'im.itemname') -> str:
    lim = max(1, min(int(limit or 400), 2000))
    return f'SELECT * FROM ({inner_sql} ORDER BY {order_by}) WHERE ROWNUM <= {lim}'


def _item_popup_search_clauses(
    search: str,
    params: Dict[str, Any],
    *,
    prefix_only: bool = False,
) -> List[str]:
    """Build LIKE filters for item popup search.

    ``prefix_only=True`` uses ``TERM%`` (index-friendly); otherwise ``%TERM%`` contains match.
    """
    clauses: List[str] = []
    for i, tok in enumerate([t for t in (search or '').upper().split() if t]):
        key = f'popup_s{i}'
        if prefix_only:
            params[key] = f'{tok}%'
        else:
            params[key] = f'%{tok}%'
        clauses.append(
            f"(UPPER(TO_CHAR(im.itemcode)) LIKE :{key} "
            f"OR UPPER(im.itemname) LIKE :{key} "
            f"OR UPPER(NVL(im.manufacturerid, '')) LIKE :{key})"
        )
    return clauses


def _item_popup_minimal_row_select(stock_expr: str, price_col: str) -> str:
    """Picker-friendly SELECT without category/brand joins (much faster on large ITEMMASTER)."""
    return f"""
        SELECT
            im.itemcode,
            im.itemname,
            im.manufacturerid,
            im.baseuom AS unit,
            NVL(im.retailprice, 0) AS retailprice,
            NVL(im.wholesaleprice, 0) AS wholesaleprice,
            NVL(im.thirdprice, 0) AS thirdprice,
            NVL(im.branchprice, 0) AS branchprice,
            NVL(im.costprice, 0) AS costprice,
            {stock_expr} AS stock,
            NVL(im.quantitylimit, 0) AS limit,
            0 AS quantity,
            '' AS micro,
            '' AS brand,
            '' AS origin,
            '' AS propertyname,
            im.description,
            im.itemflag,
            im.ownproduct,
            NULL AS lastdate,
            NULL AS billno,
            ROUND(((NVL(im.retailprice, 0) - NVL(im.costprice, 0)) / NULLIF(NVL(im.retailprice, 0), 0)) * 100, 2) AS gp
    """


def _item_popup_fetch_warehouse_items(
    location_code: int,
    warehouse_id: int,
    search: str,
    price_mode: str,
    enforce_stock_positive: bool,
    limit: int,
    extra_where: Optional[List[str]] = None,
    extra_params: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    """List/search items scoped to one warehouse (optionally stock > 0 only)."""
    if not ensure_warehouse_stock_table() or not _table_exists(WAREHOUSE_STOCK_TABLE):
        return []
    try:
        wh_id = int(warehouse_id)
    except (TypeError, ValueError):
        return []
    if wh_id <= 0:
        return []
    lim = max(1, min(int(limit or 100), 300))
    price_col = {'retail': 'im.retailprice', 'wholesale': 'im.wholesaleprice', 'third': 'im.thirdprice', 'branch': 'im.branchprice'}.get(
        (price_mode or 'retail').strip().lower(), 'im.retailprice'
    )
    stock_expr = 'NVL(ws.QTY, 0)'
    search_stripped = (search or '').strip()
    require_positive = bool(enforce_stock_positive)

    def _query(prefix_only: bool) -> List[Dict[str, Any]]:
        params: Dict[str, Any] = {'location_code': location_code, 'warehouse_id': wh_id}
        if extra_params:
            params.update(extra_params)
        where_parts = ['im.locationcode = :location_code']
        if require_positive:
            where_parts.append(f'{stock_expr} > 0')
        search_clauses = _item_popup_search_clauses(search, params, prefix_only=prefix_only)
        if search_clauses:
            where_parts.extend(search_clauses)
        if extra_where:
            where_parts.extend(extra_where)
        if search_stripped:
            query = f"""
                {_item_popup_minimal_row_select(stock_expr, price_col)}
                FROM itemmaster im
                INNER JOIN {WAREHOUSE_STOCK_TABLE} ws
                    ON ws.itemcode = im.itemcode
                    AND ws.locationcode = im.locationcode
                    AND ws.warehouse_id = :warehouse_id
                WHERE {' AND '.join(where_parts)}
                ORDER BY im.itemname
                FETCH FIRST {lim} ROWS ONLY
            """
        else:
            query = f"""
                {_item_popup_minimal_row_select(stock_expr, price_col)}
                FROM {WAREHOUSE_STOCK_TABLE} ws
                INNER JOIN itemmaster im
                    ON im.itemcode = ws.itemcode AND im.locationcode = ws.locationcode
                WHERE ws.warehouse_id = :warehouse_id
                  AND ws.locationcode = :location_code
                  AND im.locationcode = :location_code
                  {' AND ' + ' AND '.join(where_parts[1:]) if len(where_parts) > 1 else ''}
                ORDER BY im.itemname
                FETCH FIRST {lim} ROWS ONLY
            """
        return _safe_rows(query, params)

    if not search_stripped:
        return _query(prefix_only=False)
    rows = _query(prefix_only=True)
    if rows:
        return rows
    return _query(prefix_only=False)


def _item_popup_fetch_fast_search(
    location_code: int,
    search: str,
    price_mode: str,
    enforce_stock_positive: bool,
    limit: int,
    extra_where: Optional[List[str]] = None,
    extra_params: Optional[Dict[str, Any]] = None,
    warehouse_id: Optional[int] = None,
) -> List[Dict[str, Any]]:
    """Match items by code/name/barcode first (small set), then attach stock — avoids full-catalog scans."""
    wh_id: Optional[int] = None
    if warehouse_id is not None:
        try:
            wh_id = int(warehouse_id)
            if wh_id <= 0:
                wh_id = None
        except (TypeError, ValueError):
            wh_id = None
    if wh_id is not None:
        return _item_popup_fetch_warehouse_items(
            location_code,
            wh_id,
            search,
            price_mode,
            enforce_stock_positive,
            limit,
            extra_where=extra_where,
            extra_params=extra_params,
        )
    _stk, _stk_pos, _grp_stores, _stk_join = _item_popup_stock_sql(location_code, wh_id)
    price_col = {'retail': 'im.retailprice', 'wholesale': 'im.wholesaleprice', 'third': 'im.thirdprice', 'branch': 'im.branchprice'}.get(
        (price_mode or 'retail').strip().lower(), 'im.retailprice'
    )
    params: Dict[str, Any] = {'location_code': location_code}
    if wh_id is not None:
        params['warehouse_id'] = wh_id
    if extra_params:
        params.update(extra_params)
    lim = max(1, min(int(limit or 100), 300))

    def _run(prefix_only: bool) -> List[Dict[str, Any]]:
        run_params: Dict[str, Any] = dict(params)
        search_clauses = _item_popup_search_clauses(search, run_params, prefix_only=prefix_only)
        if not search_clauses:
            return []
        inner_where = ['im.locationcode = :location_code'] + list(extra_where or []) + search_clauses
        wh_only = _item_popup_warehouse_where(wh_id)
        if wh_only:
            inner_where.append(wh_only)
        # Compute the stock value inside the inner query where the real ``itemmaster im``
        # (and any stock join) is in scope. The outer query only sees the subquery's
        # projected columns, so referencing ``im.currentstock``/``im.storeN`` there would
        # raise ORA-00904 and make every search return no rows.
        inner_sql = f"""
            SELECT im.itemcode, im.itemname, im.manufacturerid, im.baseuom, im.retailprice,
                   im.wholesaleprice, im.thirdprice, im.branchprice, im.costprice,
                   im.quantitylimit, im.description, im.itemflag, im.ownproduct,
                   {_stk} AS stk_val
            FROM itemmaster im
            {_stk_join}
            WHERE {' AND '.join(inner_where)}
            ORDER BY im.itemname
            FETCH FIRST {lim} ROWS ONLY
        """
        outer_sql = f"""
            {_item_popup_minimal_row_select('NVL(im.stk_val, 0)', price_col)}
            FROM ({inner_sql}) im
        """
        if enforce_stock_positive:
            outer_sql += ' WHERE NVL(im.stk_val, 0) > 0'
        return _safe_rows(outer_sql, run_params)

    rows = _run(prefix_only=True)
    if rows:
        return rows
    return _run(prefix_only=False)


def get_item_popup_items(location_code: int, filter_key: str, search: str, price_mode: str, customer_code: Optional[str]=None, bill_no: Optional[str]=None, seed_item_code: Optional[str]=None, customer_category: Optional[str]=None, user_id: Optional[str]=None, enforce_stock_positive: bool=False, limit: Optional[int]=None, warehouse_id: Optional[int]=None) -> List[Dict[str, Any]]:
    """Get item list for sales item popup with filters"""
    filter_key = (filter_key or 'all').strip().lower()
    price_mode = (price_mode or 'retail').strip().lower()
    customer_code = (customer_code or '').strip()
    bill_no = (bill_no or '').strip()
    seed_item_code = (seed_item_code or '').strip()
    customer_category = (customer_category or '').strip()
    search_stripped = (search or '').strip()
    wh_id: Optional[int] = None
    if warehouse_id is not None:
        try:
            wh_id = int(warehouse_id)
            if wh_id <= 0:
                wh_id = None
        except (TypeError, ValueError):
            wh_id = None
    if limit is None:
        if search_stripped:
            limit = 100
        elif wh_id is not None:
            limit = 250
        else:
            limit = 400
    try:
        limit = max(1, min(int(limit), 2000))
    except (TypeError, ValueError):
        limit = 400
    _stk, _stk_pos, _grp_stores, _stk_join = _item_popup_stock_sql(location_code, wh_id)
    _grp_seg = ('\n                ' + _grp_stores + ',') if _grp_stores else ''
    _stk_pos_if = _stk_pos if enforce_stock_positive else ''
    _rownum_lim = f' FETCH FIRST {int(limit)} ROWS ONLY' if limit else ''
    price_col = {'retail': 'im.retailprice', 'wholesale': 'im.wholesaleprice', 'third': 'im.thirdprice', 'branch': 'im.branchprice'}.get(price_mode, 'im.retailprice')
    base_select = f"""
        {_item_popup_minimal_row_select(_stk, price_col)}
        FROM itemmaster im
        {_stk_join}
        WHERE im.locationcode = :location_code
    """
    if enforce_stock_positive:
        base_select += _stk_pos
    params: Dict[str, Any] = {'location_code': location_code}
    if wh_id is not None:
        params['warehouse_id'] = wh_id
    wh_only = _item_popup_warehouse_where(wh_id)
    where_clauses: List[str] = []
    if wh_only:
        where_clauses.append(wh_only)
    rows: List[Dict[str, Any]] = []
    skip_base_select = False
    if filter_key == 'own_products':
        where_clauses.append("im.ownproduct = 'Y'")
    elif filter_key == 'special_promotion':
        where_clauses.append('im.categorycode IN (SELECT microcategorycode FROM tblspecialmicrocategory)')
    elif filter_key == 'slow_moving':
        where_clauses.append("im.slowmoving = 'Y'")
    elif filter_key == 'veg':
        where_clauses.append('im.maincategory = 605')
    elif filter_key == 'disposable_packing':
        where_clauses.append('im.categorycode IN (SELECT microcategorycode FROM tblspecialmicrocategory)')
    elif filter_key == 'similar_items_all':
        if not seed_item_code:
            return []
        where_clauses.append('\n            im.categorycode IN (\n                SELECT categorycode FROM itemmaster WHERE itemcode = :seed_item_code AND locationcode = :location_code\n            )\n        ')
        params['seed_item_code'] = seed_item_code
    elif filter_key == 'similar_items_own':
        if not seed_item_code:
            return []
        where_clauses.append("im.ownproduct = 'Y'")
        where_clauses.append('\n            im.categorycode IN (\n                SELECT categorycode FROM itemmaster WHERE itemcode = :seed_item_code AND locationcode = :location_code\n            )\n        ')
        params['seed_item_code'] = seed_item_code
    elif filter_key in {'customer_category', 'own_prod_cust_category'}:
        if not customer_category:
            return []
        customer_filter = _resolve_customer_category_filter()
        if not customer_filter:
            return []
        table_name, code_col, category_col = customer_filter
        own_clause = "AND im.ownproduct = 'Y'" if filter_key == 'own_prod_cust_category' else ''
        query = f"\n            SELECT DISTINCT\n                im.itemcode,\n                im.itemname,\n                im.manufacturerid,\n                im.baseuom AS unit,\n                {price_col} AS retailprice,\n                NVL(im.wholesaleprice, 0) AS wholesaleprice,\n                NVL(im.thirdprice, 0) AS thirdprice,\n                NVL(im.branchprice, 0) AS branchprice,\n                NVL(im.costprice, 0) AS costprice,\n                {_stk} AS stock,\n                NVL(im.quantitylimit, 0) AS limit,\n                0 AS quantity,\n                NVL(c.name, '') AS micro,\n                NVL(b.name, '') AS brand,\n                NVL(o.name, '') AS origin,\n                NVL(p.name, '') AS propertyname,\n                im.description,\n                im.itemflag,\n                MAX(TO_CHAR(hdr.billdate, 'YYYY-MM-DD')) AS lastdate,\n                MAX(hdr.billno) AS billno,\n                ROUND(((NVL(im.retailprice, 0) - NVL(im.costprice, 0)) / NULLIF(NVL(im.retailprice, 0), 0)) * 100, 2) AS gp,\n                im.ownproduct\n            FROM itemmaster im\n            {_stk_join}JOIN (SELECT code, name FROM category WHERE flag = 'C') c ON im.categorycode = c.code\n            JOIN (SELECT code, name FROM category WHERE flag = 'B') b ON im.brandcode = b.code\n            JOIN (SELECT code, name FROM tblitemorigin) o ON im.origin = o.code\n            JOIN (SELECT code, name FROM tblitemproperty) p ON im.property = p.code\n            JOIN billdtlhistory dtl ON dtl.itemcode = im.itemcode\n            JOIN billhdrhistory hdr ON dtl.billno = hdr.billno\n            WHERE im.locationcode = :location_code\n              AND hdr.customercode IN (\n                SELECT {code_col}\n                FROM {table_name}\n                WHERE {category_col} = :customer_category\n              )\n              {own_clause}\n              {_stk_pos_if}\n            GROUP BY\n                im.itemcode, im.itemname, im.baseuom, {price_col},\n{_grp_seg}\n                im.quantitylimit, c.name, b.name, o.name, p.name,\n                im.description, im.itemflag, im.ownproduct, im.manufacturerid,\n                im.wholesaleprice, im.thirdprice, im.branchprice, im.costprice, im.retailprice\n            ORDER BY billno, itemname DESC\n        "
        rows = _safe_rows(query, {'location_code': location_code, 'customer_category': customer_category})
        skip_base_select = True
    elif filter_key == 'customer_category_not_sold':
        if not customer_category or not customer_code:
            return []
        where_clauses.append('im.categorycode = :customer_category')
        where_clauses.append('\n            im.itemcode NOT IN (\n                SELECT DISTINCT dtl.itemcode\n                FROM billdtlhistory dtl\n                JOIN billhdrhistory hdr ON dtl.billno = hdr.billno\n                WHERE hdr.customercode = :customer_code\n            )\n        ')
        params['customer_category'] = customer_category
        params['customer_code'] = customer_code
    sql_search_applied = False
    if filter_key == 'customer_item':
        if not customer_code:
            return []
        skip_base_select = True
        if search_stripped:
            rows = _item_popup_fetch_fast_search(
                location_code,
                search,
                price_mode,
                enforce_stock_positive,
                limit,
                extra_where=[
                    'EXISTS (SELECT 1 FROM billdtlhistory dtl '
                    'JOIN billhdrhistory hdr ON dtl.billno = hdr.billno '
                    'WHERE dtl.itemcode = im.itemcode AND hdr.customercode = :customer_code)',
                ],
                extra_params={'customer_code': customer_code},
                warehouse_id=wh_id,
            )
            sql_search_applied = True
        else:
            query = f"""
                SELECT
                    im.itemcode,
                    im.itemname,
                    im.manufacturerid,
                    im.baseuom AS unit,
                    {price_col} AS retailprice,
                    NVL(im.wholesaleprice, 0) AS wholesaleprice,
                    NVL(im.thirdprice, 0) AS thirdprice,
                    NVL(im.branchprice, 0) AS branchprice,
                    NVL(im.costprice, 0) AS costprice,
                    {_stk} AS stock,
                    NVL(im.quantitylimit, 0) AS limit,
                    0 AS quantity,
                    '' AS micro,
                    '' AS brand,
                    '' AS origin,
                    '' AS propertyname,
                    im.description,
                    im.itemflag,
                    im.ownproduct,
                    MAX(TO_CHAR(hdr.billdate, 'YYYY-MM-DD')) AS lastdate,
                    MAX(hdr.billno) AS billno,
                    ROUND(((NVL(im.retailprice, 0) - NVL(im.costprice, 0)) / NULLIF(NVL(im.retailprice, 0), 0)) * 100, 2) AS gp
                FROM itemmaster im
                {_stk_join}
                JOIN billdtlhistory dtl ON dtl.itemcode = im.itemcode
                JOIN billhdrhistory hdr ON dtl.billno = hdr.billno
                WHERE im.locationcode = :location_code
                  AND hdr.customercode = :customer_code
                  {_stk_pos_if}
                GROUP BY
                    im.itemcode, im.itemname, im.manufacturerid, im.baseuom, {price_col},
{_grp_seg}
                    im.quantitylimit, im.description, im.itemflag, im.ownproduct,
                    im.wholesaleprice, im.thirdprice, im.branchprice, im.costprice, im.retailprice
                ORDER BY im.itemname
                FETCH FIRST {int(limit)} ROWS ONLY
            """
            rows = _safe_rows(query, {**params, 'customer_code': customer_code})
    elif filter_key == 'customer_1week':
        if not customer_code:
            return []
        query = f"\n            SELECT\n                im.itemcode,\n                im.itemname,\n                im.manufacturerid,\n                im.baseuom AS unit,\n                {price_col} AS retailprice,\n                NVL(im.wholesaleprice, 0) AS wholesaleprice,\n                NVL(im.thirdprice, 0) AS thirdprice,\n                NVL(im.branchprice, 0) AS branchprice,\n                NVL(im.costprice, 0) AS costprice,\n                {_stk} AS stock,\n                NVL(im.quantitylimit, 0) AS limit,\n                0 AS quantity,\n                NVL(cat.name, '') AS micro,\n                NVL(brand.name, '') AS brand,\n                NVL(origin.name, '') AS origin,\n                NVL(prop.name, '') AS propertyname,\n                im.description,\n                im.itemflag,\n                im.ownproduct,\n                hdr.lastdate,\n                hdr.billno,\n                ROUND(((NVL(im.retailprice, 0) - NVL(im.costprice, 0)) / NULLIF(NVL(im.retailprice, 0), 0)) * 100, 2) AS gp\n            FROM itemmaster im\n            {_stk_join}JOIN customerlastweekitems hdr ON hdr.itemcode = im.itemcode AND hdr.customercode = :customer_code\n            LEFT JOIN category cat ON im.categorycode = cat.code AND cat.flag = 'C'\n            LEFT JOIN category brand ON im.brandcode = brand.code AND brand.flag = 'B'\n            LEFT JOIN tblitemorigin origin ON im.origin = origin.code\n            LEFT JOIN tblitemproperty prop ON im.property = prop.code\n            WHERE im.locationcode = :location_code{_rownum_lim}\n            ORDER BY im.itemname\n        "
        rows = _safe_rows(query, {**params, 'customer_code': customer_code})
    elif filter_key == 'customer_last_mon':
        if not customer_code:
            return []
        query = f"\n            SELECT\n                im.itemcode,\n                im.itemname,\n                im.manufacturerid,\n                im.baseuom AS unit,\n                {price_col} AS retailprice,\n                NVL(im.wholesaleprice, 0) AS wholesaleprice,\n                NVL(im.thirdprice, 0) AS thirdprice,\n                NVL(im.branchprice, 0) AS branchprice,\n                NVL(im.costprice, 0) AS costprice,\n                {_stk} AS stock,\n                NVL(im.quantitylimit, 0) AS limit,\n                0 AS quantity,\n                NVL(cat.name, '') AS micro,\n                NVL(brand.name, '') AS brand,\n                NVL(origin.name, '') AS origin,\n                NVL(prop.name, '') AS propertyname,\n                im.description,\n                im.itemflag,\n                im.ownproduct,\n                hdr.lastdate,\n                hdr.billno,\n                ROUND(((NVL(im.retailprice, 0) - NVL(im.costprice, 0)) / NULLIF(NVL(im.retailprice, 0), 0)) * 100, 2) AS gp\n            FROM itemmaster im\n            {_stk_join}JOIN customerlastmonthitems hdr ON hdr.itemcode = im.itemcode AND hdr.customercode = :customer_code\n            LEFT JOIN category cat ON im.categorycode = cat.code AND cat.flag = 'C'\n            LEFT JOIN category brand ON im.brandcode = brand.code AND brand.flag = 'B'\n            LEFT JOIN tblitemorigin origin ON im.origin = origin.code\n            LEFT JOIN tblitemproperty prop ON im.property = prop.code\n            WHERE im.locationcode = :location_code{_rownum_lim}\n            ORDER BY im.itemname\n        "
        rows = _safe_rows(query, {**params, 'customer_code': customer_code})
    elif filter_key == 'executive_last_week':
        if not user_id:
            return []
        query = f"\n            SELECT\n                im.itemcode,\n                im.itemname,\n                im.manufacturerid,\n                im.baseuom AS unit,\n                {price_col} AS retailprice,\n                NVL(im.wholesaleprice, 0) AS wholesaleprice,\n                NVL(im.thirdprice, 0) AS thirdprice,\n                NVL(im.branchprice, 0) AS branchprice,\n                NVL(im.costprice, 0) AS costprice,\n                {_stk} AS stock,\n                NVL(im.quantitylimit, 0) AS limit,\n                0 AS quantity,\n                NVL(cat.name, '') AS micro,\n                NVL(brand.name, '') AS brand,\n                NVL(origin.name, '') AS origin,\n                NVL(prop.name, '') AS propertyname,\n                im.description,\n                im.itemflag,\n                hdr.lastdate,\n                hdr.billno,\n                ROUND(((NVL(im.retailprice, 0) - NVL(im.costprice, 0)) / NULLIF(NVL(im.retailprice, 0), 0)) * 100, 2) AS gp\n            FROM itemmaster im\n            {_stk_join}JOIN executivelastweekitems hdr ON hdr.itemcode = im.itemcode AND hdr.createdby = :user_id\n            LEFT JOIN category cat ON im.categorycode = cat.code AND cat.flag = 'C'\n            LEFT JOIN category brand ON im.brandcode = brand.code AND brand.flag = 'B'\n            LEFT JOIN tblitemorigin origin ON im.origin = origin.code\n            LEFT JOIN tblitemproperty prop ON im.property = prop.code\n            WHERE im.locationcode = :location_code{_rownum_lim}\n            ORDER BY im.itemname\n        "
        rows = _safe_rows(query, {**params, 'user_id': user_id})
    elif not skip_base_select:
        if search_stripped and filter_key in _ITEM_POPUP_SIMPLE_FILTERS:
            rows = _item_popup_fetch_fast_search(
                location_code,
                search,
                price_mode,
                enforce_stock_positive,
                limit,
                extra_where=where_clauses or None,
                warehouse_id=wh_id,
            )
            sql_search_applied = True
        elif wh_id is not None and filter_key in _ITEM_POPUP_SIMPLE_FILTERS:
            rows = _item_popup_fetch_warehouse_items(
                location_code,
                wh_id,
                '',
                price_mode,
                enforce_stock_positive,
                limit,
                extra_where=where_clauses or None,
            )
            # Keep warehouse scope strict: do not fall back to branch stock when a
            # warehouse is selected (avoids picking items that fail line stock checks).
        else:
            search_clauses = _item_popup_search_clauses(search, params)
            if search_clauses:
                sql_search_applied = True
            all_clauses = list(where_clauses) + search_clauses
            if all_clauses:
                base_select += ' AND ' + ' AND '.join(all_clauses)
            query = _item_popup_limited_query(base_select, limit)
            rows = _safe_rows(query, params)
    for row in rows:
        row['display_item_name'] = str(row.get('itemname') or '').strip()
    tokens = [t for t in search_stripped.upper().split() if t]
    if not tokens or sql_search_applied:
        return rows

    def matches(row: Dict[str, Any]) -> bool:
        hay = f"{row.get('itemcode', '')} {row.get('itemname', '')} {row.get('display_item_name', '')}".upper()
        return all((token in hay for token in tokens))
    return [row for row in rows if matches(row)]

def refresh_customer_item_history(location_code: int, customer_code: str, bill_no: str, price_mode: str) -> None:
    """Refresh tblcustomeritemhistory for customer item filter"""
    customer_code = (customer_code or '').strip()
    bill_no = (bill_no or '').strip()
    if not customer_code or not bill_no:
        return
    price_mode = (price_mode or 'retail').strip().lower()
    price_col = {'retail': 'im.retailprice', 'wholesale': 'im.wholesaleprice', 'third': 'im.thirdprice', 'branch': 'im.branchprice'}.get(price_mode, 'im.retailprice')
    delete_query = '\n        DELETE FROM tblcustomeritemhistory\n        WHERE customercode = :customer_code\n    '
    insert_query = f"\n        INSERT INTO tblcustomeritemhistory (\n            itemcode, itemname, unit, retailprice, stock, limit, itemflag, description,\n            micro, brand, origin, propertyname, lastdate, billno, customercode, currentbillno, gp, ownproduct\n        )\n        SELECT DISTINCT\n            im.itemcode,\n            im.itemname,\n            im.baseuom unit,\n            {price_col} retail,\n            im.currentstock stock,\n            im.quantitylimit limit,\n            im.itemflag,\n            im.description,\n            c.name micro,\n            b.name brand,\n            o.name origin,\n            p.name propertyname,\n            MAX(hdr.billdate) lastdate,\n            MAX(hdr.billno) billno,\n            MAX(hdr.customercode) customercode,\n            :bill_no currentbillno,\n            0 gp,\n            im.ownproduct\n        FROM itemmaster im\n        JOIN (SELECT code, name FROM category WHERE flag = 'C') c ON im.categorycode = c.code\n        JOIN (SELECT code, name FROM category WHERE flag = 'B') b ON im.brandcode = b.code\n        JOIN (SELECT code, name FROM tblitemorigin) o ON im.origin = o.code\n        JOIN (SELECT code, name FROM tblitemproperty) p ON im.property = p.code\n        JOIN billdtlhistory dtl ON dtl.itemcode = im.itemcode\n        JOIN billhdrhistory hdr ON dtl.billno = hdr.billno\n        WHERE im.locationcode = :location_code\n          AND hdr.customercode = :customer_code\n        GROUP BY\n            im.itemcode, im.itemname, im.baseuom, {price_col},\n            im.currentstock, im.quantitylimit, c.name, b.name, o.name, p.name,\n            im.description, im.itemflag, im.ownproduct\n        ORDER BY billno, itemname DESC\n    "
    params = {'location_code': location_code, 'customer_code': customer_code, 'bill_no': bill_no}
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(delete_query, params)
                cur.execute(insert_query, params)
                conn.commit()
    except Exception:
        return

def get_invoice_type_flag(invoice_code: str) -> Tuple[str, Optional[str]]:
    """Resolve bill type flag and name from TBLINVOICETYPE"""
    invoice_code = (invoice_code or '').strip()
    if not invoice_code:
        return ('C', None)
    code_col = _detect_column('TBLINVOICETYPE', ['CODE', 'TYPECODE', 'INVOICECODE'])
    flag_col = _detect_column('TBLINVOICETYPE', ['FLAG', 'BILLTYPE', 'TYPE'])
    name_col = _detect_column('TBLINVOICETYPE', ['NAME', 'TYPENAME', 'INVOICENAME'])
    if code_col and flag_col:
        name_sql = name_col if name_col else 'NULL'
        query = f'\n            SELECT {flag_col} AS FLAG, {name_sql} AS NAME\n            FROM TBLINVOICETYPE\n            WHERE {code_col} = :invoice_code\n        '
        try:
            _, rows = _fetch_rows(query, {'invoice_code': invoice_code})
            if rows and rows[0].get('flag'):
                flag = str(rows[0]['flag']).strip().upper()
                name = rows[0].get('name')
                return (flag, name)
        except Exception:
            pass
    mapping = {'1': 'C', '2': 'R', '3': 'T'}
    return (mapping.get(invoice_code, 'C'), None)


def _customer_billing_type_column(cust_tbl: Optional[str] = None) -> Optional[str]:
    tbl = cust_tbl or _detect_table(['CUSTOMER', 'customer', 'CUSTOMERS', 'customers'])
    if not tbl:
        return None
    return _detect_column(tbl, ['CUSTOMER_BILLING_TYPE', 'customer_billing_type', 'BILLING_TYPE'])


def normalize_customer_billing_type(raw: Any) -> str:
    """Return ``CASH`` or ``CREDIT``."""
    s = str(raw or '').strip().upper()
    if s in ('CREDIT', 'CR', 'R', '2'):
        return 'CREDIT'
    if s in ('CASH', 'C', '1'):
        return 'CASH'
    return 'CASH'


def billtype_from_customer_billing(billing_type: Any) -> str:
    """``CASH`` → ``C``; ``CREDIT`` → ``R``."""
    return 'R' if normalize_customer_billing_type(billing_type) == 'CREDIT' else 'C'


def _get_customer_billing_type(customer_code: int, db_key: Optional[str] = None) -> str:
    """Read ``CUSTOMER.CUSTOMER_BILLING_TYPE`` (Cash/Credit) for bill type resolution."""
    try:
        cc = int(customer_code)
    except (TypeError, ValueError):
        return 'CASH'
    if cc <= 0:
        return 'CASH'
    cust_tbl = _detect_table(['CUSTOMER', 'customer', 'CUSTOMERS', 'customers'])
    if not cust_tbl:
        return 'CASH'
    code_col = _detect_column(cust_tbl, ['CUSTOMERCODE', 'CODE', 'CUSTOMER_CODE'])
    bill_col = _customer_billing_type_column(cust_tbl)
    if not code_col or not bill_col:
        return 'CASH'
    rows = _safe_rows(
        f'SELECT {bill_col} AS bt FROM {cust_tbl} WHERE {code_col} = :cc',
        {'cc': cc},
        db_key=db_key,
    ) or []
    if not rows:
        return 'CASH'
    return normalize_customer_billing_type(rows[0].get('bt'))


def resolve_customer_billtype(customer_code: Any, header: Optional[Dict[str, Any]] = None) -> str:
    """
    Resolve ``BILLHDR.BILLTYPE`` from customer billing (Cash/Credit).

    Walk-in (customer code 0) → ``C``. Credit customer → ``R``. Cash customer → ``C``.
    """
    h = header or {}
    pt = str(
        h.get('customer_billing_type')
        or h.get('payment_type')
        or h.get('customer_payment_type')
        or ''
    ).strip().upper()
    if pt:
        return billtype_from_customer_billing(pt)
    try:
        cc = int(customer_code or 0)
    except (TypeError, ValueError):
        cc = 0
    if cc <= 0:
        return 'C'
    return billtype_from_customer_billing(_get_customer_billing_type(cc))


def _resolve_sales_billtype_from_customer(header: Dict[str, Any], customer_code: int) -> str:
    """Sales / return: bill type from ``CUSTOMER.CUSTOMER_BILLING_TYPE``."""
    return resolve_customer_billtype(customer_code, header)


def _resolve_sales_header_billtype(header: Dict[str, Any]) -> Tuple[Optional[str], Optional[str]]:
    """Resolve BILLTYPE (C/R) from customer billing only — no silent Cash default."""
    try:
        cc = int(header.get('customercode') or 0)
    except (TypeError, ValueError):
        cc = 0
    if cc <= 0:
        return (None, 'Select a customer to determine bill type (Cash/Credit).')
    bt = resolve_customer_billtype(cc, header)
    if bt not in ('C', 'R'):
        return (None, 'Could not determine bill type from customer billing settings.')
    return (bt, None)


def get_pending_invoices(customercode: str, salesman_code: str) -> List[Dict[str, Any]]:
    columns = _resolve_settlement_columns()
    invoice_no = columns['invoice_no']
    invoice_date = columns['invoice_date']
    amount = columns['amount']
    paid = columns['paid']
    balance = columns['balance']
    customer = columns['customer']
    join_clause, salesman_name_col = _resolve_salesman_join()
    customer_salesman_col = os.getenv('DASH_CUSTOMER_SALESMAN_COLUMN', 'salesman')
    where_clauses = [f's.{balance} > 0', "s.flag = 'B'", f's.{customer} = :customercode']
    if salesman_code:
        where_clauses.append(f'c.{customer_salesman_col} = :salesman_code')
    query = f"\n        SELECT * FROM (\n            SELECT\n                s.{invoice_no} AS invoice_no,\n                s.{invoice_date} AS bill_date,\n                s.{amount} AS bill_amount,\n                s.{paid} AS paid_amount,\n                s.{balance} AS balance,\n                s.rowid AS rid,\n                c.{customer_salesman_col} AS salesmancode,\n                {salesman_name_col or 'NULL'} AS salesman_name,\n                ROW_NUMBER() OVER (ORDER BY s.{invoice_date} DESC) AS rn\n            FROM tblsettlement s\n            {join_clause}\n            WHERE {' AND '.join(where_clauses)}\n        )\n        WHERE rn <= 1000\n        ORDER BY bill_date DESC\n    "
    params = {'customercode': customercode}
    if salesman_code:
        params['salesman_code'] = salesman_code
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except cx_Oracle.DatabaseError as e:
        print(f'[ERROR get_pending_invoices] {e}')
        import traceback
        traceback.print_exc()
        return []

def get_next_pending_number() -> str:
    query = "\n        SELECT NVL(MAX(TO_NUMBER(pendingno)), 0) + 1 AS next_no\n        FROM tblsettlement\n        WHERE pendingno IS NOT NULL AND REGEXP_LIKE(pendingno, '^[0-9]+$')\n    "
    try:
        result = _get_scalar(query, {})
        return str(int(result))
    except Exception:
        return '1'

def get_salesmen_for_customer(customercode: str) -> List[Dict[str, Any]]:

    def _fetch_salesmen_rows(query: str, params: Dict[str, Any]) -> List[Dict[str, Any]]:
        try:
            _, rows = _fetch_rows(query, params)
            return rows
        except Exception:
            return []
    salesman_code_col = os.getenv('DASH_SALESMAN_CODE_COLUMN', 'salesmancode')
    salesman_name_col = os.getenv('DASH_SALESMAN_NAME_COLUMN')
    if not salesman_name_col:
        detected = _detect_column('SALESMAN', ['SALESMANNAME', 'SALESMAN_NAME', 'NAME'])
        salesman_name_col = detected
    name_sql = f's.{salesman_name_col}' if salesman_name_col else 'NULL'
    rows: List[Dict[str, Any]] = []
    customer_table = None
    customer_code_col = None
    customer_salesman_col = None
    for table_name in ['CUSTOMER', 'CUSTOMERS']:
        try:
            code_col = _detect_column(table_name, ['CUSTOMERCODE', 'CUST_CODE', 'CUSTOMER_CODE', 'CODE'])
            salesman_col = _detect_column(table_name, [os.getenv('DASH_CUSTOMER_SALESMAN_COLUMN', 'salesman'), 'SALESMANCODE', 'SALESMAN_CODE', 'SALESMAN', 'SM_CODE', 'SMCODE'])
            if code_col and salesman_col:
                customer_table = table_name
                customer_code_col = code_col
                customer_salesman_col = salesman_col
                break
        except Exception:
            continue
    if customer_table and customer_code_col and customer_salesman_col:
        query = f'\n            SELECT DISTINCT\n                c.{customer_salesman_col} AS code,\n                {name_sql} AS name\n            FROM {customer_table} c\n            LEFT JOIN salesman s ON s.{salesman_code_col} = c.{customer_salesman_col}\n            WHERE c.{customer_code_col} = :customercode\n              AND c.{customer_salesman_col} IS NOT NULL\n            ORDER BY c.{customer_salesman_col}\n        '
        rows = _fetch_salesmen_rows(query, {'customercode': customercode})
    if not rows:
        settlement_table = 'TBLSETTLEMENT'
        if _get_table_columns(settlement_table):
            settlement_customer_col = _detect_column(settlement_table, ['CUSTOMERCODE', 'CUSTOMER', 'CUST_CODE', 'CUSTOMER_CODE'])
            settlement_salesman_col = _detect_column(settlement_table, ['SALESMANCODE', 'SALESMAN_CODE', 'SALESMAN', 'SM_CODE', 'SMCODE'])
            if settlement_customer_col and settlement_salesman_col:
                query = f'\n                    SELECT DISTINCT\n                        s.{settlement_salesman_col} AS code,\n                        {name_sql} AS name\n                    FROM {settlement_table} t\n                    LEFT JOIN salesman s ON s.{salesman_code_col} = t.{settlement_salesman_col}\n                    WHERE t.{settlement_customer_col} = :customercode\n                      AND t.{settlement_salesman_col} IS NOT NULL\n                    ORDER BY t.{settlement_salesman_col}\n                '
                rows = _fetch_salesmen_rows(query, {'customercode': customercode})
    if not rows and _get_table_columns('SALESMAN'):
        query = f"\n            SELECT DISTINCT\n                {salesman_code_col} AS code,\n                {salesman_name_col or 'NULL'} AS name\n            FROM SALESMAN\n            ORDER BY {salesman_code_col}\n        "
        rows = _fetch_salesmen_rows(query, {})
    return rows

def get_salesman_details(salesman_code: str) -> Dict[str, Any]:
    salesman_join_clause, salesman_name_column = _resolve_salesman_join()
    customer_name_column = os.getenv('DASH_CUSTOMER_NAME_COLUMN')
    if not customer_name_column:
        detected = _detect_column('CUSTOMERS', ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME'])
        customer_name_column = detected
    salesman_code_col = os.getenv('DASH_SALESMAN_CODE_COLUMN', 'salesmancode')
    customer_salesman_col = os.getenv('DASH_CUSTOMER_SALESMAN_COLUMN', 'salesman')
    invoice_date_column = _resolve_invoice_date_column()
    salesman_name_query = f"\n        SELECT {salesman_name_column or 'NULL'} AS name\n        FROM salesman\n        WHERE {salesman_code_col} = :code\n    "
    _, salesman_rows = _fetch_rows(salesman_name_query, {'code': salesman_code})
    salesman_name = salesman_rows[0]['name'] if salesman_rows else ''
    total_query = f"\n        SELECT \n            SUM(NVL(s.balance, 0)) AS outstanding,\n            COUNT(*) AS invoice_count\n        FROM tblsettlement s\n        LEFT JOIN customers c ON s.customercode = c.cust_code\n        WHERE c.{customer_salesman_col} = :code\n        AND s.balance <> 0\n        AND s.flag = 'B'\n    "
    _, total_rows = _fetch_rows(total_query, {'code': salesman_code})
    outstanding_total = float(total_rows[0]['outstanding']) if total_rows else 0.0
    invoice_count = int(total_rows[0]['invoice_count']) if total_rows else 0
    customer_query = f"\n        SELECT\n            s.customercode AS code,\n            {customer_name_column or 'NULL'} AS name,\n            SUM(CASE WHEN TRUNC({invoice_date_column}) >= TRUNC(SYSDATE) - 30 THEN NVL(s.balance, 0) ELSE 0 END) AS amt_30,\n            SUM(CASE WHEN TRUNC({invoice_date_column}) >= TRUNC(SYSDATE) - 60 AND TRUNC({invoice_date_column}) < TRUNC(SYSDATE) - 30 THEN NVL(s.balance, 0) ELSE 0 END) AS amt_60,\n            SUM(CASE WHEN TRUNC({invoice_date_column}) >= TRUNC(SYSDATE) - 90 AND TRUNC({invoice_date_column}) < TRUNC(SYSDATE) - 60 THEN NVL(s.balance, 0) ELSE 0 END) AS amt_90,\n            SUM(CASE WHEN TRUNC({invoice_date_column}) < TRUNC(SYSDATE) - 90 THEN NVL(s.balance, 0) ELSE 0 END) AS amt_90p,\n            SUM(NVL(s.balance, 0)) AS total_amount,\n            COUNT(*) AS invoice_count\n        FROM tblsettlement s\n        LEFT JOIN customers c ON s.customercode = c.cust_code\n        WHERE c.{customer_salesman_col} = :code\n        AND s.balance <> 0\n        AND s.flag = 'B'\n        GROUP BY s.customercode, {customer_name_column or 'NULL'}\n        ORDER BY total_amount DESC\n    "
    _, customer_rows = _fetch_rows(customer_query, {'code': salesman_code})
    return {'salesman_code': salesman_code, 'salesman_name': salesman_name, 'outstanding_total': outstanding_total, 'invoice_count': invoice_count, 'customers': customer_rows}

def get_customer_billdate_range(customercode: str) -> Dict[str, Any]:
    query = "\n        SELECT \n            MIN(billdate) AS min_date,\n            MAX(billdate) AS max_date\n        FROM tblsettlement\n        WHERE customercode = :code\n        AND balance <> 0\n        AND flag = 'B'\n    "
    try:
        _, rows = _fetch_rows(query, {'code': customercode})
        if rows:
            return {'min_date': rows[0].get('min_date'), 'max_date': rows[0].get('max_date')}
    except Exception:
        pass
    return {'min_date': None, 'max_date': None}

def process_payments(customer_code: str, items: List[Dict[str, Any]], meta: Dict[str, Any]) -> None:
    if not items:
        return
    columns = _resolve_settlement_columns()
    invoice_no = columns['invoice_no']
    balance_col = columns['balance']
    with _get_connection() as conn:
        with conn.cursor() as cur:
            voucher_no = meta.get('voucherno', '')
            pay_date = meta.get('paydate')
            location_code = meta.get('locationcode') or os.getenv('LOCATION_CODE', '')
            remark = meta.get('remark', '')
            puser = meta.get('puser', '')
            salesman_code = meta.get('salesmancode', '')
            salesman_col = _detect_column('tblsettlement', ['SALESMANCODE', 'SALESMAN_CODE', 'salesmancode', 'salesman'])
            pendingno_col = _detect_column('tblsettlement', ['PENDINGNO', 'PENDING_NO', 'pendingno'])
            voucherno_col = _detect_column('tblsettlement', ['VOUCHERNO', 'VOUCHER_NO', 'voucherno'])
            if voucherno_col and voucherno_col == pendingno_col:
                voucherno_col = None
            createdby_col = _detect_column('tblsettlement', ['CREATEDBY', 'CREATED_BY', 'createdby', 'created_by', 'CREATED_BY_USER', 'created_by_user'])
            if not createdby_col:
                try:
                    existing_cols = _get_table_columns('tblsettlement')
                    existing_upper = [c.upper() for c in existing_cols or []]
                    if 'CREATEDBY' not in existing_upper:
                        cur.execute('ALTER TABLE tblsettlement ADD CREATEDBY VARCHAR2(50)')
                        createdby_col = _detect_column('tblsettlement', ['CREATEDBY', 'CREATED_BY', 'createdby', 'created_by'])
                except Exception as e:
                    print(f'[DEBUG process_payments] Error ensuring CREATEDBY column: {e}')
            onlineflag_col = _detect_column('tblsettlement', ['ONLINEFLAG', 'ONLINE_FLAG', 'ONLINEFLG', 'onlineflag'])
            created_at_col = _detect_column('tblsettlement', ['CREATED_AT', 'CREATEDAT', 'created_at', 'createdat'])
            if not created_at_col:
                try:
                    existing_cols = _get_table_columns('tblsettlement')
                    existing_upper = [c.upper() for c in existing_cols or []]
                    if 'CREATED_AT' not in existing_upper:
                        cur.execute('ALTER TABLE tblsettlement ADD CREATED_AT DATE')
                        _TABLE_COLUMNS_CACHE.pop('TBLSETTLEMENT', None)
                        created_at_col = _detect_column('tblsettlement', ['CREATED_AT', 'CREATEDAT', 'created_at', 'createdat'])
                except Exception as e:
                    print(f'[DEBUG process_payments] Error ensuring CREATED_AT column: {e}')
            if salesman_col and salesman_code:
                cols = ['locationcode', 'pendingno', 'billno', 'billdate', 'billamount', 'customercode', 'remark', 'flag', salesman_col]
                vals = [':loc', ':voucher', ':voucher', ':paydate', ':total', ':cust', ':remark', "'R'", ':salesman']
                if voucherno_col:
                    cols.append(voucherno_col)
                    vals.append(':voucher')
                if createdby_col:
                    cols.append(createdby_col)
                    vals.append(':createdby')
                if onlineflag_col:
                    cols.append(onlineflag_col)
                    vals.append("'M'")
                if created_at_col:
                    cols.append(created_at_col)
                    vals.append('SYSDATE')
                summary_insert = f"\n                    INSERT INTO tblsettlement ({', '.join(cols)})\n                    VALUES ({', '.join(vals)})\n                "
                total_amount = sum((float(item.get('payamount', 0)) for item in items))
                params = {'loc': location_code, 'voucher': voucher_no, 'paydate': pay_date, 'total': total_amount, 'cust': customer_code, 'remark': remark, 'salesman': salesman_code}
                if createdby_col:
                    params['createdby'] = puser
                cur.execute(summary_insert, params)
            else:
                cols = ['locationcode', 'pendingno', 'billno', 'billdate', 'billamount', 'customercode', 'remark', 'flag']
                vals = [':loc', ':voucher', ':voucher', ':paydate', ':total', ':cust', ':remark', "'R'"]
                if voucherno_col:
                    cols.append(voucherno_col)
                    vals.append(':voucher')
                if createdby_col:
                    cols.append(createdby_col)
                    vals.append(':createdby')
                if onlineflag_col:
                    cols.append(onlineflag_col)
                    vals.append("'M'")
                if created_at_col:
                    cols.append(created_at_col)
                    vals.append('SYSDATE')
                summary_insert = f"\n                    INSERT INTO tblsettlement ({', '.join(cols)})\n                    VALUES ({', '.join(vals)})\n                "
                total_amount = sum((float(item.get('payamount', 0)) for item in items))
                params = {'loc': location_code, 'voucher': voucher_no, 'paydate': pay_date, 'total': total_amount, 'cust': customer_code, 'remark': remark}
                if createdby_col:
                    params['createdby'] = puser
                cur.execute(summary_insert, params)
            for item in items:
                billno = item.get('billno')
                payamount = float(item.get('payamount', 0))
                if not billno or payamount == 0:
                    continue
                update_query = f"\n                    UPDATE tblsettlement\n                    SET paidamount = paidamount + :pay,\n                        balance = balance - :pay,\n                        paiddate = :paydate,\n                        puser = :puser,\n                        remark = :remark,\n                        voucherno = :voucher,\n                        status = CASE WHEN (balance - :pay) = 0 THEN 'PAID' ELSE 'PENDING' END,\n                        pflag = CASE WHEN (balance - :pay) = 0 THEN 'Y' ELSE 'N' END\n                    WHERE {invoice_no} = :billno\n                    AND customercode = :cust\n                    AND flag = 'B'\n                "
                cur.execute(update_query, {'pay': payamount, 'paydate': pay_date, 'puser': puser, 'remark': remark, 'voucher': voucher_no, 'billno': billno, 'cust': customer_code})
                temp_insert = "\n                    INSERT INTO tbltempsettlement (locationcode, pendingno, customercode, status, paidamount, againstno, paiddate, flag, puser, remarks, salesmancode, billamount, version)\n                    VALUES (:loc, :voucher, :cust, 'PAID', :pay, :billno, :paydate, 'R', :puser, :remark, :salesman, 0, 1)\n                "
                salesman_code = item.get('salesmancode', '')
                cur.execute(temp_insert, {'loc': location_code, 'voucher': voucher_no, 'cust': customer_code, 'pay': payamount, 'billno': billno, 'paydate': pay_date, 'puser': puser, 'remark': remark, 'salesman': salesman_code})
            conn.commit()

def process_payments_credit(customer_code: str, items: List[Dict[str, Any]], meta: Dict[str, Any]) -> None:
    """Same as process_payments but uses tblcreditsettlement and tblcrsettlement."""
    if not items:
        return
    settle_table = _detect_table(['TBLCREDITSETTLEMENT', 'tblcreditsettlement'])
    temp_table = _detect_table(['TBLCRSETTLEMENT', 'tblcrsettlement'])
    if not settle_table or not temp_table:
        return
    columns = _resolve_settlement_columns()
    invoice_no = columns['invoice_no']
    balance_col = columns['balance']
    with _get_connection() as conn:
        with conn.cursor() as cur:
            voucher_no = meta.get('voucherno', '')
            pay_date = meta.get('paydate')
            location_code = meta.get('locationcode') or os.getenv('LOCATION_CODE', '')
            remark = meta.get('remark', '')
            puser = meta.get('puser', '')
            salesman_code = meta.get('salesmancode', '')
            salesman_col = _detect_column(settle_table, ['SALESMANCODE', 'SALESMAN_CODE', 'salesmancode', 'salesman'])
            pendingno_col = _detect_column(settle_table, ['PENDINGNO', 'PENDING_NO', 'pendingno'])
            voucherno_col = _detect_column(settle_table, ['VOUCHERNO', 'VOUCHER_NO', 'voucherno'])
            if voucherno_col and voucherno_col == pendingno_col:
                voucherno_col = None
            createdby_col = _detect_column(settle_table, ['CREATEDBY', 'CREATED_BY', 'createdby', 'created_by', 'CREATED_BY_USER', 'created_by_user'])
            onlineflag_col = _detect_column(settle_table, ['ONLINEFLAG', 'ONLINE_FLAG', 'ONLINEFLG', 'onlineflag'])
            created_at_col = _detect_column(settle_table, ['CREATED_AT', 'CREATEDAT', 'created_at', 'createdat'])
            temp_version_col = _detect_column(temp_table, ['VERSION', 'version'])
            if salesman_col and salesman_code:
                cols = ['locationcode', 'pendingno', 'billno', 'billdate', 'billamount', 'customercode', 'remark', 'flag', salesman_col]
                vals = [':loc', ':voucher', ':voucher', ':paydate', ':total', ':cust', ':remark', "'R'", ':salesman']
            else:
                cols = ['locationcode', 'pendingno', 'billno', 'billdate', 'billamount', 'customercode', 'remark', 'flag']
                vals = [':loc', ':voucher', ':voucher', ':paydate', ':total', ':cust', ':remark', "'R'"]
            if voucherno_col:
                cols.append(voucherno_col)
                vals.append(':voucher')
            if createdby_col:
                cols.append(createdby_col)
                vals.append(':createdby')
            if onlineflag_col:
                cols.append(onlineflag_col)
                vals.append("'M'")
            if created_at_col:
                cols.append(created_at_col)
                vals.append('SYSDATE')
            total_amount = sum((float(item.get('payamount', 0)) for item in items))
            params = {'loc': location_code, 'voucher': voucher_no, 'paydate': pay_date, 'total': total_amount, 'cust': customer_code, 'remark': remark, 'salesman': salesman_code}
            if createdby_col:
                params['createdby'] = puser
            summary_insert = f"INSERT INTO {settle_table} ({', '.join(cols)}) VALUES ({', '.join(vals)})"
            cur.execute(summary_insert, params)
            for item in items:
                billno = item.get('billno')
                payamount = float(item.get('payamount', 0))
                if not billno or payamount == 0:
                    continue
                update_query = f"\n                    UPDATE {settle_table}\n                    SET paidamount = paidamount + :pay,\n                        balance = balance - :pay,\n                        paiddate = :paydate,\n                        puser = :puser,\n                        remark = :remark,\n                        voucherno = :voucher,\n                        status = CASE WHEN (balance - :pay) = 0 THEN 'PAID' ELSE 'PENDING' END,\n                        pflag = CASE WHEN (balance - :pay) = 0 THEN 'Y' ELSE 'N' END\n                    WHERE {invoice_no} = :billno\n                    AND customercode = :cust\n                    AND flag = 'B'\n                "
                cur.execute(update_query, {'pay': payamount, 'paydate': pay_date, 'puser': puser, 'remark': remark, 'voucher': voucher_no, 'billno': billno, 'cust': customer_code})
                temp_cols = ['locationcode', 'pendingno', 'customercode', 'status', 'paidamount', 'againstno', 'paiddate', 'flag', 'puser', 'remarks', 'salesmancode', 'billamount']
                temp_vals = [':loc', ':voucher', ':cust', "'PAID'", ':pay', ':billno', ':paydate', "'R'", ':puser', ':remark', ':salesman', '0']
                if temp_version_col:
                    temp_cols.append(temp_version_col)
                    temp_vals.append('1')
                temp_insert = f"INSERT INTO {temp_table} ({', '.join(temp_cols)}) VALUES ({', '.join(temp_vals)})"
                cur.execute(temp_insert, {'loc': location_code, 'voucher': voucher_no, 'cust': customer_code, 'pay': payamount, 'billno': billno, 'paydate': pay_date, 'puser': puser, 'remark': remark, 'salesman': item.get('salesmancode', '')})
            conn.commit()

def get_settlements(customercode: str) -> Dict[str, Any]:
    if not customercode:
        return {'columns': [], 'rows': []}
    try:
        columns, rows = _fetch_rows(_settlement_query('tblsettlement'), {'customercode': customercode, 'limit': 500})
        return {'columns': columns, 'rows': rows}
    except Exception as e:
        print(f'[ERROR get_settlements] {e}')
        import traceback
        traceback.print_exc()
        return {'columns': [], 'rows': []}

