        formatted_categories_today = sorted(formatted_categories, key=lambda x: x['today_amount'], reverse=True)
        formatted_categories_yesterday = sorted(formatted_categories, key=lambda x: x['yesterday_amount'], reverse=True)
        try:
            maincategory_today_query = "\n                SELECT\n                    NVL(im.MAINCATEGORYCODE, 0) AS code,\n                    NVL(im.MAINCATEGORYNAME, 'Uncategorized') AS name,\n                    SUM(NVL(bd.QUANTITY, 0) * NVL(bd.RATE, 0)) AS total_amount\n                FROM billhdrhistory bh\n                JOIN billdtlhistory bd ON bh.BILLNO = bd.BILLNO\n                LEFT JOIN itemmasterdetails im ON bd.ITEMCODE = im.ITEMCODE\n                WHERE im.MAINCATEGORYCODE IS NOT NULL\n                AND TRUNC(bh.BILLDATE) = TRUNC(:today)\n                GROUP BY im.MAINCATEGORYCODE, im.MAINCATEGORYNAME\n                ORDER BY total_amount DESC\n            "
            _, maincategory_today_data = _fetch_rows(maincategory_today_query, {'today': today})
            print(f'[DEBUG] Main categories (today) query executed. Found: {(len(maincategory_today_data) if maincategory_today_data else 0)} rows')
        except Exception as e:
            print(f'[ERROR get_sales_dashboard_data - maincategories today] {e}')
