def _item_lot_apply_schema_upgrades() -> None:
    """Add UNIT_COST, ITEM_LOT_BIN, etc. to existing lot installs."""
    ensure_warehouse_storage_table()
    if not _table_exists(ITEM_LOT_TABLE):
        return
    tcols = {c.upper() for c in _get_table_columns(ITEM_LOT_TABLE) or []}
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if 'UNIT_COST' not in tcols:
                    try:
                        cur.execute(f'ALTER TABLE {ITEM_LOT_TABLE} ADD (UNIT_COST NUMBER(18,4))')
                    except Exception as e:
                        print(f'[_item_lot_apply_schema_upgrades UNIT_COST] {e}')
                if 'LOT_BLOCKED' not in tcols:
                    try:
                        cur.execute(f"ALTER TABLE {ITEM_LOT_TABLE} ADD (LOT_BLOCKED VARCHAR2(1) DEFAULT 'N')")
                    except Exception as e:
                        print(f'[_item_lot_apply_schema_upgrades LOT_BLOCKED] {e}')
                try:
                    tcols = {c.upper() for c in _get_table_columns(ITEM_LOT_TABLE) or []}
                except Exception:
                    tcols = set()
                if 'LOT_BLOCK_REMARKS' not in tcols:
                    try:
                        cur.execute(f'ALTER TABLE {ITEM_LOT_TABLE} ADD (LOT_BLOCK_REMARKS VARCHAR2(500))')
                    except Exception as e:
                        print(f'[_item_lot_apply_schema_upgrades LOT_BLOCK_REMARKS] {e}')
                try:
                    tcols = {c.upper() for c in _get_table_columns(ITEM_LOT_TABLE) or []}
                except Exception:
                    tcols = set()
                if 'RESETNO' not in tcols and 'RESET_NO' not in tcols:
                    try:
                        cur.execute(f'ALTER TABLE {ITEM_LOT_TABLE} ADD (RESETNO NUMBER)')
                    except Exception as e:
                        print(f'[_item_lot_apply_schema_upgrades RESETNO] {e}')
                try:
                    tcols = {c.upper() for c in (_get_table_columns(ITEM_LOT_TABLE) or [])}
                except Exception:
                    tcols = set()
                if 'WAREHOUSE_ID' in tcols:
                    _drop_item_lot_warehouse_id_cur(cur)
                if not _table_exists(ITEM_LOT_BIN_TABLE):
                    try:
                        cur.execute(f'\n                            CREATE TABLE {ITEM_LOT_BIN_TABLE} (\n                                LOT_ID NUMBER NOT NULL,\n                                STORAGE_ID NUMBER NOT NULL,\n                                QTY NUMBER(18,4) DEFAULT 0 NOT NULL,\n                                CONSTRAINT PK_ITEM_LOT_BIN PRIMARY KEY (LOT_ID, STORAGE_ID),\n                                CONSTRAINT FK_ILB_LOT FOREIGN KEY (LOT_ID)\n                                    REFERENCES {ITEM_LOT_TABLE}(LOT_ID),\n                                CONSTRAINT FK_ILB_WH FOREIGN KEY (STORAGE_ID)\n                                    REFERENCES {WAREHOUSE_STORAGE_TABLE}(STORAGE_ID)\n                            )\n                            ')
                    except Exception as e:
                        if '00955' not in str(e) and 'ORA-00955' not in str(e):
                            print(f'[_item_lot_apply_schema_upgrades BIN] {e}')
            conn.commit()
    except Exception as e:
        print(f'[_item_lot_apply_schema_upgrades] {e}')
    try:
        k = ITEM_LOT_TABLE.upper()
        _TABLE_COLUMNS_CACHE.pop(k, None)
    except Exception:
        pass

def ensure_item_lot_tables(db_key: Optional[str]=None) -> bool:

    def _is_ora_955(e: Exception) -> bool:
        s = str(e)
        if '00955' in s or 'ORA-00955' in s or 'name is already used' in s:
            return True
        c = getattr(e, 'code', None)
        return c == 955
    ensure_itemmaster_inventory_extension_columns()
    if _table_exists(ITEM_LOT_TABLE, db_key=db_key) and _table_exists(ITEM_LOT_BALANCE_TABLE, db_key=db_key):
        _item_lot_apply_schema_upgrades()
        return True
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                for seq in ('ITEM_LOT_SEQ', 'ITEM_LOT_MOVEMENT_SEQ'):
                    try:
                        cur.execute('SELECT 1 FROM user_sequences WHERE sequence_name = :n', {'n': seq})
                        if cur.fetchone() is None:
                            cur.execute(f'CREATE SEQUENCE {seq} START WITH 1 INCREMENT BY 1 NOCACHE')
                    except Exception:
                        pass
                if not _table_exists(ITEM_LOT_TABLE, db_key=db_key):
                    try:
                        cur.execute(f'\n                            CREATE TABLE {ITEM_LOT_TABLE} (\n                            LOT_ID NUMBER NOT NULL,\n                            LOCATIONCODE NUMBER NOT NULL,\n                            RESETNO NUMBER,\n                            ITEMCODE NUMBER NOT NULL,\n                            BATCH_NO VARCHAR2(80) NOT NULL,\n                            MFG_DATE DATE,\n                            EXPIRY_DATE DATE,\n                            SUPPLIERCODE NUMBER,\n                            RECEIPT_NO NUMBER,\n                            RECEIPT_LINE NUMBER,\n                            REMARKS VARCHAR2(500),\n                            CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP,\n                            CONSTRAINT PK_ITEM_LOT PRIMARY KEY (LOT_ID),\n                            CONSTRAINT UQ_ITEM_LOT_BATCH UNIQUE (LOCATIONCODE, ITEMCODE, BATCH_NO)\n                            )\n                            ')
                    except Exception as e:
                        if not _is_ora_955(e):
                            raise
                    try:
                        cur.execute(f'CREATE INDEX IDX_ITEM_LOT_ITEM ON {ITEM_LOT_TABLE} (LOCATIONCODE, ITEMCODE, EXPIRY_DATE)')
                    except Exception:
                        pass
                if not _table_exists(ITEM_LOT_BALANCE_TABLE, db_key=db_key):
                    try:
                        cur.execute(f'\n                            CREATE TABLE {ITEM_LOT_BALANCE_TABLE} (\n                            LOT_ID NUMBER NOT NULL,\n                            QTY NUMBER(18,4) DEFAULT 0 NOT NULL,\n                            CONSTRAINT PK_ITEM_LOT_BAL PRIMARY KEY (LOT_ID),\n                            CONSTRAINT FK_LOT_BAL_LOT FOREIGN KEY (LOT_ID)\n                                REFERENCES {ITEM_LOT_TABLE}(LOT_ID)\n                            )\n                            ')
                    except Exception as e:
                        if not _is_ora_955(e):
                            raise
                if not _table_exists(ITEM_LOT_MOVEMENT_TABLE, db_key=db_key):
                    try:
                        cur.execute(f'\n                            CREATE TABLE {ITEM_LOT_MOVEMENT_TABLE} (\n                            MOV_ID NUMBER NOT NULL,\n                            LOT_ID NUMBER NOT NULL,\n                            QTY NUMBER(18,4) NOT NULL,\n                            KIND VARCHAR2(10) NOT NULL,\n                            REF_TYPE VARCHAR2(20),\n                            REF_NO NUMBER,\n                            REF_LINE NUMBER,\n                            REMARKS VARCHAR2(500),\n                            AT_TS TIMESTAMP DEFAULT SYSTIMESTAMP,\n                            CONSTRAINT PK_ITEM_LOT_MOV PRIMARY KEY (MOV_ID),\n                            CONSTRAINT FK_MOV_LOT FOREIGN KEY (LOT_ID)\n                                REFERENCES {ITEM_LOT_TABLE}(LOT_ID)\n                            )\n                            ')
                    except Exception as e:
                        if not _is_ora_955(e):
                            raise
                    try:
                        cur.execute(f'CREATE INDEX IDX_ITEM_LOT_MOV_REF ON {ITEM_LOT_MOVEMENT_TABLE} (REF_TYPE, REF_NO)')
                    except Exception:
                        pass
            conn.commit()
        _item_lot_apply_schema_upgrades()
        return True
    except Exception as e:
        print(f'[ERROR ensure_item_lot_tables] {e}')
        if _table_exists(ITEM_LOT_TABLE, db_key=db_key) and _table_exists(ITEM_LOT_BALANCE_TABLE, db_key=db_key) and _table_exists(ITEM_LOT_MOVEMENT_TABLE, db_key=db_key):
            try:
                _item_lot_apply_schema_upgrades()
            except Exception as e2:
                print(f'[WARN ensure_item_lot_tables post-check upgrades] {e2}')
            return True
        return False

_LOCATION_ITEMMASTER_BRANCH_FLAGS_CACHE: Dict[Tuple[str, int], Tuple[float, Tuple[bool, bool, bool]]] = {}
_LOCATION_ITEMMASTER_BRANCH_FLAGS_TTL_SECONDS = 300.0

def _tenant_cache_key(db_key: Optional[str]=None) -> str:
    if db_key:
        return str(db_key).strip() or 'default'
    try:
        from nexa_http import g, session, has_request_context
        current_tenant_id = g.get('current_tenant_id') if g else None
        if (not current_tenant_id) and has_request_context():
            current_tenant_id = session.get('tenant_id')
        if current_tenant_id:
            return str(current_tenant_id).strip() or 'default'
    except Exception:
        pass
    try:
        current_tenant_id = getattr(_ACTIVE_DB_CONTEXT, 'tenant_id', None)
        if current_tenant_id:
            return str(current_tenant_id).strip() or 'default'
    except Exception:
        pass
    return 'default'

def get_locationmaster_itemmaster_branch_flags(location_code: int, db_key: Optional[str]=None) -> Tuple[bool, bool, bool]:
    """
    One round-trip for Item Master / inventory gates: ``(batch_tracking, bin_tracking, warehouse_enable)``.
    Replaces three separate ``is_location_*`` calls (each repeated ensure + metadata + SELECT).
    """
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return (False, False, False)
    cache_key = (_tenant_cache_key(db_key), lc)
    now = time.time()
    cached = _LOCATION_ITEMMASTER_BRANCH_FLAGS_CACHE.get(cache_key)
    if cached and (now - cached[0]) <= _LOCATION_ITEMMASTER_BRANCH_FLAGS_TTL_SECONDS:
        return cached[1]
    ensure_location_master_branch_tracking_columns()
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    if not _table_exists(tbl, db_key=db_key):
        return (False, False, False)
    try:
        cols = {c.upper() for c in _get_table_columns(tbl) or []}
    except Exception:
        return (False, False, False)
    parts: List[str] = []
    if 'BATCH_TRACKING' in cols:
        parts.append('BATCH_TRACKING AS im_batch_trk')
    if 'BIN_TRACKING' in cols:
        parts.append('BIN_TRACKING AS im_bin_trk')
    if 'WAREHOUSE_ENABLE' in cols:
        parts.append('WAREHOUSE_ENABLE AS im_wh_en')
    if not parts:
        return (False, False, False)
    rows = _safe_rows(f"SELECT {', '.join(parts)} FROM {tbl} WHERE LOCATIONCODE = :lc", {'lc': lc}, db_key=db_key)
    if not rows:
        result = (False, False, False)
        _LOCATION_ITEMMASTER_BRANCH_FLAGS_CACHE[cache_key] = (now, result)
        return result
    r = rows[0]
    bt = False
    if 'BATCH_TRACKING' in cols:
        bt = str(r.get('im_batch_trk') or '').strip().upper() == 'Y'
    bnt = False
    if 'BIN_TRACKING' in cols:
        bnt = str(r.get('im_bin_trk') or '').strip().upper() == 'Y'
    we = False
    if 'WAREHOUSE_ENABLE' in cols:
        we = str(r.get('im_wh_en') or '').strip().upper() == 'Y'
    result = (bt, bnt, we)
    _LOCATION_ITEMMASTER_BRANCH_FLAGS_CACHE[cache_key] = (now, result)
    if len(_LOCATION_ITEMMASTER_BRANCH_FLAGS_CACHE) > 200:
        for k in list(_LOCATION_ITEMMASTER_BRANCH_FLAGS_CACHE.keys())[:100]:
            _LOCATION_ITEMMASTER_BRANCH_FLAGS_CACHE.pop(k, None)
    return result

def is_location_batch_tracking_enabled(location_code: int, _db_key_ignored: Any=None) -> bool:
    """
    True if **LOCATIONMASTER.BATCH_TRACKING** = ``'Y'`` for this ``LOCATIONCODE``.

    When ``False``, batch/lot posting is disabled for this branch regardless of **ITEMMASTER.BATCH_TRACKED**.
    """
    ensure_location_master_branch_tracking_columns()
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    if not _table_exists(tbl):
        return False
    try:
        cols = {c.upper() for c in _get_table_columns(tbl) or []}
    except Exception:
        return False
    if 'BATCH_TRACKING' not in cols:
        return False
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return False
    rows = _safe_rows(f'SELECT BATCH_TRACKING AS bt FROM {tbl} WHERE LOCATIONCODE = :lc', {'lc': lc})
    if not rows:
        return False
    return str(rows[0].get('bt') or '').strip().upper() == 'Y'

