def get_location_sales_feature_flags(location_code: int) -> Dict[str, bool]:
    """One LOCATIONMASTER read for warehouse / bin / batch flags (Sales Invoice form open)."""
    out = {'warehouse_enabled': False, 'bin_tracking_enabled': False, 'batch_tracking_enabled': False}
    try:
        ensure_location_master_warehouse_enable_column()
        ensure_location_master_bin_tracking_column()
        ensure_location_master_branch_tracking_columns()
    except Exception:
        pass
    tbl = (LOCATIONS_TABLE or 'LOCATIONMASTER').strip().upper()
    if not _table_exists(tbl):
        return out
    try:
        cols = {c.upper() for c in _get_table_columns(tbl) or []}
    except Exception:
        return out
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return out
    sel = []
    if 'WAREHOUSE_ENABLE' in cols:
        sel.append("NVL(WAREHOUSE_ENABLE, 'N') AS we")
    else:
        sel.append("'N' AS we")
    if 'BIN_TRACKING' in cols:
        sel.append("NVL(BIN_TRACKING, 'N') AS bin_t")
    else:
        sel.append("'N' AS bin_t")
    if 'BATCH_TRACKING' in cols:
        sel.append("NVL(BATCH_TRACKING, 'N') AS batch_t")
    else:
        sel.append("'N' AS batch_t")
    rows = _safe_rows(
        f"SELECT {', '.join(sel)} FROM {tbl} WHERE LOCATIONCODE = :lc",
        {'lc': lc},
    )
    if not rows:
        return out
    r = rows[0] or {}
    wh = str(r.get('we') or '').strip().upper() == 'Y'
    out['warehouse_enabled'] = wh
    out['bin_tracking_enabled'] = wh and str(r.get('bin_t') or '').strip().upper() == 'Y'
    out['batch_tracking_enabled'] = str(r.get('batch_t') or '').strip().upper() == 'Y'
    return out

def is_item_batch_tracked(item_code: int, location_code: int, db_key: Optional[str]=None) -> bool:
    """True when branch allows batch (**LOCATIONMASTER.BATCH_TRACKING**) and ITEMMASTER.BATCH_TRACKED = 'Y'."""
    if not is_location_batch_tracking_enabled(int(location_code)):
        return False
    ensure_item_lot_tables(db_key=db_key)
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return False
    cols = {c.upper() for c in _get_table_columns(im) or []}
    if 'BATCH_TRACKED' not in cols:
        return False
    code_col = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    loc_col = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    if not code_col:
        return False
    w = [f'{code_col} = :ic']
    p: Dict[str, Any] = {'ic': int(item_code)}
    if loc_col:
        w.append(f'{loc_col} = :loc')
        p['loc'] = int(location_code)
    rows = _safe_rows(f"SELECT BATCH_TRACKED AS bt FROM {im} WHERE {' AND '.join(w)}", p)
    if not rows:
        return False
    return str(rows[0].get('bt') or '').strip().upper() == 'Y'

def is_item_bin_configured(item_code: int, location_code: int, db_key: Optional[str]=None) -> bool:
    """True when branch bin tracking is on and item has default/staging bin or BIN_STOCK qty."""
    if not is_location_bin_tracking_enabled(int(location_code)):
        return False
    ensure_itemmaster_default_bin_storage_id_column()
    ensure_itemmaster_staging_bin_storage_id_column()
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return False
    cols = {c.upper() for c in _get_table_columns(im) or []}
    code_col = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    loc_col = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    if not code_col:
        return False
    sel = []
    if 'DEFAULT_BIN_STORAGE_ID' in cols:
        sel.append('DEFAULT_BIN_STORAGE_ID AS default_bin')
    if 'STAGING_BIN_STORAGE_ID' in cols:
        sel.append('STAGING_BIN_STORAGE_ID AS staging_bin')
    if sel:
        w = [f'{code_col} = :ic']
        p: Dict[str, Any] = {'ic': int(item_code)}
        if loc_col:
            w.append(f'{loc_col} = :loc')
            p['loc'] = int(location_code)
        rows = _safe_rows(f"SELECT {', '.join(sel)} FROM {im} WHERE {' AND '.join(w)}", p)
        if rows:
            r0 = rows[0]
            for k in ('default_bin', 'staging_bin'):
                v = r0.get(k)
                if v is not None:
                    try:
                        if int(float(v)) > 0:
                            return True
                    except (TypeError, ValueError):
                        pass
    if _table_exists(BIN_STOCK_TABLE, db_key=db_key):
        bs_cols = {c.upper() for c in _get_table_columns(BIN_STOCK_TABLE) or []}
        ic_col = _detect_column(BIN_STOCK_TABLE, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
        lc_col = _detect_column(BIN_STOCK_TABLE, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
        qty_col = _detect_column(BIN_STOCK_TABLE, ['QTY', 'qty', 'QUANTITY'])
        if ic_col and qty_col:
            w2 = [f'{ic_col} = :ic', f'NVL({qty_col}, 0) > 0']
            p2: Dict[str, Any] = {'ic': int(item_code)}
            if lc_col:
                w2.append(f'{lc_col} = :loc')
                p2['loc'] = int(location_code)
            try:
                cnt = _safe_rows(f'SELECT 1 AS x FROM {BIN_STOCK_TABLE} WHERE {" AND ".join(w2)} AND ROWNUM = 1', p2)
                if cnt:
                    return True
            except Exception:
                pass
    return False

def set_item_batch_tracked(item_code: int, location_code: int, tracked: bool, db_key: Optional[str]=None) -> Tuple[bool, str]:
    """Set ITEMMASTER.BATCH_TRACKED to Y/N. Postings apply lots only when branch BATCH_TRACKING is Y too."""
    ensure_item_lot_tables(db_key=db_key)
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return (False, 'ITEMMASTER not found.')
    cols = {c.upper() for c in _get_table_columns(im) or []}
    if 'BATCH_TRACKED' not in cols:
        return (False, 'BATCH_TRACKED column missing; run app once to migrate.')
    code_col = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    loc_col = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    if not code_col:
        return (False, 'Invalid item table.')
    flg = 'Y' if tracked else 'N'
    w = [f'{code_col} = :ic']
    p: Dict[str, Any] = {'ic': int(item_code), 'f': flg}
    if loc_col:
        w.append(f'{loc_col} = :loc')
        p['loc'] = int(location_code)
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f"UPDATE {im} SET BATCH_TRACKED = :f WHERE {' AND '.join(w)}", p)
                if cur.rowcount == 0:
                    conn.rollback()
                    return (False, 'Item row not found for this location.')
            conn.commit()
        return (True, '')
    except Exception as e:
        return (False, str(e))

def is_item_weight_item(item_code: int, location_code: int, db_key: Optional[str]=None) -> bool:
    """True when ITEMMASTER.IS_WEIGHT_ITEM = 'Y' for this branch/item."""
    ensure_itemmaster_inventory_extension_columns()
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return False
    cols = {c.upper() for c in _get_table_columns(im) or []}
    if 'IS_WEIGHT_ITEM' not in cols:
        return False
    code_col = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    loc_col = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    if not code_col:
        return False
    w = [f'{code_col} = :ic']
    p: Dict[str, Any] = {'ic': int(item_code)}
    if loc_col:
        w.append(f'{loc_col} = :loc')
        p['loc'] = int(location_code)
    rows = _safe_rows(f"SELECT NVL(IS_WEIGHT_ITEM, 'N') AS flg FROM {im} WHERE {' AND '.join(w)} AND ROWNUM = 1", p, db_key=db_key)
    if not rows:
        return False
    return str(rows[0].get('flg') or '').strip().upper() == 'Y'

