def _parse_line_date(val: Any) -> Optional[datetime]:
    if val is None:
        return None
    if isinstance(val, datetime):
        return val
    s = str(val).strip()
    if not s:
        return None
    for fmt in ('%Y-%m-%d', '%d-%b-%Y', '%d/%m/%Y', '%Y/%m/%d', '%d-%m-%Y'):
        try:
            return datetime.strptime(s[:32], fmt)
        except Exception:
            continue
    return None

def parse_grn_receipt_header_datetime(val: Optional[str]) -> Optional[datetime]:
    """Parse GRN header receipt date strings (ISO date, DD-MON-YYYY, etc.) for lot/expiry defaults."""
    s = (val or '').strip()
    if not s:
        return None
    if len(s) >= 10 and s[4:5] == '-' and (s[7:8] == '-'):
        try:
            return datetime.strptime(s[:10], '%Y-%m-%d')
        except ValueError:
            pass
    return _parse_line_date(s[:32])

def grn_line_has_batch_intent(line: Dict[str, Any]) -> bool:
    """True if the GRN line payload carries batch/mfg/expiry the user expects to persist."""
    bn = str(line.get('batch_no') or line.get('batchno') or line.get('BATCH_NO') or '').strip()
    if bn:
        return True
    for k in ('mfg_date', 'mfgdate', 'MFG_DATE', 'expiry_date', 'expirydate', 'EXPIRY_DATE'):
        if _parse_line_date(line.get(k)):
            return True
    return False

def _item_lot_insert_movement_cur(cur: Any, lot_id: int, qty: float, kind: str, ref_type: Optional[str], ref_no: Optional[int], ref_line: Optional[int], remarks: Optional[str]=None) -> None:
    cur.execute('SELECT ITEM_LOT_MOVEMENT_SEQ.NEXTVAL FROM DUAL')
    r = cur.fetchone()
    mid = int(r[0]) if r and r[0] is not None else None
    if mid is None:
        raise RuntimeError('Could not allocate movement id.')
    cur.execute(f'\n        INSERT INTO {ITEM_LOT_MOVEMENT_TABLE}\n        (MOV_ID, LOT_ID, QTY, KIND, REF_TYPE, REF_NO, REF_LINE, REMARKS)\n        VALUES (:mid, :lid, :q, :k, :rt, :rn, :rl, :rm)\n        ', {'mid': mid, 'lid': int(lot_id), 'q': float(qty), 'k': (kind or 'IN')[:10], 'rt': (ref_type or '')[:20] or None, 'rn': ref_no, 'rl': ref_line, 'rm': (remarks or '')[:500] or None})

def undo_item_lot_movements_for_ref_cur(cur: Any, ref_type: str, ref_no: int) -> None:
    """
    Reverse balance impact of movements for this ref, then delete those rows.
    Restores unallocated balance only (binned qty is not reversed here).
    """
    if not _table_exists(ITEM_LOT_MOVEMENT_TABLE):
        return
    rt = (ref_type or '')[:20]
    try:
        rn = int(ref_no)
    except (TypeError, ValueError):
        return
    cur.execute(f"\n        SELECT LOT_ID, QTY FROM {ITEM_LOT_MOVEMENT_TABLE}\n        WHERE UPPER(NVL(REF_TYPE,'')) = UPPER(:rt) AND REF_NO = :rn\n        ", {'rt': rt, 'rn': rn})
    for row in cur.fetchall() or []:
        try:
            lid = int(row[0])
            qf = float(row[1] or 0)
        except (TypeError, ValueError):
            continue
        if abs(qf) < 1e-12:
            continue
        if not _table_exists(ITEM_LOT_BALANCE_TABLE):
            continue
        cur.execute(f'SELECT NVL(QTY,0) FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :lid FOR UPDATE', {'lid': lid})
        br = cur.fetchone()
        bbal = float(br[0] or 0) if br else 0.0
        nq = bbal - qf
        if nq < 1e-09 and br:
            cur.execute(f'DELETE FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :lid', {'lid': lid})
        elif br:
            cur.execute(f'UPDATE {ITEM_LOT_BALANCE_TABLE} SET QTY = :q WHERE LOT_ID = :lid', {'q': nq, 'lid': lid})
        else:
            cur.execute(f'INSERT INTO {ITEM_LOT_BALANCE_TABLE} (LOT_ID, QTY) VALUES (:lid, :q)', {'lid': lid, 'q': nq})
    cur.execute(f"DELETE FROM {ITEM_LOT_MOVEMENT_TABLE} WHERE UPPER(NVL(REF_TYPE,'')) = UPPER(:rt) AND REF_NO = :rn", {'rt': rt, 'rn': rn})

def stock_adjustment_apply_batch_lot_cur(cur: Any, location_code: int, item_code: int, base_delta: float, adj_no: int, line_no: int, explicit_lot_id: Optional[int]=None, unit_cost_hint: Optional[float]=None, ref_type: str='STKADJ', batch_prefix: str='ADJ') -> Optional[str]:
    """
    Positive base_delta: IN to synthetic lot (e.g. ADJ{n}-L{line} or RP{n}-L{line}). Negative: FEFO or explicit OUT.
    """
    if not ensure_item_lot_tables():
        return None
    if not is_item_batch_tracked(int(item_code), int(location_code)):
        return None
    d = float(base_delta)
    if abs(d) < 1e-09:
        return None
    if d > 0:
        loc = int(location_code)
        ic = int(item_code)
        rb = f'{str(batch_prefix or "ADJ").strip()[:8]}{int(adj_no)}-L{int(line_no)}'[:80]
        ucost: Optional[float] = None
        if unit_cost_hint is not None and float(unit_cost_hint) > 0:
            ucost = float(unit_cost_hint)
        has_uc = 'UNIT_COST' in {c.upper() for c in _get_table_columns(ITEM_LOT_TABLE) or []}
        cur.execute(f'\n            SELECT LOT_ID FROM {ITEM_LOT_TABLE}\n            WHERE LOCATIONCODE = :loc AND ITEMCODE = :ic AND BATCH_NO = :bn\n            ', {'loc': loc, 'ic': ic, 'bn': rb})
        r = cur.fetchone()
        lot_id = int(r[0]) if r and r[0] is not None else None
        if lot_id is None:
            cur.execute('SELECT ITEM_LOT_SEQ.NEXTVAL FROM DUAL')
            r2 = cur.fetchone()
            lot_id = int(r2[0]) if r2 and r2[0] is not None else None
            if lot_id is None:
                return 'Could not allocate adjustment lot id.'
            if has_uc and ucost is not None:
                cur.execute(f"\n                    INSERT INTO {ITEM_LOT_TABLE}\n                    (LOT_ID, LOCATIONCODE, ITEMCODE, BATCH_NO, MFG_DATE, EXPIRY_DATE, REMARKS, UNIT_COST)\n                    VALUES (:lid, :loc, :ic, :bn, NULL, NULL, 'Stock adjustment in', :uc)\n                    ", {'lid': lot_id, 'loc': loc, 'ic': ic, 'bn': rb, 'uc': ucost})
            else:
                cur.execute(f"\n                    INSERT INTO {ITEM_LOT_TABLE}\n                    (LOT_ID, LOCATIONCODE, ITEMCODE, BATCH_NO, MFG_DATE, EXPIRY_DATE, REMARKS)\n                    VALUES (:lid, :loc, :ic, :bn, NULL, NULL, 'Stock adjustment in')\n                    ", {'lid': lot_id, 'loc': loc, 'ic': ic, 'bn': rb})
        cur.execute(f'SELECT QTY FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :lid FOR UPDATE', {'lid': int(lot_id)})
        br = cur.fetchone()
        add_q = float(d)
        if not br:
            cur.execute(f'INSERT INTO {ITEM_LOT_BALANCE_TABLE} (LOT_ID, QTY) VALUES (:lid, :q)', {'lid': int(lot_id), 'q': add_q})
        else:
            nq = float(br[0] or 0) + add_q
            cur.execute(f'UPDATE {ITEM_LOT_BALANCE_TABLE} SET QTY = :q WHERE LOT_ID = :lid', {'q': nq, 'lid': int(lot_id)})
        rt = str(ref_type or 'STKADJ').strip()[:20] or 'STKADJ'
        _item_lot_insert_movement_cur(cur, int(lot_id), add_q, 'IN', rt, int(adj_no), int(line_no), None)
        return None
    rt = str(ref_type or 'STKADJ').strip()[:20] or 'STKADJ'
    return fefo_issue_out_for_item_cur(cur, int(location_code), int(item_code), abs(d), rt, int(adj_no), int(line_no), explicit_lot_id)

def ensure_receiptdtl_batch_mfg_expiry_columns(receiptdtl_tbl: Optional[str]=None, _db_key_ignored: Any=None) -> None:
    """
    Add BATCH_NO, MFG_DATE, and (if no legacy expiry column) EXPIRY_DATE on RECEIPTDTL when missing.

    Also adds ``LINENO NUMBER`` when the table has no line-number column (LINENO / LINE_NO / SLNO /
    RECEIPT_LINE / RECEIPTLINE). Needed when ``ITEM_LOT`` FK references RECEIPTDTL receipt lines.

    Safe to call repeatedly; failures (e.g. no DDL privilege) are ignored.
    """
    tbl = receiptdtl_tbl or _detect_table(['RECEIPTDTL', 'receiptdtl'])
    if not tbl or not _table_exists(tbl):
        return
    try:
        raw_cols = _get_table_columns(tbl) or []
    except Exception:
        return
    cols_u = {str(c).upper() for c in raw_cols}
    expiry_present = cols_u.intersection({'EXPIRY_DATE', 'EXPIRYDATE', 'DATEOFEXPIRY', 'DATE_OF_EXPIRY', 'EXPIREDATE'})
    lineno_present = cols_u.intersection({'LINENO', 'LINE_NO', 'SLNO', 'RECEIPT_LINE', 'RECEIPTLINE'})
    statements: List[str] = []
    if 'BATCH_NO' not in cols_u:
        statements.append(f'ALTER TABLE {tbl} ADD BATCH_NO VARCHAR2(80)')
    if 'RECEIVEDQTY' not in cols_u and 'RECEIVED_QTY' not in cols_u:
        statements.append(f'ALTER TABLE {tbl} ADD RECEIVEDQTY NUMBER(18,3)')
    if 'MFG_DATE' not in cols_u:
        statements.append(f'ALTER TABLE {tbl} ADD MFG_DATE DATE')
    if not expiry_present:
        statements.append(f'ALTER TABLE {tbl} ADD EXPIRY_DATE DATE')
    if not lineno_present:
        statements.append(f'ALTER TABLE {tbl} ADD LINENO NUMBER')
    if not statements:
        return
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                for sql in statements:
                    try:
                        cur.execute(sql)
                    except Exception:
                        pass
            conn.commit()
    except Exception:
        return
    try:
        _TABLE_COLUMNS_CACHE.pop(tbl.upper(), None)
    except Exception:
        pass

