def _ensure_table_warehouse_code_and_id_columns(tbl: str, *, code_varchar_len: int=30) -> None:
    """Rename ``INVENTORYLOCATION`` → ``WAREHOUSE_CODE`` when present; ensure ``WAREHOUSE_ID``."""
    if not tbl or not _table_exists(tbl):
        return
    try:
        cols_u = {str(c).upper() for c in (_get_table_columns(tbl) or [])}
    except Exception:
        return
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if 'INVENTORYLOCATION' in cols_u and 'WAREHOUSE_CODE' not in cols_u:
                    try:
                        cur.execute(f'ALTER TABLE {tbl} RENAME COLUMN INVENTORYLOCATION TO WAREHOUSE_CODE')
                    except Exception:
                        _ensure_table_column(tbl, 'WAREHOUSE_CODE', f'ALTER TABLE {tbl} ADD (WAREHOUSE_CODE VARCHAR2({code_varchar_len}))')
                        try:
                            cur.execute(f'UPDATE {tbl} SET WAREHOUSE_CODE = INVENTORYLOCATION WHERE WAREHOUSE_CODE IS NULL')
                        except Exception:
                            pass
                elif 'WAREHOUSE_CODE' not in cols_u:
                    _ensure_table_column(tbl, 'WAREHOUSE_CODE', f'ALTER TABLE {tbl} ADD (WAREHOUSE_CODE VARCHAR2({code_varchar_len}))')
                if 'WAREHOUSE_ID' not in cols_u:
                    try:
                        cur.execute(f'ALTER TABLE {tbl} ADD (WAREHOUSE_ID NUMBER)')
                    except Exception:
                        pass
            conn.commit()
    except Exception:
        pass
    try:
        _TABLE_COLUMNS_CACHE.pop(tbl.upper(), None)
    except Exception:
        pass

