def ensure_tempreturn_tables() -> bool:
    """Create TEMPRETURNHDR / TEMPRETURNDTL for purchase return requests (draft/approved workflow)."""
    global _TEMPRETURN_SCHEMA_ENSURED_PROCESS
    try:
        from nexa_http import g, has_request_context
        if has_request_context() and getattr(g, '_tempreturn_schema_ensured', False):
            return _table_exists('TEMPRETURNHDR') and _table_exists('TEMPRETURNDTL')
    except Exception:
        pass
    if _TEMPRETURN_SCHEMA_ENSURED_PROCESS:
        return _table_exists('TEMPRETURNHDR') and _table_exists('TEMPRETURNDTL')
    try:
        if _table_exists('TEMPRETURNHDR') and _table_exists('TEMPRETURNDTL'):
            try:
                ensure_returndtl_warehouse_columns()
            except Exception:
                pass
            try:
                ensure_tempreturnhdr_posting_date_column()
            except Exception:
                pass
            try:
                ensure_tempreturnhdr_discount_column()
            except Exception:
                pass
            _TEMPRETURN_SCHEMA_ENSURED_PROCESS = True
            try:
                from nexa_http import g, has_request_context
                if has_request_context():
                    g._tempreturn_schema_ensured = True
            except Exception:
                pass
            return True
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if not _table_exists('TEMPRETURNHDR'):
                    cur.execute(
                        """
                        CREATE TABLE TEMPRETURNHDR (
                            LOCATIONCODE NUMBER NOT NULL,
                            GOODSRETURNNO NUMBER NOT NULL,
                            RETURNDATE DATE,
                            POSTINGDATE DATE,
                            RETURNTYPE CHAR(1) DEFAULT 'P',
                            TRANSFERLOCATION NUMBER,
                            SUPPLIERCODE NUMBER,
                            RECEIPTNO NUMBER,
                            RETURNAMOUNT NUMBER(18,3) DEFAULT 0,
                            DISCOUNT NUMBER(18,3) DEFAULT 0,
                            DELFLAG CHAR(1) DEFAULT 'N',
                            CREATEDBY VARCHAR2(20),
                            CREATEDDATE DATE DEFAULT SYSDATE,
                            MODIFIEDBY VARCHAR2(20),
                            MODIFIEDDATE DATE,
                            RESETNO NUMBER DEFAULT 0,
                            TRANSACTIONNO NUMBER,
                            SUPERVISOR VARCHAR2(20),
                            RECEIVER VARCHAR2(20),
                            SECTIONINC VARCHAR2(100),
                            CONSTRAINT PK_TEMPRETURNHDR PRIMARY KEY (LOCATIONCODE, GOODSRETURNNO)
                        )
                        """
                    )
                if not _table_exists('TEMPRETURNDTL'):
                    cur.execute(
                        """
                        CREATE TABLE TEMPRETURNDTL (
                            LOCATIONCODE NUMBER NOT NULL,
                            GOODSRETURNNO NUMBER NOT NULL,
                            ITEMCODE NUMBER NOT NULL,
                            UOM VARCHAR2(10),
                            QUANTITY NUMBER(18,3) DEFAULT 0,
                            RATE NUMBER(18,3) DEFAULT 0,
                            RESETNO NUMBER DEFAULT 0,
                            STORE VARCHAR2(20),
                            COSTPRICE NUMBER(18,3) DEFAULT 0,
                            MANUFACTURERID VARCHAR2(50),
                            DISCOUNT NUMBER(18,3) DEFAULT 0,
                            AMOUNT NUMBER(18,3) DEFAULT 0,
                            CONVERSIONFACTOR NUMBER(18,6) DEFAULT 1,
                            WAREHOUSE_ID NUMBER,
                            STORAGE_ID NUMBER,
                            LOT_ID NUMBER,
                            CONSTRAINT PK_TEMPRETURNDTL PRIMARY KEY (LOCATIONCODE, GOODSRETURNNO, ITEMCODE)
                        )
                        """
                    )
                conn.commit()
        try:
            ensure_returndtl_warehouse_columns()
        except Exception:
            pass
        try:
            ensure_returndtl_discount_amount_columns()
        except Exception:
            pass
        try:
            ensure_tempreturnhdr_posting_date_column()
        except Exception:
            pass
        try:
            ensure_tempreturnhdr_discount_column()
        except Exception:
            pass
        ok = _table_exists('TEMPRETURNHDR') and _table_exists('TEMPRETURNDTL')
        if ok:
            _TEMPRETURN_SCHEMA_ENSURED_PROCESS = True
            try:
                from nexa_http import g, has_request_context
                if has_request_context():
                    g._tempreturn_schema_ensured = True
            except Exception:
                pass
        return ok
    except Exception as e:
        print(f'[ERROR ensure_tempreturn_tables] {e}')
        return False


