def item_lot_id_for_batch_at_location_cur(cur: Any, location_code: Any, item_code: Any, batch_no: Optional[str]) -> Optional[int]:
    """Resolve ITEM_LOT.LOT_ID after GRN lot posting (same batch key as receipt_apply_lot)."""
    bn = str(batch_no or '').strip()
    if not bn or not _table_exists(ITEM_LOT_TABLE):
        return None
    try:
        loc = int(location_code)
        ic = int(item_code)
    except (TypeError, ValueError):
        return None
    try:
        cur.execute(
            f'\n            SELECT LOT_ID FROM {ITEM_LOT_TABLE}\n            WHERE LOCATIONCODE = :loc AND ITEMCODE = :ic\n              AND UPPER(TRIM(BATCH_NO)) = UPPER(TRIM(:bn))\n            ',
            {'loc': loc, 'ic': ic, 'bn': bn},
        )
        row = cur.fetchone()
        if row and row[0] is not None:
            return int(row[0])
    except Exception:
        return None
    return None

def ensure_itemjournal_storage_id_column(_db_key_ignored: Any=None) -> None:
    """Add STORAGE_ID on ITEMJOURNAL / ITEMJOURNEL for warehouse bin trace (own connection; DDL-safe)."""
    for tbl_u in ('ITEMJOURNAL', 'ITEMJOURNEL'):
        try:
            if not _table_exists(tbl_u):
                continue
            try:
                cols_u = {str(c).upper() for c in (_get_table_columns(tbl_u) or [])}
            except Exception:
                cols_u = set()
            if 'STORAGE_ID' in cols_u:
                continue
            try:
                with _get_connection() as conn:
                    with conn.cursor() as cur:
                        try:
                            cur.execute(f'ALTER TABLE {tbl_u} ADD STORAGE_ID NUMBER')
                        except Exception:
                            pass
                    conn.commit()
            except Exception:
                pass
            try:
                _TABLE_COLUMNS_CACHE.pop(tbl_u, None)
            except Exception:
                pass
        except Exception:
            pass

def resolve_grn_line_lot_batch_mfg_expiry(location_code: int, item_num: int, base_qty: float, line: Dict[str, Any], receipt_no: int, line_idx: int, line_foc: bool, grn_receipt_date: Optional[datetime]=None) -> Tuple[Optional[str], Optional[datetime], Optional[datetime], Optional[str]]:
    """
    Canonical batch key + manufacturing/expiry used for GRN ITEM_LOT and RECEIPTDTL.

    Returns ``(batch_key, mfg_date, expiry_date, error)``.
    When lot rules do not apply (not batch-tracked, FOC, zero qty): ``(None, None, None, None)``.
    On validation error (same as lot posting would fail): ``(_, _, _, error_message)``.
    """
    if line_foc or abs(float(base_qty or 0)) < 1e-09:
        return (None, None, None, None)
    if not is_item_batch_tracked(int(item_num), int(location_code)):
        return (None, None, None, None)
    batch_no = str(line.get('batch_no') or line.get('batchno') or line.get('BATCH_NO') or '').strip()
    exp = _parse_line_date(line.get('expiry_date') or line.get('expirydate') or line.get('EXPIRY_DATE'))
    base_for_exp = grn_receipt_date
    if base_for_exp is None:
        base_for_exp = _parse_line_date(line.get('receiptdate') or line.get('receipt_date') or line.get('RECEIPTDATE'))
    if not batch_no:
        try:
            rn = int(receipt_no)
            li = int(line_idx)
            ic = int(item_num)
        except (TypeError, ValueError):
            return (None, None, None, f'Line {line_idx}: cannot auto-generate batch — invalid receipt/line/item.')
        batch_no = f'AUTO-G{rn}-L{li}-I{ic}'
    if not exp:
        if base_for_exp:
            exp = base_for_exp + timedelta(days=365)
        else:
            return (None, None, None, f'Line {line_idx}: expiry date is required for batch-tracked item {item_num} (or set a valid GRN receipt date for default expiry).')
    mfg = _parse_line_date(line.get('mfg_date') or line.get('mfgdate') or line.get('MFG_DATE'))
    bkey = batch_no[:80]
    return (bkey, mfg, exp, None)

def _item_lot_receipt_fk_column_sets(il_cols_u: Set[str]) -> Tuple[List[str], List[str]]:
    """
    RECEIPT reference columns present on ITEM_LOT for FK to RECEIPTDTL / RECEIPTHDR.

    RF / TEST_HAYYA pattern: RECEIPTDTL has RECEIPTNO + LINENO + RESETNO; ITEM_LOT has
    RECEIPT_NO + RECEIPT_LINE + RESETNO — FK pairs columns by position; values must match
    (same receipt number and line index).

    Other sites use RECEIPTNO/LINENO on ITEM_LOT; Nexa-created DDL uses RECEIPT_NO/RECEIPT_LINE only.
    Populate every alias that exists on ITEM_LOT so constraint-checked columns are not NULL.
    """
    no_cols = [c for c in ('RECEIPTNO', 'RECEIPT_NO') if c in il_cols_u]
    line_cols = [c for c in ('LINENO', 'SLNO', 'RECEIPT_LINE') if c in il_cols_u]
    if not no_cols:
        no_cols = ['RECEIPT_NO']
    if not line_cols:
        line_cols = ['RECEIPT_LINE']
    return (no_cols, line_cols)

def receipt_apply_lot_on_grn_line_cur(cur: Any, location_code: int, item_num: int, base_qty: float, line: Dict[str, Any], supplier_code: int, receipt_no: int, line_idx: int, line_foc: bool, reset_no: Optional[int]=None, grn_receipt_date: Optional[datetime]=None) -> Optional[str]:
    """
    On GRN posting: add stock to ITEM_LOT / balance. Returns error string or None.

    For batch-tracked items, if batch number or expiry are omitted:
    batch → ``AUTO-G{receipt}-L{line}-I{item}`` (truncated to 80 chars);
    expiry → GRN receipt date + 365 days (from ``grn_receipt_date`` or line date fields).

    Pass ``reset_no`` when ``ITEM_LOT`` has ``RESETNO`` and RECEIPT detail uses the same reset (see ``_save_receipt``).

    Insert order is always ``ITEM_LOT`` then ``ITEM_LOT_BALANCE`` — matches ``FK_LOT_BAL_LOT`` (balance references lot).
    If ``ITEM_LOT`` also has ``FK_ITEM_LOT_ITEM_LOT_B`` (lot→balance), drop that constraint; paired with ``FK_LOT_BAL_LOT``
    it creates an impossible circular FK unless constraints are deferrable.
    """
    if not ensure_item_lot_tables():
        return 'Batch/lot tables could not be created.'
    bkey, mfg, exp, err = resolve_grn_line_lot_batch_mfg_expiry(location_code, item_num, base_qty, line, receipt_no, line_idx, line_foc, grn_receipt_date)
    if err:
        return err
    if not bkey:
        return None
    try:
        loc = int(location_code)
        ic = int(item_num)
        qv = abs(float(base_qty))
    except (TypeError, ValueError):
        return f'Line {line_idx}: invalid quantity or codes.'
    unit_cost: Optional[float] = None
    try:
        land = float(line.get('landingcost') or line.get('LANDINGCOST') or line.get('averagecost') or line.get('AVERAGECOST') or 0)
        if land > 0:
            unit_cost = land
        else:
            rate = float(line.get('rate') or line.get('RATE') or 0)
            conv = float(line.get('conversionfactor') or line.get('conversion_factor') or line.get('CONVERSIONFACTOR') or 0)
            amt = float(line.get('amount') or line.get('AMOUNT') or 0)
            och = float(line.get('othercharge') or line.get('OTHERCHARGE') or 0)
            bq = abs(float(base_qty or 0))
            if bq > 1e-12:
                unit_cost = (amt + och) / bq
            elif conv and conv > 0:
                unit_cost = rate / conv
            elif rate > 0:
                unit_cost = rate
    except (TypeError, ValueError):
        unit_cost = None
    has_uc = 'UNIT_COST' in {c.upper() for c in _get_table_columns(ITEM_LOT_TABLE) or []}
    il_cols_u = {c.upper() for c in (_get_table_columns(ITEM_LOT_TABLE) or [])}
    rn_il_col: Optional[str] = None
    if 'RESETNO' in il_cols_u:
        rn_il_col = 'RESETNO'
    elif 'RESET_NO' in il_cols_u:
        rn_il_col = 'RESET_NO'
    cur.execute(f'\n        SELECT LOT_ID FROM {ITEM_LOT_TABLE}\n        WHERE LOCATIONCODE = :loc AND ITEMCODE = :ic\n          AND UPPER(TRIM(BATCH_NO)) = UPPER(TRIM(:bn))\n        ', {'loc': loc, 'ic': ic, 'bn': bkey})
    row = cur.fetchone()
    lot_id: Optional[int] = int(row[0]) if row and row[0] is not None else None
    if lot_id is None:
        cur.execute('SELECT ITEM_LOT_SEQ.NEXTVAL FROM DUAL')
        r2 = cur.fetchone()
        lot_id = int(r2[0]) if r2 and r2[0] is not None else None
        if lot_id is None:
            return 'Could not allocate lot id.'
        # FK_LOT_BAL_LOT: ITEM_LOT_BALANCE → ITEM_LOT ⇒ insert lot row then balance row.
        # Remove ITEM_LOT.FK_ITEM_LOT_ITEM_LOT_B if defined (ITEM_LOT → ITEM_LOT_BALANCE); it contradicts FK_LOT_BAL_LOT.
        cols_il = ['LOT_ID', 'LOCATIONCODE']
        ph_il = [':lid', ':loc']
        bind_il: Dict[str, Any] = {'lid': lot_id, 'loc': loc}
        if rn_il_col is not None and reset_no is not None:
            cols_il.append(rn_il_col)
            ph_il.append(':rset')
            bind_il['rset'] = int(reset_no)
        cols_il.extend(['ITEMCODE', 'BATCH_NO', 'MFG_DATE', 'EXPIRY_DATE', 'SUPPLIERCODE'])
        ph_il.extend([':ic', ':bn', ':mfg', ':exp', ':sup'])
        bind_il.update({'ic': ic, 'bn': bkey, 'mfg': mfg, 'exp': exp, 'sup': int(supplier_code) if supplier_code else None})
        no_cols_il, line_cols_il = _item_lot_receipt_fk_column_sets(il_cols_u)
        for cn in no_cols_il:
            cols_il.append(cn)
            ph_il.append(':rno')
        for cn in line_cols_il:
            cols_il.append(cn)
            ph_il.append(':rln')
        bind_il['rno'] = int(receipt_no)
        bind_il['rln'] = int(line_idx)
        if has_uc and unit_cost is not None:
            cols_il.append('UNIT_COST')
            ph_il.append(':uc')
            bind_il['uc'] = float(unit_cost)
        sql_il = f"INSERT INTO {ITEM_LOT_TABLE} ({', '.join(cols_il)}) VALUES ({', '.join(ph_il)})"
        sql_bal = f'INSERT INTO {ITEM_LOT_BALANCE_TABLE} (LOT_ID, QTY) VALUES (:lid, :q)'
        bal_params = {'lid': lot_id, 'q': qv}
        cur.execute(sql_il, bind_il)
        cur.execute(sql_bal, bal_params)
    else:
        if has_uc and unit_cost is not None:
            try:
                cur.execute(f'\n                    UPDATE {ITEM_LOT_TABLE}\n                    SET UNIT_COST = NVL(UNIT_COST, :uc)\n                    WHERE LOT_ID = :lid\n                    ', {'uc': float(unit_cost), 'lid': int(lot_id)})
            except Exception:
                pass
        cur.execute(f'SELECT QTY FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :lid FOR UPDATE', {'lid': lot_id})
        br = cur.fetchone()
        if not br:
            cur.execute(f'INSERT INTO {ITEM_LOT_BALANCE_TABLE} (LOT_ID, QTY) VALUES (:lid, :q)', {'lid': lot_id, 'q': qv})
        else:
            nq = float(br[0] or 0) + qv
            cur.execute(f'UPDATE {ITEM_LOT_BALANCE_TABLE} SET QTY = :q WHERE LOT_ID = :lid', {'q': nq, 'lid': lot_id})
    _item_lot_insert_movement_cur(cur, int(lot_id), qv, 'IN', 'GRN', int(receipt_no), int(line_idx), None)
    return None

def _lot_on_hand_subquery_bin() -> str:
    if not _table_exists(ITEM_LOT_BIN_TABLE):
        return '0'
    return f'(SELECT NVL(SUM(QTY),0) FROM {ITEM_LOT_BIN_TABLE} b2 WHERE b2.LOT_ID = l.LOT_ID)'

def _deduct_qty_from_lot_bins_and_balance_cur(cur: Any, lot_id: int, take: float, ref_type: str, ref_no: int, ref_line: int, allow_negative: bool=False) -> Optional[str]:
    """Consumes ``take`` from bins first, then unallocated balance. One OUT movement for the lot."""
    need = float(take)
    if need < 1e-09:
        return None
    lid = int(lot_id)
    if _table_exists(ITEM_LOT_BIN_TABLE):
        cur.execute(f'\n            SELECT STORAGE_ID, QTY FROM {ITEM_LOT_BIN_TABLE}\n            WHERE LOT_ID = :lid AND QTY > 0.0001\n            ORDER BY STORAGE_ID\n            FOR UPDATE\n            ', {'lid': lid})
        for br in cur.fetchall() or []:
            if need < 1e-09:
                break
            sid = int(br[0])
            bq = float(br[1] or 0)
            if bq < 1e-09:
                continue
            use = min(need, bq)
            nq = bq - use
            if nq < 1e-09:
                cur.execute(f'DELETE FROM {ITEM_LOT_BIN_TABLE} WHERE LOT_ID = :lid AND STORAGE_ID = :sid', {'lid': lid, 'sid': sid})
            else:
                cur.execute(f'\n                    UPDATE {ITEM_LOT_BIN_TABLE}\n                    SET QTY = :q WHERE LOT_ID = :lid AND STORAGE_ID = :sid\n                    ', {'q': nq, 'lid': lid, 'sid': sid})
            need -= use
    cur.execute(f'SELECT NVL(QTY,0) FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :lid FOR UPDATE', {'lid': lid})
    row = cur.fetchone()
    bbal = float(row[0] or 0) if row else 0.0
    if need > bbal + 1e-05 and not allow_negative:
        return f'Lot {lid}: insufficient quantity (bins + unallocated).'
    new_b = bbal - need
    if abs(new_b) < 1e-09 and row is not None:
        cur.execute(f'DELETE FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :lid', {'lid': lid})
    elif row is not None:
        cur.execute(f'UPDATE {ITEM_LOT_BALANCE_TABLE} SET QTY = :q WHERE LOT_ID = :lid', {'q': new_b, 'lid': lid})
    elif allow_negative:
        cur.execute(f'INSERT INTO {ITEM_LOT_BALANCE_TABLE} (LOT_ID, QTY) VALUES (:lid, :q)', {'lid': lid, 'q': new_b})
    elif need > 1e-09:
        return f'Lot {lid}: no balance row.'
    _item_lot_insert_movement_cur(cur, lid, -abs(float(take)), 'OUT', ref_type, ref_no, ref_line, None)
    return None

def fefo_issue_out_for_item_cur(cur: Any, location_code: int, item_code: int, need_qty: float, ref_type: str, ref_no: int, ref_line: int, explicit_lot_id: Optional[int]=None, allow_negative: bool=False) -> Optional[str]:
    """FEFO issue (or single-lot if explicit_lot_id set)."""
    loc = int(location_code)
    ic = int(item_code)
    need = abs(float(need_qty or 0))
    if need < 1e-09:
        return None
    if explicit_lot_id is not None:
        cur.execute(f"\n            SELECT l.LOT_ID,\n                   NVL(b.QTY,0) + NVL({_lot_on_hand_subquery_bin()},0) AS av,\n                   UPPER(NVL(TRIM(l.LOT_BLOCKED),'N')) AS lb\n            FROM {ITEM_LOT_TABLE} l\n            LEFT JOIN {ITEM_LOT_BALANCE_TABLE} b ON b.LOT_ID = l.LOT_ID\n            WHERE l.LOT_ID = :lid AND l.LOCATIONCODE = :loc AND l.ITEMCODE = :ic\n            FOR UPDATE\n            ", {'lid': int(explicit_lot_id), 'loc': loc, 'ic': ic})
        r = cur.fetchone()
        if not r:
            return f'Lot {explicit_lot_id} not found for this item/location.'
        av = float(r[1] or 0)
        lb = str(r[2] or 'N').strip().upper()
        if lb == 'Y':
            return f'Lot {explicit_lot_id} is blocked (QC hold) and cannot be issued.'
        if av + 1e-09 < need and not allow_negative:
            return f'Lot {explicit_lot_id}: only {av:.3f} available.'
        return _deduct_qty_from_lot_bins_and_balance_cur(cur, int(explicit_lot_id), need, ref_type, ref_no, ref_line, allow_negative=allow_negative)
    bin_sq = _lot_on_hand_subquery_bin()
    cur.execute(f"\n        SELECT l.LOT_ID, l.EXPIRY_DATE,\n               NVL(b.QTY,0) + NVL({bin_sq},0) AS av\n        FROM {ITEM_LOT_TABLE} l\n        LEFT JOIN {ITEM_LOT_BALANCE_TABLE} b ON b.LOT_ID = l.LOT_ID\n        WHERE l.LOCATIONCODE = :loc AND l.ITEMCODE = :ic\n          AND UPPER(NVL(TRIM(l.LOT_BLOCKED),'N')) <> 'Y'\n          AND ( NVL(b.QTY,0) + NVL({bin_sq},0) ) > 0.0001\n        ORDER BY l.EXPIRY_DATE NULLS LAST, l.LOT_ID\n        ", {'loc': loc, 'ic': ic})
    lot_rows = cur.fetchall()
    remaining = need
    for lr in lot_rows or []:
        if remaining < 1e-09:
            break
        lid = int(lr[0])
        av = float(lr[2] or 0)
        if av < 1e-09:
            continue
        take = min(remaining, av)
        err = _deduct_qty_from_lot_bins_and_balance_cur(cur, lid, take, ref_type, ref_no, ref_line)
        if err:
            return err
        remaining -= take
    if remaining > 1e-06:
        if allow_negative:
            neg_batch = f'NEG-{ref_type}-{ic}'[:80]
            cur.execute(f'\n                SELECT LOT_ID FROM {ITEM_LOT_TABLE}\n                WHERE LOCATIONCODE = :loc AND ITEMCODE = :ic AND BATCH_NO = :bn\n                ', {'loc': loc, 'ic': ic, 'bn': neg_batch})
            nr = cur.fetchone()
            neg_lot_id = int(nr[0]) if nr and nr[0] is not None else None
            if neg_lot_id is None:
                cur.execute('SELECT ITEM_LOT_SEQ.NEXTVAL FROM DUAL')
                sr = cur.fetchone()
                neg_lot_id = int(sr[0]) if sr and sr[0] is not None else None
                if neg_lot_id is None:
                    return 'Could not allocate negative batch lot id.'
                cur.execute(f"\n                    INSERT INTO {ITEM_LOT_TABLE}\n                    (LOT_ID, LOCATIONCODE, ITEMCODE, BATCH_NO, MFG_DATE, EXPIRY_DATE, REMARKS)\n                    VALUES (:lid, :loc, :ic, :bn, NULL, NULL, 'POS negative batch bucket')\n                    ", {'lid': neg_lot_id, 'loc': loc, 'ic': ic, 'bn': neg_batch})
            return _deduct_qty_from_lot_bins_and_balance_cur(cur, int(neg_lot_id), remaining, ref_type, ref_no, ref_line, allow_negative=True)
        return f'Insufficient batch stock for item {ic} ({ref_type}). Short by {remaining:.3f}.'
    return None

def fefo_apply_sales_issue_cur(cur: Any, location_code: int, item_code: int, qty_base: float, is_sales_return: bool, billno: int, line_no: int, explicit_lot_id: Optional[int]=None, allow_negative: bool=False, batch_tracked_precheck: Optional[bool]=None) -> Optional[str]:
    """
    Sales: deduct lots by FEFO. Sales return: add back to a return lot bucket.
    Returns error string or None.

    ``batch_tracked_precheck``: when ``False``, skip lot logic (non-batch item). When ``True``, caller
    already verified branch batch rules + ITEMMASTER.BATCH_TRACKED. When ``None``, call ``is_item_batch_tracked``.
    """
    if batch_tracked_precheck is False:
        return None
    if not ensure_item_lot_tables():
        return 'Batch/lot tables not available.'
    if batch_tracked_precheck is None:
        if not is_item_batch_tracked(int(item_code), int(location_code)):
            return None
    need = abs(float(qty_base or 0))
    if need < 1e-09:
        return None
    loc = int(location_code)
    ic = int(item_code)
    if is_sales_return:
        rb = f'RET-SR{billno}-L{line_no}'[:80]
        cur.execute(f'\n            SELECT LOT_ID FROM {ITEM_LOT_TABLE}\n            WHERE LOCATIONCODE = :loc AND ITEMCODE = :ic AND BATCH_NO = :bn\n            ', {'loc': loc, 'ic': ic, 'bn': rb})
        r = cur.fetchone()
        lot_id = int(r[0]) if r and r[0] is not None else None
        if lot_id is None:
            cur.execute('SELECT ITEM_LOT_SEQ.NEXTVAL FROM DUAL')
            r2 = cur.fetchone()
            lot_id = int(r2[0]) if r2 and r2[0] is not None else None
            if lot_id is None:
                return 'Could not allocate return lot id.'
            cur.execute(f"\n                INSERT INTO {ITEM_LOT_TABLE}\n                (LOT_ID, LOCATIONCODE, ITEMCODE, BATCH_NO, MFG_DATE, EXPIRY_DATE, REMARKS)\n                VALUES (:lid, :loc, :ic, :bn, NULL, NULL, 'Sales return bucket')\n                ", {'lid': lot_id, 'loc': loc, 'ic': ic, 'bn': rb})
            cur.execute(f'INSERT INTO {ITEM_LOT_BALANCE_TABLE} (LOT_ID, QTY) VALUES (:lid, :q)', {'lid': lot_id, 'q': need})
        else:
            cur.execute(f'SELECT QTY FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :lid FOR UPDATE', {'lid': lot_id})
            br = cur.fetchone()
            cq = float(br[0] or 0) if br else 0.0
            cur.execute(f'UPDATE {ITEM_LOT_BALANCE_TABLE} SET QTY = :q WHERE LOT_ID = :lid', {'q': cq + need, 'lid': lot_id})
        _item_lot_insert_movement_cur(cur, int(lot_id), need, 'IN', 'SALES_RET', int(billno), int(line_no), None)
        return None
    return fefo_issue_out_for_item_cur(cur, loc, ic, need, 'SALES', int(billno), int(line_no), explicit_lot_id=explicit_lot_id, allow_negative=allow_negative)

def get_item_lot_stock_list(location_code: int, itemcode: Optional[int]=None, expiring_within_days: Optional[int]=None) -> List[Dict[str, Any]]:
    """Inventory inquiry: lots with on-hand (unallocated + binned) and expiry."""
    if not ensure_item_lot_tables():
        return []
    if not _table_exists(ITEM_LOT_TABLE):
        return []
    try:
        loc = int(location_code)
    except (TypeError, ValueError):
        return []
    p: Dict[str, Any] = {'loc': loc}
    bin_sq = f'(SELECT NVL(SUM(x.QTY),0) FROM {ITEM_LOT_BIN_TABLE} x WHERE x.LOT_ID = l.LOT_ID)' if _table_exists(ITEM_LOT_BIN_TABLE) else '0'
    w = ['l.LOCATIONCODE = :loc', f'( NVL(b.QTY,0) + NVL({bin_sq},0) ) > 0.0001']
    if itemcode is not None:
        w.append('l.ITEMCODE = :ic')
        p['ic'] = int(itemcode)
    dayfilt = ''
    if expiring_within_days is not None and int(expiring_within_days) >= 0:
        dayfilt = f'AND l.EXPIRY_DATE IS NOT NULL AND l.EXPIRY_DATE <= TRUNC(SYSDATE) + {int(expiring_within_days)}'
    q = f"\n        SELECT l.LOT_ID AS lot_id, l.LOCATIONCODE AS locationcode, l.ITEMCODE AS itemcode,\n               l.BATCH_NO AS batch_no, l.MFG_DATE AS mfg_date, l.EXPIRY_DATE AS expiry_date,\n               NVL(b.QTY,0) AS qty_unalloc,\n               NVL({bin_sq},0) AS qty_binned,\n               NVL(b.QTY,0) + NVL({bin_sq},0) AS qty,\n               l.RECEIPT_NO AS receipt_no, l.SUPPLIERCODE AS suppliercode,\n               UPPER(NVL(TRIM(l.LOT_BLOCKED),'N')) AS lot_blocked\n        FROM {ITEM_LOT_TABLE} l\n        LEFT JOIN {ITEM_LOT_BALANCE_TABLE} b ON b.LOT_ID = l.LOT_ID\n        WHERE {' AND '.join(w)}\n        {dayfilt}\n        ORDER BY l.EXPIRY_DATE NULLS LAST, l.ITEMCODE, l.BATCH_NO\n    "
    return _safe_rows(q, p) or []

def get_item_lot_movements(lot_id: int, limit: int=200) -> List[Dict[str, Any]]:
    if not _table_exists(ITEM_LOT_MOVEMENT_TABLE):
        return []
    try:
        lid = int(lot_id)
        lim = max(1, min(1000, int(limit)))
    except (TypeError, ValueError):
        return []
    return _safe_rows(f'\n            SELECT * FROM (\n            SELECT MOV_ID AS mov_id, LOT_ID AS lot_id, QTY AS qty, KIND AS kind,\n                   REF_TYPE AS ref_type, REF_NO AS ref_no, REF_LINE AS ref_line, AT_TS AS at_ts\n            FROM {ITEM_LOT_MOVEMENT_TABLE}\n            WHERE LOT_ID = :lid\n            ORDER BY AT_TS DESC, MOV_ID DESC\n            ) WHERE ROWNUM <= {lim}\n            ', {'lid': lid}) or []

def get_item_lot_by_id(lot_id: int) -> Optional[Dict[str, Any]]:
    if not _table_exists(ITEM_LOT_TABLE):
        return None
    try:
        lid = int(lot_id)
    except (TypeError, ValueError):
        return None
    rows = _safe_rows(f'\n        SELECT l.LOT_ID AS lot_id, l.LOCATIONCODE AS locationcode, l.ITEMCODE AS itemcode,\n               l.BATCH_NO AS batch_no, l.MFG_DATE AS mfg_date, l.EXPIRY_DATE AS expiry_date\n        FROM {ITEM_LOT_TABLE} l\n        WHERE l.LOT_ID = :id\n        ', {'id': lid})
    return rows[0] if rows else None

def get_item_lot_bin_breakdown(lot_id: int) -> List[Dict[str, Any]]:
    """Per-bin lot quantities (ITEM_LOT_BIN + WAREHOUSE_STORAGE label)."""
    if not _table_exists(ITEM_LOT_BIN_TABLE) or not _table_exists(WAREHOUSE_STORAGE_TABLE):
        return []
    try:
        lid = int(lot_id)
    except (TypeError, ValueError):
        return []
    return _safe_rows(f'\n            SELECT b.STORAGE_ID AS storage_id, NVL(b.QTY, 0) AS qty,\n                   w.CODE AS storage_code, w.NAME AS storage_name, w.STORAGE_TYPE AS storage_type\n            FROM {ITEM_LOT_BIN_TABLE} b\n            JOIN {WAREHOUSE_STORAGE_TABLE} w ON w.STORAGE_ID = b.STORAGE_ID\n            WHERE b.LOT_ID = :lid AND NVL(b.QTY, 0) > 0.0001\n            ORDER BY w.CODE, w.STORAGE_ID\n            ', {'lid': lid}) or []

def get_item_lot_bin_shelf_stock_grid(location_code: int, itemcode: Optional[int]=None, search: Optional[str]=None, wh_loc_key: Optional[str]=None, db_key: Optional[str]=None, *, include_zero_qty: bool=False) -> List[Dict[str, Any]]:
    """
    One row per lot × bin with bin/shelf (parent) labels for branch batch stock view.
    """
    if not ensure_item_lot_tables():
        return []
    if not _table_exists(ITEM_LOT_TABLE) or not _table_exists(ITEM_LOT_BIN_TABLE):
        return []
    if not _table_exists(WAREHOUSE_STORAGE_TABLE):
        return []
    try:
        loc = int(location_code)
    except (TypeError, ValueError):
        return []
    ws_cols = {c.upper() for c in _get_table_columns(WAREHOUSE_STORAGE_TABLE) or []}
    has_parent = 'PARENT_STORAGE_ID' in ws_cols
    has_loc_key = 'LOC_KEY' in ws_cols
    if has_parent:
        pr_join = f'LEFT JOIN {WAREHOUSE_STORAGE_TABLE} pr ON pr.STORAGE_ID = w.PARENT_STORAGE_ID'
        shelf_fields = 'pr.CODE AS shelf_code, pr.NAME AS shelf_name'
    else:
        pr_join = ''
        shelf_fields = 'CAST(NULL AS VARCHAR2(80)) AS shelf_code, CAST(NULL AS VARCHAR2(200)) AS shelf_name'
    p: Dict[str, Any] = {'loc': loc}
    qty_filt = '1=1' if include_zero_qty else 'NVL(b.QTY, 0) > 0.0001'
    filt: List[str] = ['l.LOCATIONCODE = :loc', qty_filt]
    if itemcode is not None:
        try:
            ic = int(itemcode)
        except (TypeError, ValueError):
            ic = 0
        if ic > 0:
            filt.append('l.ITEMCODE = :ic')
            p['ic'] = ic
    sp = (search or '').strip()
    if sp:
        filt.append("(TO_CHAR(l.ITEMCODE) LIKE :sp OR UPPER(NVL(l.BATCH_NO,'')) LIKE UPPER(:sp2))")
        pat = f'%{sp}%'
        p['sp'] = pat
        p['sp2'] = pat
    if wh_loc_key and str(wh_loc_key).strip() and has_loc_key:
        filt.append('w.LOC_KEY = :whlk')
        p['whlk'] = str(wh_loc_key).strip()
    q = f"\n        SELECT l.LOT_ID AS lot_id, l.ITEMCODE AS itemcode, l.BATCH_NO AS batch_no,\n               l.EXPIRY_DATE AS expiry_date,\n               b.STORAGE_ID AS storage_id,\n               NVL(b.QTY, 0) AS qty,\n               w.CODE AS bin_code, w.NAME AS bin_name, w.STORAGE_TYPE AS storage_type,\n               {shelf_fields}\n        FROM {ITEM_LOT_TABLE} l\n        JOIN {ITEM_LOT_BIN_TABLE} b ON b.LOT_ID = l.LOT_ID\n        JOIN {WAREHOUSE_STORAGE_TABLE} w ON w.STORAGE_ID = b.STORAGE_ID\n        {pr_join}\n        WHERE {' AND '.join(filt)}\n        ORDER BY l.ITEMCODE, l.EXPIRY_DATE NULLS LAST, w.CODE, b.STORAGE_ID\n    "
    return _safe_rows(q, p, db_key=db_key) or []

def list_item_lots_for_qc_hold(location_code: int, search: Optional[str]=None, limit: int=400) -> List[Dict[str, Any]]:
    """Lots at a branch with on-hand qty and QC block flags (simple hold screen)."""
    if not ensure_item_lot_tables():
        return []
    if not _table_exists(ITEM_LOT_TABLE):
        return []
    try:
        loc = int(location_code)
    except (TypeError, ValueError):
        return []
    lim = max(20, min(2000, int(limit)))
    bin_sq = f'(SELECT NVL(SUM(x.QTY),0) FROM {ITEM_LOT_BIN_TABLE} x WHERE x.LOT_ID = l.LOT_ID)' if _table_exists(ITEM_LOT_BIN_TABLE) else '0'
    p: Dict[str, Any] = {'loc': loc}
    wsql = ['l.LOCATIONCODE = :loc', f'( NVL(b.QTY,0) + NVL({bin_sq},0) ) > 0.0001']
    sp = (search or '').strip()
    if sp:
        wsql.append("(TO_CHAR(l.ITEMCODE) LIKE :sp OR UPPER(NVL(l.BATCH_NO,'')) LIKE UPPER(:sp2))")
        pat = f'%{sp}%'
        p['sp'] = pat
        p['sp2'] = pat
    q = f"\n        SELECT * FROM (\n            SELECT l.LOT_ID AS lot_id, l.ITEMCODE AS itemcode, l.BATCH_NO AS batch_no,\n                   l.EXPIRY_DATE AS expiry_date,\n                   UPPER(NVL(TRIM(l.LOT_BLOCKED),'N')) AS lot_blocked,\n                   l.LOT_BLOCK_REMARKS AS lot_block_remarks,\n                   NVL(b.QTY,0) + NVL({bin_sq},0) AS qty\n            FROM {ITEM_LOT_TABLE} l\n            LEFT JOIN {ITEM_LOT_BALANCE_TABLE} b ON b.LOT_ID = l.LOT_ID\n            WHERE {' AND '.join(wsql)}\n            ORDER BY l.ITEMCODE, l.EXPIRY_DATE NULLS LAST, l.LOT_ID\n        ) WHERE ROWNUM <= {lim}\n    "
    return _safe_rows(q, p) or []

def set_item_lot_blocked_state(lot_id: int, blocked: bool, remarks: Optional[str]=None, location_code: Optional[int]=None) -> Tuple[bool, Optional[str]]:
    """Set ITEM_LOT.LOT_BLOCKED / LOT_BLOCK_REMARKS (QC hold)."""
    if not ensure_item_lot_tables():
        return (False, 'Batch/lot tables not available.')
    try:
        lid = int(lot_id)
    except (TypeError, ValueError):
        return (False, 'Invalid lot id.')
    flag = 'Y' if blocked else 'N'
    rm = (remarks or '').strip()[:500] or None
    p: Dict[str, Any] = {'lid': lid, 'flg': flag, 'rm': rm}
    loc_sql = ''
    if location_code is not None:
        try:
            p['lc'] = int(location_code)
            loc_sql = ' AND LOCATIONCODE = :lc'
        except (TypeError, ValueError):
            pass
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f'\n                    UPDATE {ITEM_LOT_TABLE}\n                    SET LOT_BLOCKED = :flg, LOT_BLOCK_REMARKS = :rm\n                    WHERE LOT_ID = :lid\n                    {loc_sql}\n                    ', p)
                if cur.rowcount == 0:
                    return (False, 'Lot not found or not in this branch.')
            conn.commit()
    except Exception as e:
        return (False, str(e))
    return (True, None)

def item_lot_putaway_to_bin_cur(cur: Any, loc_key: str, lot_id: int, storage_id: int, qty: float, location_code: int, updated_by: str='') -> Optional[str]:
    """
    Move quantity from unallocated lot balance to ITEM_LOT_BIN and align BIN_STOCK
    (same item + bin) in the current transaction.
    """
    if not ensure_item_lot_tables() or not _table_exists(ITEM_LOT_BIN_TABLE):
        return 'Lot / bin tables are not available.'
    if not ensure_bin_stock_tables():
        return 'Bin stock tables are not available.'
    try:
        qv = float(qty)
        lid = int(lot_id)
        sid = int(storage_id)
        loc = int(location_code)
    except (TypeError, ValueError):
        return 'Invalid lot, storage, quantity, or location.'
    if qv < 1e-09:
        return 'Quantity must be greater than zero.'
    row, err = _validate_bin_for_site(loc_key, sid, loc)
    if not row:
        return err or 'Invalid bin.'
    scope = _bin_stock_scope_for_site(row, loc_key)
    user_s = (updated_by or '').strip()[:200] or None
    bs_cols = {c.upper() for c in (_get_table_columns(BIN_STOCK_TABLE) or [])}
    cur.execute(f'\n        SELECT LOT_ID, ITEMCODE, LOCATIONCODE\n        FROM {ITEM_LOT_TABLE} WHERE LOT_ID = :id\n        ', {'id': lid})
    lr = cur.fetchone()
    if not lr:
        return f'Lot {lid} not found.'
    if int(lr[2] or 0) != loc:
        return 'Lot does not belong to this store location.'
    itemcode = int(lr[1] or 0)
    if itemcode <= 0:
        return 'Invalid item on lot.'
    it = get_item_by_code(itemcode, loc)
    if not it:
        return f'Item {itemcode} is not available for this location.'
    cur.execute(f'SELECT NVL(QTY,0) FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :id FOR UPDATE', {'id': lid})
    br = cur.fetchone()
    bbal = float(br[0] or 0) if br else 0.0
    if bbal + 1e-09 < qv:
        return f'Insufficient unallocated lot balance ({bbal:.4f} available).'
    new_b = bbal - qv
    if new_b < 1e-09 and br:
        cur.execute(f'DELETE FROM {ITEM_LOT_BALANCE_TABLE} WHERE LOT_ID = :id', {'id': lid})
    elif br:
        cur.execute(f'UPDATE {ITEM_LOT_BALANCE_TABLE} SET QTY = :q WHERE LOT_ID = :id', {'q': new_b, 'id': lid})
    else:
        return 'Lot has no unallocated balance row to put away from.'
    cur.execute(f'SELECT QTY FROM {ITEM_LOT_BIN_TABLE} WHERE LOT_ID = :lid AND STORAGE_ID = :sid FOR UPDATE', {'lid': lid, 'sid': sid})
    ex = cur.fetchone()
    if ex:
        nqb = float(ex[0] or 0) + qv
        cur.execute(f'\n            UPDATE {ITEM_LOT_BIN_TABLE} SET QTY = :q\n            WHERE LOT_ID = :lid AND STORAGE_ID = :sid\n            ', {'q': nqb, 'lid': lid, 'sid': sid})
    else:
        cur.execute(f'\n            INSERT INTO {ITEM_LOT_BIN_TABLE} (LOT_ID, STORAGE_ID, QTY)\n            VALUES (:lid, :sid, :q)\n            ', {'lid': lid, 'sid': sid, 'q': qv})
    _item_lot_insert_movement_cur(cur, lid, -abs(qv), 'OUT', 'PUTAWAY', int(sid), int(lid), 'To bin (putaway)')
    cur.execute(f'SELECT QTY FROM {BIN_STOCK_TABLE} WHERE STORAGE_ID = :s AND ITEMCODE = :i FOR UPDATE', {'s': sid, 'i': itemcode})
    r1 = cur.fetchone()
    cur_qty = float(r1[0]) if r1 and r1[0] is not None else 0.0
    new_q = cur_qty + qv
    if new_q < 1e-09:
        return 'Bin stock merge produced invalid state.'
    if 'WAREHOUSE_ID' in bs_cols and scope.get('warehouse_id'):
        _cursor_execute_named(cur, f"""
            MERGE INTO {BIN_STOCK_TABLE} b
            USING (SELECT :s AS sid, :i AS itemcode, :q AS qty, :wid AS warehouse_id, :u AS uby FROM DUAL) x
            ON (b.STORAGE_ID = x.sid AND b.ITEMCODE = x.itemcode)
            WHEN MATCHED THEN UPDATE SET
                b.QTY = x.qty, b.UPDATED_AT = SYSTIMESTAMP, b.UPDATED_BY = x.uby, b.WAREHOUSE_ID = x.warehouse_id
            WHEN NOT MATCHED THEN INSERT (STORAGE_ID, ITEMCODE, QTY, WAREHOUSE_ID, UPDATED_AT, UPDATED_BY)
            VALUES (x.sid, x.itemcode, x.qty, x.warehouse_id, SYSTIMESTAMP, x.uby)
        """, {'s': sid, 'i': itemcode, 'q': new_q, 'wid': int(scope['warehouse_id']), 'u': user_s})
    else:
        wh_lk = _warehouse_row_site_key(row) or _warehouse_normalize_loc_key(loc_key)
        _cursor_execute_named(cur, f"""
            MERGE INTO {BIN_STOCK_TABLE} b
            USING (SELECT :s AS sid, :i AS itemcode, :q AS qty, :lk AS loc_key, :u AS uby FROM DUAL) x
            ON (b.STORAGE_ID = x.sid AND b.ITEMCODE = x.itemcode)
            WHEN MATCHED THEN UPDATE SET
                b.QTY = x.qty, b.UPDATED_AT = SYSTIMESTAMP, b.UPDATED_BY = x.uby, b.LOC_KEY = x.loc_key
            WHEN NOT MATCHED THEN INSERT (STORAGE_ID, ITEMCODE, QTY, LOC_KEY, UPDATED_AT, UPDATED_BY)
            VALUES (x.sid, x.itemcode, x.qty, x.loc_key, SYSTIMESTAMP, x.uby)
        """, {'s': sid, 'i': itemcode, 'q': new_q, 'lk': (wh_lk or '')[:120], 'u': user_s})
    return None

def item_lot_putaway_to_bin(loc_key: str, lot_id: int, storage_id: int, qty: float, location_code: int, updated_by: str='') -> Tuple[bool, str]:
    """Post putaway: unallocated lot → bin (ITEM_LOT_BIN + BIN_STOCK)."""
    err: Optional[str] = None
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                err = item_lot_putaway_to_bin_cur(cur, loc_key, lot_id, storage_id, qty, location_code, updated_by=updated_by)
                if err:
                    conn.rollback()
                    return (False, err)
            conn.commit()
        return (True, '')
    except Exception as e:
        return (False, str(e))

def get_item_properties() -> List[Dict[str, Any]]:
    """Get item properties from TBLITEMPROPERTY."""
    tbl = _detect_table(['TBLITEMPROPERTY', 'tblitemproperty', 'TBL_ITEM_PROPERTY'])
    if not tbl:
        return []
    code_col = _detect_column(tbl, ['PROPERTYCODE', 'PROPERTY_CODE', 'CODE', 'ID', 'PROPERTYID', 'PROPERTY_ID'])
    name_col = _detect_column(tbl, ['PROPERTYNAME', 'PROPERTY_NAME', 'NAME', 'DESCRIPTION', 'DESC'])
    if not code_col:
        return []
    name_expr = name_col if name_col else 'TO_CHAR(' + code_col + ')'
    query = f'\n        SELECT {code_col} AS code, {name_expr} AS name\n        FROM {tbl}\n        WHERE {code_col} IS NOT NULL\n        ORDER BY {code_col}\n    '
    try:
        _, rows = _fetch_rows(query, {})
        return rows
    except Exception:
        return []

def get_item_property_lookup_display(code: Any) -> str:
    """Single TBLITEMPROPERTY row as ``CODE - NAME`` (no full-table scan)."""
    if code is None or str(code).strip() in ('', 'None', '0'):
        return ''
    tbl, code_col, name_col = _item_property_table_parts()
    if not tbl or not code_col:
        return str(code).strip()
    name_expr = name_col if name_col else f'TO_CHAR({code_col})'
    try:
        cval: Any = int(float(str(code).strip()))
    except (TypeError, ValueError):
        cval = code
    rows = _safe_rows(f'SELECT {code_col} AS code, {name_expr} AS name FROM {tbl} WHERE {code_col} = :c AND ROWNUM <= 1', {'c': cval}) or []
    if not rows:
        return str(code).strip()
    rc = rows[0].get('code')
    nm = (str(rows[0].get('name') or '')).strip()
    base = str(rc).strip() if rc is not None else str(code).strip()
    return f'{base} - {nm}'.strip(' -') if nm else base

