def insert_item_property_row(name: str) -> Tuple[bool, str, Optional[Any]]:
    """Insert a row in TBLITEMPROPERTY (or detected alias). Code = MAX+1."""
    tbl, code_col, name_col = _item_property_table_parts()
    if not tbl or not code_col or (not name_col):
        return (False, 'Property table (TBLITEMPROPERTY) not found', None)
    name_u = (name or '').strip().upper()
    if not name_u:
        return (False, 'Name is required', None)
    try:
        rows = _safe_rows(f'SELECT NVL(MAX({code_col}), 0) + 1 AS n FROM {tbl}', {})
        nxt = int(rows[0].get('n') or 1) if rows else 1
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f'INSERT INTO {tbl} ({code_col}, {name_col}) VALUES (:c, :n)', {'c': nxt, 'n': name_u})
            conn.commit()
        return (True, '', nxt)
    except Exception as e:
        return (False, str(e), None)

def update_item_property_row(code: Any, name: str) -> Tuple[bool, str]:
    tbl, code_col, name_col = _item_property_table_parts()
    if not tbl or not code_col or (not name_col):
        return (False, 'Property table (TBLITEMPROPERTY) not found')
    name_u = (name or '').strip().upper()
    if not name_u:
        return (False, 'Name is required')
    try:
        cval: Any = int(code) if str(code).strip().lstrip('-').isdigit() else code
    except (TypeError, ValueError):
        cval = code
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f'UPDATE {tbl} SET {name_col} = :n WHERE {code_col} = :c', {'n': name_u, 'c': cval})
                if cur.rowcount == 0:
                    conn.rollback()
                    return (False, 'No row updated')
            conn.commit()
        return (True, '')
    except Exception as e:
        return (False, str(e))

