_ITEMMASTER_DETAIL_VIEW_TENANT_QUERY_ERR_LOGGED: Set[str] = set()
_ITEMMASTER_DETAIL_SELECT_CACHE: Tuple[Optional[frozenset], Optional[str]] = (None, None)

def _invalidate_itemmaster_detail_select_cache() -> None:
    global _ITEMMASTER_DETAIL_SELECT_CACHE
    _ITEMMASTER_DETAIL_SELECT_CACHE = (None, None)


def _resolve_itemmaster_detail_select_sql() -> str:
    """Cached ITEMMASTER detail SELECT matching this database's columns."""
    global _ITEMMASTER_DETAIL_SELECT_CACHE
    _ensure_im_inv_ext_cols_once()
    imx = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER']) or 'ITEMMASTER'
    icols = frozenset(str(c).upper() for c in (_get_table_columns(imx) or []))
    cached_key, cached_sql = _ITEMMASTER_DETAIL_SELECT_CACHE
    if cached_key == icols and cached_sql:
        return cached_sql
    sql = build_itemmaster_detail_select_sql(set(icols))
    _ITEMMASTER_DETAIL_SELECT_CACHE = (icols, sql)
    return sql

def _itemmaster_detail_fetch_dict(item_code: int, location_code: int, *, tenant_id: Optional[str]) -> Optional[Dict[str, Any]]:
    """One row from embedded ITEMMASTER detail SELECT (LBL_* joins), lowercase keys, or None."""
    global _ITEMMASTER_DETAIL_VIEW_QUERY_ERR_LOGGED
    try:
        ic = int(item_code)
        lc = int(location_code)
    except (TypeError, ValueError):
        return None
    q = _resolve_itemmaster_detail_select_sql().strip() + '\nWHERE im.ITEMCODE = :ic AND im.LOCATIONCODE = :lc'
    p = {'ic': ic, 'lc': lc}
    try:
        if tenant_id:
            tid = (tenant_id or '').strip()
            if not tid:
                return None
            with _get_tenant_connection(tid) as conn:
                with conn.cursor() as cur:
                    cur.execute(q, p)
                    cols = [c[0].lower() for c in cur.description or []]
                    row = cur.fetchone()
                    if not row:
                        return None
                    return {cols[i]: _materialize_db_value(row[i]) for i in range(len(cols))}
        rows = _safe_rows(q, p)
        if not rows:
            return None
        return dict(rows[0])
    except Exception as e:
        if tenant_id:
            tkey = (tenant_id or '').strip()
            if tkey and tkey not in _ITEMMASTER_DETAIL_VIEW_TENANT_QUERY_ERR_LOGGED:
                _ITEMMASTER_DETAIL_VIEW_TENANT_QUERY_ERR_LOGGED.add(tkey)
                print(f'[itemmaster] embedded ITEMMASTER detail SELECT failed for tenant={tkey!r}: {e}')
        else:
            if not _ITEMMASTER_DETAIL_VIEW_QUERY_ERR_LOGGED:
                _ITEMMASTER_DETAIL_VIEW_QUERY_ERR_LOGGED = True
                print(f'[try_get_itemmaster_detail_view] embedded ITEMMASTER detail SELECT failed: {e}')
        return None

def _itemmaster_detail_view_finalize_row(row: Dict[str, Any]) -> Tuple[Dict[str, Any], Dict[str, str]]:
    row = dict(row)
    lbl_to_key: Dict[str, str] = {
        'lbl_main_category': 'main_category',
        'lbl_department': 'department',
        'lbl_category': 'category',
        'lbl_brand': 'brand',
        'lbl_size': 'size',
        'lbl_color': 'color',
        'lbl_supplier': 'supplier',
        'lbl_base_uom': 'base_uom',
        'lbl_ministry_unit': 'ministry_unit',
        'lbl_property': 'property',
        'lbl_origin': 'origin',
        'lbl_sales_account': 'sales_account',
        'lbl_purchase_account': 'purchase_account',
        'lbl_inventory_account': 'inventory_account',
        'lbl_cogs_account': 'cogs_account',
        'lbl_alternate_uom': 'alternate_uom',
    }
    labels: Dict[str, str] = {}
    for lk, dk in lbl_to_key.items():
        if lk in row and row.get(lk) is not None:
            txt = str(row.get(lk) or '').strip()
            if txt:
                labels[dk] = txt
        row.pop(lk, None)
    row['itemnameara'] = _fix_mojibake(row.get('itemnameara'))
    row['display_item_name'] = _display_item_name_prefer_arabic(row.get('itemname'), row.get('itemnameara'))
    row['batch_tracked'] = str(row.get('batch_tracked') or 'N').strip()[:1] or 'N'
    vwh = row.get('default_warehouse_id')
    if vwh is None:
        vwh = row.get('DEFAULT_WAREHOUSE_ID')
    if vwh is not None and str(vwh).strip() != '':
        try:
            row['default_warehouse_id'] = int(float(vwh))
        except (TypeError, ValueError):
            row['default_warehouse_id'] = None
    else:
        row['default_warehouse_id'] = None
    row.pop('DEFAULT_WAREHOUSE_ID', None)
    for bid in ('default_bin_storage_id', 'staging_bin_storage_id'):
        if bid not in row:
            continue
        v = row.get(bid)
        if v is not None and str(v).strip() != '':
            try:
                row[bid] = int(float(v))
            except (TypeError, ValueError):
                row[bid] = None
        else:
            row[bid] = None
    return (row, labels)

def try_get_itemmaster_detail_view_for_tenant(tenant_id: str, item_code: int, location_code: int) -> Optional[Tuple[Dict[str, Any], Dict[str, str]]]:
    """Same as :func:`try_get_itemmaster_detail_view` but against the given tenant PDB/schema."""
    raw = _itemmaster_detail_fetch_dict(item_code, location_code, tenant_id=(tenant_id or '').strip())
    if not raw:
        return None
    return _itemmaster_detail_view_finalize_row(raw)

def try_get_itemmaster_detail_view(item_code: int, location_code: int) -> Optional[Tuple[Dict[str, Any], Dict[str, str]]]:
    """
    One-round-trip load for Item Master read-only: embedded Oracle SELECT matching ``ITEMMASTER_DETAIL_V``
    (ITEMMASTER rows plus ``LBL_*`` display columns). No database view required.
    Returns ``(item_row, im_view_labels)`` or None if no row / Oracle error.
    """
    raw = _itemmaster_detail_fetch_dict(item_code, location_code, tenant_id=None)
    if not raw:
        return None
    return _itemmaster_detail_view_finalize_row(raw)

def _ensure_im_inv_ext_cols_once() -> None:
    """Ensure batch/bin columns exist; at most once per process (and once per request)."""
    if _IM_INV_EXT_COLS_ENSURED_PROCESS:
        return
    try:
        from nexa_http import g, has_request_context
        if has_request_context():
            if getattr(g, '_im_inv_ext_cols_ensured', False):
                return
            ensure_itemmaster_inventory_extension_columns()
            g._im_inv_ext_cols_ensured = True
            return
    except Exception:
        pass
    try:
        ensure_itemmaster_inventory_extension_columns()
    except Exception:
        pass

def get_item_by_code(item_code: int, location_code: int) -> Optional[Dict[str, Any]]:
    """Get item details by item code (single round-trip; optional store/bin columns included)."""
    _ensure_im_inv_ext_cols_once()
    imx = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER']) or 'ITEMMASTER'
    icols = {str(c).upper() for c in _get_table_columns(imx) or []}
    ic_col = _detect_column(imx, ['ITEMCODE', 'ITEM_CODE', 'itemcode']) or 'ITEMCODE'
    lc_col = _detect_column(imx, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode']) or 'LOCATIONCODE'
    extras: List[str] = []
    if 'DEFAULT_WAREHOUSE_ID' in icols:
        extras.append('im.DEFAULT_WAREHOUSE_ID AS default_warehouse_id')
    else:
        extras.append('CAST(NULL AS NUMBER) AS default_warehouse_id')
    if 'BATCH_TRACKED' in icols:
        extras.append(f"NVL(im.BATCH_TRACKED, 'N') AS batch_tracked")
    else:
        extras.append("'N' AS batch_tracked")
    if 'IS_WEIGHT_ITEM' in icols:
        extras.append(f"NVL(im.IS_WEIGHT_ITEM, 'N') AS is_weight_item")
    else:
        extras.append("'N' AS is_weight_item")
    if 'DEFAULT_BIN_STORAGE_ID' in icols:
        extras.append('im.DEFAULT_BIN_STORAGE_ID AS default_bin_storage_id')
    else:
        extras.append('CAST(NULL AS NUMBER) AS default_bin_storage_id')
    if 'STAGING_BIN_STORAGE_ID' in icols:
        extras.append('im.STAGING_BIN_STORAGE_ID AS staging_bin_storage_id')
    else:
        extras.append('CAST(NULL AS NUMBER) AS staging_bin_storage_id')
    if 'IMAGE_PATH' in icols:
        extras.append('im.IMAGE_PATH AS image_path')
    else:
        extras.append("CAST(NULL AS VARCHAR2(500)) AS image_path")
    if 'AVERAGECOST' in icols:
        extras.append('im.AVERAGECOST AS averagecost')
    else:
        extras.append('0 AS averagecost')
    if 'LANDINGCOST' in icols:
        extras.append('im.LANDINGCOST AS landingcost')
    else:
        extras.append('0 AS landingcost')
    extra_sql = ',\n            '.join(extras)
    from .itemmaster_core import _itemmaster_stock_qty_sql
    stock_sql = _itemmaster_stock_qty_sql(icols, table_alias='im') + ' AS CURRENTSTOCK'
    dept_sql = (
        """NVL(
                (SELECT CODE FROM CATEGORY WHERE CODE = im.DEPARTMENTCODE AND FLAG = 'D'),
                im.DEPARTMENTCODE
            ) AS DEPARTMENTCODE"""
        if 'DEPARTMENTCODE' in icols
        else 'CAST(NULL AS NUMBER) AS DEPARTMENTCODE'
    )
    cat_sql = (
        """NVL(
                (SELECT CODE FROM CATEGORY WHERE CODE = im.CATEGORYCODE AND FLAG = 'C'),
                im.CATEGORYCODE
            ) AS CATEGORYCODE"""
        if 'CATEGORYCODE' in icols
        else 'CAST(NULL AS NUMBER) AS CATEGORYCODE'
    )
    cat_name_sql = (
        "(SELECT NVL(MAX(cat.NAME), '') FROM CATEGORY cat WHERE cat.CODE = im.CATEGORYCODE AND cat.FLAG = 'C') AS CATEGORYNAME"
        if 'CATEGORYCODE' in icols
        else "CAST(NULL AS VARCHAR2(200)) AS CATEGORYNAME"
    )
    def _ic(name: str, null: str) -> str:
        return f'im.{name}' if name in icols else null
    query = f"""
        SELECT
            im.{ic_col} AS ITEMCODE,
            {_ic('RAWABICODE', 'CAST(NULL AS VARCHAR2(50)) AS RAWABICODE')},
            {_ic('ITEMNAME', 'CAST(NULL AS VARCHAR2(500)) AS ITEMNAME')},
            {_ic('MANUFACTURERID', 'CAST(NULL AS VARCHAR2(50)) AS MANUFACTURERID')},
            {_ic('BRANDCODE', 'CAST(NULL AS NUMBER) AS BRANDCODE')},
            {_ic('SIZECODE', 'CAST(NULL AS NUMBER) AS SIZECODE')},
            {_ic('COLORCODE', 'CAST(NULL AS NUMBER) AS COLORCODE')},
            {_ic('BASEUOM', "CAST(NULL AS VARCHAR2(20)) AS BASEUOM")},
            {_ic('COSTPRICE', 'CAST(NULL AS NUMBER) AS COSTPRICE')},
            {_ic('RETAILPRICE', 'CAST(NULL AS NUMBER) AS RETAILPRICE')},
            {_ic('WHOLESALEPRICE', 'CAST(NULL AS NUMBER) AS WHOLESALEPRICE')},
            {_ic('THIRDPRICE', 'CAST(NULL AS NUMBER) AS THIRDPRICE')},
            {_ic('BRANCHPRICE', 'CAST(NULL AS NUMBER) AS BRANCHPRICE')},
            {_ic('MAXIMUMLEVEL', 'CAST(NULL AS NUMBER) AS MAXIMUMLEVEL')},
            {_ic('REORDERLEVEL', 'CAST(NULL AS NUMBER) AS REORDERLEVEL')},
            {stock_sql},
            {_ic('DISCOUNTFLAG', "CAST(NULL AS VARCHAR2(1)) AS DISCOUNTFLAG")},
            {_ic('COMPANYCODE', 'CAST(NULL AS NUMBER) AS COMPANYCODE')},
            {_ic('SUPCODE', 'CAST(NULL AS NUMBER) AS SUPCODE')},
            {_ic('MAINCATEGORY', 'CAST(NULL AS NUMBER) AS MAINCATEGORY')},
            {_ic('REBATE', 'CAST(NULL AS NUMBER) AS REBATE')},
            {_ic('ITEMNAMEARA', 'CAST(NULL AS VARCHAR2(500)) AS ITEMNAMEARA')},
            {_ic('DESCRIPTION', 'CAST(NULL AS VARCHAR2(500)) AS DESCRIPTION')},
            {_ic('PROPERTY', 'CAST(NULL AS NUMBER) AS PROPERTY')},
            {_ic('ORIGIN', 'CAST(NULL AS NUMBER) AS ORIGIN')},
            {_ic('QUANTITYLIMIT', 'CAST(NULL AS NUMBER) AS QUANTITYLIMIT')},
            {_ic('PACKING', 'CAST(NULL AS VARCHAR2(50)) AS PACKING')},
            {_ic('MINISTRYFACTOR', 'CAST(NULL AS NUMBER) AS MINISTRYFACTOR')},
            {_ic('MINISTRYUNIT', "CAST(NULL AS VARCHAR2(20)) AS MINISTRYUNIT")},
            {_ic('VATPERCENT', 'CAST(NULL AS NUMBER) AS VATPERCENT')},
            {'im.SALESACCOUNT AS SALES_ACCOUNT' if 'SALESACCOUNT' in icols else 'CAST(NULL AS VARCHAR2(30)) AS SALES_ACCOUNT'},
            {'im.PURCHASEACCOUNT AS PURCHASE_ACCOUNT' if 'PURCHASEACCOUNT' in icols else 'CAST(NULL AS VARCHAR2(30)) AS PURCHASE_ACCOUNT'},
            {'im.INVENTORYACCOUNT AS INVENTORY_ACCOUNT' if 'INVENTORYACCOUNT' in icols else 'CAST(NULL AS VARCHAR2(30)) AS INVENTORY_ACCOUNT'},
            {'im.COGSACCOUNT AS COGS_ACCOUNT' if 'COGSACCOUNT' in icols else 'CAST(NULL AS VARCHAR2(30)) AS COGS_ACCOUNT'},
            {_ic('ITEMFLAG', "CAST(NULL AS VARCHAR2(1)) AS ITEMFLAG")},
            {extra_sql},
            {dept_sql},
            {cat_sql},
            {cat_name_sql}
        FROM {imx} im
        WHERE im.{ic_col} = :item_code
        AND im.{lc_col} = :location_code
    """
    try:
        _, rows = _fetch_rows(query, {'item_code': item_code, 'location_code': location_code})
        if rows:
            if 'ITEMNAMEARA' in icols:
                ara_q = f'SELECT im.ITEMNAMEARA AS itemnameara FROM {imx} im WHERE im.{ic_col} = :item_code AND im.{lc_col} = :location_code'
                try:
                    ara_rows = _fetch_rows_itemnameara_only(None, ara_q, {'item_code': item_code, 'location_code': location_code}, nls_lang=(os.environ.get('NLS_LANG') or 'AMERICAN_AMERICA.UTF8').strip() or 'AMERICAN_AMERICA.UTF8')
                    if ara_rows and ara_rows[0].get('itemnameara') is not None:
                        rows[0]['itemnameara'] = _fix_mojibake(ara_rows[0].get('itemnameara'))
                except Exception:
                    rows[0]['itemnameara'] = _fix_mojibake(rows[0].get('itemnameara'))
            else:
                rows[0]['itemnameara'] = _fix_mojibake(rows[0].get('itemnameara'))
            rows[0]['display_item_name'] = _display_item_name_prefer_arabic(rows[0].get('itemname'), rows[0].get('itemnameara'))
            rows[0]['batch_tracked'] = str(rows[0].get('batch_tracked') or 'N').strip()[:1] or 'N'
            v = rows[0].get('default_bin_storage_id')
            if v is not None and str(v).strip() != '':
                try:
                    rows[0]['default_bin_storage_id'] = int(float(v))
                except (TypeError, ValueError):
                    rows[0]['default_bin_storage_id'] = None
            else:
                rows[0]['default_bin_storage_id'] = None
            v3 = rows[0].get('staging_bin_storage_id')
            if v3 is not None and str(v3).strip() != '':
                try:
                    rows[0]['staging_bin_storage_id'] = int(float(v3))
                except (TypeError, ValueError):
                    rows[0]['staging_bin_storage_id'] = None
            else:
                rows[0]['staging_bin_storage_id'] = None
            vwh = rows[0].get('default_warehouse_id')
            if vwh is not None and str(vwh).strip() != '':
                try:
                    rows[0]['default_warehouse_id'] = int(float(vwh))
                except (TypeError, ValueError):
                    rows[0]['default_warehouse_id'] = None
            else:
                rows[0]['default_warehouse_id'] = None
            return rows[0]
        return None
    except Exception:
        return None

def get_item_by_code_anywhere(item_code: int) -> Optional[Dict[str, Any]]:
    """Get item details by item code without location filter"""
    query = '\n        SELECT *\n        FROM (\n            SELECT \n                ITEMCODE, RAWABICODE, ITEMNAME, CATEGORYCODE, MANUFACTURERID,\n                BRANDCODE, SIZECODE, COLORCODE, BASEUOM,\n                COSTPRICE, RETAILPRICE, WHOLESALEPRICE, THIRDPRICE, BRANCHPRICE,\n                MAXIMUMLEVEL, REORDERLEVEL, CURRENTSTOCK, DISCOUNTFLAG,\n                COMPANYCODE, SUPCODE, DEPARTMENTCODE,\n                MAINCATEGORY, REBATE, ITEMNAMEARA, DESCRIPTION,\n                PROPERTY, ORIGIN, QUANTITYLIMIT, PACKING,\n                MINISTRYFACTOR, MINISTRYUNIT, VATPERCENT,\n                SALESACCOUNT AS SALES_ACCOUNT,\n                PURCHASEACCOUNT AS PURCHASE_ACCOUNT,\n                INVENTORYACCOUNT AS INVENTORY_ACCOUNT,\n                COGSACCOUNT AS COGS_ACCOUNT,\n                ITEMFLAG,\n                LOCATIONCODE\n            FROM ITEMMASTER\n            WHERE ITEMCODE = :item_code\n            ORDER BY LOCATIONCODE\n        ) WHERE ROWNUM = 1\n    '
    try:
        _, rows = _fetch_rows(query, {'item_code': item_code})
        if rows:
            rows[0]['itemnameara'] = _fix_mojibake(rows[0].get('itemnameara'))
            rows[0]['display_item_name'] = _display_item_name_prefer_arabic(rows[0].get('itemname'), rows[0].get('itemnameara'))
            return rows[0]
        return None
    except Exception:
        return None

def get_item_by_manufacturer_id(manufacturer_id: str, location_code: int) -> Optional[Dict[str, Any]]:
    """Get item by manufacturer ID/barcode"""
    query = '\n        SELECT ITEMCODE\n        FROM ITEMMASTER\n        WHERE MANUFACTURERID = :manufacturer_id\n        AND LOCATIONCODE = :location_code\n    '
    try:
        _, rows = _fetch_rows(query, {'manufacturer_id': manufacturer_id, 'location_code': location_code})
        if rows:
            item_code = rows[0].get('itemcode')
            return get_item_by_code(item_code, location_code)
        return None
    except Exception:
        return None

def get_item_by_alternate_barcode(manufacturer_id: str, location_code: int) -> Optional[Dict[str, Any]]:
    """Get item by alternate barcode from ITEMALTERNATEUOMMAP"""
    query = '\n        SELECT ITEMCODE\n        FROM ITEMALTERNATEUOMMAP\n        WHERE MANUFACTURERID = :manufacturer_id\n        AND LOCATIONCODE = :location_code\n    '
    try:
        _, rows = _fetch_rows(query, {'manufacturer_id': manufacturer_id, 'location_code': location_code})
        if rows:
            item_code = rows[0].get('itemcode')
            return get_item_by_code(item_code, location_code)
        return None
    except Exception:
        return None

def get_item_uom_pricing(location_code: int, item_code: int, uom_code: str, price_mode: str) -> Optional[Dict[str, Any]]:
    """Get pricing for base or alternate UOM"""
    uom_code = (uom_code or '').strip()
    price_mode = (price_mode or 'retail').strip().lower()
    if not uom_code:
        return None
    item = get_item_by_code(item_code, location_code)
    if not item:
        return None
    base_uom = (item.get('baseuom') or '').strip()
    base_prices = {'retail': item.get('retailprice'), 'wholesale': item.get('wholesaleprice'), 'third': item.get('thirdprice'), 'branch': item.get('branchprice')}
    selected_price = base_prices.get(price_mode) or item.get('retailprice') or 0
    if base_uom and base_uom.upper() == uom_code.upper():
        mid = item.get('manufacturerid')
        mid_s = '' if mid is None else str(mid).strip()
        item_cost = float(item.get('costprice') or 0)
        item_avg_cost = float(item.get('averagecost') or 0)
        return {'is_base': True, 'uom_code': base_uom, 'conversion_factor': 1, 'item_factor': 1, 'rate': float(selected_price or 0), 'cost_price': item_cost, 'costprice': item_cost, 'average_cost': item_avg_cost, 'averagecost': item_avg_cost, 'manufacturer_id': mid_s}
    query = '\n        SELECT\n            ALTERNATEUOMCODE,\n            MANUFACTURERID,\n            CONVERSIONFACTOR,\n            COSTPRICE,\n            RETAILPRICE,\n            WHOLESALEPRICE,\n            THIRDPRICE,\n            BRANCHPRICE\n        FROM ITEMALTERNATEUOMMAP\n        WHERE LOCATIONCODE = :location_code\n        AND ITEMCODE = :item_code\n        AND ALTERNATEUOMCODE = :alternate_uom_code\n    '
    params = {'location_code': location_code, 'item_code': item_code, 'alternate_uom_code': uom_code}
    try:
        _, rows = _fetch_rows(query, params)
        if not rows:
            return None
        alt = rows[0]
        alt_prices = {'retail': alt.get('retailprice'), 'wholesale': alt.get('wholesaleprice'), 'third': alt.get('thirdprice'), 'branch': alt.get('branchprice')}
        alt_price = alt_prices.get(price_mode) or alt.get('retailprice') or 0
        am = alt.get('manufacturerid')
        am_s = '' if am is None else str(am).strip()
        item_avg_cost = float(item.get('averagecost') or 0)
        item_cost = float(item.get('costprice') or 0)
        alt_cost = float(alt.get('costprice') or item_cost or 0)
        factor = float(alt.get('conversionfactor') or 1)
        return {'is_base': False, 'uom_code': alt.get('alternateuomcode'), 'conversion_factor': factor, 'item_factor': factor, 'rate': float(alt_price or 0), 'cost_price': alt_cost, 'costprice': item_cost, 'average_cost': item_avg_cost, 'averagecost': item_avg_cost, 'manufacturer_id': am_s}
    except Exception:
        return None

def _im_import_normalize_header_key(h: Any) -> str:
    s = str(h or '').strip()
    if s.startswith('\ufeff'):
        s = s[1:].strip()
    return s.lower().replace(' ', '_').replace('-', '_')

def _im_import_row_dict(raw: Dict[str, Any]) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    for k, v in (raw or {}).items():
        nk = _im_import_normalize_header_key(k)
        if nk:
            out[nk] = v
    return out

def _im_import_cell(d: Dict[str, Any], *keys: str) -> Any:
    for k in keys:
        if k in d:
            return d[k]
    return None

def _im_import_parse_action(v: Any) -> str:
    s = str(v or '').strip().upper()
    if s in ('UPDATE', 'U', 'EDIT'):
        return 'UPDATE'
    return 'CREATE'

def _itemmaster_import_row_exists(location_code: int, item_code: int) -> bool:
    try:
        rows = _safe_rows('SELECT 1 FROM ITEMMASTER WHERE LOCATIONCODE = :loc AND ITEMCODE = :ic', {'loc': int(location_code), 'ic': int(item_code)})
        return bool(rows)
    except Exception:
        return False


def _itemmaster_import_existing_keys_for_location(location_code: int) -> Set[Tuple[int, int]]:
    """(locationcode, itemcode) keys already in ITEMMASTER for bulk import checks."""
    out: Set[Tuple[int, int]] = set()
    try:
        loc = int(location_code)
        rows = _safe_rows(
            'SELECT ITEMCODE FROM ITEMMASTER WHERE LOCATIONCODE = :loc',
            {'loc': loc},
        )
        for r in rows or []:
            try:
                ic = int(r.get('itemcode') or 0)
            except (TypeError, ValueError):
                continue
            if ic > 0:
                out.add((loc, ic))
    except Exception:
        pass
    return out


def _itemmaster_import_next_code_for_location(
    location_code: int,
    *,
    next_code_cache: Dict[int, int],
    existing_keys: Set[Tuple[int, int]],
) -> int:
    """Allocate next ITEMCODE for a location (in-memory cache + existing set)."""
    loc = int(location_code)
    cached = next_code_cache.get(loc)
    if cached is None or cached <= 0:
        cached = int(get_next_item_code(loc))
    while (loc, cached) in existing_keys:
        cached += 1
    next_code_cache[loc] = cached + 1
    existing_keys.add((loc, cached))
    return cached

def itemmaster_excel_row_to_item_data(nf: Dict[str, Any], default_location_code: int, *, resolved_item_code: Optional[int]) -> Dict[str, Any]:
    """
    Build ``item_data`` dict for :func:`save_item` from a normalized Excel row (lowercase underscored keys).
    Pass ``resolved_item_code`` when CREATE auto-assigned code (overrides blank Excel code).
    """
    loc = _cm_import_parse_int(_im_import_cell(nf, 'location_code', 'locationcode'))
    loc_f = int(loc) if loc is not None else int(default_location_code)
    ic = _cm_import_parse_int(_im_import_cell(nf, 'item_code', 'itemcode', 'code'))
    if resolved_item_code is not None:
        ic_f = int(resolved_item_code)
    elif ic is not None:
        ic_f = int(ic)
    else:
        ic_f = 0
    nm = str(_im_import_cell(nf, 'item_name', 'itemname', 'name') or '').strip()

    def _gint(*keys: str, default: int=0) -> int:
        v = _im_import_cell(nf, *keys)
        x = _cm_import_parse_int(v)
        return int(x) if x is not None else default

    def _gtxt(*keys: str, default: str='') -> str:
        v = _im_import_cell(nf, *keys)
        return str(v).strip() if v is not None else default

    def _gflt(*keys: str, default: float=0.0) -> float:
        v = _im_import_cell(nf, *keys)
        if v is None or (isinstance(v, str) and (not str(v).strip())):
            return default
        try:
            return float(str(v).strip())
        except (TypeError, ValueError):
            return default

    def _gacct(*keys: str) -> Optional[int]:
        v = _im_import_cell(nf, *keys)
        if v is None or (isinstance(v, str) and (not str(v).strip())):
            return None
        x = _cm_import_parse_int(v)
        if x is None or int(x) <= 0:
            return None
        return int(x)

    ara_raw = _gtxt('item_name_ara', 'itemnameara', 'arabic_name')
    ara = _fix_mojibake(ara_raw) if ara_raw else ''
    wh_raw = _im_import_cell(nf, 'default_warehouse_id', 'warehouse_id', 'store', 'store_code', 'storecode')
    wh_id: Optional[int] = None
    if wh_raw is not None and str(wh_raw).strip() != '':
        try:
            wh_id = int(float(str(wh_raw).strip()))
        except (TypeError, ValueError):
            wh_id = resolve_warehouse_id(str(wh_raw).strip())
    if wh_id is None or wh_id <= 0:
        wh_id = resolve_warehouse_id_for_location_code(loc_f)
    data: Dict[str, Any] = {'location_code': loc_f, 'item_code': ic_f, 'item_name': nm, 'manufacturer_id': _gtxt('manufacturer_id', 'manufacturerid', 'mfr_id', 'barcode'), 'category_code': _gint('category_code', 'categorycode'), 'brand_code': _gint('brand_code', 'brandcode'), 'size_code': _gint('size_code', 'sizecode'), 'color_code': _gint('color_code', 'colorcode'), 'base_uom': _gtxt('base_uom', 'baseuom', 'uom'), 'cost_price': _gflt('cost_price', 'costprice', 'cost'), 'retail_price': _gflt('retail_price', 'retailprice', 'retail'), 'wholesale_price': _gflt('wholesale_price', 'wholesaleprice', 'wholesale'), 'third_price': _gflt('third_price', 'thirdprice'), 'branch_price': _gflt('branch_price', 'branchprice'), 'maximum_level': _gint('maximum_level', 'maximumlevel'), 'reorder_level': _gint('reorder_level', 'reorderlevel'), 'discount_flag': (_gtxt('discount_flag', 'discountflag') or 'N')[:1].upper() or 'N', 'company_code': _im_import_cell(nf, 'company_code', 'companycode'), 'sup_code': _gint('sup_code', 'supcode', 'supplier_code', 'suppliercode'), 'department_code': _gint('department_code', 'departmentcode'), 'main_category': _gint('main_category', 'maincategory'), 'rebate': _gflt('rebate'), 'item_name_ara': str(ara) if ara else '', 'description': _gtxt('description', 'descr'), 'property': _gint('property', 'property_code', 'propertycode'), 'origin': _gint('origin', 'origin_code', 'origincode'), 'quantity_limit': _gint('quantity_limit', 'quantitylimit'), 'packing': _gtxt('packing'), 'ministry_factor': _gflt('ministry_factor', 'ministryfactor'), 'ministry_unit': _gtxt('ministry_unit', 'ministryunit'), 'vat_percent': _gflt('vat_percent', 'vatpercent', 'vat'), 'sales_account': _gacct('sales_account', 'salesaccount'), 'purchase_account': _gacct('purchase_account', 'purchaseaccount'), 'inventory_account': _gacct('inventory_account', 'inventoryaccount'), 'cogs_account': _gacct('cogs_account', 'cogsaccount'), 'default_warehouse_id': wh_id}
    data['item_name'] = _clip_itemmaster_item_name(data['item_name'])
    return data

def import_itemmaster_from_excel_rows(
    location_code: int,
    rows: List[Dict[str, Any]],
    *,
    max_rows: int = 50000,
    row_offset: int = 0,
    row_limit: Optional[int] = None,
    import_state: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Bulk CREATE/UPDATE ITEMMASTER from Excel rows. Uses :func:`save_item` per row.

    After each successful save, upserts the base ITEMALTERNATEUOMMAP row (base UOM mirror).

    When ``row_limit`` is set, only processes ``rows[row_offset:row_offset + row_limit]`` (for batched HTTP).
    Pass ``import_state`` across batches to keep existence/next-code caches and running totals.
    """
    from db.itemmaster_core import (
        apply_itemmaster_account_defaults_to_item_data,
        ensure_itemalternateuommap_extension_columns,
        save_item as _save_item_im,
        sync_base_alternate_row_from_itemmaster_cur,
    )

    loc0 = int(location_code)
    state = import_state if isinstance(import_state, dict) else {}
    errors: List[str] = list(state.get('errors') or [])
    created = int(state.get('created') or 0)
    updated = int(state.get('updated') or 0)
    skipped = int(state.get('skipped') or 0)
    existing_raw = state.get('existing_keys') or []
    existing_keys: Set[Tuple[int, int]] = set()
    for pair in existing_raw:
        try:
            existing_keys.add((int(pair[0]), int(pair[1])))
        except (TypeError, ValueError, IndexError):
            continue
    if not existing_keys:
        existing_keys = _itemmaster_import_existing_keys_for_location(loc0)
    next_code_cache: Dict[int, int] = dict(state.get('next_code_cache') or {})
    locations_loaded: Set[int] = set(int(x) for x in (state.get('locations_loaded') or []) if x is not None)
    locations_loaded.add(loc0)

    def _ensure_loc_loaded(loc: int) -> None:
        loc_i = int(loc)
        if loc_i in locations_loaded:
            return
        existing_keys.update(_itemmaster_import_existing_keys_for_location(loc_i))
        locations_loaded.add(loc_i)

    slice_rows = (rows or [])[max(0, int(row_offset)):]
    if row_limit is not None:
        slice_rows = slice_rows[: max(0, int(row_limit))]
    sheet_row = int(state.get('sheet_row') or 1)
    processed_total = int(state.get('processed_total') or 0)
    processed_in_batch = 0
    commit_every = 75
    pending_since_commit = 0

    ensure_itemmaster_account_columns()
    ensure_itemalternateuommap_extension_columns()
    cols_cache: Dict[str, Set[str]] = {}

    def _import_save_item_and_sync_base(conn: Any, item_data: Dict[str, Any], *, is_new: bool) -> Any:
        saved_code = _save_item_im(item_data, is_new=is_new, conn=conn, item_cols_cache=cols_cache)
        sync_item = dict(item_data)
        sync_item['item_code'] = saved_code
        if not str(sync_item.get('manufacturer_id') or '').strip():
            sync_item['manufacturer_id'] = str(saved_code)
        with conn.cursor() as cur:
            sync_base_alternate_row_from_itemmaster_cur(cur, sync_item, auto_dedupe=False)
        return saved_code

    try:
        with _get_connection() as conn:
            for raw in slice_rows:
                sheet_row += 1
                if processed_total >= max_rows:
                    errors.append(f'Stopped after {max_rows} data rows.')
                    break
                nf = _im_import_row_dict(raw)
                if not nf:
                    continue
                if not any((v not in (None, '') and str(v).strip() != '' for v in nf.values())):
                    continue
                processed_total += 1
                processed_in_batch += 1
                act = _im_import_parse_action(_im_import_cell(nf, 'action', 'mode'))
                ic_excel = _cm_import_parse_int(_im_import_cell(nf, 'item_code', 'itemcode', 'code'))
                name = str(_im_import_cell(nf, 'item_name', 'itemname', 'name') or '').strip()
                if act == 'UPDATE':
                    if ic_excel is None or ic_excel <= 0:
                        errors.append(f'Row {sheet_row}: UPDATE requires Item_Code.')
                        continue
                    eff_loc = _cm_import_parse_int(_im_import_cell(nf, 'location_code', 'locationcode'))
                    row_loc = int(eff_loc) if eff_loc is not None else loc0
                    _ensure_loc_loaded(row_loc)
                    if not name:
                        errors.append(f'Row {sheet_row}: UPDATE requires Item_Name.')
                        continue
                    if (row_loc, int(ic_excel)) not in existing_keys:
                        errors.append(f'Row {sheet_row}: No item LOCATIONCODE={row_loc} ITEMCODE={ic_excel}.')
                        continue
                    item_data = itemmaster_excel_row_to_item_data(nf, loc0, resolved_item_code=int(ic_excel))
                    item_data['location_code'] = row_loc
                    item_data['item_code'] = int(ic_excel)
                    existing_row = get_item_by_code(int(ic_excel), row_loc)
                    apply_itemmaster_account_defaults_to_item_data(item_data, existing_row)
                    try:
                        _import_save_item_and_sync_base(conn, item_data, is_new=False)
                        updated += 1
                        pending_since_commit += 1
                        if pending_since_commit >= commit_every:
                            conn.commit()
                            pending_since_commit = 0
                    except Exception as exc:
                        errors.append(f'Row {sheet_row}: UPDATE failed: {exc}')
                    continue
                if not name:
                    errors.append(f'Row {sheet_row}: CREATE requires Item_Name.')
                    continue
                eff_loc = _cm_import_parse_int(_im_import_cell(nf, 'location_code', 'locationcode'))
                row_loc = int(eff_loc) if eff_loc is not None else loc0
                _ensure_loc_loaded(row_loc)
                resolved = None
                if ic_excel is not None and ic_excel > 0:
                    if (row_loc, int(ic_excel)) in existing_keys:
                        errors.append(f'Row {sheet_row}: Item code {ic_excel} already exists — use UPDATE or leave code blank.')
                        skipped += 1
                        continue
                    resolved = int(ic_excel)
                    existing_keys.add((row_loc, resolved))
                else:
                    resolved = _itemmaster_import_next_code_for_location(
                        row_loc, next_code_cache=next_code_cache, existing_keys=existing_keys,
                    )
                item_data = itemmaster_excel_row_to_item_data(nf, loc0, resolved_item_code=resolved)
                item_data['location_code'] = row_loc
                item_data['item_code'] = int(resolved)
                apply_itemmaster_account_defaults_to_item_data(item_data)
                try:
                    _import_save_item_and_sync_base(conn, item_data, is_new=True)
                    created += 1
                    pending_since_commit += 1
                except Exception as exc:
                    errors.append(f'Row {sheet_row}: CREATE failed: {exc}')
                if pending_since_commit >= commit_every:
                    conn.commit()
                    pending_since_commit = 0
            if pending_since_commit:
                conn.commit()
    except Exception as exc:
        errors.append(f'Import aborted: {exc}')

    state['errors'] = errors
    state['created'] = created
    state['updated'] = updated
    state['skipped'] = skipped
    state['existing_keys'] = list(existing_keys)
    state['next_code_cache'] = next_code_cache
    state['locations_loaded'] = list(locations_loaded)
    state['sheet_row'] = sheet_row
    state['processed_total'] = processed_total

    return {
        'created': created,
        'updated': updated,
        'skipped': skipped,
        'errors': errors,
        'import_state': state,
        'batch_processed': processed_in_batch,
    }


def _im_import_optional_price(d: Dict[str, Any], *keys: str) -> Optional[float]:
    v = _im_import_cell(d, *keys)
    if v is None or (isinstance(v, str) and not str(v).strip()):
        return None
    try:
        return float(str(v).strip())
    except (TypeError, ValueError):
        return None


def _im_import_prices_from_row(nf: Dict[str, Any]) -> Dict[str, float]:
    """Return only price keys explicitly set in the import row."""
    out: Dict[str, float] = {}
    for key, *aliases in (
        ('cost_price', 'cost_price', 'costprice', 'cost'),
        ('retail_price', 'retail_price', 'retailprice', 'retail'),
        ('wholesale_price', 'wholesale_price', 'wholesaleprice', 'wholesale'),
        ('third_price', 'third_price', 'thirdprice', 'third'),
        ('branch_price', 'branch_price', 'branchprice', 'branch'),
    ):
        v = _im_import_optional_price(nf, *aliases)
        if v is not None:
            out[key] = v
    return out


def import_itemmaster_prices_from_excel_rows(
    location_code: int,
    rows: List[Dict[str, Any]],
    *,
    max_rows: int = 10000,
) -> Dict[str, Any]:
    """Bulk price update by barcode for ITEMMASTER and ITEMALTERNATEUOMMAP."""
    from .itemmaster_core import update_item_prices_by_barcode as _upd

    loc0 = int(location_code)
    errors: List[str] = []
    updated = skipped = failed = 0
    sheet_row = 1
    processed = 0
    for raw in rows or []:
        sheet_row += 1
        if processed >= max_rows:
            errors.append(f'Stopped after {max_rows} data rows.')
            break
        nf = _im_import_row_dict(raw)
        if not nf:
            continue
        if not any(v not in (None, '') and str(v).strip() != '' for v in nf.values()):
            continue
        processed += 1
        bc = str(_im_import_cell(nf, 'barcode', 'manufacturer_id', 'manufacturerid', 'mfr_id') or '').strip()
        if not bc:
            errors.append(f'Row {sheet_row}: Barcode is required.')
            failed += 1
            continue
        prices = _im_import_prices_from_row(nf)
        if not prices:
            errors.append(f'Row {sheet_row}: At least one price column is required (Cost/Retail/Wholesale/Third/Branch).')
            failed += 1
            continue
        eff_loc = _cm_import_parse_int(_im_import_cell(nf, 'location_code', 'locationcode'))
        row_loc = int(eff_loc) if eff_loc is not None else loc0
        try:
            ok, msg = _upd(row_loc, bc, prices)
            if ok:
                updated += 1
            else:
                failed += 1
                errors.append(f'Row {sheet_row}: {msg}')
        except Exception as exc:
            failed += 1
            errors.append(f'Row {sheet_row}: {exc}')
    return {'updated': updated, 'skipped': skipped, 'failed': failed, 'errors': errors, 'processed': processed}


def import_itemmaster_costprice_from_excel_rows(
    location_code: int,
    rows: List[Dict[str, Any]],
    *,
    max_rows: int = 10000,
    row_offset: int = 0,
    row_limit: Optional[int] = None,
    import_state: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Bulk COSTPRICE update by item code for ITEMMASTER and base ITEMALTERNATEUOMMAP."""
    from .itemmaster_core import update_item_costprice_by_itemcode as _upd

    loc0 = int(location_code)
    state = import_state if isinstance(import_state, dict) else {}
    errors: List[str] = list(state.get('errors') or [])
    updated = int(state.get('updated') or 0)
    skipped = int(state.get('skipped') or 0)
    failed = int(state.get('failed') or 0)

    slice_rows = (rows or [])[max(0, int(row_offset)):]
    if row_limit is not None:
        slice_rows = slice_rows[: max(0, int(row_limit))]

    sheet_row = int(state.get('sheet_row') or 1)
    processed_total = int(state.get('processed_total') or 0)
    batch_processed = 0

    for raw in slice_rows:
        sheet_row += 1
        if processed_total >= max_rows:
            errors.append(f'Stopped after {max_rows} data rows.')
            break
        nf = _im_import_row_dict(raw)
        if not nf:
            continue
        if not any(v not in (None, '') and str(v).strip() != '' for v in nf.values()):
            continue
        processed_total += 1
        batch_processed += 1
        ic = _cm_import_parse_int(_im_import_cell(nf, 'item_code', 'itemcode', 'code'))
        if ic is None or ic <= 0:
            errors.append(f'Row {sheet_row}: ItemCode is required.')
            failed += 1
            continue
        cp = _im_import_optional_price(nf, 'cost_price', 'costprice', 'cost')
        if cp is None:
            errors.append(f'Row {sheet_row}: CostPrice is required.')
            failed += 1
            continue
        eff_loc = _cm_import_parse_int(_im_import_cell(nf, 'location_code', 'locationcode'))
        row_loc = int(eff_loc) if eff_loc is not None else loc0
        try:
            ok, msg = _upd(row_loc, ic, cp)
            if ok:
                updated += 1
            else:
                failed += 1
                errors.append(f'Row {sheet_row}: {msg}')
        except Exception as exc:
            failed += 1
            errors.append(f'Row {sheet_row}: {exc}')

    state['errors'] = errors
    state['updated'] = updated
    state['skipped'] = skipped
    state['failed'] = failed
    state['sheet_row'] = sheet_row
    state['processed_total'] = processed_total

    return {
        'updated': updated,
        'skipped': skipped,
        'failed': failed,
        'errors': errors,
        'processed': processed_total,
        'import_state': state,
        'batch_processed': batch_processed,
    }


def _costing_fmt_amount(v: Any, decimals: int = 3) -> str:
    try:
        return f'{float(v or 0):.{decimals}f}'
    except (TypeError, ValueError):
        return f'0.{"0" * decimals}'


def _receipt_line_landing_unit(row: Dict[str, Any]) -> float:
    try:
        land = float(row.get('landingcost') or 0)
    except (TypeError, ValueError):
        land = 0.0
    if land > 0:
        return land
    try:
        bq = abs(float(row.get('baseqty') or 0))
        amt = float(row.get('amount') or 0)
        och = float(row.get('othercharge') or 0)
        if bq > 1e-12:
            return (amt + och) / bq
    except (TypeError, ValueError):
        pass
    try:
        rate = float(row.get('rate') or 0)
        cf = float(row.get('conversionfactor') or row.get('uomfactor') or 1)
        if cf > 0:
            return rate / cf
        return rate
    except (TypeError, ValueError):
        return 0.0


def _fetch_item_last_purchase_receipt_line(location_code: int, item_code: int) -> Optional[Dict[str, Any]]:
    dtl = _detect_table(['RECEIPTDTL', 'receiptdtl'])
    hdr = _detect_table(['RECEIPTHDR', 'receipthdr'])
    if not dtl:
        return None
    d_ic = _detect_column(dtl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    d_loc = _detect_column(dtl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    d_rno = _detect_column(dtl, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
    d_rate = _detect_column(dtl, ['RATE', 'rate'])
    d_amt = _detect_column(dtl, ['AMOUNT', 'amount'])
    d_och = _detect_column(dtl, ['OTHERCHARGE', 'OTHER_CHARGE', 'othercharge'])
    d_bq = _detect_column(dtl, ['BASEQTY', 'BASE_QTY', 'baseqty'])
    d_land = _detect_column(dtl, ['LANDINGCOST', 'LANDING_COST', 'landingcost'])
    d_uom = _detect_column(dtl, ['UOM', 'uom', 'UNITOFMEASUREMENT'])
    d_cf = _detect_column(dtl, ['CONVERSIONFACTOR', 'CONVERSION_FACTOR', 'UOMFACTOR', 'conversionfactor'])
    if not d_ic or not d_rno:
        return None
    sel = [
        f'd.{d_ic} AS itemcode',
        f'd.{d_rno} AS receiptno',
        f'NVL(d.{d_rate}, 0) AS rate' if d_rate else '0 AS rate',
        f'NVL(d.{d_amt}, 0) AS amount' if d_amt else '0 AS amount',
        f'NVL(d.{d_och}, 0) AS othercharge' if d_och else '0 AS othercharge',
        f'NVL(d.{d_bq}, 0) AS baseqty' if d_bq else '0 AS baseqty',
        f'NVL(d.{d_land}, 0) AS landingcost' if d_land else '0 AS landingcost',
        f'd.{d_uom} AS uom' if d_uom else "'' AS uom",
        f'NVL(d.{d_cf}, 1) AS conversionfactor' if d_cf else '1 AS conversionfactor',
    ]
    joins = ''
    order = f'd.{d_rno} DESC'
    if hdr:
        h_rno = _detect_column(hdr, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
        h_loc = _detect_column(hdr, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
        h_dt = _detect_column(hdr, ['RECEIPTDATE', 'RECEIPT_DATE', 'receiptdate'])
        h_sup = _detect_column(hdr, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode'])
        if h_rno:
            joins = f' INNER JOIN {hdr} h ON h.{h_rno} = d.{d_rno}'
            if h_loc and d_loc:
                joins += f' AND h.{h_loc} = d.{d_loc}'
            if h_dt:
                sel.append(f'h.{h_dt} AS receiptdate')
                order = f'h.{h_dt} DESC NULLS LAST, d.{d_rno} DESC'
            if h_sup:
                sel.append(f'h.{h_sup} AS suppliercode')
    where = [f'd.{d_ic} = :icode']
    params: Dict[str, Any] = {'icode': int(item_code)}
    if d_loc:
        where.append(f'd.{d_loc} = :loc')
        params['loc'] = int(location_code)
    q = f"""
        SELECT {', '.join(sel)}
        FROM {dtl} d
        {joins}
        WHERE {' AND '.join(where)}
        ORDER BY {order}
    """
    try:
        rows = _safe_rows(q, params)
    except Exception:
        return None
    if not rows:
        return None
    row = rows[0]
    row['landing_unit'] = round(_receipt_line_landing_unit(row), 3)
    return row


def _fetch_item_recent_purchase_receipt_lines(location_code: int, item_code: int, limit: int = 8) -> List[Dict[str, Any]]:
    dtl = _detect_table(['RECEIPTDTL', 'receiptdtl'])
    hdr = _detect_table(['RECEIPTHDR', 'receipthdr'])
    if not dtl:
        return []
    d_ic = _detect_column(dtl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    d_loc = _detect_column(dtl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    d_rno = _detect_column(dtl, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
    d_rate = _detect_column(dtl, ['RATE', 'rate'])
    d_amt = _detect_column(dtl, ['AMOUNT', 'amount'])
    d_och = _detect_column(dtl, ['OTHERCHARGE', 'OTHER_CHARGE', 'othercharge'])
    d_bq = _detect_column(dtl, ['BASEQTY', 'BASE_QTY', 'baseqty'])
    d_land = _detect_column(dtl, ['LANDINGCOST', 'LANDING_COST', 'landingcost'])
    d_uom = _detect_column(dtl, ['UOM', 'uom'])
    if not d_ic or not d_rno:
        return []
    lim = max(1, min(int(limit), 25))
    sel = [
        f'd.{d_ic} AS itemcode',
        f'd.{d_rno} AS receiptno',
        f'NVL(d.{d_rate}, 0) AS rate' if d_rate else '0 AS rate',
        f'NVL(d.{d_amt}, 0) AS amount' if d_amt else '0 AS amount',
        f'NVL(d.{d_och}, 0) AS othercharge' if d_och else '0 AS othercharge',
        f'NVL(d.{d_bq}, 0) AS baseqty' if d_bq else '0 AS baseqty',
        f'NVL(d.{d_land}, 0) AS landingcost' if d_land else '0 AS landingcost',
        f'd.{d_uom} AS uom' if d_uom else "'' AS uom",
    ]
    joins = ''
    order = f'd.{d_rno} DESC'
    if hdr:
        h_rno = _detect_column(hdr, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
        h_loc = _detect_column(hdr, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
        h_dt = _detect_column(hdr, ['RECEIPTDATE', 'RECEIPT_DATE', 'receiptdate'])
        if h_rno:
            joins = f' INNER JOIN {hdr} h ON h.{h_rno} = d.{d_rno}'
            if h_loc and d_loc:
                joins += f' AND h.{h_loc} = d.{d_loc}'
            if h_dt:
                sel.append(f'h.{h_dt} AS receiptdate')
                order = f'h.{h_dt} DESC NULLS LAST, d.{d_rno} DESC'
    where = [f'd.{d_ic} = :icode']
    params: Dict[str, Any] = {'icode': int(item_code)}
    if d_loc:
        where.append(f'd.{d_loc} = :loc')
        params['loc'] = int(location_code)
    q = f"""
        SELECT * FROM (
            SELECT {', '.join(sel)}
            FROM {dtl} d
            {joins}
            WHERE {' AND '.join(where)}
            ORDER BY {order}
        ) WHERE ROWNUM <= :lim
    """
    params['lim'] = lim
    try:
        rows = _safe_rows(q, params)
    except Exception:
        return []
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        lu = round(_receipt_line_landing_unit(r), 3)
        out.append({
            'receipt_no': r.get('receiptno'),
            'receipt_date': r.get('receiptdate'),
            'rate': r.get('rate'),
            'base_qty': r.get('baseqty'),
            'amount': r.get('amount'),
            'other_charge': r.get('othercharge'),
            'landing_unit': lu,
            'uom': r.get('uom'),
        })
    return out


def get_item_costing_method_details(location_code: int, item_code: int) -> Dict[str, Any]:
    """Costing method summary + per-metric explanation for Item Master UI."""
    try:
        loc = int(location_code)
        ic = int(item_code)
    except (TypeError, ValueError):
        return {'ok': False, 'error': 'Invalid location or item code.'}
    if ic <= 0:
        return {'ok': False, 'error': 'Item code is required.'}
    item = get_item_by_code(ic, loc) or {}
    if not item:
        return {'ok': False, 'error': f'Item {ic} not found at location {loc}.'}

    def _f(key: str) -> float:
        try:
            return float(item.get(key) or 0)
        except (TypeError, ValueError):
            return 0.0

    stock = _f('currentstock')
    cost_price = _f('costprice')
    avg_cost = _f('averagecost')
    land_cost = _f('landingcost')
    if land_cost <= 0 and avg_cost > 0:
        land_cost = avg_cost

    last_line = _fetch_item_last_purchase_receipt_line(loc, ic)
    last_purchase = float(last_line.get('landing_unit') or 0) if last_line else 0.0
    recent = _fetch_item_recent_purchase_receipt_lines(loc, ic, limit=8)

    method_name = 'Weighted average (GRN posting)'
    method_note = (
        'Inventory unit costs are recalculated when a Goods Receipt (GRN) is posted. '
        'Landing cost is the weighted average landed unit cost for the receipt; average cost blends '
        'stock on hand with the new receipt using a weighted-average formula.'
    )

    cards: List[Dict[str, Any]] = []

    lp_steps = [
        'Take the most recent posted purchase receipt line for this item (RECEIPTDTL).',
        'Landing unit per base qty = (Line amount + Other charge) ÷ Base qty when landing is not stored on the line.',
        'Otherwise use the line Landing cost field, or Rate ÷ Conversion factor.',
    ]
    if last_line:
        lp_steps.append(
            f'Last receipt #{last_line.get("receiptno")}: amount {_costing_fmt_amount(last_line.get("amount"), 2)} + '
            f'other charge {_costing_fmt_amount(last_line.get("othercharge"), 2)} on base qty '
            f'{_costing_fmt_amount(last_line.get("baseqty"), 3)} → landing unit {_costing_fmt_amount(last_purchase)}.'
        )
    else:
        lp_steps.append('No purchase receipt lines found — showing 0 until the first GRN is posted.')

    cards.append({
        'id': 'last_purchase',
        'title': 'Last purchase cost',
        'value': last_purchase,
        'value_label': _costing_fmt_amount(last_purchase),
        'summary': 'Landed unit cost from the latest goods receipt line (per base UOM).',
        'formula': 'Last purchase = (Amount + Other charge) ÷ Base qty  (or line Landing cost)',
        'steps': lp_steps,
        'source': 'RECEIPTDTL / RECEIPTHDR (latest receipt)',
        'last_receipt': {
            'receipt_no': last_line.get('receiptno') if last_line else None,
            'receipt_date': str(last_line.get('receiptdate') or '') if last_line else '',
            'rate': last_line.get('rate') if last_line else None,
            'base_qty': last_line.get('baseqty') if last_line else None,
            'amount': last_line.get('amount') if last_line else None,
            'other_charge': last_line.get('othercharge') if last_line else None,
            'uom': last_line.get('uom') if last_line else '',
        } if last_line else None,
    })

    cards.append({
        'id': 'average_cost',
        'title': 'Average cost',
        'value': avg_cost,
        'value_label': _costing_fmt_amount(avg_cost),
        'summary': 'Weighted-average inventory unit cost stored on ITEMMASTER (AVERAGECOST).',
        'formula': 'New avg = (Qty on hand × Avg on hand − Old receipt qty × Old landing + New receipt qty × New landing) ÷ (Qty on hand + New receipt qty)',
        'steps': [
            'On GRN save, the system reads current stock and average cost from ITEMMASTER.',
            'It backs out the previous receipt quantity/value for this document (re-save safe).',
            'It adds the new receipt weighted landing cost, then writes AVERAGECOST on ITEMMASTER.',
            f'Current stock: {_costing_fmt_amount(stock, 3)} · Stored average: {_costing_fmt_amount(avg_cost)}.',
        ],
        'source': 'ITEMMASTER.AVERAGECOST (updated on GRN posting)',
    })

    cards.append({
        'id': 'landing_cost',
        'title': 'Landing cost',
        'value': land_cost,
        'value_label': _costing_fmt_amount(land_cost),
        'summary': 'Weighted landed unit cost from the latest GRN for this item (per base UOM).',
        'formula': 'Landing = Σ(Base qty × Line landing unit) ÷ Σ(Base qty)  for all lines of the receipt',
        'steps': [
            'Each GRN line landing unit = (Amount + Other charge) ÷ Base qty (FOC lines use 0).',
            'Lines for the same item on one receipt are combined into one weighted landing.',
            'ITEMMASTER.LANDINGCOST is set to that value when the receipt is posted.',
            f'Stored landing cost: {_costing_fmt_amount(land_cost)}.',
        ],
        'source': 'ITEMMASTER.LANDINGCOST (updated on GRN posting)',
    })

    cards.append({
        'id': 'cost_price',
        'title': 'Cost price',
        'value': cost_price,
        'value_label': _costing_fmt_amount(cost_price),
        'summary': 'Manual/list cost on the item header (COSTPRICE); also refreshed from the latest receipt base cost on GRN.',
        'formula': 'Cost price ≈ Receipt rate ÷ Conversion factor  (per purchase UOM → base UOM)',
        'steps': [
            'Editable on Item Master → Pricing → Cost Price.',
            'When a GRN is posted, COSTPRICE is updated to the receipt base unit cost for that item.',
            f'Current cost price: {_costing_fmt_amount(cost_price)}.',
        ],
        'source': 'ITEMMASTER.COSTPRICE',
    })

    return {
        'ok': True,
        'location_code': loc,
        'item_code': ic,
        'costing_method': method_name,
        'costing_method_note': method_note,
        'current_stock': stock,
        'cost_price': cost_price,
        'average_cost': avg_cost,
        'landing_cost': land_cost,
        'last_purchase_cost': last_purchase,
        'cards': cards,
        'recent_receipts': recent,
        'has_average_column': _detect_column(_detect_table(['ITEMMASTER']) or 'ITEMMASTER', ['AVERAGECOST', 'averagecost']) is not None,
        'has_landing_column': _detect_column(_detect_table(['ITEMMASTER']) or 'ITEMMASTER', ['LANDINGCOST', 'landingcost']) is not None,
    }


def get_next_itemalternate_slno(location_code: int, item_code: int) -> int:
    query = '\n        SELECT NVL(MAX(SLNO), 0) + 1 AS NEXT_SLNO\n        FROM ITEMALTERNATEUOMMAP\n        WHERE LOCATIONCODE = :location_code\n        AND ITEMCODE = :item_code\n    '
    rows = _safe_rows(query, {'location_code': location_code, 'item_code': item_code})
    if rows and rows[0].get('next_slno') is not None:
        try:
            return int(rows[0]['next_slno'])
        except (ValueError, TypeError):
            return 1
    return 1

def get_item_alternate_uom(location_code: int, item_code: int) -> Optional[Dict[str, Any]]:
    """Get first alternate UOM mapping for an item"""
    from .itemmaster_core import ensure_itemalternateuommap_extension_columns, itemalternateuommap_select_sql
    ensure_itemalternateuommap_extension_columns()
    sel = itemalternateuommap_select_sql()
    query = f'\n        SELECT {sel}\n        FROM ITEMALTERNATEUOMMAP\n        WHERE LOCATIONCODE = :location_code\n        AND ITEMCODE = :item_code\n        ORDER BY SLNO\n    '
    rows = _safe_rows(query, {'location_code': location_code, 'item_code': item_code})
    return rows[0] if rows else None

def get_item_alternate_uoms(location_code: int, item_code: int) -> List[Dict[str, Any]]:
    """Get all alternate UOM mappings for an item"""
    from .itemmaster_core import ensure_itemalternateuommap_extension_columns, itemalternateuommap_select_sql
    ensure_itemalternateuommap_extension_columns()
    sel = itemalternateuommap_select_sql()
    query = f'\n        SELECT {sel}\n        FROM ITEMALTERNATEUOMMAP\n        WHERE LOCATIONCODE = :location_code\n        AND ITEMCODE = :item_code\n        ORDER BY SLNO\n    '
    return _safe_rows(query, {'location_code': location_code, 'item_code': item_code})

def get_item_store_rows_from_itemmaster(item_code: int, location_code: int, db_key: Optional[str]=None) -> List[Dict[str, Any]]:
    """
    Default warehouse row from **ITEMMASTER.DEFAULT_WAREHOUSE_ID** for this branch + item.
    Shape matches ``get_item_store_inventory`` callers: ``store`` (label), ``code``, ``stock``.
    """
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return []
    cols_upper = {c.upper() for c in _get_table_columns(im) or []}
    if 'DEFAULT_WAREHOUSE_ID' not in cols_upper:
        return []
    code_col = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    loc_col = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    cu_col = _detect_column(im, ['CURRENTSTOCK', 'CURRENT_STOCK', 'STOCK'])
    if not code_col or not loc_col:
        return []
    try:
        ic = int(item_code)
        lc = int(location_code)
    except (TypeError, ValueError):
        return []
    rows = _safe_rows(f"""
        SELECT im.DEFAULT_WAREHOUSE_ID AS warehouse_id
        FROM {im} im
        WHERE im.{code_col} = :ic AND im.{loc_col} = :loc
        """, {'ic': ic, 'loc': lc}, db_key=db_key)
    if not rows or rows[0].get('warehouse_id') is None:
        return []
    try:
        wid = int(rows[0]['warehouse_id'])
    except (TypeError, ValueError):
        return []
    if wid <= 0:
        return []
    wm = get_warehouse_master_by_id(wid, db_key)
    label = str(wm.get('warehouse_code') or wid) if wm else str(wid)
    desc = str(wm.get('warehouse_name') or '').strip() if wm else ''
    qty_expr = f'NVL(im.{cu_col}, 0)' if cu_col else '0'
    rows2 = _safe_rows(f"""
        SELECT {qty_expr} AS stock FROM {im} im
        WHERE im.{code_col} = :ic AND im.{loc_col} = :loc
        """, {'ic': ic, 'loc': lc}, db_key=db_key)
    try:
        st = float(rows2[0].get('stock') or 0) if rows2 else 0.0
    except (TypeError, ValueError):
        st = 0.0
    return [{'code': str(wid), 'store': label, 'description': desc, 'stock': st, 'warehouse_id': wid}]

def _get_item_store_inventory_from_warehouse_stock(
    location_code: int,
    item_code: int,
    db_key: Optional[str]=None,
    *,
    include_zero: bool=False,
) -> List[Dict[str, Any]]:
    """
    Store Inventory panel rows from ``WAREHOUSE_STOCK`` (per warehouse at branch).
    Shape: ``code``, ``store``, ``description``, ``stock``, optional ``warehouse_id``.
    """
    if not ensure_warehouse_stock_table(db_key=db_key) or not _table_exists(WAREHOUSE_STOCK_TABLE, db_key=db_key):
        return []
    try:
        lc = int(location_code)
        ic = int(item_code)
    except (TypeError, ValueError):
        return []
    wm_tbl = resolve_warehouse_master_table(db_key)
    join_ws = (
        f'INNER JOIN {WAREHOUSE_STOCK_TABLE} ws\n'
        f'  ON ws.WAREHOUSE_ID = wm.WAREHOUSE_ID\n'
        f' AND ws.ITEMCODE = :ic\n'
        f' AND ws.LOCATIONCODE = :loc'
    )
    if include_zero and wm_tbl:
        join_ws = (
            f'LEFT JOIN {WAREHOUSE_STOCK_TABLE} ws\n'
            f'  ON ws.WAREHOUSE_ID = wm.WAREHOUSE_ID\n'
            f' AND ws.ITEMCODE = :ic\n'
            f' AND ws.LOCATIONCODE = :loc'
        )
    qty_filter = '' if include_zero else ' AND NVL(ws.QTY, 0) <> 0'
    params: Dict[str, Any] = {'loc': lc, 'ic': ic}
    if wm_tbl:
        q = f"""
            SELECT
                TO_CHAR(wm.WAREHOUSE_ID) AS code,
                TRIM(wm.WAREHOUSE_CODE) AS store,
                TRIM(wm.WAREHOUSE_NAME) AS description,
                NVL(ws.QTY, 0) AS stock,
                wm.WAREHOUSE_ID AS warehouse_id
            FROM {wm_tbl} wm
            {join_ws}
            WHERE wm.LOCATIONCODE = :loc
              AND NVL(wm.IS_ACTIVE, 'Y') = 'Y'
            {qty_filter}
            ORDER BY UPPER(TRIM(wm.WAREHOUSE_CODE))
        """
        return _safe_rows(q, params, db_key=db_key) or []
    q = f"""
        SELECT
            TO_CHAR(ws.WAREHOUSE_ID) AS code,
            TO_CHAR(ws.WAREHOUSE_ID) AS store,
            '' AS description,
            NVL(ws.QTY, 0) AS stock,
            ws.WAREHOUSE_ID AS warehouse_id
        FROM {WAREHOUSE_STOCK_TABLE} ws
        WHERE ws.LOCATIONCODE = :loc AND ws.ITEMCODE = :ic
        {qty_filter}
        ORDER BY ws.WAREHOUSE_ID
    """
    return _safe_rows(q, params, db_key=db_key) or []


def _get_item_store_inventory_legacy_storeinventory(
    location_code: int,
    item_code: int,
) -> List[Dict[str, Any]]:
    """Legacy: STOREINVENTORY view (used only when WAREHOUSE_STOCK is unavailable)."""
    table_name = 'STOREINVENTORY'
    try:
        if not _get_table_columns(table_name):
            return []
    except Exception:
        return []
    item_col = _detect_column(table_name, ['ITEMCODE', 'ITEM_CODE', 'ITEM', 'PRODUCTCODE', 'PRODUCT_CODE'])
    store_col = _detect_column(table_name, ['STORE', 'STORECODE', 'STORE_CODE', 'STORENO', 'STORE_NO', 'GODOWN', 'GODOWNCODE', 'LOCATION'])
    code_col = _detect_column(table_name, ['CODE', 'ID', 'STORECODE', 'STORE_CODE', 'STORENO', 'STORE_NO'])
    desc_col = _detect_column(table_name, ['DESCRIPTION', 'STOREDESCRIPTION', 'STOREDESC', 'STOREDESCRIPTION', 'NAME', 'STORENAME', 'GODOWNNAME'])
    stock_col = _detect_column(table_name, ['STOCK', 'CURRENTSTOCK', 'QTY', 'QUANTITY', 'BALANCE', 'TOTALSTOCK', 'STOCKQTY'])
    location_col = _detect_column(table_name, ['LOCATIONCODE', 'LOCATION_CODE'])
    if not store_col or not stock_col:
        return []
    query = f"""\n        SELECT\n            {(code_col if code_col else store_col)} AS code,\n            {store_col} AS store,\n            {(desc_col if desc_col else "''")} AS description,\n            NVL({stock_col}, 0) AS stock\n        FROM {table_name}\n        WHERE 1=1\n    """
    params: Dict[str, Any] = {}
    if item_col:
        query += f' AND {item_col} = :item_code'
        params['item_code'] = item_code
    if location_col:
        query += f' AND {location_col} = :location_code'
        params['location_code'] = location_code
    query += f' AND NVL({stock_col}, 0) <> 0'
    query += f' ORDER BY UPPER(TRIM({store_col})) ASC'
    return _safe_rows(query, params)


def get_item_store_inventory(location_code: int, item_code: int) -> List[Dict[str, Any]]:
    """Store inventory rows for Item Master: ``WAREHOUSE_STOCK`` per warehouse (legacy STOREINVENTORY fallback)."""
    if ensure_warehouse_stock_table() and _table_exists(WAREHOUSE_STOCK_TABLE):
        return _get_item_store_inventory_from_warehouse_stock(location_code, item_code, include_zero=False)
    return _get_item_store_inventory_legacy_storeinventory(location_code, item_code)

def _warehouse_stock_summary_for_items(location_code: int, item_codes: List[int]) -> Dict[int, Dict[str, Any]]:
    """Per item: total qty and warehouse code with highest qty from WAREHOUSE_STOCK."""
    out: Dict[int, Dict[str, Any]] = {}
    if not item_codes:
        return out
    if not ensure_warehouse_stock_table() or not _table_exists(WAREHOUSE_STOCK_TABLE):
        return out
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return out
    binds = ','.join([f':s{i}' for i in range(len(item_codes))])
    params: Dict[str, Any] = {'loc': lc}
    for i, v in enumerate(item_codes):
        params[f's{i}'] = int(v)
    wm_tbl = resolve_warehouse_master_table()
    if wm_tbl:
        q = f"""
            SELECT ws.ITEMCODE AS ic,
                   SUM(NVL(ws.QTY, 0)) AS total_stock,
                   MAX(TRIM(wm.WAREHOUSE_CODE)) KEEP (DENSE_RANK LAST ORDER BY NVL(ws.QTY, 0)) AS best_store
            FROM {WAREHOUSE_STOCK_TABLE} ws
            INNER JOIN {wm_tbl} wm
              ON wm.WAREHOUSE_ID = ws.WAREHOUSE_ID
             AND wm.LOCATIONCODE = ws.LOCATIONCODE
            WHERE ws.LOCATIONCODE = :loc
              AND ws.ITEMCODE IN ({binds})
              AND NVL(wm.IS_ACTIVE, 'Y') = 'Y'
            GROUP BY ws.ITEMCODE
        """
    else:
        q = f"""
            SELECT ws.ITEMCODE AS ic,
                   SUM(NVL(ws.QTY, 0)) AS total_stock,
                   MAX(TO_CHAR(ws.WAREHOUSE_ID)) KEEP (DENSE_RANK LAST ORDER BY NVL(ws.QTY, 0)) AS best_store
            FROM {WAREHOUSE_STOCK_TABLE} ws
            WHERE ws.LOCATIONCODE = :loc
              AND ws.ITEMCODE IN ({binds})
            GROUP BY ws.ITEMCODE
        """
    try:
        rows = _safe_rows(q, params) or []
    except Exception:
        return out
    for r in rows:
        try:
            ic = int(float(str(r.get('ic') or 0)))
        except (TypeError, ValueError):
            continue
        if ic <= 0:
            continue
        try:
            tot = float(r.get('total_stock') or 0)
        except (TypeError, ValueError):
            tot = 0.0
        bs = str(r.get('best_store') or '').strip()
        out[ic] = {'total': tot, 'best_store': bs}
    return out


def get_storeinventory_stock_summary_for_items(location_code: int, item_codes: List[Any]) -> Dict[int, Dict[str, Any]]:
    """Per item at this branch: total qty across stores and store/warehouse with highest qty.

    Returned shape: ``{ itemcode_int: {\"total\": float, \"best_store\": str } }``.
    Uses WAREHOUSE_STOCK when available; otherwise STOREINVENTORY legacy view.
    Items with no rows are omitted from the dict (caller treats as zeros).
    """
    out: Dict[int, Dict[str, Any]] = {}
    uniq: List[int] = []
    for c in item_codes or []:
        try:
            ic = int(float(str(c).strip()))
            if ic > 0:
                uniq.append(ic)
        except (TypeError, ValueError):
            continue
    uniq = sorted(set(uniq))
    if not uniq:
        return out
    if ensure_warehouse_stock_table() and _table_exists(WAREHOUSE_STOCK_TABLE):
        wh_out = _warehouse_stock_summary_for_items(location_code, uniq)
        if wh_out:
            return wh_out
    table_name = 'STOREINVENTORY'
    try:
        if not _get_table_columns(table_name):
            return out
    except Exception:
        return out
    item_col = _detect_column(table_name, ['ITEMCODE', 'ITEM_CODE', 'ITEM', 'PRODUCTCODE', 'PRODUCT_CODE'])
    store_col = _detect_column(table_name, ['STORE', 'STORECODE', 'STORE_CODE', 'STORENO', 'STORE_NO', 'GODOWN', 'GODOWNCODE', 'LOCATION'])
    stock_col = _detect_column(table_name, ['STOCK', 'CURRENTSTOCK', 'QTY', 'QUANTITY', 'BALANCE', 'TOTALSTOCK', 'STOCKQTY'])
    location_col = _detect_column(table_name, ['LOCATIONCODE', 'LOCATION_CODE'])
    if not item_col or not store_col or not stock_col or not location_col:
        return out
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return out
    binds = ','.join([f':s{i}' for i in range(len(uniq))])
    params: Dict[str, Any] = {'loc': lc}
    for i, v in enumerate(uniq):
        params[f's{i}'] = int(v)
    store_expr = f'TRIM({store_col})'
    q_try = (
        f'SELECT {item_col} AS ic, SUM(NVL({stock_col}, 0)) AS total_stock, '
        f'MAX({store_expr}) KEEP (DENSE_RANK LAST ORDER BY NVL({stock_col}, 0)) AS best_store '
        f'FROM {table_name} WHERE {location_col} = :loc AND {item_col} IN ({binds}) GROUP BY {item_col}'
    )
    rows: List[Dict[str, Any]]
    try:
        rows = _safe_rows(q_try, params)
    except Exception:
        q_sum = (
            f'SELECT {item_col} AS ic, SUM(NVL({stock_col}, 0)) AS total_stock '
            f'FROM {table_name} WHERE {location_col} = :loc AND {item_col} IN ({binds}) GROUP BY {item_col}'
        )
        try:
            rows = _safe_rows(q_sum, params)
        except Exception:
            return out
        for r in rows or []:
            try:
                ic = int(float(str(r.get('ic') or 0)))
            except (TypeError, ValueError):
                continue
            if ic <= 0:
                continue
            try:
                tot = float(r.get('total_stock') or 0)
            except (TypeError, ValueError):
                tot = 0.0
            out[ic] = {'total': tot, 'best_store': ''}
        return out

    def _pick_key(row: Dict[str, Any], *candidates: str) -> Any:
        for k in candidates:
            if k in row:
                return row.get(k)
        lk = {str(kk).upper(): kk for kk in row.keys()}
        for cand in candidates:
            kk = lk.get(str(cand).upper())
            if kk is not None:
                return row.get(kk)
        return None

    for r in rows or []:
        try:
            ic = int(float(str(_pick_key(r, 'ic', 'IC', 'ITEMCODE') or 0)))
        except (TypeError, ValueError):
            continue
        if ic <= 0:
            continue
        bs_raw = _pick_key(r, 'best_store', 'BEST_STORE')
        try:
            tot = float(_pick_key(r, 'total_stock', 'TOTAL_STOCK') or 0)
        except (TypeError, ValueError):
            tot = 0.0
        out[ic] = {'total': tot, 'best_store': str(bs_raw).strip() if bs_raw is not None else ''}
    return out

def get_store_inventory_lines_for_branch(location_code: int, db_key: Optional[str]=None, *, include_zero: bool=False) -> List[Dict[str, Any]]:
    """STOREINVENTORY lines for a branch: store, itemcode, qty, itemname. By default excludes zero qty."""
    table_name = 'STOREINVENTORY'
    try:
        if not _get_table_columns(table_name, db_key=db_key):
            return []
    except Exception:
        return []
    item_col = _detect_column(table_name, ['ITEMCODE', 'ITEM_CODE', 'ITEM', 'PRODUCTCODE', 'PRODUCT_CODE'])
    store_col = _detect_column(table_name, ['STORE', 'STORECODE', 'STORE_CODE', 'STORENO', 'STORE_NO', 'GODOWN', 'GODOWNCODE', 'LOCATION'])
    stock_col = _detect_column(table_name, ['STOCK', 'CURRENTSTOCK', 'QTY', 'QUANTITY', 'BALANCE', 'TOTALSTOCK', 'STOCKQTY'])
    location_col = _detect_column(table_name, ['LOCATIONCODE', 'LOCATION_CODE'])
    if not item_col or not store_col or not stock_col or not location_col:
        return []
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return []
    imx_tbl = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    join_sql = ''
    params: Dict[str, Any] = {'loc': lc}
    if imx_tbl:
        ic_join = _detect_column(imx_tbl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
        lc_join = _detect_column(imx_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
        name_join = _detect_column(imx_tbl, ['ITEMNAME', 'ITEM_NAME', 'itemname'])
        if ic_join and lc_join and name_join:
            join_sql = f'\n            LEFT JOIN {imx_tbl} im ON im.{ic_join} = si.{item_col} AND im.{lc_join} = :loc\n        '
    name_sel = "CAST(NULL AS VARCHAR2(400)) AS itemname"
    if join_sql.strip():
        name_sel = f'NVL(im.{name_join}, \'\') AS itemname'
    q = f"""
        SELECT TRIM(si.{store_col}) AS store,
               si.{item_col} AS itemcode,
               NVL(si.{stock_col}, 0) AS qty,
               {name_sel}
        FROM {table_name} si
        {join_sql}
        WHERE si.{location_col} = :loc
          {('' if include_zero else 'AND NVL(si.' + stock_col + ', 0) <> 0')}
        ORDER BY UPPER(TRIM(si.{store_col})), si.{item_col}
    """
    try:
        return _safe_rows(q, params, db_key=db_key) or []
    except Exception:
        return []


def _vsp_batch_tracked_item_codes_for_branch(location_code: int, db_key: Optional[str]=None) -> Set[int]:
    """ITEMMASTER item codes flagged BATCH_TRACKED=Y for this branch (when tables/columns exist)."""
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        return set()
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return set()
    try:
        cols = {str(c).upper() for c in (_get_table_columns(im, db_key=db_key) or [])}
    except Exception:
        return set()
    if 'BATCH_TRACKED' not in cols:
        return set()
    code_col = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    loc_col = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    if not code_col:
        return set()
    w = ["UPPER(TRIM(im.BATCH_TRACKED)) = 'Y'"]
    p: Dict[str, Any] = {}
    if loc_col:
        w.append(f'im.{loc_col} = :loc')
        p['loc'] = lc
    q = f'SELECT im.{code_col} AS itemcode FROM {im} im WHERE {" AND ".join(w)}'
    rows = _safe_rows(q, p, db_key=db_key) or []
    out: Set[int] = set()
    for r in rows:
        try:
            ic = int(r.get('itemcode') or 0)
        except (TypeError, ValueError):
            continue
        if ic > 0:
            out.add(ic)
    return out


def _vsp_lot_nodes_by_storage_item(location_code: int, wh_loc_key: str, *, include_zero_qty: bool, db_key: Optional[str]=None) -> Dict[Tuple[int, int], List[Dict[str, Any]]]:
    """Map (storage_id, itemcode) → lot child nodes for warehouse tree."""
    from collections import defaultdict
    rows = get_item_lot_bin_shelf_stock_grid(
        location_code, None, None, wh_loc_key, db_key=db_key, include_zero_qty=include_zero_qty,
    ) or []
    m: Dict[Tuple[int, int], List[Dict[str, Any]]] = defaultdict(list)
    for r in rows:
        try:
            sid = int(r.get('storage_id') or 0)
            ic = int(r.get('itemcode') or 0)
        except (TypeError, ValueError):
            continue
        if sid <= 0 or ic <= 0:
            continue
        qty = float(r.get('qty') or 0)
        if not include_zero_qty and abs(qty) < 1e-9:
            continue
        try:
            lid = int(r.get('lot_id') or 0)
        except (TypeError, ValueError):
            lid = 0
        batch_no = str(r.get('batch_no') or '').strip()
        exp = r.get('expiry_date')
        exp_s = ''
        if exp is not None:
            iso = getattr(exp, 'isoformat', None)
            exp_s = (iso() if callable(iso) else str(exp))[:32]
        label = f'L{lid} · {batch_no}' if (lid and batch_no) else (f'Lot {lid}' if lid else (batch_no or 'Lot'))
        m[(sid, ic)].append({
            'kind': 'lot',
            'label': label,
            'lot_id': lid or None,
            'batch_no': batch_no or None,
            'expiry_date': exp_s or None,
            'qty': round(qty, 4),
        })
    out: Dict[Tuple[int, int], List[Dict[str, Any]]] = {}
    for k, v in m.items():
        v.sort(key=lambda x: (str(x.get('batch_no') or ''), x.get('lot_id') or 0))
        out[k] = v
    return out


def _vsp_attach_lots_to_wh_tree(nodes: List[Dict[str, Any]], lot_map: Dict[Tuple[int, int], List[Dict[str, Any]]], tracked_set: Set[int]) -> None:
    for n in nodes or []:
        k = str(n.get('kind') or '')
        ch = n.get('children')
        if k == 'item':
            try:
                sid = int(n.get('storage_id') or 0)
                ic = int(n.get('itemcode') or 0)
            except (TypeError, ValueError):
                sid, ic = 0, 0
            if ic in tracked_set and sid > 0:
                n['children'] = list(lot_map.get((sid, ic), []))
            continue
        if isinstance(ch, list) and ch:
            _vsp_attach_lots_to_wh_tree(cast(List[Dict[str, Any]], ch), lot_map, tracked_set)


def build_visual_stock_report_payload(
    location_code: int,
    wh_loc_key: Optional[str]=None,
    db_key: Optional[str]=None,
    *,
    warehouse_site_label: Optional[str]=None,
    include_zero_qty: bool=False,
    attach_bin_lots: bool=True,
    totals_basis: str='separate',
) -> Dict[str, Any]:
    """Structured trees for Visual Stock Report: store ledger + warehouse rack→shelf→bin→items (optional lot children)."""
    from collections import defaultdict
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        lc = 1
    basis_raw = (totals_basis or 'separate').strip().lower()
    if basis_raw not in ('store', 'warehouse', 'separate'):
        basis_raw = 'separate'

    batch_on = bool(is_location_batch_tracking_enabled(lc))
    tracked_items: Set[int] = _vsp_batch_tracked_item_codes_for_branch(lc, db_key=db_key) if batch_on else set()

    lk = (wh_loc_key or '').strip() or resolve_warehouse_loc_key_for_location_code(lc, db_key=db_key) or ''
    lot_map: Dict[Tuple[int, int], List[Dict[str, Any]]] = {}
    if lk and attach_bin_lots and batch_on and tracked_items:
        try:
            lot_map = _vsp_lot_nodes_by_storage_item(lc, lk, include_zero_qty=include_zero_qty, db_key=db_key)
        except Exception:
            lot_map = {}

    store_lines = get_store_inventory_lines_for_branch(lc, db_key=db_key, include_zero=include_zero_qty) or []
    store_total = sum(float(r.get('qty') or 0) for r in store_lines)
    by_store: Dict[str, Dict[str, Any]] = {}
    for row in store_lines:
        qv = float(row.get('qty') or 0)
        st = str(row.get('store') or '').strip() or '—'
        if st not in by_store:
            by_store[st] = {'kind': 'store', 'label': st, 'qty': 0.0, 'children': []}
        by_store[st]['qty'] += qv
        nm = str(row.get('itemname') or '').strip()
        ic = row.get('itemcode')
        by_store[st]['children'].append({
            'kind': 'item',
            'label': f'{ic} · {nm}' if nm else str(ic),
            'itemcode': ic,
            'itemname': nm or None,
            'qty': round(qv, 4),
        })
    for v in by_store.values():
        v['qty'] = round(float(v['qty']), 4)
    store_tree = sorted(by_store.values(), key=lambda x: str(x.get('label') or '').upper())

    bin_rows: List[Dict[str, Any]] = []
    if lk:
        try:
            bin_rows = get_bin_stock_list(lk, lc, db_key=db_key, limit=5000, include_zero=include_zero_qty) or []
        except Exception:
            bin_rows = []

    sid_to_meta: Dict[int, Dict[str, str]] = {}
    if lk:
        try:
            flat_wh = get_warehouse_storage_flat(lk, db_key=db_key) or []
        except Exception:
            flat_wh = []
        for fr in flat_wh:
            stt = str(fr.get('storage_type') or '').upper()
            if stt not in ('BIN', 'STAGING'):
                continue
            try:
                sid = int(fr.get('storage_id') or 0)
            except (TypeError, ValueError):
                continue
            if sid <= 0:
                continue
            rack_l = fr.get('parent_rack_code')
            shelf_l = fr.get('parent_shelf_code')
            if fr.get('is_unplaced'):
                rack_l = rack_l or '(Unplaced)'
                shelf_l = shelf_l or '—'
            rack_l = str(rack_l or '(Unplaced)').strip()
            shelf_l = str(shelf_l or '—').strip()
            bn = str(fr.get('code') or str(sid)).strip()
            sid_to_meta[sid] = {'rack': rack_l, 'shelf': shelf_l, 'bin': bn}

    agg: Dict[Tuple[str, str, str], List[Dict[str, Any]]] = defaultdict(list)
    wh_total = 0.0
    for br in bin_rows:
        try:
            sid = int(br.get('storage_id') or 0)
        except (TypeError, ValueError):
            sid = 0
        mq = float(br.get('qty') or 0)
        wh_total += mq
        meta = sid_to_meta.get(sid) if sid else None
        if not meta:
            meta = {
                'rack': '(Unknown layout)',
                'shelf': '—',
                'bin': str(br.get('bin_code') or sid or '?').strip(),
            }
        nm = str(br.get('itemname') or '').strip()
        ic = br.get('itemcode')
        key = (meta['rack'], meta['shelf'], meta['bin'])
        agg[key].append({
            'kind': 'item',
            'label': f'{ic} · {nm}' if nm else str(ic),
            'itemcode': ic,
            'itemname': nm or None,
            'qty': round(mq, 4),
            'storage_id': sid,
        })

    racks_map: Dict[str, Dict[str, Any]] = {}
    for (rack, shelf, bin_code), items in agg.items():
        rk = racks_map.setdefault(rack, {'kind': 'rack', 'label': rack, 'qty': 0.0, 'shelves': {}})
        sh = rk['shelves'].setdefault(shelf, {'kind': 'shelf', 'label': shelf, 'qty': 0.0, 'bins': {}})
        bnode = sh['bins'].setdefault(bin_code, {'kind': 'bin', 'label': bin_code, 'qty': 0.0, 'children': []})
        bnode['children'].extend(items)

    wh_tree: List[Dict[str, Any]] = []
    for rkey, rn in sorted(racks_map.items(), key=lambda x: x[0].upper()):
        shelvelist: List[Dict[str, Any]] = []
        for sk, sn in sorted(rn['shelves'].items(), key=lambda x: x[0].upper()):
            binlist: List[Dict[str, Any]] = []
            for bk, bn in sorted(sn['bins'].items(), key=lambda x: x[0].upper()):
                bq = round(sum(float(c.get('qty') or 0) for c in bn['children']), 4)
                bn['qty'] = bq
                binlist.append(bn)
            sn['qty'] = round(sum(b.get('qty', 0) for b in binlist), 4)
            sn['children'] = binlist
            del sn['bins']
            shelvelist.append(sn)
        rn['qty'] = round(sum(s.get('qty', 0) for s in shelvelist), 4)
        rn['children'] = shelvelist
        del rn['shelves']
        wh_tree.append(rn)

    if lot_map and tracked_items:
        _vsp_attach_lots_to_wh_tree(wh_tree, lot_map, tracked_items)

    site_disp: Optional[str] = None
    if lk:
        site_disp = (warehouse_site_label or '').strip() or str(lk).strip()
        wh_tree = [{
            'kind': 'wh_site',
            'label': site_disp,
            'loc_key': lk,
            'qty': round(wh_total, 4),
            'children': wh_tree,
        }]

    theor: Optional[float] = None
    if basis_raw == 'store':
        theor = round(store_total, 4)
    elif basis_raw == 'warehouse':
        theor = round(wh_total, 4)

    return {
        'location_code': lc,
        'loc_key': lk or None,
        'warehouse_site_label': site_disp,
        'options': {
            'include_zero_qty': bool(include_zero_qty),
            'attach_bin_lots': bool(attach_bin_lots),
            'totals_basis': basis_raw,
        },
        'flags': {'batch_tracking_branch': batch_on},
        'summary': {
            'store_ledger_qty': round(store_total, 4),
            'warehouse_bin_qty': round(wh_total, 4),
            'store_line_count': len(store_lines),
            'warehouse_line_count': len(bin_rows),
            'totals_basis': basis_raw,
            'theoretical_total': theor,
            'theoretical_total_label': (
                'Same as store ledger qty' if basis_raw == 'store' else (
                    'Same as warehouse bin qty' if basis_raw == 'warehouse' else ''
                )
            ),
        },
        'store_tree': store_tree,
        'warehouse_tree': wh_tree,
    }


def flatten_visual_stock_audit_rows(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    """One CSV row per store-line, bin-line, or bin-lot line for audit exports."""
    if not isinstance(payload, dict):
        return []
    lc = payload.get('location_code')
    lk = payload.get('loc_key') or ''
    basis = str((payload.get('summary') or {}).get('totals_basis') or 'separate')
    rows_acc: List[Dict[str, Any]] = []

    def emit(**kw: Any) -> None:
        rows_acc.append({
            'branch_location_code': lc,
            'warehouse_loc_key': lk,
            'wh_site_label': kw.get('wh_site_label', ''),
            'theoretical_basis': basis,
            'tree': kw.get('tree', ''),
            'store': kw.get('store', ''),
            'rack': kw.get('rack', ''),
            'shelf': kw.get('shelf', ''),
            'bin': kw.get('bin', ''),
            'storage_id': kw.get('storage_id', ''),
            'itemcode': kw.get('itemcode', ''),
            'itemname': kw.get('itemname', ''),
            'qty': kw.get('qty', ''),
            'lot_id': kw.get('lot_id', ''),
            'batch_no': kw.get('batch_no', ''),
            'expiry_date': kw.get('expiry_date', ''),
        })

    def walk_store(nodes: List[Dict[str, Any]], store_name: str) -> None:
        for n in nodes or []:
            k = str(n.get('kind') or '')
            if k == 'store':
                walk_store(cast(List[Dict[str, Any]], n.get('children') or []), str(n.get('label') or ''))
            elif k == 'item':
                emit(tree='store_ledger', wh_site_label='', store=store_name, rack='', shelf='', bin='',
                     storage_id='', itemcode=n.get('itemcode', ''), itemname=n.get('itemname', ''),
                     qty=n.get('qty', ''), lot_id='', batch_no='', expiry_date='')

    def walk_wh(nodes: List[Dict[str, Any]], wh_site_lbl: str, rack: str, shelf: str, bin_code: str) -> None:
        for n in nodes or []:
            k = str(n.get('kind') or '')
            ch = cast(List[Dict[str, Any]], n.get('children') or [])
            if k == 'wh_site':
                desc = str(n.get('label') or n.get('loc_key') or '').strip() or wh_site_lbl
                walk_wh(ch, desc, rack, shelf, bin_code)
            elif k == 'rack':
                walk_wh(ch, wh_site_lbl, str(n.get('label') or ''), shelf, bin_code)
            elif k == 'shelf':
                walk_wh(ch, wh_site_lbl, rack, str(n.get('label') or ''), bin_code)
            elif k == 'bin':
                walk_wh(ch, wh_site_lbl, rack, shelf, str(n.get('label') or ''))
            elif k == 'item':
                emit(tree='warehouse_bin', wh_site_label=wh_site_lbl, store='', rack=rack, shelf=shelf, bin=bin_code,
                     storage_id=n.get('storage_id', ''), itemcode=n.get('itemcode', ''), itemname=n.get('itemname', ''),
                     qty=n.get('qty', ''), lot_id='', batch_no='', expiry_date='')
                for lot in ch:
                    if str(lot.get('kind')) != 'lot':
                        continue
                    emit(tree='warehouse_lot', wh_site_label=wh_site_lbl, store='', rack=rack, shelf=shelf, bin=bin_code,
                         storage_id=n.get('storage_id', ''), itemcode=n.get('itemcode', ''), itemname=n.get('itemname', ''),
                         qty=lot.get('qty', ''), lot_id=lot.get('lot_id', ''), batch_no=lot.get('batch_no', ''),
                         expiry_date=lot.get('expiry_date', ''))

    walk_store(cast(List[Dict[str, Any]], payload.get('store_tree') or []), '')
    ws_fallback = str(payload.get('warehouse_site_label') or '').strip()
    walk_wh(cast(List[Dict[str, Any]], payload.get('warehouse_tree') or []), ws_fallback, '', '', '')
    return rows_acc


STOCK_VERIFICATION_TOL = 0.001


def _sv_qty_map(rows: List[Dict[str, Any]], key: str='itemcode', val: str='qty') -> Dict[int, float]:
    out: Dict[int, float] = {}
    for r in rows or []:
        try:
            ic = int(r.get(key) or 0)
        except (TypeError, ValueError):
            continue
        if ic <= 0:
            continue
        try:
            out[ic] = float(r.get(val) or 0)
        except (TypeError, ValueError):
            out[ic] = 0.0
    return out


def _sv_warehouse_ids_for_branch(location_code: int, db_key: Optional[str]=None) -> List[int]:
    ids: List[int] = []
    for r in list_warehouse_master_rows(db_key) or []:
        try:
            if int(r.get('locationcode') or 0) != int(location_code):
                continue
            wid = int(r.get('warehouse_id') or 0)
            if wid > 0 and wid not in ids:
                ids.append(wid)
        except (TypeError, ValueError):
            continue
    if ids:
        return ids
    if ensure_warehouse_stock_table(db_key=db_key) and _table_exists(WAREHOUSE_STOCK_TABLE, db_key=db_key):
        try:
            rows = _safe_rows(
                f'SELECT DISTINCT WAREHOUSE_ID AS warehouse_id FROM {WAREHOUSE_STOCK_TABLE} WHERE LOCATIONCODE = :loc',
                {'loc': int(location_code)},
                db_key=db_key,
            )
            for r in rows or []:
                try:
                    wid = int(r.get('warehouse_id') or 0)
                    if wid > 0 and wid not in ids:
                        ids.append(wid)
                except (TypeError, ValueError):
                    pass
        except Exception:
            pass
    return ids


def _sv_itemmaster_qty_map(location_code: int, db_key: Optional[str]=None, *, item_code: Optional[int]=None) -> Dict[int, Dict[str, Any]]:
    im_tbl = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im_tbl:
        return {}
    ic_col = _detect_column(im_tbl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    nm_col = _detect_column(im_tbl, ['ITEMNAME', 'ITEM_NAME', 'itemname'])
    lc_col = _detect_column(im_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    st_col = _detect_column(im_tbl, ['CURRENTSTOCK', 'CURRENT_STOCK', 'STOCK'])
    if not ic_col or not lc_col or not st_col:
        return {}
    item_clause = ''
    params: Dict[str, Any] = {'loc': int(location_code)}
    if item_code is not None:
        try:
            params['ic'] = int(item_code)
            item_clause = f' AND im.{ic_col} = :ic'
        except (TypeError, ValueError):
            pass
    nm_expr = f'im.{nm_col}' if nm_col else 'NULL'
    q = f"""
        SELECT im.{ic_col} AS itemcode, {nm_expr} AS itemname, NVL(im.{st_col}, 0) AS qty
        FROM {im_tbl} im
        WHERE im.{lc_col} = :loc{item_clause}
    """
    try:
        rows = _safe_rows(q, params, db_key=db_key) or []
    except Exception:
        return {}
    out: Dict[int, Dict[str, Any]] = {}
    for r in rows:
        try:
            ic = int(r.get('itemcode') or 0)
        except (TypeError, ValueError):
            continue
        if ic <= 0:
            continue
        out[ic] = {'itemname': str(r.get('itemname') or '').strip(), 'qty': float(r.get('qty') or 0)}
    return out


def _sv_warehouse_stock_qty_map(location_code: int, warehouse_id: Optional[int]=None, db_key: Optional[str]=None, *, item_code: Optional[int]=None) -> Dict[int, float]:
    if not ensure_warehouse_stock_table(db_key=db_key) or not _table_exists(WAREHOUSE_STOCK_TABLE, db_key=db_key):
        return {}
    params: Dict[str, Any] = {'loc': int(location_code)}
    wh_clause = ''
    if warehouse_id is not None:
        try:
            params['wid'] = int(warehouse_id)
            wh_clause = ' AND ws.WAREHOUSE_ID = :wid'
        except (TypeError, ValueError):
            pass
    item_clause = ''
    if item_code is not None:
        try:
            params['ic'] = int(item_code)
            item_clause = ' AND ws.ITEMCODE = :ic'
        except (TypeError, ValueError):
            pass
    q = f"""
        SELECT ws.ITEMCODE AS itemcode, SUM(NVL(ws.QTY, 0)) AS qty
        FROM {WAREHOUSE_STOCK_TABLE} ws
        WHERE ws.LOCATIONCODE = :loc{wh_clause}{item_clause}
        GROUP BY ws.ITEMCODE
    """
    try:
        return _sv_qty_map(_safe_rows(q, params, db_key=db_key) or [])
    except Exception:
        return {}


def _sv_bin_stock_qty_map(location_code: int, warehouse_id: Optional[int]=None, db_key: Optional[str]=None, *, item_code: Optional[int]=None) -> Dict[int, float]:
    if not ensure_bin_stock_tables(db_key=db_key) or not _table_exists(BIN_STOCK_TABLE, db_key=db_key):
        return {}
    bs_cols = {c.upper() for c in (_get_table_columns(BIN_STOCK_TABLE) or [])}
    if 'WAREHOUSE_ID' not in bs_cols:
        return {}
    params: Dict[str, Any] = {}
    wh_clause = ''
    if warehouse_id is not None:
        try:
            params['wid'] = int(warehouse_id)
            wh_clause = ' AND b.WAREHOUSE_ID = :wid'
        except (TypeError, ValueError):
            pass
    else:
        wh_ids = _sv_warehouse_ids_for_branch(location_code, db_key)
        if not wh_ids:
            return {}
        placeholders = []
        for i, wid in enumerate(wh_ids):
            k = f'w{i}'
            params[k] = wid
            placeholders.append(f':{k}')
        wh_clause = f" AND b.WAREHOUSE_ID IN ({', '.join(placeholders)})"
    item_clause = ''
    if item_code is not None:
        try:
            params['ic'] = int(item_code)
            item_clause = ' AND b.ITEMCODE = :ic'
        except (TypeError, ValueError):
            pass
    q = f"""
        SELECT b.ITEMCODE AS itemcode, SUM(NVL(b.QTY, 0)) AS qty
        FROM {BIN_STOCK_TABLE} b
        WHERE 1=1{wh_clause}{item_clause}
        GROUP BY b.ITEMCODE
    """
    try:
        return _sv_qty_map(_safe_rows(q, params, db_key=db_key) or [])
    except Exception:
        return {}


def _sv_lot_balance_qty_map(location_code: int, db_key: Optional[str]=None, *, item_code: Optional[int]=None) -> Dict[int, float]:
    if not ensure_item_lot_tables() or not _table_exists(ITEM_LOT_TABLE, db_key=db_key) or not _table_exists(ITEM_LOT_BALANCE_TABLE, db_key=db_key):
        return {}
    params: Dict[str, Any] = {'loc': int(location_code)}
    item_clause = ''
    if item_code is not None:
        try:
            params['ic'] = int(item_code)
            item_clause = ' AND l.ITEMCODE = :ic'
        except (TypeError, ValueError):
            pass
    q = f"""
        SELECT l.ITEMCODE AS itemcode, SUM(NVL(bal.QTY, 0)) AS qty
        FROM {ITEM_LOT_TABLE} l
        JOIN {ITEM_LOT_BALANCE_TABLE} bal ON bal.LOT_ID = l.LOT_ID
        WHERE l.LOCATIONCODE = :loc{item_clause}
        GROUP BY l.ITEMCODE
    """
    try:
        return _sv_qty_map(_safe_rows(q, params, db_key=db_key) or [])
    except Exception:
        return {}


def _sv_lot_bin_qty_map(location_code: int, warehouse_id: Optional[int]=None, db_key: Optional[str]=None, *, item_code: Optional[int]=None) -> Dict[int, float]:
    if not ensure_item_lot_tables() or not _table_exists(ITEM_LOT_TABLE, db_key=db_key) or not _table_exists(ITEM_LOT_BIN_TABLE, db_key=db_key):
        return {}
    join_wh = ''
    params: Dict[str, Any] = {'loc': int(location_code)}
    if warehouse_id is not None and _table_exists(WAREHOUSE_STORAGE_TABLE, db_key=db_key):
        try:
            params['wid'] = int(warehouse_id)
            join_wh = f' JOIN {WAREHOUSE_STORAGE_TABLE} w ON w.STORAGE_ID = lb.STORAGE_ID AND w.WAREHOUSE_ID = :wid'
        except (TypeError, ValueError):
            join_wh = ''
    item_clause = ''
    if item_code is not None:
        try:
            params['ic'] = int(item_code)
            item_clause = ' AND l.ITEMCODE = :ic'
        except (TypeError, ValueError):
            pass
    q = f"""
        SELECT l.ITEMCODE AS itemcode, SUM(NVL(lb.QTY, 0)) AS qty
        FROM {ITEM_LOT_TABLE} l
        JOIN {ITEM_LOT_BIN_TABLE} lb ON lb.LOT_ID = l.LOT_ID
        {join_wh}
        WHERE l.LOCATIONCODE = :loc{item_clause}
        GROUP BY l.ITEMCODE
    """
    try:
        return _sv_qty_map(_safe_rows(q, params, db_key=db_key) or [])
    except Exception:
        return {}


def _sv_lot_at_warehouse_qty_map(location_code: int, warehouse_id: int, db_key: Optional[str]=None, *, item_code: Optional[int]=None) -> Dict[int, float]:
    if not ensure_item_lot_tables() or not _table_exists(ITEM_LOT_TABLE, db_key=db_key):
        return {}
    il_cols_u = {c.upper() for c in (_get_table_columns(ITEM_LOT_TABLE) or [])}
    ic_filter = ''
    bind: Dict[str, Any] = {'loc': int(location_code), 'wid': int(warehouse_id)}
    if item_code is not None:
        try:
            bind['ic'] = int(item_code)
            ic_filter = ' AND l.ITEMCODE = :ic'
        except (TypeError, ValueError):
            pass
    union_sql = _item_lot_qty_at_warehouse_union_sql(il_cols_u, ic_filter)
    if not union_sql:
        return {}
    q = f"""
        SELECT itemcode, SUM(qty) AS qty
        FROM ({union_sql})
        GROUP BY itemcode
    """
    try:
        return _sv_qty_map(_safe_rows(q, bind, db_key=db_key) or [])
    except Exception:
        return {}


def _sv_near(a: float, b: float, tol: float=STOCK_VERIFICATION_TOL) -> bool:
    return abs(float(a) - float(b)) <= tol


def _sv_active_verification_rules(
    *,
    wh_stock_enabled: bool,
    bin_verify_enabled: bool,
    lot_verify_enabled: bool,
    itemjournal_enabled: bool,
    warehouse_scoped: bool,
) -> List[str]:
    """Human-readable rules applied for this branch (gated by LOCATIONMASTER flags)."""
    rules: List[str] = []
    if itemjournal_enabled:
        rules.append('Item master CURRENTSTOCK = SUM(ITEMJOURNAL.QTY) at branch (net signed movements).')
    if wh_stock_enabled:
        rules.append('Item master CURRENTSTOCK = sum of WAREHOUSE_STOCK at branch (all warehouses).')
        if warehouse_scoped and itemjournal_enabled:
            rules.append('WAREHOUSE_STOCK (scoped) = SUM(ITEMJOURNAL.QTY) for that warehouse when WAREHOUSE_ID/code is set.')
    if bin_verify_enabled:
        rules.append('WAREHOUSE_STOCK = sum of BIN_STOCK in that warehouse (BIN_TRACKING on).')
    if lot_verify_enabled and wh_stock_enabled:
        rules.append('WAREHOUSE_STOCK = lot-derived qty at warehouse (BATCH_TRACKING on).')
    if lot_verify_enabled:
        rules.append('Lot balance = qty in ITEM_LOT_BIN + unallocated ITEM_LOT_BALANCE (BATCH_TRACKING on).')
    return rules


def _iv_normalize_cost_method(raw: Optional[str]) -> str:
    k = (raw or '').strip().lower().replace(' ', '_').replace('-', '_')
    if k in ('landing', 'landing_cost', 'landingcost'):
        return 'landing'
    if k in ('cost', 'costprice', 'cost_price', 'last_purchase', 'lastpurchase'):
        return 'cost'
    return 'average'


def _iv_unit_cost_sql(im_alias: str, im_cols: Set[str], cost_method: str) -> str:
    """Unit cost expression from ITEMMASTER columns."""
    method = _iv_normalize_cost_method(cost_method)

    def _col(*names: str) -> Optional[str]:
        for n in names:
            if n in im_cols:
                return f'{im_alias}.{n}'
        return None

    avg = _col('AVERAGECOST', 'AVERAGE_COST', 'AVGCOST')
    land = _col('LANDINGCOST', 'LANDING_COST')
    cost = _col('COSTPRICE', 'COST_PRICE', 'COST')
    if method == 'landing':
        chain = [c for c in (land, avg, cost) if c]
    elif method == 'cost':
        chain = [c for c in (cost, avg, land) if c]
    else:
        chain = [c for c in (avg, land, cost) if c]
    if not chain:
        return '0'
    expr = '0'
    for col in reversed(chain):
        expr = f'NVL({col}, {expr})'
    return expr


def get_inventory_valuation_report(
    location_code: int,
    *,
    warehouse_id: Optional[int] = None,
    search: Optional[str] = None,
    barcode: Optional[str] = None,
    item_code: Optional[int] = None,
    category_code: Optional[int] = None,
    cost_method: str = 'average',
    include_zero: bool = False,
    limit: int = 200,
    offset: int = 0,
    db_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Inventory valuation rows for a branch, optionally scoped to one warehouse/store.
    Uses WAREHOUSE_STOCK when enabled; otherwise ITEMMASTER branch stock.
    """
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        lc = 1
    wid: Optional[int] = None
    if warehouse_id is not None:
        try:
            wv = int(warehouse_id)
            if wv > 0:
                wid = wv
        except (TypeError, ValueError):
            wid = None

    wh_label = 'All stores (branch total)'
    wh_code = ''
    if wid:
        wh_row = get_warehouse_master_by_id(wid, db_key)
        if wh_row:
            wh_code = str(wh_row.get('warehouse_code') or '').strip()
            wh_name = str(wh_row.get('warehouse_name') or '').strip()
            wh_label = (f'{wh_code} — {wh_name}' if wh_code and wh_name else wh_code or wh_name or str(wid))
        else:
            wh_label = str(wid)

    im_tbl = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im_tbl:
        return _iv_empty_valuation_payload(lc, wid, wh_label, wh_code, cost_method)
    im_cols = {str(c or '').upper() for c in (_get_table_columns(im_tbl) or [])}
    im_ic = _detect_column(im_tbl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    im_nm = _detect_column(im_tbl, ['ITEMNAME', 'ITEM_NAME', 'itemname'])
    im_lc = _detect_column(im_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    im_uom = _detect_column(im_tbl, ['BASEUOM', 'BASE_UOM', 'baseuom'])
    im_cat = _detect_column(im_tbl, ['CATEGORYCODE', 'CATEGORY_CODE', 'categorycode'])
    if not im_ic:
        return _iv_empty_valuation_payload(lc, wid, wh_label, wh_code, cost_method)

    unit_cost_sql = _iv_unit_cost_sql('im', im_cols, cost_method)
    from db.itemmaster_core import _itemmaster_stock_qty_sql
    branch_qty_sql = _itemmaster_stock_qty_sql(im_cols, 'im')
    wh_enabled = _iv_location_warehouse_stock_enabled(lc, db_key)

    where_parts = ['1=1']
    params: Dict[str, Any] = {'loc': lc}
    if im_lc:
        where_parts.append(f'im.{im_lc} = :loc')
    if item_code is not None:
        try:
            params['ic'] = int(item_code)
            where_parts.append(f'im.{im_ic} = :ic')
        except (TypeError, ValueError):
            pass
    if category_code is not None and im_cat:
        try:
            params['cat'] = int(category_code)
            where_parts.append(f'im.{im_cat} = :cat')
        except (TypeError, ValueError):
            pass
    qsearch = (search or '').strip()
    if qsearch:
        params['q'] = f'%{qsearch}%'
        name_clause = f" OR UPPER(im.{im_nm}) LIKE UPPER(:q)" if im_nm else ''
        where_parts.append(f"(TO_CHAR(im.{im_ic}) LIKE :q{name_clause})")

    bc_filter = (barcode or '').strip()
    if bc_filter:
        params['iv_bc_like'] = f'%{bc_filter.upper()}%'
        bc_clauses: List[str] = []
        im_bc_col = _detect_column(im_tbl, ['MANUFACTURERID', 'MANUFACTURER_ID', 'manufacturerid', 'BARCODE', 'barcode', 'RAWABICODE'])
        if im_bc_col:
            bc_clauses.append(f"UPPER(TRIM(TO_CHAR(im.{im_bc_col}))) LIKE :iv_bc_like")
        if _table_exists('ITEMALTERNATEUOMMAP', db_key=db_key):
            alt_loc = f'alt.LOCATIONCODE = :loc' if im_lc else '1=1'
            bc_clauses.append(
                f"EXISTS (SELECT 1 FROM ITEMALTERNATEUOMMAP alt "
                f"WHERE {alt_loc} AND alt.ITEMCODE = im.{im_ic} "
                f"AND UPPER(TRIM(NVL(alt.MANUFACTURERID, ''))) LIKE :iv_bc_like)"
            )
        if bc_clauses:
            where_parts.append('(' + ' OR '.join(bc_clauses) + ')')

    cat_name_sel = "CAST(NULL AS VARCHAR2(200)) AS categoryname"
    cat_join = ''
    if im_cat:
        cat_tbl = _detect_table(['CATEGORY', 'category'])
        if cat_tbl:
            cat_code = _detect_column(cat_tbl, ['CODE', 'code'])
            cat_flag = _detect_column(cat_tbl, ['FLAG', 'flag'])
            cat_name = _detect_column(cat_tbl, ['NAME', 'name', 'DESCRIPTION'])
            if cat_code and cat_name:
                flag_clause = f" AND cat.{cat_flag} = 'C'" if cat_flag else ''
                cat_join = f" LEFT JOIN {cat_tbl} cat ON cat.{cat_code} = im.{im_cat}{flag_clause}"
                cat_name_sel = f'cat.{cat_name} AS categoryname'

    uom_sel = f'im.{im_uom} AS baseuom' if im_uom else "CAST(NULL AS VARCHAR2(20)) AS baseuom"
    cat_sel = f'im.{im_cat} AS categorycode' if im_cat else 'CAST(NULL AS NUMBER) AS categorycode'
    zero_clause = '' if include_zero else f' AND ABS(NVL(qty, 0)) > 0.0001'

    if wh_enabled and wid and _table_exists(WAREHOUSE_STOCK_TABLE, db_key=db_key):
        wm_tbl = resolve_warehouse_master_table(db_key)
        wh_code_sel = "CAST(NULL AS VARCHAR2(50)) AS warehouse_code"
        wh_name_sel = "CAST(NULL AS VARCHAR2(200)) AS warehouse_name"
        wm_join = ''
        if wm_tbl:
            wm_join = f' LEFT JOIN {wm_tbl} wm ON wm.WAREHOUSE_ID = ws.WAREHOUSE_ID'
            wh_code_sel = 'TRIM(wm.WAREHOUSE_CODE) AS warehouse_code'
            wh_name_sel = 'TRIM(wm.WAREHOUSE_NAME) AS warehouse_name'
        ws_where = ['ws.LOCATIONCODE = :loc', 'ws.WAREHOUSE_ID = :wid']
        params['wid'] = wid
        if item_code is not None and 'ic' in params:
            ws_where.append('ws.ITEMCODE = :ic')
        base_sql = f"""
            SELECT
                ws.ITEMCODE AS itemcode,
                {f'im.{im_nm}' if im_nm else 'CAST(NULL AS VARCHAR2(500))'} AS itemname,
                NVL(ws.QTY, 0) AS qty,
                {unit_cost_sql} AS unitcost,
                NVL(ws.QTY, 0) * ({unit_cost_sql}) AS stockvalue,
                {wh_code_sel},
                {wh_name_sel},
                {cat_sel},
                {cat_name_sel},
                {uom_sel}
            FROM {WAREHOUSE_STOCK_TABLE} ws
            INNER JOIN {im_tbl} im ON im.{im_ic} = ws.ITEMCODE
                {f' AND im.{im_lc} = ws.LOCATIONCODE' if im_lc else ''}
            {wm_join}
            {cat_join}
            WHERE {' AND '.join(ws_where)}
              AND {' AND '.join(where_parts[1:] if where_parts[0] == '1=1' else where_parts)}
        """
    elif wh_enabled and _table_exists(WAREHOUSE_STOCK_TABLE, db_key=db_key):
        base_sql = f"""
            SELECT
                ws.ITEMCODE AS itemcode,
                {f'MAX(im.{im_nm})' if im_nm else 'CAST(NULL AS VARCHAR2(500))'} AS itemname,
                SUM(NVL(ws.QTY, 0)) AS qty,
                MAX({unit_cost_sql}) AS unitcost,
                SUM(NVL(ws.QTY, 0) * ({unit_cost_sql})) AS stockvalue,
                CAST(NULL AS VARCHAR2(50)) AS warehouse_code,
                CAST('All stores' AS VARCHAR2(200)) AS warehouse_name,
                MAX({cat_sel.replace(' AS categorycode', '')}) AS categorycode,
                MAX({cat_name_sel.replace(' AS categoryname', '')}) AS categoryname,
                MAX({uom_sel.replace(' AS baseuom', '')}) AS baseuom
            FROM {WAREHOUSE_STOCK_TABLE} ws
            INNER JOIN {im_tbl} im ON im.{im_ic} = ws.ITEMCODE
                {f' AND im.{im_lc} = ws.LOCATIONCODE' if im_lc else ''}
            {cat_join}
            WHERE ws.LOCATIONCODE = :loc
              AND {' AND '.join(where_parts[1:] if where_parts[0] == '1=1' else where_parts)}
            GROUP BY ws.ITEMCODE
        """
    else:
        im_where = list(where_parts)
        if im_lc and f'im.{im_lc} = :loc' not in im_where:
            im_where.append(f'im.{im_lc} = :loc')
        base_sql = f"""
            SELECT
                im.{im_ic} AS itemcode,
                {f'im.{im_nm}' if im_nm else 'CAST(NULL AS VARCHAR2(500))'} AS itemname,
                {branch_qty_sql} AS qty,
                {unit_cost_sql} AS unitcost,
                ({branch_qty_sql}) * ({unit_cost_sql}) AS stockvalue,
                CAST(NULL AS VARCHAR2(50)) AS warehouse_code,
                CAST('Branch total' AS VARCHAR2(200)) AS warehouse_name,
                {cat_sel},
                {cat_name_sel},
                {uom_sel}
            FROM {im_tbl} im
            {cat_join}
            WHERE {' AND '.join(im_where)}
        """

    filtered_sql = f"SELECT * FROM ({base_sql}) v WHERE 1=1{zero_clause}"
    summary_sql = f"""
        SELECT
            COUNT(*) AS item_count,
            NVL(SUM(qty), 0) AS total_qty,
            NVL(SUM(stockvalue), 0) AS total_value
        FROM ({filtered_sql}) s
    """
    try:
        summary_rows = _safe_rows(summary_sql, params, db_key=db_key) or [{}]
        s0 = summary_rows[0] or {}
        total_count = int(s0.get('item_count') or 0)
        total_qty = float(s0.get('total_qty') or 0)
        total_value = round(float(s0.get('total_value') or 0), 2)
    except Exception as exc:
        print(f'[ERROR get_inventory_valuation_report summary] {exc}')
        raise

    off = max(0, int(offset or 0))
    lim = max(1, min(int(limit or 200), 500)) if limit else 0
    page_rows: List[Dict[str, Any]] = []
    if total_count > 0:
        end_row = off + lim if lim > 0 else total_count + off
        page_sql = f"""
            SELECT * FROM (
                SELECT inner_q.*, ROWNUM AS rn FROM (
                    SELECT * FROM ({filtered_sql}) ORDER BY itemcode
                ) inner_q WHERE ROWNUM <= :end_row
            ) WHERE rn > :start_row
        """
        page_params = dict(params)
        page_params['start_row'] = off
        page_params['end_row'] = end_row
        try:
            raw_rows = _safe_rows(page_sql, page_params, db_key=db_key) or []
            for r in raw_rows:
                qty = float(r.get('qty') or 0)
                unit = float(r.get('unitcost') or 0)
                page_rows.append({
                    'itemcode': r.get('itemcode'),
                    'itemname': str(r.get('itemname') or '').strip(),
                    'qty': round(qty, 4),
                    'unitcost': round(unit, 4),
                    'stockvalue': round(float(r.get('stockvalue') or qty * unit), 2),
                    'warehouse_code': str(r.get('warehouse_code') or wh_code or '').strip(),
                    'warehouse_name': str(r.get('warehouse_name') or wh_label or '').strip(),
                    'categorycode': r.get('categorycode'),
                    'categoryname': str(r.get('categoryname') or '').strip(),
                    'baseuom': str(r.get('baseuom') or '').strip(),
                })
        except Exception as exc:
            print(f'[ERROR get_inventory_valuation_report page] {exc}')
            raise

    per_page = lim if lim > 0 else max(total_count, 1)
    total_pages = max(1, (total_count + per_page - 1) // per_page) if per_page else 1
    page_num = (off // per_page) + 1 if per_page else 1
    return {
        'location_code': lc,
        'warehouse_id': wid,
        'warehouse_label': wh_label,
        'warehouse_code': wh_code,
        'cost_method': _iv_normalize_cost_method(cost_method),
        'warehouse_stock_enabled': wh_enabled,
        'summary': {
            'item_count': total_count,
            'total_qty': round(total_qty, 4),
            'total_value': total_value,
        },
        'pagination': {
            'offset': off,
            'limit': lim,
            'page': page_num,
            'per_page': per_page,
            'total_count': total_count,
            'total_pages': total_pages,
            'has_more': off + len(page_rows) < total_count,
        },
        'total_count': total_count,
        'total_pages': total_pages,
        'page': page_num,
        'per_page': per_page,
        'rows': page_rows,
    }


def _iv_location_warehouse_stock_enabled(location_code: int, db_key: Optional[str] = None) -> bool:
    """True when branch uses WAREHOUSE_STOCK for on-hand qty (not ITEMMASTER store fields only)."""
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        lc = 1
    return bool(
        is_location_warehouse_enabled(lc, db_key)
        and ensure_warehouse_stock_table(db_key=db_key)
        and _table_exists(WAREHOUSE_STOCK_TABLE, db_key=db_key)
    )


def _iv_store_pivot_columns(im_cols: Set[str]) -> List[Dict[str, Any]]:
    store_cols = sorted(
        [c for c in im_cols if re.fullmatch(r'STORE\d+', str(c or '').upper())],
        key=lambda x: int(str(x)[5:]),
    )
    return [{'warehouse_id': None, 'code': c, 'label': c, 'name': c} for c in store_cols]


def _iv_pivot_finalize_row_totals(
    row: Dict[str, Any],
    sq: Dict[str, float],
    col_codes: List[str],
    *,
    base_qty: float,
    unit: float,
) -> None:
    """Apply store breakdown; branch total from SQL when per-store lookup is empty."""
    sq_out = dict(sq or {})
    store_sum = round(sum(float(sq_out.get(c) or 0) for c in col_codes), 4)
    base_q = round(float(base_qty or 0), 4)
    if abs(store_sum) > 0.0001:
        total_qty = store_sum
    else:
        total_qty = base_q
    unit_f = float(unit or 0)
    row['store_qty'] = sq_out
    row['total_qty'] = round(total_qty, 4)
    row['total_value'] = round(total_qty * unit_f, 2)


def _iv_pivot_warehouse_stock_breakdown(
    location_code: int,
    item_codes: List[int],
    db_key: Optional[str] = None,
    *,
    batch_size: int = 400,
) -> Dict[int, Dict[str, float]]:
    """Item → {WH_CODE: qty} from WAREHOUSE_STOCK (batched IN lists for large exports)."""
    wm_tbl = resolve_warehouse_master_table(db_key)
    if not wm_tbl or not item_codes:
        return {}
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        lc = 1
    uniq = sorted({int(x) for x in item_codes if int(x) > 0})
    if not uniq:
        return {}
    out: Dict[int, Dict[str, float]] = {}
    for off in range(0, len(uniq), batch_size):
        chunk = uniq[off: off + batch_size]
        bind: Dict[str, Any] = {'loc': lc}
        in_parts: List[str] = []
        for idx, ic in enumerate(chunk):
            key = f'ic{idx}'
            bind[key] = ic
            in_parts.append(f':{key}')
        q = f"""
            SELECT ws.ITEMCODE AS itemcode,
                   UPPER(TRIM(wm.WAREHOUSE_CODE)) AS wh_code,
                   SUM(NVL(ws.QTY, 0)) AS qty
            FROM {WAREHOUSE_STOCK_TABLE} ws
            INNER JOIN {wm_tbl} wm
                ON wm.WAREHOUSE_ID = ws.WAREHOUSE_ID
               AND wm.LOCATIONCODE = ws.LOCATIONCODE
            WHERE ws.LOCATIONCODE = :loc
              AND ws.ITEMCODE IN ({', '.join(in_parts)})
            GROUP BY ws.ITEMCODE, UPPER(TRIM(wm.WAREHOUSE_CODE))
        """
        for d in _safe_rows(q, bind, db_key=db_key) or []:
            try:
                ic_i = int(d.get('itemcode'))
            except (TypeError, ValueError):
                continue
            wh_c = str(d.get('wh_code') or '').strip().upper()
            if not wh_c:
                continue
            out.setdefault(ic_i, {})[wh_c] = float(d.get('qty') or 0)
    return out


def _iv_pivot_itemmaster_store_breakdown(
    location_code: int,
    item_codes: List[int],
    col_codes: List[str],
    im_tbl: str,
    im_cols: Set[str],
    db_key: Optional[str] = None,
    *,
    batch_size: int = 400,
) -> Dict[int, Dict[str, float]]:
    """Item → {STOREn: qty} from ITEMMASTER store columns (batched)."""
    im_ic = _detect_column(im_tbl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    im_lc = _detect_column(im_tbl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    if not im_ic or not item_codes or not col_codes:
        return {}
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        lc = 1
    sel_store = [c for c in col_codes if c in im_cols]
    if not sel_store:
        return {}
    uniq = sorted({int(x) for x in item_codes if int(x) > 0})
    out: Dict[int, Dict[str, float]] = {}
    for off in range(0, len(uniq), batch_size):
        chunk = uniq[off: off + batch_size]
        bind: Dict[str, Any] = {'loc': lc}
        in_parts: List[str] = []
        for idx, ic in enumerate(chunk):
            key = f'ic{idx}'
            bind[key] = ic
            in_parts.append(f':{key}')
        sel_parts = [f'im.{im_ic} AS itemcode']
        for col in sel_store:
            sel_parts.append(f'NVL(im.{col}, 0) AS {col.lower()}')
        where = [f'im.{im_ic} IN ({", ".join(in_parts)})']
        if im_lc:
            where.append(f'im.{im_lc} = :loc')
        q = f'SELECT {", ".join(sel_parts)} FROM {im_tbl} im WHERE {" AND ".join(where)}'
        for d in _safe_rows(q, bind, db_key=db_key) or []:
            try:
                ic_i = int(d.get('itemcode'))
            except (TypeError, ValueError):
                continue
            sq: Dict[str, float] = {}
            for col in sel_store:
                key = col.lower()
                sq[col] = round(float(d.get(key) if key in d else d.get(col) or 0), 4)
            out[ic_i] = sq
    return out


def _iv_warehouse_pivot_columns(location_code: int, im_cols: Set[str], db_key: Optional[str] = None) -> List[Dict[str, Any]]:
    """Pivot column codes aligned with qty source: WAREHOUSE_STOCK codes or ITEMMASTER STOREn."""
    if not _iv_location_warehouse_stock_enabled(location_code, db_key):
        return _iv_store_pivot_columns(im_cols)
    wm_tbl = resolve_warehouse_master_table(db_key)
    if wm_tbl:
        q = f"""
            SELECT wm.WAREHOUSE_ID AS warehouse_id,
                   TRIM(wm.WAREHOUSE_CODE) AS code,
                   TRIM(wm.WAREHOUSE_NAME) AS name
            FROM {wm_tbl} wm
            WHERE wm.LOCATIONCODE = :loc
              AND NVL(wm.IS_ACTIVE, 'Y') = 'Y'
              AND TRIM(wm.WAREHOUSE_CODE) IS NOT NULL
            ORDER BY UPPER(TRIM(wm.WAREHOUSE_CODE))
        """
        rows = _safe_rows(q, {'loc': int(location_code)}, db_key=db_key) or []
        out: List[Dict[str, Any]] = []
        seen: Set[str] = set()
        for r in rows:
            code = str(r.get('code') or '').strip().upper()
            if not code or code in seen:
                continue
            seen.add(code)
            try:
                wid = int(r.get('warehouse_id') or 0)
            except (TypeError, ValueError):
                wid = 0
            name = str(r.get('name') or '').strip()
            out.append({
                'warehouse_id': wid,
                'code': code,
                'label': code,
                'name': name,
            })
        if out:
            return out
    return _iv_store_pivot_columns(im_cols)


def get_inventory_valuation_pivot_report(
    location_code: int,
    *,
    warehouse_id: Optional[int] = None,
    search: Optional[str] = None,
    barcode: Optional[str] = None,
    item_code: Optional[int] = None,
    category_code: Optional[int] = None,
    cost_method: str = 'average',
    include_zero: bool = False,
    limit: int = 200,
    offset: int = 0,
    db_key: Optional[str] = None,
) -> Dict[str, Any]:
    """Item rows with qty per store column (WH001, SH002, …), total qty, unit cost, total value."""
    wid: Optional[int] = None
    if warehouse_id is not None:
        try:
            wv = int(warehouse_id)
            if wv > 0:
                wid = wv
        except (TypeError, ValueError):
            wid = None

    base = get_inventory_valuation_report(
        location_code,
        warehouse_id=wid,
        search=search,
        barcode=barcode,
        item_code=item_code,
        category_code=category_code,
        cost_method=cost_method,
        include_zero=include_zero,
        limit=limit,
        offset=offset,
        db_key=db_key,
    )
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        lc = 1

    im_tbl = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    im_cols: Set[str] = set()
    if im_tbl:
        im_cols = {str(c or '').upper() for c in (_get_table_columns(im_tbl) or [])}
    pivot_columns = _iv_warehouse_pivot_columns(lc, im_cols, db_key=db_key)
    if wid:
        wh_row = get_warehouse_master_by_id(wid, db_key)
        wh_code_filter = str((wh_row or {}).get('warehouse_code') or base.get('warehouse_code') or '').strip().upper()
        if wh_code_filter:
            pivot_columns = [
                c for c in pivot_columns
                if str(c.get('code') or '').strip().upper() == wh_code_filter
            ]
            if not pivot_columns:
                wh_name = str((wh_row or {}).get('warehouse_name') or '').strip()
                pivot_columns = [{'code': wh_code_filter, 'label': wh_code_filter, 'name': wh_name or wh_code_filter}]
    col_codes = [str(c.get('code') or '').strip().upper() for c in pivot_columns if c.get('code')]
    col_codes = [c for c in col_codes if c]

    page_rows: List[Dict[str, Any]] = []
    for r in base.get('rows') or []:
        try:
            ic = int(r.get('itemcode'))
        except (TypeError, ValueError):
            continue
        qty = float(r.get('qty') or 0)
        unit = float(r.get('unitcost') or 0)
        value = float(r.get('stockvalue') or qty * unit)
        store_qty = {code: 0.0 for code in col_codes}
        if wid and col_codes:
            store_qty[col_codes[0]] = round(qty, 4)
        page_rows.append({
            'itemcode': ic,
            'itemname': str(r.get('itemname') or '').strip(),
            'categorycode': r.get('categorycode'),
            'categoryname': str(r.get('categoryname') or '').strip(),
            'baseuom': str(r.get('baseuom') or '').strip(),
            'store_qty': store_qty,
            'total_qty': round(qty, 4),
            'unitcost': round(unit, 4),
            'total_value': round(value, 2),
        })

    wh_enabled = _iv_location_warehouse_stock_enabled(lc, db_key)
    if page_rows and col_codes and wh_enabled and not wid:
        ics = [int(r['itemcode']) for r in page_rows]
        by_item = _iv_pivot_warehouse_stock_breakdown(lc, ics, db_key)
        for row in page_rows:
            base_q = float(row.get('total_qty') or 0)
            unit = float(row.get('unitcost') or 0)
            ic_i = int(row['itemcode'])
            sq: Dict[str, float] = {}
            for code in col_codes:
                sq[code] = round(float((by_item.get(ic_i) or {}).get(code, 0)), 4)
            _iv_pivot_finalize_row_totals(row, sq, col_codes, base_qty=base_q, unit=unit)
    elif page_rows and col_codes and not wh_enabled and im_tbl and not wid:
        ics = [int(r['itemcode']) for r in page_rows]
        by_item = _iv_pivot_itemmaster_store_breakdown(
            lc, ics, col_codes, im_tbl, im_cols, db_key,
        )
        for row in page_rows:
            base_q = float(row.get('total_qty') or 0)
            unit = float(row.get('unitcost') or 0)
            ic_i = int(row['itemcode'])
            sq: Dict[str, float] = {}
            raw = by_item.get(ic_i) or {}
            for code in col_codes:
                sq[code] = round(float(raw.get(code) or 0), 4)
            _iv_pivot_finalize_row_totals(row, sq, col_codes, base_qty=base_q, unit=unit)

    store_totals = {code: 0.0 for code in col_codes}
    for row in page_rows:
        sq = row.get('store_qty') or {}
        for code in col_codes:
            store_totals[code] = round(store_totals.get(code, 0) + float(sq.get(code) or 0), 4)

    out = dict(base)
    out['view'] = 'pivot'
    out['warehouse_id'] = wid
    out['warehouse_label'] = str(base.get('warehouse_label') or ('All stores' if not wid else str(wid)))
    out['warehouse_code'] = str(base.get('warehouse_code') or '')
    out['pivot_columns'] = pivot_columns
    out['column_totals'] = {
        'store_qty': store_totals,
        'total_qty': round(sum(float(r.get('total_qty') or 0) for r in page_rows), 4),
        'total_value': round(sum(float(r.get('total_value') or 0) for r in page_rows), 2),
    }
    out['rows'] = page_rows
    return out


def _iv_empty_valuation_payload(
    location_code: int,
    warehouse_id: Optional[int],
    warehouse_label: str,
    warehouse_code: str,
    cost_method: str,
) -> Dict[str, Any]:
    return {
        'location_code': location_code,
        'warehouse_id': warehouse_id,
        'warehouse_label': warehouse_label,
        'warehouse_code': warehouse_code,
        'cost_method': _iv_normalize_cost_method(cost_method),
        'warehouse_stock_enabled': False,
        'summary': {'item_count': 0, 'total_qty': 0.0, 'total_value': 0.0},
        'pagination': {
            'offset': 0, 'limit': 200, 'page': 1, 'per_page': 200,
            'total_count': 0, 'total_pages': 1, 'has_more': False,
        },
        'total_count': 0,
        'total_pages': 1,
        'page': 1,
        'per_page': 200,
        'rows': [],
    }


def _sv_build_verification_row(
    ic: int,
    *,
    im_map: Dict[int, Any],
    wh_map: Dict[int, float],
    bin_map: Dict[int, float],
    lot_bal_map: Dict[int, float],
    lot_bin_map: Dict[int, float],
    lot_wh_map: Dict[int, float],
    wh_all_map: Dict[int, float],
    ij_branch_map: Dict[int, float],
    ij_wh_map: Dict[int, float],
    qsearch: str,
    include_zero: bool,
    mismatches_only: bool,
    wid: Optional[int],
    bin_verify_enabled: bool,
    lot_verify_enabled: bool,
    wh_stock_enabled: bool,
) -> Optional[Dict[str, Any]]:
    meta = im_map.get(ic) or {}
    itemname = str(meta.get('itemname') or '').strip()
    if qsearch and qsearch not in str(ic) and qsearch not in itemname.lower():
        return None
    im_qty = float((im_map.get(ic) or {}).get('qty', 0))
    wh_qty = float(wh_map.get(ic, 0))
    bin_qty = float(bin_map.get(ic, 0))
    lot_qty = float(lot_bal_map.get(ic, 0))
    lot_bin_qty = float(lot_bin_map.get(ic, 0))
    lot_unalloc = max(0.0, lot_qty - lot_bin_qty)
    lot_at_wh = float(lot_wh_map.get(ic, 0))
    wh_branch_total = float(wh_all_map.get(ic, 0))
    ij_branch_qty = float(ij_branch_map.get(ic, 0))
    ij_wh_qty = float(ij_wh_map.get(ic, 0))

    issues: List[str] = []
    if ij_branch_map and not _sv_near(im_qty, ij_branch_qty):
        if abs(im_qty) > STOCK_VERIFICATION_TOL and abs(ij_branch_qty) <= STOCK_VERIFICATION_TOL:
            issues.append(
                'Item master ≠ net item journal QTY (branch) — journal net is 0; '
                'check Item Journal for missing PURCHASE/SALES lines or REVERSAL pairs'
            )
        else:
            issues.append('Item master ≠ net item journal QTY (branch)')
    if wid and ij_wh_map and not _sv_near(wh_qty, ij_wh_qty):
        issues.append('Warehouse stock ≠ net item journal QTY (warehouse)')
    if bin_verify_enabled and not _sv_near(wh_qty, bin_qty):
        issues.append('Warehouse stock ≠ bin stock')
    if lot_verify_enabled and wh_stock_enabled and not _sv_near(wh_qty, lot_at_wh):
        issues.append('Warehouse stock ≠ lot-derived at warehouse')
    if lot_verify_enabled and not _sv_near(lot_qty, lot_bin_qty + lot_unalloc) and not _sv_near(lot_qty, lot_bin_qty):
        if abs(lot_qty - lot_bin_qty) > STOCK_VERIFICATION_TOL:
            issues.append('Lot balance ≠ qty in bins (check unallocated)')
    if wh_stock_enabled and not wid and not _sv_near(im_qty, wh_branch_total):
        issues.append('Item master current stock ≠ Σ warehouse stock')
    elif wh_stock_enabled and wid and not _sv_near(im_qty, wh_branch_total):
        issues.append('Item master (branch) ≠ Σ all warehouses — informational')

    has_stock = any(abs(x) > STOCK_VERIFICATION_TOL for x in (im_qty, wh_qty, bin_qty, lot_qty, lot_at_wh, ij_branch_qty))
    if not include_zero and not has_stock and not issues:
        return None
    status = 'ok'
    if issues:
        status = 'err' if any(
            '≠' in i and ('Warehouse' in i or 'Item master' in i or 'lot-derived' in i or 'item journal' in i)
            for i in issues
        ) else 'warn'
    if mismatches_only and not issues:
        return None
    return {
        'itemcode': ic,
        'itemname': itemname,
        'itemmaster_qty': round(im_qty, 4),
        'warehouse_qty': round(wh_qty, 4),
        'warehouse_branch_total': round(wh_branch_total, 4),
        'bin_qty': round(bin_qty, 4),
        'lot_qty': round(lot_qty, 4),
        'lot_bin_qty': round(lot_bin_qty, 4),
        'lot_unalloc_qty': round(lot_unalloc, 4),
        'lot_at_warehouse_qty': round(lot_at_wh, 4),
        'itemjournal_qty': round(ij_wh_qty if wid else ij_branch_qty, 4),
        'itemjournal_branch_qty': round(ij_branch_qty, 4),
        'delta_im_wh': round(im_qty - wh_branch_total, 4),
        'delta_im_ij': round(im_qty - ij_branch_qty, 4),
        'delta_wh_bin': round(wh_qty - bin_qty, 4) if bin_verify_enabled else None,
        'delta_wh_lot': round(wh_qty - lot_at_wh, 4) if (lot_verify_enabled and wh_stock_enabled) else None,
        'delta_wh_ij': round(wh_qty - ij_wh_qty, 4) if wid else None,
        'status': status,
        'issues': issues,
    }


def get_stock_verification_report(
    location_code: int,
    warehouse_id: Optional[int]=None,
    db_key: Optional[str]=None,
    *,
    include_zero: bool=False,
    mismatches_only: bool=False,
    item_code: Optional[int]=None,
    search: Optional[str]=None,
    limit: int=200,
    offset: int=0,
) -> Dict[str, Any]:
    """
    Compare ITEMMASTER.CURRENTSTOCK, WAREHOUSE_STOCK, BIN_STOCK, and lot quantities
    for one branch (optional single warehouse scope for WH/bin/lot-at-WH checks).
    """
    try:
        lc = int(location_code)
    except (TypeError, ValueError):
        lc = 1
    wid: Optional[int] = None
    if warehouse_id is not None:
        try:
            wv = int(warehouse_id)
            if wv > 0:
                wid = wv
        except (TypeError, ValueError):
            wid = None
    wh_label = ''
    if wid:
        wh_row = get_warehouse_master_by_id(wid, db_key)
        if wh_row:
            code = str(wh_row.get('warehouse_code') or '').strip()
            name = str(wh_row.get('warehouse_name') or '').strip()
            wh_label = (f'{code} - {name}' if code and name else code or name or str(wid))
        else:
            wh_label = str(wid)

    # Fresh LOCATIONMASTER reads (no 5-min cache) so disabled BIN/BATCH flags apply immediately.
    inv_wh = is_location_warehouse_enabled(lc, db_key)
    inv_bin = is_location_bin_tracking_enabled(lc, db_key) if inv_wh else False
    inv_bt = is_location_batch_tracking_enabled(lc, db_key)
    wh_stock_enabled = bool(inv_wh and _table_exists(WAREHOUSE_STOCK_TABLE, db_key=db_key))
    bin_verify_enabled = bool(
        inv_bin
        and wh_stock_enabled
        and _table_exists(WAREHOUSE_STORAGE_TABLE, db_key=db_key)
        and _table_exists(BIN_STOCK_TABLE, db_key=db_key)
    )
    lot_verify_enabled = bool(
        inv_bt
        and _table_exists(ITEM_LOT_TABLE, db_key=db_key)
        and _table_exists(ITEM_LOT_BALANCE_TABLE, db_key=db_key)
    )

    im_map = _sv_itemmaster_qty_map(lc, db_key, item_code=item_code)
    wh_map = _sv_warehouse_stock_qty_map(lc, wid, db_key, item_code=item_code) if wh_stock_enabled else {}
    bin_map = _sv_bin_stock_qty_map(lc, wid, db_key, item_code=item_code) if bin_verify_enabled else {}
    lot_bal_map: Dict[int, float] = {}
    lot_bin_map: Dict[int, float] = {}
    lot_wh_map: Dict[int, float] = {}
    if lot_verify_enabled:
        lot_bal_map = _sv_lot_balance_qty_map(lc, db_key, item_code=item_code)
        lot_bin_map = _sv_lot_bin_qty_map(lc, wid, db_key, item_code=item_code)
        if wid:
            lot_wh_map = _sv_lot_at_warehouse_qty_map(lc, wid, db_key, item_code=item_code)
        else:
            branch_wh_ids = _sv_warehouse_ids_for_branch(lc, db_key)
            lot_wh_map = _sv_lot_at_warehouses_qty_map(lc, branch_wh_ids, db_key, item_code=item_code)

    if wid and wh_stock_enabled:
        wh_all_map = _sv_warehouse_stock_qty_map(lc, None, db_key, item_code=item_code)
    else:
        wh_all_map = wh_map

    ij_branch_map = _sv_itemjournal_qty_map(lc, None, db_key, item_code=item_code)
    ij_wh_map = _sv_itemjournal_qty_map(lc, wid, db_key, item_code=item_code) if wid else ij_branch_map

    codes = _sv_collect_item_codes(
        im_map, wh_map, bin_map, lot_bal_map, lot_bin_map, lot_wh_map, ij_branch_map,
        include_zero=include_zero,
        item_code=item_code,
    )
    qsearch = (search or '').strip().lower()

    off = max(0, int(offset or 0))
    lim = int(limit) if limit else 0
    out_rows: List[Dict[str, Any]] = []
    mismatch_count = 0
    filtered_index = 0
    for ic in sorted(codes):
        row = _sv_build_verification_row(
            ic,
            im_map=im_map,
            wh_map=wh_map,
            bin_map=bin_map,
            lot_bal_map=lot_bal_map,
            lot_bin_map=lot_bin_map,
            lot_wh_map=lot_wh_map,
            wh_all_map=wh_all_map,
            ij_branch_map=ij_branch_map,
            ij_wh_map=ij_wh_map,
            qsearch=qsearch,
            include_zero=include_zero,
            mismatches_only=mismatches_only,
            wid=wid,
            bin_verify_enabled=bin_verify_enabled,
            lot_verify_enabled=lot_verify_enabled,
            wh_stock_enabled=wh_stock_enabled,
        )
        if row is None:
            continue
        if row.get('issues'):
            mismatch_count += 1
        if filtered_index >= off and (lim <= 0 or len(out_rows) < lim):
            out_rows.append(row)
        filtered_index += 1

    total_count = filtered_index
    per_page = lim if lim > 0 else max(total_count, 1)
    total_pages = max(1, (total_count + per_page - 1) // per_page) if per_page else 1
    page = (off // per_page) + 1 if per_page else 1

    return {
        'location_code': lc,
        'warehouse_id': wid,
        'warehouse_label': wh_label,
        'flags': {
            'itemmaster': bool(im_map),
            'warehouse_stock': wh_stock_enabled,
            'bin_stock': bin_verify_enabled,
            'lot_tables': lot_verify_enabled,
            'itemjournal': bool(ij_branch_map or _resolve_itemjournal_table(db_key)),
            'branch_batch_tracking': inv_bt,
            'branch_bin_tracking': inv_bin,
            'branch_warehouse_enable': inv_wh,
        },
        'branch_gates': {
            'warehouse_enable': inv_wh,
            'bin_tracking': inv_bin,
            'batch_tracking': inv_bt,
        },
        'verification_enabled': {
            'warehouse_vs_bin': bin_verify_enabled,
            'warehouse_vs_lot': bool(lot_verify_enabled and wh_stock_enabled),
            'lot_balance_vs_bins': lot_verify_enabled,
        },
        'rules': _sv_active_verification_rules(
            wh_stock_enabled=wh_stock_enabled,
            bin_verify_enabled=bin_verify_enabled,
            lot_verify_enabled=lot_verify_enabled,
            itemjournal_enabled=bool(ij_branch_map or _resolve_itemjournal_table(db_key)),
            warehouse_scoped=bool(wid),
        ),
        'summary': {
            'rows': total_count,
            'mismatch_count': mismatch_count,
            'items_scanned': len(codes),
        },
        'pagination': {
            'offset': off,
            'limit': lim if lim > 0 else total_count,
            'page': page,
            'per_page': per_page,
            'total_count': total_count,
            'total_pages': total_pages,
            'has_more': off + len(out_rows) < total_count,
        },
        'total_count': total_count,
        'total_pages': total_pages,
        'page': page,
        'per_page': per_page,
        'rows': out_rows,
    }


def flatten_stock_verification_export_rows(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(payload, dict):
        return []
    lc = payload.get('location_code')
    wid = payload.get('warehouse_id') or ''
    wh_lbl = payload.get('warehouse_label') or ''
    out: List[Dict[str, Any]] = []
    for r in payload.get('rows') or []:
        out.append({
            'location_code': lc,
            'warehouse_id': wid,
            'warehouse_label': wh_lbl,
            'itemcode': r.get('itemcode', ''),
            'itemname': r.get('itemname', ''),
            'itemmaster_qty': r.get('itemmaster_qty', ''),
            'warehouse_branch_total': r.get('warehouse_branch_total', ''),
            'warehouse_qty': r.get('warehouse_qty', ''),
            'bin_qty': r.get('bin_qty', ''),
            'lot_qty': r.get('lot_qty', ''),
            'lot_bin_qty': r.get('lot_bin_qty', ''),
            'lot_unalloc_qty': r.get('lot_unalloc_qty', ''),
            'lot_at_warehouse_qty': r.get('lot_at_warehouse_qty', ''),
            'itemjournal_qty': r.get('itemjournal_qty', ''),
            'itemjournal_branch_qty': r.get('itemjournal_branch_qty', ''),
            'delta_im_wh': r.get('delta_im_wh', ''),
            'delta_im_ij': r.get('delta_im_ij', ''),
            'delta_wh_bin': r.get('delta_wh_bin', ''),
            'delta_wh_lot': r.get('delta_wh_lot', ''),
            'delta_wh_ij': r.get('delta_wh_ij', ''),
            'status': r.get('status', ''),
            'issues': '; '.join(r.get('issues') or []),
        })
    return out


def _itemmaster_inventory_fallback_rows_on_cursor(cur: Any, location_code: int, item_code: int) -> List[Dict[str, Any]]:
    """Per-store qty columns on ITEMMASTER when STOREINVENTORY is missing or empty."""
    cur.execute("SELECT column_name FROM user_tab_columns WHERE table_name = 'ITEMMASTER'")
    colnames = [str(r[0]).upper() for r in cur.fetchall() or []]
    if not colnames or 'ITEMCODE' not in colnames or 'LOCATIONCODE' not in colnames:
        return []
    store_qty_cols = sorted([c for c in colnames if re.fullmatch('STORE\\d+', c)], key=lambda x: int(x[5:]))
    try:
        lc = int(location_code)
        ic = int(item_code)
    except (TypeError, ValueError):
        return []
    if store_qty_cols:
        sele = ', '.join([f'NVL(im.{c}, 0)' for c in store_qty_cols])
        cur.execute(f'\n            SELECT {sele}\n            FROM ITEMMASTER im\n            WHERE im.LOCATIONCODE = :loc AND im.ITEMCODE = :icode\n            ', {'loc': lc, 'icode': ic})
        row = cur.fetchone()
        if not row:
            return []
        out: List[Dict[str, Any]] = []
        for idx, c in enumerate(store_qty_cols):
            try:
                qty = float(_materialize_db_value(row[idx]) or 0)
            except (TypeError, ValueError, IndexError):
                qty = 0.0
            out.append({'code': c, 'store': c, 'description': '', 'stock': qty})
        return out
    cu_col = None
    for cand in ('CURRENTSTOCK', 'CURRENT_STOCK', 'STOCK'):
        if cand in colnames:
            cu_col = cand
            break
    if not cu_col:
        return []
    cur.execute(f'\n        SELECT NVL(im.{cu_col}, 0) AS stock\n        FROM ITEMMASTER im\n        WHERE im.LOCATIONCODE = :loc AND im.ITEMCODE = :icode\n        ', {'loc': lc, 'icode': ic})
    r = cur.fetchone()
    if not r:
        return []
    try:
        st = float(_materialize_db_value(r[0]) or 0)
    except (TypeError, ValueError):
        st = 0.0
    return [{'code': 'STOCK', 'store': 'Stock', 'description': '', 'stock': st}]

def _item_store_inventory_wh_stock_on_cursor(
    cur: Any,
    location_code: int,
    item_code: int,
    *,
    include_zero: bool=False,
) -> List[Dict[str, Any]]:
    """Run WAREHOUSE_STOCK store-inventory query on an open tenant cursor."""
    try:
        cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': WAREHOUSE_STOCK_TABLE.upper()})
        if int((cur.fetchone() or [0])[0] or 0) <= 0:
            return []
    except Exception:
        return []
    try:
        lc = int(location_code)
        ic = int(item_code)
    except (TypeError, ValueError):
        return []
    wm_tbl = None
    for cand in WAREHOUSE_MASTER_CANDIDATES:
        try:
            cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': cand.upper()})
            if int((cur.fetchone() or [0])[0] or 0) > 0:
                wm_tbl = cand
                break
        except Exception:
            continue
    qty_filter = '' if include_zero else ' AND NVL(ws.QTY, 0) <> 0'
    params: Dict[str, Any] = {'loc': lc, 'ic': ic}
    if wm_tbl:
        join_ws = (
            f'INNER JOIN {WAREHOUSE_STOCK_TABLE} ws\n'
            f'  ON ws.WAREHOUSE_ID = wm.WAREHOUSE_ID\n'
            f' AND ws.ITEMCODE = :ic\n'
            f' AND ws.LOCATIONCODE = :loc'
        )
        if include_zero:
            join_ws = (
                f'LEFT JOIN {WAREHOUSE_STOCK_TABLE} ws\n'
                f'  ON ws.WAREHOUSE_ID = wm.WAREHOUSE_ID\n'
                f' AND ws.ITEMCODE = :ic\n'
                f' AND ws.LOCATIONCODE = :loc'
            )
        q = f"""
            SELECT
                TO_CHAR(wm.WAREHOUSE_ID) AS code,
                TRIM(wm.WAREHOUSE_CODE) AS store,
                TRIM(wm.WAREHOUSE_NAME) AS description,
                NVL(ws.QTY, 0) AS stock,
                wm.WAREHOUSE_ID AS warehouse_id
            FROM {wm_tbl} wm
            {join_ws}
            WHERE wm.LOCATIONCODE = :loc
              AND NVL(wm.IS_ACTIVE, 'Y') = 'Y'
            {qty_filter}
            ORDER BY UPPER(TRIM(wm.WAREHOUSE_CODE))
        """
    else:
        q = f"""
            SELECT
                TO_CHAR(ws.WAREHOUSE_ID) AS code,
                TO_CHAR(ws.WAREHOUSE_ID) AS store,
                '' AS description,
                NVL(ws.QTY, 0) AS stock,
                ws.WAREHOUSE_ID AS warehouse_id
            FROM {WAREHOUSE_STOCK_TABLE} ws
            WHERE ws.LOCATIONCODE = :loc AND ws.ITEMCODE = :ic
            {qty_filter}
            ORDER BY ws.WAREHOUSE_ID
        """
    try:
        cur.execute(q, params)
        if not cur.description:
            return []
        cols = [c[0].lower() for c in cur.description]
        return [dict(zip(cols, [_materialize_db_value(v) for v in row])) for row in cur.fetchall() or []]
    except Exception:
        return []


def get_item_store_inventory_for_tenant(tenant_id: str, location_code: int, item_code: int, *, include_zero_stock: bool=True) -> List[Dict[str, Any]]:
    """WAREHOUSE_STOCK per warehouse on tenant DB; legacy STOREINVENTORY / ITEMMASTER fallback."""
    tid = (tenant_id or '').strip()
    if not tid:
        return []
    table_u = 'STOREINVENTORY'
    try:
        with _get_tenant_connection(tid) as conn:
            with conn.cursor() as cur:
                wh_rows = _item_store_inventory_wh_stock_on_cursor(
                    cur, location_code, item_code, include_zero=include_zero_stock,
                )
                try:
                    cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': WAREHOUSE_STOCK_TABLE.upper()})
                    has_ws = int((cur.fetchone() or [0])[0] or 0) > 0
                except Exception:
                    has_ws = False
                if has_ws:
                    return wh_rows
                cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :tbl', {'tbl': table_u})
                has_si = int((cur.fetchone() or [0])[0] or 0) > 0
                if has_si:
                    cur.execute('SELECT column_name FROM user_tab_columns WHERE table_name = :tbl', {'tbl': table_u})
                    col_set = {str(r[0]).upper() for r in cur.fetchall() or []}

                    def pick(cands: List[str]) -> Optional[str]:
                        for c in cands:
                            if c.upper() in col_set:
                                return c
                        return None
                    item_col = pick(['ITEMCODE', 'ITEM_CODE', 'ITEM', 'PRODUCTCODE', 'PRODUCT_CODE'])
                    store_col = pick(['STORE', 'STORECODE', 'STORE_CODE', 'STORENO', 'STORE_NO', 'GODOWN', 'GODOWNCODE', 'LOCATION'])
                    code_col = pick(['CODE', 'ID'])
                    desc_col = pick(['DESCRIPTION', 'STOREDESCRIPTION', 'STOREDESC', 'NAME', 'STORENAME', 'GODOWNNAME'])
                    stock_col = pick(['STOCK', 'CURRENTSTOCK', 'QTY', 'QUANTITY', 'BALANCE', 'TOTALSTOCK', 'STOCKQTY'])
                    location_col = pick(['LOCATIONCODE', 'LOCATION_CODE'])
                    if store_col and stock_col:
                        query = f"""\n                            SELECT\n                                {(code_col if code_col else store_col)} AS code,\n                                {store_col} AS store,\n                                {(desc_col if desc_col else "''")} AS description,\n                                NVL({stock_col}, 0) AS stock\n                            FROM {table_u}\n                            WHERE 1=1\n                        """
                        params: Dict[str, Any] = {}
                        if item_col:
                            query += f' AND {item_col} = :item_code'
                            params['item_code'] = item_code
                        if location_col:
                            query += f' AND {location_col} = :location_code'
                            params['location_code'] = location_code
                        if not include_zero_stock:
                            query += f' AND NVL({stock_col}, 0) <> 0'
                        query += f' ORDER BY UPPER(TRIM({store_col})) ASC'
                        cur.execute(query, params)
                        desc_cols = [d[0].lower() for d in cur.description or []]
                        rows_out = [dict(zip(desc_cols, [_materialize_db_value(v) for v in row])) for row in cur.fetchall() or []]
                        if rows_out:
                            return rows_out
                return _itemmaster_inventory_fallback_rows_on_cursor(cur, location_code, item_code)
    except Exception:
        return []

def get_customer_item_history(location_code: int, customer_code: str, item_code: int) -> List[Dict[str, Any]]:
    """Get customer item history from bill history tables"""
    query = "\n        SELECT\n            HDR.BILLNO AS billno,\n            TO_CHAR(HDR.BILLDATE, 'YYYY-MM-DD') AS billdate,\n            DTL.ITEMCODE AS itemcode,\n            DTL.QUANTITY AS quantity,\n            DTL.UNITOFMEASUREMENT AS uom,\n            DTL.RATE AS rate,\n            DTL.ITDISC AS discount,\n            (DTL.RATE - DTL.ITDISC) AS total\n        FROM BILLDTLHISTORY DTL\n        JOIN BILLHDRHISTORY HDR ON DTL.BILLNO = HDR.BILLNO\n        WHERE HDR.CUSTOMERCODE = :customer_code\n          AND DTL.ITEMCODE = :item_code\n        ORDER BY HDR.BILLNO DESC\n    "
    return _safe_rows(query, {'customer_code': customer_code, 'item_code': item_code})

def get_item_history(location_code: int, item_code: int) -> List[Dict[str, Any]]:
    """Get item history across customers from bill history tables"""
    query = "\n        SELECT\n            HDR.BILLNO AS billno,\n            TO_CHAR(HDR.BILLDATE, 'YYYY-MM-DD') AS billdate,\n            DTL.ITEMCODE AS itemcode,\n            HDR.CUSTOMERNAME AS customername,\n            DTL.QUANTITY AS quantity,\n            DTL.UNITOFMEASUREMENT AS uom,\n            DTL.RATE AS rate,\n            DTL.ITDISC AS discount,\n            (DTL.QUANTITY * (DTL.RATE - DTL.ITDISC)) AS total\n        FROM BILLDTLHISTORY DTL\n        JOIN BILLHDRHISTORY HDR ON DTL.BILLNO = HDR.BILLNO\n        WHERE DTL.ITEMCODE = :item_code\n        ORDER BY HDR.BILLNO DESC\n    "
    return _safe_rows(query, {'item_code': item_code})

def get_item_ledger_tab(location_code: int, item_code: int, tab: str, limit: int=400) -> List[Dict[str, Any]]:
    """
    Item ledger lines for Item Master: GRN purchase, purchase return, invoice sale,
    sale return, stock adjustment.
    ``tab``: purchase | purchase_return | sale | sale_return | stock_adjustment
    Sale vs sale return uses ``BILLDTLHISTORY.QUANTITY``: ``>= 0`` for Sale, ``< 0`` for Sale return
    (fallback: header RETURNFLAG/BILLTYPE when quantity column is missing).
    """
    tab_norm = (tab or '').strip().lower().replace('-', '_')
    lim = max(1, min(int(limit or 400), 2000))
    try:
        ic = int(item_code)
    except (TypeError, ValueError):
        return []
    try:
        if tab_norm in ('purchase', 'purchase_grn', 'grn'):
            return _item_ledger_purchase_grn_lines(location_code, ic, lim)
        if tab_norm in ('purchase_return', 'pr', 'goods_return'):
            return _item_ledger_purchase_return_lines(location_code, ic, lim)
        if tab_norm in ('sale', 'sales'):
            return _item_ledger_sales_lines(location_code, ic, lim, sales_return=False)
        if tab_norm in ('sale_return', 'sales_return', 'return'):
            return _item_ledger_sales_lines(location_code, ic, lim, sales_return=True)
        if tab_norm in ('stock_adjustment', 'stk_adj', 'adjustment', 'stkadj'):
            return _item_ledger_stock_adjustment_lines(location_code, ic, lim)
    except Exception:
        return []
    return []

def _bill_history_return_predicate(alias: str, hdr_tbl: str, sales_return: bool) -> str:
    rf = _detect_column(hdr_tbl, ['RETURNFLAG', 'returnflag'])
    bt = _detect_column(hdr_tbl, ['BILLTYPE', 'billtype'])
    parts_true: List[str] = []
    parts_false: List[str] = []
    if rf:
        parts_true.append(f"NVL({alias}.{rf}, 'N') = 'Y'")
        parts_false.append(f"NVL({alias}.{rf}, 'N') <> 'Y'")
    if bt:
        parts_true.append(f"UPPER(NVL(TRIM(TO_CHAR({alias}.{bt})), ' ')) = 'R'")
        parts_false.append(f"UPPER(NVL(TRIM(TO_CHAR({alias}.{bt})), ' ')) <> 'R'")
    if not parts_true:
        return '1=1' if not sales_return else '1=0'
    if sales_return:
        return '(' + ' OR '.join(parts_true) + ')'
    return '(' + ' AND '.join(parts_false) + ')'

def _item_ledger_purchase_grn_lines(location_code: int, item_code: int, limit: int) -> List[Dict[str, Any]]:
    rh = _detect_table(['RECEIPTHDR', 'receipthdr'])
    rd = _detect_table(['RECEIPTDTL', 'receiptdtl'])
    if not rh or not rd:
        return []
    h_loc = _detect_column(rh, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    h_no = _detect_column(rh, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
    h_sup = _detect_column(rh, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode'])
    h_date = _detect_column(rh, ['RECEIPTDATE', 'RECEIPT_DATE', 'receiptdate', 'CREATEDDATE', 'createddate'])
    d_loc = _detect_column(rd, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    d_no = _detect_column(rd, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
    d_item = _detect_column(rd, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    d_qty = _detect_column(rd, ['QUANTITY', 'quantity'])
    d_rate = _detect_column(rd, ['RATE', 'rate'])
    d_uom = _detect_column(rd, ['UNITOFMEASUREMENT', 'UOM', 'unitofmeasurement', 'uom'])
    d_amt = _detect_column(rd, ['AMOUNT', 'amount'])
    if not h_no or not d_no or (not d_item):
        return []
    join_cond = [f'd.{d_no} = h.{h_no}']
    if h_loc and d_loc:
        join_cond.append(f'd.{d_loc} = h.{h_loc}')
    sup_tbl = _detect_table(['SUPPLIER', 'supplier', 'SUPPLIERS'])
    sup_code = _detect_column(sup_tbl, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode']) if sup_tbl else None
    sup_name = _detect_column(sup_tbl, ['SUPPLIERNAME', 'SUPPLIER_NAME', 'suppliername']) if sup_tbl else None
    party_expr = 'CAST(NULL AS VARCHAR2(400)) AS party_name'
    party_code_sel = f'h.{h_sup} AS party_code' if h_sup else 'NULL AS party_code'
    join_sup = ' '
    if sup_tbl and sup_code and sup_name and h_sup:
        party_expr = f's.{sup_name} AS party_name'
        join_sup = f' LEFT JOIN {sup_tbl} s ON h.{h_sup} = s.{sup_code} '
    date_sel = f"TO_CHAR(h.{h_date}, 'YYYY-MM-DD') AS doc_date" if h_date else 'NULL AS doc_date'
    d_bonus = _detect_column(rd, ['BONUS', 'bonus'])
    d_foc = _detect_column(rd, ['FOC', 'foc'])
    bonus_sel = f'NVL(d.{d_bonus}, 0) AS bonus' if d_bonus else 'NULL AS bonus'
    foc_sel = f'NVL(d.{d_foc}, 0) AS foc' if d_foc else 'NULL AS foc'
    qty_sel = f'd.{d_qty} AS qty' if d_qty else 'NULL AS qty'
    rate_sel = f'd.{d_rate} AS rate' if d_rate else 'NULL AS rate'
    uom_sel = f'd.{d_uom} AS uom' if d_uom else 'NULL AS uom'
    amt_sel = f'd.{d_amt} AS amount' if d_amt else 'NULL AS amount'
    where = [f'd.{d_item} = :item']
    params: Dict[str, Any] = {'item': item_code}
    if d_loc:
        where.append(f'd.{d_loc} = :loc')
        params['loc'] = location_code
    elif h_loc:
        where.append(f'h.{h_loc} = :loc')
        params['loc'] = location_code
    del_col = _detect_column(rh, ['DELFLAG', 'delflag'])
    if del_col:
        where.append(f"NVL(h.{del_col}, 'N') <> 'Y'")
    q = f"SELECT h.{h_no} AS doc_no,\n                   {date_sel},\n                   {party_code_sel},\n                   {party_expr},\n                   {qty_sel}, {uom_sel}, {rate_sel},\n                   {bonus_sel}, {foc_sel}, CAST(NULL AS NUMBER) AS discount,\n                   {amt_sel}\n            FROM {rd} d\n            INNER JOIN {rh} h ON {' AND '.join(join_cond)}\n            {join_sup}\n            WHERE {' AND '.join(where)}\n            ORDER BY h.{h_no} DESC"
    rows = _safe_rows(q, params) or []
    return rows[:limit]

def _item_ledger_purchase_return_lines(location_code: int, item_code: int, limit: int) -> List[Dict[str, Any]]:
    hdr = _detect_table(['RETURNHDR', 'returnhdr']) or _detect_table(['TEMPRETURNHDR', 'tempreturnhdr'])
    dtl = _detect_table(['RETURNDTL', 'returndtl']) or _detect_table(['TEMPRETURNDTL', 'tempreturndtl'])
    if not hdr or not dtl:
        return []
    h_loc = _detect_column(hdr, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    h_no = _detect_column(hdr, ['GOODSRETURNNO', 'goodsreturnno'])
    h_sup = _detect_column(hdr, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode'])
    h_date = _detect_column(hdr, ['RETURNDATE', 'returndate'])
    h_del = _detect_column(hdr, ['DELFLAG', 'delflag'])
    d_loc = _detect_column(dtl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    d_no = _detect_column(dtl, ['GOODSRETURNNO', 'goodsreturnno'])
    d_item = _detect_column(dtl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    d_qty = _detect_column(dtl, ['QUANTITY', 'quantity'])
    d_rate = _detect_column(dtl, ['RATE', 'rate'])
    d_uom = _detect_column(dtl, ['UOM', 'UNITOFMEASUREMENT', 'uom'])
    d_disc = _detect_column(dtl, ['DISCOUNT', 'discount'])
    d_amt = _detect_column(dtl, ['AMOUNT', 'amount'])
    if not h_no or not d_no or (not d_item):
        return []
    join_cond = [f'd.{d_no} = h.{h_no}']
    if h_loc and d_loc:
        join_cond.append(f'd.{d_loc} = h.{h_loc}')
    sup_tbl = _detect_table(['SUPPLIER', 'supplier', 'SUPPLIERS'])
    sup_code = _detect_column(sup_tbl, ['SUPPLIERCODE', 'SUPPLIER_CODE', 'suppliercode']) if sup_tbl else None
    sup_name = _detect_column(sup_tbl, ['SUPPLIERNAME', 'SUPPLIER_NAME', 'suppliername']) if sup_tbl else None
    party_expr = 'CAST(NULL AS VARCHAR2(400)) AS party_name'
    party_code_sel = f'h.{h_sup} AS party_code' if h_sup else 'NULL AS party_code'
    join_sup = ' '
    if sup_tbl and sup_code and sup_name and h_sup:
        party_expr = f's.{sup_name} AS party_name'
        join_sup = f' LEFT JOIN {sup_tbl} s ON h.{h_sup} = s.{sup_code} '
    date_sel = f"TO_CHAR(h.{h_date}, 'YYYY-MM-DD') AS doc_date" if h_date else 'NULL AS doc_date'
    d_bonus = _detect_column(dtl, ['BONUS', 'bonus'])
    d_foc = _detect_column(dtl, ['FOC', 'foc'])
    bonus_sel = f'NVL(d.{d_bonus}, 0) AS bonus' if d_bonus else 'NULL AS bonus'
    foc_sel = f'NVL(d.{d_foc}, 0) AS foc' if d_foc else 'NULL AS foc'
    qty_sel = f'd.{d_qty} AS qty' if d_qty else 'NULL AS qty'
    rate_sel = f'd.{d_rate} AS rate' if d_rate else 'NULL AS rate'
    uom_sel = f'd.{d_uom} AS uom' if d_uom else 'NULL AS uom'
    disc_sel = f'NVL(d.{d_disc}, 0) AS discount' if d_disc else 'CAST(NULL AS NUMBER) AS discount'
    if d_amt:
        if d_qty and d_rate and d_disc:
            amt_sel = (
                f'CASE WHEN NVL(d.{d_amt}, 0) <> 0 THEN d.{d_amt} '
                f'ELSE GREATEST(NVL(d.{d_qty}, 0) * NVL(d.{d_rate}, 0) - NVL(d.{d_disc}, 0), 0) END AS amount'
            )
        else:
            amt_sel = f'd.{d_amt} AS amount'
    elif d_qty and d_rate and d_disc:
        amt_sel = f'GREATEST(NVL(d.{d_qty}, 0) * NVL(d.{d_rate}, 0) - NVL(d.{d_disc}, 0), 0) AS amount'
    elif d_qty and d_rate:
        amt_sel = f'(NVL(d.{d_qty}, 0) * NVL(d.{d_rate}, 0)) AS amount'
    else:
        amt_sel = 'NULL AS amount'
    where = [f'd.{d_item} = :item']
    params: Dict[str, Any] = {'item': item_code}
    if d_loc:
        where.append(f'd.{d_loc} = :loc')
        params['loc'] = location_code
    elif h_loc:
        where.append(f'h.{h_loc} = :loc')
        params['loc'] = location_code
    if h_del:
        where.append(f"NVL(h.{h_del}, 'N') = 'N'")
    q = f"SELECT h.{h_no} AS doc_no,\n                   {date_sel},\n                   {party_code_sel},\n                   {party_expr},\n                   {qty_sel}, {uom_sel}, {rate_sel},\n                   {bonus_sel}, {foc_sel}, {disc_sel},\n                   {amt_sel}\n            FROM {dtl} d\n            INNER JOIN {hdr} h ON {' AND '.join(join_cond)}\n            {join_sup}\n            WHERE {' AND '.join(where)}\n            ORDER BY h.{h_no} DESC"
    rows = _safe_rows(q, params) or []
    return rows[:limit]

def _item_ledger_sales_lines(location_code: int, item_code: int, limit: int, sales_return: bool) -> List[Dict[str, Any]]:
    hdr = _detect_table(['BILLHDRHISTORY', 'billhdrhistory'])
    dtl = _detect_table(['BILLDTLHISTORY', 'billdtlhistory'])
    if not hdr or not dtl:
        return []
    h_loc = _detect_column(hdr, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    h_no = _detect_column(hdr, ['BILLNO', 'BILL_NO', 'billno'])
    h_date = _detect_column(hdr, ['BILLDATE', 'BILL_DATE', 'billdate'])
    h_cust_code = _detect_column(hdr, ['CUSTOMERCODE', 'CUSTOMER_CODE', 'customercode'])
    h_cust_name = _detect_column(hdr, ['CUSTOMERNAME', 'CUSTOMER_NAME', 'customername'])
    h_del = _detect_column(hdr, ['DELFLAG', 'delflag'])
    d_loc = _detect_column(dtl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    d_no = _detect_column(dtl, ['BILLNO', 'BILL_NO', 'billno'])
    d_item = _detect_column(dtl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    d_qty = _detect_column(dtl, ['QUANTITY', 'quantity'])
    d_rate = _detect_column(dtl, ['RATE', 'rate'])
    d_uom = _detect_column(dtl, ['UNITOFMEASUREMENT', 'UOM', 'unitofmeasurement', 'uom'])
    d_disc = _detect_column(dtl, ['ITDISC', 'IT_DISC', 'DISCOUNT', 'discount'])
    if not h_no or not d_no or (not d_item):
        return []
    join_cond = [f'd.{d_no} = h.{h_no}']
    if h_loc and d_loc:
        join_cond.append(f'd.{d_loc} = h.{h_loc}')
    party_code_sel = f'h.{h_cust_code} AS party_code' if h_cust_code else 'NULL AS party_code'
    party_expr = f'h.{h_cust_name} AS party_name' if h_cust_name else 'CAST(NULL AS VARCHAR2(400)) AS party_name'
    date_sel = f"TO_CHAR(h.{h_date}, 'YYYY-MM-DD') AS doc_date" if h_date else 'NULL AS doc_date'
    bonus_sel = 'NULL AS bonus'
    foc_sel = 'NULL AS foc'
    discount_sel = f'NVL(d.{d_disc}, 0) AS discount' if d_disc else 'NULL AS discount'
    qty_sel = f'd.{d_qty} AS qty' if d_qty else 'NULL AS qty'
    rate_sel = f'd.{d_rate} AS rate' if d_rate else 'NULL AS rate'
    uom_sel = f'd.{d_uom} AS uom' if d_uom else 'NULL AS uom'
    if d_qty and d_rate and d_disc:
        amt_sel = f'(d.{d_qty} * (d.{d_rate} - NVL(d.{d_disc}, 0))) AS amount'
    elif d_qty and d_rate:
        amt_sel = f'(d.{d_qty} * d.{d_rate}) AS amount'
    else:
        amt_sel = 'NULL AS amount'
    qty_kind_pred = _bill_history_return_predicate('h', hdr, sales_return) if not d_qty else None
    where = [f'd.{d_item} = :item']
    if d_qty:
        if sales_return:
            where.append(f'NVL(d.{d_qty}, 0) < 0')
        else:
            where.append(f'NVL(d.{d_qty}, 0) >= 0')
    elif qty_kind_pred:
        where.append(qty_kind_pred)
    params: Dict[str, Any] = {'item': item_code}
    if d_loc:
        where.append(f'd.{d_loc} = :loc')
        params['loc'] = location_code
    elif h_loc:
        where.append(f'h.{h_loc} = :loc')
        params['loc'] = location_code
    if h_del:
        where.append(f"NVL(h.{h_del}, 'N') <> 'Y'")
    q = f"SELECT h.{h_no} AS doc_no,\n                   {date_sel},\n                   {party_code_sel},\n                   {party_expr},\n                   {qty_sel}, {uom_sel}, {rate_sel},\n                   {bonus_sel}, {foc_sel}, {discount_sel},\n                   {amt_sel}\n            FROM {dtl} d\n            INNER JOIN {hdr} h ON {' AND '.join(join_cond)}\n            WHERE {' AND '.join(where)}\n            ORDER BY h.{h_no} DESC"
    rows = _safe_rows(q, params) or []
    return rows[:limit]

def _item_ledger_stock_adjustment_lines(location_code: int, item_code: int, limit: int) -> List[Dict[str, Any]]:
    hdr = _detect_table(['STKADJHDR', 'stockadjustmenthdr', 'ADJUSTMENTHDR'])
    dtl = _detect_table(['STKADJDTL', 'stockadjustmentdtl', 'ADJUSTMENTDTL'])
    if not hdr or not dtl:
        return []
    h_loc = _detect_column(hdr, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    h_no = _detect_column(hdr, ['ADJNO', 'ADJUSTNO', 'DOCNO']) or 'ADJNO'
    h_date = _detect_column(hdr, ['ADJDATE', 'ADJUSTDATE', 'DOCDATE']) or 'ADJDATE'
    h_status = _detect_column(hdr, ['STATUS', 'status'])
    h_rem = _detect_column(hdr, ['REMARKS', 'remarks'])
    d_loc = _detect_column(dtl, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    d_no = _detect_column(dtl, ['ADJNO', 'ADJUSTNO', 'DOCNO']) or 'ADJNO'
    d_item = _detect_column(dtl, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    d_qty = _detect_column(dtl, ['ADJUSTQTY', 'adjustqty'])
    d_base = _detect_column(dtl, ['BASEQTY', 'baseqty'])
    d_rate = _detect_column(dtl, ['COSTPRICE', 'costprice'])
    d_uom = _detect_column(dtl, ['UNITOFMEASUREMENT', 'UOM', 'unitofmeasurement', 'uom'])
    d_store = _detect_column(dtl, ['STORE', 'store'])
    if not h_no or not d_no or not d_item:
        return []
    join_cond = [f'd.{d_no} = h.{h_no}']
    if h_loc and d_loc:
        join_cond.append(f'd.{d_loc} = h.{h_loc}')
    doc_no_sel = f'TO_CHAR(h.{h_no}) AS doc_no'
    date_sel = f"TO_CHAR(h.{h_date}, 'YYYY-MM-DD') AS doc_date" if h_date else 'NULL AS doc_date'
    if d_store:
        party_code_sel = f'd.{d_store} AS party_code'
        party_expr = f'd.{d_store} AS party_name'
    elif h_rem:
        party_code_sel = 'NULL AS party_code'
        party_expr = f'h.{h_rem} AS party_name'
    else:
        party_code_sel = 'NULL AS party_code'
        party_expr = 'CAST(NULL AS VARCHAR2(400)) AS party_name'
    if d_qty:
        qty_sel = f'd.{d_qty} AS qty'
    elif d_base:
        qty_sel = f'd.{d_base} AS qty'
    else:
        qty_sel = 'NULL AS qty'
    rate_sel = f'd.{d_rate} AS rate' if d_rate else 'NULL AS rate'
    uom_sel = f'd.{d_uom} AS uom' if d_uom else 'NULL AS uom'
    bonus_sel = 'NULL AS bonus'
    foc_sel = 'NULL AS foc'
    discount_sel = 'NULL AS discount'
    if d_qty and d_rate:
        amt_sel = f'(NVL(d.{d_qty}, 0) * NVL(d.{d_rate}, 0)) AS amount'
    elif d_base and d_rate:
        amt_sel = f'(NVL(d.{d_base}, 0) * NVL(d.{d_rate}, 0)) AS amount'
    else:
        amt_sel = 'NULL AS amount'
    where = [f'd.{d_item} = :item']
    params: Dict[str, Any] = {'item': item_code}
    if d_loc:
        where.append(f'd.{d_loc} = :loc')
        params['loc'] = location_code
    elif h_loc:
        where.append(f'h.{h_loc} = :loc')
        params['loc'] = location_code
    if h_status:
        where.append(f"NVL(h.{h_status}, 'P') = 'P'")
    if h_rem:
        where.append(f"(h.{h_rem} IS NULL OR UPPER(h.{h_rem}) NOT LIKE 'REPACKING:%')")
        where.append(f"(h.{h_rem} IS NULL OR UPPER(h.{h_rem}) NOT LIKE 'REVERSAL OF ADJ%')")
    q = f"""SELECT {doc_no_sel},
                   {date_sel},
                   {party_code_sel},
                   {party_expr},
                   {qty_sel}, {uom_sel}, {rate_sel},
                   {bonus_sel}, {foc_sel}, {discount_sel},
                   {amt_sel}
            FROM {dtl} d
            INNER JOIN {hdr} h ON {' AND '.join(join_cond)}
            WHERE {' AND '.join(where)}
            ORDER BY h.{h_date or h_no} DESC, h.{h_no} DESC"""
    rows = _safe_rows(q, params) or []
    return rows[:limit]

def get_item_alternate_uom_by_barcode(location_code: int, manufacturer_id: str) -> Optional[Dict[str, Any]]:
    """Get alternate UOM mapping by alternate barcode"""
    query = '\n        SELECT\n            LOCATIONCODE,\n            SLNO,\n            ITEMCODE,\n            ALTERNATEUOMCODE,\n            MANUFACTURERID,\n            CONVERSIONFACTOR,\n            COSTPRICE,\n            WHOLESALEPRICE,\n            RETAILPRICE,\n            THIRDPRICE,\n            BRANCHPRICE\n        FROM ITEMALTERNATEUOMMAP\n        WHERE LOCATIONCODE = :location_code\n        AND MANUFACTURERID = :manufacturer_id\n        ORDER BY SLNO\n    '
    rows = _safe_rows(query, {'location_code': location_code, 'manufacturer_id': manufacturer_id})
    return rows[0] if rows else None

def get_next_alternate_barcode(location_code: int, item_code: int) -> str:
    """Generate next alternate barcode as ITEMCODE + L#"""
    query = '\n        SELECT MANUFACTURERID\n        FROM ITEMALTERNATEUOMMAP\n        WHERE LOCATIONCODE = :location_code\n        AND ITEMCODE = :item_code\n        AND MANUFACTURERID LIKE :prefix\n    '
    prefix = f'{item_code}L%'
    rows = _safe_rows(query, {'location_code': location_code, 'item_code': item_code, 'prefix': prefix})
    max_suffix = 0
    for row in rows:
        value = str(row.get('manufacturerid') or '')
        if value.startswith(f'{item_code}L'):
            suffix = value[len(f'{item_code}L'):]
            try:
                max_suffix = max(max_suffix, int(suffix))
            except (ValueError, TypeError):
                continue
    return f'{item_code}L{max_suffix + 1}'

def check_manufacturer_id_exists(manufacturer_id: str, location_code: int, exclude_item_code: Optional[int]=None) -> bool:
    """Check if manufacturer ID already exists"""
    if exclude_item_code:
        query = '\n            SELECT COUNT(*) FROM ITEMMASTER\n            WHERE MANUFACTURERID = :manufacturer_id\n            AND LOCATIONCODE = :location_code\n            AND ITEMCODE <> :exclude_item_code\n        '
        params = {'manufacturer_id': manufacturer_id, 'location_code': location_code, 'exclude_item_code': exclude_item_code}
    else:
        query = '\n            SELECT COUNT(*) FROM ITEMMASTER\n            WHERE MANUFACTURERID = :manufacturer_id\n            AND LOCATIONCODE = :location_code\n        '
        params = {'manufacturer_id': manufacturer_id, 'location_code': location_code}
    try:
        count = _get_count(query, params)
        return count > 0
    except Exception:
        return False


INTERNAL_BARCODE_PREFIX = '12'
INTERNAL_BARCODE_TOTAL_DIGITS = 13
INTERNAL_BARCODE_MAX_ITEM_DIGITS = INTERNAL_BARCODE_TOTAL_DIGITS - len(INTERNAL_BARCODE_PREFIX)


def format_location_prefix_item_barcode(location_code: int, item_code: int) -> Optional[str]:
    """
    13-digit internal barcode: prefix ``12`` + zero-padded middle + item code suffix.
    Example: item 1000 -> 1200000001000
    ``location_code`` is kept for API compatibility but not used in the barcode.
    """
    _ = location_code
    try:
        ic = int(item_code)
    except (TypeError, ValueError):
        return None
    if ic <= 0:
        return None
    ic_str = str(ic)
    if len(ic_str) > INTERNAL_BARCODE_MAX_ITEM_DIGITS:
        return None
    pad_len = INTERNAL_BARCODE_TOTAL_DIGITS - len(INTERNAL_BARCODE_PREFIX) - len(ic_str)
    if pad_len < 0:
        return None
    return f'{INTERNAL_BARCODE_PREFIX}{"0" * pad_len}{ic_str}'


def barcode_taken_in_location(
    manufacturer_id: str,
    location_code: int,
    *,
    exclude_item_code: Optional[int] = None,
) -> bool:
    """True when barcode exists on ITEMMASTER or ITEMALTERNATEUOMMAP (another item)."""
    mfg = str(manufacturer_id or '').strip()
    if not mfg:
        return False
    try:
        loc = int(location_code)
    except (TypeError, ValueError):
        return False
    if check_manufacturer_id_exists(mfg, loc, exclude_item_code=exclude_item_code):
        return True
    try:
        alt_hit = get_item_by_alternate_barcode(mfg, loc)
    except Exception:
        alt_hit = None
    if not alt_hit:
        return False
    if exclude_item_code is not None:
        try:
            alt_ic = int(alt_hit.get('itemcode') or alt_hit.get('item_code') or 0)
            if alt_ic == int(exclude_item_code):
                return False
        except (TypeError, ValueError):
            pass
    return True


def suggest_location_prefix_item_barcode(
    location_code: int,
    item_code: int,
    *,
    exclude_item_code: Optional[int] = None,
) -> tuple:
    """Return (barcode, error_message). Error set when format invalid or barcode already used."""
    barcode = format_location_prefix_item_barcode(location_code, item_code)
    if not barcode:
        return (None, (
            f'Item code must be 1–{10 ** INTERNAL_BARCODE_MAX_ITEM_DIGITS - 1} '
            f'for a {INTERNAL_BARCODE_TOTAL_DIGITS}-digit barcode starting with {INTERNAL_BARCODE_PREFIX}.'
        ))
    if barcode_taken_in_location(barcode, location_code, exclude_item_code=exclude_item_code):
        return (None, f'Barcode {barcode} is already used. Choose another barcode manually.')
    return (barcode, None)

def _build_items_list_where(
    tbl_alias: str,
    location_code: Optional[int]=None,
    search: Optional[str]=None,
    stock_filter: Optional[str]=None,
    brand_code: Optional[int]=None,
    category_code: Optional[int]=None,
    supplier_code: Optional[str]=None,
    item_codes: Optional[List[int]]=None,
) -> Tuple[str, Dict[str, Any]]:
    where_conditions = []
    params: Dict[str, Any] = {}
    if location_code is not None:
        where_conditions.append(f'{tbl_alias}.LOCATIONCODE = :location_code')
        params['location_code'] = location_code
    if search:
        qraw = str(search or '').strip()
        qup = qraw.upper().replace('*', '%')
        # Exact / prefix paths use indexes; avoid leading-wildcard when user types a code/barcode.
        if qraw.isdigit():
            where_conditions.append(f'''
                (
                    {tbl_alias}.ITEMCODE = :search_itemcode
                    OR UPPER(TRIM({tbl_alias}.MANUFACTURERID)) = :search_exact
                    OR UPPER(TRIM({tbl_alias}.MANUFACTURERID)) LIKE :search_prefix
                    OR UPPER({tbl_alias}.ITEMNAME) LIKE :search_contains
                )
            ''')
            params['search_itemcode'] = int(qraw)
            params['search_exact'] = qup
            params['search_prefix'] = f'{qup}%'
            params['search_contains'] = f'%{qup}%'
        else:
            if '%' not in qup:
                # Prefer prefix on barcode; keep contains on name.
                where_conditions.append(f'''
                    (
                        UPPER(TO_CHAR({tbl_alias}.ITEMCODE)) LIKE :search_prefix
                        OR UPPER(TRIM({tbl_alias}.MANUFACTURERID)) = :search_exact
                        OR UPPER(TRIM({tbl_alias}.MANUFACTURERID)) LIKE :search_prefix
                        OR UPPER({tbl_alias}.ITEMNAME) LIKE :search_contains
                    )
                ''')
                params['search_exact'] = qup
                params['search_prefix'] = f'{qup}%'
                params['search_contains'] = f'%{qup}%'
            else:
                where_conditions.append(f'''
                    (
                        UPPER(TO_CHAR({tbl_alias}.ITEMCODE)) LIKE :search
                        OR UPPER({tbl_alias}.MANUFACTURERID) LIKE :search
                        OR UPPER({tbl_alias}.ITEMNAME) LIKE :search
                    )
                ''')
                params['search'] = qup if qup.startswith('%') else f'%{qup}%'
    if stock_filter:
        if stock_filter == 'notzero':
            where_conditions.append(f'NVL({tbl_alias}.CURRENTSTOCK, 0) <> 0')
        elif stock_filter == 'greater':
            where_conditions.append(f'NVL({tbl_alias}.CURRENTSTOCK, 0) > 0')
        elif stock_filter == 'less':
            where_conditions.append(f'NVL({tbl_alias}.CURRENTSTOCK, 0) < 0')
        elif stock_filter == 'instock':
            # Above low-stock threshold (matches mobile catalog buckets)
            where_conditions.append(f'NVL({tbl_alias}.CURRENTSTOCK, 0) > 10')
        elif stock_filter == 'low':
            where_conditions.append(
                f'NVL({tbl_alias}.CURRENTSTOCK, 0) > 0 AND NVL({tbl_alias}.CURRENTSTOCK, 0) <= 10'
            )
        elif stock_filter in ('out', 'zero'):
            where_conditions.append(f'NVL({tbl_alias}.CURRENTSTOCK, 0) <= 0')
    if brand_code is not None:
        where_conditions.append(f'{tbl_alias}.BRANDCODE = :brand_code')
        params['brand_code'] = brand_code
    if category_code is not None:
        where_conditions.append(f'{tbl_alias}.CATEGORYCODE = :category_code')
        params['category_code'] = category_code
    if supplier_code:
        where_conditions.append(f'{tbl_alias}.SUPCODE = :supplier_code')
        params['supplier_code'] = supplier_code
    if item_codes:
        placeholders = ','.join([f':item_code_{i}' for i in range(len(item_codes))])
        where_conditions.append(f'{tbl_alias}.ITEMCODE IN ({placeholders})')
        for i, code in enumerate(item_codes):
            params[f'item_code_{i}'] = code
    where_clause = 'WHERE ' + ' AND '.join(where_conditions) if where_conditions else ''
    return (where_clause, params)

def get_items_kpis(location_code: Optional[int]=None, search: Optional[str]=None, stock_filter: Optional[str]=None, brand_code: Optional[int]=None, category_code: Optional[int]=None, supplier_code: Optional[str]=None, item_codes: Optional[List[int]]=None) -> Dict[str, Any]:
    """Return KPI totals from ITEMMASTER for the same filter set used by product list."""
    where_clause, params = _build_items_list_where('im', location_code=location_code, search=search, stock_filter=stock_filter, brand_code=brand_code, category_code=category_code, supplier_code=supplier_code, item_codes=item_codes)
    query = f"""
        SELECT
            COUNT(*) AS total_items,
            SUM(CASE WHEN NVL(im.ITEMFLAG, 'Y') = 'N' THEN 1 ELSE 0 END) AS inactive_items,
            SUM(CASE WHEN NVL(im.ITEMFLAG, 'Y') <> 'N' THEN 1 ELSE 0 END) AS active_items,
            SUM(CASE WHEN NVL(im.CURRENTSTOCK, 0) <= 0 THEN 1 ELSE 0 END) AS low_stock_items,
            SUM(NVL(im.CURRENTSTOCK, 0) * NVL(im.COSTPRICE, 0)) AS inventory_value
        FROM ITEMMASTER im
        {where_clause}
    """
    try:
        _, rows = _fetch_rows(query, params)
        row = rows[0] if rows else {}
        return {
            'total_items': int(row.get('total_items') or 0),
            'active_items': int(row.get('active_items') or 0),
            'inactive_items': int(row.get('inactive_items') or 0),
            'low_stock_items': int(row.get('low_stock_items') or 0),
            'inventory_value': round(float(row.get('inventory_value') or 0), 2),
        }
    except Exception as e:
        print(f'[ERROR get_items_kpis] {e}')
        return {'total_items': 0, 'active_items': 0, 'inactive_items': 0, 'low_stock_items': 0, 'inventory_value': 0.0}

def get_items_list(
    location_code: Optional[int]=None,
    search: Optional[str]=None,
    limit: Optional[int]=None,
    stock_filter: Optional[str]=None,
    brand_code: Optional[int]=None,
    category_code: Optional[int]=None,
    supplier_code: Optional[str]=None,
    item_codes: Optional[List[int]]=None,
    order_by: Optional[str]=None,
    order_direction: Optional[str]=None,
    page: Optional[int]=None,
    items_per_page: Optional[int]=None,
    *,
    include_lookup_names: bool = False,
) -> Tuple[List[Dict[str, Any]], int]:
    """Get items list from ``ITEMMASTER``.

    Product list UI does not show category/brand/supplier columns, so those name
    lookups are omitted unless ``include_lookup_names`` or sorting by them.
    COUNT uses the same filters. ROWNUM pagination is Oracle 11g–safe.
    """
    tbl_alias = 'im'
    where_clause, params = _build_items_list_where(tbl_alias, location_code=location_code, search=search, stock_filter=stock_filter, brand_code=brand_code, category_code=category_code, supplier_code=supplier_code, item_codes=item_codes)
    order_by_clause = f'ORDER BY {tbl_alias}.ITEMCODE DESC'
    _sql_cat_name = "(SELECT NVL(MAX(cat.NAME), '') FROM CATEGORY cat WHERE cat.CODE = im.CATEGORYCODE AND cat.FLAG = 'C')"
    _sql_brand_name = "(SELECT NVL(MAX(brand.NAME), '') FROM CATEGORY brand WHERE brand.CODE = im.BRANDCODE AND brand.FLAG = 'B')"
    _sql_supp_name = "(SELECT NVL(MAX(sup.SUPPLIERNAME), '') FROM SUPPLIER sup WHERE sup.SUPPLIERCODE = im.SUPCODE AND sup.LOCATIONCODE = im.LOCATIONCODE)"
    order_key = (order_by or '').strip().lower()
    need_name_cols = bool(include_lookup_names) or order_key in ('categoryname', 'brandname', 'suppliername')
    if order_by:
        sort_column_map = {
            'locationcode': 'im.LOCATIONCODE',
            'itemcode': 'im.ITEMCODE',
            'manufacturerid': 'im.MANUFACTURERID',
            'itemname': 'im.ITEMNAME',
            'baseuom': 'im.BASEUOM',
            'costprice': 'im.COSTPRICE',
            'averagecost': 'im.AVERAGECOST',
            'currentstock': 'im.CURRENTSTOCK',
            'retailprice': 'im.RETAILPRICE',
            'wholesaleprice': 'im.WHOLESALEPRICE',
            'description': 'im.DESCRIPTION',
            'categoryname': _sql_cat_name,
            'brandname': _sql_brand_name,
            'suppliername': _sql_supp_name,
        }
        sort_column = sort_column_map.get(order_key, 'im.ITEMCODE')
        sort_direction = 'DESC' if order_direction and order_direction.upper() == 'DESC' else 'ASC'
        order_by_clause = f'ORDER BY {sort_column} {sort_direction}'
    if need_name_cols:
        name_select = f'{_sql_cat_name} AS CATEGORYNAME, {_sql_brand_name} AS BRANDNAME, {_sql_supp_name} AS SUPPLIERNAME'
    else:
        # Keep keys for API/export compatibility without per-row correlated lookups.
        name_select = "CAST('' AS VARCHAR2(1)) AS CATEGORYNAME, CAST('' AS VARCHAR2(1)) AS BRANDNAME, CAST('' AS VARCHAR2(1)) AS SUPPLIERNAME"
    base_query = f'''
        SELECT
            im.LOCATIONCODE,
            im.ITEMCODE,
            im.MANUFACTURERID,
            im.ITEMNAME,
            im.DESCRIPTION,
            im.IMAGE_PATH,
            im.BASEUOM,
            NVL(im.COSTPRICE, 0) AS COSTPRICE,
            NVL(im.AVERAGECOST, 0) AS AVERAGECOST,
            NVL(im.CURRENTSTOCK, 0) AS CURRENTSTOCK,
            NVL(im.RETAILPRICE, 0) AS RETAILPRICE,
            NVL(im.WHOLESALEPRICE, 0) AS WHOLESALEPRICE,
            im.ITEMFLAG,
            {name_select}
        FROM ITEMMASTER im
        {where_clause}
        {order_by_clause}
    '''
    count_query = f'SELECT COUNT(*) AS cnt FROM ITEMMASTER im {where_clause}'
    count_succeeded = False
    try:
        _, count_rows = _fetch_rows(count_query, params)
        total_count = int(count_rows[0].get('cnt') or 0) if count_rows else 0
        count_succeeded = True
    except Exception as e:
        print(f'[ERROR get_items_list count] {e}')
        total_count = 0
    if count_succeeded and total_count == 0:
        return ([], 0)
    if page is not None and items_per_page is not None:
        offset = (page - 1) * items_per_page
        query = f'\n            SELECT * FROM (\n                SELECT a.*, ROWNUM rnum FROM (\n                    {base_query}\n                ) a WHERE ROWNUM <= :max_row\n            ) WHERE rnum > :min_row\n        '
        params['max_row'] = offset + items_per_page
        params['min_row'] = offset
    elif limit:
        query = f'\n            SELECT * FROM (\n                {base_query}\n            ) WHERE ROWNUM <= :limit\n        '
        params['limit'] = int(limit)
    else:
        query = base_query
    try:
        _, rows = _fetch_rows(query, params)
        return (rows, total_count)
    except Exception as e:
        print(f'[ERROR get_items_list] {e}')
        import traceback
        traceback.print_exc()
        return ([], 0)

def get_sessions(location_code: Optional[int]=None) -> List[Dict[str, Any]]:
    """Get delivery sessions from TBLSESSION"""
    location_col = _detect_column('TBLSESSION', ['LOCATIONCODE', 'LOCATION_CODE'])
    where_clause = ''
    params: Dict[str, Any] = {}
    if location_col and location_code is not None:
        where_clause = f'WHERE {location_col} = :location_code'
        params['location_code'] = location_code
    query = f'\n        SELECT SESSIONCODE AS CODE, SESSIONNAME AS NAME\n        FROM TBLSESSION\n        {where_clause}\n        ORDER BY SESSIONCODE\n    '
    try:
        _, rows = _fetch_rows(query, params)
        return rows
    except Exception:
        return []

def get_open_bill_date(location_code: int) -> Optional[datetime]:
    """Get open bill date from TBLTRANSACTIONDATE"""
    query = "\n        SELECT DATEOFOPEN\n        FROM TBLTRANSACTIONDATE\n        WHERE LOCATIONCODE = :location_code\n          AND OPENFLAG = 'O'\n          AND TRANSACTIONCODE = 1\n    "
    try:
        result = _get_scalar(query, {'location_code': location_code})
        return result
    except Exception:
        return None

def _itemjournal_pk_columns(conn, tbl_u: str) -> List[str]:
    """Primary-key column names for ITEMJOURNAL / ITEMJOURNEL (uppercase), or []."""
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT cc.column_name
                FROM user_constraints c
                JOIN user_cons_columns cc
                  ON cc.constraint_name = c.constraint_name AND cc.table_name = c.table_name
                WHERE c.table_name = :t AND c.constraint_type = 'P'
                ORDER BY cc.position
                """,
                {'t': str(tbl_u or '').upper()},
            )
            return [str(r[0] or '').upper() for r in cur.fetchall() or []]
    except Exception:
        return []


def _itemjournal_has_legacy_receiptno_unique(conn: Any, tbl_u: str) -> bool:
    """True when legacy unique index on (LOC, RESET, RECEIPTNO, LINENO) still exists (ITEMJOURNAL_PK)."""
    t = str(tbl_u or '').upper()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT COUNT(*) FROM user_indexes i
                WHERE i.table_name = :t AND i.uniqueness = 'UNIQUE'
                  AND UPPER(i.index_name) IN ('ITEMJOURNAL_PK', 'ITEMJOURNEL_PK')
                """,
                {'t': t},
            )
            if int((cur.fetchone() or [0])[0] or 0) > 0:
                return True
            cur.execute(
                """
                SELECT COUNT(DISTINCT ic.index_name) FROM user_ind_columns ic
                JOIN user_indexes i ON i.index_name = ic.index_name AND i.table_name = ic.table_name
                WHERE ic.table_name = :t AND i.uniqueness = 'UNIQUE'
                  AND i.index_name NOT LIKE 'PK_%'
                GROUP BY ic.index_name
                HAVING SUM(CASE WHEN ic.column_name = 'RECEIPTNO' THEN 1 ELSE 0 END) > 0
                   AND SUM(CASE WHEN ic.column_name = 'LINENO' THEN 1 ELSE 0 END) > 0
                   AND SUM(CASE WHEN ic.column_name = 'LOCATIONCODE' THEN 1 ELSE 0 END) > 0
                """,
                {'t': t},
            )
            return cur.fetchone() is not None
    except Exception:
        return False


def _drop_legacy_itemjournal_receiptno_index(conn: Any, tbl_u: str) -> None:
    """Drop orphaned ITEMJOURNAL_PK unique index after surrogate PK migration (safe to repeat)."""
    t = str(tbl_u or '').upper()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT index_name FROM user_indexes
                WHERE table_name = :t AND uniqueness = 'UNIQUE'
                  AND UPPER(index_name) IN ('ITEMJOURNAL_PK', 'ITEMJOURNEL_PK')
                """,
                {'t': t},
            )
            for (idx_name,) in cur.fetchall() or []:
                try:
                    cur.execute(f'DROP INDEX {idx_name}')
                except Exception:
                    pass
    except Exception:
        pass


def _itemjournal_needs_receiptno_namespace(conn: Any, tbl_u: str) -> bool:
    """True when RECEIPTNO+LINENO must be namespaced per SOURCE_DOC (composite PK or legacy unique index)."""
    pk = _itemjournal_pk_columns(conn, tbl_u)
    if bool(pk) and pk != ['ITEMJOURNAL_ID']:
        return True
    return _itemjournal_has_legacy_receiptno_unique(conn, tbl_u)


def ensure_itemjournal_surrogate_pk(conn) -> None:
    """Upgrade ITEMJOURNAL / ITEMJOURNEL: add ITEMJOURNAL_ID, drop legacy composite PK on
    (LOCATIONCODE, RESETNO, RECEIPTNO, LINENO), primary key on ITEMJOURNAL_ID only, BEFORE INSERT
    trigger assigns next sequence value. RECEIPTNO is no longer part of the primary key."""
    global _ITEMJOURNAL_SURROGATE_PK_ENSURED
    if _ITEMJOURNAL_SURROGATE_PK_ENSURED:
        return
    id_col = 'ITEMJOURNAL_ID'

    def _ensure_bi_trigger(tbl_u: str, seq_name: str, trg_name: str) -> None:
        with conn.cursor() as cur:
            cur.execute(f'\n                CREATE OR REPLACE TRIGGER {trg_name}\n                BEFORE INSERT ON {tbl_u}\n                FOR EACH ROW\n                BEGIN\n                  IF :NEW.{id_col} IS NULL THEN\n                    SELECT {seq_name}.NEXTVAL INTO :NEW.{id_col} FROM DUAL;\n                  END IF;\n                END;\n                ')

    def _migrate_one_journal_table(tbl_u: str) -> None:
        seq_name = f'{tbl_u}_SEQ'
        if len(seq_name) > 30:
            seq_name = seq_name[:30]
        trg_name = f'TRG_{tbl_u}_BI'
        if len(trg_name) > 30:
            trg_name = trg_name[:30]
        with conn.cursor() as cur:
            cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': tbl_u})
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                return
            cur.execute('SELECT COUNT(*) FROM user_tab_columns WHERE table_name = :t AND column_name = :c', {'t': tbl_u, 'c': id_col})
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                cur.execute(f'ALTER TABLE {tbl_u} ADD ({id_col} NUMBER(18,0))')
            cur.execute("\n                SELECT constraint_name\n                FROM user_constraints\n                WHERE table_name = :t AND constraint_type = 'P'\n                ", {'t': tbl_u})
            pk_row = cur.fetchone()
            pk_name = pk_row[0] if pk_row else None
            pk_cols: List[str] = []
            if pk_name:
                cur.execute('\n                    SELECT column_name\n                    FROM user_cons_columns\n                    WHERE constraint_name = :cn AND table_name = :t\n                    ORDER BY position\n                    ', {'cn': pk_name, 't': tbl_u})
                pk_cols = [str(r[0] or '').upper() for r in cur.fetchall()]
            if pk_cols == [id_col]:
                cur.execute('SELECT COUNT(*) FROM user_sequences WHERE sequence_name = :s', {'s': seq_name})
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute(f'\n                        CREATE SEQUENCE {seq_name}\n                        MINVALUE 1 MAXVALUE 999999999999999999\n                        START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE\n                        ')
                    cur.execute(f'SELECT NVL(MAX({id_col}), 0) + 1 FROM {tbl_u}')
                    next_start = max(1, int((cur.fetchone() or [0])[0] or 1))
                    cur.execute(f'DROP SEQUENCE {seq_name}')
                    cur.execute(f'\n                        CREATE SEQUENCE {seq_name}\n                        MINVALUE 1 MAXVALUE 999999999999999999\n                        START WITH {next_start} INCREMENT BY 1 NOCACHE NOCYCLE\n                        ')
                _ensure_bi_trigger(tbl_u, seq_name, trg_name)
            else:
                try:
                    cur.execute('SELECT COUNT(*) FROM user_triggers WHERE trigger_name = :tn', {'tn': trg_name})
                    if int((cur.fetchone() or [0])[0] or 0) > 0:
                        cur.execute(f'DROP TRIGGER {trg_name}')
                except Exception:
                    pass
                cur.execute('SELECT COUNT(*) FROM user_sequences WHERE sequence_name = :s', {'s': seq_name})
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute(f'\n                    CREATE SEQUENCE {seq_name}\n                    MINVALUE 1 MAXVALUE 999999999999999999\n                    START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE\n                    ')
                cur.execute(f'SELECT COUNT(*) FROM {tbl_u} WHERE {id_col} IS NULL')
                if int((cur.fetchone() or [0])[0] or 0) > 0:
                    cur.execute(f'SELECT ROWID FROM {tbl_u} WHERE {id_col} IS NULL')
                    for rid, in cur.fetchall():
                        cur.execute(f'UPDATE {tbl_u} SET {id_col} = {seq_name}.NEXTVAL WHERE ROWID = :rid', {'rid': rid})
                cur.execute(f'SELECT NVL(MAX({id_col}), 0) + 1 FROM {tbl_u}')
                next_start = max(1, int((cur.fetchone() or [0])[0] or 1))
                try:
                    cur.execute(f'DROP SEQUENCE {seq_name}')
                except Exception:
                    pass
                cur.execute(f'\n                CREATE SEQUENCE {seq_name}\n                MINVALUE 1 MAXVALUE 999999999999999999\n                START WITH {next_start} INCREMENT BY 1 NOCACHE NOCYCLE\n                ')
                if pk_name and pk_cols != [id_col]:
                    cur.execute(f'ALTER TABLE {tbl_u} DROP CONSTRAINT {pk_name}')
                cur.execute("\n                SELECT COUNT(*) FROM user_tab_columns\n                WHERE table_name = :t AND column_name = :c AND nullable = 'N'\n                ", {'t': tbl_u, 'c': id_col})
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute(f'ALTER TABLE {tbl_u} MODIFY ({id_col} NOT NULL)')
                cur.execute("SELECT COUNT(*) FROM user_constraints WHERE table_name = :t AND constraint_type = 'P'", {'t': tbl_u})
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    pk_new = f'PK_{tbl_u}_JID'
                    if len(pk_new) > 30:
                        pk_new = pk_new[:30]
                    cur.execute(f'ALTER TABLE {tbl_u} ADD CONSTRAINT {pk_new} PRIMARY KEY ({id_col})')
                _ensure_bi_trigger(tbl_u, seq_name, trg_name)
        _drop_legacy_itemjournal_receiptno_index(conn, tbl_u)
    for physical in ('ITEMJOURNAL', 'ITEMJOURNEL'):
        try:
            with conn.cursor() as cur:
                cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': physical})
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    continue
        except Exception:
            continue
        if _itemjournal_pk_columns(conn, physical) == [id_col]:
            # Already migrated. Do NOT DROP INDEX on this path — DDL while a sales
            # transaction is open can wait forever on enq:TM and leave the UI on "Saving...".
            continue
        _migrate_one_journal_table(physical)
    _ITEMJOURNAL_SURROGATE_PK_ENSURED = True

def _resolve_itemjournal_backfill_table(prefer_itemjournel: bool=True) -> Optional[str]:
    """Physical journal table: prefer ITEMJOURNEL when requested and present, else ITEMJOURNAL."""
    order = ('ITEMJOURNEL', 'ITEMJOURNAL') if prefer_itemjournel else ('ITEMJOURNAL', 'ITEMJOURNEL')
    return _resolve_itemjournal_table_name(candidates=order)

def _ensure_itemjournal_trace_columns_for_table(cur: Any, tbl_u: str) -> None:
    """Add trace columns used by GRN/sales/PR journal rows if the legacy table is missing them."""
    extras = [('TOTALINVENTORY', 'NUMBER(18,3) DEFAULT 0'), ('TRANSTYPE', 'VARCHAR2(20)'), ('SOURCE_DOC', 'VARCHAR2(30)'), ('SOURCE_NO', 'VARCHAR2(50)'), ('STORAGE_ID', 'NUMBER'), ('WAREHOUSE_ID', 'NUMBER'), ('BATCH_NO', 'VARCHAR2(80)'), ('MFG_DATE', 'DATE'), ('EXPIRY_DATE', 'DATE'), ('LOT_ID', 'NUMBER'), ('AVERAGECOST', 'NUMBER(18,4) DEFAULT 0')]
    for col, typ in extras:
        cur.execute('SELECT COUNT(*) FROM user_tab_columns WHERE table_name = :t AND column_name = :c', {'t': tbl_u, 'c': col})
        if int((cur.fetchone() or [0])[0] or 0) == 0:
            try:
                cur.execute(f'ALTER TABLE {tbl_u} ADD ({col} {typ})')
            except Exception:
                pass

def _journal_cols_upper(cur: Any, tbl_u: str) -> Set[str]:
    cur.execute('SELECT column_name FROM user_tab_columns WHERE table_name = :t', {'t': tbl_u})
    return {str(r[0] or '').upper() for r in cur.fetchall() or []}

def _sql_ident_col(val: Any) -> Optional[str]:
    """Ensure we only embed real Oracle identifiers in SQL (avoid f-string ``d.None`` / ``d.nan``)."""
    if val is None:
        return None
    if isinstance(val, float):
        if val != val:
            return None
        return None
    if not isinstance(val, str):
        return None
    s = val.strip()
    if not s or s.upper() in ('NONE', 'NULL'):
        return None
    return s

def _journal_row_exists(cur: Any, tbl_u: str, jcols: Set[str], loc: int, reset: int, receipt: int, lineno: int, source_doc: str, source_no: str) -> bool:
    loc_c = 'LOCATIONCODE' if 'LOCATIONCODE' in jcols else None
    reset_c = 'RESETNO' if 'RESETNO' in jcols else None
    rec_c = 'RECEIPTNO' if 'RECEIPTNO' in jcols else None
    ln_c = 'LINENO' if 'LINENO' in jcols else None
    sd_c = 'SOURCE_DOC' if 'SOURCE_DOC' in jcols else None
    sn_c = 'SOURCE_NO' if 'SOURCE_NO' in jcols else None
    if not all([loc_c, reset_c, rec_c, ln_c]):
        return True
    parts = [f'{loc_c} = :loc', f'{reset_c} = :rn', f'{rec_c} = :rno', f'{ln_c} = :ln']
    params: Dict[str, Any] = {'loc': loc, 'rn': reset, 'rno': receipt, 'ln': lineno}
    if sd_c and sn_c:
        parts.append(f"NVL({sd_c}, '@') = NVL(:sd, '@')")
        parts.append(f"NVL(TO_CHAR({sn_c}), '@') = NVL(:sn, '@')")
        params['sd'] = source_doc
        params['sn'] = source_no
    sql = f"SELECT 1 FROM {tbl_u} WHERE {' AND '.join(parts)} AND ROWNUM = 1"
    cur.execute(sql, params)
    return cur.fetchone() is not None


def _journal_row_exists_any(
    cur: Any,
    conn: Any,
    loc: int,
    reset: int,
    receipt: int,
    lineno: int,
    source_doc: str,
    source_no: str,
) -> bool:
    """True when a matching line exists in any journal read table (ITEMJOURNAL / ITEMJOURNEL)."""
    for tbl in _itemjournal_read_tables(cur, conn):
        tbl_u = tbl.upper()
        jcols = _journal_cols_upper(cur, tbl_u)
        if _journal_row_exists(cur, tbl_u, jcols, loc, reset, receipt, lineno, source_doc, source_no):
            return True
    return False


def _alloc_itemjournal_id_cur(cur: Any, tbl_u: str) -> Optional[int]:
    """Next ITEMJOURNAL_ID from ``{TABLE}_SEQ`` (works with or without BI trigger)."""
    seq_name = f'{str(tbl_u or "").upper()}_SEQ'[:30]
    try:
        cur.execute(f'SELECT {seq_name}.NEXTVAL FROM DUAL')
        r = cur.fetchone()
        return int(r[0]) if r and r[0] is not None else None
    except Exception:
        return None


def _alloc_itemjournal_ids_cur(cur: Any, tbl_u: str, count: int) -> List[int]:
    """Allocate multiple ITEMJOURNAL_ID values in one round-trip."""
    n = int(count or 0)
    if n <= 0:
        return []
    seq_name = f'{str(tbl_u or "").upper()}_SEQ'[:30]
    out: List[int] = []
    try:
        cur.execute(
            f'SELECT {seq_name}.NEXTVAL FROM DUAL CONNECT BY LEVEL <= :n',
            {'n': n},
        )
        out = [int(r[0]) for r in cur.fetchall() or [] if r and r[0] is not None]
        if len(out) == n:
            return out
    except Exception:
        out = []
    for _ in range(n - len(out)):
        jid = _alloc_itemjournal_id_cur(cur, tbl_u)
        if jid is None:
            break
        out.append(jid)
    return out


def _journal_row_map_for_insert(
    jcols: Set[str],
    values: Dict[str, Any],
    *,
    itemjournal_id: Optional[int] = None,
) -> Dict[str, Any]:
    """Normalize a journal insert map (shared by single and bulk insert)."""
    skip = {'ITEMJOURNAL_ID', 'CREATEDDATE'}
    norm_vals = {str(k or '').upper(): v for k, v in (values or {}).items()}
    row: Dict[str, Any] = {}
    if itemjournal_id is not None and 'ITEMJOURNAL_ID' in jcols:
        row['ITEMJOURNAL_ID'] = int(itemjournal_id)
    for cu in jcols:
        if cu in skip:
            continue
        if cu in norm_vals:
            row[cu] = norm_vals[cu]
    if 'CREATEDDATE' in jcols:
        row['CREATEDDATE'] = True
    return row


def _journal_insert_many_from_maps(
    cur: Any,
    tbl_u: str,
    jcols: Set[str],
    row_maps: List[Dict[str, Any]],
    *,
    dry_run: bool = False,
) -> int:
    """Bulk insert journal rows (executemany + batched sequence ids)."""
    if not row_maps:
        return 0
    if dry_run:
        return len(row_maps)
    built: List[Dict[str, Any]] = []
    ids: List[int] = []
    if 'ITEMJOURNAL_ID' in jcols:
        ids = _alloc_itemjournal_ids_cur(cur, tbl_u, len(row_maps))
        if len(ids) != len(row_maps):
            # Bulk sequence allocation can fail under load; caller falls back row-by-row.
            return 0
    for idx, values in enumerate(row_maps):
        jid = ids[idx] if idx < len(ids) else None
        built.append(_journal_row_map_for_insert(jcols, values, itemjournal_id=jid))
    if not built:
        return 0
    use: List[str] = []
    use_set: Set[str] = set()
    for row in built:
        for cu in row.keys():
            if cu in jcols and cu not in use_set:
                if cu == 'CREATEDDATE':
                    use.append('CREATEDDATE')
                else:
                    use.append(cu)
                use_set.add(cu)
    if 'ITEMJOURNAL_ID' in jcols and 'ITEMJOURNAL_ID' not in use_set:
        use = ['ITEMJOURNAL_ID'] + use
    if not use:
        return 0
    val_parts: List[str] = []
    for cu in use:
        if cu == 'CREATEDDATE':
            val_parts.append('SYSDATE')
        else:
            val_parts.append(f':b_{cu.lower()}')
    sql = f"INSERT INTO {tbl_u} ({', '.join(use)}) VALUES ({', '.join(val_parts)})"
    binds: List[Dict[str, Any]] = []
    for row in built:
        b: Dict[str, Any] = {}
        for cu in use:
            if cu == 'CREATEDDATE':
                continue
            b[f'b_{cu.lower()}'] = row.get(cu)
        binds.append(b)
    cur.executemany(sql, binds)
    return len(binds)


def _journal_insert_from_map(cur: Any, tbl_u: str, jcols: Set[str], values: Dict[str, Any], *, dry_run: bool) -> bool:
    """Insert one journal row using only columns present on the table; assigns ITEMJOURNAL_ID when present."""
    skip = {'ITEMJOURNAL_ID'}
    norm_vals = {str(k or '').upper(): v for k, v in (values or {}).items()}
    use = [cu for cu in jcols if cu not in skip and cu in norm_vals]
    if 'CREATEDDATE' in jcols:
        use.append('CREATEDDATE')
    jid: Optional[int] = None
    if 'ITEMJOURNAL_ID' in jcols:
        jid = _alloc_itemjournal_id_cur(cur, tbl_u)
        if jid is None:
            raise RuntimeError(f'Could not allocate ITEMJOURNAL_ID for {tbl_u}')
        use = ['ITEMJOURNAL_ID'] + [c for c in use if c != 'ITEMJOURNAL_ID']
    if not use:
        raise RuntimeError(f'No insertable ITEMJOURNAL columns for {tbl_u}')
    cols_sql = ', '.join(use)
    placeholders = []
    bind: Dict[str, Any] = {}
    for cu in use:
        if cu == 'CREATEDDATE':
            placeholders.append('SYSDATE')
        elif cu == 'ITEMJOURNAL_ID':
            placeholders.append(':b_itemjournal_id')
            bind['b_itemjournal_id'] = jid
        else:
            placeholders.append(f':b_{cu.lower()}')
            bind[f'b_{cu.lower()}'] = norm_vals.get(cu)
    ph = ', '.join(placeholders)
    sql = f'INSERT INTO {tbl_u} ({cols_sql}) VALUES ({ph})'
    if dry_run:
        return True
    cur.execute(sql, bind)
    return True

ITEMJOURNAL_TRANSTYPE_REVERSAL = 'REVERSAL'
ITEMJOURNAL_SOURCE_GRN = 'GRN'
ITEMJOURNAL_SOURCE_PURCHASE_RETURN = 'RETURN'
ITEMJOURNAL_SOURCE_SALES = 'BILL'
ITEMJOURNAL_SOURCE_SALES_RETURN = 'BILL RETURN'
ITEMJOURNAL_SOURCE_POS = 'POS'
ITEMJOURNAL_SOURCE_POS_RETURN = 'POS RETURN'
ITEMJOURNAL_SOURCE_STOCK_COUNT = 'STOCK_COUNT'
ITEMJOURNAL_SOURCE_STOCK_ADJ = 'STKADJ'
ITEMJOURNAL_SOURCE_REPACK = 'REPACK'
ITEMJOURNAL_HDR_TABLE = 'ITEMJOURNAL_HDR'
ITEMJOURNAL_HDR_SEQ = 'ITEMJOURNAL_HDR_SEQ'
# Legacy PK (LOC, RESET, RECEIPTNO, LINENO) — separate RECEIPTNO namespace per SOURCE_DOC.
ITEMJOURNAL_LEGACY_OFFSET_GRN = 900_000_000
ITEMJOURNAL_LEGACY_OFFSET_SALES_RETURN = 800_000_000
ITEMJOURNAL_LEGACY_OFFSET_POS = 700_000_000
ITEMJOURNAL_LEGACY_OFFSET_POS_RETURN = 600_000_000
ITEMJOURNAL_LEGACY_OFFSET_REPACK = 530_000_000
ITEMJOURNAL_LEGACY_OFFSET_STOCK_ADJ = 540_000_000
ITEMJOURNAL_LEGACY_OFFSET_STOCK_COUNT = 550_000_000
ITEMJOURNAL_LEGACY_OFFSET_UNKNOWN = 950_000_000


def _itemjournal_legacy_composite_pk(conn: Any, tbl_u: str) -> bool:
    """True when PK still uses RECEIPTNO+LINENO (document types share one number pool)."""
    pk = _itemjournal_pk_columns(conn, tbl_u)
    return bool(pk) and pk != ['ITEMJOURNAL_ID']


def _itemjournal_doc_number(source_no: str, receipt_no: int) -> int:
    n = billno_numeric_part(source_no)
    if n > 0:
        return n
    try:
        n = int(receipt_no or 0)
    except (TypeError, ValueError):
        n = 0
    return max(0, abs(n))


def _itemjournal_journal_receiptno(
    conn: Any,
    tbl_u: str,
    source_doc: str,
    source_no: str,
    receipt_no: int,
) -> int:
    """Physical RECEIPTNO for journal INSERT — scoped by SOURCE_DOC when legacy unique index/PK exists."""
    if not _itemjournal_needs_receiptno_namespace(conn, tbl_u):
        return int(receipt_no)
    sd = str(source_doc or '').strip().upper()
    doc_n = _itemjournal_doc_number(source_no, int(receipt_no or 0))
    n = max(1, doc_n)
    if sd == ITEMJOURNAL_SOURCE_PURCHASE_RETURN or sd == 'RETURN':
        return -n
    if sd == ITEMJOURNAL_SOURCE_GRN:
        return ITEMJOURNAL_LEGACY_OFFSET_GRN + n
    if sd == ITEMJOURNAL_SOURCE_SALES_RETURN or sd == 'BILL RETURN':
        return ITEMJOURNAL_LEGACY_OFFSET_SALES_RETURN + n
    if sd == ITEMJOURNAL_SOURCE_POS_RETURN:
        return ITEMJOURNAL_LEGACY_OFFSET_POS_RETURN + n
    if sd == ITEMJOURNAL_SOURCE_POS:
        return ITEMJOURNAL_LEGACY_OFFSET_POS + n
    if sd == ITEMJOURNAL_SOURCE_STOCK_COUNT:
        return ITEMJOURNAL_LEGACY_OFFSET_STOCK_COUNT + n
    if sd == ITEMJOURNAL_SOURCE_REPACK or sd == 'REPACK':
        return ITEMJOURNAL_LEGACY_OFFSET_REPACK + n
    if sd == ITEMJOURNAL_SOURCE_STOCK_ADJ or sd == 'STKADJ':
        return ITEMJOURNAL_LEGACY_OFFSET_STOCK_ADJ + n
    if sd == ITEMJOURNAL_SOURCE_SALES or sd == 'BILL':
        return n
    return ITEMJOURNAL_LEGACY_OFFSET_UNKNOWN + n


def _delete_legacy_orphan_itemjournal_cur(
    cur: Any,
    tbl_u: str,
    location_code: int,
    reset_no: int,
    journal_receipt_no: int,
    source_doc: str,
    transtype: str,
) -> int:
    """Remove pre-SOURCE_DOC rows that used raw RECEIPTNO (sales/POS/purchase-return family)."""
    jcols = _journal_cols_upper(cur, tbl_u)
    loc_c = 'LOCATIONCODE' if 'LOCATIONCODE' in jcols else None
    rn_c = 'RESETNO' if 'RESETNO' in jcols else None
    rno_c = 'RECEIPTNO' if 'RECEIPTNO' in jcols else None
    sd_c = 'SOURCE_DOC' if 'SOURCE_DOC' in jcols else None
    tt_c = 'TRANSTYPE' if 'TRANSTYPE' in jcols else None
    if not all([loc_c, rn_c, rno_c, sd_c]):
        return 0
    sd = str(source_doc or '').strip().upper()
    allowed_sd = {
        ITEMJOURNAL_SOURCE_SALES, 'BILL',
        ITEMJOURNAL_SOURCE_SALES_RETURN, 'BILL RETURN',
        ITEMJOURNAL_SOURCE_POS, ITEMJOURNAL_SOURCE_POS_RETURN,
        ITEMJOURNAL_SOURCE_PURCHASE_RETURN, 'RETURN',
    }
    if sd not in allowed_sd:
        return 0
    tt_filter = ''
    if tt_c:
        if sd in (ITEMJOURNAL_SOURCE_SALES, 'BILL'):
            tt_filter = f" AND NVL({tt_c}, ' ') LIKE 'SALES%'"
        elif sd in (ITEMJOURNAL_SOURCE_SALES_RETURN, 'BILL RETURN'):
            tt_filter = f" AND NVL({tt_c}, ' ') LIKE 'SALES%RETURN%'"
        elif sd == ITEMJOURNAL_SOURCE_POS:
            tt_filter = f" AND NVL({tt_c}, ' ') LIKE 'POS%'"
        elif sd == ITEMJOURNAL_SOURCE_POS_RETURN:
            tt_filter = f" AND NVL({tt_c}, ' ') LIKE 'POS%RETURN%'"
        elif sd in (ITEMJOURNAL_SOURCE_PURCHASE_RETURN, 'RETURN'):
            tt_filter = f" AND UPPER(NVL({tt_c}, ' ')) = 'PURCHASE_RETURN'"
    sql = f"""
        DELETE FROM {tbl_u}
        WHERE {loc_c} = :loc AND {rn_c} = :rn AND {rno_c} = :rno
          AND ( {sd_c} IS NULL OR TRIM({sd_c}) = '' )
          {tt_filter}
    """
    try:
        cur.execute(sql, {'loc': int(location_code), 'rn': int(reset_no), 'rno': int(journal_receipt_no)})
        return int(cur.rowcount or 0)
    except Exception:
        return 0


def _delete_itemjournal_purchase_return_by_receiptno_cur(
    cur: Any,
    tbl_u: str,
    location_code: int,
    reset_no: int,
    goods_return_no: int,
    journal_receipt_no: int,
) -> int:
    """Remove purchase-return rows keyed by legacy (+n) or namespaced (-n) RECEIPTNO."""
    jcols = _journal_cols_upper(cur, tbl_u)
    loc_c = 'LOCATIONCODE' if 'LOCATIONCODE' in jcols else None
    rn_c = 'RESETNO' if 'RESETNO' in jcols else None
    rno_c = 'RECEIPTNO' if 'RECEIPTNO' in jcols else None
    sd_c = 'SOURCE_DOC' if 'SOURCE_DOC' in jcols else None
    tt_c = 'TRANSTYPE' if 'TRANSTYPE' in jcols else None
    if not all([loc_c, rn_c, rno_c]):
        return 0
    doc_n = max(1, abs(billno_numeric_part(goods_return_no)))
    rnos = sorted({doc_n, -doc_n, int(journal_receipt_no or 0)})
    rno_ph = ', '.join(f':rno{i}' for i in range(len(rnos)))
    params: Dict[str, Any] = {'loc': int(location_code), 'rn': int(reset_no)}
    for i, rv in enumerate(rnos):
        params[f'rno{i}'] = int(rv)
    type_filter = ''
    if tt_c and sd_c:
        type_filter = (
            f" AND ( UPPER(NVL({tt_c}, ' ')) = 'PURCHASE_RETURN' "
            f"OR UPPER(NVL({sd_c}, ' ')) IN ('RETURN', '{ITEMJOURNAL_SOURCE_PURCHASE_RETURN}') )"
        )
    elif tt_c:
        type_filter = f" AND UPPER(NVL({tt_c}, ' ')) = 'PURCHASE_RETURN'"
    elif sd_c:
        type_filter = f" AND UPPER(NVL({sd_c}, ' ')) IN ('RETURN', '{ITEMJOURNAL_SOURCE_PURCHASE_RETURN}')"
    sql = f"""
        DELETE FROM {tbl_u}
        WHERE {loc_c} = :loc AND {rn_c} = :rn
          AND {rno_c} IN ({rno_ph})
          {type_filter}
    """
    try:
        cur.execute(sql, params)
        return int(cur.rowcount or 0)
    except Exception:
        return 0


def _resolve_itemjournal_table_name(
    cur: Any = None,
    *,
    candidates: tuple = ('ITEMJOURNEL', 'ITEMJOURNAL'),
    conn: Any = None,
) -> Optional[str]:
    """Resolve primary journal table (same as posting). Falls back to legacy candidate order."""
    canonical = _resolve_itemjournal_post_table(cur, conn)
    if canonical:
        return canonical
    for t in candidates:
        try:
            if cur is not None:
                cur.execute(
                    'SELECT COUNT(*) FROM user_tables WHERE table_name = :t',
                    {'t': t},
                )
                row = cur.fetchone()
                exists = int((row[0] if row else 0) or 0) > 0
            else:
                exists = _get_count(
                    'SELECT COUNT(*) AS cnt FROM user_tables WHERE table_name = :table_name',
                    {'table_name': t},
                ) > 0
            _TABLE_EXISTS_CACHE[t] = exists
            if exists:
                return t
        except Exception:
            _TABLE_EXISTS_CACHE[t] = False
    return None


def _resolve_itemjournal_post_table(cur: Any = None, conn: Any = None) -> Optional[str]:
    """Physical table for INSERT/UPDATE/DELETE — prefer migrated ITEMJOURNAL when both exist."""
    order = ('ITEMJOURNEL', 'ITEMJOURNAL')
    present: List[str] = []
    for t in order:
        try:
            if cur is not None:
                cur.execute(
                    'SELECT COUNT(*) FROM user_tables WHERE table_name = :t',
                    {'t': t},
                )
                row = cur.fetchone()
                exists = int((row[0] if row else 0) or 0) > 0
            else:
                exists = _get_count(
                    'SELECT COUNT(*) AS cnt FROM user_tables WHERE table_name = :table_name',
                    {'table_name': t},
                ) > 0
            _TABLE_EXISTS_CACHE[t] = exists
            if exists:
                present.append(t)
        except Exception:
            _TABLE_EXISTS_CACHE[t] = False
    if not present:
        return None
    if len(present) == 1:
        return present[0]
    conn_for_pk = conn
    if conn_for_pk is None and cur is not None:
        try:
            conn_for_pk = cur.connection
        except Exception:
            conn_for_pk = None
    if conn_for_pk is not None:
        for t in ('ITEMJOURNAL', 'ITEMJOURNEL'):
            if t in present:
                try:
                    if _itemjournal_pk_columns(conn_for_pk, t) == ['ITEMJOURNAL_ID']:
                        return t
                except Exception:
                    pass
    return 'ITEMJOURNAL' if 'ITEMJOURNAL' in present else present[0]


def _journal_insert_prepared_rows(
    cur: Any,
    tbl_u: str,
    jcols: Set[str],
    prepared: List[Dict[str, Any]],
) -> int:
    """Insert journal rows; bulk when large, row-by-row fallback if bulk fails."""
    if not prepared:
        return 0
    n = 0
    if len(prepared) >= 20:
        n = _journal_insert_many_from_maps(cur, tbl_u, jcols, prepared)
    if n >= len(prepared):
        return n
    start_at = n
    for row_map in prepared[start_at:]:
        if _journal_insert_from_map(cur, tbl_u, jcols, row_map, dry_run=False):
            n += 1
    return n


def _require_itemjournal_lines_inserted(
    expected: int,
    inserted: int,
    *,
    source_doc: str,
    source_no: str,
    tbl_u: Optional[str] = None,
) -> None:
    if expected <= 0:
        return
    if inserted >= expected:
        return
    tbl_part = f' into {tbl_u}' if tbl_u else ''
    raise ValueError(
        f'Item journal incomplete{tbl_part}: inserted {inserted} of {expected} line(s) '
        f'for {source_doc} {source_no}. Save rolled back — retry once; if it persists, '
        f'run Admin → ensure ITEMJOURNAL sequence/PK migration.'
    )


def _is_itemjournal_reversal_transtype(transtype: Any) -> bool:
    t = str(transtype or '').strip().upper()
    return t == ITEMJOURNAL_TRANSTYPE_REVERSAL or t.startswith('REV-') or t.startswith('REV ')


def _journal_negate_numeric(val: Any) -> Any:
    try:
        return -float(val or 0)
    except (TypeError, ValueError):
        return val


def _journal_fill_amount_fields(row: Dict[str, Any]) -> Dict[str, Any]:
    """Backfill AMOUNT / VAT / TOTALAMOUNT when legacy rows stored qty only (common on STKADJ)."""
    out = dict(row or {})
    norm = {str(k or '').upper(): v for k, v in out.items()}

    def _f(key: str, default: float = 0.0) -> float:
        raw = norm.get(key)
        if raw is None or str(raw).strip() == '':
            return default
        try:
            return float(raw)
        except (TypeError, ValueError):
            return default

    qty = _f('QTY')
    rate = 0.0
    for key in ('RATE', 'AVERAGECOST'):
        v = _f(key)
        if abs(v) > 1e-09:
            rate = v
            break
    amt = _f('AMOUNT')
    if abs(amt) < 0.0005 and abs(qty) > 1e-09 and abs(rate) > 1e-09:
        amt = round(qty * rate, 3)
        out['AMOUNT'] = amt
        norm['AMOUNT'] = amt
    vat_pct = _f('VATPERCENT')
    vat_amt = _f('VATAMOUNT')
    if abs(vat_amt) < 0.0005 and abs(amt) > 0.0005 and abs(vat_pct) > 1e-09:
        vat_amt = round(amt * vat_pct / 100.0, 3)
        out['VATAMOUNT'] = vat_amt
        norm['VATAMOUNT'] = vat_amt
    total = _f('TOTALAMOUNT')
    if abs(total) < 0.0005 and (abs(amt) > 0.0005 or abs(vat_amt) > 0.0005):
        total = round(amt + vat_amt, 3)
        out['TOTALAMOUNT'] = total
    return out


def _journal_row_fingerprint(row: Dict[str, Any], *, negate_qty: bool = False) -> Tuple[str, str, float, str, str]:
    """Stable key to match an original journal line to its REVERSAL counterpart."""
    try:
        qty = round(float(row.get('QTY') or 0), 3)
    except (TypeError, ValueError):
        qty = 0.0
    if negate_qty:
        qty = -qty
    wh = str(
        row.get('WAREHOUSE_CODE')
        or row.get('INVENTORYLOCATION')
        or row.get('WAREHOUSE_ID')
        or ''
    ).strip().upper()
    return (
        str(row.get('LINENO') if row.get('LINENO') is not None else ''),
        str(row.get('ITEMCODE') if row.get('ITEMCODE') is not None else '').strip(),
        qty,
        wh,
        str(row.get('UOM') or '').strip().upper(),
    )


def _journal_rows_for_document(
    cur: Any,
    tbl_u: str,
    jcols: Set[str],
    location_code: int,
    reset_no: int,
    source_doc: str,
    source_no: str,
    *,
    receipt_no: Optional[int]=None,
    open_only: bool=True,
) -> List[Dict[str, Any]]:
    """Fetch journal lines for a source document.

    When ``open_only`` is True (default), return only non-reversal rows that are not yet
    matched by a later REVERSAL. This prevents re-edit/repost from reversing the same
    historical STOCK_ADJ/SALES/... lines again (which inflated Item Journal qty while
    ITEMMASTER only applied stock deltas).
    """
    loc_c = 'LOCATIONCODE' if 'LOCATIONCODE' in jcols else None
    rn_c = 'RESETNO' if 'RESETNO' in jcols else None
    sd_c = 'SOURCE_DOC' if 'SOURCE_DOC' in jcols else None
    sn_c = 'SOURCE_NO' if 'SOURCE_NO' in jcols else None
    tt_c = 'TRANSTYPE' if 'TRANSTYPE' in jcols else None
    rno_c = 'RECEIPTNO' if 'RECEIPTNO' in jcols else None
    if not all([loc_c, rn_c, sd_c, sn_c]):
        return []
    sel_cols = sorted(jcols)
    if not sel_cols:
        return []
    parts = [
        f'{loc_c} = :loc',
        f'{rn_c} = :rn',
        f'{sd_c} = :sd',
        f"NVL(TO_CHAR({sn_c}), '@') = NVL(:sn, '@')",
    ]
    params: Dict[str, Any] = {
        'loc': int(location_code),
        'rn': int(reset_no),
        'sd': str(source_doc or '')[:30],
        'sn': str(source_no or '')[:50],
    }
    if receipt_no is not None and rno_c:
        parts.append(f'{rno_c} = :rno')
        params['rno'] = int(receipt_no)
    order_bits = []
    if 'CREATEDDATE' in jcols:
        order_bits.append('CREATEDDATE ASC NULLS LAST')
    if 'ITEMJOURNAL_ID' in jcols:
        order_bits.append('ITEMJOURNAL_ID ASC')
    if 'LINENO' in jcols:
        order_bits.append('LINENO ASC')
    order_sql = (' ORDER BY ' + ', '.join(order_bits)) if order_bits else ''
    sql = f"SELECT {', '.join(sel_cols)} FROM {tbl_u} WHERE {' AND '.join(parts)}{order_sql}"
    try:
        cur.execute(sql, params)
        if not cur.description:
            return []
        names = [str(d[0] or '').upper() for d in cur.description]
        all_rows: List[Dict[str, Any]] = []
        for raw in cur.fetchall() or []:
            all_rows.append({names[i]: raw[i] for i in range(len(names))})
    except Exception:
        return []

    if not open_only or not tt_c:
        return [r for r in all_rows if not (tt_c and _is_itemjournal_reversal_transtype(r.get(tt_c)))]

    # FIFO-match each REVERSAL to an earlier non-reversal with opposite qty fingerprint.
    from collections import defaultdict, deque
    unused_rev: Dict[Tuple[str, str, float, str, str], deque] = defaultdict(deque)
    for row in all_rows:
        if _is_itemjournal_reversal_transtype(row.get(tt_c)):
            unused_rev[_journal_row_fingerprint(row, negate_qty=True)].append(row)

    open_rows: List[Dict[str, Any]] = []
    for row in all_rows:
        if _is_itemjournal_reversal_transtype(row.get(tt_c)):
            continue
        fp = _journal_row_fingerprint(row, negate_qty=False)
        bucket = unused_rev.get(fp)
        if bucket:
            bucket.popleft()
            if not bucket:
                unused_rev.pop(fp, None)
            continue
        open_rows.append(row)
    return open_rows


def _journal_row_to_reversal(row: Dict[str, Any], jcols: Set[str]) -> Dict[str, Any]:
    row = _journal_fill_amount_fields(row)
    rev: Dict[str, Any] = {}
    for col in jcols:
        if col in ('ITEMJOURNAL_ID', 'CREATEDDATE'):
            continue
        val = row.get(col)
        if val is None:
            continue
        if col in ('QTY', 'TOTALINVENTORY', 'AMOUNT', 'VATAMOUNT', 'TOTALAMOUNT'):
            rev[col] = round(_journal_negate_numeric(val), 3)
        else:
            rev[col] = val
    rev['TRANSTYPE'] = ITEMJOURNAL_TRANSTYPE_REVERSAL
    if 'SOURCE_DOC' in jcols and 'SOURCE_DOC' not in rev:
        rev['SOURCE_DOC'] = row.get('SOURCE_DOC')
    if 'SOURCE_NO' in jcols and 'SOURCE_NO' not in rev:
        rev['SOURCE_NO'] = row.get('SOURCE_NO')
    return rev


def reverse_itemjournal_document(
    cur: Any,
    conn: Any,
    location_code: int,
    reset_no: int,
    source_doc: str,
    source_no: str,
    *,
    receipt_no: Optional[int]=None,
) -> int:
    """
    Standard ERP correction: insert reversal rows (negated qty/amounts), never UPDATE posted lines.
    Only open (not-yet-reversed) lines are reversed — safe for repeated document re-edits.
    Returns count of reversal rows inserted.
    """
    tbl_u = _resolve_itemjournal_post_table(cur, conn)
    if not tbl_u:
        return 0
    ensure_itemjournal_surrogate_pk(conn)
    jcols = _journal_cols_upper(cur, tbl_u)
    posted = _journal_rows_for_document(
        cur, tbl_u, jcols, location_code, reset_no, source_doc, source_no,
        receipt_no=receipt_no, open_only=True,
    )
    n = 0
    expected = len(posted)
    for row in posted:
        rev = _journal_row_to_reversal(row, jcols)
        if _journal_insert_from_map(cur, tbl_u, jcols, rev, dry_run=False):
            n += 1
    _require_itemjournal_lines_inserted(
        expected, n, source_doc=source_doc, source_no=source_no, tbl_u=tbl_u,
    )
    return n


def post_itemjournal_lines(
    cur: Any,
    conn: Any,
    location_code: int,
    reset_no: int,
    receipt_no: int,
    source_doc: str,
    transtype: str,
    source_no: str,
    lines: List[Dict[str, Any]],
) -> int:
    """Insert new journal lines only (unique ITEMJOURNAL_ID per row)."""
    tbl_u = _resolve_itemjournal_post_table(cur, conn)
    if not tbl_u:
        if lines:
            print(
                f'[WARN post_itemjournal_lines] ITEMJOURNAL table not found; skipped {len(lines)} '
                f'line(s) for {source_doc} {source_no}',
                flush=True,
            )
        return 0
    if not lines:
        return 0
    ensure_itemjournal_surrogate_pk(conn)
    jcols = _journal_cols_upper(cur, tbl_u)
    item_avg_cache: Dict[int, float] = {}
    wh_col = itemjournal_warehouse_code_column(tbl_u)
    prepared: List[Dict[str, Any]] = []
    for ln in lines:
        row_map = {
            'LOCATIONCODE': int(location_code),
            'RESETNO': int(reset_no),
            'RECEIPTNO': int(receipt_no),
            'LINENO': int(ln.get('lineno') or ln.get('LINENO') or 0),
            'ITEMCODE': ln.get('itemcode') or ln.get('ITEMCODE') or ln.get('item'),
            'UOM': ln.get('uom') or ln.get('UOM'),
            'QTY': ln.get('qty') if 'qty' in ln else ln.get('QTY'),
            'RATE': ln.get('rate') if 'rate' in ln else ln.get('RATE'),
            'AMOUNT': ln.get('amount') if 'amount' in ln else ln.get('AMOUNT'),
            'VATPERCENT': ln.get('vat_percent') if 'vat_percent' in ln else ln.get('VATPERCENT'),
            'VATAMOUNT': ln.get('vat_amount') if 'vat_amount' in ln else ln.get('VATAMOUNT'),
            'TOTALAMOUNT': ln.get('total_amount') if 'total_amount' in ln else ln.get('TOTALAMOUNT'),
            'TOTALINVENTORY': ln.get('totalinventory') if 'totalinventory' in ln else ln.get('TOTALINVENTORY', ln.get('qty', ln.get('QTY'))),
            'TRANSTYPE': str(transtype or '')[:20],
            'SOURCE_DOC': str(source_doc or '')[:30],
            'SOURCE_NO': str(source_no or '')[:50],
        }
        avg_cost = _journal_average_cost_for_line(cur, location_code, ln, item_cache=item_avg_cache)
        if avg_cost > 0 and 'AVERAGECOST' in jcols:
            row_map['AVERAGECOST'] = avg_cost
        for opt_key, col_candidates in (
            ('warehouse_code', ['WAREHOUSE_CODE', 'INVENTORYLOCATION']),
            ('warehouse_id', ['WAREHOUSE_ID']),
            ('storage_id', ['STORAGE_ID']),
            ('batch_no', ['BATCH_NO']),
            ('mfg_date', ['MFG_DATE']),
            ('expiry_date', ['EXPIRY_DATE']),
            ('lot_id', ['LOT_ID']),
            ('suppliercode', ['SUPPLIERCODE']),
            ('suppliername', ['SUPPLIERNAME']),
            ('averagecost', ['AVERAGECOST']),
        ):
            val = ln.get(opt_key)
            if val is None:
                continue
            for col in col_candidates:
                if col in jcols:
                    row_map[col] = val
                    break
        if wh_col and wh_col.upper() in jcols and wh_col.upper() not in row_map:
            wc = ln.get('warehouse_code') or ln.get('store')
            if wc:
                row_map[wh_col.upper()] = str(wc)[:30]
        prepared.append(row_map)
    n = _journal_insert_prepared_rows(cur, tbl_u, jcols, prepared)
    _require_itemjournal_lines_inserted(
        len(prepared), n, source_doc=source_doc, source_no=source_no, tbl_u=tbl_u,
    )
    return n


def delete_itemjournal_for_document_cur(
    cur: Any,
    tbl_u: str,
    location_code: int,
    reset_no: int,
    *,
    receipt_no: Optional[int]=None,
    source_doc: Optional[str]=None,
    source_no: Optional[str]=None,
) -> int:
    """Remove journal rows for one document (scoped by SOURCE_DOC when present — never all RECEIPTNO rows)."""
    jcols = _journal_cols_upper(cur, tbl_u)
    loc_c = 'LOCATIONCODE' if 'LOCATIONCODE' in jcols else None
    rn_c = 'RESETNO' if 'RESETNO' in jcols else None
    rno_c = 'RECEIPTNO' if 'RECEIPTNO' in jcols else None
    sd_c = 'SOURCE_DOC' if 'SOURCE_DOC' in jcols else None
    sn_c = 'SOURCE_NO' if 'SOURCE_NO' in jcols else None
    if not loc_c or not rn_c:
        return 0
    parts = [f'{loc_c} = :loc', f'{rn_c} = :rn']
    params: Dict[str, Any] = {'loc': int(location_code), 'rn': int(reset_no)}
    has_scope = False
    if source_doc and sd_c:
        parts.append(f'{sd_c} = :sd')
        params['sd'] = str(source_doc or '')[:30]
        has_scope = True
    if source_no is not None and sn_c:
        parts.append(f"NVL(TO_CHAR({sn_c}), '@') = NVL(:sn, '@')")
        params['sn'] = str(source_no or '')[:50]
        has_scope = True
    if receipt_no is not None and rno_c:
        parts.append(f'{rno_c} = :rno')
        params['rno'] = int(receipt_no)
        has_scope = True
    if not has_scope:
        return 0
    try:
        cur.execute(f'DELETE FROM {tbl_u} WHERE {" AND ".join(parts)}', params)
        return int(cur.rowcount or 0)
    except Exception:
        return 0


def ensure_itemjournal_hdr_table() -> bool:
    """Create Nova-owned ITEMJOURNAL_HDR (one row per posted source document)."""
    global _ITEMJOURNAL_HDR_ENSURED
    if _ITEMJOURNAL_HDR_ENSURED:
        return _table_exists(ITEMJOURNAL_HDR_TABLE)
    _ITEMJOURNAL_HDR_ENSURED = True
    if _table_exists(ITEMJOURNAL_HDR_TABLE):
        return True
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    CREATE TABLE {ITEMJOURNAL_HDR_TABLE} (
                        JOURNAL_HDR_ID   NUMBER(18) NOT NULL,
                        LOCATIONCODE     NUMBER(10) NOT NULL,
                        RESETNO          NUMBER(10) DEFAULT 1 NOT NULL,
                        RECEIPTNO        NUMBER(18) NOT NULL,
                        SOURCE_DOC       VARCHAR2(30) NOT NULL,
                        SOURCE_NO        VARCHAR2(50),
                        TRANSTYPE        VARCHAR2(20),
                        LINE_COUNT       NUMBER(10) DEFAULT 0 NOT NULL,
                        CREATED_BY       VARCHAR2(100),
                        POSTED_DATE      DATE DEFAULT SYSDATE NOT NULL,
                        MODIFIED_DATE    DATE DEFAULT SYSDATE NOT NULL,
                        CONSTRAINT PK_ITEMJOURNAL_HDR PRIMARY KEY (JOURNAL_HDR_ID),
                        CONSTRAINT UQ_ITEMJOURNAL_HDR_DOC UNIQUE (LOCATIONCODE, RESETNO, SOURCE_DOC, SOURCE_NO)
                    )
                    """
                )
                cur.execute(
                    f'CREATE SEQUENCE {ITEMJOURNAL_HDR_SEQ} START WITH 1 INCREMENT BY 1 NOCACHE'
                )
            conn.commit()
        _TABLE_EXISTS_CACHE[ITEMJOURNAL_HDR_TABLE] = True
        return True
    except Exception as e:
        err = str(e).upper()
        if 'ORA-00955' in err or 'ORA-01408' in err or 'ORA-02260' in err:
            _TABLE_EXISTS_CACHE[ITEMJOURNAL_HDR_TABLE] = True
            return True
        print(f'[WARN ensure_itemjournal_hdr_table] {e}')
        return _table_exists(ITEMJOURNAL_HDR_TABLE)


def delete_itemjournal_hdr_for_document_cur(
    cur: Any,
    location_code: int,
    reset_no: int,
    source_doc: str,
    source_no: str,
) -> int:
    """Remove header row when journal lines for a document are cleared."""
    if not _table_exists(ITEMJOURNAL_HDR_TABLE):
        return 0
    sd = str(source_doc or '').strip()[:30]
    if not sd:
        return 0
    sn = str(source_no or '').strip()[:50] or None
    try:
        cur.execute(
            f"""
            DELETE FROM {ITEMJOURNAL_HDR_TABLE}
            WHERE LOCATIONCODE = :loc AND RESETNO = :rn
              AND SOURCE_DOC = :sd
              AND NVL(SOURCE_NO, '@') = NVL(:sn, '@')
            """,
            {'loc': int(location_code), 'rn': int(reset_no), 'sd': sd, 'sn': sn},
        )
        return int(cur.rowcount or 0)
    except Exception:
        return 0


def upsert_itemjournal_hdr_cur(
    cur: Any,
    location_code: int,
    reset_no: int,
    receipt_no: int,
    source_doc: str,
    source_no: str,
    transtype: str,
    line_count: int,
    *,
    created_by: Optional[str] = None,
) -> None:
    """Insert or update one ITEMJOURNAL_HDR row for a posted document."""
    if not ensure_itemjournal_hdr_table():
        return
    sd = str(source_doc or '').strip()[:30]
    if not sd:
        return
    sn = str(source_no or '').strip()[:50] or None
    tt = str(transtype or '').strip()[:20] or None
    usr = str(created_by or '').strip()[:100] or None
    lookup_params: Dict[str, Any] = {
        'loc': int(location_code),
        'rn': int(reset_no),
        'sd': sd,
        'sn': sn,
    }
    save_params: Dict[str, Any] = {
        **lookup_params,
        'rno': int(receipt_no),
        'tt': tt,
        'lc': max(0, int(line_count or 0)),
        'usr': usr,
    }
    cur.execute(
        f"""
        SELECT JOURNAL_HDR_ID FROM {ITEMJOURNAL_HDR_TABLE}
        WHERE LOCATIONCODE = :loc AND RESETNO = :rn
          AND SOURCE_DOC = :sd
          AND NVL(SOURCE_NO, '@') = NVL(:sn, '@')
        FOR UPDATE
        """,
        lookup_params,
    )
    row = cur.fetchone()
    if row and row[0] is not None:
        cur.execute(
            f"""
            UPDATE {ITEMJOURNAL_HDR_TABLE}
            SET RECEIPTNO = :rno, TRANSTYPE = :tt, LINE_COUNT = :lc,
                MODIFIED_DATE = SYSDATE,
                CREATED_BY = NVL(:usr, CREATED_BY)
            WHERE JOURNAL_HDR_ID = :id
            """,
            {
                'rno': int(receipt_no),
                'tt': tt,
                'lc': max(0, int(line_count or 0)),
                'usr': usr,
                'id': int(row[0]),
            },
        )
        return
    cur.execute(f'SELECT {ITEMJOURNAL_HDR_SEQ}.NEXTVAL FROM DUAL')
    nid_row = cur.fetchone()
    if not nid_row or nid_row[0] is None:
        return
    cur.execute(
        f"""
        INSERT INTO {ITEMJOURNAL_HDR_TABLE}
            (JOURNAL_HDR_ID, LOCATIONCODE, RESETNO, RECEIPTNO, SOURCE_DOC, SOURCE_NO,
             TRANSTYPE, LINE_COUNT, CREATED_BY, POSTED_DATE, MODIFIED_DATE)
        VALUES (:id, :loc, :rn, :rno, :sd, :sn, :tt, :lc, :usr, SYSDATE, SYSDATE)
        """,
        {**save_params, 'id': int(nid_row[0])},
    )


def _itemjournal_uses_surrogate_pk(conn: Any, tbl_u: str) -> bool:
    """True when PK is ITEMJOURNAL_ID only (reversal rows may share RECEIPTNO/LINENO)."""
    try:
        ensure_itemjournal_surrogate_pk(conn)
    except Exception:
        pass
    return _itemjournal_pk_columns(conn, tbl_u) == ['ITEMJOURNAL_ID']


def repost_itemjournal_standard(
    cur: Any,
    conn: Any,
    location_code: int,
    reset_no: int,
    receipt_no: int,
    source_doc: str,
    transtype: str,
    source_no: str,
    lines: List[Dict[str, Any]],
    *,
    match_receipt_no: bool=True,
    journal_receipt_no: Optional[int]=None,
) -> Tuple[int, int]:
    """
    Standard ERP post: reverse/delete existing lines for this document (SOURCE_DOC + SOURCE_NO),
    then insert new lines. On legacy composite PK each SOURCE_DOC uses its own RECEIPTNO namespace
    so GRN #1, bill #1, POS #1, etc. never collide.
    Returns (reversal_count, insert_count).
    """
    tbl_u = _resolve_itemjournal_post_table(cur, conn)
    if not tbl_u:
        if lines:
            raise ValueError('ITEMJOURNAL / ITEMJOURNEL table not found; cannot post stock journal.')
        return (0, 0)
    ensure_itemjournal_surrogate_pk(conn)
    needs_ns = _itemjournal_needs_receiptno_namespace(conn, tbl_u)
    try:
        _ensure_itemjournal_trace_columns_for_table(cur, tbl_u)
    except Exception:
        pass
    sd = str(source_doc or '').strip()
    sn = str(source_no or '').strip()
    j_rno = int(
        journal_receipt_no
        if journal_receipt_no is not None
        else _itemjournal_journal_receiptno(conn, tbl_u, sd, sn, int(receipt_no))
    )
    # Never DROP INDEX here — that DDL was hanging sales/POS saves mid-transaction.
    _ = match_receipt_no  # document identity is SOURCE_DOC + SOURCE_NO

    def _clear_existing_journal() -> int:
        cleared = delete_itemjournal_for_document_cur(
            cur, tbl_u, location_code, reset_no,
            source_doc=sd,
            source_no=sn,
        )
        cleared += _delete_legacy_orphan_itemjournal_cur(
            cur, tbl_u, location_code, reset_no, j_rno, sd, transtype,
        )
        if str(sd or '').strip().upper() in (ITEMJOURNAL_SOURCE_PURCHASE_RETURN, 'RETURN'):
            cleared += _delete_itemjournal_purchase_return_by_receiptno_cur(
                cur, tbl_u, location_code, reset_no, int(receipt_no), j_rno,
            )
        delete_itemjournal_hdr_for_document_cur(cur, location_code, reset_no, sd, sn)
        return cleared

    if not lines:
        return (_clear_existing_journal(), 0)

    if _itemjournal_uses_surrogate_pk(conn, tbl_u) and not needs_ns:
        rev_n = reverse_itemjournal_document(
            cur, conn, location_code, reset_no, sd, sn,
            receipt_no=None,
        )
    else:
        rev_n = _clear_existing_journal()
    ins_n = post_itemjournal_lines(
        cur, conn, location_code, reset_no, j_rno, sd, transtype, sn, lines,
    )
    if ins_n > 0:
        upsert_itemjournal_hdr_cur(
            cur, location_code, reset_no, j_rno, sd, sn, transtype, ins_n,
        )
    else:
        delete_itemjournal_hdr_for_document_cur(cur, location_code, reset_no, sd, sn)
    return (rev_n, ins_n)


def repost_itemjournal_grn(
    cur: Any,
    conn: Any,
    location_code: int,
    reset_no: int,
    receipt_no: int,
    stock_rows: List[Dict[str, Any]],
    *,
    supplier_code: Any=None,
    supplier_name: str='',
) -> Tuple[int, int]:
    """GRN stock post → standard item journal (SOURCE_DOC=GRN, TRANSTYPE=PURCHASE)."""
    lines: List[Dict[str, Any]] = []
    for row in stock_rows or []:
        qty = float(row.get('stock_qty_base') or row.get('qty') or 0)
        lines.append({
            'lineno': row.get('lineno'),
            'item': row.get('item'),
            'uom': row.get('uom'),
            'qty': qty,
            'totalinventory': qty,
            'rate': row.get('rate'),
            'amount': row.get('amount'),
            'vat_percent': row.get('vat_percent'),
            'vat_amount': row.get('vat_amount'),
            'total_amount': row.get('total_amount'),
            'warehouse_code': row.get('warehouse_code'),
            'warehouse_id': row.get('warehouse_id'),
            'storage_id': row.get('storage_id'),
            'batch_no': row.get('batch_no'),
            'mfg_date': row.get('mfg_date'),
            'expiry_date': row.get('expiry_date'),
            'lot_id': row.get('lot_id'),
            'suppliercode': supplier_code,
            'suppliername': supplier_name,
        })
    rno_int = billno_numeric_part(receipt_no)
    if rno_int <= 0:
        try:
            rno_int = int(receipt_no or 0)
        except (TypeError, ValueError):
            rno_int = 0
    return repost_itemjournal_standard(
        cur, conn, location_code, reset_no, rno_int,
        ITEMJOURNAL_SOURCE_GRN, 'PURCHASE', str(receipt_no), lines,
    )


def _journal_warehouse_fields_from_line(line: Dict[str, Any]) -> Dict[str, Any]:
    """Resolve warehouse_code, warehouse_id, storage_id, lot_id for ITEMJOURNAL posting (GRN / purchase return)."""
    out: Dict[str, Any] = {}
    wh_id_int: Optional[int] = None
    wh_id_raw = line.get('warehouse_id')
    if wh_id_raw not in (None, ''):
        try:
            wh_id_int = int(float(wh_id_raw))
            if wh_id_int <= 0:
                wh_id_int = None
        except (TypeError, ValueError):
            wh_id_int = None
    wh_code = str(
        line.get('warehouse_code') or line.get('store') or line.get('location')
        or line.get('inventorylocation') or line.get('inventory_location') or ''
    ).strip()[:30]
    if not wh_code and wh_id_int:
        try:
            wh_row = get_warehouse_master_by_id(wh_id_int)
            if wh_row:
                wh_code = str(wh_row.get('warehouse_code') or '').strip()[:30]
        except Exception:
            pass
    if wh_code:
        out['warehouse_code'] = wh_code
    if not wh_id_int and wh_code:
        try:
            wh_row = get_warehouse_master_by_code(wh_code)
            if wh_row:
                wid_raw = wh_row.get('warehouse_id') or wh_row.get('WAREHOUSE_ID')
                if wid_raw not in (None, ''):
                    wh_id_int = int(float(wid_raw))
                    if wh_id_int <= 0:
                        wh_id_int = None
        except Exception:
            wh_id_int = None
    if wh_id_int:
        out['warehouse_id'] = wh_id_int
    sid_raw = line.get('storage_id')
    if sid_raw not in (None, ''):
        try:
            sid = int(float(sid_raw))
            if sid > 0:
                out['storage_id'] = sid
        except (TypeError, ValueError):
            pass
    lot_raw = line.get('lot_id') or line.get('lotid')
    if lot_raw not in (None, ''):
        try:
            lot_id = int(float(lot_raw))
            if lot_id > 0:
                out['lot_id'] = lot_id
        except (TypeError, ValueError):
            pass
    return out


def _purchase_return_journal_rate_amount(line: Dict[str, Any]) -> Tuple[float, float]:
    """Resolve document rate and negative line amount for purchase-return ITEMJOURNAL."""
    qty = abs(float(line.get('quantity') or line.get('qty') or 0))
    if qty < 1e-12:
        return 0.0, 0.0
    line_disc = float(line.get('discount') or 0)
    rate = float(line.get('rate') or 0)
    if rate <= 0:
        rate = float(line.get('averagecost') or line.get('average_cost') or line.get('costprice') or 0)
    raw_amt = line.get('amount')
    if raw_amt is not None and str(raw_amt).strip() != '':
        line_amt = max(0.0, abs(float(raw_amt)))
    else:
        line_amt = max(0.0, qty * rate - line_disc)
    if rate <= 0 and line_amt > 0:
        rate = (line_amt + line_disc) / qty
    return rate, -line_amt


def repost_itemjournal_purchase_return(
    cur: Any,
    conn: Any,
    location_code: int,
    reset_no: int,
    goods_return_no: Any,
    pr_lines: List[Dict[str, Any]],
) -> Tuple[int, int]:
    """Purchase return inventory journal (negative qty = stock out)."""
    lines: List[Dict[str, Any]] = []
    line_no = 1
    for line in pr_lines or []:
        item = line.get('itemcode') or line.get('item_code') or line.get('item')
        if not item:
            continue
        qty = float(line.get('quantity') or line.get('qty') or 0)
        if abs(qty) < 1e-12:
            continue
        rate, amt_out = _purchase_return_journal_rate_amount(line)
        uom = str(line.get('uom') or 'NOS')[:20]
        line_conv = float(line.get('conversionfactor') or line.get('uomfactor') or 0)
        factor_for_base = line_conv if line_conv > 0 else _get_uom_factor_for_item(item, uom)
        if factor_for_base <= 0:
            factor_for_base = 1.0
        qty_out_base = -abs(abs(qty) * factor_for_base)
        # AVERAGECOST on journal must be base-UOM unit cost (qty column is already base).
        try:
            avg_raw = float(line.get('averagecost') or line.get('average_cost') or 0)
        except (TypeError, ValueError):
            avg_raw = 0.0
        if avg_raw <= 0:
            avg_raw = rate
        if factor_for_base > 1.0 + 1e-9 and rate > 0 and abs(avg_raw - rate) <= max(0.01, abs(rate) * 0.001):
            avg_raw = rate / factor_for_base
        ij_row: Dict[str, Any] = {
            'lineno': line_no,
            'item': item,
            'uom': uom,
            'qty': qty_out_base,
            'totalinventory': qty_out_base,
            'rate': rate,
            'amount': amt_out,
            'vat_percent': 0.0,
            'vat_amount': 0.0,
            'total_amount': amt_out,
            'averagecost': round(float(avg_raw or 0), 4),
            'conversionfactor': factor_for_base,
            'quantity': qty,
        }
        ij_row.update(_journal_warehouse_fields_from_line(line))
        lines.append(ij_row)
        line_no += 1
    return repost_itemjournal_standard(
        cur, conn, location_code, reset_no, billno_journal_receipt_no(goods_return_no),
        ITEMJOURNAL_SOURCE_PURCHASE_RETURN, 'PURCHASE_RETURN', str(goods_return_no), lines,
    )


def repost_itemjournal_stock_count(
    cur: Any,
    conn: Any,
    location_code: int,
    reset_no: int,
    count_no: int,
    journal_lines: List[Dict[str, Any]],
) -> Tuple[int, int]:
    """Stock count post → item journal (SOURCE_DOC=STOCK_COUNT, qty = variance in base UOM)."""
    lines: List[Dict[str, Any]] = []
    for row in journal_lines or []:
        try:
            var_q = float(row.get('variance') or row.get('qty') or 0)
        except (TypeError, ValueError):
            var_q = 0.0
        if abs(var_q) < 1e-09:
            continue
        try:
            lineno = int(row.get('lineno') or row.get('line_no') or 0)
        except (TypeError, ValueError):
            lineno = 0
        item = row.get('itemcode') or row.get('item_code') or row.get('item')
        uom = str(row.get('uom') or 'NOS')[:20]
        avg_cost = _journal_average_cost_for_line(cur, int(location_code), row)
        amount = round(var_q * avg_cost, 3) if avg_cost > 0 else 0.0
        ij_row: Dict[str, Any] = {
            'lineno': lineno,
            'item': item,
            'uom': uom,
            'qty': var_q,
            'totalinventory': var_q,
            'rate': avg_cost,
            'amount': amount,
        }
        ij_row.update(_journal_warehouse_fields_from_line(row))
        lines.append(ij_row)
    return repost_itemjournal_standard(
        cur, conn, location_code, reset_no, int(count_no),
        ITEMJOURNAL_SOURCE_STOCK_COUNT, 'STOCK_COUNT', str(count_no), lines,
    )


def repost_itemjournal_stock_adjustment(
    cur: Any,
    conn: Any,
    location_code: int,
    reset_no: int,
    adj_no: int,
    journal_lines: List[Dict[str, Any]],
    *,
    opening_stock: bool = False,
) -> Tuple[int, int]:
    """Stock adjustment post → item journal (SOURCE_DOC=STKADJ, qty = signed base adjust qty).

    When ``opening_stock`` is set the row is tagged TRANSTYPE=OPENING_STOCK so the Item
    Journal distinguishes opening-balance imports from ordinary stock adjustments. The
    SOURCE_DOC stays STKADJ so document identity / repost / verification logic is unchanged.
    """
    lines: List[Dict[str, Any]] = []
    item_cost_cache: Dict[int, float] = {}
    item_codes: List[int] = []
    for row in journal_lines or []:
        item = row.get('itemcode') or row.get('item_code') or row.get('item')
        try:
            ic = int(float(item))
        except (TypeError, ValueError):
            ic = 0
        if ic > 0:
            item_codes.append(ic)
    cost_map = _batch_itemmaster_journal_cost_map(cur, int(location_code), item_codes)
    vat_map = _batch_vat_percent_for_items(cur, int(location_code), item_codes)
    for row in journal_lines or []:
        try:
            qty = float(row.get('base_qty') if row.get('base_qty') is not None else row.get('adjust_qty') or row.get('qty') or 0)
        except (TypeError, ValueError):
            qty = 0.0
        if abs(qty) < 1e-09:
            continue
        try:
            lineno = int(row.get('lineno') or row.get('line_no') or row.get('slno') or 0)
        except (TypeError, ValueError):
            lineno = 0
        item = row.get('itemcode') or row.get('item_code') or row.get('item')
        uom = str(row.get('uom') or 'NOS')[:20]
        journal_row = dict(row)
        journal_row.setdefault('itemcode', item)
        avg_cost = _journal_average_cost_for_line(
            cur, int(location_code), journal_row, item_cache=item_cost_cache,
        )
        if avg_cost <= 0:
            try:
                ic = int(float(item))
                avg_cost = float(cost_map.get(ic) or 0)
            except (TypeError, ValueError):
                avg_cost = 0.0
        amount = round(qty * avg_cost, 3) if avg_cost > 0 else 0.0
        ij_row: Dict[str, Any] = {
            'lineno': lineno,
            'item': item,
            'uom': uom,
            'qty': qty,
            'totalinventory': qty,
            'rate': avg_cost,
            'amount': amount,
        }
        if avg_cost > 0:
            ij_row['averagecost'] = avg_cost
        try:
            ic_vat = int(float(item))
        except (TypeError, ValueError):
            ic_vat = 0
        if ic_vat > 0:
            vat_pct = float(vat_map.get(ic_vat, 0) or 0)
            vat_amt = round(amount * vat_pct / 100.0, 3)
            total_amt = round(amount + vat_amt, 3)
            ij_row.update({
                'vat_percent': vat_pct,
                'vat_amount': vat_amt,
                'total_amount': total_amt,
            })
        else:
            ij_row.update({'vat_percent': 0.0, 'vat_amount': 0.0, 'total_amount': amount})
        ij_row.update(_journal_warehouse_fields_from_line(row))
        lines.append(ij_row)
    transtype = 'OPENING_STOCK' if opening_stock else 'STOCK_ADJ'
    return repost_itemjournal_standard(
        cur, conn, location_code, reset_no, int(adj_no),
        ITEMJOURNAL_SOURCE_STOCK_ADJ, transtype, str(adj_no), lines,
    )


def repost_itemjournal_repacking(
    cur: Any,
    conn: Any,
    location_code: int,
    reset_no: int,
    repack_no: int,
    journal_lines: List[Dict[str, Any]],
) -> Tuple[int, int]:
    """Repacking post → item journal (SOURCE_DOC=REPACK, signed base qty per line)."""
    lines: List[Dict[str, Any]] = []
    item_cost_cache: Dict[int, float] = {}
    for row in journal_lines or []:
        try:
            qty = float(row.get('base_qty') if row.get('base_qty') is not None else row.get('adjust_qty') or row.get('qty') or 0)
        except (TypeError, ValueError):
            qty = 0.0
        if abs(qty) < 1e-09:
            continue
        try:
            lineno = int(row.get('lineno') or row.get('line_no') or row.get('slno') or 0)
        except (TypeError, ValueError):
            lineno = 0
        item = row.get('itemcode') or row.get('item_code') or row.get('item')
        uom = str(row.get('uom') or 'NOS')[:20]
        journal_row = dict(row)
        journal_row.setdefault('itemcode', item)
        avg_cost = _journal_average_cost_for_line(
            cur, int(location_code), journal_row, item_cache=item_cost_cache,
        )
        amount = round(qty * avg_cost, 3) if avg_cost > 0 else 0.0
        ij_row: Dict[str, Any] = {
            'lineno': lineno,
            'item': item,
            'uom': uom,
            'qty': qty,
            'totalinventory': qty,
            'rate': avg_cost,
            'amount': amount,
        }
        if avg_cost > 0:
            ij_row['averagecost'] = avg_cost
        try:
            ic_vat = int(float(item))
        except (TypeError, ValueError):
            ic_vat = 0
        if ic_vat > 0:
            ij_row.update(_journal_vat_amount_fields(cur, int(location_code), ic_vat, amount))
        else:
            ij_row.update({'vat_percent': 0.0, 'vat_amount': 0.0, 'total_amount': amount})
        ij_row.update(_journal_warehouse_fields_from_line(row))
        if row.get('from_storage_id') is not None:
            ij_row['storage_id'] = row.get('from_storage_id')
        elif row.get('to_storage_id') is not None:
            ij_row['storage_id'] = row.get('to_storage_id')
        if row.get('lot_id') is not None:
            ij_row['lot_id'] = row.get('lot_id')
        lines.append(ij_row)
    return repost_itemjournal_standard(
        cur, conn, location_code, reset_no, int(repack_no),
        ITEMJOURNAL_SOURCE_REPACK, 'REPACK', str(repack_no), lines,
    )


def _vat_percent_for_item(cur: Any, loc: int, item_code: int) -> float:
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return 0.0
    im_code = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    im_loc = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    im_vat = _detect_column(im, ['VATPERCENT', 'VAT_PERCENT', 'vatpercent'])
    if not im_code or not im_vat:
        return 0.0
    wh = [f'{im_code} = :ic']
    prm: Dict[str, Any] = {'ic': item_code}
    if im_loc:
        wh.append(f'{im_loc} = :lc')
        prm['lc'] = loc
    try:
        cur.execute(f"SELECT NVL({im_vat}, 0) FROM {im} WHERE {' AND '.join(wh)}", prm)
        r = cur.fetchone()
        return float(r[0] or 0) if r else 0.0
    except Exception:
        return 0.0


def _batch_vat_percent_for_items(
    cur: Any,
    location_code: int,
    item_codes: List[int],
) -> Dict[int, float]:
    """Prefetch ITEMMASTER.VATPERCENT for many items (one query per chunk)."""
    out: Dict[int, float] = {}
    uniq = sorted({int(c) for c in item_codes if c and int(c) > 0})
    if not uniq:
        return out
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return out
    im_code = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    im_loc = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    im_vat = _detect_column(im, ['VATPERCENT', 'VAT_PERCENT', 'vatpercent'])
    if not im_code or not im_vat:
        return out
    chunk_size = 400
    for ci in range(0, len(uniq), chunk_size):
        chunk = uniq[ci:ci + chunk_size]
        keys = [f'ic_{ci}_{i}' for i in range(len(chunk))]
        binds = ','.join(f':{k}' for k in keys)
        params: Dict[str, Any] = {k: int(v) for k, v in zip(keys, chunk)}
        where = [f'{im_code} IN ({binds})']
        if im_loc:
            where.append(f'{im_loc} = :lc')
            params['lc'] = int(location_code)
        try:
            cur.execute(
                f'SELECT {im_code} AS itemcode, NVL({im_vat}, 0) AS vatpct '
                f'FROM {im} WHERE {" AND ".join(where)}',
                params,
            )
            for row in cur.fetchall() or []:
                try:
                    out[int(row[0])] = float(row[1] or 0)
                except (TypeError, ValueError):
                    continue
        except Exception:
            pass
    return out


def _batch_itemmaster_journal_cost_map(
    cur: Any,
    location_code: int,
    item_codes: List[int],
) -> Dict[int, float]:
    """Prefetch average/cost price for ITEMJOURNAL posting (one query per chunk)."""
    out: Dict[int, float] = {}
    uniq = sorted({int(c) for c in item_codes if c and int(c) > 0})
    if not uniq:
        return out
    im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
    if not im:
        return out
    im_code = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
    im_loc = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
    im_avg = _detect_column(im, ['AVERAGECOST', 'averagecost'])
    im_cost = _detect_column(im, ['COSTPRICE', 'COST_PRICE', 'costprice'])
    if not im_code:
        return out
    if im_avg and im_cost:
        cost_sel = f'NVL({im_avg}, NVL({im_cost}, 0))'
    elif im_avg:
        cost_sel = f'NVL({im_avg}, 0)'
    elif im_cost:
        cost_sel = f'NVL({im_cost}, 0)'
    else:
        return out
    chunk_size = 400
    for ci in range(0, len(uniq), chunk_size):
        chunk = uniq[ci:ci + chunk_size]
        keys = [f'ic_{ci}_{i}' for i in range(len(chunk))]
        binds = ','.join(f':{k}' for k in keys)
        params: Dict[str, Any] = {k: int(v) for k, v in zip(keys, chunk)}
        where = [f'{im_code} IN ({binds})']
        if im_loc:
            where.append(f'{im_loc} = :lc')
            params['lc'] = int(location_code)
        try:
            cur.execute(
                f'SELECT {im_code} AS itemcode, {cost_sel} AS cost '
                f'FROM {im} WHERE {" AND ".join(where)}',
                params,
            )
            for row in cur.fetchall() or []:
                try:
                    out[int(row[0])] = round(float(row[1] or 0), 4)
                except (TypeError, ValueError):
                    continue
        except Exception:
            pass
    return out


def _journal_vat_amount_fields(
    cur: Any,
    location_code: int,
    item_code: Any,
    amount: float,
) -> Dict[str, float]:
    """VATPERCENT / VATAMOUNT / TOTALAMOUNT for ITEMJOURNAL (same formula as GRN posting)."""
    try:
        amt = float(amount or 0)
    except (TypeError, ValueError):
        amt = 0.0
    try:
        ic = int(float(item_code))
    except (TypeError, ValueError):
        ic = 0
    vat_pct = _vat_percent_for_item(cur, int(location_code), ic) if ic > 0 else 0.0
    vat_amt = round(amt * vat_pct / 100.0, 3)
    total_amt = round(amt + vat_amt, 3)
    return {
        'vat_percent': vat_pct,
        'vat_amount': vat_amt,
        'total_amount': total_amt,
    }


def _journal_average_cost_for_line(
    cur: Any,
    location_code: int,
    line: Dict[str, Any],
    *,
    item_cache: Optional[Dict[int, float]] = None,
) -> float:
    """Base-UOM unit cost for ITEMJOURNAL.AVERAGECOST / sales COGS.

    Prefer ITEMMASTER.AVERAGECOST (base). Do not use alt-UOM pack cost with BASEQTY.
    """
    item_raw = (
        line.get('itemcode')
        or line.get('ITEMCODE')
        or line.get('item')
        or line.get('item_code')
    )
    try:
        item_int = int(float(item_raw))
    except (TypeError, ValueError):
        item_int = 0

    cache = item_cache if item_cache is not None else {}
    master = 0.0
    if item_int > 0:
        if item_int in cache:
            master = float(cache[item_int] or 0)
        else:
            im = _detect_table(['ITEMMASTER', 'itemmaster', 'ITEM_MASTER'])
            if im:
                im_code = _detect_column(im, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
                im_loc = _detect_column(im, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
                im_avg = _detect_column(im, ['AVERAGECOST', 'averagecost'])
                im_cost = _detect_column(im, ['COSTPRICE', 'COST_PRICE', 'costprice'])
                if im_code and (im_avg or im_cost):
                    if im_avg and im_cost:
                        cost_sel = f'NVL({im_avg}, NVL({im_cost}, 0))'
                    elif im_avg:
                        cost_sel = f'NVL({im_avg}, 0)'
                    else:
                        cost_sel = f'NVL({im_cost}, 0)'
                    wh = [f'{im_code} = :ic']
                    prm: Dict[str, Any] = {'ic': item_int}
                    if im_loc:
                        wh.append(f'{im_loc} = :lc')
                        prm['lc'] = int(location_code)
                    try:
                        cur.execute(f'SELECT {cost_sel} FROM {im} WHERE {" AND ".join(wh)}', prm)
                        r = cur.fetchone()
                        master = round(float(r[0] or 0), 4) if r else 0.0
                    except Exception:
                        master = 0.0
            cache[item_int] = master
        if master > 0:
            return round(master, 4)

    # No master cost — fall back carefully (unwind pack cost when alt UOM).
    qty = 0.0
    base = 0.0
    try:
        qty = abs(
            float(
                line.get('quantity')
                or line.get('qty')
                or line.get('adjust_qty')
                or line.get('transfer_qty')
                or 0
            )
        )
    except (TypeError, ValueError):
        qty = 0.0
    try:
        base = abs(
            float(
                line.get('base_qty')
                or line.get('baseqty')
                or qty
                or 0
            )
        )
    except (TypeError, ValueError):
        base = qty
    factor = (base / qty) if qty > 1e-12 else 1.0
    cf = 0.0
    try:
        cf = float(
            line.get('conversion_factor')
            or line.get('conversionfactor')
            or line.get('item_factor')
            or line.get('factor')
            or line.get('uomfactor')
            or 0
        )
        if cf > 1e-12:
            factor = cf
    except (TypeError, ValueError):
        cf = 0.0
    if factor <= 0:
        factor = 1.0

    for key in ('averagecost', 'average_cost', 'AVERAGECOST'):
        raw = line.get(key)
        if raw is None or str(raw).strip() == '':
            continue
        try:
            val = float(raw)
        except (TypeError, ValueError):
            continue
        if val <= 0:
            continue
        pack = 0.0
        for ck in ('costprice', 'cost', 'COSTPRICE', 'COST', 'rate', 'RATE'):
            try:
                pack = float(line.get(ck) or 0)
            except (TypeError, ValueError):
                pack = 0.0
            if pack > 0:
                break
        # Pack cost wrongly stored as averagecost while qty is already converted to base.
        if factor > 1.0 + 1e-9 and pack > 0 and abs(val - pack) <= max(0.01, pack * 0.001):
            return round(val / factor, 4)
        if factor > 1.0 + 1e-9 and qty < 1e-12 and base > 1e-12:
            # Only base_qty present: if value looks like pack (no master), prefer /factor when
            # conversionfactor was supplied explicitly.
            if cf > 1.0 + 1e-9:
                return round(val / factor, 4)
        return round(val, 4)

    for key in ('costprice', 'cost', 'COSTPRICE', 'COST'):
        raw = line.get(key)
        if raw is None or str(raw).strip() == '':
            continue
        try:
            val = float(raw)
        except (TypeError, ValueError):
            continue
        if val <= 0:
            continue
        if factor > 1.0 + 1e-9:
            return round(val / factor, 4)
        return round(val, 4)
    return 0.0


def _base_unit_inventory_cost_from_maps(
    ln: Dict[str, Any],
    item_row: Optional[Dict[str, Any]] = None,
) -> float:
    """Per-base-UOM cost for sales inventory/COGS (never alt pack cost × BASEQTY)."""

    def _n(v: Any, default: float = 0.0) -> float:
        try:
            if v is None or v == '':
                return default
            return float(v)
        except (TypeError, ValueError):
            return default

    item_row = item_row or {}
    master_avg = _n(item_row.get('averagecost') or item_row.get('AVERAGECOST'))
    if master_avg > 0:
        return round(master_avg, 6)
    master_cost = _n(item_row.get('costprice') or item_row.get('COSTPRICE'))
    if master_cost > 0:
        return round(master_cost, 6)

    qty = abs(_n(ln.get('quantity')))
    base = abs(_n(ln.get('base_qty') or ln.get('baseqty'), qty))
    factor = (base / qty) if qty > 1e-12 else _n(
        ln.get('conversion_factor')
        or ln.get('conversionfactor')
        or ln.get('item_factor')
        or ln.get('factor'),
        1.0,
    )
    if factor <= 0:
        factor = 1.0

    line_avg = _n(ln.get('averagecost') or ln.get('average_cost'))
    pack = _n(ln.get('costprice') or ln.get('cost'))
    if line_avg > 0:
        if factor > 1.0 + 1e-9 and pack > 0 and abs(line_avg - pack) <= max(0.01, pack * 0.001):
            return round(line_avg / factor, 6)
        return round(line_avg, 6)
    if pack > 0:
        if factor > 1.0 + 1e-9:
            return round(pack / factor, 6)
        return round(pack, 6)
    return 0.0


def backfill_itemjournal_from_documents(conn: Optional[Any]=None, *, location_code: Optional[int]=None, prefer_itemjournel: bool=True, include_grn: bool=True, include_sales: bool=True, include_purchase_return: bool=True, dry_run: bool=False) -> Tuple[bool, str, Dict[str, int]]:
    """
    Insert missing stock journal rows into ITEMJOURNEL (preferred) or ITEMJOURNAL from:
    posted GRNs (TBLGRNPOSTINGHDR + RECEIPTHDR/RECEIPTDTL), BILLHDR/BILLDTL sales, posted purchase
    returns (TBLPRPOSTINGHDR + RETURNHDR/RETURNDTL). Skips rows that already match the same
    LOCATIONCODE, RESETNO, RECEIPTNO, LINENO, SOURCE_DOC, SOURCE_NO.

    Call ``ensure_itemjournal_surrogate_pk`` first (uses same connection). Commit is left to the
    caller when ``conn`` is passed in; when ``conn`` is None, opens a tenant/default connection and
    commits unless ``dry_run``.

    Multi-DB: run inside Flask app context with tenant session set, or pass an explicit ``conn``.
    """
    stats = {'grn': 0, 'sales': 0, 'purchase_return': 0, 'skipped_exists': 0}
    own_conn = conn is None
    if own_conn:
        conn = _get_connection()
    try:
        jtbl = _resolve_itemjournal_backfill_table(prefer_itemjournel=prefer_itemjournel)
        if not jtbl:
            return (False, 'No ITEMJOURNAL / ITEMJOURNEL table found.', stats)
        tbl_u = jtbl.upper()
        try:
            ensure_itemjournal_surrogate_pk(conn)
        except Exception as ex:
            if 'ORA-14411' not in str(ex) and '14411' not in str(ex):
                raise
        with conn.cursor() as cur:
            _ensure_itemjournal_trace_columns_for_table(cur, tbl_u)
            jcols = _journal_cols_upper(cur, tbl_u)
            avg_cache: Dict[int, float] = {}
            if 'LOCATIONCODE' not in jcols or 'RESETNO' not in jcols or 'RECEIPTNO' not in jcols or ('LINENO' not in jcols):
                return (False, f'{tbl_u} is missing required columns (LOCATIONCODE, RESETNO, RECEIPTNO, LINENO).', stats)
            rh = _detect_table(['RECEIPTHDR', 'receipthdr'])
            rd = _detect_table(['RECEIPTDTL', 'receiptdtl'])
            post_grn = _table_exists('TBLGRNPOSTINGHDR')
            if include_grn and rh and rd and post_grn:
                h_loc = _detect_column(rh, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
                h_reset = _detect_column(rh, ['RESETNO', 'RESET_NO', 'resetno'])
                h_no = _detect_column(rh, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
                d_loc = _detect_column(rd, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
                d_reset = _detect_column(rd, ['RESETNO', 'RESET_NO', 'resetno'])
                d_no = _detect_column(rd, ['RECEIPTNO', 'RECEIPT_NO', 'receiptno'])
                d_item = _detect_column(rd, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
                d_qty = _detect_column(rd, ['QUANTITY', 'quantity'])
                d_rcv = _detect_column(rd, ['RECEIVEDQTY', 'RECEIVED_QTY', 'receivedqty'])
                d_rate = _detect_column(rd, ['RATE', 'rate'])
                d_uom = _detect_column(rd, ['UNITOFMEASUREMENT', 'UOM', 'unitofmeasurement', 'uom'])
                d_amt = _detect_column(rd, ['AMOUNT', 'amount'])
                d_disc = _detect_column(rd, ['DISCOUNT', 'discount'])
                d_base = _detect_column(rd, ['BASEQTY', 'BASE_QTY', 'baseqty'])
                d_inv = receiptdtl_warehouse_code_column(rd)
                d_wh = _detect_column(rd, ['WAREHOUSE_ID', 'warehouse_id'])
                d_batch = _detect_column(rd, ['BATCH_NO', 'BATCHNO', 'batch_no', 'BATCH_NUMBER', 'BATCHNUMBER'])
                d_mfg = _detect_column(rd, ['MFG_DATE', 'MFGDATE', 'mfg_date', 'MANUFACTURING_DATE'])
                d_expiry = _detect_column(rd, ['EXPIRY_DATE', 'EXPIRYDATE', 'expiry_date', 'DATEOFEXPIRY', 'DATE_OF_EXPIRY', 'EXPIREDATE'])
                d_sl = _sql_ident_col(_detect_column(rd, ['SLNO', 'slno', 'LINENO', 'lineno']))
                d_loc = _sql_ident_col(d_loc)
                d_reset = _sql_ident_col(d_reset)
                d_no = _sql_ident_col(d_no)
                d_item = _sql_ident_col(d_item)
                d_qty = _sql_ident_col(d_qty)
                d_rcv = _sql_ident_col(d_rcv)
                d_rate = _sql_ident_col(d_rate)
                d_uom = _sql_ident_col(d_uom)
                d_amt = _sql_ident_col(d_amt)
                d_disc = _sql_ident_col(d_disc)
                d_base = _sql_ident_col(d_base)
                d_inv = _sql_ident_col(d_inv)
                d_wh = _sql_ident_col(d_wh)
                d_batch = _sql_ident_col(d_batch)
                d_mfg = _sql_ident_col(d_mfg)
                d_expiry = _sql_ident_col(d_expiry)
                h_loc = _sql_ident_col(h_loc)
                h_reset = _sql_ident_col(h_reset)
                h_no = _sql_ident_col(h_no)
                if h_loc and h_no and d_no and d_item:
                    join_h = f'h.{h_no} = d.{d_no} AND h.{h_loc} = d.{d_loc}'
                    if h_reset and d_reset:
                        join_h += f' AND NVL(h.{h_reset},1) = NVL(d.{d_reset},1)'
                    h_rn_expr = f'NVL(h.{h_reset},1)' if h_reset else '1'
                    p_reset_match = f'p.RESETNO = NVL(h.{h_reset},1)' if h_reset else 'p.RESETNO = 1'
                    sql_rc = f'SELECT DISTINCT h.{h_loc} AS lc, {h_rn_expr} AS rn, h.{h_no} AS rno FROM {rh} h INNER JOIN {rd} d ON {join_h} INNER JOIN TBLGRNPOSTINGHDR p ON p.LOCATIONCODE = h.{h_loc} AND {p_reset_match} AND p.RECEIPTNO = h.{h_no} '
                    prm: Dict[str, Any] = {}
                    if location_code is not None:
                        sql_rc += f' WHERE h.{h_loc} = :lc'
                        prm['lc'] = int(location_code)
                    cur.execute(sql_rc, prm or {})
                    receipts = cur.fetchall() or []
                    for lc, rn, rno in receipts:
                        try:
                            loc_i = int(lc)
                            reset_i = int(rn or 1)
                            rno_i = int(rno)
                        except (TypeError, ValueError):
                            continue
                        ln_sel = f'NVL(d.{d_sl}, ROW_NUMBER() OVER (ORDER BY d.ROWID))' if d_sl else 'ROW_NUMBER() OVER (ORDER BY d.ROWID)'
                        if d_rcv and d_qty:
                            qty_sel = f'NVL(d.{d_rcv}, NVL(d.{d_qty},0))'
                        elif d_rcv:
                            qty_sel = f'NVL(d.{d_rcv}, 0)'
                        elif d_qty:
                            qty_sel = f'NVL(d.{d_qty}, 0)'
                        else:
                            qty_sel = '0'
                        inv_sel = f"NVL(TRIM(d.{d_inv}), '')" if d_inv else "''"
                        amt_sel = f'NVL(d.{d_amt}, 0)' if d_amt else '0'
                        disc_sel = f'NVL(d.{d_disc}, 0)' if d_disc else '0'
                        base_sel = f'NVL(d.{d_base}, 0)' if d_base else '0'
                        uom_sel = f"NVL(d.{d_uom}, 'NOS')" if d_uom else "'NOS'"
                        rate_sel = f'NVL(d.{d_rate},0)' if d_rate else '0'
                        wh_sel = f'd.{d_wh}' if d_wh else 'NULL'
                        bn_sel = f'd.{d_batch}' if d_batch else 'NULL'
                        mfg_sel = f'd.{d_mfg}' if d_mfg else 'NULL'
                        exp_sel = f'd.{d_expiry}' if d_expiry else 'NULL'
                        line_sql = f'SELECT {ln_sel} AS ln, d.{d_item} AS itemcode, {qty_sel} AS qty, {rate_sel} AS rate, {uom_sel} AS uom, {amt_sel} AS amount, {disc_sel} AS discount, {base_sel} AS baseqty, {inv_sel} AS invloc, {wh_sel} AS warehouse_id, {bn_sel} AS batch_no, {mfg_sel} AS mfg_date, {exp_sel} AS expiry_date FROM {rd} d WHERE d.{d_no} = :rno AND d.{d_loc} = :loc ' + (f' AND NVL(d.{d_reset},1) = :rn ' if d_reset else '')
                        lp = {'rno': rno_i, 'loc': loc_i, 'rn': reset_i} if d_reset else {'rno': rno_i, 'loc': loc_i}
                        cur.execute(line_sql, lp)
                        for row in cur.fetchall() or []:
                            if len(row) >= 13:
                                ln, icode, qty, rate, uom, amt, disc, baseqty, invloc, wh_id, batch_no, mfg_date, expiry_date = row
                            elif len(row) >= 10:
                                ln, icode, qty, rate, uom, amt, disc, baseqty, invloc, wh_id = row
                                batch_no, mfg_date, expiry_date = (None, None, None)
                            else:
                                ln, icode, qty, rate, uom, amt, disc, baseqty, invloc = row
                                wh_id, batch_no, mfg_date, expiry_date = (None, None, None, None)
                            try:
                                lineno = int(ln or 0)
                                item_int = int(icode)
                            except (TypeError, ValueError):
                                continue
                            if lineno <= 0:
                                continue
                            if _journal_row_exists_any(cur, conn, loc_i, reset_i, rno_i, lineno, 'GRN', str(rno_i)):
                                stats['skipped_exists'] += 1
                                continue
                            qty_f = abs(float(qty or 0))
                            rate_f = float(rate or 0)
                            disc_f = float(disc or 0)
                            base_f = abs(float(baseqty or 0))
                            if base_f <= 0 and qty_f > 0:
                                base_f = qty_f
                            if d_amt and amt is not None:
                                amt_f = float(amt or 0)
                            else:
                                amt_f = max(0.0, qty_f * rate_f - disc_f)
                            vatp = _vat_percent_for_item(cur, loc_i, item_int)
                            vat_amt = round(amt_f * vatp / 100.0, 3) if vatp else 0.0
                            tot = round(amt_f + vat_amt, 3)
                            wh_val = None
                            if wh_id not in (None, ''):
                                try:
                                    wh_val = int(wh_id)
                                except (TypeError, ValueError):
                                    wh_val = None
                            lot_id_val = item_lot_id_for_batch_at_location_cur(cur, loc_i, item_int, str(batch_no or '').strip() or None)
                            bn_val = str(batch_no or '').strip()[:80] or None
                            wh_code_col = itemjournal_warehouse_code_column(tbl_u)
                            wh_code_key = str(wh_code_col or '').upper() if wh_code_col else None
                            row_map: Dict[str, Any] = {'LOCATIONCODE': loc_i, 'RESETNO': reset_i, 'RECEIPTNO': rno_i, 'LINENO': lineno, 'ITEMCODE': item_int, 'UOM': str(uom or 'NOS')[:20] if 'UOM' in jcols else None, 'QTY': base_f, 'TOTALINVENTORY': base_f if 'TOTALINVENTORY' in jcols else None, 'RATE': rate_f, 'AMOUNT': amt_f, 'VATPERCENT': vatp, 'VATAMOUNT': vat_amt, 'TOTALAMOUNT': tot, 'TRANSTYPE': 'PURCHASE', 'SOURCE_DOC': 'GRN', 'SOURCE_NO': str(rno_i), 'WAREHOUSE_ID': wh_val if 'WAREHOUSE_ID' in jcols else None, 'BATCH_NO': bn_val if 'BATCH_NO' in jcols else None, 'MFG_DATE': mfg_date if 'MFG_DATE' in jcols else None, 'EXPIRY_DATE': expiry_date if 'EXPIRY_DATE' in jcols else None, 'LOT_ID': lot_id_val if 'LOT_ID' in jcols else None}
                            if wh_code_key and wh_code_key in jcols:
                                row_map[wh_code_key] = str(invloc or '')[:30]
                            avg_f = _journal_average_cost_for_line(cur, loc_i, {'item': item_int}, item_cache=avg_cache)
                            if avg_f > 0 and 'AVERAGECOST' in jcols:
                                row_map['AVERAGECOST'] = avg_f
                            row_map = {k: v for k, v in row_map.items() if v is not None}
                            if _journal_insert_from_map(cur, tbl_u, jcols, row_map, dry_run=dry_run):
                                stats['grn'] += 1
            bh = _detect_table(['BILLHDR', 'billhdr'])
            bd = _detect_table(['BILLDTL', 'billdtl'])
            if include_sales and bh and bd:
                b_loc = _detect_column(bh, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
                b_reset = _detect_column(bh, ['RESETNO', 'RESET_NO', 'resetno'])
                b_no = _detect_column(bh, ['BILLNO', 'BILL_NO', 'billno'])
                b_type = _detect_column(bh, ['BILLTYPE', 'BILL_TYPE', 'billtype'])
                b_del = _detect_column(bh, ['DELFLAG', 'DEL_FLAG', 'delflag'])
                d_loc = _detect_column(bd, ['LOCATIONCODE', 'LOCATION_CODE', 'locationcode'])
                d_reset = _detect_column(bd, ['RESETNO', 'RESET_NO', 'resetno'])
                d_no = _detect_column(bd, ['BILLNO', 'BILL_NO', 'billno'])
                d_sl = _detect_column(bd, ['SLNO', 'slno', 'LINENO', 'lineno'])
                d_item = _detect_column(bd, ['ITEMCODE', 'ITEM_CODE', 'itemcode'])
                d_qty = _detect_column(bd, ['QUANTITY', 'quantity'])
                d_rate = _detect_column(bd, ['RATE', 'rate'])
                d_uom = _detect_column(bd, ['UNITOFMEASUREMENT', 'UOM', 'unitofmeasurement', 'uom'])
                d_disc = _detect_column(bd, ['ITDISC', 'itdisc', 'DISCOUNT', 'discount'])
                d_base = _detect_column(bd, ['BASEQTY', 'BASE_QTY', 'baseqty'])
                d_store = _detect_column(bd, ['STORE', 'store'])
                d_vatp = _detect_column(bd, ['VATPERCENT', 'VAT_PERCENT', 'vatpercent'])
                d_vatamt = _detect_column(bd, ['VATAMOUNT', 'VAT_AMOUNT', 'vatamount'])
                b_loc = _sql_ident_col(b_loc)
                b_reset = _sql_ident_col(b_reset)
                b_no = _sql_ident_col(b_no)
                b_type = _sql_ident_col(b_type)
                b_del = _sql_ident_col(b_del)
                d_loc = _sql_ident_col(d_loc)
                d_reset = _sql_ident_col(d_reset)
                d_no = _sql_ident_col(d_no)
                d_sl = _sql_ident_col(d_sl)
                d_item = _sql_ident_col(d_item)
                d_qty = _sql_ident_col(d_qty)
                d_rate = _sql_ident_col(d_rate)
                d_uom = _sql_ident_col(d_uom)
                d_disc = _sql_ident_col(d_disc)
                d_base = _sql_ident_col(d_base)
                d_store = _sql_ident_col(d_store)
                d_vatp = _sql_ident_col(d_vatp)
                d_vatamt = _sql_ident_col(d_vatamt)
                if b_loc and b_no and d_no and d_item:
                    join_b = f'h.{b_no} = d.{d_no} AND h.{b_loc} = d.{d_loc}'
                    if b_reset and d_reset:
                        join_b += f' AND NVL(h.{b_reset},1) = NVL(d.{d_reset},1)'
                    b_rn_expr = f'NVL(h.{b_reset},1)' if b_reset else '1'
                    wh = [f"NVL(h.{b_del}, 'N') <> 'Y'" if b_del else '1=1']
                    if location_code is not None:
                        wh.append(f'h.{b_loc} = :lc')
                    if b_type:
                        sql_b = f"SELECT h.{b_loc} AS lc, {b_rn_expr} AS rn, h.{b_no} AS bno,  CASE WHEN UPPER(NVL(h.{b_type},'C')) LIKE 'R%' THEN 1 ELSE 0 END AS is_ret FROM {bh} h INNER JOIN {bd} d ON {join_b} WHERE {' AND '.join(wh)} GROUP BY h.{b_loc}, {b_rn_expr}, h.{b_no}, CASE WHEN UPPER(NVL(h.{b_type},'C')) LIKE 'R%' THEN 1 ELSE 0 END"
                    else:
                        sql_b = f"SELECT h.{b_loc} AS lc, {b_rn_expr} AS rn, h.{b_no} AS bno, 0 AS is_ret FROM {bh} h INNER JOIN {bd} d ON {join_b} WHERE {' AND '.join(wh)} GROUP BY h.{b_loc}, {b_rn_expr}, h.{b_no}"
                    prb: Dict[str, Any] = {}
                    if location_code is not None:
                        prb['lc'] = int(location_code)
                    cur.execute(sql_b, prb)
                    bills = cur.fetchall() or []
                    for bill_row in bills:
                        if len(bill_row) >= 4:
                            lc, rn, bno, is_ret = (bill_row[0], bill_row[1], bill_row[2], int(bill_row[3] or 0))
                        else:
                            lc, rn, bno, is_ret = (bill_row[0], bill_row[1], bill_row[2], 0)
                        try:
                            loc_i = int(lc)
                            reset_i = int(rn or 1)
                            bno_i = int(bno)
                        except (TypeError, ValueError):
                            continue
                        ln_b = f'NVL(d.{d_sl}, ROW_NUMBER() OVER (ORDER BY d.ROWID))' if d_sl else 'ROW_NUMBER() OVER (ORDER BY d.ROWID)'
                        st_sel = f"NVL(TRIM(d.{d_store}),'')" if d_store else "''"
                        if d_vatp and d_vatamt:
                            vat_sel = f', NVL(d.{d_vatp},0) AS vatp, NVL(d.{d_vatamt},0) AS vatamt'
                        elif d_vatp:
                            vat_sel = f', NVL(d.{d_vatp},0) AS vatp, 0 AS vatamt'
                        elif d_vatamt:
                            vat_sel = f', 0 AS vatp, NVL(d.{d_vatamt},0) AS vatamt'
                        else:
                            vat_sel = ', 0 AS vatp, 0 AS vatamt'
                        b_qty = f'NVL(d.{d_qty},0)' if d_qty else '0'
                        b_rate = f'NVL(d.{d_rate},0)' if d_rate else '0'
                        b_uom = f"NVL(d.{d_uom},'NOS')" if d_uom else "'NOS'"
                        b_disc = f'NVL(d.{d_disc},0)' if d_disc else '0'
                        if d_base and d_qty:
                            b_base = f'NVL(d.{d_base}, NVL(d.{d_qty},0))'
                        elif d_base:
                            b_base = f'NVL(d.{d_base}, 0)'
                        elif d_qty:
                            b_base = f'NVL(d.{d_qty}, 0)'
                        else:
                            b_base = '0'
                        line_sql = f'SELECT {ln_b} AS ln, d.{d_item} AS itemcode, {b_qty} AS qty, {b_rate} AS rate, {b_uom} AS uom, {b_disc} AS disc, {b_base} AS baseqty, {st_sel} AS st {vat_sel} FROM {bd} d WHERE d.{d_no} = :bno AND d.{d_loc} = :loc ' + (f' AND NVL(d.{d_reset},1) = :rn ' if d_reset else '')
                        lpb = {'bno': bno_i, 'loc': loc_i, 'rn': reset_i} if d_reset else {'bno': bno_i, 'loc': loc_i}
                        cur.execute(line_sql, lpb)
                        for row in cur.fetchall() or []:
                            if len(row) >= 10:
                                ln, icode, qty, rate, uom, disc, baseqty, st, vatp_l, vatamt_l = row[:10]
                            else:
                                ln, icode, qty, rate, uom, disc, baseqty, st = row[:8]
                                vatp_l, vatamt_l = (0.0, 0.0)
                            try:
                                lineno = int(ln or 0)
                                item_int = int(icode)
                            except (TypeError, ValueError):
                                continue
                            if lineno <= 0:
                                continue
                            src_doc = 'BILL RETURN' if is_ret else 'BILL'
                            ttype = 'SALES RETURN' if is_ret else 'SALES'
                            if _journal_row_exists_any(cur, conn, loc_i, reset_i, bno_i, lineno, src_doc, str(bno_i)):
                                stats['skipped_exists'] += 1
                                continue
                            qty_f = float(qty or 0)
                            rate_f = float(rate or 0)
                            disc_f = float(disc or 0)
                            base_f = abs(float(baseqty or 0))
                            amt_f = max(0.0, abs(qty_f) * rate_f - disc_f)
                            vatp = float(vatp_l or 0) if d_vatp else _vat_percent_for_item(cur, loc_i, item_int)
                            if len(row) >= 10 and d_vatamt:
                                vat_amt = float(vatamt_l or 0)
                            else:
                                vat_amt = round(amt_f * vatp / 100.0, 3)
                            qty_out = round(abs(base_f) if is_ret else -abs(base_f), 3) if base_f else 0.0
                            amount_val = round(amt_f if is_ret else -amt_f, 3)
                            total_amount_val = round(amount_val + (vat_amt if not is_ret else -abs(vat_amt)), 3)
                            wh_code_col_b = itemjournal_warehouse_code_column(tbl_u)
                            wh_code_key_b = str(wh_code_col_b or '').upper() if wh_code_col_b else None
                            row_map = {'LOCATIONCODE': loc_i, 'RESETNO': reset_i, 'RECEIPTNO': bno_i, 'LINENO': lineno, 'ITEMCODE': item_int, 'UOM': str(uom or 'NOS')[:20], 'QTY': qty_out, 'TOTALINVENTORY': qty_out if 'TOTALINVENTORY' in jcols else None, 'RATE': rate_f, 'AMOUNT': amount_val, 'VATPERCENT': vatp, 'VATAMOUNT': round(-abs(vat_amt), 3) if not is_ret else round(abs(vat_amt), 3), 'TOTALAMOUNT': total_amount_val, 'TRANSTYPE': ttype, 'SOURCE_DOC': src_doc, 'SOURCE_NO': str(bno_i)}
                            if wh_code_key_b and wh_code_key_b in jcols:
                                row_map[wh_code_key_b] = str(st or '')[:30]
                            avg_f = _journal_average_cost_for_line(cur, loc_i, {'item': item_int}, item_cache=avg_cache)
                            if avg_f > 0 and 'AVERAGECOST' in jcols:
                                row_map['AVERAGECOST'] = avg_f
                            row_map = {k: v for k, v in row_map.items() if v is not None}
                            if _journal_insert_from_map(cur, tbl_u, jcols, row_map, dry_run=dry_run):
                                stats['sales'] += 1
            rth = _detect_table(['RETURNHDR', 'returnhdr'])
            rtd = _detect_table(['RETURNDTL', 'returndtl'])
            post_pr = _table_exists('TBLPRPOSTINGHDR')
            if include_purchase_return and rth and rtd and post_pr:
                h_loc = _detect_column(rth, ['LOCATIONCODE', 'locationcode'])
                h_reset = _detect_column(rth, ['RESETNO', 'resetno'])
                h_no = _detect_column(rth, ['GOODSRETURNNO', 'goodsreturnno'])
                h_type = _detect_column(rth, ['RETURNTYPE', 'returntype'])
                d_loc = _detect_column(rtd, ['LOCATIONCODE', 'locationcode'])
                d_reset = _detect_column(rtd, ['RESETNO', 'resetno'])
                d_no = _detect_column(rtd, ['GOODSRETURNNO', 'goodsreturnno'])
                d_item = _detect_column(rtd, ['ITEMCODE', 'itemcode'])
                d_qty = _detect_column(rtd, ['QUANTITY', 'quantity'])
                d_rate = _detect_column(rtd, ['RATE', 'rate'])
                d_uom = _detect_column(rtd, ['UOM', 'uom'])
                d_disc = _detect_column(rtd, ['DISCOUNT', 'discount'])
                d_conv = _detect_column(rtd, ['CONVERSIONFACTOR', 'UOMFACTOR', 'conversionfactor', 'uomfactor'])
                d_store = _detect_column(rtd, ['STORE', 'store'])
                d_sl = _detect_column(rtd, ['SLNO', 'slno', 'LINENO', 'lineno'])
                h_loc = _sql_ident_col(h_loc)
                h_reset = _sql_ident_col(h_reset)
                h_no = _sql_ident_col(h_no)
                h_type = _sql_ident_col(h_type)
                d_loc = _sql_ident_col(d_loc)
                d_reset = _sql_ident_col(d_reset)
                d_no = _sql_ident_col(d_no)
                d_item = _sql_ident_col(d_item)
                d_qty = _sql_ident_col(d_qty)
                d_rate = _sql_ident_col(d_rate)
                d_uom = _sql_ident_col(d_uom)
                d_disc = _sql_ident_col(d_disc)
                d_conv = _sql_ident_col(d_conv)
                d_store = _sql_ident_col(d_store)
                d_sl = _sql_ident_col(d_sl)
                if h_loc and h_no and d_no and d_item:
                    join_h = f'h.{h_no} = d.{d_no} AND h.{h_loc} = d.{d_loc}'
                    if h_reset and d_reset:
                        join_h += f' AND NVL(h.{h_reset},1) = NVL(d.{d_reset},1)'
                    type_filter = ''
                    if h_type:
                        type_filter = f" AND (UPPER(NVL(h.{h_type},' ')) LIKE '%P%' OR UPPER(NVL(h.{h_type},' ')) LIKE '%R%')"
                    pr_rn_expr = f'NVL(h.{h_reset},1)' if h_reset else '1'
                    pr_p_reset = f'p.RESETNO = NVL(h.{h_reset},1)' if h_reset else 'p.RESETNO = 1'
                    sql_pr = f'SELECT DISTINCT h.{h_loc} AS lc, {pr_rn_expr} AS rn, h.{h_no} AS grn FROM {rth} h INNER JOIN {rtd} d ON {join_h} INNER JOIN TBLPRPOSTINGHDR p ON p.LOCATIONCODE = h.{h_loc} AND {pr_p_reset} AND p.GOODSRETURNNO = h.{h_no} WHERE 1=1 {type_filter} '
                    prp: Dict[str, Any] = {}
                    if location_code is not None:
                        sql_pr += f' AND h.{h_loc} = :lc'
                        prp['lc'] = int(location_code)
                    cur.execute(sql_pr, prp)
                    prs = cur.fetchall() or []
                    for lc, rn, grn in prs:
                        try:
                            loc_i = int(lc)
                            reset_i = int(rn or 1)
                            grn_i = int(grn)
                        except (TypeError, ValueError):
                            continue
                        pr_ln = f'NVL(d.{d_sl}, ROW_NUMBER() OVER (ORDER BY d.ROWID))' if d_sl else 'ROW_NUMBER() OVER (ORDER BY d.ROWID)'
                        pr_cf = f'NVL(d.{d_conv},0)' if d_conv else '0'
                        pr_st = f"NVL(TRIM(d.{d_store}),'')" if d_store else "''"
                        pr_disc = f'NVL(d.{d_disc},0)' if d_disc else '0'
                        pr_uom = f"NVL(d.{d_uom},'NOS')" if d_uom else "'NOS'"
                        pr_rate = f'NVL(d.{d_rate},0)' if d_rate else '0'
                        pr_qty = f'NVL(d.{d_qty},0)' if d_qty else '0'
                        line_sql = f'SELECT {pr_ln} AS ln, d.{d_item} AS itemcode, {pr_qty} AS qty, {pr_rate} AS rate, {pr_uom} AS uom, {pr_disc} AS disc, {pr_cf} AS cf, {pr_st} AS st FROM {rtd} d WHERE d.{d_no} = :g AND d.{d_loc} = :loc ' + (f' AND NVL(d.{d_reset},1) = :rn ' if d_reset else '')
                        lpp = {'g': grn_i, 'loc': loc_i, 'rn': reset_i} if d_reset else {'g': grn_i, 'loc': loc_i}
                        cur.execute(line_sql, lpp)
                        for row in cur.fetchall() or []:
                            ln, icode, qty, rate, uom, disc, cf, st = row
                            try:
                                lineno = int(ln or 0)
                                item_int = int(icode)
                            except (TypeError, ValueError):
                                continue
                            if lineno <= 0:
                                continue
                            if _journal_row_exists_any(cur, conn, loc_i, reset_i, grn_i, lineno, 'RETURN', str(grn_i)):
                                stats['skipped_exists'] += 1
                                continue
                            qty_f = abs(float(qty or 0))
                            rate_f = float(rate or 0)
                            disc_f = float(disc or 0)
                            cf_f = float(cf or 0)
                            if cf_f <= 0:
                                cf_f = 1.0
                            qty_out_base = -abs(qty_f * cf_f)
                            amt_out = -max(0.0, qty_f * rate_f - disc_f)
                            wh_code_col_pr = itemjournal_warehouse_code_column(tbl_u)
                            wh_code_key_pr = str(wh_code_col_pr or '').upper() if wh_code_col_pr else None
                            row_map = {'LOCATIONCODE': loc_i, 'RESETNO': reset_i, 'RECEIPTNO': grn_i, 'LINENO': lineno, 'ITEMCODE': item_int, 'UOM': str(uom or 'NOS')[:20], 'QTY': qty_out_base, 'TOTALINVENTORY': qty_out_base if 'TOTALINVENTORY' in jcols else None, 'RATE': rate_f, 'AMOUNT': amt_out, 'VATPERCENT': 0.0, 'VATAMOUNT': 0.0, 'TOTALAMOUNT': amt_out, 'TRANSTYPE': 'PURCHASE_RETURN', 'SOURCE_DOC': 'RETURN', 'SOURCE_NO': str(grn_i)}
                            if wh_code_key_pr and wh_code_key_pr in jcols:
                                row_map[wh_code_key_pr] = str(st or '')[:30]
                            avg_f = _journal_average_cost_for_line(cur, loc_i, {'item': item_int}, item_cache=avg_cache)
                            if avg_f > 0 and 'AVERAGECOST' in jcols:
                                row_map['AVERAGECOST'] = avg_f
                            row_map = {k: v for k, v in row_map.items() if v is not None}
                            if _journal_insert_from_map(cur, tbl_u, jcols, row_map, dry_run=dry_run):
                                stats['purchase_return'] += 1
        if own_conn and (not dry_run):
            conn.commit()
        _TABLE_COLUMNS_CACHE.pop(tbl_u, None)
        msg = f"Backfill into {tbl_u}: GRN={stats['grn']}, sales={stats['sales']}, purchase_return={stats['purchase_return']}, skipped_existing={stats['skipped_exists']}" + (' (dry_run)' if dry_run else '')
        return (True, msg, stats)
    except Exception as e:
        if own_conn:
            try:
                conn.rollback()
            except Exception:
                pass
        return (False, str(e), stats)
    finally:
        if own_conn:
            try:
                conn.close()
            except Exception:
                pass

