def ensure_customerloyalty_table() -> bool:
    """Create tenant ``CUSTOMERLOYALTY`` if missing (POS loyalty master; matches legacy ERP layout)."""
    try:
        key = CUSTOMERLOYALTY_TABLE
        if _table_exists(key):
            return True
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f"SELECT COUNT(*) FROM user_tables WHERE table_name = '{key}'")
                if (cur.fetchone() or [0])[0]:
                    pass
                else:
                    cur.execute(
                        f"""
                        CREATE TABLE {key} (
                            LOCATIONCODE   NUMBER(2, 0) NOT NULL,
                            CUSTOMERCODE   NUMBER(10, 0) NOT NULL,
                            CUSTOMERNAME   VARCHAR2(40 BYTE),
                            ADDRESS1       VARCHAR2(40 BYTE),
                            ADDRESS2       VARCHAR2(40 BYTE),
                            ADDRESS3       VARCHAR2(40 BYTE),
                            NATIONALITY    VARCHAR2(40 BYTE),
                            PHONE1         VARCHAR2(15 BYTE),
                            PHONE2         VARCHAR2(15 BYTE),
                            MOB            VARCHAR2(15 BYTE),
                            EMAILID        VARCHAR2(30 BYTE),
                            CARDNO         NUMBER(10, 0),
                            ISSUEDATE      DATE,
                            EXPIRYDATE     DATE,
                            OUTLETCODE     NUMBER,
                            TOTALPOINTS    NUMBER(14, 2),
                            QIDNO          NUMBER,
                            EMTHIAS        CHAR(1 BYTE) DEFAULT 'N' NOT NULL,
                            EMTHIASCARDNO  NUMBER DEFAULT 0,
                            CONSTRAINT PK_{key} PRIMARY KEY (LOCATIONCODE, CUSTOMERCODE)
                        ) TABLESPACE USERS
                        """
                    )
                    try:
                        cur.execute(f'CREATE INDEX IDX_{key}_LOC ON {key} (LOCATIONCODE)')
                    except Exception:
                        pass
            conn.commit()
        try:
            _TABLE_EXISTS_CACHE.pop(key, None)
            _TABLE_COLUMNS_CACHE.pop(key, None)
        except Exception:
            pass
        return True
    except Exception as e:
        print(f'[ERROR ensure_customerloyalty_table] {e}')
        import traceback
        traceback.print_exc()
        return False


def ensure_pos_bill_paymode_table() -> bool:
    """Create tenant ``POS_BILL_PAYMODE`` (payment tender lines per posted POS bill)."""
    try:
        key = POS_BILL_PAYMODE_TABLE
        if _table_exists(key):
            cols_u = {str(c or '').upper() for c in (_get_table_columns(key) or [])}
            missing = []
            if 'POSDATE' not in cols_u:
                missing.append(('POSDATE', 'DATE'))
            if missing:
                with _get_connection() as conn:
                    with conn.cursor() as cur:
                        for col, ddl in missing:
                            try:
                                cur.execute(f'ALTER TABLE {key} ADD ({col} {ddl})')
                            except Exception as exc:
                                msg = str(exc).upper()
                                if 'ORA-01430' not in msg and 'ORA-00955' not in msg:
                                    raise
                    conn.commit()
                try:
                    _TABLE_COLUMNS_CACHE.pop(key, None)
                except Exception:
                    pass
            return True
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f"SELECT COUNT(*) FROM user_tables WHERE table_name = '{key}'")
                if (cur.fetchone() or [0])[0]:
                    pass
                else:
                    cur.execute(
                        f"""
                        CREATE TABLE {key} (
                            LOCATIONCODE  NUMBER(10) NOT NULL,
                            BILLNO        NUMBER(15) NOT NULL,
                            SLNO          NUMBER(5) NOT NULL,
                            PAYMODE       VARCHAR2(30 BYTE) NOT NULL,
                            AMOUNT        NUMBER(18, 4) NOT NULL,
                            POSDATE       DATE,
                            REFERENCE     VARCHAR2(200 BYTE),
                            CREATED_AT    TIMESTAMP(6) DEFAULT SYSTIMESTAMP,
                            CONSTRAINT PK_{key} PRIMARY KEY (LOCATIONCODE, BILLNO, SLNO)
                        ) TABLESPACE USERS
                        """
                    )
                    try:
                        cur.execute(f'CREATE INDEX IDX_{key}_BILL ON {key} (LOCATIONCODE, BILLNO)')
                    except Exception:
                        pass
            conn.commit()
        try:
            _TABLE_EXISTS_CACHE.pop(key, None)
            _TABLE_COLUMNS_CACHE.pop(key, None)
        except Exception:
            pass
        return True
    except Exception as e:
        print(f'[ERROR ensure_pos_bill_paymode_table] {e}')
        return False


def _insert_pos_bill_paymode_rows(cur: Any, location_code: int, billno: Any, rows: List[Dict[str, Any]], pos_date: Any = None) -> None:
    """Insert tender rows into ``POS_BILL_PAYMODE`` (table must exist)."""
    if not rows:
        return
    tbl = POS_BILL_PAYMODE_TABLE
    cols_u = {str(c or '').upper() for c in (_get_table_columns(tbl) or [])}
    slno = 0
    for r in rows:
        code = str((r or {}).get('code') or '').strip().upper()[:30]
        try:
            amt = float((r or {}).get('amount') or 0)
        except (TypeError, ValueError):
            amt = 0.0
        # Allow negative amounts (sales returns / refunds).
        if not code or abs(amt) < 0.005:
            continue
        slno += 1
        insert_cols = ['LOCATIONCODE', 'BILLNO', 'SLNO', 'PAYMODE', 'AMOUNT']
        insert_vals = [':loc', ':bno', ':slno', ':pm', ':amt']
        params: Dict[str, Any] = {'loc': int(location_code), 'bno': coerce_billno(billno), 'slno': slno, 'pm': code, 'amt': round(amt, 4)}
        if 'POSDATE' in cols_u:
            insert_cols.append('POSDATE')
            insert_vals.append('TRUNC(:posdate)')
            params['posdate'] = pos_date
        ref = str((r or {}).get('reference') or '').strip()[:200] or None
        if 'REFERENCE' in cols_u:
            insert_cols.append('REFERENCE')
            insert_vals.append(':ref')
            params['ref'] = ref
        cur.execute(
            f"""
            INSERT INTO {tbl} ({', '.join(insert_cols)})
            VALUES ({', '.join(insert_vals)})
            """,
            params,
        )


