def ensure_pos_settlement_account_config_table() -> bool:
    """Tenant setup for POS settlement accounts that are not tender clearing accounts."""
    try:
        tbl = POS_SETTLEMENT_ACCOUNT_CONFIG_TABLE
        if not _table_exists(tbl):
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute(f"SELECT COUNT(*) FROM user_tables WHERE table_name = '{tbl}'")
                    if not (cur.fetchone() or [0])[0]:
                        cur.execute(
                            f"""
                            CREATE TABLE {tbl} (
                                CONFIG_KEY    VARCHAR2(40 BYTE) NOT NULL,
                                LABEL         VARCHAR2(120 BYTE),
                                ACCOUNT_CODE  VARCHAR2(20 BYTE),
                                NORMAL_SIDE   VARCHAR2(2 BYTE),
                                UPDATED_BY    VARCHAR2(100 BYTE),
                                UPDATED_AT    TIMESTAMP(6) DEFAULT SYSTIMESTAMP,
                                CONSTRAINT PK_POS_STL_ACC_CFG PRIMARY KEY (CONFIG_KEY)
                            ) TABLESPACE USERS
                            """
                        )
                conn.commit()
            try:
                _TABLE_EXISTS_CACHE.pop(tbl, None)
                _TABLE_COLUMNS_CACHE.pop(tbl, None)
            except Exception:
                pass
        _seed_pos_settlement_account_config()
        return True
    except Exception as e:
        print(f'[ERROR ensure_pos_settlement_account_config_table] {e}')
        return False


def _seed_pos_settlement_account_config() -> None:
    tbl = POS_SETTLEMENT_ACCOUNT_CONFIG_TABLE
    with _get_connection() as conn:
        with conn.cursor() as cur:
            for row in POS_SETTLEMENT_ACCOUNT_CONFIG_SEED_ROWS:
                cur.execute(f'SELECT COUNT(*) FROM {tbl} WHERE CONFIG_KEY = :k', {'k': row['config_key']})
                exists_row = int((cur.fetchone() or [0])[0]) > 0
                if exists_row:
                    cur.execute(
                        f"""
                        UPDATE {tbl}
                           SET LABEL = :lbl,
                               NORMAL_SIDE = :side
                         WHERE CONFIG_KEY = :k
                        """,
                        {'k': row['config_key'], 'lbl': row['label'], 'side': row['normal_side']},
                    )
                else:
                    cur.execute(
                        f"""
                        INSERT INTO {tbl} (CONFIG_KEY, LABEL, ACCOUNT_CODE, NORMAL_SIDE, UPDATED_BY)
                        VALUES (:k, :lbl, :acc, :side, 'SYSTEM')
                        """,
                        {
                            'k': row['config_key'],
                            'lbl': row['label'],
                            'acc': row['account_code'] or None,
                            'side': row['normal_side'],
                        },
                    )
        conn.commit()


def _pos_account_code_exists(account_code: str) -> bool:
    code = str(account_code or '').strip()[:20]
    if not code:
        return True
    try:
        rows = get_all_chart_of_accounts() or []
    except Exception:
        rows = []
    for r in rows:
        if str((r or {}).get('code') or '').strip() == code:
            return True
    return False


def get_pos_settlement_account_config() -> Dict[str, Dict[str, Any]]:
    if not ensure_pos_settlement_account_config_table():
        return {}
    tbl = POS_SETTLEMENT_ACCOUNT_CONFIG_TABLE
    rows = _safe_rows(f'SELECT * FROM {tbl} ORDER BY CONFIG_KEY', {}) or []
    out: Dict[str, Dict[str, Any]] = {}
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        key = str(rk.get('config_key') or '').strip().upper()
        if not key:
            continue
        out[key] = {
            'config_key': key,
            'label': str(rk.get('label') or '').strip(),
            'account_code': str(rk.get('account_code') or '').strip(),
            'normal_side': str(rk.get('normal_side') or '').strip() or 'Dr',
        }
    return out


def upsert_pos_settlement_account_config(payload: Dict[str, Any], *, updated_by: str = '') -> Tuple[bool, str]:
    if not ensure_pos_settlement_account_config_table():
        return (False, 'POS settlement account config table is not available.')
    allowed = {r['config_key']: r for r in POS_SETTLEMENT_ACCOUNT_CONFIG_SEED_ROWS}
    rows_in = payload.get('accounts') if isinstance(payload, dict) else None
    if not isinstance(rows_in, list):
        return (False, 'Accounts payload is required.')
    clean: List[Dict[str, str]] = []
    for row in rows_in:
        if not isinstance(row, dict):
            continue
        key = str(row.get('config_key') or '').strip().upper()
        if key not in allowed:
            continue
        acc = str(row.get('account_code') or '').strip()[:20]
        if acc and not _pos_account_code_exists(acc):
            return (False, f'Account {acc} does not exist in Chart of Accounts.')
        seed = allowed[key]
        clean.append({'key': key, 'label': seed['label'], 'acc': acc, 'side': seed['normal_side']})
    if not clean:
        return (False, 'No valid account config rows.')
    tbl = POS_SETTLEMENT_ACCOUNT_CONFIG_TABLE
    user = str(updated_by or '').strip()[:100] or 'SYSTEM'
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                for row in clean:
                    cur.execute(
                        f"""
                        MERGE INTO {tbl} t
                        USING (SELECT :k AS CONFIG_KEY FROM dual) s
                           ON (t.CONFIG_KEY = s.CONFIG_KEY)
                        WHEN MATCHED THEN UPDATE SET
                             LABEL = :lbl,
                             ACCOUNT_CODE = :acc,
                             NORMAL_SIDE = :side,
                             UPDATED_BY = :usr,
                             UPDATED_AT = SYSTIMESTAMP
                        WHEN NOT MATCHED THEN INSERT (
                             CONFIG_KEY, LABEL, ACCOUNT_CODE, NORMAL_SIDE, UPDATED_BY, UPDATED_AT
                        ) VALUES (
                             :k, :lbl, :acc, :side, :usr, SYSTIMESTAMP
                        )
                        """,
                        {
                            'k': row['key'],
                            'lbl': row['label'],
                            'acc': row['acc'] or None,
                            'side': row['side'],
                            'usr': user,
                        },
                    )
            conn.commit()
        return (True, '')
    except Exception as e:
        return (False, str(e))


