def _seed_stk_adj_account_config() -> None:
    try:
        ensure_inventory_chart_of_accounts()
    except Exception:
        pass
    tbl = STK_ADJ_ACCOUNT_CONFIG_TABLE
    default_acc = STK_ADJ_DEFAULT_VARIANCE_CODE
    with _get_connection() as conn:
        with conn.cursor() as cur:
            for row in STK_ADJ_ACCOUNT_CONFIG_SEED_ROWS:
                key = row['config_key']
                seed_acc = str(row.get('account_code') or default_acc).strip() or default_acc
                cur.execute(f'SELECT COUNT(*) FROM {tbl} WHERE CONFIG_KEY = :k', {'k': key})
                exists_row = int((cur.fetchone() or [0])[0]) > 0
                if exists_row:
                    cur.execute(
                        f"SELECT TRIM(NVL(ACCOUNT_CODE, '')) FROM {tbl} WHERE CONFIG_KEY = :k",
                        {'k': key},
                    )
                    current_acc = str((cur.fetchone() or [''])[0] or '').strip()
                    migrate_acc = (
                        not current_acc
                        or (key == 'DECREASE' and current_acc == STK_ADJ_LEGACY_DECREASE_CODE)
                    )
                    if migrate_acc:
                        cur.execute(
                            f"""
                            UPDATE {tbl}
                               SET LABEL = :lbl,
                                   NORMAL_SIDE = :side,
                                   ACCOUNT_CODE = :acc,
                                   UPDATED_BY = 'SYSTEM',
                                   UPDATED_AT = SYSTIMESTAMP
                             WHERE CONFIG_KEY = :k
                            """,
                            {'k': key, 'lbl': row['label'], 'side': row['normal_side'], 'acc': seed_acc},
                        )
                    else:
                        cur.execute(
                            f"""
                            UPDATE {tbl}
                               SET LABEL = :lbl,
                                   NORMAL_SIDE = :side
                             WHERE CONFIG_KEY = :k
                            """,
                            {'k': key, 'lbl': row['label'], 'side': row['normal_side']},
                        )
                else:
                    cur.execute(
                        f"""
                        INSERT INTO {tbl} (CONFIG_KEY, LABEL, ACCOUNT_CODE, NORMAL_SIDE, UPDATED_BY)
                        VALUES (:k, :lbl, :acc, :side, 'SYSTEM')
                        """,
                        {
                            'k': key,
                            'lbl': row['label'],
                            'acc': seed_acc,
                            'side': row['normal_side'],
                        },
                    )
            _ensure_stk_adj_opening_mode_row(cur)
        conn.commit()


def _ensure_stk_adj_opening_mode_row(cur: Any) -> None:
    tbl = STK_ADJ_ACCOUNT_CONFIG_TABLE
    cur.execute(f'SELECT COUNT(*) FROM {tbl} WHERE CONFIG_KEY = :k', {'k': STK_ADJ_OPENING_MODE_KEY})
    if int((cur.fetchone() or [0])[0]) > 0:
        return
    cur.execute(
        f"""
        INSERT INTO {tbl} (CONFIG_KEY, LABEL, ACCOUNT_CODE, NORMAL_SIDE, UPDATED_BY)
        VALUES (:k, :lbl, :acc, :side, 'SYSTEM')
        """,
        {
            'k': STK_ADJ_OPENING_MODE_KEY,
            'lbl': 'Opening stock import mode',
            'acc': 'N',
            'side': 'N',
        },
    )


def get_stk_adj_opening_stock_mode_enabled() -> bool:
    """True when Accounts setup has opening stock import mode turned on."""
    cfg = get_stk_adj_account_config()
