def upsert_stk_adj_account_config(payload: Dict[str, Any], *, updated_by: str = '') -> Tuple[bool, str]:
    if not ensure_stk_adj_account_config_table():
        return (False, 'Stock adjustment account config table is not available.')
    allowed = {r['config_key']: r for r in STK_ADJ_ACCOUNT_CONFIG_SEED_ROWS}
    rows_in = payload.get('accounts') if isinstance(payload, dict) else None
    if not isinstance(rows_in, list):
        return (False, 'Accounts payload is required.')
    clean: List[Dict[str, str]] = []
    for row in rows_in:
        if not isinstance(row, dict):
            continue
        key = str(row.get('config_key') or '').strip().upper()
        if key not in allowed:
            continue
        acc = str(row.get('account_code') or '').strip()[:20]
        if acc and not _pos_account_code_exists(acc):
            return (False, f'Account {acc} does not exist in Chart of Accounts.')
        seed = allowed[key]
        clean.append({'key': key, 'label': seed['label'], 'acc': acc, 'side': seed['normal_side']})
    if not clean and 'opening_stock_mode' not in payload:
        return (False, 'No valid account config rows.')
    tbl = STK_ADJ_ACCOUNT_CONFIG_TABLE
    user = str(updated_by or '').strip()[:100] or 'SYSTEM'
    try:
        if clean:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    for row in clean:
                        cur.execute(
                            f"""
                            MERGE INTO {tbl} t
                            USING (SELECT :k AS CONFIG_KEY FROM dual) s
                               ON (t.CONFIG_KEY = s.CONFIG_KEY)
                            WHEN MATCHED THEN UPDATE SET
                                 LABEL = :lbl,
                                 ACCOUNT_CODE = :acc,
                                 NORMAL_SIDE = :side,
                                 UPDATED_BY = :usr,
                                 UPDATED_AT = SYSTIMESTAMP
                            WHEN NOT MATCHED THEN INSERT (
                                 CONFIG_KEY, LABEL, ACCOUNT_CODE, NORMAL_SIDE, UPDATED_BY, UPDATED_AT
                            ) VALUES (
                                 :k, :lbl, :acc, :side, :usr, SYSTIMESTAMP
                            )
                            """,
                            {
                                'k': row['key'],
                                'lbl': row['label'],
                                'acc': row['acc'] or None,
                                'side': row['side'],
                                'usr': user,
                            },
                        )
                conn.commit()
        if 'opening_stock_mode' in payload:
            ok_mode, err_mode = set_stk_adj_opening_stock_mode(
                bool(payload.get('opening_stock_mode')),
                updated_by=user,
            )
            if not ok_mode:
                return (False, err_mode or 'Could not save opening stock mode.')
        return (True, '')
    except Exception as e:
        return (False, str(e))


def resolve_stk_adj_variance_account_codes() -> Dict[str, str]:
    """Increase (+) credits inventory Dr; decrease (−) debits inventory Cr offsets."""
    import os as _os

    default_var = str(DEFAULT_PARTY_ACCOUNTS.get('inventory_adjustment') or STK_ADJ_DEFAULT_VARIANCE_CODE).strip()
    cfg = get_stk_adj_account_config()
    inc = str((cfg.get('INCREASE') or {}).get('account_code') or '').strip()
    dec = str((cfg.get('DECREASE') or {}).get('account_code') or '').strip()
    if not inc:
        inc = (
            _os.getenv('STOCK_ADJUSTMENT_GL_ACCOUNT_INCREASE')
            or _os.getenv('STOCK_ADJUSTMENT_GL_ACCOUNT')
            or _os.getenv('STOCK_COUNT_VARIANCE_GL_ACCOUNT')
            or default_var
        ).strip()
    if not dec:
        dec = (
            _os.getenv('STOCK_ADJUSTMENT_GL_ACCOUNT_DECREASE')
            or _os.getenv('STOCK_ADJUSTMENT_GL_ACCOUNT')
            or _os.getenv('STOCK_COUNT_VARIANCE_GL_ACCOUNT')
            or default_var
        ).strip()
    opening = str((cfg.get('OPENING') or {}).get('account_code') or '').strip()
    if not opening:
        opening = (
            _os.getenv('STOCK_ADJUSTMENT_GL_ACCOUNT_OPENING')
            or str(DEFAULT_PARTY_ACCOUNTS.get('opening_stock') or STK_ADJ_DEFAULT_OPENING_STOCK_CODE)
        ).strip()
    return {
        'increase': inc[:20],
        'decrease': dec[:20],
        'opening': opening[:20],
    }


def fetch_pos_paymode_totals_for_bills(location_code: int, bill_nos: List[Any]) -> Dict[str, float]:
    """Sum POS_BILL_PAYMODE amounts per PAYMODE code for the given bills.

    Sales-return bills often store tender AMOUNT as a positive refund figure; sign by
    ``BILLHDR.NETBILLAMOUNT`` so settlement expected cash nets (sale − return).
    """
    if not bill_nos or not ensure_pos_bill_paymode_table():
        return {}
    tbl = POS_BILL_PAYMODE_TABLE
    clean = _clean_settlement_billnos(bill_nos)
    if not clean:
        return {}
    ph = ','.join([f':b{i}' for i in range(len(clean))])
    params: Dict[str, Any] = {'loc': int(location_code)}
    for i, bn in enumerate(clean):
        params[f'b{i}'] = bn
    # Negative NETBILLAMOUNT (returns) → negative tender contribution.
    q = f"""
        SELECT pm.PAYMODE AS pm,
               SUM(
                   CASE
                       WHEN NVL(bh.NETBILLAMOUNT, 0) < 0 THEN -ABS(NVL(pm.AMOUNT, 0))
                       ELSE NVL(pm.AMOUNT, 0)
                   END
               ) AS samt
        FROM {tbl} pm
        LEFT JOIN BILLHDR bh
          ON bh.LOCATIONCODE = pm.LOCATIONCODE
         AND bh.BILLNO = pm.BILLNO
        WHERE pm.LOCATIONCODE = :loc
          AND pm.BILLNO IN ({ph})
        GROUP BY pm.PAYMODE
    """
    rows = _safe_rows(q, params) or []
    out: Dict[str, float] = {}
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        pm = str(rk.get('pm') or '').strip().upper()
        if not pm:
            continue
        try:
            amt = float(rk.get('samt') or 0)
        except (TypeError, ValueError):
            amt = 0.0
        out[pm] = round(amt, 4)
    return out


def fetch_pos_paymode_amounts_by_bill(location_code: int, bill_nos: List[Any]) -> Dict[Any, Dict[str, float]]:
    """Per-bill POS_BILL_PAYMODE totals keyed by bill number then PAYMODE code."""
    if not bill_nos or not ensure_pos_bill_paymode_table():
        return {}
    tbl = POS_BILL_PAYMODE_TABLE
    clean: List[Any] = []
    seen: set = set()
    for b in bill_nos:
        bn = coerce_billno(b)
        if not billno_is_valid(bn):
            continue
        key = str(bn)
        if key in seen:
            continue
        seen.add(key)
        clean.append(bn)
    if not clean:
        return {}
    ph = ','.join([f':b{i}' for i in range(len(clean))])
    params: Dict[str, Any] = {'loc': int(location_code)}
    for i, bn in enumerate(clean):
        params[f'b{i}'] = bn
    q = f"""
        SELECT pm.BILLNO AS bno, pm.PAYMODE AS pm,
               SUM(
                   CASE
                       WHEN NVL(bh.NETBILLAMOUNT, 0) < 0 THEN -ABS(NVL(pm.AMOUNT, 0))
                       ELSE NVL(pm.AMOUNT, 0)
                   END
               ) AS samt
        FROM {tbl} pm
        LEFT JOIN BILLHDR bh
          ON bh.LOCATIONCODE = pm.LOCATIONCODE
         AND bh.BILLNO = pm.BILLNO
        WHERE pm.LOCATIONCODE = :loc
          AND pm.BILLNO IN ({ph})
        GROUP BY pm.BILLNO, pm.PAYMODE
    """
    rows = _safe_rows(q, params) or []
    out: Dict[Any, Dict[str, float]] = {}
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        bno = coerce_billno(rk.get('bno'))
        if not billno_is_valid(bno):
            continue
        pm = str(rk.get('pm') or '').strip().upper()
        if not pm:
            continue
        try:
            amt = float(rk.get('samt') or 0)
        except (TypeError, ValueError):
            amt = 0.0
        bucket = out.setdefault(bno, {})
        bucket[pm] = round(bucket.get(pm, 0.0) + amt, 4)
    return out


def settlement_tender_amounts_by_bill(
    location_code: int,
    bill_rows: List[Dict[str, Any]],
) -> Dict[int, Dict[str, float]]:
    """Tender amounts per bill for settlement UI: paymode detail when present, else BILLHDR buckets."""
    if not bill_rows:
        return {}
    bill_nos: List[int] = []
    for r in bill_rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        try:
            bn = int(rk.get('billno') or 0)
        except (TypeError, ValueError):
            bn = 0
        if bn > 0:
            bill_nos.append(bn)
    bill_nos = sorted(set(bill_nos))
    if not bill_nos:
        return {}
    pm_by_bill = fetch_pos_paymode_amounts_by_bill(location_code, bill_nos)
    with_pm = _pos_billnos_with_paymode_rows(location_code, bill_nos)
    out: Dict[int, Dict[str, float]] = {}
    for r in bill_rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        try:
            bn = int(rk.get('billno') or 0)
        except (TypeError, ValueError):
            continue
        if bn <= 0:
            continue
        if bn in with_pm and pm_by_bill.get(bn):
            out[bn] = dict(pm_by_bill[bn])
            continue
        hdr = paymode_amounts_from_billhdr_settlement_totals(
            _aggregate_pos_settlement_totals_from_billhdr_rows([r])
        )
        out[bn] = dict(hdr) if hdr else {}
    return out


def pos_settlement_bills_have_paymode_rows(location_code: int, bill_nos: List[Any]) -> bool:
    """True when every bill has at least one POS_BILL_PAYMODE row (detail present)."""
    if not bill_nos or not ensure_pos_bill_paymode_table():
        return False
    tbl = POS_BILL_PAYMODE_TABLE
    clean = _clean_settlement_billnos(bill_nos)
    if not clean:
        return False
    ph = ','.join([f':b{i}' for i in range(len(clean))])
    params: Dict[str, Any] = {'loc': int(location_code)}
    for i, bn in enumerate(clean):
        params[f'b{i}'] = bn
    q = f'SELECT BILLNO AS bno, COUNT(*) AS cnt FROM {tbl} WHERE LOCATIONCODE = :loc AND BILLNO IN ({ph}) GROUP BY BILLNO'
    rows = _safe_rows(q, params) or []
    present = set()
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        try:
            cnt = int(float(rk.get('cnt') or 0))
        except (TypeError, ValueError):
            cnt = 0
        if cnt <= 0:
            continue
        bn = coerce_billno(rk.get('bno'))
        if billno_is_valid(bn):
            present.add(str(bn))
    return len(present) == len(clean)


def paymode_amounts_from_billhdr_settlement_totals(totals: Dict[str, Any]) -> Dict[str, float]:
    """Map aggregated BILLHDR settlement buckets to pseudo paymode codes (matches ``POS_TENDER_TYPE`` seed codes).

    Used when selected bills do not all have ``POS_BILL_PAYMODE`` rows: clearing lines still post to GL accounts
    configured per tender in ``POS_TENDER_TYPE``.
    """
    out: Dict[str, float] = {}
    try:
        cash = float(totals.get('cash') or 0)
    except (TypeError, ValueError):
        cash = 0.0
    try:
        card = float(totals.get('card') or 0)
    except (TypeError, ValueError):
        card = 0.0
    try:
        wallet = float(totals.get('wallet') or 0)
    except (TypeError, ValueError):
        wallet = 0.0
    try:
        credit = float(totals.get('credit') or 0)
    except (TypeError, ValueError):
        credit = 0.0
    if abs(cash) > 0.0005:
        out['CASH'] = round(cash, 4)
    if abs(card) > 0.0005:
        out['CARD'] = round(card, 4)
    if abs(wallet) > 0.0005:
        out['WALLET'] = round(wallet, 4)
    if abs(credit) > 0.0005:
        out['CREDIT'] = round(credit, 4)
    return out


def pos_settlement_paymode_totals_reconcile(totals: Dict[str, Any], paymode_totals: Dict[str, Any]) -> bool:
    """Use POS paymode rows only when their total matches BILLHDR settlement buckets."""
    if not paymode_totals:
        return False
    try:
        pm_total = sum(float(v or 0) for v in paymode_totals.values())
    except (TypeError, ValueError):
        return False
    billhdr_buckets = paymode_amounts_from_billhdr_settlement_totals(totals)
    try:
        hdr_total = sum(float(v or 0) for v in billhdr_buckets.values())
    except (TypeError, ValueError):
        hdr_total = 0.0
    if abs(hdr_total) <= 0.0005:
        try:
            hdr_total = float(totals.get('net') or 0)
        except (TypeError, ValueError):
            hdr_total = 0.0
    return abs(round(pm_total - hdr_total, 2)) <= 0.01


def compute_pos_settlement_payment_mode_summary(location_code: int, bill_nos: List[Any]) -> Dict[str, Any]:
    """POS Settlement UI: payment lines with amounts aligned to draft/journal logic and labels from ``POS_TENDER_TYPE``."""
    clean = _clean_settlement_billnos(bill_nos)
    if not clean:
        return {'lines': [], 'source': 'empty', 'paymode_totals': {}, 'billhdr_totals': {}, 'bill_count': 0}
    rows = _fetch_billhdr_rows_for_pos_settlement(location_code, clean)
    if len(rows) != len(clean):
        return {'lines': [], 'source': 'bill_mismatch', 'paymode_totals': {}, 'billhdr_totals': {}, 'bill_count': len(clean)}
    totals_agg = _aggregate_pos_settlement_totals_from_billhdr_rows(rows)
    paymode_totals = fetch_pos_paymode_totals_for_bills(location_code, clean)
    all_have_paymode = pos_settlement_bills_have_paymode_rows(location_code, clean)
    tender_rows: List[Dict[str, Any]] = []
    if ensure_pos_tender_type_table():
        tender_rows = list_pos_tender_types(active_only=True)
    if paymode_totals and all_have_paymode and pos_settlement_paymode_totals_reconcile(totals_agg, paymode_totals):
        pm: Dict[str, float] = dict(paymode_totals)
        source = 'paymode_tender_map'
    else:
        pm = _merge_pos_shift_tender_totals(location_code, rows, clean)
        if not pm:
            pm = paymode_amounts_from_billhdr_settlement_totals(totals_agg)
            source = 'billhdr_buckets_tender_map'
        elif not pos_settlement_paymode_totals_reconcile(totals_agg, pm):
            # Unsigned return tenders (or stale paymode) — prefer BILLHDR net buckets.
            pm = paymode_amounts_from_billhdr_settlement_totals(totals_agg)
            source = 'billhdr_buckets_tender_map'
        else:
            source = 'paymode_merged_tender_map' if paymode_totals else 'billhdr_buckets_tender_map'
    code_to_label: Dict[str, str] = {}
    for tr in tender_rows:
        tc = str(tr.get('tender_code') or '').strip().upper()
        if tc:
            code_to_label[tc] = str(tr.get('tender_name') or tc).strip()
    # Show every active tender type (including zero amounts), then any unknown paymodes with activity
    codes: List[str] = []
    seen: set = set()
    for tr in tender_rows:
        tc = str(tr.get('tender_code') or '').strip().upper()
        if not tc or tc in seen:
            continue
        seen.add(tc)
        codes.append(tc)
    for code in sorted(pm.keys(), key=lambda c: _paymode_sort_key(c, tender_rows)):
        cu = str(code or '').strip().upper()
        if not cu or cu in seen:
            continue
        try:
            amt_extra = float(pm.get(code) or 0)
        except (TypeError, ValueError):
            amt_extra = 0.0
        if abs(amt_extra) <= 0.0005:
            continue
        seen.add(cu)
        codes.append(cu)
    lines_out: List[Dict[str, Any]] = []
    for code in codes:
        try:
            amt = float(pm.get(code) or 0)
        except (TypeError, ValueError):
            amt = 0.0
        lines_out.append(
            {
                'code': code,
                'label': code_to_label.get(code) or code.replace('_', ' ').title(),
                'amount': round(amt, 2),
            }
        )
    return {
        'lines': lines_out,
        'source': source,
        'paymode_totals': pm,
        'billhdr_totals': totals_agg,
        'bill_count': len(clean),
        'tender_types': [
            {
                'code': str(tr.get('tender_code') or '').strip().upper(),
                'name': str(tr.get('tender_name') or '').strip(),
                'sort_order': int(tr.get('sort_order') or 0),
            }
            for tr in tender_rows
            if str(tr.get('tender_code') or '').strip()
        ],
    }


def _paymode_sort_key(code: str, tender_rows: List[Dict[str, Any]]) -> Tuple[int, str]:
    code_u = str(code or '').strip().upper()
    for tr in tender_rows or []:
        if str(tr.get('tender_code') or '').strip().upper() == code_u:
            return (int(tr.get('sort_order') or 0), code_u)
    return (9999, code_u)


def _resolve_pos_tender_gl(pm_code: str, code_to_gl: Dict[str, str]) -> str:
    pc = str(pm_code or '').strip().upper()
    if not pc:
        return ''
    if pc in code_to_gl and code_to_gl[pc]:
        return str(code_to_gl[pc]).strip()[:20]
    if pc in ('VISA', 'MC', 'AMEX', 'MAESTRO', 'RUPAY'):
        return str(code_to_gl.get('CARD') or '').strip()[:20]
    return ''


def build_pos_settlement_gl_lines_from_paymodes(
    totals: Dict[str, Any],
    paymode_amounts: Dict[str, float],
    *,
    tender_rows: List[Dict[str, Any]],
    accounts: Dict[str, Any],
    meta: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    """Balanced journal lines using POS_BILL_PAYMODE totals + POS tender → GL mapping."""
    sales_acc = str((accounts or {}).get('sales_acc') or '').strip()[:20]
    tax_acc = str((accounts or {}).get('tax_acc') or '').strip()[:20]
    credit_acc = str((accounts or {}).get('credit_acc') or '').strip()[:20]

    code_to_gl: Dict[str, str] = {}
    code_to_label: Dict[str, str] = {}
    for tr in tender_rows or []:
        if not isinstance(tr, dict):
            continue
        tc = str(tr.get('tender_code') or '').strip().upper()
        if not tc:
            continue
        if str(tr.get('status') or 'ACTIVE').strip().upper() != 'ACTIVE':
            continue
        gl = str(tr.get('gl_account_code') or '').strip()[:20]
        if gl:
            code_to_gl[tc] = gl
        code_to_label[tc] = str(tr.get('tender_name') or tc).strip()[:80]

    amounts: Dict[str, float] = {}
    for k, v in (paymode_amounts or {}).items():
        kk = str(k or '').strip().upper()
        if not kk:
            continue
        try:
            fv = float(v or 0)
        except (TypeError, ValueError):
            fv = 0.0
        if abs(fv) <= 0.0005:
            continue
        amounts[kk] = amounts.get(kk, 0.0) + fv

    cred = amounts.pop('CREDIT', 0.0)
    if abs(cred) > 0.005:
        if (credit_acc or '').strip():
            amounts['CREDIT'] = amounts.get('CREDIT', 0.0) + cred
        else:
            amounts['CARD'] = amounts.get('CARD', 0.0) + cred

    lines: List[Dict[str, Any]] = []

    def add_tender(acc: str, amt: float, label: str) -> None:
        if amt > 0.005:
            if not acc:
                raise ValueError(f'Amount on {label}: map tender to a GL account in Tender Type Mapping.')
            lines.append({'account_code': acc, 'debit': round(amt, 2), 'credit': 0.0, 'remarks': f'POS {label}'})
        elif amt < -0.005:
            if not acc:
                raise ValueError(f'Refund on {label}: map tender to a GL account in Tender Type Mapping.')
            lines.append({'account_code': acc, 'debit': 0.0, 'credit': round(-amt, 2), 'remarks': f'POS {label} refund'})

    order_keys = sorted(amounts.keys(), key=lambda c: _paymode_sort_key(c, tender_rows))
    for pm in order_keys:
        amt = amounts[pm]
        glc = _resolve_pos_tender_gl(pm, code_to_gl)
        if abs(amt) <= 0.005:
            continue
        if not glc:
            raise ValueError(f'Paymode "{pm}" has no active GL mapping. Update Tender Type Mapping.')
        lbl = code_to_label.get(pm) or pm
        add_tender(glc, amt, lbl)

    tender_total = sum(float(ln.get('debit') or 0) - float(ln.get('credit') or 0) for ln in lines)
    bill_pm = (meta or {}).get('bill_paymode_totals') if isinstance(meta, dict) else None
    if isinstance(bill_pm, dict) and bill_pm:
        try:
            revenue_tender_total = sum(float(v or 0) for v in bill_pm.values())
        except (TypeError, ValueError):
            revenue_tender_total = tender_total
    else:
        revenue_tender_total = tender_total
    _apply_pos_cash_settlement_adjustments(
        lines,
        cash_acc=_resolve_pos_tender_gl('CASH', code_to_gl) or str((accounts or {}).get('cash_acc') or '').strip()[:20],
        accounts=accounts,
        meta=meta,
    )
    net = _pos_settlement_revenue_total(totals, revenue_tender_total)
    tax = float(totals.get('tax') or 0)
    base = round(net - tax, 2)
    if tax > 0.005 or tax < -0.005:
        if not tax_acc:
            raise ValueError('Tax amount is non-zero: select a tax account.')
        if not sales_acc:
            raise ValueError('Select a sales account.')
        if base > 0.005:
            lines.append({'account_code': sales_acc, 'debit': 0.0, 'credit': base, 'remarks': 'POS sales'})
        elif base < -0.005:
            lines.append({'account_code': sales_acc, 'debit': round(-base, 2), 'credit': 0.0, 'remarks': 'POS sales refund'})
        if tax > 0.005:
            lines.append({'account_code': tax_acc, 'debit': 0.0, 'credit': round(tax, 2), 'remarks': 'POS tax'})
        elif tax < -0.005:
            lines.append({'account_code': tax_acc, 'debit': round(-tax, 2), 'credit': 0.0, 'remarks': 'POS tax reversal'})
    else:
        if not sales_acc:
            raise ValueError('Select a sales account.')
        if net > 0.005:
            lines.append({'account_code': sales_acc, 'debit': 0.0, 'credit': round(net, 2), 'remarks': 'POS sales'})
        elif net < -0.005:
            lines.append({'account_code': sales_acc, 'debit': round(-net, 2), 'credit': 0.0, 'remarks': 'POS sales refund'})

    if str((meta or {}).get('settlement_amount_source') or '').strip().lower() == 'counted':
        _balance_pos_settlement_with_short_excess(lines, accounts)

    tdr = sum(float(ln.get('debit') or 0) for ln in lines)
    tcr = sum(float(ln.get('credit') or 0) for ln in lines)
    if round(tdr - tcr, 2) != 0:
        raise ValueError(f'POS settlement journal not balanced internally (dr={tdr}, cr={tcr}).')
    if len(lines) < 2:
        raise ValueError('POS settlement journal requires at least two lines.')
    return lines


def _pos_settlement_revenue_total(totals: Dict[str, Any], tender_total: float) -> float:
    """Use discounted settlement value when legacy BILLHDR net still includes the discount."""
    try:
        net = float(totals.get('net') or 0)
    except (TypeError, ValueError):
        net = 0.0
    try:
        discount = float(totals.get('discount') or 0)
    except (TypeError, ValueError):
        discount = 0.0
    try:
        tender = float(tender_total or 0)
    except (TypeError, ValueError):
        tender = 0.0
    if abs((net - tender) - discount) <= 0.01:
        return round(tender, 2)
    return round(net, 2)


def _pos_meta_float(meta: Optional[Dict[str, Any]], key: str) -> float:
    try:
        return float((meta or {}).get(key) or 0)
    except (TypeError, ValueError):
        return 0.0


def _append_pos_settlement_line(lines: List[Dict[str, Any]], account_code: str, amount: float, normal: str, remarks: str) -> None:
    acc = str(account_code or '').strip()[:20]
    amt = round(float(amount or 0), 2)
    if abs(amt) <= 0.005:
        return
    drcr = normal if amt >= 0 else ('Cr' if normal == 'Dr' else 'Dr')
    if drcr == 'Dr':
        lines.append({'account_code': acc, 'debit': abs(amt), 'credit': 0.0, 'remarks': remarks})
    else:
        lines.append({'account_code': acc, 'debit': 0.0, 'credit': abs(amt), 'remarks': remarks})


def _pos_counted_paymode_amounts_from_meta(meta: Optional[Dict[str, Any]]) -> Optional[Dict[str, float]]:
    """Build tender clearing amounts from cashier grid Counted Amount (actual_cash)."""
    rows = (meta or {}).get('cashier_settlement_rows') if isinstance(meta, dict) else None
    if not isinstance(rows, list) or not rows:
        return None
    out: Dict[str, float] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        tender = str(row.get('tender_code') or row.get('tender_type') or '').strip().upper()
        if not tender:
            continue
        if tender in ('VISA', 'MC', 'AMEX', 'MAESTRO', 'RUPAY'):
            tender = 'CARD'
        try:
            actual = float(row.get('actual_cash') or 0)
        except (TypeError, ValueError):
            actual = 0.0
        if tender == 'CASH':
            try:
                opening = float(row.get('opening_cash') or 0)
            except (TypeError, ValueError):
                opening = 0.0
            amt = actual - opening
        else:
            amt = actual
        if abs(amt) <= 0.0005:
            continue
        out[tender] = out.get(tender, 0.0) + amt
    # Empty dict = rows present but all counted amounts are zero (still use counted source).
    return out


def _balance_pos_settlement_with_short_excess(lines: List[Dict[str, Any]], accounts: Dict[str, Any]) -> None:
    """Plug remaining Dr/Cr gap to short (Dr) or excess (Cr) after counted tender lines + sales."""
    tdr = sum(float(ln.get('debit') or 0) for ln in lines)
    tcr = sum(float(ln.get('credit') or 0) for ln in lines)
    diff = round(tdr - tcr, 2)
    if abs(diff) <= 0.005:
        return
    short_acc = str((accounts or {}).get('short_acc') or '').strip()[:20]
    excess_acc = str((accounts or {}).get('excess_acc') or '').strip()[:20]
    if diff < 0:
        if not short_acc:
            raise ValueError('Counted totals are less than sales: select a short account.')
        _append_pos_settlement_line(lines, short_acc, -diff, 'Dr', 'POS cash short')
    else:
        if not excess_acc:
            raise ValueError('Counted totals exceed sales: select an excess account.')
        _append_pos_settlement_line(lines, excess_acc, diff, 'Cr', 'POS cash excess')


def _apply_pos_cash_settlement_adjustments(
    lines: List[Dict[str, Any]],
    *,
    cash_acc: str,
    accounts: Dict[str, Any],
    meta: Optional[Dict[str, Any]],
) -> None:
    """Split cash into counted cash, cashier expenses, short, and excess without changing net sales."""
    expenses = max(0.0, _pos_meta_float(meta, 'expenses'))
    variance = _pos_meta_float(meta, 'cash_variance_sum')
    counted_source = str((meta or {}).get('settlement_amount_source') or '').strip().lower() == 'counted'

    # Counted-amount journals already use grid counts for tenders; only add expenses here.
    # Short/excess is plugged after sales in _balance_pos_settlement_with_short_excess.
    if counted_source:
        if abs(expenses) <= 0.005:
            return
        expense_acc = str((accounts or {}).get('expense_acc') or '').strip()[:20]
        if not expense_acc:
            raise ValueError('Cashier expenses are non-zero: select an expense account.')
        _append_pos_settlement_line(lines, expense_acc, expenses, 'Dr', 'POS cashier expenses')
        return

    if abs(expenses) <= 0.005 and abs(variance) <= 0.005:
        return

    cash_acc = str(cash_acc or '').strip()[:20]
    expense_acc = str((accounts or {}).get('expense_acc') or '').strip()[:20]
    short_acc = str((accounts or {}).get('short_acc') or '').strip()[:20]
    excess_acc = str((accounts or {}).get('excess_acc') or '').strip()[:20]
    short_amt = abs(variance) if variance < -0.005 else 0.0
    excess_amt = variance if variance > 0.005 else 0.0
    if abs(expenses) > 0.005 and not expense_acc:
        raise ValueError('Cashier expenses are non-zero: select an expense account.')
    if abs(short_amt) > 0.005 and not short_acc:
        raise ValueError('Cash short is non-zero: select a short account.')
    if abs(excess_amt) > 0.005 and not excess_acc:
        raise ValueError('Cash excess is non-zero: select an excess account.')

    cash_net = 0.0
    keep: List[Dict[str, Any]] = []
    for ln in lines:
        acc = str(ln.get('account_code') or '').strip()[:20]
        rem = str(ln.get('remarks') or '').lower()
        if cash_acc and acc == cash_acc and 'cash' in rem:
            cash_net += float(ln.get('debit') or 0) - float(ln.get('credit') or 0)
        else:
            keep.append(ln)
    lines[:] = keep
    if not cash_acc and abs(cash_net - expenses + variance) > 0.005:
        raise ValueError('Cash amount is non-zero: select the cash GL account.')
    _append_pos_settlement_line(lines, cash_acc, cash_net - expenses + variance, 'Dr', 'POS counted cash')
    _append_pos_settlement_line(lines, expense_acc, expenses, 'Dr', 'POS cashier expenses')
    _append_pos_settlement_line(lines, short_acc, short_amt, 'Dr', 'POS cash short')
    _append_pos_settlement_line(lines, excess_acc, excess_amt, 'Cr', 'POS cash excess')


def _pos_settlement_default_sales_account_code() -> str:
    """Revenue GL for POS settlement journals (default ``4100``); override with env ``POS_SETTLEMENT_SALES_ACCOUNT``."""
    raw = (os.getenv('POS_SETTLEMENT_SALES_ACCOUNT') or '').strip()
    return raw[:20] if raw else '4100'


def get_pos_settlement_account_defaults_from_tenders() -> Dict[str, Any]:
    """Clearing GL codes from **active** POS tender rows (first row with GL per bucket, ``SORT_ORDER`` then code).

    Includes ``*_clearing`` metadata so the settlement UI can show which tender drove each account.
    Non-tender settlement accounts are loaded from POS Accounts Configuration.
    """
    cfg = get_pos_settlement_account_config()
    sales_acc = (cfg.get('SALES_REVENUE') or {}).get('account_code') or _pos_settlement_default_sales_account_code()
    out: Dict[str, Any] = {
        'cash_acc': '',
        'card_acc': '',
        'wallet_acc': '',
        'credit_acc': '',
        'sales_acc': sales_acc,
        'tax_acc': (cfg.get('TAX') or {}).get('account_code') or '',
        'expense_acc': (cfg.get('EXPENSE') or {}).get('account_code') or '',
        'short_acc': (cfg.get('SHORT') or {}).get('account_code') or '',
        'excess_acc': (cfg.get('EXCESS') or {}).get('account_code') or '',
        'cash_clearing': None,
        'card_clearing': None,
        'wallet_clearing': None,
        'credit_clearing': None,
        'settlement_config': cfg,
    }
    meta_for_bucket = {
        'cash_acc': 'cash_clearing',
        'card_acc': 'card_clearing',
        'wallet_acc': 'wallet_clearing',
        'credit_acc': 'credit_clearing',
    }
    if not ensure_pos_tender_type_table():
        return out
    rows = list_pos_tender_types(active_only=True)
    buckets_seen = {'cash_acc': False, 'card_acc': False, 'wallet_acc': False, 'credit_acc': False}

    def bucket_for_category(cat: str, code: str) -> Optional[str]:
        c = (cat or '').strip().upper()
        cd = (code or '').strip().upper()
        if cd == 'CREDIT' or c == 'CREDIT':
            return 'credit_acc'
        if c == 'CASH' or cd == 'CASH':
            return 'cash_acc'
        if c == 'CARD':
            return 'card_acc'
        if c in ('WALLET', 'VOUCHER', 'UPI', 'ONLINE') or cd in ('UPI', 'WALLET', 'VOUCHER'):
            return 'wallet_acc'
        return None

    for tr in rows:
        tc = str(tr.get('tender_code') or '').strip().upper()
        cat = str(tr.get('category') or '').strip()
        gl = str(tr.get('gl_account_code') or '').strip()
        if not gl:
            continue
        b = bucket_for_category(cat, tc)
        if not b or buckets_seen.get(b):
            continue
        code_gl = gl[:20]
        out[b] = code_gl
        mk = meta_for_bucket.get(b)
        if mk:
            out[mk] = {
                'tender_code': tc,
                'tender_name': str(tr.get('tender_name') or '').strip(),
                'category': cat,
                'gl_account_code': code_gl,
            }
        buckets_seen[b] = True
    return out


def get_pos_tender_gl_by_code(*, active_only: bool = True) -> Dict[str, str]:
    """Map ``POS_TENDER_TYPE.TENDER_CODE`` → ``GL_ACCOUNT_CODE`` for settlement preview/posting."""
    out: Dict[str, str] = {}
    if not ensure_pos_tender_type_table():
        return out
    for tr in list_pos_tender_types(active_only=active_only):
        tc = str(tr.get('tender_code') or '').strip().upper()
        gl = str(tr.get('gl_account_code') or '').strip()[:20]
        if tc and gl:
            out[tc] = gl
    return out


def _sales_cash_direct_post_debit_lines(
    *,
    payment_mode_rows: List[Dict[str, Any]],
    header: Dict[str, Any],
    total_amt: float,
    receivable_fallback: str,
) -> Tuple[List[Dict[str, Any]], Optional[str]]:
    """Build Dr (invoice) / Cr (return) lines for cash direct posting by payment method.

    Returns ``(lines, error)``. Each line: ``account_code``, ``amount``, ``tender_code``, ``remarks``.
    Uses POS tender GL mapping (Cash → cash GL, Card/Visa → bank/card GL, etc.).
    """
    tender_gl = get_pos_tender_gl_by_code(active_only=False)
    # Seed defaults if tender master empty / missing codes
    seed_gl = {
        str(r.get('tender_code') or '').strip().upper(): str(r.get('gl_account_code') or '').strip()[:20]
        for r in POS_TENDER_TYPE_SEED_ROWS
        if str(r.get('tender_code') or '').strip() and str(r.get('gl_account_code') or '').strip()
    }

    def _gl_for(code: str) -> str:
        c = (code or '').strip().upper()
        return (tender_gl.get(c) or seed_gl.get(c) or '').strip()[:20]

    amounts: Dict[str, float] = {}
    for row in payment_mode_rows or []:
        if not isinstance(row, dict):
            continue
        code = str(row.get('code') or row.get('paymode') or '').strip().upper()
        if not code or code == 'CREDIT':
            continue
        try:
            amt = abs(float(row.get('amount') or 0))
        except (TypeError, ValueError):
            amt = 0.0
        if amt < 0.005:
            continue
        amounts[code] = round(amounts.get(code, 0.0) + amt, 2)

    if not amounts:
        try:
            cash_a = abs(float(header.get('cashamount') or 0))
        except (TypeError, ValueError):
            cash_a = 0.0
        try:
            card_a = abs(float(header.get('cardamount') or 0))
        except (TypeError, ValueError):
            card_a = 0.0
        try:
            wallet_a = abs(float(header.get('walletamount') or 0))
        except (TypeError, ValueError):
            wallet_a = 0.0
        try:
            loyalty_a = abs(float(header.get('loyaltyamount') or header.get('loyalty_amount') or 0))
        except (TypeError, ValueError):
            loyalty_a = 0.0
        try:
            points_a = abs(float(header.get('pointsamount') or header.get('points_amount') or 0))
        except (TypeError, ValueError):
            points_a = 0.0
        if cash_a >= 0.005:
            amounts['CASH'] = round(cash_a, 2)
        if card_a >= 0.005:
            amounts['CARD'] = round(card_a, 2)
        if wallet_a >= 0.005:
            amounts['WALLET'] = round(wallet_a, 2)
        if loyalty_a >= 0.005:
            amounts['LOYALTY'] = round(loyalty_a, 2)
        if points_a >= 0.005:
            amounts['POINTS'] = round(points_a, 2)

    target = round(abs(float(total_amt or 0)), 2)
    if not amounts and target >= 0.005:
        amounts['CASH'] = target

    if not amounts:
        return ([], None)

    missing: List[str] = []
    lines: List[Dict[str, Any]] = []
    for code, amt in amounts.items():
        gl = _gl_for(code)
        if not gl:
            missing.append(code)
            continue
        lines.append({
            'account_code': gl,
            'amount': round(amt, 2),
            'tender_code': code,
            'remarks': f'{code} tender',
        })
    if missing:
        return (
            [],
            'Direct posting is enabled but these payment methods have no GL account: '
            + ', '.join(sorted(missing))
            + '. Set GL on POS Tender Types (or disable Direct posting in Sales Accounts Configuration).',
        )

    paid = round(sum(float(x['amount']) for x in lines), 2)
    diff = round(target - paid, 2)
    if abs(diff) >= 0.02:
        cash_gl = _gl_for('CASH') or (receivable_fallback or '').strip()[:20]
        if not cash_gl:
            return (
                [],
                f'Direct posting payment total {paid:.2f} does not match invoice {target:.2f} '
                'and no Cash / Receivable GL is available for the difference.',
            )
        # Merge remainder into an existing CASH line when possible
        merged = False
        for ln in lines:
            if str(ln.get('tender_code') or '').upper() == 'CASH' and cash_gl == ln.get('account_code'):
                ln['amount'] = round(float(ln['amount']) + diff, 2)
                merged = True
                break
        if not merged:
            lines.append({
                'account_code': cash_gl,
                'amount': abs(diff),
                'tender_code': 'CASH' if cash_gl == _gl_for('CASH') else 'ADJ',
                'remarks': 'Rounding / remainder',
            })
        # Drop zero/negative after merge
        lines = [ln for ln in lines if float(ln.get('amount') or 0) >= 0.005]

    # Collapse same account+tender
    collapsed: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for ln in lines:
        key = (str(ln['account_code']), str(ln.get('tender_code') or ''))
        if key in collapsed:
            collapsed[key]['amount'] = round(float(collapsed[key]['amount']) + float(ln['amount']), 2)
        else:
            collapsed[key] = dict(ln)
    return (list(collapsed.values()), None)


def ensure_billhdr_pos_settlement_columns() -> None:
    """Ensure ``BILLHDR`` has POS settlement workflow columns (tenant DB)."""
    try:
        if not _table_exists('BILLHDR'):
            return
        cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
        specs = [('POS_SETTLEMENT_STATUS', 'VARCHAR2(20)'), ('POS_SETTLEMENT_VOUCHER_NO', 'VARCHAR2(40)'), ('POS_SETTLEMENT_NOTE', 'VARCHAR2(500)')]
        if all(name in cols_u for name, _ in specs):
            return
        changed = False
        with _get_connection() as conn:
            with conn.cursor() as cur:
                for name, ddl in specs:
                    if name in cols_u:
                        continue
                    try:
                        cur.execute(f'ALTER TABLE BILLHDR ADD ({name} {ddl})')
                        changed = True
                        cols_u.add(name)
                    except Exception as ex:
                        msg = str(ex).upper()
                        if 'ORA-01430' in msg or 'ORA-00955' in msg or 'ORA-01442' in msg or 'ORA-04021' in msg:
                            cols_u.add(name)
                        else:
                            print(f'[WARN ensure_billhdr_pos_settlement_columns] {name}: {ex}')
                if changed:
                    try:
                        cur.execute("UPDATE BILLHDR SET POS_SETTLEMENT_STATUS = 'PENDING' WHERE POS_SETTLEMENT_STATUS IS NULL")
                    except Exception:
                        pass
            conn.commit()
        try:
            _TABLE_COLUMNS_CACHE.pop('BILLHDR', None)
        except Exception:
            pass
    except Exception as e:
        print(f'[WARN ensure_billhdr_pos_settlement_columns] {e}')


def update_billhdr_pos_settlement_posting(
    location_code: int,
    bill_nos: List[Any],
    *,
    status: str,
    voucher_no: str = '',
    remarks: str = '',
    conn: Optional[Any] = None,
    commit: bool = True,
) -> Tuple[bool, str]:
    """Update POS settlement columns on ``BILLHDR`` for listed bills."""
    ensure_billhdr_pos_settlement_columns()
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    if 'POS_SETTLEMENT_STATUS' not in cols_u:
        return (False, 'BILLHDR does not have POS_SETTLEMENT_STATUS.')
    clean_nos = _clean_settlement_billnos(bill_nos)
    if not clean_nos:
        return (False, 'No valid bill numbers.')
    st = str(status or '').strip().upper()[:20]
    if st not in ('PENDING', 'SETTLED', 'CANCELLED'):
        return (False, 'Invalid settlement status.')
    vn = None if st == 'PENDING' else (str(voucher_no or '').strip()[:40] or None)
    note = str(remarks or '').strip()[:500] or None
    placeholders = ','.join([f':b{i}' for i in range(len(clean_nos))])
    params: Dict[str, Any] = {'loc': int(location_code), 'st': st, 'vn': vn, 'note': note}
    for i, bn in enumerate(clean_nos):
        params[f'b{i}'] = bn
    q = f'\n        UPDATE BILLHDR SET POS_SETTLEMENT_STATUS = :st,\n            POS_SETTLEMENT_VOUCHER_NO = :vn,\n            POS_SETTLEMENT_NOTE = :note\n        WHERE LOCATIONCODE = :loc AND BILLNO IN ({placeholders})\n    '
    try:
        if conn is not None:
            with conn.cursor() as cur:
                cur.execute(q, params)
                rc = cur.rowcount
            if commit:
                conn.commit()
        else:
            with _get_connection() as conn2:
                with conn2.cursor() as cur:
                    cur.execute(q, params)
                    rc = cur.rowcount
                conn2.commit()
        if commit:
            try:
                _TABLE_COLUMNS_CACHE.pop('BILLHDR', None)
            except Exception:
                pass
        if not rc:
            return (False, 'No bills were updated (wrong branch or bill numbers).')
        return (True, '')
    except Exception as e:
        return (False, str(e))


def ensure_pos_settlement_draft_tables() -> bool:
    """Tenant tables for POS settlement draft → verify → GL post workflow."""
    hdr = POS_SETTLEMENT_DRAFT_HDR_TABLE
    bill_tbl = POS_SETTLEMENT_DRAFT_BILL_TABLE
    try:
        seq_name = 'POS_SETTLEMENT_DRAFT_SEQ'
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f"SELECT 1 FROM user_sequences WHERE sequence_name = '{seq_name}'")
                if cur.fetchone() is None:
                    cur.execute(f'CREATE SEQUENCE {seq_name} START WITH 1 INCREMENT BY 1 NOCACHE')
                if not _table_exists(hdr):
                    cur.execute(
                        f"""
                        CREATE TABLE {hdr} (
                            DRAFT_ID NUMBER NOT NULL,
                            LOCATIONCODE NUMBER NOT NULL,
                            STATUS VARCHAR2(20) DEFAULT 'DRAFT' NOT NULL,
                            VOUCHER_NO VARCHAR2(40),
                            VOUCHER_DATE VARCHAR2(10),
                            REFERENCE_NO VARCHAR2(50),
                            NARRATION VARCHAR2(500),
                            META_JSON CLOB,
                            JOURNAL_LINES_JSON CLOB,
                            CREATED_BY VARCHAR2(100),
                            CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
                            VERIFIED_AT TIMESTAMP,
                            POSTED_AT TIMESTAMP,
                            CONSTRAINT PK_PSSD_HDR PRIMARY KEY (DRAFT_ID)
                        )
                        """
                    )
                    try:
                        cur.execute(f'CREATE INDEX IDX_PSSD_HDR ON {hdr} (LOCATIONCODE, CREATED_AT DESC)')
                    except Exception:
                        pass
                if not _table_exists(bill_tbl):
                    billno_col = (
                        f'BILLNO VARCHAR2({_BILLNO_VARCHAR_LEN}) NOT NULL'
                        if billno_uses_varchar_storage()
                        else 'BILLNO NUMBER NOT NULL'
                    )
                    cur.execute(
                        f"""
                        CREATE TABLE {bill_tbl} (
                            DRAFT_ID NUMBER NOT NULL,
                            {billno_col},
                            CONSTRAINT PK_PSSD_BILL PRIMARY KEY (DRAFT_ID, BILLNO),
                            CONSTRAINT FK_PSSD_BILL_REF FOREIGN KEY (DRAFT_ID) REFERENCES {hdr}(DRAFT_ID) ON DELETE CASCADE
                        )
                        """
                    )
                    try:
                        cur.execute(f'CREATE INDEX IDX_PSSD_BILL ON {bill_tbl} (BILLNO)')
                    except Exception:
                        pass
            conn.commit()
        try:
            _TABLE_EXISTS_CACHE.pop(hdr, None)
            _TABLE_COLUMNS_CACHE.pop(hdr, None)
            _TABLE_EXISTS_CACHE.pop(bill_tbl, None)
            _TABLE_COLUMNS_CACHE.pop(bill_tbl, None)
        except Exception:
            pass
        return True
    except Exception as e:
        print(f'[ERROR ensure_pos_settlement_draft_tables] {e}')
        return False


def _aggregate_pos_settlement_totals_from_billhdr_rows(raw_rows: List[Dict[str, Any]]) -> Dict[str, float]:
    cash = card = wallet = credit = 0.0
    net_total = tax_total = disc_total = 0.0
    for r in raw_rows or []:
        rk = {str(k).lower(): v for k, v in r.items()}

        def _f(key: str) -> float:
            try:
                return float(rk.get(key) or 0)
            except (TypeError, ValueError):
                return 0.0

        net = _f('netbillamount')
        disc = _f('discountamount')
        tax = _f('taxamount') + _f('vatamount') + _f('vat')
        cash_amt = _f('cashamount')
        card_amt = _f('cardamount')
        wallet_amt = _f('walletamount') + _f('onlineamount')
        credit_amt = _f('creditamount')
        bt = str(rk.get('billtype') or '').strip().upper()
        bt_key = bt[:1] if bt else ''
        if bt_key == 'R':
            if credit_amt <= 0:
                credit_amt = net
            cash_amt = card_amt = wallet_amt = 0.0
        elif not (cash_amt or card_amt or wallet_amt or credit_amt):
            pay_txt = (str(rk.get('paymentmode') or rk.get('paymode') or rk.get('paytype') or '') + ' ').lower()
            if 'card' in pay_txt:
                card_amt = net
            elif 'wallet' in pay_txt or 'online' in pay_txt:
                wallet_amt = net
            elif 'credit' in pay_txt:
                credit_amt = net
            elif 'mixed' in pay_txt:
                cash_amt = net * 0.5
                card_amt = net * 0.5
            else:
                cash_amt = net
        else:
            bucket_sum = cash_amt + card_amt + wallet_amt + credit_amt
            if abs(bucket_sum - net) > 0.01:
                cash_amt += net - bucket_sum
        cash += cash_amt
        card += card_amt
        wallet += wallet_amt
        credit += credit_amt
        net_total += net
        tax_total += tax
        disc_total += disc
    return {
        'cash': round(cash, 2),
        'card': round(card, 2),
        'wallet': round(wallet, 2),
        'credit': round(credit, 2),
        'net': round(net_total, 2),
        'tax': round(tax_total, 2),
        'discount': round(disc_total, 2),
    }


def build_pos_settlement_gl_lines(
    totals: Dict[str, Any],
    *,
    cash_acc: str,
    card_acc: str,
    wallet_acc: str,
    credit_acc: str,
    sales_acc: str,
    tax_acc: str,
    accounts: Optional[Dict[str, Any]] = None,
    meta: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    """Balanced journal lines for POS settlement (matches settlement UI logic).

    Supports **negative net** (returns/refunds): clearing accounts are credited for outflows,
    sales/tax are debited when amounts are negative.

    When ``credit_acc`` is empty, credit-POS tender totals are folded into the card clearing line
    (same behaviour as the settlement UI).
    """
    cash_acc = str(cash_acc or '').strip()[:20]
    card_acc = str(card_acc or '').strip()[:20]
    wallet_acc = str(wallet_acc or '').strip()[:20]
    credit_acc = str(credit_acc or '').strip()[:20]
    sales_acc = str(sales_acc or '').strip()[:20]
    tax_acc = str(tax_acc or '').strip()[:20]
    ca = float(totals.get('cash') or 0)
    cd = float(totals.get('card') or 0)
    wa = float(totals.get('wallet') or 0)
    cr = float(totals.get('credit') or 0)
    tender_total = ca + cd + wa + cr
    net = _pos_settlement_revenue_total(totals, tender_total)
    tax = float(totals.get('tax') or 0)
    if abs(wa) > 0.005 and not wallet_acc:
        raise ValueError('Wallet/UPI amount is non-zero: select a wallet clearing account.')
    if abs(cr) > 0.005 and not credit_acc:
        cd += cr
        cr = 0.0

    lines: List[Dict[str, Any]] = []

    def add_tender(acc: str, amt: float, label: str) -> None:
        """Positive tender = cash/card in (DR clearing); negative = refund out (CR clearing)."""
        if amt > 0.005:
            if not acc:
                raise ValueError(f'Amount on {label}: select the matching GL account.')
            lines.append({'account_code': acc, 'debit': round(amt, 2), 'credit': 0.0, 'remarks': f'POS {label}'})
        elif amt < -0.005:
            if not acc:
                raise ValueError(f'Refund on {label}: select the matching GL account.')
            lines.append({'account_code': acc, 'debit': 0.0, 'credit': round(-amt, 2), 'remarks': f'POS {label} refund'})

    add_tender(cash_acc, ca, 'cash')
    add_tender(card_acc, cd, 'card')
    add_tender(wallet_acc, wa, 'wallet')
    add_tender(credit_acc, cr, 'credit')
    adjustment_accounts = dict(accounts or {})
    adjustment_accounts.setdefault('cash_acc', cash_acc)
    _apply_pos_cash_settlement_adjustments(lines, cash_acc=cash_acc, accounts=adjustment_accounts, meta=meta)

    base = round(net - tax, 2)
    if tax > 0.005 or tax < -0.005:
        if not tax_acc:
            raise ValueError('Tax amount is non-zero: select a tax account.')
        if not sales_acc:
            raise ValueError('Select a sales account.')
        if base > 0.005:
            lines.append({'account_code': sales_acc, 'debit': 0.0, 'credit': base, 'remarks': 'POS sales'})
        elif base < -0.005:
            lines.append({'account_code': sales_acc, 'debit': round(-base, 2), 'credit': 0.0, 'remarks': 'POS sales refund'})
        if tax > 0.005:
            lines.append({'account_code': tax_acc, 'debit': 0.0, 'credit': round(tax, 2), 'remarks': 'POS tax'})
        elif tax < -0.005:
            lines.append({'account_code': tax_acc, 'debit': round(-tax, 2), 'credit': 0.0, 'remarks': 'POS tax reversal'})
    else:
        if not sales_acc:
            raise ValueError('Select a sales account.')
        if net > 0.005:
            lines.append({'account_code': sales_acc, 'debit': 0.0, 'credit': round(net, 2), 'remarks': 'POS sales'})
        elif net < -0.005:
            lines.append({'account_code': sales_acc, 'debit': round(-net, 2), 'credit': 0.0, 'remarks': 'POS sales refund'})

    tdr = sum(float(ln.get('debit') or 0) for ln in lines)
    tcr = sum(float(ln.get('credit') or 0) for ln in lines)
    if round(tdr - tcr, 2) != 0:
        raise ValueError(f'POS settlement journal not balanced internally (dr={tdr}, cr={tcr}).')
    if len(lines) < 2:
        raise ValueError('POS settlement journal requires at least two lines.')
    return lines


def _fetch_billhdr_rows_by_billnos(location_code: int, bill_nos: List[Any]) -> List[Dict[str, Any]]:
    """Load BILLHDR rows by bill number only (used when opening an existing draft)."""
    ensure_billhdr_pos_settlement_columns()
    clean = _clean_settlement_billnos(bill_nos)
    if not clean:
        return []
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    if 'BILLNO' not in cols_u or 'LOCATIONCODE' not in cols_u:
        return []
    placeholders = ','.join([f':b{i}' for i in range(len(clean))])
    params: Dict[str, Any] = {'loc': int(location_code)}
    for i, bn in enumerate(clean):
        params[f'b{i}'] = bn
    q = f'SELECT * FROM BILLHDR WHERE LOCATIONCODE = :loc AND BILLNO IN ({placeholders})'
    return _safe_rows(q, params) or []


def _fetch_billhdr_rows_for_pos_settlement(location_code: int, bill_nos: List[Any]) -> List[Dict[str, Any]]:
    ensure_billhdr_pos_settlement_columns()
    clean = _clean_settlement_billnos(bill_nos)
    if not clean:
        return []
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    if 'BILLNO' not in cols_u or 'LOCATIONCODE' not in cols_u:
        return []
    placeholders = ','.join([f':b{i}' for i in range(len(clean))])
    params: Dict[str, Any] = {'loc': int(location_code)}
    for i, bn in enumerate(clean):
        params[f'b{i}'] = bn
    extra_where = ''
    if 'BILLTYPE' in cols_u and 'CUSTOMERCODE' in cols_u:
        extra_where = " AND NOT (UPPER(NVL(TRIM(TO_CHAR(BILLTYPE)), ' ')) = 'R' AND NVL(CUSTOMERCODE, 0) > 0)"
    elif 'BILLTYPE' in cols_u:
        extra_where = " AND UPPER(NVL(TRIM(TO_CHAR(BILLTYPE)), ' ')) <> 'R'"
    q = f'SELECT * FROM BILLHDR WHERE LOCATIONCODE = :loc AND BILLNO IN ({placeholders}){extra_where}'
    return _safe_rows(q, params) or []


def _cancel_open_pos_settlement_drafts_for_bills(
    location_code: int,
    bill_nos: List[Any],
    *,
    except_draft_id: Optional[int] = None,
    conn: Any = None,
) -> int:
    """Cancel open (DRAFT/VERIFIED) settlements that include any of the given bills."""
    if not ensure_pos_settlement_draft_tables():
        return 0
    clean = _clean_settlement_billnos(bill_nos)
    if not clean:
        return 0
    hdr = POS_SETTLEMENT_DRAFT_HDR_TABLE
    bill_tbl = POS_SETTLEMENT_DRAFT_BILL_TABLE
    placeholders = ','.join([f':b{i}' for i in range(len(clean))])
    params: Dict[str, Any] = {'loc': int(location_code)}
    for i, bn in enumerate(clean):
        params[f'b{i}'] = bn
    except_sql = ''
    if except_draft_id is not None:
        except_sql = ' AND h.DRAFT_ID <> :ex'
        params['ex'] = int(except_draft_id)
    q = f"""
        UPDATE {hdr} h
        SET STATUS = 'CANCELLED'
        WHERE h.LOCATIONCODE = :loc
          AND h.STATUS IN ('DRAFT', 'VERIFIED')
          {except_sql}
          AND EXISTS (
              SELECT 1 FROM {bill_tbl} b
              WHERE b.DRAFT_ID = h.DRAFT_ID
                AND b.BILLNO IN ({placeholders})
          )
    """

    def _run(cur: Any) -> int:
        cur.execute(q, params)
        return int(cur.rowcount or 0)

    if conn is not None:
        with conn.cursor() as cur:
            return _run(cur)
    try:
        with _get_connection() as own:
            with own.cursor() as cur:
                n = _run(cur)
            own.commit()
            return n
    except Exception:
        return 0


def _cleanup_stale_open_pos_settlement_drafts(location_code: int) -> int:
    """Cancel open drafts that no longer have any pending BILLHDR bills (e.g. already posted elsewhere)."""
    if not ensure_pos_settlement_draft_tables():
        return 0
    ensure_billhdr_pos_settlement_columns()
    hdr = POS_SETTLEMENT_DRAFT_HDR_TABLE
    bill_tbl = POS_SETTLEMENT_DRAFT_BILL_TABLE
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    if 'POS_SETTLEMENT_STATUS' not in cols_u:
        return 0
    q = f"""
        UPDATE {hdr} h
        SET STATUS = 'CANCELLED'
        WHERE h.LOCATIONCODE = :loc
          AND h.STATUS IN ('DRAFT', 'VERIFIED')
          AND NOT EXISTS (
              SELECT 1
              FROM {bill_tbl} b
              JOIN BILLHDR bh
                ON bh.LOCATIONCODE = h.LOCATIONCODE
               AND bh.BILLNO = b.BILLNO
              WHERE b.DRAFT_ID = h.DRAFT_ID
                AND NVL(bh.POS_SETTLEMENT_STATUS, 'PENDING') = 'PENDING'
          )
    """
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(q, {'loc': int(location_code)})
                n = int(cur.rowcount or 0)
            conn.commit()
            return n
    except Exception:
        return 0


def create_pos_settlement_draft(
    location_code: int,
    bill_nos: List[Any],
    *,
    accounts: Dict[str, Any],
    meta: Optional[Dict[str, Any]] = None,
    created_by: str = '',
) -> Tuple[bool, str, Optional[int]]:
    """Persist a draft settlement with computed GL lines. Bills must be POS-settlement pending."""
    if not ensure_pos_settlement_draft_tables():
        return (False, 'POS settlement draft tables are not available.', None)
    ensure_billhdr_pos_settlement_columns()
    try:
        ensure_billno_varchar_columns()
    except Exception:
        pass
    clean_nos = _clean_settlement_billnos(bill_nos)
    if not clean_nos:
        return (False, 'No valid bill numbers.', None)
    # Replace prior open drafts for the same bills so Open drafts stays clean.
    _cancel_open_pos_settlement_drafts_for_bills(location_code, clean_nos)
    rows = _fetch_billhdr_rows_for_pos_settlement(location_code, clean_nos)
    if len(rows) != len(clean_nos):
        return (False, 'Some bills were not found or are not eligible for POS settlement.', None)
    account_defaults = get_pos_settlement_account_defaults_from_tenders()
    effective_accounts = dict(account_defaults or {})
    # Expense config is a parent/control account; settlement must submit the actual expense sub account.
    effective_accounts.pop('expense_acc', None)
    for k, v in dict(accounts or {}).items():
        if str(v or '').strip():
            effective_accounts[k] = v
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        st = str(rk.get('pos_settlement_status') or 'PENDING').strip().upper()
        if st != 'PENDING':
            bn = rk.get('billno')
            return (False, f'Bill {bn} is not pending settlement (status={st or "?" }).')
    totals = _aggregate_pos_settlement_totals_from_billhdr_rows(rows)
    paymode_totals = fetch_pos_paymode_totals_for_bills(location_code, clean_nos)
    all_have_paymode = pos_settlement_bills_have_paymode_rows(location_code, clean_nos)
    tender_table_ok = ensure_pos_tender_type_table()
    meta_journal_source = 'billhdr_aggregate'
    pm_amounts_for_meta: Dict[str, float] = {}
    meta_payload = dict(meta or {})
    lines: List[Dict[str, Any]]
    try:
        if tender_table_ok:
            tender_list = list_pos_tender_types(active_only=True)
            if paymode_totals and all_have_paymode and pos_settlement_paymode_totals_reconcile(totals, paymode_totals):
                pm_amounts_for_meta = dict(paymode_totals)
                meta_journal_source = 'paymode_tender_map'
            else:
                pm_amounts_for_meta = _merge_pos_shift_tender_totals(location_code, rows, clean_nos)
                if not pm_amounts_for_meta:
                    pm_amounts_for_meta = paymode_amounts_from_billhdr_settlement_totals(totals)
                    meta_journal_source = 'billhdr_buckets_tender_map'
                elif not pos_settlement_paymode_totals_reconcile(totals, pm_amounts_for_meta):
                    pm_amounts_for_meta = paymode_amounts_from_billhdr_settlement_totals(totals)
                    meta_journal_source = 'billhdr_buckets_tender_map'
                else:
                    meta_journal_source = (
                        'paymode_merged_tender_map' if paymode_totals else 'billhdr_buckets_tender_map'
                    )
            bill_paymode_totals = dict(pm_amounts_for_meta)
            counted_pm = _pos_counted_paymode_amounts_from_meta(meta_payload)
            if counted_pm is not None or str(meta_payload.get('settlement_amount_source') or '').strip().lower() == 'counted':
                meta_payload['settlement_amount_source'] = 'counted'
                meta_payload['bill_paymode_totals'] = bill_paymode_totals
                pm_amounts_for_meta = counted_pm if counted_pm is not None else {}
                meta_journal_source = 'counted_tender_grid'
            lines = build_pos_settlement_gl_lines_from_paymodes(
                totals,
                pm_amounts_for_meta,
                tender_rows=tender_list,
                accounts=effective_accounts,
                meta=meta_payload,
            )
        else:
            lines = build_pos_settlement_gl_lines(
                totals,
                cash_acc=str(effective_accounts.get('cash_acc') or ''),
                card_acc=str(effective_accounts.get('card_acc') or ''),
                wallet_acc=str(effective_accounts.get('wallet_acc') or ''),
                credit_acc=str(effective_accounts.get('credit_acc') or ''),
                sales_acc=str(effective_accounts.get('sales_acc') or ''),
                tax_acc=str(effective_accounts.get('tax_acc') or ''),
                accounts=effective_accounts,
                meta=meta_payload,
            )
    except ValueError as ve:
        return (False, str(ve), None)
    meta_payload['totals'] = totals
    meta_payload['bill_count'] = len(clean_nos)
    meta_payload['journal_source'] = meta_journal_source
    if meta_journal_source in (
        'paymode_tender_map',
        'paymode_merged_tender_map',
        'billhdr_buckets_tender_map',
        'counted_tender_grid',
    ):
        meta_payload['paymode_totals'] = pm_amounts_for_meta
    lines_json = json.dumps(lines, default=str, ensure_ascii=False)
    meta_json = json.dumps(meta_payload, default=str, ensure_ascii=False)
    narration = f'POS settlement draft ({len(clean_nos)} bills, loc {location_code})'
    hdr = POS_SETTLEMENT_DRAFT_HDR_TABLE
    bill_tbl = POS_SETTLEMENT_DRAFT_BILL_TABLE
    ref_no = f'POS-DRAFT-{location_code}-{datetime.now().strftime("%Y%m%d%H%M%S")}'
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute('SELECT POS_SETTLEMENT_DRAFT_SEQ.NEXTVAL FROM DUAL')
                draft_id = int(cur.fetchone()[0])
                meta_var = cur.var(cx_Oracle.CLOB)
                meta_var.setvalue(0, meta_json)
                lines_var = cur.var(cx_Oracle.CLOB)
                lines_var.setvalue(0, lines_json)
                cur.execute(
                    f"""
                    INSERT INTO {hdr} (
                        DRAFT_ID, LOCATIONCODE, STATUS, REFERENCE_NO, NARRATION,
                        META_JSON, JOURNAL_LINES_JSON, CREATED_BY
                    ) VALUES (
                        :did, :loc, 'DRAFT', :ref, :nar,
                        :meta, :jlines, :usr
                    )
                    """,
                    {
                        'did': draft_id,
                        'loc': int(location_code),
                        'ref': ref_no[:50],
                        'nar': narration[:500],
                        'meta': meta_var,
                        'jlines': lines_var,
                        'usr': str(created_by or '').strip()[:100] or None,
                    },
                )
                for bn in clean_nos:
                    cur.execute(
                        f'INSERT INTO {bill_tbl} (DRAFT_ID, BILLNO) VALUES (:d, :b)',
                        {'d': draft_id, 'b': coerce_billno(bn)},
                    )
            conn.commit()
        return (True, '', draft_id)
    except Exception as e:
        return (False, str(e), None)


def list_pos_settlement_pending_by_date(location_code: int, *, limit_days: int = 90) -> List[Dict[str, Any]]:
    """Pending POS bills aggregated by bill date (newest first) for settlement list tab."""
    ensure_billhdr_pos_settlement_columns()
    cols_u = {str(c).upper() for c in (_get_table_columns('BILLHDR') or [])}
    if 'BILLNO' not in cols_u or 'BILLDATE' not in cols_u or 'LOCATIONCODE' not in cols_u:
        return []
    lim = max(1, min(int(limit_days or 90), 366))
    where_parts = ['LOCATIONCODE = :loc']
    params: Dict[str, Any] = {'loc': int(location_code), 'lim': lim}
    if 'DELFLAG' in cols_u:
        where_parts.append("NVL(DELFLAG, 'N') <> 'Y'")
    if 'BILLSTATUS' in cols_u:
        where_parts.append("NVL(BILLSTATUS, ' ') <> 'V'")
    # Match settlement candidate filter: skip on-account credit invoices.
    if 'BILLTYPE' in cols_u and 'CUSTOMERCODE' in cols_u:
        where_parts.append(
            "NOT (UPPER(NVL(TRIM(TO_CHAR(BILLTYPE)), ' ')) = 'R' AND NVL(CUSTOMERCODE, 0) > 0)"
        )
    elif 'BILLTYPE' in cols_u:
        where_parts.append("UPPER(NVL(TRIM(TO_CHAR(BILLTYPE)), ' ')) <> 'R'")
    if 'POS_SETTLEMENT_STATUS' in cols_u:
        where_parts.append(
            "(UPPER(TRIM(NVL(POS_SETTLEMENT_STATUS, 'PENDING'))) IN ('PENDING', '') "
            "OR POS_SETTLEMENT_STATUS IS NULL)"
        )
    amt_expr = 'NVL(NETBILLAMOUNT, 0)' if 'NETBILLAMOUNT' in cols_u else '0'
    where_sql = ' AND '.join(where_parts)
    q = f"""
        SELECT * FROM (
            SELECT TRUNC(BILLDATE) AS BILL_DATE,
                   COUNT(*) AS BILL_COUNT,
                   SUM({amt_expr}) AS NET_AMOUNT
            FROM BILLHDR
            WHERE {where_sql}
            GROUP BY TRUNC(BILLDATE)
            ORDER BY TRUNC(BILLDATE) DESC
        ) WHERE ROWNUM <= :lim
    """
    rows = _safe_rows(q, params) or []
    out: List[Dict[str, Any]] = []
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        bd = rk.get('bill_date')
        if bd is not None and hasattr(bd, 'strftime'):
            try:
                bill_date = bd.strftime('%Y-%m-%d')
            except Exception:
                bill_date = str(bd)[:10]
        else:
            bill_date = str(bd or '')[:10]
        if not bill_date:
            continue
        try:
            net_amount = round(float(rk.get('net_amount') or 0), 2)
        except (TypeError, ValueError):
            net_amount = 0.0
        out.append(
            {
                'bill_date': bill_date,
                'bill_count': int(rk.get('bill_count') or 0),
                'net_amount': net_amount,
            }
        )
    return out


def list_pos_settlement_drafts(location_code: int, *, limit: int = 40) -> List[Dict[str, Any]]:
    if not ensure_pos_settlement_draft_tables():
        return []
    # Drop orphan open drafts whose bills were already settled/posted.
    _cleanup_stale_open_pos_settlement_drafts(location_code)
    hdr = POS_SETTLEMENT_DRAFT_HDR_TABLE
    bill_tbl = POS_SETTLEMENT_DRAFT_BILL_TABLE
    lim = max(1, min(int(limit or 40), 200))
    q = f"""
        SELECT * FROM (
            SELECT h.DRAFT_ID, h.LOCATIONCODE, h.STATUS, h.VOUCHER_NO, h.VOUCHER_DATE, h.REFERENCE_NO,
                   h.NARRATION, h.CREATED_BY, h.CREATED_AT, h.VERIFIED_AT, h.POSTED_AT,
                   (SELECT COUNT(*) FROM {bill_tbl} b WHERE b.DRAFT_ID = h.DRAFT_ID) AS BILL_COUNT
            FROM {hdr} h
            WHERE h.LOCATIONCODE = :loc
              AND h.STATUS <> 'CANCELLED'
            ORDER BY h.CREATED_AT DESC
        ) WHERE ROWNUM <= :lim
    """
    rows = _safe_rows(q, {'loc': int(location_code), 'lim': lim}) or []
    out: List[Dict[str, Any]] = []
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        cat = rk.get('created_at')
        if cat is not None and hasattr(cat, 'strftime'):
            try:
                cat = cat.strftime('%Y-%m-%d %H:%M')
            except Exception:
                cat = str(cat)
        vat = rk.get('verified_at')
        if vat is not None and hasattr(vat, 'strftime'):
            try:
                vat = vat.strftime('%Y-%m-%d %H:%M')
            except Exception:
                vat = str(vat)
        pat = rk.get('posted_at')
        if pat is not None and hasattr(pat, 'strftime'):
            try:
                pat = pat.strftime('%Y-%m-%d %H:%M')
            except Exception:
                pat = str(pat)
        vdate = rk.get('voucher_date')
        if vdate is not None and hasattr(vdate, 'strftime'):
            try:
                vdate = vdate.strftime('%Y-%m-%d')
            except Exception:
                vdate = str(vdate)[:10]
        else:
            vdate = str(vdate or '')[:10]
        out.append(
            {
                'draft_id': int(rk.get('draft_id') or 0),
                'location_code': int(rk.get('locationcode') or 0),
                'status': str(rk.get('status') or ''),
                'voucher_no': str(rk.get('voucher_no') or ''),
                'voucher_date': vdate,
                'reference_no': str(rk.get('reference_no') or ''),
                'narration': str(rk.get('narration') or ''),
                'created_by': str(rk.get('created_by') or ''),
                'created_at': str(cat or ''),
                'verified_at': str(vat or ''),
                'posted_at': str(pat or ''),
                'bill_count': int(rk.get('bill_count') or 0),
            }
        )
    return out


def get_pos_settlement_draft_detail(draft_id: int, location_code: int) -> Optional[Dict[str, Any]]:
    if not ensure_pos_settlement_draft_tables():
        return None
    hdr = POS_SETTLEMENT_DRAFT_HDR_TABLE
    bill_tbl = POS_SETTLEMENT_DRAFT_BILL_TABLE
    did = int(draft_id)
    loc = int(location_code)
    hrows = _safe_rows(
        f'SELECT * FROM {hdr} WHERE DRAFT_ID = :d AND LOCATIONCODE = :loc',
        {'d': did, 'loc': loc},
    )
    if not hrows:
        return None
    h0 = {str(k).lower(): v for k, v in hrows[0].items()}
    brows = _safe_rows(f'SELECT BILLNO FROM {bill_tbl} WHERE DRAFT_ID = :d ORDER BY BILLNO', {'d': did})
    bill_nos = []
    for br in brows or []:
        bk = {str(k).lower(): v for k, v in br.items()}
        bn = coerce_billno(bk.get('billno'))
        if billno_is_valid(bn):
            bill_nos.append(bn)
    lines: List[Any] = []
    meta: Dict[str, Any] = {}
    try:
        lj = h0.get('journal_lines_json')
        if lj is not None and hasattr(lj, 'read'):
            lj = lj.read()
        if isinstance(lj, str) and lj.strip():
            lines = json.loads(lj)
    except Exception:
        lines = []
    try:
        mj = h0.get('meta_json')
        if mj is not None and hasattr(mj, 'read'):
            mj = mj.read()
        if isinstance(mj, str) and mj.strip():
            meta = json.loads(mj)
    except Exception:
        meta = {}
    return {
        'draft_id': did,
        'location_code': loc,
        'status': str(h0.get('status') or ''),
        'voucher_no': str(h0.get('voucher_no') or ''),
        'voucher_date': str(h0.get('voucher_date') or ''),
        'reference_no': str(h0.get('reference_no') or ''),
        'narration': str(h0.get('narration') or ''),
        'bill_nos': bill_nos,
        'journal_lines': lines if isinstance(lines, list) else [],
        'meta': meta,
    }


def verify_pos_settlement_draft(draft_id: int, location_code: int) -> Tuple[bool, str]:
    if not ensure_pos_settlement_draft_tables():
        return (False, 'POS settlement draft tables are not available.')
    existing = get_pos_settlement_draft_detail(int(draft_id), int(location_code))
    if not existing:
        return (False, 'Draft not found.')
    st = str(existing.get('status') or '').strip().upper()
    if st == 'VERIFIED':
        return (True, '')
    if st != 'DRAFT':
        return (False, 'Draft is not in DRAFT status.')
    hdr = POS_SETTLEMENT_DRAFT_HDR_TABLE
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    UPDATE {hdr}
                    SET STATUS = 'VERIFIED', VERIFIED_AT = SYSTIMESTAMP
                    WHERE DRAFT_ID = :d AND LOCATIONCODE = :loc AND STATUS = 'DRAFT'
                    """,
                    {'d': int(draft_id), 'loc': int(location_code)},
                )
                rc = cur.rowcount
            conn.commit()
        if not rc:
            return (False, 'Draft could not be verified (concurrent update?).')
        return (True, '')
    except Exception as e:
        return (False, str(e))


def cancel_pos_settlement_draft(draft_id: int, location_code: int) -> Tuple[bool, str]:
    """Cancel an open (DRAFT/VERIFIED) settlement so its bills stay pending for a new settlement.

    Open drafts never mark their bills as SETTLED, so cancelling only flips the draft to
    CANCELLED — no GL reversal or BILLHDR change is needed. Posted drafts cannot be cancelled
    here (use the GL reverse flow instead).
    """
    if not ensure_pos_settlement_draft_tables():
        return (False, 'POS settlement draft tables are not available.')
    existing = get_pos_settlement_draft_detail(int(draft_id), int(location_code))
    if not existing:
        return (False, 'Draft not found.')
    st = str(existing.get('status') or '').strip().upper()
    if st == 'CANCELLED':
        return (True, '')
    if st == 'POSTED':
        return (False, 'This settlement is already posted. Use reverse GL to undo it.')
    if st not in ('DRAFT', 'VERIFIED'):
        return (False, f'Only open drafts can be cancelled (status={st or "?"}).')
    hdr = POS_SETTLEMENT_DRAFT_HDR_TABLE
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    UPDATE {hdr}
                    SET STATUS = 'CANCELLED'
                    WHERE DRAFT_ID = :d AND LOCATIONCODE = :loc AND STATUS IN ('DRAFT', 'VERIFIED')
                    """,
                    {'d': int(draft_id), 'loc': int(location_code)},
                )
                rc = cur.rowcount
            conn.commit()
        if not rc:
            return (False, 'Draft could not be cancelled (already posted or concurrent update?).')
        return (True, '')
    except Exception as e:
        return (False, str(e))


def post_pos_settlement_draft(
    draft_id: int,
    location_code: int,
    *,
    voucher_date: Optional[str] = None,
    narration_extra: str = '',
    remarks_bills: str = '',
    created_by: str = '',
    dimension_defaults: Optional[Dict[str, Any]] = None,
) -> Tuple[bool, str, Optional[str]]:
    """Atomically post verified draft to GL, update bills, and mark draft POSTED (single DB transaction)."""
    detail = get_pos_settlement_draft_detail(int(draft_id), int(location_code))
    if not detail:
        return (False, 'Draft not found.', None)
    if str(detail.get('status') or '').upper() != 'VERIFIED':
        return (False, 'Draft must be verified before posting.', None)
    bill_nos = _clean_settlement_billnos(detail.get('bill_nos') or [])
    lines = detail.get('journal_lines') or []
    if not isinstance(lines, list) or len(lines) < 2:
        return (False, 'Draft has no valid journal lines.', None)
    if not bill_nos:
        return (False, 'Draft has no valid bill numbers.', None)
    rows = _fetch_billhdr_rows_for_pos_settlement(location_code, bill_nos)
    if len(rows) != len(bill_nos):
        return (False, 'One or more bills are missing or no longer eligible.', None)
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        st = str(rk.get('pos_settlement_status') or 'PENDING').strip().upper()
        if st != 'PENDING':
            return (False, f"Bill {rk.get('billno')} is no longer pending settlement.")
    gl_lines: List[Dict[str, Any]] = []
    for ln in lines:
        if not isinstance(ln, dict):
            continue
        gl_lines.append(
            {
                'account_code': str(ln.get('account_code') or '').strip(),
                'debit': float(ln.get('debit') or 0),
                'credit': float(ln.get('credit') or 0),
                'remarks': str(ln.get('remarks') or '').strip()[:250] or None,
                'cost_center': ln.get('cost_center'),
                'department': ln.get('department'),
                'project': ln.get('project'),
            }
        )
    ref = str(detail.get('reference_no') or '')[:50] or None
    nar_parts = [str(detail.get('narration') or '').strip(), str(narration_extra or '').strip()]
    narration = ' — '.join([p for p in nar_parts if p])[:500] or None
    vdate = voucher_date
    hdr_tbl = POS_SETTLEMENT_DRAFT_HDR_TABLE
    vdt = _to_iso_date(vdate) or datetime.now().strftime('%Y-%m-%d')
    try:
        with _get_connection() as conn:
            try:
                voucher_no = create_gl_journal_entry(
                    vdate,
                    ref,
                    narration,
                    gl_lines,
                    created_by=str(created_by or '').strip()[:50] or None,
                    source='POS_SETTLEMENT',
                    dimension_defaults=dimension_defaults,
                    conn=conn,
                    commit=False,
                )
                ok_b, err_b = update_billhdr_pos_settlement_posting(
                    location_code,
                    bill_nos,
                    status='SETTLED',
                    voucher_no=voucher_no,
                    remarks=remarks_bills,
                    conn=conn,
                    commit=False,
                )
                if not ok_b:
                    conn.rollback()
                    return (False, err_b or 'Bill update failed.', None)
                with conn.cursor() as cur:
                    cur.execute(
                        f"""
                        UPDATE {hdr_tbl}
                        SET STATUS = 'POSTED', VOUCHER_NO = :vn, VOUCHER_DATE = :vd, POSTED_AT = SYSTIMESTAMP,
                            NARRATION = :nar
                        WHERE DRAFT_ID = :d AND LOCATIONCODE = :loc AND STATUS = 'VERIFIED'
                        """,
                        {
                            'vn': voucher_no[:40],
                            'vd': vdt[:10],
                            'nar': narration[:500] if narration else None,
                            'd': int(draft_id),
                            'loc': int(location_code),
                        },
                    )
                    rc_d = cur.rowcount
                if rc_d != 1:
                    conn.rollback()
                    return (False, 'Draft could not be posted (already posted, not verified, or concurrent change).', None)
                # Remove other open drafts that still reference these now-settled bills.
                _cancel_open_pos_settlement_drafts_for_bills(
                    location_code,
                    bill_nos,
                    except_draft_id=int(draft_id),
                    conn=conn,
                )
                conn.commit()
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
                raise
        try:
            _TABLE_COLUMNS_CACHE.pop('BILLHDR', None)
        except Exception:
            pass
        return (True, '', voucher_no)
    except Exception as e:
        return (False, str(e), None)


def reverse_pos_settlement_gl_journal(
    location_code: int,
    bill_nos: List[Any],
    *,
    remarks: str = '',
    created_by: str = '',
    dimension_defaults: Optional[Dict[str, Any]] = None,
) -> Tuple[bool, str, List[str]]:
    """Create reversing GL journals for distinct settlement vouchers and reset bills to pending.

    All reversal journals plus bill updates run in **one** DB transaction (commit once).
    """
    ensure_billhdr_pos_settlement_columns()
    clean_nos: List[int] = []
    for x in bill_nos or []:
        try:
            n = int(x)
            if n > 0:
                clean_nos.append(n)
        except (TypeError, ValueError):
            continue
    clean_nos = sorted(set(clean_nos))
    if not clean_nos:
        return (False, 'No valid bill numbers.', [])
    placeholders = ','.join([f':b{i}' for i in range(len(clean_nos))])
    params: Dict[str, Any] = {'loc': int(location_code)}
    for i, bn in enumerate(clean_nos):
        params[f'b{i}'] = bn
    q = f"""
        SELECT BILLNO, POS_SETTLEMENT_STATUS, POS_SETTLEMENT_VOUCHER_NO
        FROM BILLHDR WHERE LOCATIONCODE = :loc AND BILLNO IN ({placeholders})
    """
    rows = _safe_rows(q, params) or []
    vouchers: Set[str] = set()
    for r in rows:
        rk = {str(k).lower(): v for k, v in r.items()}
        if str(rk.get('pos_settlement_status') or '').strip().upper() != 'SETTLED':
            continue
        vn = str(rk.get('pos_settlement_voucher_no') or '').strip()
        if vn:
            vouchers.add(vn)
    if not vouchers:
        return (False, 'No posted settlement vouchers found for the selected bills.', [])

    to_post: List[Tuple[str, List[Dict[str, Any]]]] = []
    for vno in sorted(vouchers):
        detail = get_gl_voucher_detail(vno)
        if not detail or not detail.get('lines'):
            continue
        rev_lines: List[Dict[str, Any]] = []
        for ln in detail.get('lines') or []:
            if not isinstance(ln, dict):
                continue
            dr = float(ln.get('debit') or 0)
            cr = float(ln.get('credit') or 0)
            piece: Dict[str, Any] = {
                'account_code': str(ln.get('account_code') or '').strip(),
                'debit': round(cr, 2),
                'credit': round(dr, 2),
                'remarks': (f'Rev {vno} ' + str(ln.get('remarks') or ''))[:250],
            }
            cc_dim = ln.get('cost_center')
            if cc_dim and str(cc_dim).strip() not in ('', '—'):
                piece['cost_center'] = str(cc_dim).strip()
            dp = ln.get('department')
            if dp and str(dp).strip() not in ('', '—'):
                piece['department'] = str(dp).strip()
            pj = ln.get('project')
            if pj and str(pj).strip() not in ('', '—'):
                piece['project'] = str(pj).strip()
            rev_lines.append(piece)
        if len(rev_lines) >= 2:
            to_post.append((vno, rev_lines))

    rev_v_date = datetime.now().strftime('%Y-%m-%d')
    try:
        with _get_connection() as conn:
            try:
                new_vouchers: List[str] = []
                for vno, rev_lines in to_post:
                    rv = create_gl_journal_entry(
                        rev_v_date,
                        vno[:50],
                        (f'Reversal POS settlement {vno} ' + str(remarks or ''))[:500],
                        rev_lines,
                        created_by=str(created_by or '').strip()[:50] or None,
                        source='POS_SETTLEMENT_REV',
                        dimension_defaults=dimension_defaults,
                        conn=conn,
                        commit=False,
                    )
                    new_vouchers.append(rv)
                ok_b, err_b = update_billhdr_pos_settlement_posting(
                    location_code,
                    clean_nos,
                    status='PENDING',
                    voucher_no='',
                    remarks=str(remarks or '').strip()[:500] or None,
                    conn=conn,
                    commit=False,
                )
                if not ok_b:
                    conn.rollback()
                    return (False, err_b or 'Could not reset bills.', [])
                conn.commit()
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
                raise
        try:
            _TABLE_COLUMNS_CACHE.pop('BILLHDR', None)
        except Exception:
            pass
        return (True, '', new_vouchers)
    except Exception as e:
        return (False, str(e), [])


def ensure_pos_save_queue_table() -> bool:
    """Create tenant-local POS background posting queue."""
    try:
        def _ensure_seq() -> None:
            try:
                with _get_connection() as conn:
                    with conn.cursor() as cur:
                        cur.execute("SELECT 1 FROM user_sequences WHERE sequence_name = 'POS_SAVE_QUEUE_SEQ'")
                        if cur.fetchone() is None:
                            cur.execute('CREATE SEQUENCE POS_SAVE_QUEUE_SEQ START WITH 1 INCREMENT BY 1 NOCACHE')
                    conn.commit()
            except Exception:
                pass
        if _table_exists(POS_SAVE_QUEUE_TABLE):
            _ensure_seq()
            return True
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT 1 FROM user_sequences WHERE sequence_name = 'POS_SAVE_QUEUE_SEQ'")
                if cur.fetchone() is None:
                    cur.execute('CREATE SEQUENCE POS_SAVE_QUEUE_SEQ START WITH 1 INCREMENT BY 1 NOCACHE')
                cur.execute(f"""
                    CREATE TABLE {POS_SAVE_QUEUE_TABLE} (
                        JOB_ID NUMBER NOT NULL,
                        LOCATIONCODE NUMBER NOT NULL,
                        BILLNO NUMBER NOT NULL,
                        STATUS VARCHAR2(20) DEFAULT 'PENDING' NOT NULL,
                        PAYLOAD_JSON CLOB NOT NULL,
                        ERROR_MESSAGE VARCHAR2(2000),
                        POSTED_BILLNO NUMBER,
                        CREATED_BY VARCHAR2(100),
                        COUNTERCODE NUMBER,
                        CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
                        STARTED_AT TIMESTAMP,
                        FINISHED_AT TIMESTAMP,
                        ATTEMPTS NUMBER DEFAULT 0 NOT NULL,
                        CONSTRAINT PK_POS_SAVE_QUEUE PRIMARY KEY (JOB_ID)
                    )
                """)
                try:
                    cur.execute(f'CREATE INDEX IDX_POS_SAVE_Q_STATUS ON {POS_SAVE_QUEUE_TABLE} (STATUS, CREATED_AT)')
                except Exception:
                    pass
                try:
                    cur.execute(f'CREATE INDEX IDX_POS_SAVE_Q_BILL ON {POS_SAVE_QUEUE_TABLE} (LOCATIONCODE, BILLNO)')
                except Exception:
                    pass
            conn.commit()
        try:
            _TABLE_EXISTS_CACHE.pop(POS_SAVE_QUEUE_TABLE, None)
            _TABLE_COLUMNS_CACHE.pop(POS_SAVE_QUEUE_TABLE, None)
        except Exception:
            pass
        return True
    except Exception as e:
        print(f'[ERROR ensure_pos_save_queue_table] {e}')
        return False

def enqueue_pos_save_job(payload: Dict[str, Any], location_code: int, billno: Any, created_by: str='', countercode: Optional[int]=None) -> Tuple[bool, Optional[str], Optional[int]]:
    if not ensure_pos_save_queue_table():
        return (False, 'POS save queue table is not available.', None)
    queue_billno = coerce_billno(billno)
    if not billno_is_valid(queue_billno):
        queue_billno = billno_journal_receipt_no(billno)
    try:
        queue_billno = int(queue_billno)
    except (TypeError, ValueError):
        queue_billno = billno_journal_receipt_no(billno)
    try:
        payload_s = json.dumps(payload or {}, default=str, ensure_ascii=False)
        with _get_connection() as conn:
            with conn.cursor() as cur:
                job_var = cur.var(cx_Oracle.NUMBER)
                payload_var = cur.var(cx_Oracle.CLOB)
                payload_var.setvalue(0, payload_s)
                cur.execute(
                    f"""
                    INSERT INTO {POS_SAVE_QUEUE_TABLE}
                        (JOB_ID, LOCATIONCODE, BILLNO, STATUS, PAYLOAD_JSON, CREATED_BY, COUNTERCODE)
                    VALUES
                        (POS_SAVE_QUEUE_SEQ.NEXTVAL, :loc, :billno, 'PENDING', :payload, :created_by, :countercode)
                    RETURNING JOB_ID INTO :job_id
                    """,
                    {
                        'loc': int(location_code),
                        'billno': queue_billno,
                        'payload': payload_var,
                        'created_by': (created_by or '')[:100],
                        'countercode': countercode,
                        'job_id': job_var,
                    },
                )
                raw_job = job_var.getvalue()
                if isinstance(raw_job, list):
                    raw_job = raw_job[0] if raw_job else None
                job_id = int(raw_job) if raw_job is not None else None
            conn.commit()
        return (True, None, job_id)
    except Exception as e:
        print(f'[ERROR enqueue_pos_save_job] {e}')
        return (False, str(e), None)

def mark_temp_bill_queued(location_code: int, billno: int) -> None:
    """Hide queued temp bill from active POS reload while worker posts it."""
    try:
        cols = _get_table_columns('TEMPBILLHDR') or []
        updates = []
        if 'FLAG' in cols:
            updates.append('FLAG = 0')
        if 'BILLTYPE' in cols:
            updates.append("BILLTYPE = 'Q'")
        if not updates:
            return
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f"UPDATE TEMPBILLHDR SET {', '.join(updates)} WHERE LOCATIONCODE = :loc AND BILLNO = :billno", {'loc': int(location_code), 'billno': coerce_billno(billno)})
            conn.commit()
    except Exception as e:
        print(f'[WARN mark_temp_bill_queued] {e}')

def _read_lob_value(value: Any) -> str:
    try:
        if hasattr(value, 'read'):
            return value.read() or ''
    except Exception:
        pass
    return str(value or '')


def release_stale_pos_save_processing_jobs(max_age_minutes: int = POS_SAVE_QUEUE_STALE_MINUTES) -> int:
    """Reset PROCESSING rows stuck longer than max_age (dead worker / hung DB). Returns rows updated."""
    if not ensure_pos_save_queue_table():
        return 0
    try:
        mins = max(2, min(int(max_age_minutes), 24 * 60))
    except Exception:
        mins = POS_SAVE_QUEUE_STALE_MINUTES
    note = ' | auto-requeued (stale PROCESSING)'
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    UPDATE {POS_SAVE_QUEUE_TABLE}
                    SET STATUS = 'PENDING',
                        STARTED_AT = NULL,
                        ERROR_MESSAGE = SUBSTR(NVL(ERROR_MESSAGE, ' ') || :note, 1, 2000)
                    WHERE STATUS = 'PROCESSING'
                      AND STARTED_AT IS NOT NULL
                      AND STARTED_AT < SYSTIMESTAMP - NUMTODSINTERVAL(:mins, 'MINUTE')
                    """,
                    {'mins': mins, 'note': note},
                )
                n = cur.rowcount or 0
            conn.commit()
        if n:
            print(f'[POS_SAVE_QUEUE] released {int(n)} stale PROCESSING row(s) (> {mins}m)')
        return int(n)
    except Exception as e:
        print(f'[ERROR release_stale_pos_save_processing_jobs] {e}')
        return 0


def requeue_excess_pos_save_processing_jobs() -> int:
    """If more than one row is PROCESSING, requeue all of them (orphaned hung workers)."""
    if not ensure_pos_save_queue_table():
        return 0
    note = ' | auto-requeued (duplicate PROCESSING)'
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT COUNT(*) FROM {POS_SAVE_QUEUE_TABLE}
                    WHERE STATUS = 'PROCESSING'
                    """
                )
                row = cur.fetchone()
                cnt = int(row[0] or 0) if row else 0
                if cnt <= 1:
                    conn.rollback()
                    return 0
                cur.execute(
                    f"""
                    UPDATE {POS_SAVE_QUEUE_TABLE}
                    SET STATUS = 'PENDING',
                        STARTED_AT = NULL,
                        ERROR_MESSAGE = SUBSTR(NVL(ERROR_MESSAGE, ' ') || :note, 1, 2000)
                    WHERE STATUS = 'PROCESSING'
                    """,
                    {'note': note},
                )
                n = cur.rowcount or 0
            conn.commit()
        if n:
            print(f'[POS_SAVE_QUEUE] requeued {int(n)} duplicate PROCESSING row(s)')
        return int(n)
    except Exception as e:
        print(f'[ERROR requeue_excess_pos_save_processing_jobs] {e}')
        return 0


def force_requeue_all_pos_save_processing_jobs() -> int:
    """Manual reset: all PROCESSING rows back to PENDING."""
    if not ensure_pos_save_queue_table():
        return 0
    note = ' | manual unstick (all PROCESSING)'
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    UPDATE {POS_SAVE_QUEUE_TABLE}
                    SET STATUS = 'PENDING',
                        STARTED_AT = NULL,
                        FINISHED_AT = NULL,
                        ERROR_MESSAGE = SUBSTR(NVL(ERROR_MESSAGE, ' ') || :note, 1, 2000)
                    WHERE STATUS = 'PROCESSING'
                    """,
                    {'note': note},
                )
                n = cur.rowcount or 0
            conn.commit()
        return int(n)
    except Exception as e:
        print(f'[ERROR force_requeue_all_pos_save_processing_jobs] {e}')
        return 0


def count_pos_save_processing_jobs() -> int:
    if not ensure_pos_save_queue_table():
        return 0
    try:
        return _get_count(
            f"SELECT COUNT(*) FROM {POS_SAVE_QUEUE_TABLE} WHERE STATUS = 'PROCESSING'",
            {},
        )
    except Exception:
        return 0


def prepare_pos_save_queue_for_claim(*, stale_minutes: int = POS_SAVE_QUEUE_STALE_MINUTES) -> None:
    """Release stale / duplicate PROCESSING rows before claiming the next job."""
    release_stale_pos_save_processing_jobs(stale_minutes)
    requeue_excess_pos_save_processing_jobs()


def claim_next_pos_save_job() -> Optional[Dict[str, Any]]:
    if not ensure_pos_save_queue_table():
        return None
    try:
        prepare_pos_save_queue_for_claim()
        if count_pos_save_processing_jobs() > 0:
            return None
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT JOB_ID, LOCATIONCODE, BILLNO, PAYLOAD_JSON
                    FROM (
                        SELECT JOB_ID, LOCATIONCODE, BILLNO, PAYLOAD_JSON
                        FROM {POS_SAVE_QUEUE_TABLE}
                        WHERE STATUS = 'PENDING'
                        ORDER BY CREATED_AT, JOB_ID
                    )
                    WHERE ROWNUM = 1
                    """
                )
                row = cur.fetchone()
                if not row:
                    conn.rollback()
                    return None
                job_id = int(row[0])
                cur.execute(
                    f"""
                    UPDATE {POS_SAVE_QUEUE_TABLE}
                    SET STATUS = 'PROCESSING',
                        STARTED_AT = SYSTIMESTAMP,
                        ATTEMPTS = NVL(ATTEMPTS, 0) + 1,
                        ERROR_MESSAGE = NULL
                    WHERE JOB_ID = :job_id AND STATUS = 'PENDING'
                    """,
                    {'job_id': job_id},
                )
                if cur.rowcount == 0:
                    conn.rollback()
                    return None
                payload_text = _read_lob_value(row[3])
            conn.commit()
        return {'job_id': job_id, 'location_code': row[1], 'billno': row[2], 'payload': json.loads(payload_text or '{}')}
    except Exception as e:
        print(f'[ERROR claim_next_pos_save_job] {e}')
        return None


def claim_pos_save_job_by_id(job_id: int) -> Optional[Dict[str, Any]]:
    """Claim a specific PENDING or FAILED job for immediate posting (skips FIFO wait)."""
    if not ensure_pos_save_queue_table():
        return None
    try:
        prepare_pos_save_queue_for_claim()
        jid = int(job_id)
        if jid <= 0:
            return None
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    SELECT JOB_ID, LOCATIONCODE, BILLNO, PAYLOAD_JSON
                    FROM {POS_SAVE_QUEUE_TABLE}
                    WHERE JOB_ID = :job_id AND STATUS IN ('PENDING', 'FAILED')
                    """,
                    {'job_id': jid},
                )
                row = cur.fetchone()
                if not row:
                    conn.rollback()
                    return None
                cur.execute(
                    f"""
                    UPDATE {POS_SAVE_QUEUE_TABLE}
                    SET STATUS = 'PROCESSING',
                        STARTED_AT = SYSTIMESTAMP,
                        ATTEMPTS = NVL(ATTEMPTS, 0) + 1,
                        ERROR_MESSAGE = NULL,
                        FINISHED_AT = NULL
                    WHERE JOB_ID = :job_id AND STATUS IN ('PENDING', 'FAILED')
                    """,
                    {'job_id': jid},
                )
                if cur.rowcount == 0:
                    conn.rollback()
                    return None
                payload_text = _read_lob_value(row[3])
            conn.commit()
        return {'job_id': jid, 'location_code': row[1], 'billno': row[2], 'payload': json.loads(payload_text or '{}')}
    except Exception as e:
        print(f'[ERROR claim_pos_save_job_by_id] {e}')
        return None


def finish_pos_save_job(job_id: int, ok: bool, posted_billno: Optional[int]=None, error: Optional[str]=None) -> None:
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    UPDATE {POS_SAVE_QUEUE_TABLE}
                    SET STATUS = :status,
                        POSTED_BILLNO = :posted_billno,
                        ERROR_MESSAGE = :error_message,
                        FINISHED_AT = SYSTIMESTAMP
                    WHERE JOB_ID = :job_id AND STATUS = 'PROCESSING'
                    """,
                    {
                        'status': 'POSTED' if ok else 'FAILED',
                        'posted_billno': posted_billno,
                        'error_message': (error or '')[:2000] if error else None,
                        'job_id': int(job_id),
                    },
                )
            conn.commit()
    except Exception as e:
        print(f'[ERROR finish_pos_save_job] {e}')

def retry_pos_save_job(job_id: int, *, unstick_processing: bool = False) -> Tuple[bool, str]:
    if not ensure_pos_save_queue_table():
        return (False, 'POS save queue table is not available.')
    status_sql = "STATUS = 'PROCESSING'" if unstick_processing else "STATUS = 'FAILED'"
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    f"""
                    UPDATE {POS_SAVE_QUEUE_TABLE}
                    SET STATUS = 'PENDING',
                        ERROR_MESSAGE = NULL,
                        STARTED_AT = NULL,
                        FINISHED_AT = NULL
                    WHERE JOB_ID = :job_id AND {status_sql}
                    """,
                    {'job_id': int(job_id)},
                )
                if cur.rowcount == 0:
                    conn.rollback()
                    hint = 'Job not in PROCESSING (nothing to unstick).' if unstick_processing else 'Job not FAILED or not found.'
                    return (False, hint)
            conn.commit()
        return (True, '')
    except Exception as e:
        return (False, str(e))

def list_pos_save_queue(limit: int=100) -> List[Dict[str, Any]]:
    if not ensure_pos_save_queue_table():
        return []
    try:
        lim = max(1, min(int(limit or 100), 500))
    except Exception:
        lim = 100
    rows = _safe_rows(
        f"""
        SELECT * FROM (
            SELECT JOB_ID AS job_id,
                   LOCATIONCODE AS locationcode,
                   BILLNO AS billno,
                   STATUS AS status,
                   ERROR_MESSAGE AS error_message,
                   POSTED_BILLNO AS posted_billno,
                   CREATED_BY AS created_by,
                   COUNTERCODE AS countercode,
                   TO_CHAR(CREATED_AT, 'YYYY-MM-DD HH24:MI:SS') AS created_at,
                   TO_CHAR(STARTED_AT, 'YYYY-MM-DD HH24:MI:SS') AS started_at,
                   TO_CHAR(FINISHED_AT, 'YYYY-MM-DD HH24:MI:SS') AS finished_at,
                   ATTEMPTS AS attempts
            FROM {POS_SAVE_QUEUE_TABLE}
            ORDER BY JOB_ID DESC
        )
        WHERE ROWNUM <= :lim
        """,
        {'lim': lim},
    )
    return rows or []


