    where_sql = 'WHERE ' + ' AND '.join(where_parts)
    inner = f"\n        SELECT {', '.join(select_cols)}\n        FROM TEMPBILLHDR\n        {where_sql}\n        ORDER BY BILLDATE DESC NULLS LAST, BILLNO DESC\n    "
    q = f'SELECT * FROM ({inner}) WHERE ROWNUM <= :lim'
    return _filter_rows_positive_counter(_safe_rows(q, params) or [])


