def count_pos_held_bills_for_counter(
    location_code: int,
    counter_code: int,
    pos_date: Any,
    *,
    db_key: Optional[str] = None,
) -> int:
    """Count held carts (TEMPBILLHDR BILLTYPE H) for counter on POS business date."""
    if not _table_exists('TEMPBILLHDR', db_key=db_key):
        return 0
    cols = _get_table_columns('TEMPBILLHDR')
    if not cols or 'BILLNO' not in cols or 'BILLTYPE' not in cols:
        return 0
    if 'COUNTERCODE' not in cols or 'BILLDATE' not in cols:
        return 0
    try:
        lc = int(location_code)
        cc = int(counter_code)
    except (TypeError, ValueError):
        return 0
    pd = pos_date.date() if hasattr(pos_date, 'date') and callable(pos_date.date) else pos_date
    rows = _safe_rows(
        """
        SELECT COUNT(*) AS cnt
        FROM TEMPBILLHDR
        WHERE LOCATIONCODE = :loc
          AND COUNTERCODE = :cc
          AND BILLTYPE = 'H'
          AND TRUNC(BILLDATE) = TRUNC(:pd)
        """,
        {'loc': lc, 'cc': cc, 'pd': pd},
        db_key=db_key,
    ) or []
    if not rows:
        return 0
    r0 = rows[0]
    try:
        return int(float(r0.get('cnt') or r0.get('CNT') or 0))
    except (TypeError, ValueError):
        return 0


