def get_pos_bill_receipt_for_tab(tab: str, billno: int, location_code: int, user_dbkey: Optional[str]=None, nls_lang: Optional[str]=None) -> Optional[Dict[str, Any]]:
    """Receipt payload for POS Bills UI: posted / held / canceled."""
    t = (tab or '').strip().lower()
    if t == 'posted':
        h, lines = get_sales_print_data(billno, location_code)
        if not h:
            return None
        receipt = sales_print_to_pos_receipt(h, lines, billno, user_dbkey)
        if receipt:
            receipt['receipt_extras'] = _pos_receipt_extras_for_posted_bill(location_code, billno, h)
        return receipt
    if t == 'held':
        return get_receipt_data_from_temp_bill(billno, location_code, user_dbkey, nls_lang=nls_lang, billtype_filter=('H',))
    if t == 'canceled':
        if not _table_exists('TBLCANCELEDHDR'):
            return None
        return get_receipt_data_from_temp_bill(billno, location_code, user_dbkey, nls_lang=nls_lang, hdr_table='TBLCANCELEDHDR', dtl_table='TBLCANCELEDDTL', billtype_filter=None)
    return None


def void_bill(billno: int, location_code: Optional[int]=None) -> Tuple[bool, Optional[str]]:
    """Mark a bill as void: set DELFLAG='Y' and BILLSTATUS='V' on BILLHDR and BILLHDRHISTORY."""
    if not billno:
        return (False, 'Invalid bill number.')
    hdr_cols = _get_table_columns('BILLHDR')
    if not hdr_cols:
        return (False, 'BILLHDR table not available.')
    billno_col = 'BILLNO' if 'BILLNO' in hdr_cols else None
    if not billno_col:
        return (False, 'BILLHDR has no BILLNO column.')
    updates = []
    params = {'billno': billno}
    if 'DELFLAG' in hdr_cols:
        updates.append("DELFLAG = 'Y'")
    if 'BILLSTATUS' in hdr_cols:
        updates.append("BILLSTATUS = 'V'")
    if not updates:
        return (False, 'No void columns (DELFLAG/BILLSTATUS) in BILLHDR.')
    where_parts = [f'{billno_col} = :billno']
    if location_code is not None and 'LOCATIONCODE' in hdr_cols:
        where_parts.append('LOCATIONCODE = :location_code')
        params['location_code'] = location_code
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f"UPDATE BILLHDR SET {', '.join(updates)} WHERE {' AND '.join(where_parts)}", params)
                hist_cols = _get_table_columns('BILLHDRHISTORY')
                if hist_cols and 'BILLNO' in hist_cols:
                    hist_set = []
                    if 'DELFLAG' in hist_cols:
                        hist_set.append("DELFLAG = 'Y'")
                    if 'BILLSTATUS' in hist_cols:
                        hist_set.append("BILLSTATUS = 'V'")
                    if hist_set:
                        hist_where = ['BILLNO = :billno']
                        hist_params = {'billno': billno}
                        if location_code is not None and 'LOCATIONCODE' in hist_cols:
                            hist_where.append('LOCATIONCODE = :location_code')
                            hist_params['location_code'] = location_code
                        cur.execute(f"UPDATE BILLHDRHISTORY SET {', '.join(hist_set)} WHERE {' AND '.join(hist_where)}", hist_params)
                conn.commit()
        return (True, None)
    except Exception as e:
        print(f'[ERROR void_bill] {e}')
        return (False, str(e))
GL_HDR_TABLE = 'GL_VOUCHER_HDR'
GL_DTL_TABLE = 'GL_VOUCHER_DTL'
GL_DTL_SEQ = 'GL_VOUCHER_DTL_SEQ'
GL_ACCOUNT_DIMENSION_RULE_TABLE = 'GL_ACCOUNT_DIMENSION_RULE'
GL_DIMENSION_VALUE_TABLE = 'GL_DIMENSION_VALUE'
GL_DIMENSION_TYPES: Tuple[str, ...] = ('COST_CENTER', 'DEPARTMENT', 'PROJECT')
AP_ALLOC_TABLE = 'AP_SUPPLIER_PAYMENT_ALLOC'
AP_ALLOC_SEQ = 'AP_SUPPLIER_PAYMENT_ALLOC_SEQ'
AR_ALLOC_TABLE = 'AR_CUSTOMER_PAYMENT_ALLOC'
AR_ALLOC_SEQ = 'AR_CUSTOMER_PAYMENT_ALLOC_SEQ'

def _to_iso_date(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.strftime('%Y-%m-%d')
    s = str(value).strip()
    if not s:
        return None
    try:
        return datetime.strptime(s[:10], '%Y-%m-%d').strftime('%Y-%m-%d')
    except Exception:
        return None

def ensure_gl_tables(db_key: Optional[str]=None) -> bool:
    """Create GL voucher header/detail tables and sequence if missing."""
    global _GL_TABLES_ENSURED
    if _GL_TABLES_ENSURED:
        return True
    hdr_ok = _table_exists(GL_HDR_TABLE, db_key=db_key)
    dtl_ok = _table_exists(GL_DTL_TABLE, db_key=db_key)
    if hdr_ok and dtl_ok:
        _GL_TABLES_ENSURED = True
        return True
    _GL_TABLES_ENSURED = True
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                try:
                    cur.execute('SELECT 1 FROM user_sequences WHERE sequence_name = :n', {'n': GL_DTL_SEQ})
                    if cur.fetchone() is None:
                        cur.execute(f'CREATE SEQUENCE {GL_DTL_SEQ} START WITH 1 INCREMENT BY 1 NOCACHE')
                except Exception:
                    pass
                if not _table_exists(GL_HDR_TABLE, db_key=db_key):
                    cur.execute(f'\n                        CREATE TABLE {GL_HDR_TABLE} (\n                            VOUCHER_NO VARCHAR2(30) PRIMARY KEY,\n                            VOUCHER_DATE DATE NOT NULL,\n                            REFERENCE_NO VARCHAR2(50),\n                            NARRATION VARCHAR2(500),\n                            SOURCE VARCHAR2(20),\n                            CREATED_BY VARCHAR2(50),\n                            CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL\n                        )\n                        ')
                if not _table_exists(GL_DTL_TABLE, db_key=db_key):
                    cur.execute(f'\n                        CREATE TABLE {GL_DTL_TABLE} (\n                            LINE_ID NUMBER PRIMARY KEY,\n                            VOUCHER_NO VARCHAR2(30) NOT NULL,\n                            LINE_NO NUMBER NOT NULL,\n                            ACCOUNT_CODE VARCHAR2(20) NOT NULL,\n                            DEBIT NUMBER(18,2) DEFAULT 0 NOT NULL,\n                            CREDIT NUMBER(18,2) DEFAULT 0 NOT NULL,\n                            REMARKS VARCHAR2(250),\n                            PARTY_TYPE VARCHAR2(20),\n                            PARTY_CODE VARCHAR2(50),\n                            COST_CENTER VARCHAR2(30),\n                            DEPARTMENT VARCHAR2(30),\n                            PROJECT VARCHAR2(30)\n                        )\n                        ')
                else:
                    try:
                        dtl_cols = _get_table_columns(GL_DTL_TABLE)
                        if 'PARTY_TYPE' not in dtl_cols:
                            cur.execute(f'ALTER TABLE {GL_DTL_TABLE} ADD PARTY_TYPE VARCHAR2(20)')
                        if 'PARTY_CODE' not in dtl_cols:
                            cur.execute(f'ALTER TABLE {GL_DTL_TABLE} ADD PARTY_CODE VARCHAR2(50)')
                        _TABLE_COLUMNS_CACHE.pop(GL_DTL_TABLE.upper(), None)
                    except Exception:
                        pass
                    try:
                        dtl_cols2 = {c.upper() for c in _get_table_columns(GL_DTL_TABLE) or []}
                        if 'COST_CENTER' not in dtl_cols2:
                            cur.execute(f'ALTER TABLE {GL_DTL_TABLE} ADD COST_CENTER VARCHAR2(30)')
                        if 'DEPARTMENT' not in dtl_cols2:
                            cur.execute(f'ALTER TABLE {GL_DTL_TABLE} ADD DEPARTMENT VARCHAR2(30)')
                        if 'PROJECT' not in dtl_cols2:
                            cur.execute(f'ALTER TABLE {GL_DTL_TABLE} ADD PROJECT VARCHAR2(30)')
                        _TABLE_COLUMNS_CACHE.pop(GL_DTL_TABLE.upper(), None)
                    except Exception:
                        pass
                conn.commit()
        return True
    except Exception as e:
        print(f'[ERROR ensure_gl_tables] {e}')
        return False


def pos_payload_credit_delta(header: Dict[str, Any], lines: List[Dict[str, Any]]) -> float:
    """Signed delta on customer's tracked outstanding credit (same magnitude logic as POS GL net bill total)."""
    total_amount = 0.0
    for line in lines or []:
        if not isinstance(line, dict):
            continue
        total_amount += _sales_line_net_for_total(line)
    mag = round(abs(total_amount), 2)
    is_ret = bool(header.get('is_sales_return')) or _infer_sales_return_from_lines(lines)
    return round(-mag, 2) if is_ret else mag


def validate_pos_credit_customer_accounts(location_code: int, customer_code: Any, *, proposed_credit_delta: Optional[float]=None) -> Tuple[bool, Optional[str]]:
    """POS credit (posts GL): customer must exist; GL mappings filled when enforced; optional credit limit check."""
    try:
        cc = int(customer_code or 0)
    except (TypeError, ValueError):
        return (False, 'Invalid customer code for credit sale.')
    if cc <= 0:
        return (True, None)
    if not ensure_gl_tables():
        return (False, 'General ledger is not available. Use cash sale or ask an administrator to configure GL.')
    cust_tbl = _detect_table(['CUSTOMER', 'customer', 'CUSTOMERS', 'customers'])
    if not cust_tbl:
        return (True, None)
    loc_col = _detect_column(cust_tbl, ['LOCATIONCODE', 'locationcode', 'LOCATION_CODE'])
    code_col = _detect_column(cust_tbl, ['CUSTOMERCODE', 'customercode', 'CUST_CODE', 'CODE'])
    recv_col = _detect_column(cust_tbl, ['RECEIVABLEACCOUNT', 'receivableaccount'])
    sales_col = _detect_column(cust_tbl, ['SALESACCOUNT', 'salesaccount'])
    vat_col = _detect_column(cust_tbl, ['VATOUTPUTACCOUNT', 'vatoutputaccount'])
    lim_col = _detect_column(cust_tbl, ['CREDITLIMIT', 'CREDIT_LIMIT', 'CREDITLIMITAMOUNT', 'CREDITAMOUNT', 'CREDIT_AMT'])
    curcred_col = _detect_column(cust_tbl, ['CURRENTCREDIT', 'CURRENT_CREDIT', 'CURRCREDIT', 'CURRENTCREDITAMOUNT', 'CURRENT_CREDIT_AMOUNT', 'CREDITBALANCE', 'CREDITBAL'])
    if not code_col:
        return (True, None)
    sel_parts: List[str] = []
    for c in (code_col, recv_col, sales_col, vat_col, lim_col, curcred_col):
        if c and c not in sel_parts:
            sel_parts.append(c)
    where = [f'{code_col} = :cc']
    params: Dict[str, Any] = {'cc': cc}
    if loc_col:
        where.append(f'{loc_col} = :lc')
        params['lc'] = location_code
    q = f"SELECT {', '.join(sel_parts)} FROM {cust_tbl} WHERE {' AND '.join(where)}"
    rows = _safe_rows(q, params)
    if not rows:
        return (False, f'Customer {cc} was not found in the customer master for this branch. Pick a valid customer or use walk-in cash sale.')
    rk = {str(k).lower(): v for k, v in rows[0].items()}
    if proposed_credit_delta is not None and lim_col:
        try:
            delta_f = float(proposed_credit_delta)
        except (TypeError, ValueError):
            delta_f = 0.0
        if abs(delta_f) > 1e-9:
            try:
                lim_v = float(rk.get(str(lim_col).lower()) or 0)
            except (TypeError, ValueError):
                lim_v = 0.0
            recv_ac = rk.get(str(recv_col).lower()) if recv_col else None
            gl_ctx = _customer_gl_receivable_context()
            if gl_ctx:
                cur_v, _src = _customer_gl_receivable_balance(cc, recv_ac, ctx=gl_ctx)
            else:
                cur_v = 0.0
            new_v = cur_v + delta_f
            if lim_v > 0 and new_v > lim_v + 1e-6:
                return (False, f'Credit limit exceeded for customer {cc}. Limit {lim_v:.2f}, outstanding credit {cur_v:.2f}, this bill {delta_f:+.2f}.')
    gl_pairs = [(recv_col, 'Receivable account'), (sales_col, 'Sales account'), (vat_col, 'VAT output account')]
    defined_pairs = [(col, label) for col, label in gl_pairs if col]
    if not defined_pairs:
        return (True, None)
    missing: List[str] = []
    for col, label in defined_pairs:
        key = str(col).lower()
        val = rk.get(key)
        if val is None or str(val).strip() == '':
            missing.append(label)
    if missing:
        joined = ', '.join(missing)
        return (False, f'This customer cannot post to accounts until GL mapping is set: missing {joined}. Update the customer master or use walk-in cash sale.')
    return (True, None)


def ensure_gl_account_dimension_rule_table(_db_key_ignored: Any=None) -> bool:
    """Optional rules: which GL accounts require cost center / department / project."""
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if not _table_exists(GL_ACCOUNT_DIMENSION_RULE_TABLE):
                    cur.execute(f"\n                        CREATE TABLE {GL_ACCOUNT_DIMENSION_RULE_TABLE} (\n                            ACCOUNT_CODE VARCHAR2(20) NOT NULL PRIMARY KEY,\n                            REQUIRE_COST_CENTER VARCHAR2(1) DEFAULT 'N' NOT NULL,\n                            REQUIRE_DEPARTMENT VARCHAR2(1) DEFAULT 'N' NOT NULL,\n                            REQUIRE_PROJECT VARCHAR2(1) DEFAULT 'N' NOT NULL,\n                            UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL\n                        )\n                        ")
                conn.commit()
        try:
            _TABLE_EXISTS_CACHE.pop(GL_ACCOUNT_DIMENSION_RULE_TABLE.upper(), None)
        except Exception:
            pass
        return True
    except Exception as e:
        print(f'[ERROR ensure_gl_account_dimension_rule_table] {e}')
        return False

def list_gl_account_dimension_rules(_db_key_ignored: Any=None) -> List[Dict[str, Any]]:
    ensure_gl_account_dimension_rule_table()
    if not _table_exists(GL_ACCOUNT_DIMENSION_RULE_TABLE):
        return []
    rows = _safe_rows(f'\n        SELECT ACCOUNT_CODE, REQUIRE_COST_CENTER, REQUIRE_DEPARTMENT, REQUIRE_PROJECT, UPDATED_AT\n        FROM {GL_ACCOUNT_DIMENSION_RULE_TABLE}\n        ORDER BY ACCOUNT_CODE\n        ', {})
    return rows or []

def upsert_gl_account_dimension_rule(account_code: str, require_cost_center: str='N', require_department: str='N', require_project: str='N', _db_key_ignored: Any=None) -> Tuple[bool, str]:
    """Set Y/N requirements for one COA code. Unknown accounts still validate at posting if rule row exists."""
    ensure_gl_account_dimension_rule_table()
    if not _table_exists(GL_ACCOUNT_DIMENSION_RULE_TABLE):
        return (False, 'GL_ACCOUNT_DIMENSION_RULE table not available.')
    ac = (account_code or '').strip()[:20].upper()
    if not ac:
        return (False, 'ACCOUNT_CODE is required.')

    def _yn(v: str) -> str:
        return 'Y' if str(v or '').strip().upper() in ('Y', '1', 'TRUE', 'YES') else 'N'
    rcc, rdp, rpr = (_yn(require_cost_center), _yn(require_department), _yn(require_project))
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f'DELETE FROM {GL_ACCOUNT_DIMENSION_RULE_TABLE} WHERE ACCOUNT_CODE = :ac', {'ac': ac})
                cur.execute(f'\n                    INSERT INTO {GL_ACCOUNT_DIMENSION_RULE_TABLE}\n                        (ACCOUNT_CODE, REQUIRE_COST_CENTER, REQUIRE_DEPARTMENT, REQUIRE_PROJECT, UPDATED_AT)\n                    VALUES (:ac, :rcc, :rdp, :rpr, SYSTIMESTAMP)\n                    ', {'ac': ac, 'rcc': rcc, 'rdp': rdp, 'rpr': rpr})
            conn.commit()
        return (True, '')
    except Exception as e:
        return (False, str(e))

def get_gl_dimension_requirements_for_account(account_code: str) -> Dict[str, bool]:
    """Return which dimensions are required for this account (no row => nothing required)."""
    ensure_gl_account_dimension_rule_table()
    out = {'require_cost_center': False, 'require_department': False, 'require_project': False}
    if not _table_exists(GL_ACCOUNT_DIMENSION_RULE_TABLE):
        return out
    ac = (account_code or '').strip()[:20].upper()
    if not ac:
        return out
    rows = _safe_rows(f'\n        SELECT REQUIRE_COST_CENTER, REQUIRE_DEPARTMENT, REQUIRE_PROJECT\n        FROM {GL_ACCOUNT_DIMENSION_RULE_TABLE}\n        WHERE ACCOUNT_CODE = :ac\n        ', {'ac': ac})
    if not rows:
        return out
    r0 = rows[0] or {}

    def _is_y(k: str) -> bool:
        return str(r0.get(k) or r0.get(k.lower()) or 'N').strip().upper() == 'Y'
    out['require_cost_center'] = _is_y('REQUIRE_COST_CENTER')
    out['require_department'] = _is_y('REQUIRE_DEPARTMENT')
    out['require_project'] = _is_y('REQUIRE_PROJECT')
    return out

def _gl_line_dim_trim(val: Any) -> Optional[str]:
    if val is None:
        return None
    s = str(val).strip()[:30]
    return s if s else None

def resolve_gl_line_dimensions(line: Dict[str, Any], dimension_defaults: Optional[Dict[str, Any]]=None) -> Dict[str, Optional[str]]:
    """
    Merge per-line and header/session defaults for GL analytic dimensions.

    Precedence: explicit line field (any alias) wins; else ``dimension_defaults`` key.
    """
    line = line or {}
    d = dimension_defaults or {}

    def _pick(keys: Tuple[str, ...]) -> Optional[str]:
        for m in (line, d):
            for k in keys:
                if k in m and m[k] is not None and (str(m[k]).strip() != ''):
                    return _gl_line_dim_trim(m[k])
        return None
    return {'cost_center': _pick(('cost_center', 'COST_CENTER', 'cc', 'CC')), 'department': _pick(('department', 'DEPARTMENT', 'dept', 'DEPT')), 'project': _pick(('project', 'PROJECT', 'proj', 'PROJ'))}

def _validate_resolved_gl_dimensions(account_code: str, resolved: Dict[str, Optional[str]]) -> None:
    req = get_gl_dimension_requirements_for_account(account_code)
    if req.get('require_cost_center') and (not (resolved.get('cost_center') or '').strip()):
        raise ValueError(f'Account {account_code}: cost center is required.')
    if req.get('require_department') and (not (resolved.get('department') or '').strip()):
        raise ValueError(f'Account {account_code}: department is required.')
    if req.get('require_project') and (not (resolved.get('project') or '').strip()):
        raise ValueError(f'Account {account_code}: project is required.')

def normalize_gl_dimension_type(raw: Any) -> str:
    """Return one of COST_CENTER, DEPARTMENT, PROJECT or raise ValueError."""
    u = str(raw or '').strip().upper()
    if u not in GL_DIMENSION_TYPES:
        raise ValueError('Dimension type must be COST_CENTER, DEPARTMENT, or PROJECT.')
    return u

def ensure_gl_dimension_value_table(_db_key_ignored: Any=None) -> bool:
    """Master list of allowed analytic dimension codes (Setup → GL dimensions)."""
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                if not _table_exists(GL_DIMENSION_VALUE_TABLE):
                    cur.execute(f"\n                        CREATE TABLE {GL_DIMENSION_VALUE_TABLE} (\n                            DIM_TYPE VARCHAR2(20) NOT NULL,\n                            DIM_CODE VARCHAR2(30) NOT NULL,\n                            DIM_NAME VARCHAR2(200),\n                            ACTIVE VARCHAR2(1) DEFAULT 'Y' NOT NULL,\n                            SORT_ORDER NUMBER(6) DEFAULT 0 NOT NULL,\n                            UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,\n                            CONSTRAINT PK_GL_DIM_VAL PRIMARY KEY (DIM_TYPE, DIM_CODE)\n                        )\n                        ")
                conn.commit()
        try:
            _TABLE_EXISTS_CACHE.pop(GL_DIMENSION_VALUE_TABLE.upper(), None)
        except Exception:
            pass
        return True
    except Exception as e:
        print(f'[ERROR ensure_gl_dimension_value_table] {e}')
        return False

def list_gl_dimension_values(dim_type: Optional[str]=None, include_inactive: bool=False, _db_key_ignored: Any=None) -> List[Dict[str, Any]]:
    """List dimension master rows; optional filter by DIM_TYPE."""
    ensure_gl_dimension_value_table()
    if not _table_exists(GL_DIMENSION_VALUE_TABLE):
        return []
    where = ['1=1']
    params: Dict[str, Any] = {}
    if dim_type:
        where.append('DIM_TYPE = :dt')
        params['dt'] = normalize_gl_dimension_type(dim_type)
    if not include_inactive:
        where.append("NVL(UPPER(TRIM(ACTIVE)), 'Y') = 'Y'")
    q = f"\n        SELECT DIM_TYPE, DIM_CODE, DIM_NAME, ACTIVE, SORT_ORDER, UPDATED_AT\n        FROM {GL_DIMENSION_VALUE_TABLE}\n        WHERE {' AND '.join(where)}\n        ORDER BY DIM_TYPE, SORT_ORDER, DIM_CODE\n    "
    return _safe_rows(q, params) or []

def upsert_gl_dimension_value(dim_type: str, dim_code: str, dim_name: Optional[str]=None, active: str='Y', sort_order: int=0, _db_key_ignored: Any=None) -> Tuple[bool, str]:
    ensure_gl_dimension_value_table()
    if not _table_exists(GL_DIMENSION_VALUE_TABLE):
        return (False, 'GL_DIMENSION_VALUE table not available.')
    try:
        dt = normalize_gl_dimension_type(dim_type)
    except ValueError as e:
        return (False, str(e))
    dc = str(dim_code or '').strip()[:30].upper()
    if not dc:
        return (False, 'Dimension code is required.')
    nm = (dim_name or '').strip()[:200] or None
    act = 'Y' if str(active or '').strip().upper() in ('Y', '1', 'TRUE', 'YES') else 'N'
    try:
        so = int(sort_order)
    except (TypeError, ValueError):
        so = 0
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f'DELETE FROM {GL_DIMENSION_VALUE_TABLE} WHERE DIM_TYPE = :dt AND DIM_CODE = :dc', {'dt': dt, 'dc': dc})
                cur.execute(f'\n                    INSERT INTO {GL_DIMENSION_VALUE_TABLE}\n                        (DIM_TYPE, DIM_CODE, DIM_NAME, ACTIVE, SORT_ORDER, UPDATED_AT)\n                    VALUES (:dt, :dc, :nm, :act, :so, SYSTIMESTAMP)\n                    ', {'dt': dt, 'dc': dc, 'nm': nm, 'act': act, 'so': so})
            conn.commit()
        return (True, '')
    except Exception as e:
        return (False, str(e))

