def ensure_ap_payment_tables() -> bool:
    """Create AP supplier payment allocation table if missing."""
    ensure_gl_tables()
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                try:
                    cur.execute('SELECT 1 FROM user_sequences WHERE sequence_name = :n', {'n': AP_ALLOC_SEQ})
                    if cur.fetchone() is None:
                        cur.execute(f'CREATE SEQUENCE {AP_ALLOC_SEQ} START WITH 1 INCREMENT BY 1 NOCACHE')
                except Exception:
                    pass
        if not _table_exists(AP_ALLOC_TABLE):
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute(f'\n                        CREATE TABLE {AP_ALLOC_TABLE} (\n                            ALLOC_ID NUMBER PRIMARY KEY,\n                            PAYMENT_VOUCHER_NO VARCHAR2(30) NOT NULL,\n                            SUPPLIER_CODE VARCHAR2(50) NOT NULL,\n                            INVOICE_VOUCHER_NO VARCHAR2(30) NOT NULL,\n                            ALLOCATED_AMOUNT NUMBER(18,2) DEFAULT 0 NOT NULL,\n                            CREATED_BY VARCHAR2(50),\n                            CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL\n                        )\n                        ')
                    conn.commit()
        return True
    except Exception as e:
        print(f'[ERROR ensure_ap_payment_tables] {e}')
        return False

def _coa_type_map_for_payment() -> Dict[str, str]:
    """Uppercase account code -> COA type (LIABILITY, ASSET, …)."""
    out: Dict[str, str] = {}
    for r in get_all_chart_of_accounts() or []:
        code = str(r.get('code') or '').strip().upper()
        if code:
            out[code] = str(r.get('type') or '').upper()
    return out


def _party_gl_voucher_balance_rows(party_type: str, party_code: str) -> List[Dict[str, Any]]:
    """All GL detail rows for one party, excluding posted payment/receipt settlement vouchers."""
    pt = (party_type or '').strip().upper()
    pcode = _norm_supplier_key(party_code)
    if pt not in {'SUPPLIER', 'CUSTOMER'} or not pcode:
        return []
    return _safe_rows(
        f"""
        SELECT
            d.VOUCHER_NO AS voucher_no,
            h.VOUCHER_DATE AS voucher_date,
            h.REFERENCE_NO AS reference_no,
            h.NARRATION AS narration,
            h.SOURCE AS source,
            d.ACCOUNT_CODE AS account_code,
            SUM(d.DEBIT) AS debit,
            SUM(d.CREDIT) AS credit
        FROM {GL_DTL_TABLE} d
        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO
        WHERE UPPER(NVL(d.PARTY_TYPE, '')) = :pt
          AND d.PARTY_CODE IS NOT NULL
          AND (
            TRIM(TO_CHAR(d.PARTY_CODE)) = :pcode
            OR LTRIM(TRIM(TO_CHAR(d.PARTY_CODE)), '0') = LTRIM(:pcode, '0')
          )
          AND UPPER(NVL(h.SOURCE, '')) NOT IN ('AP_RECEIPT', 'AR_RECEIPT')
        GROUP BY d.VOUCHER_NO, h.VOUCHER_DATE, h.REFERENCE_NO, h.NARRATION, h.SOURCE, d.ACCOUNT_CODE
        """,
        {'pt': pt, 'pcode': pcode},
    ) or []


def _voucher_open_amount_from_party_rows(
    rows: List[Dict[str, Any]],
    *,
    balance_mode: str,
    primary_account: str,
    coa_types: Dict[str, str],
) -> Dict[str, Dict[str, Any]]:
    """Per voucher: open document amount from party-tagged lines (manual journal, GRN, opening, etc.).

    Uses the same priority as :func:`get_accounts_payable_summary` / receivable balances:
    LIABILITY/ASSET lines first, else supplier/customer mapped control account, else all party lines on the voucher.

    Purchase returns / debit notes often party-tag both inventory and payable lines; those
    cancel to ~0 if summed. When that happens, prefer the payable/receivable control side.
    """
    mode = (balance_mode or '').strip().lower()
    primary = str(primary_account or '').strip().upper()
    primary_norm = _norm_gl_account_code(primary).upper()
    target_type = 'LIABILITY' if mode == 'payable' else 'ASSET'
    contra_type = 'ASSET' if mode == 'payable' else 'LIABILITY'
    voucher_map: Dict[str, Dict[str, Any]] = {}
    for r in rows or []:
        vno = str(r.get('voucher_no') or '').strip()
        if not vno:
            continue
        acc = str(r.get('account_code') or '').strip().upper()
        acc_norm = _norm_gl_account_code(acc).upper()
        dr = float(r.get('debit') or 0)
        cr = float(r.get('credit') or 0)
        line_bal = round((cr - dr) if mode == 'payable' else (dr - cr), 2)
        rec = voucher_map.setdefault(
            vno,
            {
                'voucher_no': vno,
                'voucher_date': _to_iso_date(r.get('voucher_date')),
                'reference_no': r.get('reference_no'),
                'narration': r.get('narration'),
                'source': r.get('source'),
                'line_bals': [],
            },
        )
        rec['line_bals'].append((acc, acc_norm, line_bal, coa_types.get(acc, '') or coa_types.get(acc_norm, '')))
    credit_note_sources = {
        'PURCHASE_RETURN',
        'PURCHASE_DEBIT_NOTE',
        'RETURN',
        'SALES_RETURN',
        'BILL_RETURN',
    }
    for vno, rec in voucher_map.items():
        bals: List[Tuple[str, str, float, str]] = rec.pop('line_bals', [])
        typed = [b for _a, _an, b, t in bals if t == target_type]
        mapped = [
            b
            for a, an, b, _t in bals
            if primary and (a == primary or an == primary_norm)
        ]
        src = str(rec.get('source') or '').strip().upper()
        if typed:
            amount = round(sum(typed), 2)
        elif mapped:
            amount = round(sum(mapped), 2)
        else:
            # Drop known contra stock/VAT lines when COA type is known.
            filtered = [b for _a, _an, b, t in bals if t != contra_type]
            amount = round(sum(filtered if filtered else (b for _a, _an, b, _t in bals)), 2)
        # Inventory + payable both party-tagged → nets to ~0; recover control side.
        if abs(amount) < 0.005 and len(bals) > 1:
            if mapped:
                amount = round(sum(mapped), 2)
            elif typed:
                amount = round(sum(typed), 2)
            else:
                significant = [b for _a, _an, b, _t in bals if abs(b) >= 0.005]
                if src in credit_note_sources:
                    neg = [b for b in significant if b < 0]
                    amount = round(sum(neg), 2) if neg else (min(significant) if significant else 0.0)
                elif src in {'GRN', 'PURCHASE', 'AP_INVOICE', 'SALES', 'BILL', 'POS'}:
                    pos = [b for b in significant if b > 0]
                    amount = round(sum(pos), 2) if pos else (max(significant) if significant else 0.0)
                elif significant:
                    # Largest-magnitude line (one side of a cancelled pair).
                    amount = round(max(significant, key=lambda x: abs(x)), 2)
        rec['invoice_amount'] = round(amount, 2)
    return voucher_map


def _purchase_return_gl_credits_for_supplier(
    supplier_code: Any,
    payable_account: str,
) -> Dict[str, Dict[str, Any]]:
    """Find PURCHASE_RETURN GL vouchers for a supplier even when party tags are missing/wrong.

    Matches via TBLPRPOSTINGHDR / RETURNHDR supplier, then reads the payable debit on the GL voucher.
    Also backfills PARTY_TYPE/PARTY_CODE on the payable debit line when columns exist.
    """
    pcode = _norm_supplier_key(supplier_code)
    payable = _norm_gl_account_code(payable_account) or str(
        DEFAULT_PARTY_ACCOUNTS.get('supplier_payable') or '2110'
    ).strip()
    if not pcode:
        return {}
    out: Dict[str, Dict[str, Any]] = {}

    posting_rows: List[Dict[str, Any]] = []
    if _table_exists('TBLPRPOSTINGHDR'):
        posting_rows = _safe_rows(
            """
            SELECT
                LOCATIONCODE AS locationcode,
                GOODSRETURNNO AS goodsreturnno,
                SUPPLIERCODE AS suppliercode,
                TOTALAMOUNT AS totalamount,
                RETURNDATE AS returndate
            FROM TBLPRPOSTINGHDR
            WHERE SUPPLIERCODE IS NOT NULL
            """,
            {},
        ) or []
    # Fallback: posted RETURNHDR linked by supplier (when posting hdr missing).
    if not posting_rows:
        rh = _detect_table(['RETURNHDR', 'returnhdr'])
        if rh:
            h_loc = _detect_column(rh, ['LOCATIONCODE', 'locationcode'])
            h_no = _detect_column(rh, ['GOODSRETURNNO', 'goodsreturnno'])
            h_sup = _detect_column(rh, ['SUPPLIERCODE', 'suppliercode'])
            h_date = _detect_column(rh, ['RETURNDATE', 'returndate', 'POSTINGDATE', 'postingdate'])
            h_amt = _detect_column(rh, ['RETURNAMOUNT', 'returnamount', 'NETAMOUNT', 'netamount'])
            h_type = _detect_column(rh, ['RETURNTYPE', 'returntype'])
            if h_loc and h_no and h_sup:
                type_f = f" AND UPPER(TRIM(NVL({h_type}, 'P'))) IN ('P','R')" if h_type else ''
                posting_rows = _safe_rows(
                    f"""
                    SELECT
                        {h_loc} AS locationcode,
                        {h_no} AS goodsreturnno,
                        {h_sup} AS suppliercode,
                        NVL({h_amt or '0'}, 0) AS totalamount,
                        {h_date or h_loc} AS returndate
                    FROM {rh}
                    WHERE {h_sup} IS NOT NULL
                    {type_f}
                    """,
                    {},
                ) or []

    # Also pick up any PURCHASE_RETURN GL already party-tagged / payable-debited.
    gl_pr_rows = _safe_rows(
        f"""
        SELECT
            h.VOUCHER_NO AS voucher_no,
            h.VOUCHER_DATE AS voucher_date,
            h.REFERENCE_NO AS reference_no,
            h.NARRATION AS narration,
            h.SOURCE AS source,
            d.ACCOUNT_CODE AS account_code,
            d.PARTY_TYPE AS party_type,
            d.PARTY_CODE AS party_code,
            NVL(d.DEBIT, 0) AS debit,
            NVL(d.CREDIT, 0) AS credit
        FROM {GL_HDR_TABLE} h
        JOIN {GL_DTL_TABLE} d ON d.VOUCHER_NO = h.VOUCHER_NO
        WHERE UPPER(NVL(h.SOURCE, '')) IN ('PURCHASE_RETURN', 'PURCHASE_DEBIT_NOTE', 'RETURN')
        """,
        {},
    ) or []

    def _party_matches(raw: Any) -> bool:
        return _norm_supplier_key(raw) == pcode

    def _acc_matches(raw: Any) -> bool:
        return _norm_gl_account_code(raw).upper() == payable.upper()

    # Index GL lines by voucher.
    by_vno: Dict[str, List[Dict[str, Any]]] = {}
    for r in gl_pr_rows:
        vno = str(r.get('voucher_no') or '').strip()
        if vno:
            by_vno.setdefault(vno, []).append(dict(r))

    candidate_vnos: Set[str] = set()
    meta_by_vno: Dict[str, Dict[str, Any]] = {}

    for pr in posting_rows:
        if not _party_matches(pr.get('suppliercode')):
            continue
        loc = pr.get('locationcode')
        try:
            loc_i = int(loc)
        except (TypeError, ValueError):
            loc_i = loc
        grn_raw = pr.get('goodsreturnno')
        n = 0
        try:
            n = int(billno_numeric_part(grn_raw) or 0)
        except Exception:
            try:
                n = int(float(str(grn_raw or '0').strip()))
            except Exception:
                n = 0
        grn_s = str(grn_raw or '').strip()
        cands = [
            str(f'PR-{loc_i}-{grn_s}')[:30],
            str(f'PR-{loc_i}-{n}')[:30] if n > 0 else '',
            str(f'PR-{grn_s}')[:30],
            str(f'PR-{n}')[:30] if n > 0 else '',
        ]
        # Strict ref match only (avoid short numeric false positives like "1"/"2").
        ref_needles = {
            x.upper()
            for x in (
                f'PR-{grn_s}',
                f'PR-{n}' if n > 0 else '',
                grn_s if len(grn_s) >= 4 else '',
            )
            if x
        }
        narr_needles = {
            x.upper()
            for x in (
                f'PURCHASE RETURN {grn_s}',
                f'PURCHASE RETURN {n}' if n > 0 else '',
                f'PR {grn_s}',
                f'PR {n}' if n > 0 else '',
            )
            if x
        }
        for vno, lines in by_vno.items():
            ref_u = str(lines[0].get('reference_no') or '').strip().upper()
            nar_u = str(lines[0].get('narration') or '').strip().upper()
            vno_u = str(vno or '').strip().upper()
            if (
                any(vno_u == str(c).upper() for c in cands if c)
                or any(ref_u == needle or ref_u.endswith(needle) for needle in ref_needles)
                or any(needle in nar_u for needle in narr_needles)
            ):
                if any(
                    _acc_matches(ln.get('account_code')) and float(ln.get('debit') or 0) > 0.005
                    for ln in lines
                ) or any(
                    str(ln.get('party_type') or '').upper() == 'SUPPLIER' and _party_matches(ln.get('party_code'))
                    for ln in lines
                ):
                    cands.append(vno)
        for c in cands:
            c = str(c or '').strip()
            if not c:
                continue
            candidate_vnos.add(c)
            meta_by_vno.setdefault(
                c,
                {
                    'voucher_date': _to_iso_date(pr.get('returndate')),
                    'reference_no': f'PR-{grn_raw}',
                    'narration': f'Purchase Return {grn_raw}',
                    'source': 'PURCHASE_RETURN',
                    'totalamount': float(pr.get('totalamount') or 0),
                },
            )

    # Include vouchers already tagged to this supplier or payable-debit without tag.
    for vno, lines in by_vno.items():
        tagged = any(
            str(ln.get('party_type') or '').strip().upper() == 'SUPPLIER'
            and _party_matches(ln.get('party_code'))
            for ln in lines
        )
        payable_dr = any(
            _acc_matches(ln.get('account_code')) and float(ln.get('debit') or 0) > 0.005
            for ln in lines
        )
        if tagged or (payable_dr and vno in candidate_vnos):
            candidate_vnos.add(vno)
            if vno not in meta_by_vno and lines:
                meta_by_vno[vno] = {
                    'voucher_date': _to_iso_date(lines[0].get('voucher_date')),
                    'reference_no': lines[0].get('reference_no'),
                    'narration': lines[0].get('narration'),
                    'source': lines[0].get('source') or 'PURCHASE_RETURN',
                    'totalamount': 0.0,
                }

    # Resolve voucher nos that exist in GL (case-insensitive).
    gl_keys = {_norm_voucher_key(k): k for k in by_vno.keys()}
    for cand in list(candidate_vnos):
        real = gl_keys.get(_norm_voucher_key(cand))
        if not real:
            # try load detail if missing from bulk (rare)
            continue
        lines = by_vno.get(real) or []
        # Payable open credit = Dr payable − Cr payable (negative invoice_amount for AP).
        dr = sum(float(ln.get('debit') or 0) for ln in lines if _acc_matches(ln.get('account_code')))
        cr = sum(float(ln.get('credit') or 0) for ln in lines if _acc_matches(ln.get('account_code')))
        # If payable lines missing (wrong account), fall back to any supplier-tagged Dr−Cr.
        if abs(dr) < 0.005 and abs(cr) < 0.005:
            dr = sum(
                float(ln.get('debit') or 0)
                for ln in lines
                if str(ln.get('party_type') or '').upper() == 'SUPPLIER' and _party_matches(ln.get('party_code'))
            )
            cr = sum(
                float(ln.get('credit') or 0)
                for ln in lines
                if str(ln.get('party_type') or '').upper() == 'SUPPLIER' and _party_matches(ln.get('party_code'))
            )
        # Payable mode amount = credit − debit → PR debit is negative credit.
        invoice_amount = round(cr - dr, 2)
        if abs(invoice_amount) < 0.005:
            # Last resort: posting hdr total as credit.
            meta = meta_by_vno.get(cand) or meta_by_vno.get(real) or {}
            tot = float(meta.get('totalamount') or 0)
            if tot > 0.005:
                invoice_amount = round(-tot, 2)
        if abs(invoice_amount) < 0.005:
            continue
        # Prefer negative (credit). If somehow positive on payable for PR, flip when source is return.
        src = str((meta_by_vno.get(real) or meta_by_vno.get(cand) or {}).get('source') or lines[0].get('source') or '').upper()
        if invoice_amount > 0 and src in ('PURCHASE_RETURN', 'PURCHASE_DEBIT_NOTE', 'RETURN'):
            invoice_amount = -invoice_amount
        meta = meta_by_vno.get(real) or meta_by_vno.get(cand) or {}
        out[real] = {
            'voucher_no': real,
            'voucher_date': meta.get('voucher_date') or _to_iso_date(lines[0].get('voucher_date')),
            'reference_no': meta.get('reference_no') or lines[0].get('reference_no'),
            'narration': meta.get('narration') or lines[0].get('narration'),
            'source': meta.get('source') or lines[0].get('source') or 'PURCHASE_RETURN',
            'invoice_amount': invoice_amount,
        }
        # Backfill party on payable debit lines so subsequent party queries see this PR.
        try:
            party_col = _detect_column(GL_DTL_TABLE, ['PARTY_TYPE', 'party_type'])
            code_col = _detect_column(GL_DTL_TABLE, ['PARTY_CODE', 'party_code'])
            if party_col and code_col:
                with _get_connection() as conn:
                    with conn.cursor() as cur:
                        cur.execute(
                            f"""
                            UPDATE {GL_DTL_TABLE}
                               SET PARTY_TYPE = 'SUPPLIER',
                                   PARTY_CODE = :pcode
                             WHERE VOUCHER_NO = :vno
                               AND NVL(DEBIT, 0) > 0
                               AND (
                                    UPPER(TRIM(TO_CHAR(ACCOUNT_CODE))) = :acc
                                    OR LTRIM(TRIM(TO_CHAR(ACCOUNT_CODE)), '0')
                                       = LTRIM(:acc, '0')
                               )
                               AND (
                                    PARTY_TYPE IS NULL
                                    OR TRIM(TO_CHAR(PARTY_TYPE)) = ''
                                    OR PARTY_CODE IS NULL
                                    OR TRIM(TO_CHAR(PARTY_CODE)) = ''
                               )
                            """,
                            {'pcode': pcode, 'vno': real, 'acc': payable.upper()},
                        )
                    conn.commit()
        except Exception:
            pass

    return out


def get_supplier_open_invoices_for_payment(supplier_code: Any) -> List[Dict[str, Any]]:
    """Return open supplier documents (voucher-level) for AP payment allocation.

    Includes GRN/AP invoices and **manual journals** when the payable line is party-tagged
    (``PARTY_TYPE=SUPPLIER``), not only rows on accounts with COA type LIABILITY.
    Also includes purchase-return / debit-note credits linked by posting header supplier
    even when GL party tags were missing on older posts.
    """
    ensure_ap_payment_tables()
    pcode = _norm_supplier_key(supplier_code)
    if not pcode:
        return []
    sup = get_supplier_master_by_code(pcode) or {}
    payable_acc = str(sup.get('payableaccount') or '').strip() or str(DEFAULT_PARTY_ACCOUNTS.get('supplier_payable') or '2110').strip()
    rows = _party_gl_voucher_balance_rows('SUPPLIER', pcode)
    voucher_map = _voucher_open_amount_from_party_rows(
        rows,
        balance_mode='payable',
        primary_account=payable_acc,
        coa_types=_coa_type_map_for_payment(),
    )
    # Merge purchase-return credits that party tagging missed.
    try:
        for vno, rec in (_purchase_return_gl_credits_for_supplier(pcode, payable_acc) or {}).items():
            existing = voucher_map.get(vno)
            if existing and abs(float(existing.get('invoice_amount') or 0)) >= 0.005:
                continue
            # Also skip if same voucher under different key casing.
            hit = False
            for k, val in list(voucher_map.items()):
                if _norm_voucher_key(k) == _norm_voucher_key(vno):
                    if abs(float(val.get('invoice_amount') or 0)) < 0.005:
                        voucher_map[k] = {
                            'voucher_no': k,
                            'voucher_date': rec.get('voucher_date'),
                            'reference_no': rec.get('reference_no'),
                            'narration': rec.get('narration'),
                            'source': rec.get('source'),
                            'invoice_amount': rec.get('invoice_amount'),
                        }
                    hit = True
                    break
            if not hit:
                voucher_map[vno] = {
                    'voucher_no': vno,
                    'voucher_date': rec.get('voucher_date'),
                    'reference_no': rec.get('reference_no'),
                    'narration': rec.get('narration'),
                    'source': rec.get('source'),
                    'invoice_amount': rec.get('invoice_amount'),
                }
    except Exception:
        logger = __import__('logging').getLogger(__name__)
        logger.debug('merge purchase return AP credits failed', exc_info=True)

    alloc_rows = _safe_rows(
        f"""
        SELECT INVOICE_VOUCHER_NO AS invoice_voucher_no, SUM(ALLOCATED_AMOUNT) AS allocated_amount
        FROM {AP_ALLOC_TABLE}
        WHERE SUPPLIER_CODE = :pcode
        GROUP BY INVOICE_VOUCHER_NO
        """,
        {'pcode': pcode},
    )
    payment_alloc_rows = _safe_rows(
        f"""
        SELECT PAYMENT_VOUCHER_NO AS payment_voucher_no, SUM(ALLOCATED_AMOUNT) AS allocated_amount
        FROM {AP_ALLOC_TABLE}
        WHERE SUPPLIER_CODE = :pcode
        GROUP BY PAYMENT_VOUCHER_NO
        """,
        {'pcode': pcode},
    )
    allocated_map = {
        _norm_voucher_key(r.get('invoice_voucher_no')): round(float(r.get('allocated_amount') or 0), 2)
        for r in alloc_rows or []
    }
    payment_allocated_map = {
        _norm_voucher_key(r.get('payment_voucher_no')): round(float(r.get('allocated_amount') or 0), 2)
        for r in payment_alloc_rows or []
    }
    out: List[Dict[str, Any]] = []
    for vno, rec in voucher_map.items():
        invoice_amount = round(float(rec.get('invoice_amount') or 0), 2)
        if abs(invoice_amount) < 0.005:
            continue
        vkey = _norm_voucher_key(vno)
        allocated = round(float(allocated_map.get(vkey, 0.0) or 0), 2)
        payment_applied = round(float(payment_allocated_map.get(vkey, 0.0) or 0), 2)
        if invoice_amount > 0:
            open_amount = round(invoice_amount - allocated, 2)
        else:
            open_amount = round(invoice_amount + allocated + payment_applied, 2)
        if abs(open_amount) < 0.005:
            continue
        is_credit_doc = invoice_amount < 0
        is_credit = is_credit_doc and open_amount < 0
        display_allocated = round(allocated + payment_applied, 2) if is_credit_doc else allocated
        src = str(rec.get('source') or '').strip().upper()
        if is_credit_doc and src in ('PURCHASE_RETURN', 'RETURN'):
            hint = 'Purchase return credit'
        elif is_credit_doc:
            hint = 'Supplier credit (Dr payable journal)'
        else:
            hint = 'Payable'
        out.append({
            'voucher_no': vno,
            'voucher_date': rec.get('voucher_date'),
            'reference_no': rec.get('reference_no'),
            'narration': rec.get('narration'),
            'source': rec.get('source'),
            'invoice_amount': invoice_amount,
            'allocated_amount': display_allocated,
            'open_amount': open_amount,
            'is_payable': invoice_amount > 0 and open_amount > 0,
            'is_credit': is_credit,
            'is_credit_doc': is_credit_doc,
            'credit_available': round(abs(open_amount), 2) if is_credit else 0.0,
            'balance_hint': hint,
        })
    out.sort(key=lambda x: (0 if x.get('is_payable') else 1, x.get('voucher_date') or '', x.get('voucher_no') or ''))
    return out

def parse_open_document_payment_allocations(open_rows: List[Dict[str, Any]], invoice_vouchers: List[Any], allocate_amounts: List[Any]) -> Tuple[List[Dict[str, Any]], float, float, List[str]]:
    """Parse payment/receipt allocation form rows against open document list.

    Returns (allocations, invoice_total, credit_total, error_messages).
    Positive-open rows add to invoice_total; negative-open (credit) rows add to credit_total.
    """
    open_by = {_norm_voucher_key(r.get('voucher_no')): r for r in open_rows or [] if r.get('voucher_no')}
    allocations: List[Dict[str, Any]] = []
    invoice_total = 0.0
    credit_total = 0.0
    errors: List[str] = []
    n = max(len(invoice_vouchers or []), len(allocate_amounts or []))
    for i in range(n):
        invoice_voucher = str((invoice_vouchers[i] if i < len(invoice_vouchers) else '') or '').strip()
        allocate_raw = str((allocate_amounts[i] if i < len(allocate_amounts) else '0') or '').strip()
        try:
            allocated_amount = round(float(allocate_raw or 0), 2)
        except Exception:
            allocated_amount = 0.0
        if not invoice_voucher or allocated_amount <= 0:
            continue
        rec = open_by.get(_norm_voucher_key(invoice_voucher))
        if not rec:
            errors.append(f'Open document not found: {invoice_voucher}')
            continue
        is_credit_doc = bool(rec.get('is_credit')) or bool(rec.get('is_credit_doc')) or float(rec.get('invoice_amount') or 0) < 0
        if is_credit_doc:
            cap = round(float(rec.get('credit_available') or abs(float(rec.get('open_amount') or 0))), 2)
            if allocated_amount > cap + 0.009:
                errors.append(f'Credit for {invoice_voucher} cannot exceed {cap:.2f}.')
                continue
            credit_total += allocated_amount
        else:
            cap = round(float(rec.get('open_amount') or 0), 2)
            if allocated_amount > cap + 0.009:
                errors.append(f'Allocation for {invoice_voucher} cannot exceed open {cap:.2f}.')
                continue
            invoice_total += allocated_amount
        allocations.append({
            'invoice_voucher_no': invoice_voucher[:30],
            'allocated_amount': allocated_amount,
            'is_credit': is_credit_doc,
        })
    invoice_total = round(invoice_total, 2)
    credit_total = round(credit_total, 2)
    return (allocations, invoice_total, credit_total, errors)

def save_supplier_payment_allocations(
    payment_voucher_no: str,
    supplier_code: Any,
    allocations: List[Dict[str, Any]],
    created_by: Optional[str] = None,
    *,
    conn: Optional[Any] = None,
    commit: bool = True,
) -> None:
    """Persist payment allocations by invoice voucher for supplier."""
    ensure_ap_payment_tables()
    pcode = _norm_supplier_key(supplier_code)
    vno = str(payment_voucher_no or '').strip()
    if not pcode or not vno:
        return
    valid: List[Dict[str, Any]] = []
    for a in allocations or []:
        inv_vno = str(a.get('invoice_voucher_no') or '').strip()[:30]
        try:
            amt = round(float(a.get('allocated_amount') or 0), 2)
        except Exception:
            amt = 0.0
        if not inv_vno or amt <= 0:
            continue
        valid.append({'invoice_voucher_no': inv_vno, 'allocated_amount': amt})
    if not valid:
        return

    def _insert_rows(active_cur: Any) -> None:
        for i in valid:
            active_cur.execute(
                f"""
                INSERT INTO {AP_ALLOC_TABLE}
                    (ALLOC_ID, PAYMENT_VOUCHER_NO, SUPPLIER_CODE, INVOICE_VOUCHER_NO, ALLOCATED_AMOUNT, CREATED_BY)
                VALUES
                    ({AP_ALLOC_SEQ}.NEXTVAL, :pmt, :scode, :inv, :amt, :usr)
                """,
                {
                    'pmt': vno[:30],
                    'scode': pcode[:50],
                    'inv': i['invoice_voucher_no'],
                    'amt': i['allocated_amount'],
                    'usr': (created_by or '').strip()[:50] or None,
                },
            )

    if conn is None:
        with _get_connection() as conn_own:
            with conn_own.cursor() as cur:
                _insert_rows(cur)
            if commit:
                conn_own.commit()
        return
    with conn.cursor() as cur:
        _insert_rows(cur)
    if commit:
        conn.commit()


def get_ar_discount_allowed_account() -> str:
    """GL account for customer settlement discount (Discount Allowed). Env: AR_DISCOUNT_ALLOWED_ACCOUNT."""
    import os as _os
    raw = (
        (_os.getenv('AR_DISCOUNT_ALLOWED_ACCOUNT') or '').strip()
        or str(DEFAULT_PARTY_ACCOUNTS.get('ar_discount_allowed') or '5010')
    )
    return _norm_gl_account_code(raw) or '5010'


def get_ap_discount_received_account() -> str:
    """GL account for supplier settlement discount (Discount Received). Env: AP_DISCOUNT_RECEIVED_ACCOUNT."""
    import os as _os
    raw = (
        (_os.getenv('AP_DISCOUNT_RECEIVED_ACCOUNT') or '').strip()
        or str(DEFAULT_PARTY_ACCOUNTS.get('ap_discount_received') or '4010')
    )
    return _norm_gl_account_code(raw) or '4010'


def ap_receipt_voucher_totals(voucher: Optional[Dict[str, Any]]) -> Dict[str, float]:
    """Split AP payment voucher GL lines into invoices, credits, settlement discount, and net cash."""
    lines = (voucher or {}).get('lines') or []
    payable_codes: set[str] = set()
    for ln in lines:
        if str(ln.get('party_type') or '').strip().upper() != 'SUPPLIER':
            continue
        ac = _norm_gl_account_code(ln.get('account_code')).upper()
        if ac:
            payable_codes.add(ac)
    invoice_total = 0.0
    credit_total = 0.0
    discount_total = 0.0
    net_cash = 0.0
    for ln in lines:
        ac = _norm_gl_account_code(ln.get('account_code')).upper()
        dr = float(ln.get('debit') or 0)
        cr = float(ln.get('credit') or 0)
        rm = str(ln.get('remarks') or '').lower()
        if 'settlement discount' in rm:
            discount_total += max(0.0, cr)
            continue
        if ac in payable_codes or 'invoice' in rm or 'credits applied' in rm:
            if dr > 0:
                invoice_total += dr
            if cr > 0:
                credit_total += cr
        elif cr > 0 and dr <= 0:
            net_cash += cr
    return {
        'invoice_total': round(invoice_total, 2),
        'credit_total': round(credit_total, 2),
        'discount_total': round(discount_total, 2),
        'net_cash': round(net_cash, 2),
    }


def ar_receipt_voucher_totals(voucher: Optional[Dict[str, Any]]) -> Dict[str, float]:
    """Split AR receipt voucher GL lines into invoices, credits, settlement discount, and net cash."""
    lines = (voucher or {}).get('lines') or []
    recv_codes: set[str] = set()
    for ln in lines:
        if str(ln.get('party_type') or '').strip().upper() != 'CUSTOMER':
            continue
        ac = _norm_gl_account_code(ln.get('account_code')).upper()
        if ac:
            recv_codes.add(ac)
    invoice_total = 0.0
    credit_total = 0.0
    discount_total = 0.0
    net_cash = 0.0
    for ln in lines:
        ac = _norm_gl_account_code(ln.get('account_code')).upper()
        dr = float(ln.get('debit') or 0)
        cr = float(ln.get('credit') or 0)
        rm = str(ln.get('remarks') or '').lower()
        if 'settlement discount' in rm:
            discount_total += max(0.0, dr)
            continue
        if ac in recv_codes or 'invoice' in rm or 'credits applied' in rm:
            if cr > 0:
                invoice_total += cr
            if dr > 0:
                credit_total += dr
        elif dr > 0 and cr <= 0:
            net_cash += dr
    return {
        'invoice_total': round(invoice_total, 2),
        'credit_total': round(credit_total, 2),
        'discount_total': round(discount_total, 2),
        'net_cash': round(net_cash, 2),
    }

def get_ap_payment_allocations_by_payment_voucher(payment_voucher_no: str, supplier_code: Any = None) -> List[Dict[str, Any]]:
    """Invoice allocation rows stored for one supplier payment GL voucher (AP_SUPPLIER_PAYMENT_ALLOC)."""
    ensure_ap_payment_tables()
    v = str(payment_voucher_no or '').strip()[:30]
    if not v:
        return []
    try:
        rows = _safe_rows(f'\n            SELECT INVOICE_VOUCHER_NO AS invoice_voucher_no,\n                   ALLOCATED_AMOUNT AS allocated_amount,\n                   SUPPLIER_CODE AS supplier_code\n            FROM {AP_ALLOC_TABLE}\n            WHERE PAYMENT_VOUCHER_NO = :vno\n            ORDER BY INVOICE_VOUCHER_NO\n            ', {'vno': v})
        out = list(rows or [])
        pcode = _norm_supplier_key(supplier_code or (out[0].get('supplier_code') if out else ''))
        credit_vouchers: set[str] = set()
        if pcode:
            for doc in get_supplier_open_invoices_for_payment(pcode) or []:
                if doc.get('is_credit_doc') or float(doc.get('invoice_amount') or 0) < 0:
                    credit_vouchers.add(_norm_voucher_key(doc.get('voucher_no')))
            # Closed credits no longer in open list — detect from original GL sign
            if out:
                party_rows = _party_gl_voucher_balance_rows('SUPPLIER', pcode)
                sup = get_supplier_master_by_code(pcode) or {}
                payable_acc = _norm_gl_account_code(sup.get('payableaccount') or DEFAULT_PARTY_ACCOUNTS.get('supplier_payable') or '2110')
                vm = _voucher_open_amount_from_party_rows(party_rows, balance_mode='payable', primary_account=payable_acc, coa_types=_coa_type_map_for_payment())
                for inv_vno in {str(r.get('invoice_voucher_no') or '').strip() for r in out}:
                    if _norm_voucher_key(inv_vno) in credit_vouchers:
                        continue
                    rec = vm.get(inv_vno)
                    if not rec:
                        for k, val in vm.items():
                            if _norm_voucher_key(k) == _norm_voucher_key(inv_vno):
                                rec = val
                                break
                    if rec and float(rec.get('invoice_amount') or 0) < 0:
                        credit_vouchers.add(_norm_voucher_key(inv_vno))
        for r in out:
            invk = _norm_voucher_key(r.get('invoice_voucher_no'))
            r['is_credit'] = invk in credit_vouchers
        return out
    except Exception:
        return []

def ensure_ar_payment_tables() -> bool:
    """Create AR customer payment allocation table if missing."""
    ensure_gl_tables()
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                try:
                    cur.execute('SELECT 1 FROM user_sequences WHERE sequence_name = :n', {'n': AR_ALLOC_SEQ})
                    if cur.fetchone() is None:
                        cur.execute(f'CREATE SEQUENCE {AR_ALLOC_SEQ} START WITH 1 INCREMENT BY 1 NOCACHE')
                except Exception:
                    pass
        if not _table_exists(AR_ALLOC_TABLE):
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute(f'\n                        CREATE TABLE {AR_ALLOC_TABLE} (\n                            ALLOC_ID NUMBER PRIMARY KEY,\n                            PAYMENT_VOUCHER_NO VARCHAR2(30) NOT NULL,\n                            CUSTOMER_CODE VARCHAR2(50) NOT NULL,\n                            INVOICE_VOUCHER_NO VARCHAR2(30) NOT NULL,\n                            ALLOCATED_AMOUNT NUMBER(18,2) DEFAULT 0 NOT NULL,\n                            CREATED_BY VARCHAR2(50),\n                            CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL\n                        )\n                        ')
                    conn.commit()
        return True
    except Exception as e:
        print(f'[ERROR ensure_ar_payment_tables] {e}')
        return False

def get_customer_open_invoices_for_payment(customer_code: Any) -> List[Dict[str, Any]]:
    """Return open customer documents (voucher-level) for AR receipt allocation.

    Includes sales/opening entries and **manual journals** when the receivable line is
    party-tagged (``PARTY_TYPE=CUSTOMER``), not only rows on accounts with COA type ASSET.
    """
    ensure_ar_payment_tables()
    pcode = _norm_supplier_key(customer_code)
    if not pcode:
        return []
    cust = get_customer_master_by_code(pcode) or {}
    recv_acc = _norm_gl_account_code(cust.get('receivableaccount') or DEFAULT_PARTY_ACCOUNTS.get('customer_receivable') or '1200')
    rows = _party_gl_voucher_balance_rows('CUSTOMER', pcode)
    voucher_map = _voucher_open_amount_from_party_rows(
        rows,
        balance_mode='receivable',
        primary_account=recv_acc,
        coa_types=_coa_type_map_for_payment(),
    )
    alloc_rows = _safe_rows(
        f"""
        SELECT INVOICE_VOUCHER_NO AS invoice_voucher_no, SUM(ALLOCATED_AMOUNT) AS allocated_amount
        FROM {AR_ALLOC_TABLE}
        WHERE CUSTOMER_CODE = :pcode
        GROUP BY INVOICE_VOUCHER_NO
        """,
        {'pcode': pcode},
    )
    payment_alloc_rows = _safe_rows(
        f"""
        SELECT PAYMENT_VOUCHER_NO AS payment_voucher_no, SUM(ALLOCATED_AMOUNT) AS allocated_amount
        FROM {AR_ALLOC_TABLE}
        WHERE CUSTOMER_CODE = :pcode
        GROUP BY PAYMENT_VOUCHER_NO
        """,
        {'pcode': pcode},
    )
    allocated_map = {
        _norm_voucher_key(r.get('invoice_voucher_no')): round(float(r.get('allocated_amount') or 0), 2)
        for r in alloc_rows or []
    }
    payment_allocated_map = {
        _norm_voucher_key(r.get('payment_voucher_no')): round(float(r.get('allocated_amount') or 0), 2)
        for r in payment_alloc_rows or []
    }

    def _extract_sales_billno(voucher_no: Any, reference_no: Any) -> Optional[int]:
        # SI / SR (and SIC / SRC credit variants): SI-82, SI-1-82, SR-164, SR-1-164
        for raw in (reference_no, voucher_no):
            s = str(raw or '').strip().upper()
            if not s:
                continue
            m = re.match(r'^(?:SI|SR|SIC|SRC)-(\d+)$', s)
            if m:
                try:
                    return int(m.group(1))
                except Exception:
                    pass
            m = re.match(r'^(?:SI|SR|SIC|SRC)-.+-(\d+)$', s)
            if m:
                try:
                    return int(m.group(1))
                except Exception:
                    pass
            if s.isdigit():
                try:
                    return int(s)
                except Exception:
                    pass
        return None

    billno_by_voucher: Dict[str, int] = {}
    for vno, rec in voucher_map.items():
        billno = _extract_sales_billno(vno, rec.get('reference_no'))
        if billno is not None:
            billno_by_voucher[str(vno)] = billno

    orderno_by_billno: Dict[int, str] = {}
    billnos = sorted({int(b) for b in billno_by_voucher.values() if b is not None})
    if billnos:
        # Oracle ORA-01795: max 1000 expressions in an IN list
        chunk_size = 900
        try:
            for offset in range(0, len(billnos), chunk_size):
                chunk = billnos[offset:offset + chunk_size]
                placeholders = ','.join([f':b{i}' for i in range(len(chunk))])
                params = {f'b{i}': str(int(chunk[i])) for i in range(len(chunk))}
                for table_literal in ('BILLHDR', 'BILLHDRHISTORY'):
                    tbl = _detect_table([table_literal, table_literal.lower()])
                    if not tbl:
                        continue
                    billno_col = _detect_column(tbl, ['BILLNO', 'BILL_NO', 'billno']) or 'BILLNO'
                    orderno_col = _detect_column(tbl, ['ORDERNO', 'ORDER_NO', 'orderno'])
                    if not orderno_col:
                        continue
                    order_rows = _safe_rows(
                        f"""
                        SELECT {billno_col} AS billno, {orderno_col} AS orderno
                        FROM {tbl}
                        WHERE TRIM(TO_CHAR({billno_col})) IN ({placeholders})
                        """,
                        params,
                    ) or []
                    for r in order_rows:
                        try:
                            bno = billno_numeric_part(r.get('billno'))
                            if bno <= 0:
                                bno = int(r.get('billno'))
                        except Exception:
                            continue
                        if bno <= 0:
                            continue
                        ono = str(r.get('orderno') or '').strip()
                        if not ono:
                            continue
                        # Prefer first non-empty (BILLHDR queried before history)
                        if bno not in orderno_by_billno:
                            orderno_by_billno[bno] = ono
        except Exception:
            orderno_by_billno = {}

    out: List[Dict[str, Any]] = []
    for vno, rec in voucher_map.items():
        invoice_amount = round(float(rec.get('invoice_amount') or 0), 2)
        if abs(invoice_amount) < 0.005:
            continue
        vkey = _norm_voucher_key(vno)
        open_amount, display_allocated = _ar_open_amount_from_allocations(
            invoice_amount, vkey, allocated_map, payment_allocated_map,
        )
        if abs(open_amount) < 0.005:
            continue
        is_credit_doc = invoice_amount < 0
        is_credit = is_credit_doc and open_amount < 0
        billno = billno_by_voucher.get(str(vno))
        orderno = orderno_by_billno.get(billno, '') if billno is not None else ''
        out.append({
            'voucher_no': vno,
            'voucher_date': rec.get('voucher_date'),
            'orderno': orderno,
            'reference_no': rec.get('reference_no'),
            'narration': rec.get('narration'),
            'source': rec.get('source'),
            'invoice_amount': invoice_amount,
            'allocated_amount': display_allocated,
            'open_amount': open_amount,
            'is_payable': invoice_amount > 0 and open_amount > 0,
            'is_credit': is_credit,
            'is_credit_doc': is_credit_doc,
            'credit_available': round(abs(open_amount), 2) if is_credit else 0.0,
            'balance_hint': 'Receivable' if invoice_amount > 0 else 'Customer credit (Cr receivable journal)',
        })
    out.sort(key=lambda x: (0 if x.get('is_payable') else 1, x.get('voucher_date') or '', x.get('voucher_no') or ''))
    return out

def save_customer_payment_allocations(
    payment_voucher_no: str,
    customer_code: Any,
    allocations: List[Dict[str, Any]],
    created_by: Optional[str] = None,
    *,
    conn: Optional[Any] = None,
    commit: bool = True,
) -> None:
    """Persist receipt allocations by invoice voucher for customer."""
    ensure_ar_payment_tables()
    pcode = _norm_supplier_key(customer_code)
    vno = str(payment_voucher_no or '').strip()
    if not pcode or not vno:
        return
    valid: List[Dict[str, Any]] = []
    for a in allocations or []:
        inv_vno = str(a.get('invoice_voucher_no') or '').strip()[:30]
        try:
            amt = round(float(a.get('allocated_amount') or 0), 2)
        except Exception:
            amt = 0.0
        if not inv_vno or amt <= 0:
            continue
        valid.append({'invoice_voucher_no': inv_vno, 'allocated_amount': amt})
    if not valid:
        return

    def _insert_rows(active_cur: Any) -> None:
        for i in valid:
            active_cur.execute(
                f"""
                INSERT INTO {AR_ALLOC_TABLE}
                    (ALLOC_ID, PAYMENT_VOUCHER_NO, CUSTOMER_CODE, INVOICE_VOUCHER_NO, ALLOCATED_AMOUNT, CREATED_BY)
                VALUES
                    ({AR_ALLOC_SEQ}.NEXTVAL, :pmt, :ccode, :inv, :amt, :usr)
                """,
                {
                    'pmt': vno[:30],
                    'ccode': pcode[:50],
                    'inv': i['invoice_voucher_no'],
                    'amt': i['allocated_amount'],
                    'usr': (created_by or '').strip()[:50] or None,
                },
            )

    if conn is None:
        with _get_connection() as conn_own:
            with conn_own.cursor() as cur:
                _insert_rows(cur)
            if commit:
                conn_own.commit()
        return
    with conn.cursor() as cur:
        _insert_rows(cur)
    if commit:
        conn.commit()

def get_ar_payment_allocations_by_payment_voucher(payment_voucher_no: str, customer_code: Any = None) -> List[Dict[str, Any]]:
    """Invoice allocation rows stored for one customer receipt GL voucher."""
    ensure_ar_payment_tables()
    v = str(payment_voucher_no or '').strip()[:30]
    if not v:
        return []
    try:
        rows = _safe_rows(f'\n            SELECT INVOICE_VOUCHER_NO AS invoice_voucher_no,\n                   ALLOCATED_AMOUNT AS allocated_amount,\n                   CUSTOMER_CODE AS customer_code\n            FROM {AR_ALLOC_TABLE}\n            WHERE PAYMENT_VOUCHER_NO = :vno\n            ORDER BY INVOICE_VOUCHER_NO\n            ', {'vno': v})
        out = list(rows or [])
        pcode = _norm_supplier_key(customer_code or (out[0].get('customer_code') if out else ''))
        credit_vouchers: set[str] = set()
        if pcode:
            for doc in get_customer_open_invoices_for_payment(pcode) or []:
                if doc.get('is_credit_doc') or float(doc.get('invoice_amount') or 0) < 0:
                    credit_vouchers.add(_norm_voucher_key(doc.get('voucher_no')))
            if out:
                party_rows = _party_gl_voucher_balance_rows('CUSTOMER', pcode)
                cust = get_customer_master_by_code(pcode) or {}
                recv_acc = _norm_gl_account_code(cust.get('receivableaccount') or DEFAULT_PARTY_ACCOUNTS.get('customer_receivable') or '1200')
                vm = _voucher_open_amount_from_party_rows(party_rows, balance_mode='receivable', primary_account=recv_acc, coa_types=_coa_type_map_for_payment())
                for inv_vno in {str(r.get('invoice_voucher_no') or '').strip() for r in out}:
                    if _norm_voucher_key(inv_vno) in credit_vouchers:
                        continue
                    rec = vm.get(inv_vno)
                    if not rec:
                        for k, val in vm.items():
                            if _norm_voucher_key(k) == _norm_voucher_key(inv_vno):
                                rec = val
                                break
                    if rec and float(rec.get('invoice_amount') or 0) < 0:
                        credit_vouchers.add(_norm_voucher_key(inv_vno))
        for r in out:
            invk = _norm_voucher_key(r.get('invoice_voucher_no'))
            r['is_credit'] = invk in credit_vouchers
        return out
    except Exception:
        return []

def _next_voucher_no(voucher_date_iso: str) -> str:
    date_tag = (voucher_date_iso or datetime.now().strftime('%Y-%m-%d')).replace('-', '')
    prefix = f'JV{date_tag}-'
    rows = _safe_rows(f'SELECT MAX(VOUCHER_NO) AS max_no FROM {GL_HDR_TABLE} WHERE VOUCHER_NO LIKE :pfx', {'pfx': f'{prefix}%'})
    max_no = (rows[0].get('max_no') if rows else None) or ''
    seq = 1
    if isinstance(max_no, str) and '-' in max_no:
        tail = max_no.split('-')[-1]
        if tail.isdigit():
            seq = int(tail) + 1
    return f'{prefix}{seq:04d}'


def _next_voucher_no_from_cursor(cur: Any, voucher_date_iso: str) -> str:
    """Next JV voucher number using ``cur`` (same DB transaction as inserts)."""
    date_tag = (voucher_date_iso or datetime.now().strftime('%Y-%m-%d')).replace('-', '')
    prefix = f'JV{date_tag}-'
    cur.execute(f'SELECT MAX(VOUCHER_NO) AS max_no FROM {GL_HDR_TABLE} WHERE VOUCHER_NO LIKE :pfx', {'pfx': f'{prefix}%'})
    row = cur.fetchone()
    max_no = ''
    if row is not None and row[0] is not None:
        max_no = str(row[0]).strip()
    seq = 1
    if isinstance(max_no, str) and '-' in max_no:
        tail = max_no.split('-')[-1]
        if tail.isdigit():
            seq = int(tail) + 1
    return f'{prefix}{seq:04d}'


def create_gl_journal_entry(
    voucher_date: Optional[str],
    reference_no: Optional[str],
    narration: Optional[str],
    lines: List[Dict[str, Any]],
    created_by: Optional[str] = None,
    source: str = 'MANUAL',
    dimension_defaults: Optional[Dict[str, Any]] = None,
    *,
    conn: Optional[Any] = None,
    commit: bool = True,
    skip_period_lock: bool = False,
) -> str:
    """Create a balanced journal entry and return voucher number.

    Optional **dimensions** (per line, merged with ``dimension_defaults``):
    ``cost_center`` / ``COST_CENTER``, ``department`` / ``DEPARTMENT``, ``project`` / ``PROJECT``.
    Mandatory dimensions per account are configured in ``GL_ACCOUNT_DIMENSION_RULE``; see
    :func:`upsert_gl_account_dimension_rule` and ``docs/GL_DIMENSIONS.md``.

    *skip_period_lock*: used by Period Closing reopen (unlock + reverse in one TX) where the
    period row is already updated to OPEN in the same uncommitted transaction.
    """
    if conn is None:
        ensure_gl_tables()
        ensure_gl_account_dimension_rule_table()
    # Block postings into closed accounting periods (Period Closing module).
    # Closing journals use source PERIOD_CLOSE and are allowed.
    if not skip_period_lock and (source or '').strip().upper() != 'PERIOD_CLOSE':
        try:
            from addons.accounts.period_closing_db import is_period_closed_for_date
            _lock_msg = is_period_closed_for_date(voucher_date)
            if _lock_msg:
                raise ValueError(_lock_msg)
        except ValueError:
            raise
        except Exception:
            pass
    valid_lines: List[Dict[str, Any]] = []
    debit_total = 0.0
    credit_total = 0.0
    for ln in lines or []:
        account_code = str(ln.get('account_code') or '').strip()[:20]
        if not account_code:
            continue
        try:
            debit = float(ln.get('debit') or 0)
        except Exception:
            debit = 0.0
        try:
            credit = float(ln.get('credit') or 0)
        except Exception:
            credit = 0.0
        if debit < 0:
            debit = 0.0
        if credit < 0:
            credit = 0.0
        if debit == 0 and credit == 0:
            continue
        if debit > 0 and credit > 0:
            raise ValueError(f'Account {account_code}: debit and credit both cannot be > 0.')
        valid_lines.append({'account_code': account_code, 'debit': round(debit, 2), 'credit': round(credit, 2), 'remarks': str(ln.get('remarks') or '').strip()[:250] or None, 'party_type': str(ln.get('party_type') or '').strip()[:20] or None, 'party_code': str(ln.get('party_code') or '').strip()[:50] or None, '_src': dict(ln) if isinstance(ln, dict) else {}})
        debit_total += debit
        credit_total += credit
    if len(valid_lines) < 2:
        raise ValueError('Journal entry requires at least two lines.')
    if round(debit_total, 2) != round(credit_total, 2):
        raise ValueError('Journal entry is not balanced (total debit must equal total credit).')
    coa_map = {(r.get('code') or '').strip(): r for r in get_all_chart_of_accounts()}
    for ln in valid_lines:
        if ln['account_code'] not in coa_map:
            raise ValueError(f"Account code not found in Chart of Accounts: {ln['account_code']}")
    for ln in valid_lines:
        src = ln.pop('_src', {}) or {}
        resolved = resolve_gl_line_dimensions(src, dimension_defaults)
        _validate_resolved_gl_dimensions(ln['account_code'], resolved)
        ln['cost_center'] = resolved.get('cost_center')
        ln['department'] = resolved.get('department')
        ln['project'] = resolved.get('project')
    dtl_colset = {c.upper() for c in _get_table_columns(GL_DTL_TABLE) or []}
    has_cc = 'COST_CENTER' in dtl_colset
    has_dp = 'DEPARTMENT' in dtl_colset
    has_pj = 'PROJECT' in dtl_colset
    vdate = _to_iso_date(voucher_date) or datetime.now().strftime('%Y-%m-%d')

    def _insert_gl_voucher_lines(active_cur: Any, vno: str) -> None:
        active_cur.execute(
            f"\n                INSERT INTO {GL_HDR_TABLE}\n                    (VOUCHER_NO, VOUCHER_DATE, REFERENCE_NO, NARRATION, SOURCE, CREATED_BY)\n                VALUES\n                    (:vno, TO_DATE(:vdate, 'YYYY-MM-DD'), :ref, :nar, :src, :usr)\n                ",
            {'vno': vno, 'vdate': vdate, 'ref': (reference_no or '').strip()[:50] or None, 'nar': (narration or '').strip()[:500] or None, 'src': (source or 'MANUAL').strip()[:20] or 'MANUAL', 'usr': (created_by or '').strip()[:50] or None},
        )
        for i, ln in enumerate(valid_lines, start=1):
            active_cur.execute(f'SELECT {GL_DTL_SEQ}.NEXTVAL FROM DUAL')
            line_id = active_cur.fetchone()[0]
            cols = ['LINE_ID', 'VOUCHER_NO', 'LINE_NO', 'ACCOUNT_CODE', 'DEBIT', 'CREDIT', 'REMARKS', 'PARTY_TYPE', 'PARTY_CODE']
            vals = [':lid', ':vno', ':lno', ':ac', ':dr', ':cr', ':rm', ':pt', ':pc']
            params_i: Dict[str, Any] = {'lid': line_id, 'vno': vno, 'lno': i, 'ac': ln['account_code'], 'dr': ln['debit'], 'cr': ln['credit'], 'rm': ln['remarks'], 'pt': ln['party_type'], 'pc': ln['party_code']}
            if has_cc:
                cols.append('COST_CENTER')
                vals.append(':cc')
                params_i['cc'] = ln.get('cost_center')
            if has_dp:
                cols.append('DEPARTMENT')
                vals.append(':dp')
                params_i['dp'] = ln.get('department')
            if has_pj:
                cols.append('PROJECT')
                vals.append(':pj')
                params_i['pj'] = ln.get('project')
            ins_sql = f"INSERT INTO {GL_DTL_TABLE} ({', '.join(cols)}) VALUES ({', '.join(vals)})"
            active_cur.execute(ins_sql, params_i)

    if conn is None:
        voucher_no = _next_voucher_no(vdate)
        with _get_connection() as conn_own:
            with conn_own.cursor() as cur:
                _insert_gl_voucher_lines(cur, voucher_no)
            conn_own.commit()
        return voucher_no

    with conn.cursor() as cur:
        voucher_no = _next_voucher_no_from_cursor(cur, vdate)
        _insert_gl_voucher_lines(cur, voucher_no)
    if commit:
        conn.commit()
    return voucher_no

def list_gl_journal_sources() -> List[str]:
    """Distinct SOURCE values on GL vouchers (uppercase), for list filters."""
    ensure_gl_tables()
    rows = _safe_rows(
        f'''SELECT DISTINCT UPPER(TRIM(h.SOURCE)) AS src
            FROM {GL_HDR_TABLE} h
            WHERE h.SOURCE IS NOT NULL AND TRIM(h.SOURCE) IS NOT NULL
            ORDER BY 1''',
        {},
    ) or []
    out: List[str] = []
    seen = set()
    for r in rows:
        s = str(r.get('src') or r.get('SRC') or '').strip().upper()
        if s and s not in seen:
            seen.add(s)
            out.append(s)
    return out


def list_gl_journal_entries(
    date_from: Optional[str]=None,
    date_to: Optional[str]=None,
    limit: int=200,
    source: Optional[str]=None,
) -> List[Dict[str, Any]]:
    ensure_gl_tables()
    where = ['1=1']
    params: Dict[str, Any] = {}
    dfrom = _to_iso_date(date_from)
    dto = _to_iso_date(date_to)
    if dfrom:
        where.append("TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')")
        params['df'] = dfrom
    if dto:
        where.append("TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')")
        params['dt'] = dto
    src = str(source or '').strip().upper()
    if src and src not in ('ALL', '*'):
        where.append("UPPER(TRIM(NVL(h.SOURCE, ''))) = :src")
        params['src'] = src
    q = f"\n        SELECT h.VOUCHER_NO, h.VOUCHER_DATE, h.REFERENCE_NO, h.NARRATION, h.SOURCE, h.CREATED_BY, h.CREATED_AT,\n               SUM(d.DEBIT) AS TOTAL_DEBIT, SUM(d.CREDIT) AS TOTAL_CREDIT, COUNT(*) AS LINE_COUNT,\n               MAX(d.LINE_ID) AS LINE_ID\n        FROM {GL_HDR_TABLE} h\n        JOIN {GL_DTL_TABLE} d ON d.VOUCHER_NO = h.VOUCHER_NO\n        WHERE {' AND '.join(where)}\n        GROUP BY h.VOUCHER_NO, h.VOUCHER_DATE, h.REFERENCE_NO, h.NARRATION, h.SOURCE, h.CREATED_BY, h.CREATED_AT\n        ORDER BY MAX(d.LINE_ID) DESC, h.CREATED_AT DESC, h.VOUCHER_NO DESC\n    "
    rows = _safe_rows(q, params)
    return (rows or [])[:max(1, int(limit or 200))]

def get_gl_voucher_detail(voucher_no: str) -> Optional[Dict[str, Any]]:
    """Header + line items for one GL voucher (GL_VOUCHER_HDR / GL_VOUCHER_DTL)."""
    ensure_gl_tables()
    vno = (voucher_no or '').strip()
    if not vno:
        return None
    hrows = _safe_rows(f'\n        SELECT h.VOUCHER_NO, h.VOUCHER_DATE, h.REFERENCE_NO, h.NARRATION, h.SOURCE, h.CREATED_BY, h.CREATED_AT\n        FROM {GL_HDR_TABLE} h\n        WHERE h.VOUCHER_NO = :v\n        ', {'v': vno})
    if not hrows:
        return None
    h0 = hrows[0] or {}
    dtl_cols_v = {c.upper() for c in _get_table_columns(GL_DTL_TABLE) or []}
    dim_sel = ''
    if 'COST_CENTER' in dtl_cols_v:
        dim_sel += ', d.COST_CENTER'
    if 'DEPARTMENT' in dtl_cols_v:
        dim_sel += ', d.DEPARTMENT'
    if 'PROJECT' in dtl_cols_v:
        dim_sel += ', d.PROJECT'
    drows = _safe_rows(f'\n        SELECT d.LINE_NO, d.ACCOUNT_CODE, d.DEBIT, d.CREDIT, d.REMARKS, d.PARTY_TYPE, d.PARTY_CODE{dim_sel}\n        FROM {GL_DTL_TABLE} d\n        WHERE d.VOUCHER_NO = :v\n        ORDER BY d.LINE_NO\n        ', {'v': vno})
    coa = {(r.get('code') or '').strip(): r for r in get_all_chart_of_accounts()}
    lines_out: List[Dict[str, Any]] = []
    tdr, tcr = (0.0, 0.0)
    for r in drows or []:
        ac = str(r.get('account_code') or r.get('ACCOUNT_CODE') or '').strip()
        dr = float(r.get('debit') or r.get('DEBIT') or 0)
        cr = float(r.get('credit') or r.get('CREDIT') or 0)
        tdr += dr
        tcr += cr
        meta = coa.get(ac) or {}
        line_out: Dict[str, Any] = {'line_no': r.get('line_no') or r.get('LINE_NO') or 0, 'account_code': ac, 'account_name': str(meta.get('name') or '') or '—', 'debit': round(dr, 2), 'credit': round(cr, 2), 'remarks': str(r.get('remarks') or r.get('REMARKS') or '') or '—', 'party_type': str(r.get('party_type') or r.get('PARTY_TYPE') or '') or '—', 'party_code': str(r.get('party_code') or r.get('PARTY_CODE') or '') or '—'}
        if 'COST_CENTER' in dtl_cols_v:
            line_out['cost_center'] = str(r.get('cost_center') or r.get('COST_CENTER') or '') or '—'
        if 'DEPARTMENT' in dtl_cols_v:
            line_out['department'] = str(r.get('department') or r.get('DEPARTMENT') or '') or '—'
        if 'PROJECT' in dtl_cols_v:
            line_out['project'] = str(r.get('project') or r.get('PROJECT') or '') or '—'
        lines_out.append(line_out)
    _enrich_gl_lines_party_names(lines_out)
    vdt = h0.get('voucher_date') or h0.get('VOUCHER_DATE')
    if vdt is not None and (not isinstance(vdt, str)):
        try:
            vdt = vdt.strftime('%Y-%m-%d')
        except Exception:
            vdt = str(vdt)[:10]
    return {'voucher_no': h0.get('voucher_no') or h0.get('VOUCHER_NO') or vno, 'voucher_date': (str(vdt)[:10] if vdt is not None else '') or '', 'reference_no': str(h0.get('reference_no') or h0.get('REFERENCE_NO') or ''), 'narration': str(h0.get('narration') or h0.get('NARRATION') or ''), 'source': str(h0.get('source') or h0.get('SOURCE') or ''), 'created_by': str(h0.get('created_by') or h0.get('CREATED_BY') or ''), 'lines': lines_out, 'total_debit': round(tdr, 2), 'total_credit': round(tcr, 2)}


def get_gl_voucher_reversal_no(original_voucher_no: str) -> Optional[str]:
    """Return reversing voucher no if *original_voucher_no* was already reversed (SOURCE=JE_REV)."""
    ensure_gl_tables()
    orig = (original_voucher_no or '').strip()
    if not orig:
        return None
    rows = _safe_rows(
        f"""
        SELECT VOUCHER_NO
          FROM {GL_HDR_TABLE}
         WHERE REFERENCE_NO = :ref
           AND SOURCE = 'JE_REV'
         ORDER BY CREATED_AT DESC
         FETCH FIRST 1 ROW ONLY
        """,
        {'ref': orig[:50]},
    )
    if not rows:
        return None
    return str(rows[0].get('voucher_no') or rows[0].get('VOUCHER_NO') or '').strip() or None


def _gl_voucher_is_reversal_source(source: Optional[str]) -> bool:
    src = str(source or '').strip().upper()
    return src == 'JE_REV' or src.endswith('_REV')


def reverse_gl_journal_voucher(
    original_voucher_no: str,
    *,
    voucher_date: Optional[str] = None,
    remarks: str = '',
    created_by: str = '',
    conn: Optional[Any] = None,
    commit: bool = True,
    skip_period_lock: bool = False,
) -> str:
    """Post a reversing GL journal for *original_voucher_no* (swap debit/credit per line).

    Uses SOURCE ``JE_REV`` and REFERENCE_NO = original voucher. Raises ``ValueError`` if invalid
    or already reversed. When *conn* is passed, caller controls commit (set *commit* False).
    """
    orig = (original_voucher_no or '').strip()
    if not orig:
        raise ValueError('Voucher number is required.')
    if get_gl_voucher_reversal_no(orig):
        raise ValueError(f'Voucher {orig} was already reversed.')
    detail = get_gl_voucher_detail(orig)
    if not detail or not detail.get('lines'):
        raise ValueError(f'Voucher {orig} not found or has no lines.')
    src = str(detail.get('source') or '').strip()
    if _gl_voucher_is_reversal_source(src):
        raise ValueError('Cannot reverse a reversal voucher.')
    rev_lines: List[Dict[str, Any]] = []
    for ln in detail.get('lines') or []:
        if not isinstance(ln, dict):
            continue
        dr = float(ln.get('debit') or 0)
        cr = float(ln.get('credit') or 0)
        if dr == 0 and cr == 0:
            continue
        piece: Dict[str, Any] = {
            'account_code': str(ln.get('account_code') or '').strip(),
            'debit': round(cr, 2),
            'credit': round(dr, 2),
            'remarks': (f'Rev {orig} ' + str(ln.get('remarks') or '')).replace('—', '').strip()[:250],
        }
        pt = str(ln.get('party_type') or '').strip()
        pc = str(ln.get('party_code') or '').strip()
        if pt and pt != '—':
            piece['party_type'] = pt
        if pc and pc != '—':
            piece['party_code'] = pc
        for dim_key in ('cost_center', 'department', 'project'):
            dim_val = ln.get(dim_key)
            if dim_val and str(dim_val).strip() not in ('', '—'):
                piece[dim_key] = str(dim_val).strip()
        rev_lines.append(piece)
    if len(rev_lines) < 2:
        raise ValueError('Voucher has too few lines to reverse.')
    rev_date = _to_iso_date(voucher_date) or datetime.now().strftime('%Y-%m-%d')
    nar = (f'Reversal of {orig}' + (f' — {remarks}' if str(remarks or '').strip() else ''))[:500]
    user = str(created_by or '').strip()[:50] or None
    if conn is not None:
        return create_gl_journal_entry(
            rev_date,
            orig[:50],
            nar,
            rev_lines,
            created_by=user,
            source='JE_REV',
            conn=conn,
            commit=commit,
            skip_period_lock=skip_period_lock,
        )
    with _get_connection() as conn_own:
        try:
            rev_vno = create_gl_journal_entry(
                rev_date,
                orig[:50],
                nar,
                rev_lines,
                created_by=user,
                source='JE_REV',
                conn=conn_own,
                commit=False,
                skip_period_lock=skip_period_lock,
            )
            if commit:
                conn_own.commit()
            return rev_vno
        except Exception:
            try:
                conn_own.rollback()
            except Exception:
                pass
            raise


def _validate_gl_journal_lines(
    lines: List[Dict[str, Any]],
    dimension_defaults: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    """Validate journal lines and return normalized rows ready for GL insert."""
    ensure_gl_tables()
    ensure_gl_account_dimension_rule_table()
    valid_lines: List[Dict[str, Any]] = []
    debit_total = 0.0
    credit_total = 0.0
    for ln in lines or []:
        account_code = str(ln.get('account_code') or '').strip()[:20]
        if not account_code:
            continue
        try:
            debit = float(ln.get('debit') or 0)
        except Exception:
            debit = 0.0
        try:
            credit = float(ln.get('credit') or 0)
        except Exception:
            credit = 0.0
        if debit < 0:
            debit = 0.0
        if credit < 0:
            credit = 0.0
        if debit == 0 and credit == 0:
            continue
        if debit > 0 and credit > 0:
            raise ValueError(f'Account {account_code}: debit and credit both cannot be > 0.')
        valid_lines.append({
            'account_code': account_code,
            'debit': round(debit, 2),
            'credit': round(credit, 2),
            'remarks': str(ln.get('remarks') or '').strip()[:250] or None,
            'party_type': str(ln.get('party_type') or '').strip()[:20] or None,
            'party_code': str(ln.get('party_code') or '').strip()[:50] or None,
            '_src': dict(ln) if isinstance(ln, dict) else {},
        })
        debit_total += debit
        credit_total += credit
    if len(valid_lines) < 2:
        raise ValueError('Journal entry requires at least two lines.')
    if round(debit_total, 2) != round(credit_total, 2):
        raise ValueError('Journal entry is not balanced (total debit must equal total credit).')
    coa_map = {(r.get('code') or '').strip(): r for r in get_all_chart_of_accounts()}
    for ln in valid_lines:
        if ln['account_code'] not in coa_map:
            raise ValueError(f"Account code not found in Chart of Accounts: {ln['account_code']}")
    for ln in valid_lines:
        src = ln.pop('_src', {}) or {}
        resolved = resolve_gl_line_dimensions(src, dimension_defaults)
        _validate_resolved_gl_dimensions(ln['account_code'], resolved)
        ln['cost_center'] = resolved.get('cost_center')
        ln['department'] = resolved.get('department')
        ln['project'] = resolved.get('project')
    return valid_lines


def _gl_insert_detail_lines(active_cur: Any, vno: str, valid_lines: List[Dict[str, Any]], *, has_cc: bool, has_dp: bool, has_pj: bool) -> None:
    for i, ln in enumerate(valid_lines, start=1):
        active_cur.execute(f'SELECT {GL_DTL_SEQ}.NEXTVAL FROM DUAL')
        line_id = active_cur.fetchone()[0]
        cols = ['LINE_ID', 'VOUCHER_NO', 'LINE_NO', 'ACCOUNT_CODE', 'DEBIT', 'CREDIT', 'REMARKS', 'PARTY_TYPE', 'PARTY_CODE']
        vals = [':lid', ':vno', ':lno', ':ac', ':dr', ':cr', ':rm', ':pt', ':pc']
        params_i: Dict[str, Any] = {
            'lid': line_id, 'vno': vno, 'lno': i,
            'ac': ln['account_code'], 'dr': ln['debit'], 'cr': ln['credit'],
            'rm': ln['remarks'], 'pt': ln['party_type'], 'pc': ln['party_code'],
        }
        if has_cc:
            cols.append('COST_CENTER')
            vals.append(':cc')
            params_i['cc'] = ln.get('cost_center')
        if has_dp:
            cols.append('DEPARTMENT')
            vals.append(':dp')
            params_i['dp'] = ln.get('department')
        if has_pj:
            cols.append('PROJECT')
            vals.append(':pj')
            params_i['pj'] = ln.get('project')
        ins_sql = f"INSERT INTO {GL_DTL_TABLE} ({', '.join(cols)}) VALUES ({', '.join(vals)})"
        active_cur.execute(ins_sql, params_i)


def update_gl_journal_entry(
    voucher_no: str,
    voucher_date: Optional[str],
    reference_no: Optional[str],
    narration: Optional[str],
    lines: List[Dict[str, Any]],
    *,
    dimension_defaults: Optional[Dict[str, Any]] = None,
    conn: Optional[Any] = None,
    commit: bool = True,
) -> str:
    """Replace lines on an existing **MANUAL** GL voucher (header date/ref/narration updated)."""
    ensure_gl_tables()
    vno = (voucher_no or '').strip()
    if not vno:
        raise ValueError('Voucher number is required.')
    if get_gl_voucher_reversal_no(vno):
        raise ValueError(f'Voucher {vno} was reversed and cannot be edited.')
    hrows = _safe_rows(
        f"SELECT SOURCE FROM {GL_HDR_TABLE} WHERE VOUCHER_NO = :v",
        {'v': vno},
    )
    if not hrows:
        raise ValueError(f'Voucher {vno} not found.')
    src = str(hrows[0].get('source') or hrows[0].get('SOURCE') or '').strip().upper()
    if src != 'MANUAL':
        raise ValueError('Only manual journal vouchers can be edited.')
    if _gl_voucher_is_reversal_source(src):
        raise ValueError('Cannot edit a reversal voucher.')
    valid_lines = _validate_gl_journal_lines(lines, dimension_defaults)
    dtl_colset = {c.upper() for c in _get_table_columns(GL_DTL_TABLE) or []}
    has_cc = 'COST_CENTER' in dtl_colset
    has_dp = 'DEPARTMENT' in dtl_colset
    has_pj = 'PROJECT' in dtl_colset
    vdate = _to_iso_date(voucher_date) or datetime.now().strftime('%Y-%m-%d')
    try:
        from addons.accounts.period_closing_db import is_period_closed_for_date
        _lock_msg = is_period_closed_for_date(vdate)
        if _lock_msg:
            raise ValueError(_lock_msg)
    except ValueError:
        raise
    except Exception:
        pass

    def _apply_update(active_cur: Any) -> None:
        active_cur.execute(
            f"""
            UPDATE {GL_HDR_TABLE}
               SET VOUCHER_DATE = TO_DATE(:vdate, 'YYYY-MM-DD'),
                   REFERENCE_NO = :ref,
                   NARRATION = :nar
             WHERE VOUCHER_NO = :vno
            """,
            {
                'vno': vno,
                'vdate': vdate,
                'ref': (reference_no or '').strip()[:50] or None,
                'nar': (narration or '').strip()[:500] or None,
            },
        )
        active_cur.execute(f'DELETE FROM {GL_DTL_TABLE} WHERE VOUCHER_NO = :vno', {'vno': vno})
        _gl_insert_detail_lines(active_cur, vno, valid_lines, has_cc=has_cc, has_dp=has_dp, has_pj=has_pj)

    if conn is None:
        with _get_connection() as conn_own:
            try:
                with conn_own.cursor() as cur:
                    _apply_update(cur)
                if commit:
                    conn_own.commit()
            except Exception:
                try:
                    conn_own.rollback()
                except Exception:
                    pass
                raise
        return vno
    with conn.cursor() as cur:
        _apply_update(cur)
    if commit:
        conn.commit()
    return vno


def _normalize_account_ledger_dates(
    date_from: Optional[str]=None,
    date_to: Optional[str]=None,
    *,
    empty_means: str = 'ytd',
) -> Tuple[str, str]:
    """Normalize From/To for GL ledger and trial balance.

    ``empty_means``:
      - ``ytd``: both blank → Jan 1 current year through today (account ledger page)
      - ``all``: both blank → full history (trial balance + its drill-down must match)
    """
    dfrom = _to_iso_date(date_from)
    dto = _to_iso_date(date_to)
    mode = (empty_means or 'ytd').strip().lower()
    if not dfrom and (not dto):
        if mode == 'all':
            dfrom = '2000-01-01'
            dto = '2099-12-31'
        else:
            dfrom = f'{datetime.now().year}-01-01'
            dto = datetime.now().strftime('%Y-%m-%d')
    elif dfrom and (not dto):
        dto = datetime.now().strftime('%Y-%m-%d')
    elif not dfrom and dto:
        dfrom = '2000-01-01'
    if dfrom and dto and (dfrom > dto):
        dfrom, dto = (dto, dfrom)
    return (dfrom or '2000-01-01', dto or datetime.now().strftime('%Y-%m-%d'))


def _gl_exclude_closing_sql(hdr_alias: str = 'h') -> str:
    """SQL condition (no leading AND): omit PERIOD_CLOSE and reopen JE_REV of those vouchers.

    Used by Trial Balance / P&L / ledger when ``exclude_closing`` is on. Reopen-with-reverse
    posts SOURCE=JE_REV with REFERENCE_NO = original PERIOD_CLOSE voucher.
    """
    a = (hdr_alias or 'h').strip() or 'h'
    return (
        f"UPPER(TRIM(NVL({a}.SOURCE, ''))) <> 'PERIOD_CLOSE' "
        f"AND NOT ("
        f"UPPER(TRIM(NVL({a}.SOURCE, ''))) = 'JE_REV' "
        f"AND EXISTS ("
        f"SELECT 1 FROM {GL_HDR_TABLE} o_close "
        f"WHERE TRIM(o_close.VOUCHER_NO) = TRIM({a}.REFERENCE_NO) "
        f"AND UPPER(TRIM(NVL(o_close.SOURCE, ''))) = 'PERIOD_CLOSE'"
        f")"
        f")"
    )


def get_account_ledger(
    account_code: str,
    date_from: Optional[str]=None,
    date_to: Optional[str]=None,
    *,
    empty_means: str = 'ytd',
    exclude_closing: bool = False,
    party_type: Optional[str] = None,
    party_code: Optional[str] = None,
) -> Dict[str, Any]:
    """GL voucher lines for one account in a date range, with opening and running balance (debit − credit).

    Data comes from :func:`ensure_gl_tables` (GL_VOUCHER_HDR / GL_VOUCHER_DTL). Business rules use
    the tenant connection via :func:`_get_connection` / :func:`_safe_rows`.

    Use ``empty_means='all'`` when the caller is Trial Balance (blank filters = all dates).
    When ``exclude_closing`` is True, PERIOD_CLOSE journals and their JE_REV reopen reversals are omitted.
    Optional ``party_type`` / ``party_code`` restrict lines to one tagged party on this account.
    """
    ensure_gl_tables()
    code = (account_code or '').strip()[:20]
    if not code:
        return {'account_code': '', 'date_from': None, 'date_to': None, 'opening_balance': 0.0, 'total_debit': 0.0, 'total_credit': 0.0, 'closing_balance': 0.0, 'lines': []}
    dfrom, dto = _normalize_account_ledger_dates(date_from, date_to, empty_means=empty_means)
    ucode = code.upper()
    acode_d_open = 'TRIM(UPPER(d.ACCOUNT_CODE))'
    where_open = [f'{acode_d_open} = :ac', "TRUNC(h.VOUCHER_DATE) < TO_DATE(:df, 'YYYY-MM-DD')"]
    if exclude_closing:
        where_open.append(_gl_exclude_closing_sql('h'))
    open_params: Dict[str, Any] = {'ac': ucode, 'df': dfrom}
    pt_filter = (party_type or '').strip().upper()
    pc_filter = (party_code or '').strip()
    if pc_filter:
        if pt_filter:
            where_open.append("TRIM(UPPER(NVL(d.PARTY_TYPE, ''))) = :pt")
            open_params['pt'] = pt_filter
        where_open.append('TRIM(TO_CHAR(d.PARTY_CODE)) = :pc')
        open_params['pc'] = pc_filter
    q_open = f"\n        SELECT NVL(SUM(d.DEBIT - d.CREDIT), 0) AS BAL\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {' AND '.join(where_open)}\n    "
    open_rows = _safe_rows(q_open, open_params)
    ob = 0.0
    if open_rows:
        r0 = open_rows[0]
        try:
            v = r0.get('BAL')
            if v is None:
                v = r0.get('bal')
            ob = float(v or 0)
        except Exception:
            ob = 0.0
    acode_d = f'TRIM(UPPER(d.ACCOUNT_CODE))'
    where_lines = [f'{acode_d} = :ac', "TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')", "TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')"]
    if exclude_closing:
        where_lines.append(_gl_exclude_closing_sql('h'))
    line_params: Dict[str, Any] = {'ac': ucode, 'df': dfrom, 'dt': dto}
    if pc_filter:
        if pt_filter:
            where_lines.append("TRIM(UPPER(NVL(d.PARTY_TYPE, ''))) = :pt")
            line_params['pt'] = pt_filter
        where_lines.append('TRIM(TO_CHAR(d.PARTY_CODE)) = :pc')
        line_params['pc'] = pc_filter
    dtl_cols_ledger = {c.upper() for c in _get_table_columns(GL_DTL_TABLE) or []}
    dim_sel_ledger = ''
    if 'COST_CENTER' in dtl_cols_ledger:
        dim_sel_ledger += ', d.COST_CENTER'
    if 'DEPARTMENT' in dtl_cols_ledger:
        dim_sel_ledger += ', d.DEPARTMENT'
    if 'PROJECT' in dtl_cols_ledger:
        dim_sel_ledger += ', d.PROJECT'
    q_lines = f"\n        SELECT h.VOUCHER_DATE, h.VOUCHER_NO, h.REFERENCE_NO, h.NARRATION, h.SOURCE, h.CREATED_BY,\n               d.LINE_NO, d.DEBIT, d.CREDIT, d.REMARKS, d.PARTY_TYPE, d.PARTY_CODE{dim_sel_ledger}\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {' AND '.join(where_lines)}\n        ORDER BY h.VOUCHER_DATE, h.VOUCHER_NO, d.LINE_NO\n    "
    raw = _safe_rows(q_lines, line_params) or []
    total_dr = 0.0
    total_cr = 0.0
    run = round(float(ob), 2)
    lines: List[Dict[str, Any]] = []
    for r in raw:
        dr = float(r.get('debit') or r.get('DEBIT') or 0)
        cr = float(r.get('credit') or r.get('CREDIT') or 0)
        vdate = r.get('voucher_date') or r.get('VOUCHER_DATE')
        if vdate is not None and (not isinstance(vdate, str)):
            try:
                vdate = vdate.strftime('%Y-%m-%d')
            except Exception:
                vdate = str(vdate)[:10]
        elif vdate is not None:
            vdate = str(vdate)[:10]
        total_dr += dr
        total_cr += cr
        run = round(run + (dr - cr), 2)
        row_d: Dict[str, Any] = {'voucher_date': vdate or '', 'voucher_no': r.get('voucher_no') or r.get('VOUCHER_NO') or '', 'reference_no': r.get('reference_no') or r.get('REFERENCE_NO') or '', 'narration': r.get('narration') or r.get('NARRATION') or '', 'source': r.get('source') or r.get('SOURCE') or '', 'debit': round(dr, 2), 'credit': round(cr, 2), 'remarks': r.get('remarks') or r.get('REMARKS') or '', 'party_type': r.get('party_type') or r.get('PARTY_TYPE') or '', 'party_code': r.get('party_code') or r.get('PARTY_CODE') or '', 'running_balance': run}
        if 'COST_CENTER' in dtl_cols_ledger:
            row_d['cost_center'] = str(r.get('cost_center') or r.get('COST_CENTER') or '')
        if 'DEPARTMENT' in dtl_cols_ledger:
            row_d['department'] = str(r.get('department') or r.get('DEPARTMENT') or '')
        if 'PROJECT' in dtl_cols_ledger:
            row_d['project'] = str(r.get('project') or r.get('PROJECT') or '')
        lines.append(row_d)
    _enrich_gl_lines_party_names(lines)
    closing = run if lines else round(float(ob), 2)
    out: Dict[str, Any] = {'account_code': code, 'date_from': dfrom, 'date_to': dto, 'opening_balance': round(float(ob), 2), 'total_debit': round(total_dr, 2), 'total_credit': round(total_cr, 2), 'closing_balance': round(closing, 2), 'lines': lines}
    if pc_filter:
        out['party_type'] = pt_filter or None
        out['party_code'] = pc_filter
    return out

def get_gl_ledger_map_for_account_codes(account_codes: List[str], date_from: Optional[str]=None, date_to: Optional[str]=None) -> Dict[str, Dict[str, Any]]:
    """For each account code (upper keys), return opening, period dr/cr, closing (dr - cr), and detail lines. Same date rules as :func:`get_account_ledger` (debit balance convention)."""
    ensure_gl_tables()
    codes: List[str] = []
    for c in account_codes or []:
        s = (c or '').strip()[:COA_CODE_MAX_LEN]
        if s:
            codes.append(s)
    ucodes = list({(c or '').upper().strip() for c in codes if c})
    if not ucodes:
        return {}
    dfrom = _to_iso_date(date_from)
    dto = _to_iso_date(date_to)
    if not dfrom and (not dto):
        dfrom = f'{datetime.now().year}-01-01'
        dto = datetime.now().strftime('%Y-%m-%d')
    elif dfrom and (not dto):
        dto = datetime.now().strftime('%Y-%m-%d')
    elif not dfrom and dto:
        dfrom = '2000-01-01'
    if dfrom and dto and (dfrom > dto):
        dfrom, dto = (dto, dfrom)
    dfrom = dfrom or '2000-01-01'
    dto = dto or datetime.now().strftime('%Y-%m-%d')

    def _sql_in_str(vals: List[str]) -> str:
        parts: List[str] = []
        for v in vals:
            esc = (v or '').replace("'", "''")
            if esc:
                parts.append(f"'{esc}'")
        return ', '.join(parts) if parts else "''"
    in_sql = _sql_in_str(ucodes)
    acode_d = 'TRIM(UPPER(d.ACCOUNT_CODE))'
    q_open = f"\n        SELECT {acode_d} AS UCODE, NVL(SUM(d.DEBIT - d.CREDIT), 0) AS BAL\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {acode_d} IN ({in_sql})\n        AND TRUNC(h.VOUCHER_DATE) < TO_DATE(:df, 'YYYY-MM-DD')\n        GROUP BY {acode_d}\n    "
    open_by_u: Dict[str, float] = {}
    for r in _safe_rows(q_open, {'df': dfrom}) or []:
        k = (r.get('ucode') or r.get('UCODE') or '').upper().strip()
        if not k:
            continue
        try:
            v = r.get('BAL')
            if v is None:
                v = r.get('bal')
            open_by_u[k] = float(v or 0)
        except Exception:
            open_by_u[k] = 0.0
    for k in ucodes:
        open_by_u.setdefault(k.upper(), 0.0)
    q_pr = f"\n        SELECT {acode_d} AS UCODE, NVL(SUM(d.DEBIT), 0) AS SDR, NVL(SUM(d.CREDIT), 0) AS SCR\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {acode_d} IN ({in_sql})\n        AND TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')\n        AND TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')\n        GROUP BY {acode_d}\n    "
    pr_by_u: Dict[str, Tuple[float, float]] = {}
    for r in _safe_rows(q_pr, {'df': dfrom, 'dt': dto}) or []:
        k = (r.get('ucode') or r.get('UCODE') or '').upper().strip()
        if not k:
            continue
        try:
            dr = float((r.get('SDR') or r.get('sdr') or 0) or 0)
            cr = float((r.get('SCR') or r.get('scr') or 0) or 0)
        except Exception:
            dr, cr = (0.0, 0.0)
        pr_by_u[k] = (dr, cr)
    for k in ucodes:
        pr_by_u.setdefault(k.upper(), (0.0, 0.0))
    dtl_cols_map = {c.upper() for c in _get_table_columns(GL_DTL_TABLE) or []}
    dim_sel_map = ''
    if 'COST_CENTER' in dtl_cols_map:
        dim_sel_map += ', d.COST_CENTER'
    if 'DEPARTMENT' in dtl_cols_map:
        dim_sel_map += ', d.DEPARTMENT'
    if 'PROJECT' in dtl_cols_map:
        dim_sel_map += ', d.PROJECT'
    q_lines = f"\n        SELECT\n            {acode_d} AS UCODE,\n            h.VOUCHER_DATE, h.VOUCHER_NO, h.REFERENCE_NO, h.NARRATION, h.SOURCE, h.CREATED_BY,\n            d.LINE_NO, d.DEBIT, d.CREDIT, d.REMARKS, d.PARTY_TYPE, d.PARTY_CODE{dim_sel_map}\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {acode_d} IN ({in_sql})\n        AND TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')\n        AND TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')\n        ORDER BY {acode_d}, h.VOUCHER_DATE, h.VOUCHER_NO, d.LINE_NO\n    "
    raw = _safe_rows(q_lines, {'df': dfrom, 'dt': dto}) or []
    by_u_lines: Dict[str, List[Dict[str, Any]]] = {u: [] for u in ucodes}
    for r in raw:
        k = (r.get('ucode') or r.get('UCODE') or '').upper().strip()
        if not k or k not in by_u_lines:
            continue
        vdate = r.get('voucher_date') or r.get('VOUCHER_DATE')
        if vdate is not None and (not isinstance(vdate, str)):
            try:
                vdate = vdate.strftime('%Y-%m-%d')
            except Exception:
                vdate = str(vdate)[:10]
        elif vdate is not None:
            vdate = str(vdate)[:10]
        else:
            vdate = ''
        dr = float(r.get('debit') or r.get('DEBIT') or 0)
        cr = float(r.get('credit') or r.get('CREDIT') or 0)
        row_m: Dict[str, Any] = {'voucher_date': vdate, 'voucher_no': r.get('voucher_no') or r.get('VOUCHER_NO') or '', 'reference_no': r.get('reference_no') or r.get('REFERENCE_NO') or '', 'narration': r.get('narration') or r.get('NARRATION') or '', 'source': r.get('source') or r.get('SOURCE') or '', 'debit': round(dr, 2), 'credit': round(cr, 2), 'remarks': r.get('remarks') or r.get('REMARKS') or '', 'party_type': r.get('party_type') or r.get('PARTY_TYPE') or '', 'party_code': r.get('party_code') or r.get('PARTY_CODE') or ''}
        if 'COST_CENTER' in dtl_cols_map:
            row_m['cost_center'] = str(r.get('cost_center') or r.get('COST_CENTER') or '')
        if 'DEPARTMENT' in dtl_cols_map:
            row_m['department'] = str(r.get('department') or r.get('DEPARTMENT') or '')
        if 'PROJECT' in dtl_cols_map:
            row_m['project'] = str(r.get('project') or r.get('PROJECT') or '')
        by_u_lines[k].append(row_m)
    for k in by_u_lines:
        ob = open_by_u.get(k, 0.0)
        run = round(float(ob), 2)
        for ln in by_u_lines[k]:
            dr = float(ln.get('debit') or 0)
            cr = float(ln.get('credit') or 0)
            run = round(run + (dr - cr), 2)
            ln['running_balance'] = run
    out: Dict[str, Dict[str, Any]] = {}
    u_to_display: Dict[str, str] = {}
    for c in codes:
        u_to_display[(c or '').upper().strip()] = c.strip()
    for uk in ucodes:
        sdr, scr = pr_by_u.get(uk, (0.0, 0.0))
        ob = open_by_u.get(uk, 0.0)
        lines_k = by_u_lines.get(uk) or []
        closing = round(float(lines_k[-1]['running_balance']) if lines_k else float(ob), 2)
        dcode = u_to_display.get(uk, uk)
        out[uk] = {'display_code': dcode, 'opening_balance': round(float(ob), 2), 'total_debit': round(float(sdr), 2), 'total_credit': round(float(scr), 2), 'closing_balance': closing, 'lines': lines_k}
    return out

def get_main_account_ledger_data(root_account_id: Any, date_from: Optional[str]=None, date_to: Optional[str]=None) -> Dict[str, Any]:
    """Build a tree under root account with own GL (postable) and rollup (sum of subtrees) for group accounts."""
    try:
        rid = int(root_account_id)
    except (TypeError, ValueError):
        return {'error': 'Invalid account', 'root': None, 'date_from': None, 'date_to': None}
    all_rows = [r for r in get_all_chart_of_accounts() or [] if (r.get('status') or 'ACTIVE') == 'ACTIVE']
    if not all_rows:
        return {'error': 'No chart of accounts', 'root': None, 'date_from': None, 'date_to': None}
    by_id: Dict[int, Dict[str, Any]] = {}
    for a in all_rows:
        aid = a.get('account_id')
        if aid is None:
            continue
        try:
            by_id[int(aid)] = a
        except (TypeError, ValueError):
            continue
    if rid not in by_id:
        return {'error': 'Account not found', 'root': None, 'date_from': None, 'date_to': None}
    desc = {rid}
    stack = [rid]
    while stack:
        cur = stack.pop()
        for a in all_rows:
            try:
                pid = a.get('parent_id')
                aid = a.get('account_id')
                if aid is not None and pid is not None and (int(pid) == int(cur)) and (int(aid) not in desc):
                    desc.add(int(aid))
                    stack.append(int(aid))
            except (TypeError, ValueError):
                continue
    sub_rows = [a for a in all_rows if a.get('account_id') is not None and int(a['account_id']) in desc]
    children: Dict[int, List[Dict[str, Any]]] = {}
    for a in sub_rows:
        aid = int(a.get('account_id') or 0)
        p = a.get('parent_id')
        pid = int(p) if p is not None else None
        if pid is None:
            continue
        children.setdefault(pid, []).append(a)
    for pid in list(children.keys()):
        children[pid].sort(key=lambda x: (str(x.get('code') or ''), int(x.get('account_id') or 0)))

    def _node_dict(a: Dict[str, Any]) -> Dict[str, Any]:
        aid = int(a.get('account_id') or 0)
        is_p = bool(a.get('is_postable'))
        return {'account_id': aid, 'code': (a.get('code') or '').strip(), 'name': (a.get('name') or '').strip(), 'type': (a.get('type') or '').strip(), 'is_postable': is_p, 'children': [], 'own': {'opening': 0.0, 'debit': 0.0, 'credit': 0.0, 'closing': 0.0}, 'rollup': {'opening': 0.0, 'debit': 0.0, 'credit': 0.0, 'closing': 0.0}, 'lines': []}

    def build(aid: int) -> Optional[Dict[str, Any]]:
        a = by_id.get(aid)
        if not a:
            return None
        node = _node_dict(a)
        for ch in children.get(aid, []):
            caid = int(ch.get('account_id') or 0)
            sub = build(caid)
            if sub is not None:
                node['children'].append(sub)
        return node
    root = build(rid)
    if root is None:
        return {'error': 'Could not build tree', 'root': None, 'date_from': None, 'date_to': None}
    postable_codes: List[str] = []
    for a in sub_rows:
        if a.get('is_postable') and a.get('code'):
            postable_codes.append(str(a.get('code')).strip())
    dfrom_n = _to_iso_date(date_from)
    dto_n = _to_iso_date(date_to)
    if not dfrom_n and (not dto_n):
        dfrom_n = f'{datetime.now().year}-01-01'
        dto_n = datetime.now().strftime('%Y-%m-%d')
    elif dfrom_n and (not dto_n):
        dto_n = datetime.now().strftime('%Y-%m-%d')
    elif not dfrom_n and dto_n:
        dfrom_n = '2000-01-01'
    if dfrom_n and dto_n and (dfrom_n > dto_n):
        dfrom_n, dto_n = (dto_n, dfrom_n)
    dfrom_n = dfrom_n or '2000-01-01'
    dto_n = dto_n or datetime.now().strftime('%Y-%m-%d')
    glmap = get_gl_ledger_map_for_account_codes(postable_codes, dfrom_n, dto_n)

    def fill_own(node: Dict[str, Any]) -> None:
        ucode = (node.get('code') or '').upper().strip()
        d = glmap.get(ucode)
        if node.get('is_postable'):
            if d:
                node['own'] = {'opening': d['opening_balance'], 'debit': d['total_debit'], 'credit': d['total_credit'], 'closing': d['closing_balance']}
                node['lines'] = d.get('lines') or []
            else:
                node['own'] = {'opening': 0.0, 'debit': 0.0, 'credit': 0.0, 'closing': 0.0}
                node['lines'] = []
        else:
            node['own'] = {'opening': 0.0, 'debit': 0.0, 'credit': 0.0, 'closing': 0.0}
            node['lines'] = []
        for ch in node.get('children') or []:
            fill_own(ch)
    fill_own(root)

    def rollup(node: Dict[str, Any]) -> None:
        for ch in node.get('children') or []:
            rollup(ch)
        if node.get('is_postable'):
            o = node['own']
            node['rollup'] = {'opening': o['opening'], 'debit': o['debit'], 'credit': o['credit'], 'closing': o['closing']}
        else:
            ro, rd, rc, rcl = (0.0, 0.0, 0.0, 0.0)
            for ch in node.get('children') or []:
                r2 = ch.get('rollup') or {}
                ro += float(r2.get('opening') or 0)
                rd += float(r2.get('debit') or 0)
                rc += float(r2.get('credit') or 0)
                rcl += float(r2.get('closing') or 0)
            node['rollup'] = {'opening': round(ro, 2), 'debit': round(rd, 2), 'credit': round(rc, 2), 'closing': round(rcl, 2)}
    rollup(root)
    return {'error': None, 'root': root, 'date_from': dfrom_n, 'date_to': dto_n}

def _norm_supplier_key(v: Any) -> str:
    s = str(v or '').strip()
    if not s:
        return ''
    try:
        f = float(s)
        if f.is_integer():
            return str(int(f))
    except Exception:
        pass
    return s


def _norm_voucher_key(v: Any) -> str:
    """Uppercase voucher number for allocation maps (GRN / PR / journal refs)."""
    return str(v or '').strip().upper()


def _norm_gl_account_code(v: Any) -> str:
    s = str(v or '').strip()
    if not s:
        return ''
    try:
        f = float(s)
        if f.is_integer():
            return str(int(f))
    except Exception:
        pass
    return s


def resolve_item_inventory_gl_account(raw: Any, default: str = '1300') -> str:
    """Item INVENTORYACCOUNT from ITEMMASTER; treat blank/zero as inventory asset default (1300)."""
    code = _norm_gl_account_code(raw)
    if not code:
        return str(default or '1300').strip()[:20]
    try:
        if int(float(code)) <= 0:
            return str(default or '1300').strip()[:20]
    except (TypeError, ValueError):
        pass
    return code[:20]

def get_supplier_master_by_code(supplier_code: Any) -> Optional[Dict[str, Any]]:
    """Return one supplier row from tenant SUPPLIER table by code (any location)."""
    if not _supplier_table_exists():
        return None
    sk = _norm_supplier_key(supplier_code)
    if not sk:
        return None
    code_col = _detect_column(SUPPLIER_TABLE, ['SUPPLIERCODE', 'suppliercode'])
    name_col = _detect_column(SUPPLIER_TABLE, ['SUPPLIERNAME', 'suppliername'])
    payable_col = _detect_column(SUPPLIER_TABLE, ['PAYABLEACCOUNT', 'payableaccount'])
    loc_col = _detect_column(SUPPLIER_TABLE, ['LOCATIONCODE', 'locationcode'])
    if not code_col or not name_col:
        return None
    sel = [f'{code_col} AS suppliercode', f'{name_col} AS suppliername']
    if payable_col:
        sel.append(f'{payable_col} AS payableaccount')
    if loc_col:
        sel.append(f'{loc_col} AS locationcode')
    q = f"\n        SELECT {', '.join(sel)}\n        FROM {SUPPLIER_TABLE}\n        WHERE TRIM(TO_CHAR({code_col})) = :sk\n    "
    try:
        rows = _safe_rows(q, {'sk': sk})
        return rows[0] if rows else None
    except Exception:
        return None

def _liability_gl_account_norms() -> List[str]:
    """Uppercase trimmed GL codes that are CHART type LIABILITY (same basis as :func:`get_accounts_payable_summary`)."""
    return sorted({str(r.get('code') or '').strip().upper() for r in get_all_chart_of_accounts() if str(r.get('type') or '').upper() == 'LIABILITY' and str(r.get('code') or '').strip()})

def _asset_gl_account_norms() -> List[str]:
    """Uppercase trimmed GL codes that are CHART type ASSET (typical receivable / sub-ledger basis for customers)."""
    return sorted({str(r.get('code') or '').strip().upper() for r in get_all_chart_of_accounts() if str(r.get('type') or '').upper() == 'ASSET' and str(r.get('code') or '').strip()})

def get_customer_master_by_code(customer_code: Any) -> Optional[Dict[str, Any]]:
    """Return one customer row (customercode, customername, receivableaccount) from CUSTOMER/CUSTOMERS if present."""
    sk = _norm_supplier_key(customer_code)
    if not sk:
        return None
    table_candidates = ['CUSTOMER', 'CUSTOMERS', 'customer', 'customers']
    for table_name in table_candidates:
        if not _table_exists(table_name):
            continue
        code_col = _detect_column(table_name, ['CUSTOMERCODE', 'CUST_CODE', 'CUSTOMER_CODE', 'CODE', 'code'])
        name_col = _detect_column(table_name, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME', 'name'])
        recv_col = _detect_column(table_name, ['RECEIVABLEACCOUNT', 'receivableaccount', 'RECEIVABLE_AC', 'receivable_acct'])
        if not code_col or not name_col:
            continue
        sel = [f'{code_col} AS customercode', f'{name_col} AS customername']
        if recv_col:
            sel.append(f'{recv_col} AS receivableaccount')
        q = f"\n            SELECT {', '.join(sel)}\n            FROM {table_name}\n            WHERE TRIM(TO_CHAR({code_col})) = :sk\n        "
        try:
            rows = _safe_rows(q, {'sk': sk})
            if rows:
                return rows[0]
        except Exception:
            continue
    return None

def _enrich_gl_lines_party_names(lines: List[Dict[str, Any]]) -> None:
    """Add party_name on GL line dicts from SUPPLIER/CUSTOMER master (mutates *lines* in place)."""
    if not lines:
        return
    supplier_codes: set = set()
    customer_codes: set = set()
    for ln in lines:
        if not isinstance(ln, dict):
            continue
        pt = str(ln.get('party_type') or '').strip().upper()
        pc = str(ln.get('party_code') or '').strip()
        if not pc or pc in ('—', '-'):
            continue
        if pt == 'SUPPLIER':
            supplier_codes.add(pc)
        elif pt == 'CUSTOMER':
            customer_codes.add(pc)
    sup_map: Dict[str, str] = {}
    for sc in supplier_codes:
        row = get_supplier_master_by_code(sc)
        if row:
            nm = str(row.get('suppliername') or '').strip()
            if nm:
                sup_map[sc] = nm
    cust_map: Dict[str, str] = {}
    for cc in customer_codes:
        row = get_customer_master_by_code(cc)
        if row:
            nm = str(row.get('customername') or '').strip()
            if nm:
                cust_map[cc] = nm
    for ln in lines:
        if not isinstance(ln, dict):
            continue
        pt = str(ln.get('party_type') or '').strip().upper()
        pc = str(ln.get('party_code') or '').strip()
        name = ''
        if pt == 'SUPPLIER' and pc:
            name = sup_map.get(pc, '')
        elif pt == 'CUSTOMER' and pc:
            name = cust_map.get(pc, '')
        ln['party_name'] = name

def get_supplier_ledger(supplier_code: str, date_from: Optional[str]=None, date_to: Optional[str]=None, gl_account_code: Optional[str]=None, liability_accounts_only: bool=False) -> Dict[str, Any]:
    """GL voucher lines with PARTY_TYPE=SUPPLIER and PARTY_CODE=supplier, with opening and running balance.

    ``opening_balance`` / ``running_balance`` / ``closing_balance`` use **credit minus debit** (typical
    for payables: positive means net credit on supplier-tagged lines in the range).

    If ``gl_account_code`` is set (e.g. the vendor's PAYABLEACCOUNT from SUPPLIER master), only lines on
    that GL account are included. **Without** this filter, *every* party-tagged line (any account) is
    included — the running total may not look like a classic "A/P expected to clear to zero" because
    GRN/invoice vs payment lines can hit different accounts, or only some lines carry party.

    If ``liability_accounts_only`` is True, only lines whose ``ACCOUNT_CODE`` is a **LIABILITY** on the
    chart of accounts are included. That matches the balance logic in :func:`get_accounts_payable_summary`
    (``PARTY_LIABILITY``) so the **closing balance** should match **payable balance** for the same
    supplier when the GL data is consistent. A non-zero "all lines" view with **AP balance 0** usually
    means party tags on **non-liability** accounts (e.g. expense, inventory) for that supplier.
    """
    ensure_gl_tables()
    sc = _norm_supplier_key(supplier_code)
    if not sc:
        return {'supplier_code': '', 'date_from': None, 'date_to': None, 'gl_account_filter': None, 'liability_only': False, 'opening_balance': 0.0, 'total_debit': 0.0, 'total_credit': 0.0, 'closing_balance': 0.0, 'lines': []}
    dfrom = _to_iso_date(date_from)
    dto = _to_iso_date(date_to)
    if not dfrom and (not dto):
        dfrom = f'{datetime.now().year}-01-01'
        dto = datetime.now().strftime('%Y-%m-%d')
    elif dfrom and (not dto):
        dto = datetime.now().strftime('%Y-%m-%d')
    elif not dfrom and dto:
        dfrom = '2000-01-01'
    if dfrom and dto and (dfrom > dto):
        dfrom, dto = (dto, dfrom)
    acc_filter = str(gl_account_code or '').strip()[:20]
    acode_pred = 'TRIM(UPPER(TO_CHAR(d.ACCOUNT_CODE))) = TRIM(UPPER(TO_CHAR(:gac)))'
    where_party = ["TRIM(UPPER(NVL(d.PARTY_TYPE, ''))) = 'SUPPLIER'", 'TRIM(TO_CHAR(d.PARTY_CODE)) = :sc']
    if acc_filter:
        where_party = where_party + [acode_pred]
    liab_bind: Dict[str, Any] = {}
    liab_list = _liability_gl_account_norms()
    if liability_accounts_only and (not acc_filter):
        if liab_list:
            in_bind = ', '.join((f':lb{i}' for i in range(len(liab_list))))
            where_party.append(f'TRIM(UPPER(TO_CHAR(d.ACCOUNT_CODE))) IN ({in_bind})')
            for i, c in enumerate(liab_list):
                liab_bind[f'lb{i}'] = c
        else:
            where_party.append('1=0')
    q_open = f"\n        SELECT NVL(SUM(d.CREDIT - d.DEBIT), 0) AS BAL\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {' AND '.join(where_party)}\n          AND TRUNC(h.VOUCHER_DATE) < TO_DATE(:df, 'YYYY-MM-DD')\n    "
    open_params: Dict[str, Any] = {'sc': sc, 'df': dfrom}
    if acc_filter:
        open_params['gac'] = acc_filter
    open_params.update(liab_bind)
    open_rows = _safe_rows(q_open, open_params)
    ob = 0.0
    if open_rows:
        r0 = open_rows[0]
        try:
            v = r0.get('BAL')
            if v is None:
                v = r0.get('bal')
            ob = float(v or 0)
        except Exception:
            ob = 0.0
    where_lines = where_party + ["TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')", "TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')"]
    q_lines = f"\n        SELECT h.VOUCHER_DATE, h.VOUCHER_NO, h.REFERENCE_NO, h.NARRATION, h.SOURCE, h.CREATED_BY,\n               d.LINE_NO, d.DEBIT, d.CREDIT, d.REMARKS, d.PARTY_TYPE, d.PARTY_CODE, d.ACCOUNT_CODE\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {' AND '.join(where_lines)}\n        ORDER BY h.VOUCHER_DATE, h.VOUCHER_NO, d.LINE_NO\n    "
    line_params: Dict[str, Any] = {'sc': sc, 'df': dfrom, 'dt': dto}
    if acc_filter:
        line_params['gac'] = acc_filter
    line_params.update(liab_bind)
    raw = _safe_rows(q_lines, line_params) or []
    total_dr = 0.0
    total_cr = 0.0
    run = round(float(ob), 2)
    lines: List[Dict[str, Any]] = []
    for r in raw:
        dr = float(r.get('debit') or r.get('DEBIT') or 0)
        cr = float(r.get('credit') or r.get('CREDIT') or 0)
        vdate = r.get('voucher_date') or r.get('VOUCHER_DATE')
        if vdate is not None and (not isinstance(vdate, str)):
            try:
                vdate = vdate.strftime('%Y-%m-%d')
            except Exception:
                vdate = str(vdate)[:10]
        elif vdate is not None:
            vdate = str(vdate)[:10]
        total_dr += dr
        total_cr += cr
        run = round(run + (cr - dr), 2)
        acc = str(r.get('account_code') or r.get('ACCOUNT_CODE') or '').strip()
        lines.append({'voucher_date': vdate or '', 'voucher_no': r.get('voucher_no') or r.get('VOUCHER_NO') or '', 'reference_no': r.get('reference_no') or r.get('REFERENCE_NO') or '', 'narration': r.get('narration') or r.get('NARRATION') or '', 'source': r.get('source') or r.get('SOURCE') or '', 'debit': round(dr, 2), 'credit': round(cr, 2), 'remarks': r.get('remarks') or r.get('REMARKS') or '', 'account_code': acc, 'party_type': r.get('party_type') or r.get('PARTY_TYPE') or '', 'party_code': r.get('party_code') or r.get('PARTY_CODE') or '', 'running_balance': run})
    closing = run if lines else round(float(ob), 2)
    return {'supplier_code': sc, 'date_from': dfrom, 'date_to': dto, 'gl_account_filter': acc_filter or None, 'liability_only': bool(liability_accounts_only and (not acc_filter)), 'opening_balance': round(float(ob), 2), 'total_debit': round(total_dr, 2), 'total_credit': round(total_cr, 2), 'closing_balance': round(closing, 2), 'lines': lines}

def get_customer_ledger(customer_code: str, date_from: Optional[str]=None, date_to: Optional[str]=None, gl_account_code: Optional[str]=None, asset_accounts_only: bool=True) -> Dict[str, Any]:
    """GL voucher lines with PARTY_TYPE=CUSTOMER and PARTY_CODE=customer, with opening and running balance.

    ``opening_balance`` / ``running_balance`` / ``closing_balance`` use **debit minus credit** (typical
    for receivables: positive means net debit on customer-tagged lines in the range).

    If ``gl_account_code`` is set (e.g. the customer's RECEIVABLEACCOUNT from master), only lines on
    that GL account are included. If ``asset_accounts_only`` is True (default), only lines whose
    ``ACCOUNT_CODE`` is an **ASSET** on the chart of accounts are included (AR-style sub-ledger).
    """
    ensure_gl_tables()
    cc = _norm_supplier_key(customer_code)
    if not cc:
        return {'customer_code': '', 'date_from': None, 'date_to': None, 'gl_account_filter': None, 'asset_only': False, 'opening_balance': 0.0, 'total_debit': 0.0, 'total_credit': 0.0, 'closing_balance': 0.0, 'lines': []}
    dfrom = _to_iso_date(date_from)
    dto = _to_iso_date(date_to)
    if not dfrom and (not dto):
        dfrom = f'{datetime.now().year}-01-01'
        dto = datetime.now().strftime('%Y-%m-%d')
    elif dfrom and (not dto):
        dto = datetime.now().strftime('%Y-%m-%d')
    elif not dfrom and dto:
        dfrom = '2000-01-01'
    if dfrom and dto and (dfrom > dto):
        dfrom, dto = (dto, dfrom)
    acc_filter = str(gl_account_code or '').strip()[:20]
    acode_pred = 'TRIM(UPPER(TO_CHAR(d.ACCOUNT_CODE))) = TRIM(UPPER(TO_CHAR(:gac)))'
    where_party = ["TRIM(UPPER(NVL(d.PARTY_TYPE, ''))) = 'CUSTOMER'", 'TRIM(TO_CHAR(d.PARTY_CODE)) = :cc']
    if acc_filter:
        where_party = where_party + [acode_pred]
    asset_bind: Dict[str, Any] = {}
    asset_list = _asset_gl_account_norms()
    if asset_accounts_only and (not acc_filter):
        if asset_list:
            in_bind = ', '.join((f':as{i}' for i in range(len(asset_list))))
            where_party.append(f'TRIM(UPPER(TO_CHAR(d.ACCOUNT_CODE))) IN ({in_bind})')
            for i, c in enumerate(asset_list):
                asset_bind[f'as{i}'] = c
        else:
            where_party.append('1=0')
    q_open = f"\n        SELECT NVL(SUM(d.DEBIT - d.CREDIT), 0) AS BAL\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {' AND '.join(where_party)}\n          AND TRUNC(h.VOUCHER_DATE) < TO_DATE(:df, 'YYYY-MM-DD')\n    "
    open_params: Dict[str, Any] = {'cc': cc, 'df': dfrom}
    if acc_filter:
        open_params['gac'] = acc_filter
    open_params.update(asset_bind)
    open_rows = _safe_rows(q_open, open_params)
    ob = 0.0
    if open_rows:
        r0 = open_rows[0]
        try:
            v = r0.get('BAL')
            if v is None:
                v = r0.get('bal')
            ob = float(v or 0)
        except Exception:
            ob = 0.0
    where_lines = where_party + ["TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')", "TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')"]
    q_lines = f"\n        SELECT h.VOUCHER_DATE, h.VOUCHER_NO, h.REFERENCE_NO, h.NARRATION, h.SOURCE, h.CREATED_BY,\n               d.LINE_NO, d.DEBIT, d.CREDIT, d.REMARKS, d.PARTY_TYPE, d.PARTY_CODE, d.ACCOUNT_CODE\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {' AND '.join(where_lines)}\n        ORDER BY h.VOUCHER_DATE, h.VOUCHER_NO, d.LINE_NO\n    "
    line_params: Dict[str, Any] = {'cc': cc, 'df': dfrom, 'dt': dto}
    if acc_filter:
        line_params['gac'] = acc_filter
    line_params.update(asset_bind)
    raw = _safe_rows(q_lines, line_params) or []
    total_dr = 0.0
    total_cr = 0.0
    run = round(float(ob), 2)
    lines: List[Dict[str, Any]] = []
    for r in raw:
        dr = float(r.get('debit') or r.get('DEBIT') or 0)
        cr = float(r.get('credit') or r.get('CREDIT') or 0)
        vdate = r.get('voucher_date') or r.get('VOUCHER_DATE')
        if vdate is not None and (not isinstance(vdate, str)):
            try:
                vdate = vdate.strftime('%Y-%m-%d')
            except Exception:
                vdate = str(vdate)[:10]
        elif vdate is not None:
            vdate = str(vdate)[:10]
        total_dr += dr
        total_cr += cr
        run = round(run + (dr - cr), 2)
        acc = str(r.get('account_code') or r.get('ACCOUNT_CODE') or '').strip()
        lines.append({'voucher_date': vdate or '', 'voucher_no': r.get('voucher_no') or r.get('VOUCHER_NO') or '', 'reference_no': r.get('reference_no') or r.get('REFERENCE_NO') or '', 'narration': r.get('narration') or r.get('NARRATION') or '', 'source': r.get('source') or r.get('SOURCE') or '', 'debit': round(dr, 2), 'credit': round(cr, 2), 'remarks': r.get('remarks') or r.get('REMARKS') or '', 'account_code': acc, 'party_type': r.get('party_type') or r.get('PARTY_TYPE') or '', 'party_code': r.get('party_code') or r.get('PARTY_CODE') or '', 'running_balance': run})
    closing = run if lines else round(float(ob), 2)
    return {'customer_code': cc, 'date_from': dfrom, 'date_to': dto, 'gl_account_filter': acc_filter or None, 'asset_only': bool(asset_accounts_only and (not acc_filter)), 'opening_balance': round(float(ob), 2), 'total_debit': round(total_dr, 2), 'total_credit': round(total_cr, 2), 'closing_balance': round(closing, 2), 'lines': lines}

def get_gl_account_closing_balances() -> Dict[str, float]:
    """Lifetime GL closing balance by account code (SUM Debit − SUM Credit), all posted history."""
    ensure_gl_tables()
    acode = 'TRIM(UPPER(d.ACCOUNT_CODE))'
    q = f'''
        SELECT {acode} AS code,
               NVL(SUM(NVL(d.DEBIT, 0) - NVL(d.CREDIT, 0)), 0) AS bal
        FROM {GL_DTL_TABLE} d
        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO
        WHERE {acode} IS NOT NULL
        GROUP BY {acode}
    '''
    out: Dict[str, float] = {}
    try:
        for r in (_safe_rows(q, {}) or []):
            code = str(r.get('code') or r.get('CODE') or '').strip().upper()
            if not code:
                continue
            try:
                out[code] = round(float(r.get('bal') if r.get('bal') is not None else r.get('BAL') or 0), 2)
            except (TypeError, ValueError):
                out[code] = 0.0
    except Exception:
        return {}
    return out


def get_gl_party_balances_for_journal() -> Dict[str, Dict[str, float]]:
    """Supplier / customer balances for journal account picker (same sign as AP / AR).

    - SUPPLIER: liability party lines, Credit − Debit (amount owed to supplier)
    - CUSTOMER: asset party lines, Debit − Credit (amount owed by customer)
    """
    ensure_gl_tables()
    if not _table_exists(GL_DTL_TABLE):
        return {'SUPPLIER': {}, 'CUSTOMER': {}}
    coa_type = {
        str(r.get('code') or '').strip().upper(): str(r.get('type') or '').upper()
        for r in (get_all_chart_of_accounts() or [])
        if str(r.get('code') or '').strip()
    }
    suppliers: Dict[str, float] = {}
    customers: Dict[str, float] = {}
    try:
        party_rows = _safe_rows(
            f"""
            SELECT UPPER(TRIM(TO_CHAR(d.PARTY_TYPE))) AS party_type,
                   TRIM(TO_CHAR(d.PARTY_CODE)) AS party_code,
                   TRIM(TO_CHAR(d.ACCOUNT_CODE)) AS account_code,
                   SUM(NVL(d.DEBIT, 0)) AS debit,
                   SUM(NVL(d.CREDIT, 0)) AS credit
              FROM {GL_DTL_TABLE} d
             WHERE UPPER(NVL(d.PARTY_TYPE, '')) IN ('SUPPLIER', 'CUSTOMER')
               AND d.PARTY_CODE IS NOT NULL
             GROUP BY UPPER(TRIM(TO_CHAR(d.PARTY_TYPE))),
                      TRIM(TO_CHAR(d.PARTY_CODE)),
                      TRIM(TO_CHAR(d.ACCOUNT_CODE))
            """,
            {},
        ) or []
    except Exception:
        party_rows = []
    for r in party_rows:
        ptype = str(r.get('party_type') or '').strip().upper()
        pcode = _norm_supplier_key(r.get('party_code'))
        acc = str(r.get('account_code') or '').strip().upper()
        if not pcode or ptype not in ('SUPPLIER', 'CUSTOMER'):
            continue
        try:
            dr = float(r.get('debit') or 0)
            cr = float(r.get('credit') or 0)
        except (TypeError, ValueError):
            continue
        acc_type = coa_type.get(acc, '')
        if ptype == 'SUPPLIER':
            if acc_type and acc_type != 'LIABILITY':
                continue
            bal = round(cr - dr, 2)
            suppliers[pcode] = round(suppliers.get(pcode, 0.0) + bal, 2)
        else:
            if acc_type and acc_type != 'ASSET':
                continue
            bal = round(dr - cr, 2)
            customers[pcode] = round(customers.get(pcode, 0.0) + bal, 2)
    return {'SUPPLIER': suppliers, 'CUSTOMER': customers}


def get_trial_balance_report(
    date_from: Optional[str]=None,
    date_to: Optional[str]=None,
    *,
    exclude_closing: bool = False,
) -> List[Dict[str, Any]]:
    """Period Debit/Credit and Closing for the filter window.

    Uses the **same date normalization and formulas** as trial-balance account drill-down
    (``get_account_ledger(..., empty_means='all')``):

    - Debit / Credit = period sums in [From, To]
    - Balance (Closing) = opening (before From) + period Debit − period Credit

    When ``exclude_closing`` is True, PERIOD_CLOSE journals and their JE_REV reopen reversals are omitted.
    """
    ensure_gl_tables()
    # Blank filters = all history (must match TB row click / ledger API)
    dfrom, dto = _normalize_account_ledger_dates(date_from, date_to, empty_means='all')
    acode = 'TRIM(UPPER(d.ACCOUNT_CODE))'
    params = {'df': dfrom, 'dt': dto}
    close_sql = f' AND {_gl_exclude_closing_sql("h")}' if exclude_closing else ''

    q_period = f'''
        SELECT {acode} AS code,
               SUM(NVL(d.DEBIT, 0)) AS debit,
               SUM(NVL(d.CREDIT, 0)) AS credit
        FROM {GL_DTL_TABLE} d
        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO
        WHERE TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')
          AND TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')
          {close_sql}
        GROUP BY {acode}
        ORDER BY 1
    '''
    rows = _safe_rows(q_period, params) or []

    q_open = f'''
        SELECT {acode} AS code,
               NVL(SUM(NVL(d.DEBIT, 0) - NVL(d.CREDIT, 0)), 0) AS bal
        FROM {GL_DTL_TABLE} d
        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO
        WHERE TRUNC(h.VOUCHER_DATE) < TO_DATE(:df, 'YYYY-MM-DD')
          {close_sql}
        GROUP BY {acode}
    '''
    open_map: Dict[str, float] = {}
    for r in (_safe_rows(q_open, {'df': dfrom}) or []):
        c = str(r.get('code') or '').strip().upper()
        if not c:
            continue
        try:
            open_map[c] = float(r.get('bal') if r.get('bal') is not None else r.get('BAL') or 0)
        except (TypeError, ValueError):
            open_map[c] = 0.0

    coa_list = get_all_chart_of_accounts()
    coa: Dict[str, Dict[str, Any]] = {}
    for r in coa_list or []:
        c = str(r.get('code') or '').strip().upper()
        if c:
            coa[c] = r
    out: List[Dict[str, Any]] = []
    for r in rows:
        code = (r.get('code') or '').strip().upper()
        if not code:
            continue
        dr = float(r.get('debit') or 0)
        cr = float(r.get('credit') or 0)
        ob = float(open_map.get(code, 0.0))
        closing = round(ob + dr - cr, 2)
        meta = coa.get(code, {})
        out.append({
            'code': code,
            'name': meta.get('name') or code,
            'type': meta.get('type') or '',
            'debit': round(dr, 2),
            'credit': round(cr, 2),
            'opening_balance': round(ob, 2),
            'balance': closing,
        })
    return out

def get_trial_balance_by_dimension(
    dimension: str,
    date_from: Optional[str]=None,
    date_to: Optional[str]=None,
    *,
    exclude_closing: bool = False,
) -> List[Dict[str, Any]]:
    """
    Like :func:`get_trial_balance_report` but each row is **account + one analytic bucket**.

    ``dimension`` must be one of: ``cost_center``, ``department``, ``project``.
    Blank dimension values on lines are shown as ``(blank)``.
    """
    ensure_gl_tables()
    dim = (dimension or '').strip().lower()
    colmap = {'cost_center': 'COST_CENTER', 'department': 'DEPARTMENT', 'project': 'PROJECT'}
    if dim not in colmap:
        return []
    dcol = colmap[dim]
    dtl_cols_tb = {c.upper() for c in _get_table_columns(GL_DTL_TABLE) or []}
    if dcol not in dtl_cols_tb:
        return []
    where = ['1=1']
    params: Dict[str, Any] = {}
    dfrom = _to_iso_date(date_from)
    dto = _to_iso_date(date_to)
    if dfrom:
        where.append("TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')")
        params['df'] = dfrom
    if dto:
        where.append("TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')")
        params['dt'] = dto
    if exclude_closing:
        where.append(_gl_exclude_closing_sql('h'))
    grp_dim = f"NVL(NULLIF(TRIM(d.{dcol}), ''), '(blank)')"
    q = f"\n        SELECT d.ACCOUNT_CODE AS code, {grp_dim} AS dim_value,\n               SUM(d.DEBIT) AS debit, SUM(d.CREDIT) AS credit\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {' AND '.join(where)}\n        GROUP BY d.ACCOUNT_CODE, {grp_dim}\n        ORDER BY 1, 2\n    "
    rows = _safe_rows(q, params)
    coa = {(r.get('code') or '').strip(): r for r in get_all_chart_of_accounts()}
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        code = (r.get('code') or '').strip()
        dv = str(r.get('dim_value') or r.get('DIM_VALUE') or '').strip() or '(blank)'
        dr = float(r.get('debit') or 0)
        cr = float(r.get('credit') or 0)
        meta = coa.get(code, {})
        out.append({'code': code, 'name': meta.get('name') or code, 'type': meta.get('type') or '', 'dimension': dim, 'dim_value': dv, 'debit': round(dr, 2), 'credit': round(cr, 2), 'balance': round(dr - cr, 2)})
    return out

def _is_pl_cost_of_sales_account(code: str, name: str) -> bool:
    """True for COGS / Inventory Adjustment lines used in Gross Profit."""
    c = (code or '').strip().upper()
    n = (name or '').strip().upper()
    cogs_code = str(DEFAULT_PARTY_ACCOUNTS.get('cogs') or '5100').strip().upper()
    inv_adj = str(DEFAULT_PARTY_ACCOUNTS.get('inventory_adjustment') or '5199').strip().upper()
    if c in (cogs_code, inv_adj):
        return True
    if 'COST OF GOODS' in n or 'COST OF SALES' in n or n == 'COGS' or ' COGS' in f' {n}':
        return True
    if 'INVENTORY ADJUST' in n or 'STOCK ADJUST' in n:
        return True
    # Default COGS tree (5100…) — not 500x purchase expense
    if c.startswith('51'):
        return True
    return False


def get_profit_and_loss_report(
    date_from: Optional[str]=None,
    date_to: Optional[str]=None,
    *,
    exclude_closing: bool = False,
) -> Dict[str, Any]:
    tb = get_trial_balance_report(date_from=date_from, date_to=date_to, exclude_closing=exclude_closing)
    revenue_accounts: List[Dict[str, Any]] = []
    expense_accounts: List[Dict[str, Any]] = []
    cost_of_sales_accounts: List[Dict[str, Any]] = []
    operating_expense_accounts: List[Dict[str, Any]] = []
    total_revenue = 0.0
    total_expense = 0.0
    total_cost_of_sales = 0.0
    total_operating_expense = 0.0
    for r in tb:
        t = (r.get('type') or '').upper()
        if t == 'REVENUE':
            amount = round(float(r.get('credit') or 0) - float(r.get('debit') or 0), 2)
            revenue_accounts.append({**r, 'amount': amount})
            total_revenue += amount
        elif t == 'EXPENSE':
            amount = round(float(r.get('debit') or 0) - float(r.get('credit') or 0), 2)
            row = {**r, 'amount': amount}
            expense_accounts.append(row)
            total_expense += amount
            if _is_pl_cost_of_sales_account(str(r.get('code') or ''), str(r.get('name') or '')):
                cost_of_sales_accounts.append(row)
                total_cost_of_sales += amount
            else:
                operating_expense_accounts.append(row)
                total_operating_expense += amount
    gross_profit = round(total_revenue - total_cost_of_sales, 2)
    return {
        'revenue_accounts': revenue_accounts,
        'expense_accounts': expense_accounts,
        'cost_of_sales_accounts': cost_of_sales_accounts,
        'operating_expense_accounts': operating_expense_accounts,
        'total_revenue': round(total_revenue, 2),
        'total_expense': round(total_expense, 2),
        'total_cost_of_sales': round(total_cost_of_sales, 2),
        'total_operating_expense': round(total_operating_expense, 2),
        'gross_profit': gross_profit,
        'net_profit': round(total_revenue - total_expense, 2),
    }

def _normalize_profit_loss_period(date_from: Optional[str], date_to: Optional[str]) -> Tuple[str, str]:
    """Default and align P&L date range (inclusive) for reporting."""
    dfrom = _to_iso_date(date_from)
    dto = _to_iso_date(date_to)
    if not dfrom and (not dto):
        y = datetime.now().year
        dfrom = f'{y}-01-01'
        dto = datetime.now().strftime('%Y-%m-%d')
    elif dfrom and (not dto):
        dto = datetime.now().strftime('%Y-%m-%d')
    elif not dfrom and dto:
        y = datetime.strptime(dto, '%Y-%m-%d').year
        dfrom = f'{y}-01-01'
    if dfrom and dto and (dfrom > dto):
        dfrom, dto = (dto, dfrom)
    return (dfrom, dto)

def get_profit_and_loss_comparative(
    date_from: Optional[str]=None,
    date_to: Optional[str]=None,
    *,
    exclude_closing: bool = False,
) -> Dict[str, Any]:
    """P&L for the selected period and two prior periods of the same length (comparative columns).

    Returns merged revenue/expense lines with ``amounts`` = [current, prior1, prior2], period labels, and
    range metadata for display.
    """
    dfrom, dto = _normalize_profit_loss_period(date_from, date_to)
    a = datetime.strptime(dfrom, '%Y-%m-%d').date()
    b = datetime.strptime(dto, '%Y-%m-%d').date()
    span_days = (b - a).days
    p1_end = a - timedelta(days=1)
    p1_start = p1_end - timedelta(days=span_days)
    p2_end = p1_start - timedelta(days=1)
    p2_start = p2_end - timedelta(days=span_days)
    period_pairs = [(dfrom, dto), (p1_start.strftime('%Y-%m-%d'), p1_end.strftime('%Y-%m-%d')), (p2_start.strftime('%Y-%m-%d'), p2_end.strftime('%Y-%m-%d'))]
    period_labels = [b.strftime('%d %B %Y'), p1_end.strftime('%d %B %Y'), p2_end.strftime('%d %B %Y')]
    reports = [
        get_profit_and_loss_report(df, dt, exclude_closing=exclude_closing)
        for df, dt in period_pairs
    ]

    def _merge_side(key: str, amount_key: str) -> List[Dict[str, Any]]:
        by_code: Dict[str, List[float]] = {}
        names: Dict[str, str] = {}
        for i, rep in enumerate(reports):
            for r in rep.get(key) or []:
                c = (r.get('code') or '').strip()
                if not c:
                    continue
                names[c] = str(r.get('name') or c).strip() or c
                by_code.setdefault(c, [0.0, 0.0, 0.0])
                by_code[c][i] = round(float(r.get(amount_key) or 0), 2)
        rows: List[Dict[str, Any]] = []
        for c in sorted(by_code.keys(), key=lambda x: str(x).upper()):
            rows.append({'code': c, 'name': names.get(c) or c, 'amounts': by_code[c]})
        return rows
    revenue_rows = _merge_side('revenue_accounts', 'amount')
    expense_rows = _merge_side('expense_accounts', 'amount')
    cost_of_sales_rows = _merge_side('cost_of_sales_accounts', 'amount')
    operating_expense_rows = _merge_side('operating_expense_accounts', 'amount')
    total_revenue = [round(float(r.get('total_revenue') or 0), 2) for r in reports]
    total_expense = [round(float(r.get('total_expense') or 0), 2) for r in reports]
    total_cost_of_sales = [round(float(r.get('total_cost_of_sales') or 0), 2) for r in reports]
    total_operating_expense = [round(float(r.get('total_operating_expense') or 0), 2) for r in reports]
    gross_profit = [round(float(r.get('gross_profit') or 0), 2) for r in reports]
    net_profit = [round(float(r.get('net_profit') or 0), 2) for r in reports]
    return {
        'date_from': dfrom,
        'date_to': dto,
        'period_labels': period_labels,
        'period_ranges': [
            {'date_from': period_pairs[i][0], 'date_to': period_pairs[i][1]} for i in range(3)
        ],
        'revenue_rows': revenue_rows,
        'expense_rows': expense_rows,
        'cost_of_sales_rows': cost_of_sales_rows,
        'operating_expense_rows': operating_expense_rows,
        'total_revenue': total_revenue,
        'total_expense': total_expense,
        'total_cost_of_sales': total_cost_of_sales,
        'total_operating_expense': total_operating_expense,
        'gross_profit': gross_profit,
        'net_profit': net_profit,
    }

def _build_coa_forest(coa_rows: Sequence[Dict[str, Any]], account_type: str) -> List[Dict[str, Any]]:
    """Root nodes for one COA type (ASSET / LIABILITY / EQUITY), with nested children."""
    want = (account_type or '').upper()
    typed = [a for a in coa_rows or [] if (a.get('type') or '').upper() == want and (a.get('status') or 'ACTIVE') == 'ACTIVE']
    by_id: Dict[int, Dict[str, Any]] = {}
    for a in typed:
        try:
            aid = int(a.get('account_id'))
        except (TypeError, ValueError):
            continue
        node = dict(a)
        node['children'] = []
        by_id[aid] = node
    roots: List[Dict[str, Any]] = []
    for a in typed:
        try:
            aid = int(a.get('account_id'))
        except (TypeError, ValueError):
            continue
        node = by_id.get(aid)
        if not node:
            continue
        pid_raw = a.get('parent_id')
        parent: Optional[Dict[str, Any]] = None
        if pid_raw is not None:
            try:
                parent = by_id.get(int(pid_raw))
            except (TypeError, ValueError):
                parent = None
        if parent is not None:
            parent['children'].append(node)
        else:
            roots.append(node)
    def _sort_nodes(nodes: List[Dict[str, Any]]) -> None:
        nodes.sort(key=lambda x: str(x.get('code') or '').upper())
        for n in nodes:
            ch = n.get('children') or []
            if ch:
                _sort_nodes(ch)
    _sort_nodes(roots)
    return roots

def _balance_sheet_amount_for_type(account_type: str, debit: float, credit: float) -> float:
    t = (account_type or '').upper()
    if t == 'ASSET':
        return round(debit - credit, 2)
    if t in ('LIABILITY', 'EQUITY'):
        return round(credit - debit, 2)
    return round(debit - credit, 2)

def _balance_sheet_tree_to_rows(node: Dict[str, Any], depth: int, amounts_by_code: Dict[str, float]) -> Tuple[float, List[Dict[str, Any]]]:
    """Return (rollup amount, display rows) for one COA subtree."""
    code = str(node.get('code') or '').strip()
    code_u = code.upper()
    is_postable = bool(node.get('is_postable'))
    children = list(node.get('children') or [])
    child_rows: List[Dict[str, Any]] = []
    child_sum = 0.0
    for ch in children:
        amt, rows = _balance_sheet_tree_to_rows(ch, depth + 1, amounts_by_code)
        child_sum += amt
        child_rows.extend(rows)
    if is_postable:
        amount = float(amounts_by_code.get(code_u, 0.0))
    else:
        amount = child_sum
    amount = round(amount, 2)
    out: List[Dict[str, Any]] = []
    if not is_postable and children:
        if abs(amount) >= 0.005 or child_rows:
            out.append({'code': code, 'name': node.get('name') or code, 'type': node.get('type') or '', 'amount': amount, 'depth': depth, 'is_group': True, 'is_postable': False})
        out.extend(child_rows)
    elif is_postable and abs(amount) >= 0.005:
        out.append({'code': code, 'name': node.get('name') or code, 'type': node.get('type') or '', 'amount': amount, 'depth': depth, 'is_group': False, 'is_postable': True})
    return (amount, out)

def _balance_sheet_hierarchical_rows(coa_rows: Sequence[Dict[str, Any]], tb_rows: Sequence[Dict[str, Any]], account_type: str) -> Tuple[List[Dict[str, Any]], float]:
    """Hierarchical balance-sheet lines for one side (assets / liabilities / equity)."""
    want = (account_type or '').upper()
    amounts: Dict[str, float] = {}
    for r in tb_rows or []:
        if (r.get('type') or '').upper() != want:
            continue
        code_u = str(r.get('code') or '').strip().upper()
        if not code_u:
            continue
        amounts[code_u] = _balance_sheet_amount_for_type(want, float(r.get('debit') or 0), float(r.get('credit') or 0))
    forest = _build_coa_forest(coa_rows, want)
    rows: List[Dict[str, Any]] = []
    total = 0.0
    seen_codes: set[str] = set()
    for root in forest:
        amt, part = _balance_sheet_tree_to_rows(root, 0, amounts)
        total += amt
        rows.extend(part)
        for p in part:
            cu = str(p.get('code') or '').strip().upper()
            if cu:
                seen_codes.add(cu)
    # GL balances on codes not linked in COA tree (or orphan postings)
    coa_by_code = {str(a.get('code') or '').strip().upper(): a for a in coa_rows or [] if str(a.get('code') or '').strip()}
    for code_u, amount in sorted(amounts.items(), key=lambda x: x[0]):
        if code_u in seen_codes or abs(amount) < 0.005:
            continue
        meta = coa_by_code.get(code_u) or {}
        rows.append({'code': code_u, 'name': meta.get('name') or code_u, 'type': want, 'amount': round(amount, 2), 'depth': 0, 'is_group': False, 'is_postable': True})
        total += amount
    return (rows, round(total, 2))

def get_balance_sheet_report(as_of_date: Optional[str]=None) -> Dict[str, Any]:
    dto = _to_iso_date(as_of_date)
    tb = get_trial_balance_report(date_from=None, date_to=dto)
    pl = get_profit_and_loss_report(date_from=None, date_to=dto)
    coa_rows = get_all_chart_of_accounts()
    assets, total_assets = _balance_sheet_hierarchical_rows(coa_rows, tb, 'ASSET')
    liabilities, total_liabilities = _balance_sheet_hierarchical_rows(coa_rows, tb, 'LIABILITY')
    equities, total_equity = _balance_sheet_hierarchical_rows(coa_rows, tb, 'EQUITY')
    retained_earnings = round(float(pl.get('net_profit') or 0), 2)
    if retained_earnings != 0:
        equities.append({'code': 'P&L', 'name': 'Current Period Earnings', 'type': 'EQUITY', 'amount': retained_earnings, 'depth': 0, 'is_group': False, 'is_postable': False})
        total_equity += retained_earnings
    return {'assets': assets, 'liabilities': liabilities, 'equities': equities, 'total_assets': round(total_assets, 2), 'total_liabilities': round(total_liabilities, 2), 'total_equity': round(total_equity, 2), 'liabilities_plus_equity': round(total_liabilities + total_equity, 2)}

def _coa_name_code_suggests_cash_or_bank(name: str, code: str) -> bool:
    """Heuristic: this COA name/code looks like cash, bank, or cash-equivalent (not generic fixed asset)."""
    n = f"{name or ''} {code or ''}".upper()
    n = ' '.join(n.split())
    if 'BANK' in n or 'CASH' in n:
        return True
    for kw in ('SAVINGS', 'SAVING', 'DEPOSIT', 'DEPOSITS', 'CASA', 'CASHBOOK', 'CASH BOOK', 'PETTY', 'CASHIER', 'TILL', 'MONEY', 'WALLET', 'OVERDRAFT', 'OD ACC', 'CHEQUE', 'CHECKING', 'C/A', 'VOSTRO', 'NOSTRO', 'NEFT', 'RTGS', 'IMPS', 'FDR'):
        if kw in n:
            return True
    return False

def is_cash_bank_family_account(acc: Optional[Dict[str, Any]], accounts_by_id: Optional[Dict[Any, Dict[str, Any]]]=None) -> bool:
    """True if this postable account is in the cash/bank part of the tree (self or an ancestor name/code matches)."""
    if not acc:
        return False
    if accounts_by_id is None:
        coa = get_all_chart_of_accounts()
        by_id: Dict[Any, Dict[str, Any]] = {a.get('account_id'): a for a in coa}
    else:
        by_id = accounts_by_id
    cur: Optional[Dict[str, Any]] = acc
    hop = 0
    while cur and hop < 30:
        if _coa_name_code_suggests_cash_or_bank(str(cur.get('name') or ''), str(cur.get('code') or '')):
            return True
        cur = by_id.get(cur.get('parent_id'))
        hop += 1
    return False

def _get_cash_bank_postable_codes() -> Dict[str, str]:
    coa = get_all_chart_of_accounts()
    by_id = {a.get('account_id'): a for a in coa}
    return {(a.get('code') or '').strip(): a.get('name') or '' for a in coa if (a.get('type') or '').upper() == 'ASSET' and bool(a.get('is_postable')) and is_cash_bank_family_account(a, by_id)}

def _classify_cash_flow_category(account_type: str, account_name: str, account_code: str='') -> str:
    t = (account_type or '').upper()
    n = (account_name or '').upper()
    if t == 'EQUITY':
        return 'financing'
    if t == 'LIABILITY':
        if any((k in n for k in ('LOAN', 'BORROW', 'FINANCE', 'MORTGAGE', 'CAPITAL'))):
            return 'financing'
        return 'operating'
    if t == 'ASSET':
        if _coa_name_code_suggests_cash_or_bank(account_name or '', account_code or ''):
            return 'operating'
        if any((k in n for k in ('FIXED', 'PROPERTY', 'PLANT', 'EQUIPMENT', 'MACHINERY', 'VEHICLE', 'BUILDING', 'LAND', 'INVESTMENT', 'INTANGIBLE'))):
            return 'investing'
        return 'operating'
    if t in ('REVENUE', 'EXPENSE'):
        return 'operating'
    return 'operating'

def get_cash_flow_report(date_from: Optional[str]=None, date_to: Optional[str]=None) -> Dict[str, Any]:
    ensure_gl_tables()
    cash_bank_codes = _get_cash_bank_postable_codes()
    if not cash_bank_codes:
        return {'rows': [], 'opening_balance': 0.0, 'total_inflow': 0.0, 'total_outflow': 0.0, 'net_change': 0.0, 'closing_balance': 0.0, 'section_totals': {'operating': {'inflow': 0.0, 'outflow': 0.0, 'net': 0.0}, 'investing': {'inflow': 0.0, 'outflow': 0.0, 'net': 0.0}, 'financing': {'inflow': 0.0, 'outflow': 0.0, 'net': 0.0}}}
    code_keys = sorted(list(cash_bank_codes.keys()))
    bind_pairs = [(f'c{idx}', code) for idx, code in enumerate(code_keys)]
    in_clause = ', '.join((f':{k}' for k, _ in bind_pairs))
    name_by_code_upper = {(k or '').strip().upper(): v or '' for k, v in cash_bank_codes.items()}
    dfrom = _to_iso_date(date_from)
    dto = _to_iso_date(date_to)
    base_params: Dict[str, Any] = {k: (v or '').strip().upper() for k, v in bind_pairs}
    opening_balance = 0.0
    if dfrom:
        opening_q = f"\n            SELECT ROUND(SUM(NVL(d.DEBIT,0) - NVL(d.CREDIT,0)), 2) AS opening_balance\n            FROM {GL_DTL_TABLE} d\n            JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n            WHERE TRIM(UPPER(d.ACCOUNT_CODE)) IN ({in_clause})\n              AND TRUNC(h.VOUCHER_DATE) < TO_DATE(:df, 'YYYY-MM-DD')\n        "
        opening_params = dict(base_params)
        opening_params['df'] = dfrom
        opening_row = _safe_rows(opening_q, opening_params)
        opening_balance = float((opening_row[0] or {}).get('opening_balance') or 0)
    where = [f'TRIM(UPPER(d.ACCOUNT_CODE)) IN ({in_clause})']
    params = dict(base_params)
    if dfrom:
        where.append("TRUNC(h.VOUCHER_DATE) >= TO_DATE(:df, 'YYYY-MM-DD')")
        params['df'] = dfrom
    if dto:
        where.append("TRUNC(h.VOUCHER_DATE) <= TO_DATE(:dt, 'YYYY-MM-DD')")
        params['dt'] = dto
    q = f"\n        SELECT h.VOUCHER_DATE, d.VOUCHER_NO, d.LINE_NO, d.ACCOUNT_CODE, d.DEBIT, d.CREDIT, h.NARRATION, h.REFERENCE_NO\n        FROM {GL_DTL_TABLE} d\n        JOIN {GL_HDR_TABLE} h ON h.VOUCHER_NO = d.VOUCHER_NO\n        WHERE {' AND '.join(where)}\n        ORDER BY h.VOUCHER_DATE, d.VOUCHER_NO, d.LINE_NO\n    "
    rows = _safe_rows(q, params)
    voucher_nos = sorted({str(r.get('voucher_no') or '').strip() for r in rows or [] if str(r.get('voucher_no') or '').strip()})
    voucher_category: Dict[str, str] = {}
    if voucher_nos:
        coa_map = {(a.get('code') or '').strip(): a for a in get_all_chart_of_accounts()}
        voucher_params: Dict[str, Any] = {}
        voucher_binds = []
        for idx, vno in enumerate(voucher_nos):
            key = f'v{idx}'
            voucher_binds.append(f':{key}')
            voucher_params[key] = vno
        voucher_q = f"\n            SELECT d.VOUCHER_NO, d.ACCOUNT_CODE, NVL(d.DEBIT,0) AS debit, NVL(d.CREDIT,0) AS credit\n            FROM {GL_DTL_TABLE} d\n            WHERE d.VOUCHER_NO IN ({', '.join(voucher_binds)})\n        "
        vrows = _safe_rows(voucher_q, voucher_params)
        cash_bank_upper = {(k or '').strip().upper() for k in cash_bank_codes}
        bucket_by_voucher: Dict[str, Dict[str, float]] = {}
        for vr in vrows or []:
            vno = str(vr.get('voucher_no') or '').strip()
            acc = str(vr.get('account_code') or '').strip()
            if not vno or not acc:
                continue
            if (acc or '').strip().upper() in cash_bank_upper:
                continue
            meta = coa_map.get(acc) or {}
            if not meta:
                u = acc.strip().upper()
                for k, arow in coa_map.items():
                    if (k or '').strip().upper() == u:
                        meta = arow
                        break
            typ = str(meta.get('type') or '').upper()
            name = str(meta.get('name') or '')
            acode = str(meta.get('code') or acc or '')
            cat = _classify_cash_flow_category(typ, name, acode)
            amt = abs(float(vr.get('debit') or 0) - float(vr.get('credit') or 0))
            if amt <= 0:
                continue
            if vno not in bucket_by_voucher:
                bucket_by_voucher[vno] = {'operating': 0.0, 'investing': 0.0, 'financing': 0.0}
            bucket_by_voucher[vno][cat] += amt
        for vno, b in bucket_by_voucher.items():
            cat = 'operating'
            if b.get('investing', 0) >= b.get('operating', 0) and b.get('investing', 0) >= b.get('financing', 0):
                cat = 'investing'
            elif b.get('financing', 0) >= b.get('operating', 0) and b.get('financing', 0) >= b.get('investing', 0):
                cat = 'financing'
            voucher_category[vno] = cat
    total_inflow = 0.0
    total_outflow = 0.0
    section_totals: Dict[str, Dict[str, float]] = {'operating': {'inflow': 0.0, 'outflow': 0.0, 'net': 0.0}, 'investing': {'inflow': 0.0, 'outflow': 0.0, 'net': 0.0}, 'financing': {'inflow': 0.0, 'outflow': 0.0, 'net': 0.0}}
    running = opening_balance
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        dr = float(r.get('debit') or 0)
        cr = float(r.get('credit') or 0)
        net = dr - cr
        vno = str(r.get('voucher_no') or '').strip()
        section = voucher_category.get(vno, 'operating')
        running += net
        total_inflow += dr
        total_outflow += cr
        section_totals[section]['inflow'] += dr
        section_totals[section]['outflow'] += cr
        section_totals[section]['net'] += net
        code = (r.get('account_code') or '').strip()
        cku = (code or '').strip().upper()
        out.append({'voucher_date': r.get('voucher_date'), 'voucher_no': vno, 'reference_no': r.get('reference_no'), 'narration': r.get('narration'), 'account_code': code, 'account_name': name_by_code_upper.get(cku) or code, 'inflow': round(dr, 2), 'outflow': round(cr, 2), 'net_movement': round(net, 2), 'section': section, 'running_balance': round(running, 2)})
    net_change = total_inflow - total_outflow
    closing_balance = opening_balance + net_change
    return {'rows': out, 'opening_balance': round(opening_balance, 2), 'total_inflow': round(total_inflow, 2), 'total_outflow': round(total_outflow, 2), 'net_change': round(net_change, 2), 'closing_balance': round(closing_balance, 2), 'section_totals': {'operating': {'inflow': round(section_totals['operating']['inflow'], 2), 'outflow': round(section_totals['operating']['outflow'], 2), 'net': round(section_totals['operating']['net'], 2)}, 'investing': {'inflow': round(section_totals['investing']['inflow'], 2), 'outflow': round(section_totals['investing']['outflow'], 2), 'net': round(section_totals['investing']['net'], 2)}, 'financing': {'inflow': round(section_totals['financing']['inflow'], 2), 'outflow': round(section_totals['financing']['outflow'], 2), 'net': round(section_totals['financing']['net'], 2)}}}


def _supplier_gl_payable_context() -> Optional[Dict[str, Any]]:
    """Preloaded GL party maps for supplier payable balance (Accounts Payable logic)."""
    if not ensure_gl_tables():
        return None
    if not _table_exists(GL_DTL_TABLE):
        return None
    default_pay = str(DEFAULT_PARTY_ACCOUNTS.get('supplier_payable') or '2110').strip()
    party_account_bal_map: Dict[Tuple[str, str], float] = {}
    party_accounts_map: Dict[str, List[Tuple[str, float]]] = {}
    party_total_bal_map: Dict[str, float] = {}
    try:
        party_rows = _safe_rows(
            f"""
            SELECT TRIM(TO_CHAR(d.PARTY_CODE)) AS party_code, d.ACCOUNT_CODE AS account_code,
                   SUM(d.DEBIT) AS debit, SUM(d.CREDIT) AS credit
              FROM {GL_DTL_TABLE} d
             WHERE UPPER(NVL(d.PARTY_TYPE, '')) = 'SUPPLIER'
               AND d.PARTY_CODE IS NOT NULL
             GROUP BY TRIM(TO_CHAR(d.PARTY_CODE)), d.ACCOUNT_CODE
            """,
            {},
        )
        for r in party_rows or []:
            pcode = _norm_supplier_key(r.get('party_code'))
            acc = _norm_supplier_key(r.get('account_code'))
            if not pcode:
                continue
            bal = round(float(r.get('credit') or 0) - float(r.get('debit') or 0), 2)
            if acc:
                party_account_bal_map[pcode, acc] = bal
                party_accounts_map.setdefault(pcode, []).append((acc, bal))
            party_total_bal_map[pcode] = round(party_total_bal_map.get(pcode, 0.0) + bal, 2)
    except Exception:
        party_account_bal_map = {}
        party_accounts_map = {}
        party_total_bal_map = {}
    tb = get_trial_balance_report()
    tb_map = {_norm_supplier_key(r.get('code')): r for r in tb}
    coa_type_map = {_norm_supplier_key(r.get('code')): str(r.get('type') or '').upper() for r in get_all_chart_of_accounts()}
    return {
        'default_pay': default_pay,
        'party_account_bal_map': party_account_bal_map,
        'party_accounts_map': party_accounts_map,
        'party_total_bal_map': party_total_bal_map,
        'tb_map': tb_map,
        'coa_type_map': coa_type_map,
    }


def _supplier_gl_payable_balance(
    supplier_code: Any,
    payable_account: Any = None,
    *,
    ctx: Optional[Dict[str, Any]] = None,
    allow_control_fallback: bool = True,
) -> Tuple[float, str]:
    """GL payable balance for one supplier (credit minus debit), same as Accounts Payable."""
    context = ctx if ctx is not None else _supplier_gl_payable_context()
    if not context:
        return (0.0, 'NO_GL')
    default_pay = str(context.get('default_pay') or '2110').strip()
    party_account_bal_map: Dict[Tuple[str, str], float] = context.get('party_account_bal_map') or {}
    party_accounts_map: Dict[str, List[Tuple[str, float]]] = context.get('party_accounts_map') or {}
    party_total_bal_map: Dict[str, float] = context.get('party_total_bal_map') or {}
    tb_map: Dict[str, Dict[str, Any]] = context.get('tb_map') or {}
    coa_type_map: Dict[str, str] = context.get('coa_type_map') or {}

    supplier_code_norm = _norm_supplier_key(supplier_code)
    raw_ac = payable_account
    ac = _norm_supplier_key(raw_ac) if raw_ac not in (None, '') else _norm_supplier_key(default_pay)
    if not ac:
        ac = _norm_supplier_key(default_pay)
    bal = 0.0
    src = 'NO_PARTY'
    if supplier_code_norm and supplier_code_norm in party_accounts_map:
        supplier_party_accounts = party_accounts_map.get(supplier_code_norm) or []
        liability_lines = [
            (acc_code, b)
            for acc_code, b in supplier_party_accounts
            if coa_type_map.get(_norm_supplier_key(acc_code)) == 'LIABILITY'
        ]
        if liability_lines:
            bal = round(sum(b for _, b in liability_lines), 2)
            src = 'PARTY_LIABILITY'
        elif ac and (supplier_code_norm, ac) in party_account_bal_map:
            bal = party_account_bal_map[supplier_code_norm, ac]
            src = 'PARTY_MAPPED_ACC'
        elif supplier_code_norm in party_total_bal_map:
            bal = party_total_bal_map[supplier_code_norm]
            src = 'PARTY_TOTAL'
    elif supplier_code_norm and ac and (supplier_code_norm, ac) in party_account_bal_map:
        bal = party_account_bal_map[supplier_code_norm, ac]
        src = 'PARTY_MAPPED_ACC'
    elif allow_control_fallback:
        row = tb_map.get(ac)
        if row:
            bal = round(float(row.get('credit') or 0) - float(row.get('debit') or 0), 2)
            src = 'CONTROL_FALLBACK'
    return (bal, src)


def _supplier_open_documents_outstanding_total(
    supplier_code: Any,
    *,
    doc_totals: Optional[Dict[str, float]] = None,
) -> float:
    """Sum open AP document outstanding for one supplier."""
    key = _norm_supplier_key(supplier_code)
    if not key:
        return 0.0
    if doc_totals is not None:
        return round(float(doc_totals.get(key) or 0), 2)
    total = 0.0
    for doc in get_supplier_open_invoices_for_payment(supplier_code) or []:
        total += float(doc.get('open_amount') or 0)
    return round(total, 2)


def _supplier_open_documents_outstanding_totals() -> Dict[str, float]:
    """Map normalized supplier code -> total open AP outstanding from GL documents."""
    totals: Dict[str, float] = {}
    supplier_table = _detect_table(['SUPPLIER', 'supplier'])
    if not supplier_table:
        return totals
    code_col = _detect_column(supplier_table, ['SUPPLIERCODE', 'suppliercode'])
    if not code_col:
        return totals
    rows = _safe_rows(f'SELECT {code_col} AS suppliercode FROM {supplier_table}', {})
    for r in rows or []:
        key = _norm_supplier_key(r.get('suppliercode'))
        if not key:
            continue
        amt = _supplier_open_documents_outstanding_total(key)
        if amt:
            totals[key] = amt
    return totals


def get_accounts_payable_summary() -> List[Dict[str, Any]]:
    """Supplier + payable account + current balance from GL.

    Balance priority:
    1) Party-based GL totals (PARTY_TYPE='SUPPLIER' and PARTY_CODE=suppliercode), LIABILITY lines only
    2) Open AP document outstanding for that supplier
    Never uses whole payable control-account balance per supplier (avoids inflated AP variance).
    """
    ensure_gl_tables()
    supplier_table = _detect_table(['SUPPLIER', 'supplier'])
    if not supplier_table:
        return []
    loc_col = _detect_column(supplier_table, ['LOCATIONCODE', 'locationcode'])
    code_col = _detect_column(supplier_table, ['SUPPLIERCODE', 'suppliercode'])
    name_col = _detect_column(supplier_table, ['SUPPLIERNAME', 'suppliername'])
    acc_col = _detect_column(supplier_table, ['PAYABLEACCOUNT', 'payableaccount'])
    if not code_col or not name_col or (not acc_col):
        return []
    select_cols = []
    if loc_col:
        select_cols.append(f'{loc_col} AS locationcode')
    else:
        select_cols.append('NULL AS locationcode')
    select_cols.extend([f'{code_col} AS suppliercode', f'{name_col} AS suppliername', f'{acc_col} AS payableaccount'])
    suppliers = _safe_rows(f"SELECT {', '.join(select_cols)} FROM {supplier_table} ORDER BY {code_col}", {})
    gl_ctx = _supplier_gl_payable_context()
    doc_totals = _supplier_open_documents_outstanding_totals()
    out: List[Dict[str, Any]] = []
    for s in suppliers or []:
        supplier_code = _norm_supplier_key(s.get('suppliercode'))
        ac = _norm_supplier_key(s.get('payableaccount'))
        bal_gl, src = _supplier_gl_payable_balance(
            supplier_code, ac, ctx=gl_ctx, allow_control_fallback=False,
        )
        if src in ('PARTY_LIABILITY', 'PARTY_MAPPED_ACC', 'PARTY_TOTAL'):
            bal = bal_gl
        else:
            bal = _supplier_open_documents_outstanding_total(supplier_code, doc_totals=doc_totals)
            if bal:
                src = 'OPEN_DOCS'
        out.append({
            'locationcode': s.get('locationcode'),
            'suppliercode': s.get('suppliercode'),
            'suppliername': s.get('suppliername'),
            'payableaccount': ac,
            'payable_balance': bal,
            'party_code_in_gl_dtl': supplier_code if supplier_code and gl_ctx and supplier_code in (gl_ctx.get('party_accounts_map') or {}) else '',
            'balance_source': src,
        })
    return out

def _customer_gl_receivable_context() -> Optional[Dict[str, Any]]:
    """Preloaded GL party maps for customer receivable balance (Accounts Receivable logic)."""
    if not ensure_gl_tables():
        return None
    if not _table_exists(GL_DTL_TABLE):
        return None
    default_recv = str(DEFAULT_PARTY_ACCOUNTS.get('customer_receivable') or '1200').strip()
    party_account_bal_map: Dict[Tuple[str, str], float] = {}
    party_accounts_map: Dict[str, List[Tuple[str, float]]] = {}
    party_total_bal_map: Dict[str, float] = {}
    try:
        party_rows = _safe_rows(
            f"""
            SELECT TRIM(TO_CHAR(d.PARTY_CODE)) AS party_code, d.ACCOUNT_CODE AS account_code,
                   SUM(d.DEBIT) AS debit, SUM(d.CREDIT) AS credit
              FROM {GL_DTL_TABLE} d
             WHERE UPPER(NVL(d.PARTY_TYPE, '')) = 'CUSTOMER'
               AND d.PARTY_CODE IS NOT NULL
             GROUP BY TRIM(TO_CHAR(d.PARTY_CODE)), d.ACCOUNT_CODE
            """,
            {},
        )
        for r in party_rows or []:
            pcode = _norm_supplier_key(r.get('party_code'))
            acc = _norm_supplier_key(r.get('account_code'))
            if not pcode:
                continue
            bal = round(float(r.get('debit') or 0) - float(r.get('credit') or 0), 2)
            if acc:
                party_account_bal_map[pcode, acc] = bal
                party_accounts_map.setdefault(pcode, []).append((acc, bal))
            party_total_bal_map[pcode] = round(party_total_bal_map.get(pcode, 0.0) + bal, 2)
    except Exception:
        party_account_bal_map = {}
        party_accounts_map = {}
        party_total_bal_map = {}
    tb_map = {_norm_supplier_key(r.get('code')): r for r in get_trial_balance_report()}
    coa_type_map = {
        _norm_supplier_key(r.get('code')): str(r.get('type') or '').upper()
        for r in get_all_chart_of_accounts()
    }
    return {
        'default_recv': default_recv,
        'party_account_bal_map': party_account_bal_map,
        'party_accounts_map': party_accounts_map,
        'party_total_bal_map': party_total_bal_map,
        'tb_map': tb_map,
        'coa_type_map': coa_type_map,
    }


def _customer_gl_receivable_balance(
    customer_code: Any,
    receivable_account: Any = None,
    *,
    ctx: Optional[Dict[str, Any]] = None,
    allow_control_fallback: bool = True,
) -> Tuple[float, str]:
    """GL receivable balance for one customer (debit minus credit), same as Accounts Receivable."""
    context = ctx if ctx is not None else _customer_gl_receivable_context()
    if not context:
        return (0.0, 'NO_GL')
    default_recv = str(context.get('default_recv') or '1200').strip()
    party_account_bal_map: Dict[Tuple[str, str], float] = context.get('party_account_bal_map') or {}
    party_accounts_map: Dict[str, List[Tuple[str, float]]] = context.get('party_accounts_map') or {}
    party_total_bal_map: Dict[str, float] = context.get('party_total_bal_map') or {}
    tb_map: Dict[str, Dict[str, Any]] = context.get('tb_map') or {}
    coa_type_map: Dict[str, str] = context.get('coa_type_map') or {}

    customer_code_norm = _norm_supplier_key(customer_code)
    raw_ac = receivable_account
    ac = _norm_supplier_key(raw_ac) if raw_ac not in (None, '') else _norm_supplier_key(default_recv)
    if not ac:
        ac = _norm_supplier_key(default_recv)
    bal = 0.0
    src = 'NO_PARTY'
    if customer_code_norm and customer_code_norm in party_accounts_map:
        customer_party_accounts = party_accounts_map.get(customer_code_norm) or []
        asset_lines = [
            (acc_code, b)
            for acc_code, b in customer_party_accounts
            if coa_type_map.get(_norm_supplier_key(acc_code)) == 'ASSET'
        ]
        if asset_lines:
            bal = round(sum(b for _, b in asset_lines), 2)
            src = 'PARTY_ASSET'
        elif ac and (customer_code_norm, ac) in party_account_bal_map:
            bal = party_account_bal_map[customer_code_norm, ac]
            src = 'PARTY_MAPPED_ACC'
        elif customer_code_norm in party_total_bal_map:
            bal = party_total_bal_map[customer_code_norm]
            src = 'PARTY_TOTAL'
    elif customer_code_norm and ac and (customer_code_norm, ac) in party_account_bal_map:
        bal = party_account_bal_map[customer_code_norm, ac]
        src = 'PARTY_MAPPED_ACC'
    elif allow_control_fallback:
        row = tb_map.get(ac)
        if row:
            bal = round(float(row.get('debit') or 0) - float(row.get('credit') or 0), 2)
            src = 'CONTROL_FALLBACK'
    return (bal, src)


def _customer_open_documents_outstanding_total(
    customer_code: Any,
    *,
    doc_totals: Optional[Dict[str, float]] = None,
) -> float:
    """Sum open AR document outstanding for one customer (GL voucher allocations)."""
    key = _norm_supplier_key(customer_code)
    if not key:
        return 0.0
    if doc_totals is not None:
        return round(float(doc_totals.get(key) or 0), 2)
    total = 0.0
    for doc in _customer_open_documents_gl(customer_code=customer_code) or []:
        total += float(doc.get('outstanding') or 0)
    return round(total, 2)


def _customer_open_documents_outstanding_totals() -> Dict[str, float]:
    """Map normalized customer code -> total open AR outstanding from GL documents."""
    totals: Dict[str, float] = {}
    for doc in _customer_open_documents_gl() or []:
        key = _norm_supplier_key(doc.get('customercode'))
        if not key:
            continue
        totals[key] = round(totals.get(key, 0.0) + float(doc.get('outstanding') or 0), 2)
    return totals


def _customer_list_gl_outstanding(
    customer_code: Any,
    receivable_account: Any = None,
    *,
    ctx: Optional[Dict[str, Any]] = None,
    doc_totals: Optional[Dict[str, float]] = None,
) -> float:
    """
    Per-customer outstanding for list screens.

    Uses party sub-ledger on GL detail when present; otherwise open AR documents
    for that customer. Never repeats the whole receivable control-account balance.
    """
    bal, src = _customer_gl_receivable_balance(
        customer_code,
        receivable_account,
        ctx=ctx,
        allow_control_fallback=False,
    )
    if src in ('PARTY_ASSET', 'PARTY_MAPPED_ACC', 'PARTY_TOTAL'):
        return bal
    return _customer_open_documents_outstanding_total(customer_code, doc_totals=doc_totals)


def get_accounts_receivable_summary() -> List[Dict[str, Any]]:
    """Customer + receivable account + current balance from GL.

    Balance priority:
    1) Party-based GL totals (PARTY_TYPE='CUSTOMER' and PARTY_CODE=customercode), ASSET lines only
    2) Open AR document outstanding for that customer
    Never uses whole receivable control-account balance per customer (avoids inflated AR variance).
    """
    ensure_gl_tables()
    default_recv = str(DEFAULT_PARTY_ACCOUNTS.get('customer_receivable') or '1200').strip()
    table_candidates = ['CUSTOMER', 'CUSTOMERS', 'customer', 'customers']
    customer_table = None
    for t in table_candidates:
        if _table_exists(t):
            customer_table = t
            break
    if not customer_table:
        return []
    loc_col = _detect_column(customer_table, ['LOCATIONCODE', 'locationcode'])
    code_col = _detect_column(customer_table, ['CUSTOMERCODE', 'CUST_CODE', 'CUSTOMER_CODE', 'CODE', 'code'])
    name_col = _detect_column(customer_table, ['CUSTOMERNAME', 'CUST_NAME', 'CUSTOMER_NAME', 'NAME', 'name'])
    acc_col = _detect_column(customer_table, ['RECEIVABLEACCOUNT', 'receivableaccount', 'RECEIVABLE_AC', 'receivable_acct'])
    if not code_col or not name_col:
        return []
    select_cols: List[str] = []
    if loc_col:
        select_cols.append(f'{loc_col} AS locationcode')
    else:
        select_cols.append('NULL AS locationcode')
    select_cols.append(f'{code_col} AS customercode')
    select_cols.append(f'{name_col} AS customername')
    if acc_col:
        select_cols.append(f'{acc_col} AS receivableaccount')
    else:
        select_cols.append('NULL AS receivableaccount')
    customers = _safe_rows(f"SELECT {', '.join(select_cols)} FROM {customer_table} ORDER BY {code_col}", {})
    gl_ctx = _customer_gl_receivable_context()
    doc_totals = _customer_open_documents_outstanding_totals()
    out: List[Dict[str, Any]] = []
    for s in customers or []:
        customer_code = _norm_supplier_key(s.get('customercode'))
        raw_ac = s.get('receivableaccount')
        ac = _norm_supplier_key(raw_ac) if raw_ac not in (None, '') else _norm_supplier_key(default_recv)
        if not ac:
            ac = _norm_supplier_key(default_recv)
        bal_gl, src = _customer_gl_receivable_balance(
            customer_code, ac, ctx=gl_ctx, allow_control_fallback=False,
        )
        if src in ('PARTY_ASSET', 'PARTY_MAPPED_ACC', 'PARTY_TOTAL'):
            bal = bal_gl
        else:
            bal = _customer_open_documents_outstanding_total(customer_code, doc_totals=doc_totals)
            if bal:
                src = 'OPEN_DOCS'
        out.append({
            'locationcode': s.get('locationcode'),
            'customercode': s.get('customercode'),
            'customername': s.get('customername'),
            'receivableaccount': ac,
            'receivable_balance': bal,
            'party_code_in_gl_dtl': customer_code if customer_code and gl_ctx and customer_code in (gl_ctx.get('party_accounts_map') or {}) else '',
            'balance_source': src,
        })
    return out
PDC_TABLE = 'PDCCHECK'
PDC_SEQ = 'PDCCHECK_SEQ'
PDC_AUDIT_TABLE = 'PDCCHECK_AUDIT'
PDC_AUDIT_SEQ = 'PDCCHECK_AUDIT_SEQ'
_PDC_AUDIT_FIELDS = ('pdc_type', 'cheque_no', 'cheque_date', 'bank_name', 'branch_name', 'amount', 'party_type', 'party_code', 'party_name', 'status', 'deposit_date', 'cleared_date', 'bounce_date', 'narration', 'remarks', 'locationcode')

def ensure_pdc_table() -> bool:
    """Create PDCCHECK table and sequence if they do not exist."""
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute('SELECT COUNT(*) FROM user_sequences WHERE sequence_name = :n', {'n': PDC_SEQ})
                if cur.fetchone()[0] == 0:
                    cur.execute(f'CREATE SEQUENCE {PDC_SEQ} START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE')
                    conn.commit()
        if not _table_exists(PDC_TABLE):
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute(f"\n                        CREATE TABLE {PDC_TABLE} (\n                            ID          NUMBER PRIMARY KEY,\n                            PDC_TYPE    VARCHAR2(10)  NOT NULL,\n                            CHEQUE_NO   VARCHAR2(50)  NOT NULL,\n                            CHEQUE_DATE DATE          NOT NULL,\n                            BANK_NAME   VARCHAR2(100),\n                            BRANCH_NAME VARCHAR2(100),\n                            AMOUNT      NUMBER(15,3)  NOT NULL,\n                            PARTY_TYPE  VARCHAR2(10),\n                            PARTY_CODE  VARCHAR2(30),\n                            PARTY_NAME  VARCHAR2(200),\n                            STATUS      VARCHAR2(20)  DEFAULT 'PENDING' NOT NULL,\n                            DEPOSIT_DATE   DATE,\n                            CLEARED_DATE   DATE,\n                            BOUNCE_DATE    DATE,\n                            NARRATION   VARCHAR2(500),\n                            REMARKS     VARCHAR2(500),\n                            LOCATIONCODE NUMBER,\n                            CREATED_BY  VARCHAR2(50),\n                            CREATED_DATE DATE DEFAULT SYSDATE,\n                            UPDATED_BY  VARCHAR2(50),\n                            UPDATED_DATE DATE\n                        )\n                        ")
                    conn.commit()
        _TABLE_EXISTS_CACHE.pop(PDC_TABLE, None)
        try:
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    _drop_category_fk_referencing_pdccheck(cur)
                conn.commit()
        except Exception as e_fix:
            print(f'[WARN ensure_pdc_table] strip CATEGORY FK to PDCCHECK: {e_fix}')
        return True
    except Exception as e:
        print(f'[ERROR ensure_pdc_table] {e}')
        return False

def ensure_pdc_audit_table() -> bool:
    """Create PDCCHECK_AUDIT table and sequence if missing (tenant DB)."""
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute('SELECT COUNT(*) FROM user_sequences WHERE sequence_name = :n', {'n': PDC_AUDIT_SEQ})
                if cur.fetchone()[0] == 0:
                    cur.execute(f'CREATE SEQUENCE {PDC_AUDIT_SEQ} START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE')
                    conn.commit()
        if not _table_exists(PDC_AUDIT_TABLE):
            with _get_connection() as conn:
                with conn.cursor() as cur:
                    cur.execute(f'\n                        CREATE TABLE {PDC_AUDIT_TABLE} (\n                            AUDIT_ID    NUMBER PRIMARY KEY,\n                            PDC_ID      NUMBER        NOT NULL,\n                            ACTION      VARCHAR2(24)  NOT NULL,\n                            USERNAME    VARCHAR2(128),\n                            LOGGED_AT   DATE DEFAULT SYSDATE NOT NULL,\n                            SUMMARY     VARCHAR2(400),\n                            DETAIL_JSON CLOB\n                        )\n                        ')
                    conn.commit()
        _TABLE_EXISTS_CACHE.pop(PDC_AUDIT_TABLE, None)
        return True
    except Exception as e:
        print(f'[ERROR ensure_pdc_audit_table] {e}')
        return False

def _pdc_norm_audit_val(field: str, val: Any) -> Any:
    if val is None:
        return None
    if field == 'amount':
        try:
            return round(float(val), 3)
        except (TypeError, ValueError):
            return val
    if field == 'locationcode':
        try:
            return int(val)
        except (TypeError, ValueError):
            return val
    if isinstance(val, str):
        return val.strip()
    return val

def _pdc_snapshot_for_audit(row: Dict[str, Any]) -> Dict[str, Any]:
    return {k: row.get(k) for k in _PDC_AUDIT_FIELDS}

def _pdc_diff_snapshots(old: Dict[str, Any], new: Dict[str, Any]) -> Tuple[List[Dict[str, Any]], str]:
    changes: List[Dict[str, Any]] = []
    parts: List[str] = []
    for k in _PDC_AUDIT_FIELDS:
        ov = _pdc_norm_audit_val(k, old.get(k))
        nv = _pdc_norm_audit_val(k, new.get(k))
        if ov != nv:
            changes.append({'field': k, 'old': old.get(k), 'new': new.get(k)})
            so = '' if ov is None else str(ov)[:80]
            sn = '' if nv is None else str(nv)[:80]
            parts.append(f'{k}: {so}→{sn}')
    summary = '; '.join(parts[:6])
    if len(parts) > 6:
        summary += f' (+{len(parts) - 6} more)'
    return (changes, summary)

def _pdc_audit_append(pdc_id: int, action: str, username: str, summary: str, detail: Optional[Dict[str, Any]]=None) -> None:
    try:
        ensure_pdc_audit_table()
        payload = json.dumps(detail or {}, default=str)
        act = (action or '')[:24]
        uname = (username or '')[:128]
        summ = (summary or '')[:400]
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f'\n                    INSERT INTO {PDC_AUDIT_TABLE}\n                        (AUDIT_ID, PDC_ID, ACTION, USERNAME, SUMMARY, DETAIL_JSON)\n                    VALUES ({PDC_AUDIT_SEQ}.NEXTVAL, :pid, :act, :uname, :summ, :dj)\n                    ', {'pid': pdc_id, 'act': act, 'uname': uname, 'summ': summ, 'dj': payload})
            conn.commit()
    except Exception as e:
        print(f'[WARN _pdc_audit_append] {e}')

def get_pdc_audit_log(pdc_id: Optional[int]=None, limit: int=500) -> List[Dict[str, Any]]:
    """Return recent PDC audit rows (newest first). Optional filter by PDC id."""
    ensure_pdc_audit_table()
    lim = max(1, min(int(limit or 500), 2000))
    if pdc_id is not None:
        sql = f'\n            SELECT * FROM (\n                SELECT AUDIT_ID, PDC_ID, ACTION, USERNAME, LOGGED_AT, SUMMARY, DETAIL_JSON\n                FROM {PDC_AUDIT_TABLE}\n                WHERE PDC_ID = :pid\n                ORDER BY LOGGED_AT DESC, AUDIT_ID DESC\n            ) WHERE ROWNUM <= :lim\n        '
        rows = _safe_rows(sql, {'pid': pdc_id, 'lim': lim})
    else:
        sql = f'\n            SELECT * FROM (\n                SELECT AUDIT_ID, PDC_ID, ACTION, USERNAME, LOGGED_AT, SUMMARY, DETAIL_JSON\n                FROM {PDC_AUDIT_TABLE}\n                ORDER BY LOGGED_AT DESC, AUDIT_ID DESC\n            ) WHERE ROWNUM <= :lim\n        '
        rows = _safe_rows(sql, {'lim': lim})
    out: List[Dict[str, Any]] = []
    for r in rows:
        dj = r.get('detail_json')
        parsed: Optional[Dict[str, Any]] = None
        if dj is not None:
            try:
                if isinstance(dj, str):
                    parsed = json.loads(dj)
                else:
                    parsed = json.loads(str(dj))
            except Exception:
                parsed = {'raw': str(dj)[:2000]}
        lt = r.get('logged_at')
        iso: Optional[str]
        if hasattr(lt, 'isoformat'):
            iso = lt.isoformat()
        elif lt:
            iso = str(lt)
        else:
            iso = None
        out.append({'audit_id': r.get('audit_id'), 'pdc_id': r.get('pdc_id'), 'action': r.get('action'), 'username': r.get('username'), 'logged_at': iso, 'summary': r.get('summary'), 'detail': parsed})
    return out

def _pdc_date(val: Any) -> Optional[str]:
    """Return ISO date string from an Oracle date value, or None."""
    if val is None:
        return None
    if hasattr(val, 'strftime'):
        return val.strftime('%Y-%m-%d')
    s = str(val).strip()
    try:
        return datetime.strptime(s[:10], '%Y-%m-%d').strftime('%Y-%m-%d')
    except Exception:
        return s or None

def _pdc_row_to_dict(r: Dict[str, Any]) -> Dict[str, Any]:
    return {'id': r.get('id'), 'pdc_type': str(r.get('pdc_type') or '').strip(), 'cheque_no': str(r.get('cheque_no') or '').strip(), 'cheque_date': _pdc_date(r.get('cheque_date')), 'bank_name': str(r.get('bank_name') or '').strip(), 'branch_name': str(r.get('branch_name') or '').strip(), 'amount': float(r.get('amount') or 0), 'party_type': str(r.get('party_type') or '').strip(), 'party_code': str(r.get('party_code') or '').strip(), 'party_name': str(r.get('party_name') or '').strip(), 'status': str(r.get('status') or 'PENDING').strip(), 'deposit_date': _pdc_date(r.get('deposit_date')), 'cleared_date': _pdc_date(r.get('cleared_date')), 'bounce_date': _pdc_date(r.get('bounce_date')), 'narration': str(r.get('narration') or '').strip(), 'remarks': str(r.get('remarks') or '').strip(), 'locationcode': r.get('locationcode'), 'created_by': str(r.get('created_by') or '').strip(), 'created_date': _pdc_date(r.get('created_date')), 'updated_by': str(r.get('updated_by') or '').strip(), 'updated_date': _pdc_date(r.get('updated_date'))}

def get_pdc_list(pdc_type: Optional[str]=None, status: Optional[str]=None, party_type: Optional[str]=None, date_from: Optional[str]=None, date_to: Optional[str]=None, search: Optional[str]=None) -> List[Dict[str, Any]]:
    """Return filtered list of PDC records, newest cheque date first."""
    ensure_pdc_table()
    where = ['1=1']
    params: Dict[str, Any] = {}
    if pdc_type:
        where.append('UPPER(PDC_TYPE) = UPPER(:pdc_type)')
        params['pdc_type'] = pdc_type
    if status:
        where.append('UPPER(STATUS) = UPPER(:status)')
        params['status'] = status
    if party_type:
        where.append('UPPER(PARTY_TYPE) = UPPER(:party_type)')
        params['party_type'] = party_type
    if date_from:
        where.append("CHEQUE_DATE >= TO_DATE(:date_from, 'YYYY-MM-DD')")
        params['date_from'] = date_from
    if date_to:
        where.append("CHEQUE_DATE <= TO_DATE(:date_to, 'YYYY-MM-DD')")
        params['date_to'] = date_to
    if search:
        where.append('(UPPER(CHEQUE_NO) LIKE UPPER(:s) OR UPPER(PARTY_NAME) LIKE UPPER(:s) OR UPPER(BANK_NAME) LIKE UPPER(:s) OR UPPER(PARTY_CODE) LIKE UPPER(:s))')
        params['s'] = f'%{search}%'
    sql = f"\n        SELECT ID, PDC_TYPE, CHEQUE_NO, CHEQUE_DATE, BANK_NAME, BRANCH_NAME,\n               AMOUNT, PARTY_TYPE, PARTY_CODE, PARTY_NAME, STATUS,\n               DEPOSIT_DATE, CLEARED_DATE, BOUNCE_DATE,\n               NARRATION, REMARKS, LOCATIONCODE, CREATED_BY, CREATED_DATE,\n               UPDATED_BY, UPDATED_DATE\n        FROM {PDC_TABLE}\n        WHERE {' AND '.join(where)}\n        ORDER BY CHEQUE_DATE DESC, ID DESC\n    "
    rows = _safe_rows(sql, params)
    return [_pdc_row_to_dict(r) for r in rows]

def get_pdc_by_id(pdc_id: int) -> Optional[Dict[str, Any]]:
    """Return a single PDC record by ID."""
    ensure_pdc_table()
    rows = _safe_rows(f'SELECT ID, PDC_TYPE, CHEQUE_NO, CHEQUE_DATE, BANK_NAME, BRANCH_NAME,\n                   AMOUNT, PARTY_TYPE, PARTY_CODE, PARTY_NAME, STATUS,\n                   DEPOSIT_DATE, CLEARED_DATE, BOUNCE_DATE,\n                   NARRATION, REMARKS, LOCATIONCODE, CREATED_BY, CREATED_DATE,\n                   UPDATED_BY, UPDATED_DATE\n            FROM {PDC_TABLE} WHERE ID = :id', {'id': pdc_id})
    return _pdc_row_to_dict(rows[0]) if rows else None

def get_pdc_summary() -> Dict[str, Any]:
    """Return dashboard counts/totals for PDC overview cards."""
    ensure_pdc_table()
    rows = _safe_rows(f'SELECT\n                STATUS,\n                COUNT(*) AS cnt,\n                SUM(AMOUNT) AS total\n            FROM {PDC_TABLE}\n            GROUP BY STATUS', {})
    summary: Dict[str, Any] = {'pending': {'count': 0, 'total': 0.0}, 'deposited': {'count': 0, 'total': 0.0}, 'cleared': {'count': 0, 'total': 0.0}, 'bounced': {'count': 0, 'total': 0.0}, 'cancelled': {'count': 0, 'total': 0.0}}
    for r in rows:
        key = str(r.get('status') or '').strip().lower()
        if key in summary:
            summary[key]['count'] = int(r.get('cnt') or 0)
            summary[key]['total'] = float(r.get('total') or 0)
    due_rows = _safe_rows(f"SELECT COUNT(*) AS cnt, SUM(AMOUNT) AS total\n            FROM {PDC_TABLE}\n            WHERE STATUS = 'PENDING'\n              AND CHEQUE_DATE <= SYSDATE + 7", {})
    if due_rows:
        summary['due_soon'] = {'count': int(due_rows[0].get('cnt') or 0), 'total': float(due_rows[0].get('total') or 0)}
    else:
        summary['due_soon'] = {'count': 0, 'total': 0.0}
    overdue_rows = _safe_rows(f"SELECT COUNT(*) AS cnt, SUM(AMOUNT) AS total\n            FROM {PDC_TABLE}\n            WHERE STATUS = 'PENDING'\n              AND CHEQUE_DATE < TRUNC(SYSDATE)", {})
    if overdue_rows:
        summary['overdue'] = {'count': int(overdue_rows[0].get('cnt') or 0), 'total': float(overdue_rows[0].get('total') or 0)}
    else:
        summary['overdue'] = {'count': 0, 'total': 0.0}
    return summary

def save_pdc(pdc_type: str, cheque_no: str, cheque_date: str, bank_name: str, branch_name: str, amount: float, party_type: str, party_code: str, party_name: str, narration: str, remarks: str, locationcode: Optional[int], created_by: str, pdc_id: Optional[int]=None) -> int:
    """Insert (pdc_id=None) or update a PDC record. Returns the record ID."""
    ensure_pdc_table()
    if pdc_id:
        old_row = get_pdc_by_id(pdc_id)
        sql = f"\n            UPDATE {PDC_TABLE} SET\n                PDC_TYPE    = :pdc_type,\n                CHEQUE_NO   = :cheque_no,\n                CHEQUE_DATE = TO_DATE(:cheque_date, 'YYYY-MM-DD'),\n                BANK_NAME   = :bank_name,\n                BRANCH_NAME = :branch_name,\n                AMOUNT      = :amount,\n                PARTY_TYPE  = :party_type,\n                PARTY_CODE  = :party_code,\n                PARTY_NAME  = :party_name,\n                NARRATION   = :narration,\n                REMARKS     = :remarks,\n                LOCATIONCODE= :locationcode,\n                UPDATED_BY  = :updated_by,\n                UPDATED_DATE= SYSDATE\n            WHERE ID = :id\n        "
        updated = 0
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(sql, {'pdc_type': pdc_type, 'cheque_no': cheque_no, 'cheque_date': cheque_date, 'bank_name': bank_name, 'branch_name': branch_name, 'amount': amount, 'party_type': party_type, 'party_code': party_code, 'party_name': party_name, 'narration': narration, 'remarks': remarks, 'locationcode': locationcode, 'updated_by': created_by, 'id': pdc_id})
                updated = cur.rowcount
            conn.commit()
        if updated > 0 and old_row:
            new_row = get_pdc_by_id(pdc_id)
            if new_row:
                changes, summary = _pdc_diff_snapshots(old_row, new_row)
                if changes:
                    _pdc_audit_append(pdc_id, 'UPDATED', created_by, summary or 'Updated', {'changes': changes, 'before': _pdc_snapshot_for_audit(old_row), 'after': _pdc_snapshot_for_audit(new_row)})
        return pdc_id
    else:
        sql = f"\n            INSERT INTO {PDC_TABLE}\n                (ID, PDC_TYPE, CHEQUE_NO, CHEQUE_DATE, BANK_NAME, BRANCH_NAME,\n                 AMOUNT, PARTY_TYPE, PARTY_CODE, PARTY_NAME, STATUS,\n                 NARRATION, REMARKS, LOCATIONCODE, CREATED_BY, CREATED_DATE)\n            VALUES\n                ({PDC_SEQ}.NEXTVAL, :pdc_type, :cheque_no,\n                 TO_DATE(:cheque_date, 'YYYY-MM-DD'), :bank_name, :branch_name,\n                 :amount, :party_type, :party_code, :party_name, 'PENDING',\n                 :narration, :remarks, :locationcode, :created_by, SYSDATE)\n        "
        new_id = 0
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(sql, {'pdc_type': pdc_type, 'cheque_no': cheque_no, 'cheque_date': cheque_date, 'bank_name': bank_name, 'branch_name': branch_name, 'amount': amount, 'party_type': party_type, 'party_code': party_code, 'party_name': party_name, 'narration': narration, 'remarks': remarks, 'locationcode': locationcode, 'created_by': created_by})
                cur.execute(f'SELECT {PDC_SEQ}.CURRVAL FROM DUAL')
                new_id = int(cur.fetchone()[0])
            conn.commit()
        snap = get_pdc_by_id(new_id)
        if snap:
            _pdc_audit_append(new_id, 'CREATED', created_by, f'PDC #{new_id} created ({cheque_no})', {'after': _pdc_snapshot_for_audit(snap)})
        return new_id

def update_pdc_status(pdc_id: int, new_status: str, updated_by: str, action_date: Optional[str]=None) -> bool:
    """Update status and the relevant date column (deposit/cleared/bounce)."""
    ensure_pdc_table()
    old_row = get_pdc_by_id(pdc_id)
    if not old_row:
        return False
    date_col_map = {'DEPOSITED': 'DEPOSIT_DATE', 'CLEARED': 'CLEARED_DATE', 'BOUNCED': 'BOUNCE_DATE'}
    status_up = new_status.strip().upper()
    date_col = date_col_map.get(status_up)
    date_bind = f"TO_DATE(:action_date, 'YYYY-MM-DD')" if action_date else 'SYSDATE'
    extra_set = f', {date_col} = {date_bind}' if date_col else ''
    params: Dict[str, Any] = {'status': status_up, 'updated_by': updated_by, 'id': pdc_id}
    if action_date and date_col:
        params['action_date'] = action_date
    sql = f'\n        UPDATE {PDC_TABLE}\n        SET STATUS = :status, UPDATED_BY = :updated_by, UPDATED_DATE = SYSDATE{extra_set}\n        WHERE ID = :id\n    '
    try:
        updated = 0
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(sql, params)
                updated = cur.rowcount
            conn.commit()
        if updated < 1:
            return False
        new_row = get_pdc_by_id(pdc_id)
        if new_row:
            changes, summary = _pdc_diff_snapshots(old_row, new_row)
            summ = summary or f'Status → {status_up}'
            if action_date:
                summ += f' (action date {action_date})'
            _pdc_audit_append(pdc_id, 'STATUS', updated_by, summ[:400], {'changes': changes, 'before': _pdc_snapshot_for_audit(old_row), 'after': _pdc_snapshot_for_audit(new_row), 'action_date_param': action_date})
        return True
    except Exception as e:
        print(f'[ERROR update_pdc_status] {e}')
        return False

def delete_pdc(pdc_id: int, deleted_by: Optional[str]=None) -> bool:
    """Hard-delete a PDC record (only allowed when status = PENDING or CANCELLED)."""
    try:
        snap = get_pdc_by_id(pdc_id)
        if not snap:
            return False
        deleted = 0
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f"DELETE FROM {PDC_TABLE} WHERE ID = :id AND STATUS IN ('PENDING','CANCELLED')", {'id': pdc_id})
                deleted = cur.rowcount
            conn.commit()
        if deleted < 1:
            return False
        _pdc_audit_append(pdc_id, 'DELETED', deleted_by or '', f"Deleted PDC #{pdc_id} ({snap.get('cheque_no') or ''})".strip(), {'snapshot': _pdc_snapshot_for_audit(snap)})
        return True
    except Exception as e:
        print(f'[ERROR delete_pdc] {e}')
        return False
