CHAT_PARTICIPANTS_TABLE = 'CHAT_PARTICIPANTS'
CHAT_MESSAGES_TABLE = 'CHAT_MESSAGES'
CHAT_REACTIONS_TABLE = 'CHAT_MESSAGE_REACTIONS'
CHAT_TYPING_TABLE = 'CHAT_TYPING_STATUS'

def _chat_next_id(cur, table: str, id_col: str) -> int:
    cur.execute(f'SELECT NVL(MAX({id_col}), 0) + 1 FROM {table}')
    row = cur.fetchone()
    return int((row or [1])[0] or 1)

def _chat_user_exists(username: str) -> bool:
    uname = (username or '').strip()
    if not uname:
        return False
    rows = _safe_rows_auth("\n        SELECT username\n        FROM login_users\n        WHERE UPPER(TRIM(username)) = UPPER(TRIM(:u))\n          AND UPPER(NVL(TRIM(active_flag), 'Y')) = 'Y'\n        ", {'u': uname})
    return bool(rows)

def _chat_user_tenant(username: str) -> Optional[str]:
    uname = (username or '').strip()
    if not uname:
        return None
    rows = _safe_rows_auth("\n        SELECT tenant_id\n        FROM login_users\n        WHERE UPPER(TRIM(username)) = UPPER(TRIM(:u))\n          AND UPPER(NVL(TRIM(active_flag), 'Y')) = 'Y'\n        ", {'u': uname})
    if not rows:
        return None
    tid = rows[0].get('tenant_id')
    if tid is None:
        return None
    if isinstance(tid, str):
        s = tid.strip()
        return s or None
    s = str(tid).strip()
    return s or None

def _chat_text_value(v: Any) -> str:
    if v is None:
        return ''
    if hasattr(v, 'read'):
        try:
            return v.read() or ''
        except Exception:
            return ''
    return str(v)

def _chat_encode_emoji_text(text: str) -> str:
    """Encode non-BMP chars (emoji) into ASCII-safe tokens for DB storage."""
    s = text or ''
    out = []
    for ch in s:
        cp = ord(ch)
        if cp > 65535:
            out.append(f'[[EMOJI:{cp:X}]]')
        else:
            out.append(ch)
    return ''.join(out)

def _chat_decode_emoji_text(text: str) -> str:
    s = text or ''
    try:
        return re.sub('\\[\\[EMOJI:([0-9A-Fa-f]+)\\]\\]', lambda m: chr(int(m.group(1), 16)), s)
    except Exception:
        return s

def ensure_chat_tables() -> None:
    global _CHAT_TABLES_ENSURED
    if _CHAT_TABLES_ENSURED:
        return
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': CHAT_CONVERSATIONS_TABLE})
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                cur.execute(f"\n                    CREATE TABLE {CHAT_CONVERSATIONS_TABLE} (\n                        CONVERSATION_ID NUMBER PRIMARY KEY,\n                        CONVERSATION_TYPE VARCHAR2(10) DEFAULT 'DIRECT' NOT NULL,\n                        TITLE VARCHAR2(200),\n                        CREATED_BY VARCHAR2(100) NOT NULL,\n                        CREATED_DATE DATE DEFAULT SYSDATE,\n                        UPDATED_DATE DATE\n                    )\n                    ")
            cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': CHAT_PARTICIPANTS_TABLE})
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                cur.execute(f"\n                    CREATE TABLE {CHAT_PARTICIPANTS_TABLE} (\n                        CONVERSATION_ID NUMBER NOT NULL,\n                        USERNAME VARCHAR2(100) NOT NULL,\n                        JOINED_DATE DATE DEFAULT SYSDATE,\n                        LAST_READ_MSG_ID NUMBER,\n                        LAST_SEEN_DATE DATE,\n                        ACTIVE_FLAG CHAR(1) DEFAULT 'Y',\n                        PRIMARY KEY (CONVERSATION_ID, USERNAME)\n                    )\n                    ")
            else:
                cur.execute(f"\n                    SELECT COUNT(*) FROM user_tab_columns\n                    WHERE table_name = '{CHAT_PARTICIPANTS_TABLE}'\n                      AND column_name = 'LAST_SEEN_DATE'\n                    ")
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute(f'ALTER TABLE {CHAT_PARTICIPANTS_TABLE} ADD LAST_SEEN_DATE DATE')
            cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': CHAT_MESSAGES_TABLE})
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                cur.execute(f"\n                    CREATE TABLE {CHAT_MESSAGES_TABLE} (\n                        MESSAGE_ID NUMBER PRIMARY KEY,\n                        CONVERSATION_ID NUMBER NOT NULL,\n                        SENDER_USERNAME VARCHAR2(100) NOT NULL,\n                        MESSAGE_TEXT CLOB,\n                        IMAGE_URL VARCHAR2(500),\n                        FILE_URL VARCHAR2(500),\n                        FILE_NAME VARCHAR2(255),\n                        FILE_MIME VARCHAR2(120),\n                        REPLIED_MESSAGE_ID NUMBER,\n                        EDITED_FLAG CHAR(1) DEFAULT 'N',\n                        EDITED_DATE DATE,\n                        CREATED_DATE DATE DEFAULT SYSDATE,\n                        ACTIVE_FLAG CHAR(1) DEFAULT 'Y'\n                    )\n                    ")
            else:
                cur.execute(f"\n                    SELECT COUNT(*) FROM user_tab_columns\n                    WHERE table_name = '{CHAT_MESSAGES_TABLE}'\n                      AND column_name = 'FILE_URL'\n                    ")
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute(f'ALTER TABLE {CHAT_MESSAGES_TABLE} ADD FILE_URL VARCHAR2(500)')
                cur.execute(f"\n                    SELECT COUNT(*) FROM user_tab_columns\n                    WHERE table_name = '{CHAT_MESSAGES_TABLE}'\n                      AND column_name = 'FILE_NAME'\n                    ")
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute(f'ALTER TABLE {CHAT_MESSAGES_TABLE} ADD FILE_NAME VARCHAR2(255)')
                cur.execute(f"\n                    SELECT COUNT(*) FROM user_tab_columns\n                    WHERE table_name = '{CHAT_MESSAGES_TABLE}'\n                      AND column_name = 'FILE_MIME'\n                    ")
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute(f'ALTER TABLE {CHAT_MESSAGES_TABLE} ADD FILE_MIME VARCHAR2(120)')
                cur.execute(f"\n                    SELECT COUNT(*) FROM user_tab_columns\n                    WHERE table_name = '{CHAT_MESSAGES_TABLE}'\n                      AND column_name = 'REPLIED_MESSAGE_ID'\n                    ")
                if int((cur.fetchone() or [0])[0] or 0) == 0:
                    cur.execute(f'ALTER TABLE {CHAT_MESSAGES_TABLE} ADD REPLIED_MESSAGE_ID NUMBER')
            cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': CHAT_REACTIONS_TABLE})
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                cur.execute(f'\n                    CREATE TABLE {CHAT_REACTIONS_TABLE} (\n                        MESSAGE_ID NUMBER NOT NULL,\n                        USERNAME VARCHAR2(100) NOT NULL,\n                        REACTION VARCHAR2(16) NOT NULL,\n                        REACTED_DATE DATE DEFAULT SYSDATE,\n                        PRIMARY KEY (MESSAGE_ID, USERNAME)\n                    )\n                    ')
            cur.execute('SELECT COUNT(*) FROM user_tables WHERE table_name = :t', {'t': CHAT_TYPING_TABLE})
            if int((cur.fetchone() or [0])[0] or 0) == 0:
                cur.execute(f"\n                    CREATE TABLE {CHAT_TYPING_TABLE} (\n                        CONVERSATION_ID NUMBER NOT NULL,\n                        USERNAME VARCHAR2(100) NOT NULL,\n                        IS_TYPING CHAR(1) DEFAULT 'N',\n                        UPDATED_DATE DATE DEFAULT SYSDATE,\n                        PRIMARY KEY (CONVERSATION_ID, USERNAME)\n                    )\n                    ")
        conn.commit()
    _CHAT_TABLES_ENSURED = True

def _env_truthy(name: str) -> bool:
    return (os.getenv(name) or '').strip().lower() in ('1', 'true', 'yes', 'on')
_FK_TBLSETTLEMEN_TBLORD_0 = 'FK_TBLSETTLEMEN_TBLORD_0'

def _try_drop_fk_tblsettlemen_tblord_0_for_current_schema(log: Any) -> None:
    """
    Drop FK ``FK_TBLSETTLEMEN_TBLORD_0`` from its child table when present. Resolves ``table_name``
    from ``user_constraints`` so the child can be ``TBLSETTLEMENT`` or a legacy misspelled name.

    Use when Oracle raises ORA-02291 (parent key not found) on settlement saves that do not align
    with the referenced order table. **Data integrity:** the DB will no longer enforce that link.
    """
    cname = _FK_TBLSETTLEMEN_TBLORD_0
    try:
        rows = _safe_rows("SELECT table_name FROM user_constraints WHERE constraint_type = 'R' AND constraint_name = :c", {'c': cname}) or []
    except Exception as e:
        log.warning('[drop_%s] query user_constraints: %s', cname, e)
        return
    if not rows:
        return
    r0 = rows[0]
    tbl = str(r0.get('TABLE_NAME') or r0.get('table_name') or '').strip().upper()
    if not tbl or not re.match('^[A-Z][A-Z0-9_$]*$', tbl):
        log.warning('[drop_%s] invalid table_name %r', cname, tbl)
        return
    try:
        with _get_connection() as conn:
            with conn.cursor() as cur:
                cur.execute(f'ALTER TABLE {tbl} DROP CONSTRAINT {cname}')
            conn.commit()
        log.info('[drop_%s] dropped from table %s', cname, tbl)
    except Exception as e:
        s = str(e)
        if '02443' in s or '2443' in s:
            return
        log.warning('[drop_%s] ALTER TABLE %s: %s', cname, tbl, e)

def _bootstrap_drop_fk_tblsettlemen_tblord_if_env(app: Any, log: Any) -> None:
    """When ``DROP_FK_TBLSETTLEMEN_TBLORD=1``, drop the FK on the active tenant schema(s)."""
    if not _env_truthy('DROP_FK_TBLSETTLEMEN_TBLORD'):
        return
    if not is_multi_db_mode():
        _try_drop_fk_tblsettlemen_tblord_0_for_current_schema(log)
        return
    rows: List[Dict[str, Any]]
    try:
        rows = list(_safe_rows_auth("SELECT tenant_id FROM tenant_databases WHERE NVL(active_flag, 'Y') = 'Y' ORDER BY tenant_id", {}) or [])
    except Exception as e:
        log.warning('[drop_%s] cannot list tenants: %s', _FK_TBLSETTLEMEN_TBLORD_0, e)
        return
    from nexa_http.context import app_context, g
    for row in rows:
        tid_raw = row.get('tenant_id')
        tid = (str(tid_raw).strip() if tid_raw is not None else '') or ''
        if not tid:
            continue
        with app_context():
            try:
                g.current_tenant_id = tid
                _try_drop_fk_tblsettlemen_tblord_0_for_current_schema(log)
            finally:
                try:
                    g.current_tenant_id = None
                except Exception:
                    pass

def get_app_owned_extended_bootstrap_steps() -> List[Tuple[str, Callable[[], None]]]:
    """
    Odoo-like **app-owned** DDL steps: (``step_id``, ``callable``). When ``AUTO_ENSURE_FULL_SCHEMA``
    is enabled, :func:`bootstrap_application_schema` runs these for the tenant connection.

    **Add a tuple here** when you introduce a new ``ensure_*`` for a business module (and implement
    ``ensure_*`` in ``db.py`` or delegate to an addon). Legacy RFIM wholesale tables are **not** listed
    here — use export/clone scripts instead (see ``database_setup`` help text).
    """
    from addons.warehouse.stock_count_db import ensure_stock_count_tables
    from addons.warehouse.stock_count_price_db import ensure_stock_count_price_tables
    from addons.transaction_recording_audit.transaction_recording_audit_db import ensure_transaction_recording_audit_tables
    from addons.fixed_assets.fixed_assets_db import ensure_fixed_assets_tables
    return [('company_profile_table', lambda: ensure_company_profile_table()), ('system_config_table', lambda: ensure_system_config_table('HO')), ('gl_tables', lambda: ensure_gl_tables()), ('gl_dimension_value_table', lambda: ensure_gl_dimension_value_table()), ('gl_account_dimension_rule_table', lambda: ensure_gl_account_dimension_rule_table()), ('ap_payment_tables', lambda: ensure_ap_payment_tables()), ('pdc_table', lambda: ensure_pdc_table()), ('pdc_audit_table', lambda: ensure_pdc_audit_table()), ('warehouse_storage_table', lambda: ensure_warehouse_storage_table()), ('bin_stock_tables', lambda: ensure_bin_stock_tables()), ('warehouse_stock_table', lambda: ensure_warehouse_stock_table()), ('stock_count_tables', lambda: ensure_stock_count_tables()), ('stock_count_price_tables', lambda: ensure_stock_count_price_tables()), ('location_master_batch_tracking', lambda: ensure_location_master_branch_tracking_columns()), ('item_lot_tables', lambda: ensure_item_lot_tables()), ('templpo_tables', lambda: ensure_templpo_tables()), ('tempreturn_tables', lambda: ensure_tempreturn_tables()), ('lpo_po_standard_columns', lambda: ensure_lpo_po_standard_columns()), ('smart_list_ai_history', lambda: ensure_smart_list_ai_history_table()), ('tblpaymentfollowup', lambda: ensure_tblpaymentfollowup_exists()), ('transaction_recording_audit', lambda: ensure_transaction_recording_audit_tables()), ('fixed_assets_tables', lambda: ensure_fixed_assets_tables()), ('sales_detail_amount_rate_columns', lambda: ensure_sales_detail_columns()), ('purchase_detail_rate_columns', lambda: ensure_purchase_detail_rate_columns()), ('returndtl_discount_amount_columns', lambda: ensure_returndtl_discount_amount_columns())]

def list_app_owned_bootstrap_step_names() -> List[str]:
    """Human-readable step ids for UI / logs (same order as :func:`get_app_owned_extended_bootstrap_steps`)."""
    return [name for name, _ in get_app_owned_extended_bootstrap_steps()]


def warm_sales_save_caches() -> None:
    """Pre-warm process caches used by sales/POS save (background at app startup)."""
    global _ITEMJOURNAL_SURROGATE_PK_ENSURED
    try:
        warm_core_schema_cache(force=True)
    except Exception as e:
        print(f'[WARN warm_sales_save_caches] schema: {e}')
    try:
        ensure_gl_tables()
    except Exception as e:
        print(f'[WARN warm_sales_save_caches] gl: {e}')
    try:
        ensure_billhdr_sales_schema_once()
    except Exception as e:
        print(f'[WARN warm_sales_save_caches] billhdr: {e}')
    try:
        ensure_billno_varchar_columns()
    except Exception as e:
        print(f'[WARN warm_sales_save_caches] billno_varchar: {e}')
    try:
        from addons.document_numbering.document_numbering_db import seed_default_document_series
        seed_default_document_series()
        peek_next_bill_no(0, None, doc_type='SALES_INVOICE')
    except Exception as e:
        print(f'[WARN warm_sales_save_caches] doc_series: {e}')
    try:
        with _get_connection() as conn:
            ensure_itemjournal_surrogate_pk(conn)
            tbl = _resolve_itemjournal_post_table()
            if tbl:
                with conn.cursor() as cur:
                    _ensure_itemjournal_trace_columns_for_table(cur, tbl)
                    _ = _journal_cols_upper(cur, tbl)
                _ = _itemjournal_needs_receiptno_namespace(conn, tbl)
            conn.commit()
        ensure_itemjournal_averagecost_column()
    except Exception as e:
        print(f'[WARN warm_sales_save_caches] itemjournal: {e}')
    try:
        ensure_warehouse_stock_table()
    except Exception as e:
        print(f'[WARN warm_sales_save_caches] warehouse_stock: {e}')
    print(
        '[warm_sales_save_caches] done '
        f'ij_pk={_ITEMJOURNAL_SURROGATE_PK_ENSURED} gl={_GL_TABLES_ENSURED}'
    )


def bootstrap_application_schema(app: Any=None, *, initial_login_username: Optional[str]=None, initial_login_password: Optional[str]=None) -> None:
    """
    One-shot DDL when the Flask app starts: login, supplier, party accounts, roles, admin,
    tenant registry (multi-DB), chat tables (auth DB).

    **Python vs Oracle**

    Generated ``*Cols`` / ``TABLE_BUNDLE`` modules describe RFIM-style column names for SQL in Python;
    **they do not CREATE Oracle tables.** Table creation uses explicit ``ensure_*`` DDL here.

    **Deployment strategies (Odoo analogy)**

    **(A) App-owned tables — “Odoo module install”**

    Core boot (always): ``ensure_login_table``, roles, chat, etc. **Extended** business tables are
    listed in :func:`get_app_owned_extended_bootstrap_steps` and run only when
    ``AUTO_ENSURE_FULL_SCHEMA=1`` (checkbox in ``/database-setup``). That is the closest analog to
    Odoo creating module tables at install: **Python registry → ensure_* → DDL**.

    **(B) Clone full RFIM metadata once (new tenant / empty schema)**

    Not done inside this function. Use offline scripts after creating the target Oracle user::

        python scripts/oracle_export_schema_ddl.py --profile rfim --out exports/rfim.sql
        # or remapped + optional apply:
        python scripts/oracle_apply_schema_ddl.py --profile rfim --out exports/preview.sql

    **(C) Long-term auto-DDL for hundreds of legacy RFIM tables**

    There is **no** ORM that invents all RFIM tables from Python fields. Options: keep **existing**
    RFIM DB; or **one-time** clone (B); or incremental ``ensure_*`` only for tables you truly own in
    code (A).

    * Single-DB: extended ``ensure_*`` run when ``AUTO_ENSURE_FULL_SCHEMA`` is set.
    * Multi-DB: same for each active tenant only if ``BOOTSTRAP_SCHEMA_ALL_ACTIVE_TENANTS=1`` and
      ``app`` is passed to this function.
    """
    import logging
    log = logging.getLogger(__name__)
    if _env_truthy('SKIP_STARTUP_SCHEMA_BOOTSTRAP'):
        log.info('[bootstrap] skipped (SKIP_STARTUP_SCHEMA_BOOTSTRAP=1)')
        return
    ensure_login_table()
    ensure_supplier_table()
    ensure_default_party_accounts()
    ensure_roles_tables()
    ensure_ho_roles()
    ensure_initial_app_admin(initial_login_username, initial_login_password)
    if is_multi_db_mode():
        ensure_tenant_databases_table()
    ensure_chat_tables()
    try:
        _bootstrap_drop_fk_tblsettlemen_tblord_if_env(app, log)
    except Exception as e:
        log.warning('[bootstrap] DROP_FK_TBLSETTLEMEN_TBLORD: %s', e)
    if not _env_truthy('AUTO_ENSURE_FULL_SCHEMA'):
        return
    extended = get_app_owned_extended_bootstrap_steps()

    def _run_extended(tag: str) -> None:
        for step_name, fn in extended:
            try:
                fn()
            except Exception as e:
                log.warning('[%s] optional %s: %s', tag, step_name, e)
    if not is_multi_db_mode():
        _run_extended('bootstrap')
        return
    log.info('[bootstrap] AUTO_ENSURE_FULL_SCHEMA: multi-DB — extended DDL per tenant only when BOOTSTRAP_SCHEMA_ALL_ACTIVE_TENANTS=1 and create_app passes app=. Otherwise skip extended DDL at startup.')
    if not _env_truthy('BOOTSTRAP_SCHEMA_ALL_ACTIVE_TENANTS'):
        return
    rows: List[Dict[str, Any]]
    try:
        rows = list(_safe_rows_auth("SELECT tenant_id FROM tenant_databases WHERE NVL(active_flag, 'Y') = 'Y' ORDER BY tenant_id", {}) or [])
    except Exception as e:
        log.warning('[bootstrap] cannot list tenants: %s', e)
        return
    from nexa_http.context import app_context, g
    for row in rows:
        tid_raw = row.get('tenant_id')
        tid = (str(tid_raw).strip() if tid_raw is not None else '') or ''
        if not tid:
            continue
        with app_context():
            try:
                g.current_tenant_id = tid
                _run_extended(f'bootstrap:{tid}')
            finally:
                try:
                    g.current_tenant_id = None
                except Exception:
                    pass

def _chat_normalize_tenant(v: Optional[str]) -> Optional[str]:
    if v is None:
        return None
    s = str(v).strip()
    if not s or s.lower() == 'none':
        return None
    return s

def _chat_is_ho_tenant_id(tenant: Optional[str]) -> bool:
    """Head-office users in login_users use tenant_id 'HO'."""
    t = _chat_normalize_tenant(tenant)
    return bool(t and t.upper() == 'HO')

def _chat_pair_may_direct_message(tenant_a: Optional[str], tenant_b: Optional[str]) -> bool:
    """Same tenant, or either login_users.tenant_id is HO (head office). Privileged / multilocation handled by caller."""
    if (tenant_a or '') == (tenant_b or ''):
        return True
    if _chat_is_ho_tenant_id(tenant_a) or _chat_is_ho_tenant_id(tenant_b):
        return True
    return False

def chat_user_can_message_all_tenants(username: str) -> bool:
    """
    True for admin/super and for users with multilocations (HO) — may list and direct/group chat
    with any active user across tenants.
    """
    u = (username or '').strip()
    if not u:
        return False
    if u.lower() in PRIVILEGED_USERS:
        return True
    try:
        return get_user_multilocations_view(u) == 'Y'
    except Exception:
        return False

def get_assignable_login_users(current_username: Optional[str], session_tenant_id: Optional[str]=None) -> List[Dict[str, Any]]:
    """
    Active login users that may receive assignments (auth DB).

    Scoped like branch chat listing: same ``tenant_id`` as session (or user's login tenant)
    plus HO users; users who may message all tenants (HO/multiloc) see every active user.
    """
    ensure_login_table()
    cu = (current_username or '').strip()
    params: Dict[str, Any] = {}
    where_tenant = ''
    try:
        do_all = chat_user_can_message_all_tenants(cu) if cu else False
    except Exception:
        do_all = False
    if not do_all:
        current_tenant = _chat_normalize_tenant(session_tenant_id) or (_chat_normalize_tenant(_chat_user_tenant(cu)) if cu else None)
        if current_tenant is None:
            where_tenant = " AND (TRIM(u.tenant_id) IS NULL OR UPPER(TRIM(NVL(u.tenant_id, ''))) = 'HO')"
        else:
            where_tenant = " AND (UPPER(TRIM(NVL(u.tenant_id, ''))) = UPPER(TRIM(:tid)) OR UPPER(TRIM(NVL(u.tenant_id, ''))) = 'HO')"
            params['tid'] = current_tenant
    rows = _safe_rows_auth(f"\n        SELECT u.username AS username,\n               u.employeecode AS employeecode,\n               u.tenant_id AS tenant_id\n        FROM login_users u\n        WHERE NVL(u.active_flag, 'Y') = 'Y'\n        {where_tenant}\n        ORDER BY u.username\n        ", params)
    out: List[Dict[str, Any]] = []
    for r in rows or []:
        un = str(r.get('username') or '').strip()
        if not un:
            continue
        out.append({'username': un, 'employeecode': r.get('employeecode'), 'tenant_id': str(r.get('tenant_id') or '').strip()})
    return out

def chat_list_users(current_user: str, search: str='', tenant_id: Optional[str]=None) -> List[Dict[str, Any]]:
    ensure_chat_tables()
    ensure_login_table()
    do_all = chat_user_can_message_all_tenants(current_user)
    if do_all:
        current_tenant = None
    else:
        current_tenant = _chat_normalize_tenant(tenant_id) or _chat_normalize_tenant(_chat_user_tenant(current_user))
    params: Dict[str, Any] = {'u': (current_user or '').strip()}
    where_search = ''
    where_tenant = ''
    if not do_all:
        if current_tenant is None:
            where_tenant = " AND (TRIM(u.tenant_id) IS NULL OR UPPER(TRIM(NVL(u.tenant_id, ''))) = 'HO')"
        else:
            where_tenant = " AND (UPPER(TRIM(NVL(u.tenant_id, ''))) = UPPER(TRIM(:tid)) OR UPPER(TRIM(NVL(u.tenant_id, ''))) = 'HO')"
            params['tid'] = current_tenant
    q = (search or '').strip()
    if q:
        params['q'] = f'%{q.upper()}%'
        where_search = " AND (UPPER(NVL(u.username,'')) LIKE :q OR UPPER(NVL(TO_CHAR(u.employeecode),'')) LIKE :q" + (" OR UPPER(NVL(TO_CHAR(u.tenant_id),'')) LIKE :q" if do_all else '') + ')'
    return _safe_rows_auth(f"\n        SELECT u.username, u.employeecode, u.tenant_id, ls.last_seen_date\n        FROM login_users u\n        LEFT JOIN (\n            SELECT UPPER(TRIM(USERNAME)) AS uname_n, MAX(LAST_SEEN_DATE) AS LAST_SEEN_DATE\n            FROM {CHAT_PARTICIPANTS_TABLE}\n            GROUP BY UPPER(TRIM(USERNAME))\n        ) ls ON ls.uname_n = UPPER(TRIM(u.username))\n        WHERE UPPER(NVL(TRIM(u.active_flag), 'Y')) = 'Y'\n          AND UPPER(TRIM(u.username)) <> UPPER(TRIM(:u))\n          {where_tenant}\n          {where_search}\n        ORDER BY u.username\n        ", params)

def chat_get_or_create_direct_conversation(user_a: str, user_b: str, tenant_id: Optional[str]=None) -> int:
    ensure_chat_tables()
    ua = (user_a or '').strip()
    ub = (user_b or '').strip()
    if not ua or not ub:
        raise ValueError('Both users are required.')
    if not _chat_user_exists(ua) or not _chat_user_exists(ub):
        raise ValueError('Invalid chat user.')
    ta = _chat_normalize_tenant(tenant_id) or _chat_normalize_tenant(_chat_user_tenant(ua))
    tb = _chat_normalize_tenant(_chat_user_tenant(ub))
    if not chat_user_can_message_all_tenants(ua) and (not _chat_pair_may_direct_message(ta, tb)):
        raise ValueError('You can only chat with users from your tenant or HO users.')
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute(f"\n                SELECT c.CONVERSATION_ID, p.USERNAME\n                FROM {CHAT_CONVERSATIONS_TABLE} c\n                JOIN {CHAT_PARTICIPANTS_TABLE} p ON p.CONVERSATION_ID = c.CONVERSATION_ID\n                WHERE UPPER(c.CONVERSATION_TYPE) = 'DIRECT'\n                  AND c.CONVERSATION_ID IN (\n                      SELECT CONVERSATION_ID FROM {CHAT_PARTICIPANTS_TABLE}\n                      WHERE UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u1))\n                  )\n                ", {'u1': ua})
            rows = cur.fetchall() or []
            participants_by_conv: Dict[int, set] = {}
            for conv_id, uname in rows:
                participants_by_conv.setdefault(int(conv_id), set()).add(str(uname or '').strip().upper())
            expected = {ua.upper(), ub.upper()}
            for conv_id, members in participants_by_conv.items():
                if members == expected:
                    return conv_id
            conv_id = _chat_next_id(cur, CHAT_CONVERSATIONS_TABLE, 'CONVERSATION_ID')
            cur.execute(f"\n                INSERT INTO {CHAT_CONVERSATIONS_TABLE}\n                    (CONVERSATION_ID, CONVERSATION_TYPE, TITLE, CREATED_BY, CREATED_DATE, UPDATED_DATE)\n                VALUES (:id, 'DIRECT', NULL, :u, SYSDATE, SYSDATE)\n                ", {'id': conv_id, 'u': ua})
            for uname in {ua, ub}:
                cur.execute(f"\n                    INSERT INTO {CHAT_PARTICIPANTS_TABLE}\n                        (CONVERSATION_ID, USERNAME, JOINED_DATE, ACTIVE_FLAG)\n                    VALUES (:id, :u, SYSDATE, 'Y')\n                    ", {'id': conv_id, 'u': uname})
        conn.commit()
    return conv_id

def chat_create_group_conversation(created_by: str, title: str, participants: List[str], tenant_id: Optional[str]=None) -> int:
    ensure_chat_tables()
    creator = (created_by or '').strip()
    ttl = (title or '').strip()[:200]
    if not creator:
        raise ValueError('Creator is required.')
    if not ttl:
        raise ValueError('Group title is required.')
    members = {creator}
    for p in participants or []:
        s = (p or '').strip()
        if s:
            members.add(s)
    if len(members) < 2:
        raise ValueError('Group must include at least 2 users.')
    creator_tenant = _chat_normalize_tenant(tenant_id) or _chat_normalize_tenant(_chat_user_tenant(creator))
    if chat_user_can_message_all_tenants(creator):
        valid_members = [m for m in members if _chat_user_exists(m)]
    else:
        valid_members = []
        for m in members:
            if not _chat_user_exists(m):
                continue
            mt = _chat_normalize_tenant(_chat_user_tenant(m)) or ''
            ct = creator_tenant or ''
            if mt == ct or _chat_is_ho_tenant_id(mt):
                valid_members.append(m)
    if len(valid_members) < 2:
        raise ValueError('No valid participants (same tenant or HO users only).')
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            conv_id = _chat_next_id(cur, CHAT_CONVERSATIONS_TABLE, 'CONVERSATION_ID')
            cur.execute(f"\n                INSERT INTO {CHAT_CONVERSATIONS_TABLE}\n                    (CONVERSATION_ID, CONVERSATION_TYPE, TITLE, CREATED_BY, CREATED_DATE, UPDATED_DATE)\n                VALUES (:id, 'GROUP', :t, :u, SYSDATE, SYSDATE)\n                ", {'id': conv_id, 't': ttl, 'u': creator})
            for uname in valid_members:
                cur.execute(f"\n                    INSERT INTO {CHAT_PARTICIPANTS_TABLE}\n                        (CONVERSATION_ID, USERNAME, JOINED_DATE, ACTIVE_FLAG)\n                    VALUES (:id, :u, SYSDATE, 'Y')\n                    ", {'id': conv_id, 'u': uname})
        conn.commit()
    return conv_id

def chat_get_conversations(username: str) -> List[Dict[str, Any]]:
    ensure_chat_tables()
    uname = (username or '').strip()
    if not uname:
        return []
    _chat_touch_presence(uname)
    rows = _safe_rows_auth(f"\n        SELECT\n            c.CONVERSATION_ID,\n            c.CONVERSATION_TYPE,\n            c.TITLE,\n            c.UPDATED_DATE,\n            NVL(cp.LAST_READ_MSG_ID, 0) AS LAST_READ_MSG_ID,\n            (\n                SELECT p2.USERNAME\n                FROM {CHAT_PARTICIPANTS_TABLE} p2\n                WHERE p2.CONVERSATION_ID = c.CONVERSATION_ID\n                  AND UPPER(TRIM(p2.USERNAME)) <> UPPER(TRIM(:u))\n                  AND ROWNUM = 1\n            ) AS DIRECT_OTHER_USER,\n            (\n                SELECT p2.LAST_SEEN_DATE\n                FROM {CHAT_PARTICIPANTS_TABLE} p2\n                WHERE p2.CONVERSATION_ID = c.CONVERSATION_ID\n                  AND UPPER(TRIM(p2.USERNAME)) <> UPPER(TRIM(:u))\n                  AND ROWNUM = 1\n            ) AS DIRECT_OTHER_LAST_SEEN,\n            (\n                SELECT m.SENDER_USERNAME\n                FROM {CHAT_MESSAGES_TABLE} m\n                WHERE m.MESSAGE_ID = (\n                    SELECT MAX(m2.MESSAGE_ID)\n                    FROM {CHAT_MESSAGES_TABLE} m2\n                    WHERE m2.CONVERSATION_ID = c.CONVERSATION_ID\n                      AND NVL(m2.ACTIVE_FLAG, 'Y') = 'Y'\n                )\n            ) AS LAST_SENDER,\n            (\n                SELECT m.MESSAGE_TEXT\n                FROM {CHAT_MESSAGES_TABLE} m\n                WHERE m.MESSAGE_ID = (\n                    SELECT MAX(m2.MESSAGE_ID)\n                    FROM {CHAT_MESSAGES_TABLE} m2\n                    WHERE m2.CONVERSATION_ID = c.CONVERSATION_ID\n                      AND NVL(m2.ACTIVE_FLAG, 'Y') = 'Y'\n                )\n            ) AS LAST_TEXT,\n            (\n                SELECT m.IMAGE_URL\n                FROM {CHAT_MESSAGES_TABLE} m\n                WHERE m.MESSAGE_ID = (\n                    SELECT MAX(m2.MESSAGE_ID)\n                    FROM {CHAT_MESSAGES_TABLE} m2\n                    WHERE m2.CONVERSATION_ID = c.CONVERSATION_ID\n                      AND NVL(m2.ACTIVE_FLAG, 'Y') = 'Y'\n                )\n            ) AS LAST_IMAGE_URL,\n            (\n                SELECT m.FILE_NAME\n                FROM {CHAT_MESSAGES_TABLE} m\n                WHERE m.MESSAGE_ID = (\n                    SELECT MAX(m2.MESSAGE_ID)\n                    FROM {CHAT_MESSAGES_TABLE} m2\n                    WHERE m2.CONVERSATION_ID = c.CONVERSATION_ID\n                      AND NVL(m2.ACTIVE_FLAG, 'Y') = 'Y'\n                )\n            ) AS LAST_FILE_NAME,\n            (\n                SELECT m.CREATED_DATE\n                FROM {CHAT_MESSAGES_TABLE} m\n                WHERE m.MESSAGE_ID = (\n                    SELECT MAX(m2.MESSAGE_ID)\n                    FROM {CHAT_MESSAGES_TABLE} m2\n                    WHERE m2.CONVERSATION_ID = c.CONVERSATION_ID\n                      AND NVL(m2.ACTIVE_FLAG, 'Y') = 'Y'\n                )\n            ) AS LAST_CREATED_DATE,\n            (\n                SELECT COUNT(*)\n                FROM {CHAT_MESSAGES_TABLE} um\n                WHERE um.CONVERSATION_ID = c.CONVERSATION_ID\n                  AND NVL(um.ACTIVE_FLAG, 'Y') = 'Y'\n                  AND UPPER(TRIM(um.SENDER_USERNAME)) <> UPPER(TRIM(:u))\n                  AND um.MESSAGE_ID > NVL(cp.LAST_READ_MSG_ID, 0)\n            ) AS UNREAD_COUNT\n        FROM {CHAT_CONVERSATIONS_TABLE} c\n        JOIN {CHAT_PARTICIPANTS_TABLE} cp ON cp.CONVERSATION_ID = c.CONVERSATION_ID\n        WHERE UPPER(TRIM(cp.USERNAME)) = UPPER(TRIM(:u))\n          AND NVL(cp.ACTIVE_FLAG, 'Y') = 'Y'\n        ORDER BY NVL(c.UPDATED_DATE, c.CREATED_DATE) DESC, c.CONVERSATION_ID DESC\n        ", {'u': uname})
    for r in rows:
        ctype = (r.get('conversation_type') or '').upper()
        r['last_text'] = _chat_decode_emoji_text(_chat_text_value(r.get('last_text')))
        r['display_name'] = (r.get('title') or '').strip() if ctype == 'GROUP' else r.get('direct_other_user') or 'Direct Chat'
        r['unread_count'] = int(r.get('unread_count') or 0)
    return rows

def _chat_is_participant(conversation_id: int, username: str) -> bool:
    rows = _safe_rows_auth(f"\n        SELECT 1\n        FROM {CHAT_PARTICIPANTS_TABLE}\n        WHERE CONVERSATION_ID = :id\n          AND UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n          AND NVL(ACTIVE_FLAG, 'Y') = 'Y'\n        ", {'id': conversation_id, 'u': (username or '').strip()})
    return bool(rows)

def _chat_touch_presence(username: str, conversation_id: Optional[int]=None) -> None:
    uname = (username or '').strip()
    if not uname:
        return
    try:
        with _get_connection_auth() as conn:
            with conn.cursor() as cur:
                if conversation_id:
                    cur.execute(f'\n                        UPDATE {CHAT_PARTICIPANTS_TABLE}\n                        SET LAST_SEEN_DATE = SYSDATE\n                        WHERE CONVERSATION_ID = :id\n                          AND UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n                        ', {'id': int(conversation_id), 'u': uname})
                else:
                    cur.execute(f'\n                        UPDATE {CHAT_PARTICIPANTS_TABLE}\n                        SET LAST_SEEN_DATE = SYSDATE\n                        WHERE UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n                        ', {'u': uname})
            conn.commit()
    except Exception:
        pass

def chat_get_messages(conversation_id: int, username: str, limit: int=150) -> List[Dict[str, Any]]:
    ensure_chat_tables()
    if not _chat_is_participant(conversation_id, username):
        raise ValueError('You are not a participant in this conversation.')
    rows = _safe_rows_auth(f"\n        SELECT *\n        FROM (\n            SELECT\n                m.MESSAGE_ID,\n                m.CONVERSATION_ID,\n                m.SENDER_USERNAME,\n                m.MESSAGE_TEXT,\n                m.IMAGE_URL,\n                m.FILE_URL,\n                m.FILE_NAME,\n                m.FILE_MIME,\n                m.REPLIED_MESSAGE_ID,\n                (\n                    SELECT rm.SENDER_USERNAME\n                    FROM {CHAT_MESSAGES_TABLE} rm\n                    WHERE rm.MESSAGE_ID = m.REPLIED_MESSAGE_ID\n                ) AS REPLY_TO_SENDER,\n                (\n                    SELECT rm.MESSAGE_TEXT\n                    FROM {CHAT_MESSAGES_TABLE} rm\n                    WHERE rm.MESSAGE_ID = m.REPLIED_MESSAGE_ID\n                ) AS REPLY_TO_TEXT,\n                m.EDITED_FLAG,\n                m.EDITED_DATE,\n                m.CREATED_DATE\n            FROM {CHAT_MESSAGES_TABLE} m\n            WHERE m.CONVERSATION_ID = :id\n              AND NVL(m.ACTIVE_FLAG, 'Y') = 'Y'\n            ORDER BY m.MESSAGE_ID DESC\n        )\n        WHERE ROWNUM <= :lim\n        ", {'id': conversation_id, 'lim': max(1, min(int(limit or 150), 300))})
    rows = list(reversed(rows))
    participant_rows = _safe_rows_auth(f"\n        SELECT USERNAME, NVL(LAST_READ_MSG_ID, 0) AS LAST_READ_MSG_ID\n        FROM {CHAT_PARTICIPANTS_TABLE}\n        WHERE CONVERSATION_ID = :id\n          AND NVL(ACTIVE_FLAG, 'Y') = 'Y'\n        ", {'id': conversation_id})
    readers = {str(p.get('username') or '').strip().upper(): int(p.get('last_read_msg_id') or 0) for p in participant_rows}
    for r in rows:
        r['message_text'] = _chat_decode_emoji_text(_chat_text_value(r.get('message_text')))
        r['reply_to_text'] = _chat_decode_emoji_text(_chat_text_value(r.get('reply_to_text')))
        msg_id = int(r.get('message_id') or 0)
        sender = str(r.get('sender_username') or '').strip().upper()
        other_reads = [v for u, v in readers.items() if u != sender]
        read_count = sum((1 for v in other_reads if v >= msg_id))
        r['read_count'] = read_count
        r['read_by_all'] = 'Y' if other_reads and read_count == len(other_reads) else 'N'
    reaction_rows = _safe_rows_auth(f"\n        SELECT MESSAGE_ID, REACTION, COUNT(*) AS CNT\n        FROM {CHAT_REACTIONS_TABLE}\n        WHERE MESSAGE_ID IN (\n            SELECT MESSAGE_ID\n            FROM {CHAT_MESSAGES_TABLE}\n            WHERE CONVERSATION_ID = :id\n              AND NVL(ACTIVE_FLAG, 'Y') = 'Y'\n        )\n        GROUP BY MESSAGE_ID, REACTION\n        ", {'id': conversation_id})
    my_reaction_rows = _safe_rows_auth(f"\n        SELECT MESSAGE_ID, REACTION\n        FROM {CHAT_REACTIONS_TABLE}\n        WHERE UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n          AND MESSAGE_ID IN (\n              SELECT MESSAGE_ID\n              FROM {CHAT_MESSAGES_TABLE}\n              WHERE CONVERSATION_ID = :id\n                AND NVL(ACTIVE_FLAG, 'Y') = 'Y'\n          )\n        ", {'id': conversation_id, 'u': username})
    reactions_by_msg: Dict[int, Dict[str, int]] = {}
    for rr in reaction_rows:
        mid = int(rr.get('message_id') or 0)
        rx = str(rr.get('reaction') or '').strip()
        if not rx:
            continue
        reactions_by_msg.setdefault(mid, {})[rx] = int(rr.get('cnt') or 0)
    my_reaction_map = {int(rm.get('message_id') or 0): str(rm.get('reaction') or '') for rm in my_reaction_rows}
    for r in rows:
        mid = int(r.get('message_id') or 0)
        r['reaction_summary'] = reactions_by_msg.get(mid, {})
        r['my_reaction'] = my_reaction_map.get(mid, '')
    if rows:
        max_msg_id = int(max((r.get('message_id') or 0 for r in rows)))
        with _get_connection_auth() as conn:
            with conn.cursor() as cur:
                cur.execute(f'\n                    UPDATE {CHAT_PARTICIPANTS_TABLE}\n                    SET LAST_READ_MSG_ID = :m\n                    WHERE CONVERSATION_ID = :id\n                      AND UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n                    ', {'m': max_msg_id, 'id': conversation_id, 'u': username})
            conn.commit()
        _chat_touch_presence(username, conversation_id=conversation_id)
    return rows

def chat_send_message(conversation_id: int, sender_username: str, message_text: str='', image_url: str='', file_url: str='', file_name: str='', file_mime: str='', replied_message_id: Optional[int]=None) -> Dict[str, Any]:
    ensure_chat_tables()
    if not _chat_is_participant(conversation_id, sender_username):
        raise ValueError('You are not a participant in this conversation.')
    msg = (message_text or '').strip()
    msg = _chat_encode_emoji_text(msg)
    img = (image_url or '').strip()
    furl = (file_url or '').strip()
    fname = (file_name or '').strip()[:255]
    fmime = (file_mime or '').strip()[:120]
    if not msg and (not img) and (not furl):
        raise ValueError('Message text or attachment is required.')
    reply_id: Optional[int] = None
    if replied_message_id:
        try:
            rid = int(replied_message_id)
        except Exception:
            rid = 0
        if rid > 0:
            check = _safe_rows_auth(f"\n                SELECT MESSAGE_ID\n                FROM {CHAT_MESSAGES_TABLE}\n                WHERE MESSAGE_ID = :mid\n                  AND CONVERSATION_ID = :cid\n                  AND NVL(ACTIVE_FLAG, 'Y') = 'Y'\n                ", {'mid': rid, 'cid': conversation_id})
            if check:
                reply_id = rid
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            message_id = _chat_next_id(cur, CHAT_MESSAGES_TABLE, 'MESSAGE_ID')
            cur.execute(f"\n                INSERT INTO {CHAT_MESSAGES_TABLE}\n                    (MESSAGE_ID, CONVERSATION_ID, SENDER_USERNAME, IMAGE_URL, FILE_URL, FILE_NAME, FILE_MIME, REPLIED_MESSAGE_ID, MESSAGE_TEXT, EDITED_FLAG, CREATED_DATE, ACTIVE_FLAG)\n                VALUES (:id, :cid, :u, :img, :furl, :fname, :fmime, :rid, :txt, 'N', SYSDATE, 'Y')\n                ", {'id': message_id, 'cid': conversation_id, 'u': sender_username, 'img': img, 'furl': furl, 'fname': fname, 'fmime': fmime, 'rid': reply_id, 'txt': msg})
            cur.execute(f'\n                UPDATE {CHAT_CONVERSATIONS_TABLE}\n                SET UPDATED_DATE = SYSDATE\n                WHERE CONVERSATION_ID = :id\n                ', {'id': conversation_id})
        conn.commit()
    rows = _safe_rows_auth(f'\n        SELECT MESSAGE_ID, CONVERSATION_ID, SENDER_USERNAME, MESSAGE_TEXT, IMAGE_URL, FILE_URL, FILE_NAME, FILE_MIME, REPLIED_MESSAGE_ID, EDITED_FLAG, EDITED_DATE, CREATED_DATE\n        FROM {CHAT_MESSAGES_TABLE}\n        WHERE MESSAGE_ID = :id\n        ', {'id': message_id})
    if rows:
        rows[0]['message_text'] = _chat_decode_emoji_text(_chat_text_value(rows[0].get('message_text')))
    _chat_touch_presence(sender_username, conversation_id=conversation_id)
    return rows[0] if rows else {}

def chat_share_message_to_user(message_id: int, from_username: str, to_username: str, note: str='') -> Dict[str, Any]:
    """Share/forward an existing message to another user (same tenant rules apply)."""
    ensure_chat_tables()
    mid = int(message_id or 0)
    sender = (from_username or '').strip()
    target = (to_username or '').strip()
    if mid <= 0 or not sender or (not target):
        raise ValueError('Invalid share request.')
    src_rows = _safe_rows_auth(f"\n        SELECT MESSAGE_ID, CONVERSATION_ID, MESSAGE_TEXT, IMAGE_URL, FILE_URL, FILE_NAME, FILE_MIME\n        FROM {CHAT_MESSAGES_TABLE}\n        WHERE MESSAGE_ID = :id\n          AND NVL(ACTIVE_FLAG, 'Y') = 'Y'\n        ", {'id': mid})
    if not src_rows:
        raise ValueError('Message not found.')
    src = src_rows[0]
    src_conv_id = int(src.get('conversation_id') or 0)
    if not _chat_is_participant(src_conv_id, sender):
        raise ValueError('Not allowed to share this message.')
    dst_conv_id = chat_get_or_create_direct_conversation(sender, target, tenant_id=_chat_user_tenant(sender))
    src_text = _chat_decode_emoji_text(_chat_text_value(src.get('message_text'))).strip()
    note_text = (note or '').strip()
    merged_text = ''
    if note_text and src_text:
        merged_text = f'{note_text}\n{src_text}'
    elif note_text:
        merged_text = note_text
    else:
        merged_text = src_text
    shared = chat_send_message(dst_conv_id, sender, merged_text, image_url=src.get('image_url') or '', file_url=src.get('file_url') or '', file_name=src.get('file_name') or '', file_mime=src.get('file_mime') or '')
    return shared

def chat_edit_message(message_id: int, editor_username: str, new_text: str) -> bool:
    ensure_chat_tables()
    txt = (new_text or '').strip()
    if not txt:
        raise ValueError('Edited message text cannot be empty.')
    txt = _chat_encode_emoji_text(txt)
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute(f"\n                UPDATE {CHAT_MESSAGES_TABLE}\n                SET MESSAGE_TEXT = :txt,\n                    EDITED_FLAG = 'Y',\n                    EDITED_DATE = SYSDATE\n                WHERE MESSAGE_ID = :id\n                  AND UPPER(TRIM(SENDER_USERNAME)) = UPPER(TRIM(:u))\n                  AND NVL(ACTIVE_FLAG, 'Y') = 'Y'\n                ", {'txt': txt, 'id': message_id, 'u': (editor_username or '').strip()})
            updated = cur.rowcount or 0
            if updated:
                cur.execute(f'\n                    UPDATE {CHAT_CONVERSATIONS_TABLE}\n                    SET UPDATED_DATE = SYSDATE\n                    WHERE CONVERSATION_ID = (\n                        SELECT CONVERSATION_ID FROM {CHAT_MESSAGES_TABLE} WHERE MESSAGE_ID = :id\n                    )\n                    ', {'id': message_id})
        conn.commit()
    return bool(updated)

def chat_delete_message(message_id: int, editor_username: str) -> bool:
    ensure_chat_tables()
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute(f"\n                UPDATE {CHAT_MESSAGES_TABLE}\n                SET ACTIVE_FLAG = 'N',\n                    EDITED_FLAG = 'Y',\n                    EDITED_DATE = SYSDATE\n                WHERE MESSAGE_ID = :id\n                  AND UPPER(TRIM(SENDER_USERNAME)) = UPPER(TRIM(:u))\n                  AND NVL(ACTIVE_FLAG, 'Y') = 'Y'\n                ", {'id': int(message_id), 'u': (editor_username or '').strip()})
            updated = cur.rowcount or 0
            if updated:
                cur.execute(f'\n                    UPDATE {CHAT_CONVERSATIONS_TABLE}\n                    SET UPDATED_DATE = SYSDATE\n                    WHERE CONVERSATION_ID = (\n                        SELECT CONVERSATION_ID FROM {CHAT_MESSAGES_TABLE} WHERE MESSAGE_ID = :id\n                    )\n                    ', {'id': int(message_id)})
        conn.commit()
    return bool(updated)

def chat_get_user_sync_token(username: str) -> str:
    """Small signature to detect chat changes for the current user."""
    ensure_chat_tables()
    uname = (username or '').strip()
    if not uname:
        return '0:0'
    rows = _safe_rows_auth(f"\n        SELECT\n            NVL(MAX(m.MESSAGE_ID), 0) AS MAX_MSG_ID,\n            NVL(MAX(c.CONVERSATION_ID), 0) AS MAX_CONV_ID,\n            NVL(MAX(r.MESSAGE_ID), 0) AS MAX_REACTION_MSG_ID,\n            MAX(t.UPDATED_DATE) AS MAX_TYPING_DATE\n        FROM {CHAT_PARTICIPANTS_TABLE} cp\n        JOIN {CHAT_CONVERSATIONS_TABLE} c ON c.CONVERSATION_ID = cp.CONVERSATION_ID\n        LEFT JOIN {CHAT_MESSAGES_TABLE} m\n               ON m.CONVERSATION_ID = c.CONVERSATION_ID\n              AND NVL(m.ACTIVE_FLAG, 'Y') = 'Y'\n        LEFT JOIN {CHAT_REACTIONS_TABLE} r\n               ON r.MESSAGE_ID = m.MESSAGE_ID\n        LEFT JOIN {CHAT_TYPING_TABLE} t\n               ON t.CONVERSATION_ID = c.CONVERSATION_ID\n              AND t.IS_TYPING = 'Y'\n        WHERE UPPER(TRIM(cp.USERNAME)) = UPPER(TRIM(:u))\n          AND NVL(cp.ACTIVE_FLAG, 'Y') = 'Y'\n        ", {'u': uname})
    if not rows:
        return '0:0'
    typing_token = str(rows[0].get('max_typing_date') or '')
    return f"{int(rows[0].get('max_msg_id') or 0)}:{int(rows[0].get('max_conv_id') or 0)}:{int(rows[0].get('max_reaction_msg_id') or 0)}:{typing_token}"

def chat_toggle_reaction(message_id: int, username: str, reaction: str='LIKE') -> Dict[str, Any]:
    ensure_chat_tables()
    rid = int(message_id or 0)
    uname = (username or '').strip()
    react = (reaction or 'LIKE').strip().upper()[:16]
    if rid <= 0 or not uname:
        raise ValueError('Invalid reaction request.')
    if react not in {'LIKE'}:
        react = 'LIKE'
    msg_rows = _safe_rows_auth(f"SELECT CONVERSATION_ID FROM {CHAT_MESSAGES_TABLE} WHERE MESSAGE_ID = :id AND NVL(ACTIVE_FLAG, 'Y') = 'Y'", {'id': rid})
    if not msg_rows:
        raise ValueError('Message not found.')
    conv_id = int(msg_rows[0].get('conversation_id') or 0)
    if not _chat_is_participant(conv_id, uname):
        raise ValueError('Not allowed.')
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute(f'\n                SELECT REACTION\n                FROM {CHAT_REACTIONS_TABLE}\n                WHERE MESSAGE_ID = :id\n                  AND UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n                ', {'id': rid, 'u': uname})
            ex = cur.fetchone()
            if ex and str(ex[0] or '').upper() == react:
                cur.execute(f'\n                    DELETE FROM {CHAT_REACTIONS_TABLE}\n                    WHERE MESSAGE_ID = :id\n                      AND UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n                    ', {'id': rid, 'u': uname})
            elif ex:
                cur.execute(f'\n                        UPDATE {CHAT_REACTIONS_TABLE}\n                        SET REACTION = :r, REACTED_DATE = SYSDATE\n                        WHERE MESSAGE_ID = :id\n                          AND UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n                        ', {'r': react, 'id': rid, 'u': uname})
            else:
                cur.execute(f'\n                        INSERT INTO {CHAT_REACTIONS_TABLE} (MESSAGE_ID, USERNAME, REACTION, REACTED_DATE)\n                        VALUES (:id, :u, :r, SYSDATE)\n                        ', {'id': rid, 'u': uname, 'r': react})
        conn.commit()
    count_rows = _safe_rows_auth(f"SELECT COUNT(*) AS CNT FROM {CHAT_REACTIONS_TABLE} WHERE MESSAGE_ID = :id AND REACTION = 'LIKE'", {'id': rid})
    my_rows = _safe_rows_auth(f'SELECT REACTION FROM {CHAT_REACTIONS_TABLE} WHERE MESSAGE_ID = :id AND UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))', {'id': rid, 'u': uname})
    return {'like_count': int((count_rows[0].get('cnt') if count_rows else 0) or 0), 'my_reaction': (my_rows[0].get('reaction') if my_rows else '') or ''}

def chat_set_typing(conversation_id: int, username: str, is_typing: bool) -> None:
    ensure_chat_tables()
    cid = int(conversation_id or 0)
    uname = (username or '').strip()
    if cid <= 0 or not uname:
        return
    if not _chat_is_participant(cid, uname):
        return
    flag = 'Y' if is_typing else 'N'
    with _get_connection_auth() as conn:
        with conn.cursor() as cur:
            cur.execute(f'\n                UPDATE {CHAT_TYPING_TABLE}\n                SET IS_TYPING = :f, UPDATED_DATE = SYSDATE\n                WHERE CONVERSATION_ID = :cid\n                  AND UPPER(TRIM(USERNAME)) = UPPER(TRIM(:u))\n                ', {'f': flag, 'cid': cid, 'u': uname})
            if not (cur.rowcount or 0):
                cur.execute(f'\n                    INSERT INTO {CHAT_TYPING_TABLE} (CONVERSATION_ID, USERNAME, IS_TYPING, UPDATED_DATE)\n                    VALUES (:cid, :u, :f, SYSDATE)\n                    ', {'cid': cid, 'u': uname, 'f': flag})
        conn.commit()

def chat_get_typing_users(conversation_id: int, username: str) -> List[Dict[str, Any]]:
    ensure_chat_tables()
    cid = int(conversation_id or 0)
    uname = (username or '').strip()
    if cid <= 0 or not uname:
        return []
    if not _chat_is_participant(cid, uname):
        return []
    return _safe_rows_auth(f"\n        SELECT USERNAME, UPDATED_DATE\n        FROM {CHAT_TYPING_TABLE}\n        WHERE CONVERSATION_ID = :cid\n          AND UPPER(TRIM(USERNAME)) <> UPPER(TRIM(:u))\n          AND IS_TYPING = 'Y'\n          AND UPDATED_DATE >= (SYSDATE - (10/86400))\n        ORDER BY UPDATED_DATE DESC\n        ", {'cid': cid, 'u': uname})
